-- =============================================================================
-- 413 — LE CATALOGUE DES CONTRÔLES BLANCS : Tle (allemand, anglais, arts-plastiques, biochimie-biologie-biotechnologie, chimie-biologie-physiopathologie)
--
-- 360 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 413 --niveau Tle --matieres allemand,anglais,arts-plastiques,biochimie-biologie-biotechnologie,chimie-biologie-physiopathologie
--
--   allemand.jumelles           108 sujets · 36 fiches
--   allemand.m1                  36 sujets · 12 fiches
--   anglais.jumelles             72 sujets · 24 fiches
--   anglais.m1                   39 sujets · 13 fiches
--   arts-plastiques.jumelles      9 sujets · 3 fiches
--   biochimie-biologie-biotechnologie.m1a   24 sujets · 8 fiches
--   biochimie-biologie-biotechnologie.m1b   24 sujets · 8 fiches
--   chimie-biologie-physiopathologie.m1a   24 sujets · 8 fiches
--   chimie-biologie-physiopathologie.m1b   24 sujets · 8 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('dd55d3fe-7b26-56bb-a7fa-b9c1ec6e8238'::uuid, 1, 'traduction', $exo${"titre":"Conjuguer au présent","consigne":"Conjugue chaque verbe au présent, à la personne demandée, puis réponds à la question.","enonce":"**1. Conjugue** au présent :\n\na) *spielen* (du)\nb) *arbeiten* (er)\nc) *heißen* (du)\nd) *fahren* (er)\ne) *lesen* (du)\nf) *geben* (sie, elle)\ng) *sammeln* (ich)\nh) *finden* (ihr)\n\n**2.** Le changement de voyelle d’un verbe fort (*fahren → fährt*) touche-t-il aussi *wir* et *sie* (ils) ? Donne un exemple.","bareme":[{"critere":"Terminaisons régulières justes : spielst","points":2},{"critere":"Aménagements justes : arbeitet, heißt, sammle, findet","points":8},{"critere":"Verbes forts justes : fährt, liest, gibt","points":6},{"critere":"Réponse : changement aux 2e et 3e personnes du singulier seulement, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *du spielst*\nb) *er arbeitet* (radical en -t : on intercale un e)\nc) *du heißt* (radical en -ß : le -st perd son s)\nd) *er fährt* (verbe fort a → ä)\ne) *du liest* (e → ie ; radical en -s : -st perd son s)\nf) *sie gibt* (e → i)\ng) *ich sammle* (radical en -el : le e tombe à la 1re personne)\nh) *ihr findet* (radical en -d : on intercale un e)\n\n**2.** Non : le changement de voyelle ne touche que les **2e et 3e personnes du singulier**. Exemple : *du fährst, er fährt*, mais *wir fahren, sie fahren*."}$exo$::jsonb),
  ('dd55d3fe-7b26-56bb-a7fa-b9c1ec6e8238'::uuid, 2, 'traduction', $exo${"titre":"Lena se présente","consigne":"Complète la présentation de Lena au présent, puis traduis les deux phrases.","enonce":"**Situation.** Lena écrit à sa correspondante française.\n\n> Ich (1. heißen) Lena. Ich (2. lernen) seit drei Jahren Französisch. Mein Bruder Paul (3. lesen) jeden Abend und er (4. sprechen) gut Englisch. Meine Schwester (5. arbeiten) in Köln. Morgen (6. fahren) wir nach Berlin. Und du? (7. Schlafen) du am Wochenende lange?\n\n1. Écris les **sept verbes** conjugués.\n2. **Traduis** en allemand :\na) J’apprends l’allemand depuis deux ans.\nb) Demain, je vais à Munich (en train).\n3. Pourquoi n’utilise-t-on pas le futur dans la phrase b) ?","bareme":[{"critere":"Les sept formes justes : heiße, lerne, liest, spricht, arbeitet, fahren, Schläfst","points":10},{"critere":"Traduction a) au présent avec seit : Ich lerne seit zwei Jahren Deutsch","points":4},{"critere":"Traduction b) au présent, verbe en 2e position : Morgen fahre ich nach München","points":3},{"critere":"Explication : l’adverbe de temps suffit à dire l’avenir","points":3}],"dureeMin":10,"corrige":"**1.**\n1) *heiße*\n2) *lerne* (présent avec *seit*)\n3) *liest* (e → ie)\n4) *spricht* (e → i)\n5) *arbeitet* (e intercalé)\n6) *fahren* (pluriel : pas de changement de voyelle)\n7) *Schläfst* (a → ä)\n\n**2.**\na) *Ich lerne seit zwei Jahren Deutsch.* — avec *seit*, l’allemand emploie le **présent**, comme le français ; le parfait serait une faute.\nb) *Morgen fahre ich nach München.* — le verbe reste en **2e position**, le sujet passe derrière.\n\n**3.** Avec un adverbe de temps (*morgen*), le **présent suffit** à exprimer l’avenir et c’est la tournure la plus naturelle ; le futur en *werden* ne sert que sans repère temporel ou pour insister."}$exo$::jsonb),
  ('dd55d3fe-7b26-56bb-a7fa-b9c1ec6e8238'::uuid, 3, 'traduction', $exo${"titre":"Le courriel plein de fautes","consigne":"Corrige chaque faute en expliquant la règle, puis rédige un court message en allemand.","enonce":"**Document.** Courriel de Hugo, élève de 3e, à son correspondant.\n\n> Hallo Jonas! Ich habe seit zwei Jahren Deutsch gelernt. Mein Vater fahrt jeden Tag nach Paris. Du arbeitst viel, oder? Du heißst Jonas Müller, richtig? Meine Freunde und ich fähren oft ans Meer. Morgen ich spiele Fußball.\n\n1. Hugo a fait **six fautes**, une par phrase après *Hallo Jonas!*. Recopie chaque phrase **corrigée**.\n2. Pour chaque faute, **nomme la règle** en quelques mots.\n3. **Production** (5 lignes environ) : présente-toi à Jonas. Utilise au moins un verbe fort à la 2e ou 3e personne, une phrase avec *seit* et une phrase qui parle de demain au présent.","bareme":[{"critere":"Les six phrases corrigées : lerne seit, fährt, arbeitest, heißt, fahren, Morgen spiele ich","points":6},{"critere":"Règles nommées : seit + présent, verbe fort, e intercalé, s supprimé, pluriel sans inflexion, verbe en 2e position","points":6},{"critere":"Production : terminaisons et verbes forts justes","points":4},{"critere":"Production : seit + présent et avenir au présent avec adverbe, verbe en 2e position","points":4}],"dureeMin":17,"corrige":"**1 et 2.**\n- *Ich **lerne** seit zwei Jahren Deutsch.* — avec *seit*, on emploie le **présent**, pas le parfait.\n- *Mein Vater **fährt** jeden Tag nach Paris.* — *fahren* est un verbe fort : a → ä aux 2e et 3e personnes du singulier.\n- *Du **arbeitest** viel, oder?* — radical en -t : on intercale un **e**.\n- *Du **heißt** Jonas Müller, richtig?* — radical en -ß : le -st perd son **s**.\n- *Meine Freunde und ich **fahren** oft ans Meer.* — sujet *wir* : le changement de voyelle ne touche **pas** le pluriel.\n- ***Morgen spiele ich** Fußball.* — le verbe conjugué est en **2e position** ; l’adverbe de temps suffit à dire l’avenir.\n\n**3.** Exemple : *Hallo Jonas! Ich heiße Hugo und ich lerne seit vier Jahren Deutsch. Mein Bruder liest viel und er spricht Spanisch. Meine Mutter fährt jeden Tag zur Arbeit. Morgen spiele ich Tennis.* Le correcteur vérifie les terminaisons, un verbe fort bien conjugué, *seit* + présent et un avenir au présent avec le verbe en 2e position."}$exo$::jsonb),
  ('162e9d91-c27b-57c0-81df-a00b64a99b64'::uuid, 1, 'traduction', $exo${"titre":"Les formes du prétérit","consigne":"Donne la forme du prétérit, puis indique la famille de chaque verbe.","enonce":"**1. Mets au prétérit** :\n\na) *spielen* (ich)\nb) *gehen* (er)\nc) *kommen* (sie, elle)\nd) *sein* (ich)\ne) *haben* (er)\nf) *können* (wir)\ng) *bringen* (er)\nh) *nehmen* (ich)\n\n**2.** Pour *spielen*, *gehen* et *bringen*, indique la **famille** (faible, fort, mixte) et explique comment se forme leur prétérit.","bareme":[{"critere":"Les huit formes justes : spielte, ging, kam, war, hatte, konnten, brachte, nahm","points":12},{"critere":"Familles justes : spielen faible, gehen fort, bringen mixte","points":4},{"critere":"Formation expliquée : -te ; voyelle changée sans terminaison ; radical modifié + -te","points":4}],"dureeMin":7,"corrige":"**1.**\na) *ich spielte*\nb) *er ging*\nc) *sie kam*\nd) *ich war*\ne) *er hatte*\nf) *wir konnten* (modal : pas d’inflexion au prétérit)\ng) *er brachte*\nh) *ich nahm*\n\nAux 1re et 3e personnes du singulier, les formes sont identiques (*ich ging / er ging*).\n\n**2.**\n- *spielen* : verbe **faible** → radical + **-te** + terminaisons (*spielte*).\n- *gehen* : verbe **fort** → voyelle changée, **aucune terminaison** aux 1re et 3e personnes (*ging*).\n- *bringen* : verbe **mixte** → radical modifié + terminaisons faibles (*brachte*)."}$exo$::jsonb),
  ('162e9d91-c27b-57c0-81df-a00b64a99b64'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Réécris le récit au prétérit, complète la phrase au plus-que-parfait, puis explique ton choix.","enonce":"**Situation.** Pour le journal du collège, tu dois raconter le samedi de Max. Voici tes notes, au présent :\n\n> Am Samstag geht Max in die Stadt. Er sieht seinen Freund Tim. Sie trinken einen Kaffee und sprechen lange. Dann kauft Max ein Buch. Am Abend schreibt er seiner Oma. Er ist sehr zufrieden.\n\n1. **Réécris** le récit au **prétérit**.\n2. Complète au plus-que-parfait : *Nachdem Max das Buch gekauft (…), ging er nach Hause.*\n3. Pourquoi faut-il employer le prétérit, et non le parfait, dans un article de journal ?","bareme":[{"critere":"Formes fortes justes : ging, sah, tranken, sprachen, schrieb, war","points":9},{"critere":"Forme faible juste : kaufte ; terminaisons du pluriel justes","points":3},{"critere":"Plus-que-parfait juste : hatte","points":3},{"critere":"Explication : prétérit = temps du récit écrit ; parfait = oral et lettre","points":5}],"dureeMin":11,"corrige":"**1.** *Am Samstag **ging** Max in die Stadt. Er **sah** seinen Freund Tim. Sie **tranken** einen Kaffee und **sprachen** lange. Dann **kaufte** Max ein Buch. Am Abend **schrieb** er seiner Oma. Er **war** sehr zufrieden.*\n\n- *gehen → ging*, *sehen → sah*, *trinken → trank* (pluriel *tranken*), *sprechen → sprach* (*sprachen*), *schreiben → schrieb* : verbes forts.\n- *kaufen → kaufte* : verbe faible.\n- *sein → war*.\n\n**2.** *Nachdem Max das Buch gekauft **hatte**, ging er nach Hause.* — prétérit de *haben* + participe II : l’achat est **antérieur** au retour.\n\n**3.** Un article de journal est un **texte narratif écrit** : on y raconte au **prétérit**. Le parfait est le passé de l’oral et de la lettre ; mélanger les deux dans un même récit fait désordre."}$exo$::jsonb),
  ('162e9d91-c27b-57c0-81df-a00b64a99b64'::uuid, 3, 'traduction', $exo${"titre":"Une journée d’hiver","consigne":"Conjugue le récit, traduis, puis justifie les choix de temps avec les règles du cours.","enonce":"**Document.** Début d’une nouvelle, verbes à l’infinitif.\n\n> Es (1. sein) kalt. Anna (2. bleiben) zu Hause und (3. schreiben) einen Brief. Nachdem sie den Brief geschrieben (4. haben), (5. gehen) sie zur Post. Dort (6. finden) sie ihren Freund Paul. Er (7. wollen) einen Kaffee trinken. Sie (8. trinken) zusammen einen Kaffee und (9. denken) an die Ferien.\n\n1. Conjugue les **neuf verbes** : prétérit partout, plus-que-parfait pour (4).\n2. **Traduis** en allemand, pour la suite de la nouvelle : *Il faisait nuit et Anna était fatiguée. Elle ne pouvait pas dormir.*\n3. Pourquoi l’imparfait français devient-il ici un prétérit ? Aurait-on dit la même chose dans un dialogue ?\n4. À l’oral, Anna dit *Ich bin müde gewesen*. Est-ce faux ? Que dirait-on plutôt ?","bareme":[{"critere":"Formes justes : war, blieb, schrieb, ging, fand, wollte, tranken, dachten","points":6},{"critere":"Plus-que-parfait juste (hatte) et antériorité expliquée","points":3},{"critere":"Traduction juste : Es war dunkel (Nacht) und Anna war müde. Sie konnte nicht schlafen","points":5},{"critere":"Règle de registre : prétérit dans un récit écrit, parfait dans un dialogue","points":4},{"critere":"Ich war müde, ce que tout le monde dit (sein survit au prétérit à l’oral)","points":2}],"dureeMin":17,"corrige":"**1.** *Es **war** kalt. Anna **blieb** zu Hause und **schrieb** einen Brief. Nachdem sie den Brief geschrieben **hatte**, **ging** sie zur Post. Dort **fand** sie ihren Freund Paul. Er **wollte** einen Kaffee trinken. Sie **tranken** zusammen einen Kaffee und **dachten** an die Ferien.*\n\n(*denken → dachte* est un verbe mixte ; *wollen → wollte* un modal ; le plus-que-parfait *hatte geschrieben* marque ce qui s’est passé **avant** le départ pour la poste.)\n\n**2.** *Es war Nacht (Es war dunkel) und Anna war müde. Sie konnte nicht schlafen.* — *sein → war*, *können → konnte*.\n\n**3.** L’allemand oppose parfait et prétérit par le **registre**, pas par l’aspect : dans un **récit écrit**, tout passé se dit au prétérit, y compris ce que le français met à l’imparfait. Dans un **dialogue**, on aurait employé le **parfait** (sauf pour *sein, haben, werden* et les modaux).\n\n**4.** Ce n’est pas faux, mais tout le monde dit ***Ich war müde*** : *sein*, *haben*, *werden* et les modaux restent au prétérit même à l’oral."}$exo$::jsonb),
  ('241a074e-a0c0-5c7a-a35d-350a5e1dc922'::uuid, 1, 'traduction', $exo${"titre":"Participes et auxiliaires","consigne":"Forme le participe II de chaque verbe, puis choisis l’auxiliaire.","enonce":"**1. Donne le participe II** :\n\na) *spielen* · b) *machen* · c) *sehen* · d) *fahren* · e) *studieren* · f) *besuchen* · g) *einkaufen* · h) *aufstehen*\n\n**2. Choisis l’auxiliaire** (*haben* ou *sein*) et complète :\n\na) Ich … nach Hause gegangen.\nb) Wir … Pizza gegessen.\nc) Er … sofort eingeschlafen.\nd) Sie … zu Hause geblieben.\ne) Ihr … Fußball gespielt.\nf) Was … passiert?","bareme":[{"critere":"Participes justes : gespielt, gemacht, gesehen, gefahren, studiert, besucht, eingekauft, aufgestanden","points":10},{"critere":"Auxiliaires justes : bin, haben, ist, ist, habt, ist","points":10}],"dureeMin":8,"corrige":"**1.**\na) *gespielt* · b) *gemacht* (faibles : ge- + radical + -t)\nc) *gesehen* · d) *gefahren* (forts : ge- + radical + -en)\ne) *studiert* (en -ieren : pas de ge-)\nf) *besucht* (préverbe inséparable : pas de ge-)\ng) *eingekauft* · h) *aufgestanden* (préverbe séparable : le ge- s’intercale)\n\n**2.**\na) Ich **bin** nach Hause gegangen. (déplacement)\nb) Wir **haben** Pizza gegessen.\nc) Er **ist** sofort eingeschlafen. (changement d’état)\nd) Sie **ist** (ou **sind**) zu Hause geblieben. (*bleiben* prend sein)\ne) Ihr **habt** Fußball gespielt.\nf) Was **ist** passiert? (*passieren* prend sein)"}$exo$::jsonb),
  ('241a074e-a0c0-5c7a-a35d-350a5e1dc922'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"Mets le message de Jonas au parfait, en respectant l’ordre des mots, puis complète la subordonnée.","enonce":"**Situation.** Jonas raconte son week-end à son ami Ben, dans un message. Ses notes sont au présent :\n\n> Am Samstag stehe ich um 9 Uhr auf. Dann fahre ich mit dem Zug nach Hamburg. Dort besuche ich meine Oma. Wir essen Kuchen und spielen Karten. Am Abend bleibe ich bei ihr.\n\n1. **Réécris** le message au **parfait**.\n2. Complète au parfait : *Ich bin müde, weil ich viel (lernen).*\n3. Pourquoi Jonas raconte-t-il au parfait et pas au prétérit ?","bareme":[{"critere":"Auxiliaires justes : bin aufgestanden, bin gefahren, bin geblieben ; habe besucht, haben gegessen/gespielt","points":8},{"critere":"Participes justes (aufgestanden, gefahren, besucht, gegessen, gespielt, geblieben)","points":5},{"critere":"Participe en fin de phrase, auxiliaire en 2e position ; subordonnée : gelernt habe","points":4},{"critere":"Explication : le parfait est le passé de la conversation et du message","points":3}],"dureeMin":11,"corrige":"**1.** *Am Samstag **bin** ich um 9 Uhr **aufgestanden**. Dann **bin** ich mit dem Zug nach Hamburg **gefahren**. Dort **habe** ich meine Oma **besucht**. Wir **haben** Kuchen **gegessen** und Karten **gespielt**. Am Abend **bin** ich bei ihr **geblieben**.*\n\n- *aufstehen* (changement d’état), *fahren* (déplacement), *bleiben* → **sein**.\n- *besuchen* : inséparable, pas de ge- ; *aufstehen* : séparable, ge- intercalé.\n- Auxiliaire en **2e position**, participe **à la fin**.\n\n**2.** *Ich bin müde, weil ich viel **gelernt habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**, après le participe.\n\n**3.** Un message à un ami, c’est de la **conversation** écrite : on raconte au **parfait**. Le prétérit est le temps du récit écrit (roman, presse)."}$exo$::jsonb),
  ('241a074e-a0c0-5c7a-a35d-350a5e1dc922'::uuid, 3, 'traduction', $exo${"titre":"La copie à corriger","consigne":"Repère les phrases fausses et corrige-les en citant la règle, puis traduis et explique.","enonce":"**Document.** Sept phrases tirées de la copie de Léo.\n\n> a) Ich habe nach Berlin gefahren.\n> b) Er hat mit seiner Oma getelefoniert.\n> c) Wir haben im Supermarkt geeinkauft.\n> d) Ich habe das Auto in die Garage gefahren.\n> e) Ich bin müde, weil ich habe den ganzen Tag gearbeitet.\n> f) Was ist gestern passiert?\n> g) Sie hat früh eingeschlafen.\n\n1. **Deux** phrases sont justes : lesquelles ? Justifie.\n2. **Corrige** les cinq autres en citant la règle.\n3. **Traduis**, pour un message à un ami : *Hier, je suis resté à la maison et j’ai lu un livre. Ma sœur s’est endormie tôt.*\n4. *Il pleuvait* se traduit-il de la même façon dans un dialogue et dans un roman ? Explique.","bareme":[{"critere":"Phrases justes identifiées (d et f) et justifiées : emploi transitif ; passieren prend sein","points":4},{"critere":"Corrections : bin gefahren, telefoniert, eingekauft, gearbeitet habe, ist eingeschlafen","points":6},{"critere":"Traduction juste : bin geblieben, habe gelesen, ist eingeschlafen, participes en fin","points":6},{"critere":"Registre expliqué : parfait dans un dialogue, prétérit dans un roman","points":4}],"dureeMin":17,"corrige":"**1.** **d)** est juste : *fahren* est employé **transitivement** (il a un complément, *das Auto*), il prend donc **haben**. **f)** est juste : *passieren* fait partie des six verbes à part qui prennent **sein**.\n\n**2.**\na) *Ich **bin** nach Berlin gefahren.* — déplacement d’un point à un autre : **sein**.\nb) *Er hat mit seiner Oma **telefoniert**.* — verbe en -ieren : **pas de ge-**.\nc) *Wir haben im Supermarkt **eingekauft**.* — préverbe séparable : le ge- **s’intercale**.\ne) *…, weil ich den ganzen Tag **gearbeitet habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**.\ng) *Sie **ist** früh eingeschlafen.* — changement d’état : **sein**.\n\n**3.** *Gestern bin ich zu Hause geblieben und habe ein Buch gelesen. Meine Schwester ist früh eingeschlafen.* — *bleiben* et *einschlafen* prennent sein ; *lesen* (fort) donne *gelesen*.\n\n**4.** Non. L’allemand distingue parfait et prétérit par le **registre** : dans un **dialogue**, *Es hat geregnet* (parfait) ; dans un **roman**, *Es regnete* (prétérit). Le français, lui, oppose imparfait et passé composé par l’**aspect**."}$exo$::jsonb),
  ('f40c1f56-45df-5338-a499-4bfe65332daa'::uuid, 1, 'traduction', $exo${"titre":"Werden au futur","consigne":"Mets les phrases au Futur I, puis indique ce qu’exprime werden dans chaque phrase de la partie 2.","enonce":"**1. Mets au Futur I** :\n\na) Ich helfe dir.\nb) Du kommst nicht.\nc) Er schreibt einen Brief.\nd) Wir spielen Fußball.\ne) Ihr lernt viel.\nf) Sie (ils) fahren nach Wien.\n\n**2.** Que signifie *werden* dans chaque phrase : « devenir », futur ou passif ?\n\na) *Er wird Arzt.*\nb) *Das Haus wird gebaut.*\nc) *Er wird kommen.*","bareme":[{"critere":"Formes de werden justes : werde, wirst, wird, werden, werdet, werden","points":6},{"critere":"Infinitif placé en fin de phrase dans les six phrases","points":6},{"critere":"Les trois valeurs identifiées d’après ce qui suit werden","points":8}],"dureeMin":7,"corrige":"**1.**\na) *Ich **werde** dir **helfen**.*\nb) *Du **wirst** nicht **kommen**.*\nc) *Er **wird** einen Brief **schreiben**.*\nd) *Wir **werden** Fußball **spielen**.*\ne) *Ihr **werdet** viel **lernen**.*\nf) *Sie **werden** nach Wien **fahren**.*\n\n*werden* conjugué en 2e position, **infinitif à la fin**.\n\n**2.** C’est ce qui **suit** *werden* qui tranche :\na) un **nom** → « **devenir** » : il devient médecin.\nb) un **participe II** → **passif** : la maison est construite.\nc) un **infinitif** → **futur** : il viendra."}$exo$::jsonb),
  ('f40c1f56-45df-5338-a499-4bfe65332daa'::uuid, 2, 'traduction', $exo${"titre":"Les projets d’Emma","consigne":"Choisis entre présent et futur, justifie, puis traite la subordonnée et la supposition.","enonce":"**Situation.** Emma écrit à son amie Clara.\n\n> a) Morgen (fahren) ich nach Hamburg.\n> b) Keine Sorge, ich (helfen) dir! (une promesse, sans repère de temps)\n> c) Die Prüfung (sein) nicht einfach. (une prédiction)\n> d) Nächste Woche (schreiben) ich die Mathearbeit.\n\n1. Pour chaque phrase, choisis **présent** ou **Futur I**, conjugue et justifie.\n2. Complète au futur : *Ich hoffe, dass Tim (kommen).*\n3. Clara répond : *« Tim antwortet nicht. Er wird wohl krank sein. »* Traduis la seconde phrase et explique le piège.","bareme":[{"critere":"a) fahre et d) schreibe au présent, justifiés par l’adverbe de temps","points":5},{"critere":"b) werde helfen et c) wird sein au futur, justifiés (promesse, prédiction)","points":5},{"critere":"Subordonnée juste : dass Tim kommen wird (werden à la fin)","points":4},{"critere":"Supposition traduite : Il doit être malade ; ce n’est pas un futur","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Morgen **fahre** ich nach Hamburg.* — **présent** : l’adverbe *morgen* suffit à dire l’avenir.\nb) *Ich **werde** dir **helfen**!* — **futur** : une promesse, sans repère de temps.\nc) *Die Prüfung **wird** nicht einfach **sein**.* — **futur** : une prédiction.\nd) *Nächste Woche **schreibe** ich die Mathearbeit.* — **présent** : *nächste Woche* précise l’avenir.\n(Le futur en a et d n’est pas faux, seulement plus lourd.)\n\n**2.** *Ich hoffe, dass Tim kommen **wird**.* — en subordonnée, les deux morceaux se rejoignent à la fin et c’est *werden* qui ferme.\n\n**3.** *« Il **doit** être malade. »* Ce futur renforcé par *wohl* exprime une **hypothèse sur le présent**, pas l’avenir ; traduire « il sera malade » est un contresens."}$exo$::jsonb),
  ('f40c1f56-45df-5338-a499-4bfe65332daa'::uuid, 3, 'traduction', $exo${"titre":"Les mille visages de werden","consigne":"Analyse et traduis chaque phrase, transforme la subordonnée, puis rédige tes projets.","enonce":"**1. Analyse et traduis** : pour chaque phrase, dis ce qu’exprime *werden* (devenir, futur, passif, supposition, insistance), puis traduis.\n\na) *Sie wird Lehrerin.*\nb) *Die Stadt wird renoviert.*\nc) *Er wird wohl zu Hause sein.*\nd) *Er wird es vergessen haben.*\ne) *Du wirst jetzt aufräumen!*\nf) *Das wird nicht einfach sein.*\n\n**2. Transforme** en subordonnée introduite par *dass* : *Ich glaube: Er wird morgen kommen.*\n\n**3. Production** (5 lignes environ) : écris tes projets pour les prochaines vacances. Emploie au moins **deux** fois le présent avec un adverbe de temps, et **deux** fois le Futur I (une promesse, une prédiction).","bareme":[{"critere":"Valeurs identifiées d’après ce qui suit werden (devenir, passif, supposition, Futur II, insistance, prédiction)","points":6},{"critere":"Traductions justes, sans contresens sur c) et d)","points":5},{"critere":"Subordonnée juste : dass er morgen kommen wird","points":3},{"critere":"Production : présent avec adverbe et Futur I bien formé (werden + infinitif final)","points":6}],"dureeMin":17,"corrige":"**1.**\na) Nom après *werden* → **devenir** : *Elle devient professeure.*\nb) Participe II → **passif** : *La ville est rénovée.*\nc) Futur + *wohl* → **supposition** sur le présent : *Il doit être à la maison.*\nd) Futur II → **supposition** sur le passé : *Il a dû l’oublier.*\ne) Futur → **insistance**, presque une menace : *Tu vas ranger, maintenant !*\nf) Futur → **prédiction** : *Ça ne sera pas facile.*\n\n**2.** *Ich glaube, dass er morgen kommen **wird**.* — *werden* conjugué ferme la subordonnée, après l’infinitif.\n\n**3.** Exemple : *Nächsten Sommer fahre ich nach Österreich. Am ersten Tag besuche ich Wien. Ich werde dir jeden Tag schreiben, versprochen! Das wird bestimmt toll sein.* Le correcteur vérifie le présent avec *nächsten Sommer, morgen…*, le verbe en 2e position, et deux Futur I justes (*werde… schreiben*, *wird… sein*), infinitif en fin de phrase."}$exo$::jsonb),
  ('46e6dcca-44f1-5b35-90bb-610ce31f2567'::uuid, 1, 'traduction', $exo${"titre":"Donner un ordre à chacun","consigne":"Forme l’impératif demandé, sans oublier le pronom quand il le faut.","enonce":"**1. Forme l’impératif** de *kommen* pour **du**, **ihr** et **Sie**.\n\n**2. Forme l’impératif** pour **du** :\n\na) *geben* (mir das Buch)\nb) *fahren* (langsam)\nc) *arbeiten* (mehr)\nd) *lesen* (den Text)\ne) *nehmen* (den Bus)\n\n**3.** Donne l’impératif de *sein* (*ruhig sein*) pour **du**, **ihr** et **Sie**.","bareme":[{"critere":"kommen juste : Komm! Kommt! Kommen Sie!","points":5},{"critere":"Formes du juste : Gib! Fahr! Arbeite! Lies! Nimm!","points":10},{"critere":"sein juste : Sei ruhig! Seid ruhig! Seien Sie ruhig!","points":5}],"dureeMin":7,"corrige":"**1.** *Komm!* (du : radical, sans terminaison ni pronom) · *Kommt!* (ihr : forme du présent, sans pronom) · *Kommen Sie!* (Sie : infinitif + pronom).\n\n**2.**\na) *Gib mir das Buch!* — l’alternance e → i se **garde**.\nb) *Fahr langsam!* — l’alternance a → ä se **perd** (pas « Fähr »).\nc) *Arbeite mehr!* — le -e final est **obligatoire** après -t.\nd) *Lies den Text!* — e → ie gardé.\ne) *Nimm den Bus!* — e → i gardé.\n\n**3.** *Sei ruhig!* · *Seid ruhig!* · *Seien Sie ruhig!* — *sein* est à part."}$exo$::jsonb),
  ('46e6dcca-44f1-5b35-90bb-610ce31f2567'::uuid, 2, 'traduction', $exo${"titre":"Le départ en classe verte","consigne":"Transforme chaque consigne en impératif, à la personne indiquée, en ajoutant bitte quand c’est demandé.","enonce":"**Situation.** Le jour du départ en classe verte, Frau Keller, la professeure, et les élèves se donnent des consignes.\n\n1. À ton camarade Paul (**du**) :\na) *aufstehen* (+ bitte)\nb) *mich heute Abend anrufen*\nc) *langsam fahren* (à vélo)\n\n2. À toute la classe (**ihr**) :\nd) *leise sein*\ne) *die Koffer nehmen*\n\n3. À Frau Keller (**Sie**) :\nf) *die Tür zumachen* (+ bitte)\n\n4. À tout le groupe, toi compris (**wir**) :\ng) *gehen*\n\n5. Où se place le préverbe séparable à l’impératif ? Appuie-toi sur a), b) et f).","bareme":[{"critere":"Formes du justes : Steh bitte auf! Ruf mich heute Abend an! Fahr langsam!","points":6},{"critere":"Formes ihr justes : Seid leise! Nehmt die Koffer!","points":4},{"critere":"Formes Sie et wir justes : Machen Sie bitte die Tür zu! Gehen wir!","points":4},{"critere":"Règle : verbe en 1re position, préverbe séparable rejeté à la fin","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Steh bitte auf!*\nb) *Ruf mich heute Abend an!*\nc) *Fahr langsam!* (a → ä se perd)\n\n**2.**\nd) *Seid leise!* (*sein* est à part)\ne) *Nehmt die Koffer!* (forme du présent, sans pronom)\n\n**3.**\nf) *Machen Sie bitte die Tür zu!* (infinitif + *Sie*)\n\n**4.**\ng) *Gehen wir!* (« allons-y »)\n\n**5.** Le verbe **ouvre** la phrase, en première position, et le préverbe séparable (*auf*, *an*, *zu*) part **à la fin** de la phrase. *bitte* se place juste après le verbe (ou le pronom *Sie*)."}$exo$::jsonb),
  ('46e6dcca-44f1-5b35-90bb-610ce31f2567'::uuid, 3, 'traduction', $exo${"titre":"Ordres secs, ordres polis","consigne":"Adoucis, corrige et analyse les ordres, en justifiant avec les règles du cours.","enonce":"**Document 1.** Mot laissé par Anna à son frère Tom :\n\n> Mach das Fenster zu! Räum dein Zimmer auf! Gib mir mein Buch!\n\n**Document 2.** Cinq ordres écrits par un élève :\n\n> a) Fähr langsam! · b) Gebe mir das! · c) Arbeit! · d) Kommst du! · e) Sei ruhig, Herr Braun!\n\n1. Tom trouve le mot d’Anna **hostile**. Explique pourquoi, puis **réécris-le** avec *bitte*, *mal* ou *doch* (une particule différente par phrase).\n2. **Corrige** les cinq ordres du document 2 en expliquant chaque faute.\n3. Anna veut demander à sa voisine, Frau Schulz, de l’aider, le plus poliment possible. Écris la phrase.\n4. Quel est le registre de *Nicht rauchen!* et de *Du wirst jetzt lernen!* ?","bareme":[{"critere":"Explication : sans particules un impératif paraît sec ; trois phrases adoucies justes","points":5},{"critere":"Corrections : Fahr! Gib mir das! Arbeite! Komm! Seien Sie ruhig, Herr Braun!","points":7},{"critere":"Demande très polie juste : Könnten Sie mir helfen?","points":4},{"critere":"Registres : infinitif = panneaux, consignes ; futur = menaçant","points":4}],"dureeMin":16,"corrige":"**1.** Sans les petits mots *bitte, mal, doch*, un impératif allemand paraît **sec**, parfois hostile. Réécriture possible : *Mach bitte das Fenster zu! Räum doch dein Zimmer auf! Gib mir mal mein Buch!* — *bitte* ajoute la politesse, *doch* l’insistance amicale, *mal* la légèreté.\n\n**2.**\na) ***Fahr** langsam!* — l’alternance a → ä se **perd** à l’impératif.\nb) ***Gib** mir das!* — l’alternance e → i se **garde**.\nc) ***Arbeite**!* — -e final **obligatoire** après -t.\nd) ***Komm**!* — pour *du* : radical sans terminaison, **sans pronom**.\ne) ***Seien Sie** ruhig, Herr Braun!* — on vouvoie un adulte : forme *Sie*, avec le pronom ; *sein* est à part.\n\n**3.** *Könnten Sie mir bitte helfen, Frau Schulz?* — la question au **subjonctif II** est le registre **très poli**.\n\n**4.** *Nicht rauchen!* : l’infinitif seul, registre des **panneaux et consignes**. *Du wirst jetzt lernen!* : le futur, registre **menaçant**."}$exo$::jsonb),
  ('08b545ac-e023-5ded-adf8-5314e79e7968'::uuid, 1, 'traduction', $exo${"titre":"Wäre, hätte, würde","consigne":"Donne la forme de subjonctif II, puis mets les phrases au subjonctif II.","enonce":"**1. Donne le subjonctif II** (1re personne du singulier) de :\n\na) *sein* · b) *haben* · c) *können* · d) *müssen* · e) *wissen* · f) *mögen* · g) *werden*\n\n**2. Mets au subjonctif II** avec *würde* + infinitif :\n\na) Ich fahre gern nach Berlin.\nb) Wir spielen gern Tennis.\n\n**3.** À partir de quel temps se forment les formes simples ? Donne un exemple.","bareme":[{"critere":"Les sept formes justes : wäre, hätte, könnte, müsste, wüsste, möchte, würde","points":10},{"critere":"würde + infinitif final juste dans les deux phrases","points":6},{"critere":"Formation expliquée : prétérit + inflexion + -e, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *wäre* · b) *hätte* · c) *könnte* · d) *müsste* · e) *wüsste* · f) *möchte* · g) *würde*\n\n**2.**\na) *Ich **würde** gern nach Berlin **fahren**.*\nb) *Wir **würden** gern Tennis **spielen**.*\n*würde* est la construction **par défaut** pour la plupart des verbes ; l’infinitif va à la fin.\n\n**3.** Les formes simples se forment sur le **prétérit**, avec **inflexion** et un *-e* : *war → wäre*, *hatte → hätte*, *konnte → könnte*."}$exo$::jsonb),
  ('08b545ac-e023-5ded-adf8-5314e79e7968'::uuid, 2, 'traduction', $exo${"titre":"Au café, et si…","consigne":"Rends les demandes polies, puis transforme les faits en hypothèses irréelles.","enonce":"**Situation.** Au café, à Munich, Jules parle trop sèchement au serveur.\n\n1. Rends chaque phrase **polie** avec le subjonctif II :\na) *Ich will einen Kaffee.*\nb) *Können Sie mir helfen?*\nc) *Ich will zahlen.*\n\n2. En sortant, Jules se plaint. **Transforme** chaque paire de phrases en une hypothèse irréelle avec *wenn* :\nd) *Ich habe keine Zeit. Ich komme nicht mit.*\ne) *Das Wetter ist schlecht. Wir gehen nicht schwimmen.*\nf) *Ich habe kein Geld. Ich kaufe das Fahrrad nicht.*\n\n3. Pourquoi *Ich will einen Kaffee* est-il maladroit ?","bareme":[{"critere":"Demandes polies : Ich hätte gern einen Kaffee ; Könnten Sie mir helfen? ; Ich möchte bitte zahlen","points":6},{"critere":"Subordonnées justes : wenn + subjonctif II, verbe à la fin (hätte, wäre)","points":5},{"critere":"Principales justes : würde + infinitif, verbe en tête après la subordonnée","points":5},{"critere":"Explication : le présent de wollen sonne comme un ordre","points":4}],"dureeMin":11,"corrige":"**1.**\na) *Ich **hätte** gern einen Kaffee.* (ou *Ich **möchte** einen Kaffee.*)\nb) ***Könnten** Sie mir helfen?*\nc) *Ich **möchte** bitte zahlen.*\nPour la politesse, on préfère la **forme simple**.\n\n**2.**\nd) *Wenn ich Zeit **hätte**, **würde** ich **mitkommen**.*\ne) *Wenn das Wetter schön **wäre**, **würden** wir schwimmen **gehen**.* (ou *nicht schlecht wäre*)\nf) *Wenn ich Geld **hätte**, **würde** ich das Fahrrad **kaufen**.*\nDans la subordonnée, le verbe conjugué est **à la fin** ; la principale commence par le verbe (*würde*).\n\n**3.** *Ich will einen Kaffee* sonne comme un **ordre** ; *Ich hätte gern einen Kaffee* comme une **demande**. Le subjonctif II est la forme quotidienne de la politesse."}$exo$::jsonb),
  ('08b545ac-e023-5ded-adf8-5314e79e7968'::uuid, 3, 'traduction', $exo${"titre":"Si j’avais une année libre","consigne":"Transforme, complète, identifie les modes, puis rédige un paragraphe à l’irréel.","enonce":"**1. Supprime** *wenn* dans ces phrases, sans changer leur sens :\na) *Wenn ich Zeit hätte, würde ich kommen.*\nb) *Wenn das Wetter schön wäre, würden wir wandern.*\n\n**2. Complète** avec le subjonctif II :\nc) *Er tut so, als ob er alles (wissen).*\nd) *Sie spricht, als ob sie Deutsche (sein).*\ne) Ton ami est toujours fatigué. Donne-lui un **conseil** : *Du (sollen) mehr schlafen.*\n\n**3.** Dans un journal, tu lis : *Der Minister sagte, er sei krank.* Quel est le mode de *sei* ? À quoi sert-il ?\n\n**4. Production** (5 lignes environ) : *Wenn ich ein Jahr frei hätte…* Raconte ce que tu ferais. Emploie au moins **quatre** subjonctifs II (dont une forme simple et *würde*) et une phrase sans *wenn*.","bareme":[{"critere":"Phrases sans wenn justes : Hätte ich Zeit, würde ich kommen ; Wäre das Wetter schön, würden wir wandern","points":4},{"critere":"Formes justes : wüsste, wäre, solltest","points":4},{"critere":"Subjonctif I reconnu : discours indirect de la presse","points":3},{"critere":"Production : quatre subjonctifs II justes (forme simple et würde), verbe à la fin après wenn","points":6},{"critere":"Production : une phrase sans wenn, verbe en première place","points":3}],"dureeMin":17,"corrige":"**1.**\na) ***Hätte** ich Zeit, würde ich kommen.*\nb) ***Wäre** das Wetter schön, würden wir wandern.*\nQuand *wenn* disparaît, le verbe prend la **première place** : tournure élégante, valorisée à l’écrit.\n\n**2.**\nc) *…, als ob er alles **wüsste**.* — après *als ob*, le subjonctif II est de règle.\nd) *…, als ob sie Deutsche **wäre**.*\ne) *Du **solltest** mehr schlafen.* — *solltest* exprime le **conseil**.\n\n**3.** *sei* est un **subjonctif I** : il sert au **discours indirect de la presse** (on rapporte les paroles du ministre sans les prendre à son compte). Il suffit de le reconnaître.\n\n**4.** Exemple : *Wenn ich ein Jahr frei hätte, würde ich um die Welt reisen. Ich würde zuerst nach Kanada fliegen. Dort könnte ich Englisch lernen. Hätte ich genug Geld, würde ich auch Japan besuchen. Das wäre toll!* Le correcteur vérifie au moins une forme simple (*hätte, wäre, könnte…*), *würde* + infinitif final, le verbe à la fin après *wenn*, et une phrase sans *wenn* avec le verbe en tête."}$exo$::jsonb),
  ('973fe6e4-0ff3-55fa-a800-0c4993c0842c'::uuid, 1, 'traduction', $exo${"titre":"Cinq phrases à ponctuer","consigne":"Recopie chaque phrase en plaçant les virgules là où l'allemand les exige, puis réponds à la question 2.","enonce":"**1. Recopie en ajoutant les virgules nécessaires.**\n\n1. Ich weiß dass du morgen kommst.\n2. Er ist müde aber glücklich.\n3. Ich kaufe Brot Milch und Käse.\n4. Sie lernt Deutsch um in Wien zu studieren.\n5. Das Buch das ich lese ist spannend.\n\n**2.** Dans la phrase 3, explique en une phrase pourquoi on ne met pas de virgule devant *und*.","bareme":[{"critere":"Virgules justes devant dass, aber et um… zu (phrases 1, 2, 4)","points":9},{"critere":"Relative enchâssée encadrée de deux virgules (phrase 5)","points":4},{"critere":"Énumération de la phrase 3 sans virgule devant und","points":3},{"critere":"Explication juste de l'absence de virgule devant und","points":4}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Ich weiß, dass du morgen kommst.* — virgule obligatoire devant une subordonnée.\n2. *Er ist müde, aber glücklich.* — virgule devant *aber*.\n3. *Ich kaufe Brot, Milch und Käse.* — virgule entre Brot et Milch, **pas** devant *und*.\n4. *Sie lernt Deutsch, um in Wien zu studieren.* — le groupe *um… zu* exige la virgule.\n5. *Das Buch, das ich lese, ist spannend.* — la relative enchâssée est encadrée des **deux** côtés.\n\n**2.** En allemand, la virgule marque une frontière grammaticale : *und* relie deux éléments de même rang dans une énumération, et en principe on ne met pas de virgule devant *und* (ni devant *oder*)."}$exo$::jsonb),
  ('973fe6e4-0ff3-55fa-a800-0c4993c0842c'::uuid, 2, 'traduction', $exo${"titre":"Le message de Léa à corriger","consigne":"Léa a écrit ce message sans respecter l'orthographe allemande. Recopie-le en corrigeant les majuscules, la ponctuation, les guillemets et les s / ß, puis réponds à la question 2.","enonce":"**1. Recopie le texte corrigé.**\n\n> gestern habe ich im park meinen freund tom getroffen. er sagt „ich komme morgen mit.“ ich hoffe dass er pünktlich ist. wir wollen die strasse entlang bis zum fluß laufen.\n\n**2.** Explique en français pourquoi on écrit *Straße* avec ß, mais *Fluss* avec ss.","bareme":[{"critere":"Majuscules aux noms communs (Park, Freund, Straße, Fluss) et en début de phrase","points":6},{"critere":"Deux-points avant le discours direct et guillemets allemands conservés","points":4},{"critere":"Virgule devant la subordonnée en dass","points":3},{"critere":"Graphies Straße et Fluss corrigées","points":3},{"critere":"Explication juste : ß après voyelle longue, ss après voyelle brève","points":4}],"dureeMin":10,"corrige":"**1. Texte corrigé**\n\n> *Gestern habe ich im Park meinen Freund Tom getroffen. Er sagt: „Ich komme morgen mit.“ Ich hoffe, dass er pünktlich ist. Wir wollen die Straße entlang bis zum Fluss laufen.*\n\nPoints attendus :\n- Majuscule à **tous** les noms communs : *Park*, *Freund*, *Straße*, *Fluss* (et bien sûr au prénom *Tom* et en début de phrase : *Gestern*, *Er*, *Ich*, *Wir*).\n- Deux-points avant le discours direct (*Er sagt:*), guillemets ouverts en bas et fermés en haut, et majuscule au début de la parole rapportée (*Ich komme…*).\n- Virgule obligatoire devant *dass*.\n\n**2.** On écrit **ß** après une voyelle longue ou une diphtongue : le *a* de *Straße* est long. On écrit **ss** après une voyelle brève : le *u* de *Fluss* est bref. *Fluß* est donc une faute (ancienne orthographe)."}$exo$::jsonb),
  ('973fe6e4-0ff3-55fa-a800-0c4993c0842c'::uuid, 3, 'traduction', $exo${"titre":"Thème : ponctuer et écrire juste","consigne":"Traduis les quatre phrases en allemand en respectant la ponctuation et les majuscules allemandes, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Il dit : « Je sais qu'elle vient. »\n2. Madame Weber, je vous remercie.\n3. La ville que je visite est belle mais chère.\n4. J'apprends l'allemand pour lire des livres.\n\n*Aide : danken + datif ; besuchen = visiter ; schön = beau ; teuer = cher ; das Buch, die Bücher.*\n\n**2.** Quelle est la différence de sens entre *Können Sie mir helfen?* et *Können sie mir helfen?* Explique pourquoi.","bareme":[{"critere":"Virgules justes : dass, relative enchâssée, aber, um… zu","points":6},{"critere":"Deux-points et guillemets allemands au discours direct","points":3},{"critere":"Majuscules : noms communs, Ihnen de politesse","points":4},{"critere":"Ordre des mots et formes verbales corrects","points":3},{"critere":"Explication de la différence Sie / sie","points":4}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Er sagt: „Ich weiß, dass sie kommt.“*\n2. *Frau Weber, ich danke Ihnen.*\n3. *Die Stadt, die ich besuche, ist schön, aber teuer.*\n4. *Ich lerne Deutsch, um Bücher zu lesen.*\n\nPoints attendus :\n- Phrase 1 : deux-points avant la parole, guillemets „…“, virgule devant *dass*, *sie* (elle) en minuscule.\n- Phrase 2 : *danken* régit le datif : *Ihnen*, avec **majuscule** car c'est le vouvoiement.\n- Phrase 3 : relative encadrée de deux virgules, verbe *besuche* à la fin de la relative, virgule devant *aber*.\n- Phrase 4 : virgule devant *um… zu*, infinitif avec *zu* en fin de phrase.\n\n**2.** *Können Sie mir helfen?* = « Pouvez-vous m'aider ? » (vouvoiement, une personne à qui l'on parle). *Können sie mir helfen?* = « Peuvent-ils (ou peuvent-elles) m'aider ? ». À l'écrit, seule la majuscule distingue le *Sie* de politesse du *sie* de la 3e personne : l'oublier change le destinataire de la phrase."}$exo$::jsonb),
  ('fff58b7d-04c3-5a42-b00c-7c3499d94f14'::uuid, 1, 'traduction', $exo${"titre":"Changer le début de la phrase","consigne":"Réécris chaque phrase en la commençant par l'élément en gras. Attention à la place du verbe conjugué.","enonce":"**Réécris en commençant par l'élément en gras.**\n\n1. Ich fahre **morgen** nach Berlin.\n2. Wir spielen **am Samstag** Fußball.\n3. Er hat **gestern** einen Film gesehen.\n4. Ich stehe **um sieben Uhr** auf.\n5. Meine Schwester muss **heute Abend** arbeiten.","bareme":[{"critere":"Verbe conjugué en deuxième position et sujet placé derrière (inversion)","points":12},{"critere":"Second morceau du verbe (participe, infinitif, préverbe) laissé en fin de phrase","points":8}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Morgen fahre ich nach Berlin.*\n2. *Am Samstag spielen wir Fußball.*\n3. *Gestern hat er einen Film gesehen.*\n4. *Um sieben Uhr stehe ich auf.*\n5. *Heute Abend muss meine Schwester arbeiten.*\n\nPoints attendus :\n- Règle V2 : le verbe conjugué reste le **deuxième groupe**. Dès qu'un autre élément que le sujet ouvre la phrase, le sujet passe **derrière** le verbe (inversion). *Morgen ich fahre…* est faux.\n- Parenthèse verbale : *gesehen* (participe), *auf* (préverbe) et *arbeiten* (infinitif après le modal) restent à la toute fin."}$exo$::jsonb),
  ('fff58b7d-04c3-5a42-b00c-7c3499d94f14'::uuid, 2, 'traduction', $exo${"titre":"Cinq phrases à traduire dans le bon ordre","consigne":"Traduis en allemand. Soigne la place du verbe et l'ordre des compléments.","enonce":"**Traduis en allemand.**\n\n1. Demain, je dois travailler.\n2. Hier, Paul a acheté un vélo.\n3. Je donne le livre à l'enfant.\n4. Je le donne à l'enfant.\n5. Nous allons demain en train à Munich.\n\n*Aide : kaufen (gekauft) ; das Fahrrad ; das Buch ; das Kind ; fahren ; mit dem Zug ; München.*","bareme":[{"critere":"Verbe en deuxième position et inversion après Morgen / Gestern","points":6},{"critere":"Infinitif et participe rejetés en fin de phrase","points":5},{"critere":"Ordre datif puis accusatif, et pronom es placé devant le datif","points":5},{"critere":"Ordre temps, manière, lieu (TeKaMoLo) dans la phrase 5","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Morgen muss ich arbeiten.*\n2. *Gestern hat Paul ein Fahrrad gekauft.*\n3. *Ich gebe dem Kind das Buch.*\n4. *Ich gebe es dem Kind.*\n5. *Wir fahren morgen mit dem Zug nach München.*\n\nPoints attendus :\n- 1 et 2 : l'adverbe de temps occupe la première place, le verbe conjugué suit, puis le sujet (inversion). L'infinitif *arbeiten* et le participe *gekauft* ferment la phrase.\n- 3 : deux groupes nominaux → **datif puis accusatif** (*dem Kind das Buch*).\n- 4 : l'accusatif est un **pronom** → il passe devant (*es dem Kind*). *Ich gebe dem Kind es* est faux.\n- 5 : TeKaMoLo : temps (*morgen*), manière (*mit dem Zug*), lieu (*nach München*)."}$exo$::jsonb),
  ('fff58b7d-04c3-5a42-b00c-7c3499d94f14'::uuid, 3, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"À partir des notes, écris un petit texte de cinq phrases au présent, sauf une phrase au parfait. Au moins trois phrases doivent commencer par un autre élément que le sujet. Puis réponds à la question 2.","enonce":"**1. Rédige le texte à partir de ces notes.**\n\n- samedi : se lever à 8 heures (*aufstehen*)\n- ensuite : prendre le train pour Hambourg avec sa sœur\n- là-bas : devoir acheter un cadeau pour sa grand-mère (*müssen*)\n- dimanche : visiter le port — **au parfait** (*den Hafen besuchen*)\n- le soir : rentrer à la maison (*zurückkommen, nach Hause*)\n\n**2.** Choisis une de tes phrases qui commence par un complément de temps et explique en français la règle de la place du verbe qu'elle applique.","bareme":[{"critere":"Verbe conjugué en deuxième position dans chaque phrase, avec inversion","points":6},{"critere":"Parenthèse verbale : préverbe, infinitif du modal et participe en fin de phrase","points":6},{"critere":"Ordre des compléments (temps, manière, lieu) respecté","points":3},{"critere":"Explication juste de la règle V2 et de l'inversion","points":5}],"dureeMin":16,"corrige":"**1. Texte modèle**\n\n*Am Samstag steht Jonas um acht Uhr auf. Dann fährt er mit seiner Schwester mit dem Zug nach Hamburg. Dort muss er ein Geschenk für seine Großmutter kaufen. Am Sonntag hat er den Hafen besucht. Am Abend kommt er nach Hause zurück.*\n\nPoints attendus :\n- Chaque phrase ouverte par *Am Samstag*, *Dann*, *Dort*, *Am Sonntag*, *Am Abend* : verbe en 2e position, sujet **derrière**.\n- Préverbes *auf* et *zurück* en fin de phrase ; *kaufen* après le modal *muss* en fin de phrase ; participe *besucht* en fin de phrase après *hat*.\n- Compléments dans l'ordre temps → manière → lieu : *mit dem Zug nach Hamburg*.\n- Toute formulation équivalente correcte est acceptée (ex. *nimmt den Zug nach Hamburg*).\n\n**2.** Exemple : *Am Sonntag hat er den Hafen besucht.* Dans une déclarative, le verbe conjugué occupe toujours la deuxième place (le deuxième **groupe**, pas le deuxième mot). Comme le complément de temps *Am Sonntag* occupe la première place, le sujet *er* passe derrière le verbe : c'est l'inversion. Le participe *besucht* ferme la phrase."}$exo$::jsonb),
  ('2fda7bd6-974e-5e6d-bb2f-8139b11ea00a'::uuid, 1, 'traduction', $exo${"titre":"Trouver la bonne question","consigne":"Écris la question qui correspond à chaque réponse. La partie en gras est ce que l'on demande ; pour la phrase 1, pose une question fermée.","enonce":"**Écris la question (tutoie la personne).**\n\n1. Ja, ich komme morgen.\n2. Ich wohne **in Köln**.\n3. Ich fahre **nach Wien**.\n4. **Mein Bruder** ruft an.\n5. Ich sehe **den Lehrer**.","bareme":[{"critere":"Mot interrogatif juste (wo, wohin, wer, wen)","points":10},{"critere":"Place du verbe : 1re position (question fermée), 2e après le mot en w-","points":6},{"critere":"Conjugaison à la 2e personne et point d'interrogation","points":4}],"dureeMin":7,"corrige":"**Questions attendues**\n\n1. *Kommst du morgen?* — question fermée : verbe en **première** position.\n2. *Wo wohnst du?* — *wo* : le lieu où l'on est, **sans** mouvement.\n3. *Wohin fährst du?* — *wohin* : la destination, **avec** mouvement.\n4. *Wer ruft an?* — *wer* : qui (sujet, nominatif).\n5. *Wen siehst du?* — *wen* : qui (COD, accusatif de *wer*).\n\nPoints attendus : dans les questions ouvertes, le verbe reste en deuxième position, juste après le mot interrogatif ; *wer* se décline (*wen* à l'accusatif) ; ne pas confondre *wo* et *wohin*."}$exo$::jsonb),
  ('2fda7bd6-974e-5e6d-bb2f-8139b11ea00a'::uuid, 2, 'traduction', $exo${"titre":"Des questions indirectes","consigne":"Transforme chaque question directe en question indirecte avec l'amorce donnée, puis réponds à la question 2.","enonce":"**1. Transforme en question indirecte.**\n\n1. Kommt Lisa heute? → *Ich frage mich, …*\n2. Wann beginnt der Film? → *Weißt du, …*\n3. Warum lernst du Deutsch? → *Sag mir, …*\n4. Wo wohnt dein Onkel? → *Ich weiß nicht, …*\n\n**2.** Pourquoi serait-il faux d'écrire *Ich frage mich, wenn Lisa heute kommt* ?","bareme":[{"critere":"Choix de ob pour la question fermée, mot en w- conservé ailleurs","points":6},{"critere":"Verbe conjugué rejeté à la fin de la subordonnée","points":8},{"critere":"Virgules et ponctuation finale correctes","points":3},{"critere":"Explication de l'opposition ob / wenn","points":3}],"dureeMin":10,"corrige":"**1. Phrases attendues**\n\n1. *Ich frage mich, ob Lisa heute kommt.*\n2. *Weißt du, wann der Film beginnt?*\n3. *Sag mir, warum du Deutsch lernst.*\n4. *Ich weiß nicht, wo dein Onkel wohnt.*\n\nPoints attendus :\n- La question indirecte est une subordonnée : virgule devant, et verbe conjugué **à la fin** (*kommt*, *beginnt*, *lernst*, *wohnt*).\n- Sans mot interrogatif (question fermée), on emploie *ob*.\n- Le point d'interrogation disparaît, sauf quand la principale elle-même est une question (phrase 2 : *Weißt du…?*).\n\n**2.** Le « si » d'une question indirecte exprime une **alternative** (oui ou non) : il se traduit par *ob*. *Wenn* introduit une **condition** ou un **moment** ; l'employer ici serait une faute de sens."}$exo$::jsonb),
  ('2fda7bd6-974e-5e6d-bb2f-8139b11ea00a'::uuid, 3, 'traduction', $exo${"titre":"Dialogue avant le concert","consigne":"Traduis ce dialogue en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu ne viens pas au concert ?\n— Si ! Mais je ne sais pas quand il commence.\n— À huit heures. À qui penses-tu ?\n— À Mia. Et toi, à quoi penses-tu ?\n— Aux vacances !\n\n*Aide : mitkommen ; zum Konzert ; beginnen ; denken an + accusatif ; die Ferien (pluriel).*\n\n**2.** Explique en français pourquoi on répond *Doch!* à la première question, et pourquoi on dit *an wen* pour Mia mais *woran* pour les vacances.","bareme":[{"critere":"Doch employé pour contredire la question négative","points":3},{"critere":"Question indirecte avec wann et verbe en fin de subordonnée","points":5},{"critere":"An wen pour une personne, woran pour une chose","points":5},{"critere":"Place du verbe dans les questions fermées et ouvertes","points":4},{"critere":"Explication juste de doch et de wo(r) + préposition","points":3}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n— *Kommst du nicht zum Konzert mit?* (ou *Du kommst nicht mit zum Konzert?*)\n— *Doch! Aber ich weiß nicht, wann es beginnt.*\n— *Um acht Uhr. An wen denkst du?*\n— *An Mia. Und woran denkst du?*\n— *An die Ferien!*\n\nPoints attendus :\n- *Doch!* et non *Ja!* pour dire « si ».\n- *…, wann es beginnt* : virgule, verbe à la fin ; *es* reprend *das Konzert* (neutre).\n- *An wen denkst du?* (personne : préposition + *wen*) ; *Woran denkst du?* (chose : *wo(r)-* soudé à la préposition).\n- Question ouverte : verbe en 2e position après le mot interrogatif.\n\n**2.** Face à une question **négative**, *ja* est impossible : pour contredire la négation, l'allemand répond *doch* (comme « si » en français). Pour interroger sur une **chose**, l'allemand soude *wo(r)-* et la préposition (*woran*) ; pour une **personne**, il garde la préposition suivie de *wen* ou *wem* (*an wen*)."}$exo$::jsonb),
  ('04e58be7-2cb0-5921-baee-b7fb0bfa7dc3'::uuid, 1, 'traduction', $exo${"titre":"Nicht ou kein ?","consigne":"Mets chaque phrase à la forme négative en choisissant entre nicht et kein.","enonce":"**Mets à la forme négative.**\n\n1. Ich habe ein Fahrrad.\n2. Ich kenne den Mann.\n3. Er trinkt Kaffee.\n4. Das Buch ist interessant.\n5. Wir haben Freunde in Berlin.\n6. Ich gehe ins Kino.","bareme":[{"critere":"Choix juste entre nicht et kein pour chaque phrase","points":10},{"critere":"Déclinaison de kein (keinen, keine au pluriel)","points":4},{"critere":"Place de nicht (après le COD défini, devant l'attribut et le lieu)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ich habe kein Fahrrad.* — nom précédé de *ein* → *kein*.\n2. *Ich kenne den Mann nicht.* — article défini → *nicht*, placé **après** le COD défini.\n3. *Er trinkt keinen Kaffee.* — nom sans article → *kein*, décliné à l'accusatif masculin : *keinen*.\n4. *Das Buch ist nicht interessant.* — on nie l'attribut : *nicht* **devant** lui.\n5. *Wir haben keine Freunde in Berlin.* — pluriel sans article → *keine* (kein a un pluriel).\n6. *Ich gehe nicht ins Kino.* — lieu directionnel : *nicht* **devant**.\n\nRègle : *kein* devant un nom précédé de *ein* ou sans article ; *nicht* devant un article défini, un possessif, un verbe, un adjectif."}$exo$::jsonb),
  ('04e58be7-2cb0-5921-baee-b7fb0bfa7dc3'::uuid, 2, 'traduction', $exo${"titre":"Cinq négations à traduire","consigne":"Traduis en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je ne l'ai pas vu hier. (*le* = un homme)\n2. Il ne travaille plus.\n3. Je ne pars pas demain, mais aujourd'hui.\n4. Personne ne vient.\n5. Je ne vois rien.\n\n*Aide : sehen (gesehen) ; arbeiten ; fahren ; kommen.*\n\n**2.** Un élève écrit *Ich sehe nicht nichts*. Explique en français pourquoi c'est faux.","bareme":[{"critere":"Mots négatifs justes : nicht mehr, niemand, nichts","points":6},{"critere":"Place de nicht : devant le participe, devant le mot nié","points":6},{"critere":"Rectification avec sondern","points":4},{"critere":"Explication : une seule négation suffit en allemand","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe ihn gestern nicht gesehen.* — négation de toute la phrase : *nicht* le plus à droite possible, devant le participe.\n2. *Er arbeitet nicht mehr.* — « ne… plus » = *nicht mehr*.\n3. *Ich fahre nicht morgen, sondern heute.* — on nie un seul mot : *nicht* **devant** *morgen* ; après une négation, on rectifie avec *sondern* (pas *aber*).\n4. *Niemand kommt.*\n5. *Ich sehe nichts.*\n\n**2.** En allemand, deux négations ne s'additionnent pas pour renforcer : **une seule suffit**. *Nichts* porte déjà la négation (« rien »), il ne faut donc pas ajouter *nicht*. La phrase juste est *Ich sehe nichts*."}$exo$::jsonb),
  ('04e58be7-2cb0-5921-baee-b7fb0bfa7dc3'::uuid, 3, 'traduction', $exo${"titre":"Paul répond non à tout","consigne":"Paul est de mauvaise humeur : il répond non à toutes les questions de sa mère. Écris ses réponses en phrases complètes, puis réponds à la question 2.","enonce":"**1. Écris les réponses négatives de Paul.**\n\n1. Hast du einen Hund gesehen?\n2. Hast du deine Hausaufgaben gemacht?\n3. Ist dein Freund nett?\n4. Fährst du nach Berlin? — *Paul rectifie : il va à Hambourg.*\n5. Wohnst du noch in Köln?\n6. Kommt jemand mit?\n\n**2.** Justifie en français ton choix entre *nicht* et *kein* dans les réponses 1 et 2.","bareme":[{"critere":"Choix nicht / kein juste et kein décliné (keinen)","points":6},{"critere":"Place de nicht : après le COD défini, devant l'attribut et le lieu","points":5},{"critere":"Emploi de sondern, nicht mehr et niemand","points":5},{"critere":"Justification juste des réponses 1 et 2","points":4}],"dureeMin":15,"corrige":"**1. Réponses modèles**\n\n1. *Nein, ich habe keinen Hund gesehen.*\n2. *Nein, ich habe meine Hausaufgaben nicht gemacht.*\n3. *Nein, er ist nicht nett.*\n4. *Nein, ich fahre nicht nach Berlin, sondern nach Hamburg.*\n5. *Nein, ich wohne nicht mehr in Köln.*\n6. *Nein, niemand kommt mit.*\n\nPoints attendus :\n- 1 : *einen Hund* → *keinen Hund* (accusatif masculin).\n- 2 : COD avec possessif → *nicht*, placé après le COD et devant le participe *gemacht*.\n- 3 : *nicht* devant l'attribut.\n- 4 : *nicht* devant le lieu directionnel, rectification par *sondern*.\n- 5 : « ne… plus » = *nicht mehr*. 6 : *niemand*, sans autre négation.\n\n**2.** Réponse 1 : le nom est précédé de l'article indéfini *einen* → on nie avec *kein*, qui se décline comme *ein* (*keinen*). Réponse 2 : le nom est précédé d'un possessif (*meine*) → on nie avec *nicht*, jamais avec *kein*."}$exo$::jsonb),
  ('d7887fb8-3df3-55e0-b88a-e717d48633ed'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie les deux phrases avec la conjonction donnée. Attention à la place du verbe.","enonce":"**Relie avec la conjonction entre parenthèses.**\n\n1. Ich bleibe zu Hause. Ich bin krank. (*weil*)\n2. Ich weiß. Er kommt morgen. (*dass*)\n3. Sie geht spazieren. Es regnet. (*obwohl*)\n4. Er ruft an. Er hat Zeit. (*wenn*)","bareme":[{"critere":"Verbe conjugué rejeté à la fin de chaque subordonnée","points":12},{"critere":"Virgule devant la subordonnée","points":4},{"critere":"Reste de la phrase et sujet correctement placés","points":4}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Ich bleibe zu Hause, weil ich krank bin.*\n2. *Ich weiß, dass er morgen kommt.*\n3. *Sie geht spazieren, obwohl es regnet.*\n4. *Er ruft an, wenn er Zeit hat.*\n\nPoints attendus : une subordonnée se reconnaît à la conjonction en tête et au **verbe conjugué à la toute fin** (*bin*, *kommt*, *regnet*, *hat*). La virgule devant la subordonnée est obligatoire. Le sujet suit directement la conjonction (*weil ich…*, *dass er…*). *Ich bleibe zu Hause, weil ich bin krank* est la faute à éviter."}$exo$::jsonb),
  ('d7887fb8-3df3-55e0-b88a-e717d48633ed'::uuid, 2, 'traduction', $exo${"titre":"Quand, parce que : quatre traductions","consigne":"Traduis en allemand. Soigne le choix de la conjonction et la place des verbes.","enonce":"**Traduis en allemand.**\n\n1. Quand j'étais petit, j'habitais à Munich.\n2. Je reste à la maison parce que je dois travailler.\n3. Il est fatigué parce qu'il a travaillé.\n4. Quand il pleut, je lis.\n\n*Aide : klein ; wohnen (prétérit wohnte) ; München ; zu Hause bleiben ; müde ; regnen ; lesen (er liest).*","bareme":[{"critere":"Choix de als pour un fait unique du passé, wenn pour la répétition","points":5},{"critere":"Verbe final en subordonnée, modal et auxiliaire en dernier","points":6},{"critere":"Subordonnée en tête : verbe de la principale juste après la virgule","points":6},{"critere":"Virgules correctes","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Als ich klein war, wohnte ich in München.* (*habe ich in München gewohnt* accepté)\n2. *Ich bleibe zu Hause, weil ich arbeiten muss.*\n3. *Er ist müde, weil er gearbeitet hat.*\n4. *Wenn es regnet, lese ich.*\n\nPoints attendus :\n- 1 : « quand » pour une période **unique** du passé → *als*, jamais *wann* ni *wenn*.\n- 4 : « quand » au présent, à valeur répétée → *wenn*.\n- 2 : avec un modal, c'est le **modal conjugué** qui ferme la subordonnée, après l'infinitif (*arbeiten muss*).\n- 3 : au temps composé, l'**auxiliaire** ferme la subordonnée, après le participe (*gearbeitet hat*).\n- 1 et 4 : la subordonnée en tête occupe la première position ; le verbe de la principale suit **immédiatement** la virgule (*wohnte ich*, *lese ich*)."}$exo$::jsonb),
  ('d7887fb8-3df3-55e0-b88a-e717d48633ed'::uuid, 3, 'traduction', $exo${"titre":"Pourquoi j'apprends l'allemand","consigne":"Écris à ton correspondant un message de six phrases pour lui expliquer pourquoi tu apprends l'allemand. Emploie weil, denn, dass, obwohl et damit, et place au moins une subordonnée en tête de phrase. Puis réponds à la question 2.","enonce":"**1. Rédige ton message (six phrases).**\n\nIdées possibles : étudier plus tard en Allemagne, ce que disent tes parents de l'allemand, la grammaire difficile mais le cours agréable, lire des livres en allemand, un professeur qui parle lentement, une visite de ton correspondant l'été prochain.\n\n**2.** Choisis une de tes phrases avec *weil* et une avec *denn*. Explique en français la différence de construction entre les deux.","bareme":[{"critere":"Cinq conjonctions employées avec le bon sens","points":5},{"critere":"Verbe conjugué à la fin après weil, dass, obwohl, damit","points":6},{"critere":"Subordonnée en tête suivie du verbe de la principale","points":3},{"critere":"Ordre normal conservé après denn","points":3},{"critere":"Explication juste de la différence weil / denn","points":3}],"dureeMin":18,"corrige":"**1. Message modèle**\n\n*Ich lerne Deutsch, weil ich später in Berlin studieren möchte. Mein Vater sagt, dass Deutsch in Europa sehr wichtig ist. Obwohl die Grammatik schwer ist, macht mir der Unterricht Spaß. Ich lese auch deutsche Bücher, denn ich will meinen Wortschatz verbessern. Meine Lehrerin spricht langsam, damit wir alles verstehen. Wenn du mich im Sommer besuchst, können wir zusammen Deutsch sprechen.*\n\nPoints attendus :\n- Verbe (ou modal) conjugué à la fin après *weil*, *dass*, *obwohl*, *damit*, *wenn* : *möchte*, *ist*, *verstehen*, *besuchst*.\n- *Obwohl…* et *Wenn…* en tête : le verbe de la principale suit la virgule (*macht mir*, *können wir*).\n- *denn* : ordre normal, verbe en 2e position (*denn ich will…*).\n- *damit* (but avec un autre sujet), *obwohl* (concession) employés avec le bon sens. Toute production correcte et variée est acceptée.\n\n**2.** *weil* est une conjonction de **subordination** : elle envoie le verbe conjugué à la fin (*weil ich… studieren möchte*). *denn* est une conjonction de **coordination** : elle ne touche pas à l'ordre des mots, le verbe reste en deuxième position (*denn ich will…*). Le sens (la cause) est le même."}$exo$::jsonb),
  ('1d044459-b9a5-572c-b46e-cb4780dfe2b7'::uuid, 1, 'traduction', $exo${"titre":"Le bon pronom relatif","consigne":"Complète chaque phrase avec le pronom relatif qui convient, puis justifie les phrases 2 et 4.","enonce":"**1. Complète avec le pronom relatif.**\n\n1. Der Mann, ___ dort steht, ist mein Onkel.\n2. Die Frau, ___ ich helfe, ist alt.\n3. Das Buch, ___ ich lese, ist spannend.\n4. Die Kinder, mit ___ ich spiele, sind nett.\n5. Der Junge, ___ Vater Arzt ist, heißt Tim.\n6. Die Stadt, ___ ich besuche, ist schön.\n\n**2.** Justifie en une phrase chacun le pronom des phrases 2 et 4 (genre et cas).","bareme":[{"critere":"Genre et nombre repris de l'antécédent","points":6},{"critere":"Cas donné par la fonction dans la relative (dont der, denen, dessen)","points":10},{"critere":"Justification juste des phrases 2 et 4","points":4}],"dureeMin":7,"corrige":"**1. Réponses**\n\n1. *der* — masculin, sujet → nominatif.\n2. *der* — féminin, complément de *helfen* qui régit le **datif** → *der*.\n3. *das* — neutre, COD → accusatif *das*.\n4. *denen* — pluriel, après *mit* qui régit le datif → datif pluriel *denen*.\n5. *dessen* — masculin, complément du nom *Vater* → génitif *dessen*, sans article devant *Vater*.\n6. *die* — féminin, COD → accusatif *die*.\n\n**2.** Phrase 2 : *Frau* est féminin (genre venu d'avant), et dans la relative le pronom est complément de *helfen*, qui régit le datif (cas venu d'après) → *der*. Phrase 4 : *Kinder* est au pluriel, et la préposition *mit* impose le datif → *denen*, l'une des trois formes qui diffèrent de l'article."}$exo$::jsonb),
  ('1d044459-b9a5-572c-b46e-cb4780dfe2b7'::uuid, 2, 'traduction', $exo${"titre":"Deux phrases, une relative","consigne":"Relie chaque paire de phrases par une subordonnée relative.","enonce":"**Relie par une relative.**\n\n1. Das ist der Film. Ich habe den Film gestern gesehen.\n2. Ich kenne die Lehrerin. Sie wohnt in unserer Straße.\n3. Hier ist mein Freund. Ich fahre mit ihm nach Wien.\n4. Das ist die Frau. Ihr Auto ist kaputt.\n5. Du sagst alles. Das ist richtig. → commence par *Alles, …*","bareme":[{"critere":"Pronom relatif juste (den, die, dem, deren, was)","points":8},{"critere":"Préposition placée devant le relatif","points":3},{"critere":"Verbe conjugué à la fin de la relative","points":5},{"critere":"Virgules obligatoires autour de la relative","points":4}],"dureeMin":10,"corrige":"**Phrases attendues**\n\n1. *Das ist der Film, den ich gestern gesehen habe.* — masculin, COD → *den* ; l'auxiliaire *habe* ferme la relative.\n2. *Ich kenne die Lehrerin, die in unserer Straße wohnt.* — féminin, sujet → *die*.\n3. *Hier ist mein Freund, mit dem ich nach Wien fahre.* — la préposition reste **devant** le relatif et commande le datif.\n4. *Das ist die Frau, deren Auto kaputt ist.* — génitif féminin *deren*, sans article devant *Auto*.\n5. *Alles, was du sagst, ist richtig.* — après *alles*, le relatif est *was*, jamais *das*.\n\nDans toutes les phrases : virgules obligatoires, verbe conjugué **à la fin** de la relative."}$exo$::jsonb),
  ('1d044459-b9a5-572c-b46e-cb4780dfe2b7'::uuid, 3, 'traduction', $exo${"titre":"Lukas et son club de football","consigne":"Traduis le texte en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Lukas est un garçon qui habite à Hambourg. Le club dans lequel il joue au football est connu. Son entraîneur, à qui il fait confiance, est sévère. La fille dont le frère joue aussi s'appelle Emma. Lukas gagne souvent, ce qui plaît à ses parents.\n\n*Aide : der Verein ; der Trainer ; vertrauen + datif ; streng ; das Mädchen ; gewinnen ; gefallen + datif ; bekannt.*\n\n**2.** Explique en français pourquoi on écrit *dessen* (et non *deren*) devant *Bruder*, et *dem* devant *er vertraut*.","bareme":[{"critere":"Pronoms relatifs justes : der, in dem, dem, dessen","points":6},{"critere":"Relatif was après une phrase entière","points":3},{"critere":"Verbe à la fin de chaque relative et virgules","points":5},{"critere":"Vocabulaire et reste de la phrase corrects","points":2},{"critere":"Justification de dessen et de dem","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Lukas ist ein Junge, der in Hamburg wohnt. Der Verein, in dem er Fußball spielt, ist bekannt. Sein Trainer, dem er vertraut, ist streng. Das Mädchen, dessen Bruder auch spielt, heißt Emma. Lukas gewinnt oft, was seinen Eltern gefällt.*\n\nPoints attendus :\n- *der* : masculin (Junge), sujet → nominatif.\n- *in dem* : la préposition reste devant le relatif ; *in* + datif (lieu où l'on est).\n- *dem* : masculin (Trainer), complément de *vertrauen* qui régit le datif.\n- *dessen* : génitif, sans article devant *Bruder*.\n- *was* : le relatif reprend toute la phrase précédente.\n- Chaque relative : virgules et verbe conjugué à la fin (*wohnt*, *spielt*, *vertraut*, *spielt*, *gefällt*). Relative enchâssée encadrée de deux virgules.\n\n**2.** Le pronom prend le **genre de l'antécédent** : *Mädchen* est **neutre** (diminutif en -chen), donc génitif neutre *dessen* ; *deren* serait féminin ou pluriel. Pour *dem* : l'antécédent *Trainer* est masculin, et dans la relative le pronom est complément de *vertrauen*, qui régit le datif → *dem*."}$exo$::jsonb),
  ('007837c7-03c9-5a55-afce-82e96a80fc1d'::uuid, 1, 'traduction', $exo${"titre":"Passer au passif","consigne":"Mets chaque phrase au passif présent. Garde l'agent quand il est nommé.","enonce":"**Mets au passif présent.**\n\n1. Man baut ein Haus.\n2. Der Lehrer korrigiert die Hefte.\n3. Man repariert das Auto.\n4. Die Mutter kocht die Suppe.\n\n*Rappel : le COD de la phrase active devient le sujet de la phrase passive.*","bareme":[{"critere":"werden conjugué et accordé au nouveau sujet (wird, werden)","points":8},{"critere":"Participe II rejeté en fin de phrase","points":6},{"critere":"Agent introduit par von + datif (vom Lehrer, von der Mutter)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ein Haus wird gebaut.*\n2. *Die Hefte werden vom Lehrer korrigiert.*\n3. *Das Auto wird repariert.*\n4. *Die Suppe wird von der Mutter gekocht.*\n\nPoints attendus :\n- Le passif d'action se construit avec **werden** (jamais *sein*) + participe II à la fin.\n- *werden* s'accorde avec le nouveau sujet : *die Hefte* est pluriel → *werden*.\n- *man* disparaît : pas d'agent. Une personne agent est introduite par *von* + datif : *vom Lehrer* (von dem), *von der Mutter*.\n- Participes : *gebaut*, *korrigiert*, *repariert* (verbes en -ieren, sans ge-), *gekocht*."}$exo$::jsonb),
  ('007837c7-03c9-5a55-afce-82e96a80fc1d'::uuid, 2, 'traduction', $exo${"titre":"Le passif à tous les temps","consigne":"Réponds aux quatre questions.","enonce":"1. Mets *Das Haus wird gebaut* au **prétérit**, puis au **parfait**.\n2. Mets *Der Brief wird geschrieben* au **parfait**.\n3. Traduis : « Le travail doit être fait aujourd'hui. » (*die Arbeit, machen*)\n4. Explique en français la différence de sens entre *Die Tür wird geschlossen* et *Die Tür ist geschlossen*.","bareme":[{"critere":"Prétérit du passif avec wurde","points":4},{"critere":"Parfait du passif avec ist + participe + worden","points":6},{"critere":"Passif avec modal : muss + participe + werden","points":5},{"critere":"Distinction juste entre passif d'action et passif d'état","points":5}],"dureeMin":10,"corrige":"1. Prétérit : *Das Haus wurde gebaut.* Parfait : *Das Haus ist gebaut worden.*\n2. *Der Brief ist geschrieben worden.*\n3. *Die Arbeit muss heute gemacht werden.* — le modal se conjugue, le passif passe à l'infinitif (*gemacht werden*).\n4. *Die Tür wird geschlossen* = passif d'**action** : quelqu'un est en train de fermer la porte (le film). *Die Tür ist geschlossen* = passif d'**état** : la porte est fermée, c'est un résultat acquis (la photo).\n\nPoint essentiel : au parfait du passif, le participe de *werden* perd son ge- : **worden**. *geworden* est réservé au verbe *werden* au sens de « devenir » (*Er ist Arzt geworden*). L'auxiliaire du parfait passif est toujours *sein* (*ist… worden*)."}$exo$::jsonb),
  ('007837c7-03c9-5a55-afce-82e96a80fc1d'::uuid, 3, 'traduction', $exo${"titre":"L'histoire d'un pont","consigne":"Traduis ce petit article en allemand en employant le passif, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Le pont de la ville a été construit en 1890. En 2020, il a été détruit par une tempête. Aujourd'hui, il est reconstruit par une entreprise allemande. Il doit être terminé en 2027. Ici, on travaille jour et nuit.\n\n*Aide : die Brücke (féminin) ; bauen ; zerstören ; der Sturm ; die Firma ; wieder aufbauen (wieder aufgebaut) ; fertigstellen (fertiggestellt) ; Tag und Nacht. Pour « on travaille », utilise le passif impersonnel.*\n\n**2.** Réécris la dernière phrase avec *man*, puis explique pourquoi tu as employé *durch* pour la tempête et *von* pour l'entreprise.","bareme":[{"critere":"Temps du passif justes : wurde / ist … worden, wird + participe","points":6},{"critere":"Passif avec modal : muss … fertiggestellt werden","points":3},{"critere":"Passif impersonnel : Hier wird … gearbeitet","points":3},{"critere":"Agent : durch + accusatif et von + datif","points":4},{"critere":"Phrase avec man et explication von / durch","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Die Brücke der Stadt wurde 1890 gebaut. 2020 ist sie durch einen Sturm zerstört worden. Heute wird sie von einer deutschen Firma wieder aufgebaut. Sie muss 2027 fertiggestellt werden. Hier wird Tag und Nacht gearbeitet.*\n\nPoints attendus :\n- *wurde gebaut* (prétérit) ou *ist gebaut worden* (parfait) acceptés pour les deux premières phrases ; au parfait : **worden**, jamais *geworden*.\n- *sie* reprend *die Brücke* (féminin).\n- *wird… wieder aufgebaut* : présent du passif, participe en fin de phrase.\n- *muss… fertiggestellt werden* : modal + infinitif passif.\n- *Hier wird… gearbeitet* : passif impersonnel d'un verbe sans COD.\n- Une date seule s'emploie sans préposition (*1890*, *2020*) ; *im Jahr 1890* accepté.\n\n**2.** *Hier arbeitet man Tag und Nacht.* (ou *Man arbeitet hier Tag und Nacht.*)\n*von* + datif introduit une personne ou une force qui agit : l'entreprise fait le travail. *durch* + accusatif introduit un **moyen** ou un intermédiaire, comme un phénomène naturel (*durch ein Erdbeben*, *durch einen Sturm*)."}$exo$::jsonb),
  ('2351b894-2d11-5494-bb91-1a06f1224118'::uuid, 1, 'traduction', $exo${"titre":"Avec ou sans zu ?","consigne":"Complète avec zu quand il le faut, ou écris l'infinitif entre parenthèses à la bonne forme.","enonce":"**Complète (mets un tiret si zu est impossible).**\n\n1. Ich versuche, pünktlich ___ sein.\n2. Ich kann gut ___ schwimmen.\n3. Er hat keine Lust, ins Kino ___ gehen.\n4. Wir gehen heute ___ schwimmen.\n5. Es ist wichtig, früh ___ (*aufstehen*).\n6. Vergiss nicht, Brot ___ (*einkaufen*).","bareme":[{"critere":"zu présent après versuchen, Lust haben, es ist wichtig, vergessen","points":8},{"critere":"Pas de zu après un modal et un verbe de mouvement","points":6},{"critere":"zu intercalé en un seul mot : aufzustehen, einzukaufen","points":6}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Ich versuche, pünktlich zu sein.* — *versuchen* appelle *zu*.\n2. *Ich kann gut schwimmen.* — **pas** de *zu* après un modal.\n3. *Er hat keine Lust, ins Kino zu gehen.* — *Lust haben* appelle *zu*.\n4. *Wir gehen heute schwimmen.* — **pas** de *zu* après un verbe de mouvement.\n5. *Es ist wichtig, früh aufzustehen.* — avec un préverbe séparable, *zu* s'intercale entre le préverbe et le radical, en **un seul mot**.\n6. *Vergiss nicht, Brot einzukaufen.* — même règle : *einzukaufen*.\n\nÀ retenir : *zu* se place juste devant l'infinitif, en fin de groupe ; les modaux, *sehen*, *hören*, *lassen* et les verbes de mouvement le refusent."}$exo$::jsonb),
  ('2351b894-2d11-5494-bb91-1a06f1224118'::uuid, 2, 'traduction', $exo${"titre":"But, privation, substitution","consigne":"Relie chaque paire de phrases avec um… zu, damit, ohne… zu ou statt… zu, selon l'indication.","enonce":"**Relie les phrases.**\n\n1. Ich spare Geld. Ich will ein Fahrrad kaufen. (*but*)\n2. Ich erkläre es dir. Du verstehst es. (*but*)\n3. Er geht weg. Er sagt nichts. (*privation : « sans »*)\n4. Sie sieht fern. Sie sollte arbeiten. (*substitution : « au lieu de »*)\n5. Ich stehe früh auf. Ich rufe meine Oma an. (*but*)","bareme":[{"critere":"Choix du bon outil pour chaque phrase","points":6},{"critere":"damit quand le sujet change (phrase 2) avec verbe final","points":5},{"critere":"zu bien placé, dont anzurufen en un seul mot","points":5},{"critere":"Virgule obligatoire devant chaque groupe","points":4}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Ich spare Geld, um ein Fahrrad zu kaufen.*\n2. *Ich erkläre es dir, damit du es verstehst.*\n3. *Er geht weg, ohne etwas zu sagen.*\n4. *Sie sieht fern, statt zu arbeiten.* (*anstatt* accepté)\n5. *Ich stehe früh auf, um meine Oma anzurufen.*\n\nPoints attendus :\n- *um… zu* exige que les deux propositions aient le **même sujet** (phrases 1 et 5).\n- Phrase 2 : le sujet change (*ich* / *du*) → *damit*, subordonnée avec le verbe à la fin (*verstehst*).\n- Phrase 3 : « ne rien dire » → *ohne etwas zu sagen* (« sans rien dire »).\n- Phrase 5 : *anrufen* est séparable → *anzurufen*.\n- Virgule obligatoire devant *um… zu*, *ohne… zu*, *statt… zu* et *damit*. Le groupe infinitif n'a jamais de sujet propre."}$exo$::jsonb),
  ('2351b894-2d11-5494-bb91-1a06f1224118'::uuid, 3, 'traduction', $exo${"titre":"Thème : six groupes infinitifs","consigne":"Traduis les six phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. J'ai beaucoup à faire.\n2. Ce travail doit être fait aujourd'hui. (*utilise sein + zu*)\n3. Il est parti sans fermer la porte.\n4. J'apprends l'allemand pour pouvoir parler avec ma correspondante.\n5. Mes parents travaillent pour que nous puissions partir en vacances.\n6. J'ai envie d'aller nager.\n\n*Aide : tun ; die Arbeit ; gehen (ist gegangen) ; die Tür schließen ; die Brieffreundin ; in Urlaub fahren ; Lust haben ; schwimmen gehen.*\n\n**2.** Explique en français pourquoi tu as employé *um… zu* dans la phrase 4 et *damit* dans la phrase 5.","bareme":[{"critere":"haben + zu et sein + zu justes (phrases 1 et 2)","points":4},{"critere":"ohne… zu et Lust haben… zu construits correctement","points":4},{"critere":"um… zu avec modal et damit avec verbe final","points":5},{"critere":"Virgules et place de zu","points":3},{"critere":"Explication juste um… zu / damit (même sujet ou non)","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe viel zu tun.* — *haben* + *zu* : valeur active (avoir à faire).\n2. *Diese Arbeit ist heute zu machen.* — *sein* + *zu* : valeur passive (doit être fait).\n3. *Er ist gegangen, ohne die Tür zu schließen.*\n4. *Ich lerne Deutsch, um mit meiner Brieffreundin sprechen zu können.*\n5. *Meine Eltern arbeiten, damit wir in Urlaub fahren können.*\n6. *Ich habe Lust, schwimmen zu gehen.*\n\nPoints attendus : virgule devant *ohne… zu*, *um… zu*, *damit* ; *zu* juste devant le dernier infinitif (*sprechen zu können*, *schwimmen zu gehen*) ; dans la phrase 5, le modal *können* ferme la subordonnée.\n\n**2.** Phrase 4 : le sujet est le même dans les deux propositions (*ich* apprend, *ich* veux parler) → groupe infinitif *um… zu*. Phrase 5 : le sujet change (*meine Eltern* travaillent, *wir* partons) → *um… zu* est impossible, il faut une subordonnée avec *damit* et un sujet exprimé."}$exo$::jsonb),
  ('38282da7-3f32-500b-b359-817b2db1001e'::uuid, 1, 'traduction', $exo${"titre":"Der, die ou das ?","consigne":"Donne l'article défini et l'article indéfini de chaque nom, puis justifie trois de tes réponses par un repère de genre.","enonce":"**1. Donne l'article défini et l'article indéfini (nominatif singulier).**\n\nMädchen · Zeitung · Montag · Freiheit · Lehrer · Essen · Frühling · Päckchen\n\n**2.** Pour *Mädchen*, *Zeitung* et *Montag*, donne en une phrase le repère qui permet de trouver le genre.","bareme":[{"critere":"Articles définis justes (der, die, das)","points":8},{"critere":"Articles indéfinis justes (ein, eine)","points":4},{"critere":"Repères de genre justes pour les trois noms","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n\n- *das Mädchen / ein Mädchen*\n- *die Zeitung / eine Zeitung*\n- *der Montag / ein Montag*\n- *die Freiheit / eine Freiheit*\n- *der Lehrer / ein Lehrer*\n- *das Essen / ein Essen*\n- *der Frühling / ein Frühling*\n- *das Päckchen / ein Päckchen*\n\n**2.** Repères :\n- *Mädchen* : tous les diminutifs en *-chen* et *-lein* sont **neutres** — la grammaire l'emporte sur le sens (même chose pour *Päckchen*).\n- *Zeitung* : les noms en *-ung* sont **féminins** (comme ceux en *-heit* : *Freiheit*).\n- *Montag* : les jours, mois et saisons sont **masculins** (comme *Frühling*, qui se termine aussi en *-ling*).\nAutres repères acceptés : *Lehrer* en *-er* masculin ; *Essen* infinitif substantivé neutre."}$exo$::jsonb),
  ('38282da7-3f32-500b-b359-817b2db1001e'::uuid, 2, 'traduction', $exo${"titre":"Article ou pas d'article ?","consigne":"Complète le texte avec l'article qui convient, ou avec Ø quand il n'en faut pas. Puis réponds à la question 2.","enonce":"**1. Complète le texte.**\n\n> Mein Vater ist ___ Lehrer. ___ Schule, in der er arbeitet, ist groß. Am Morgen trinkt er ___ Kaffee. ___ Mädchen neben ihm ist meine Schwester. Sie hat ___ Katze. ___ Katze heißt Mimi. Im Sommer fahren wir nach ___ Deutschland. Im Garten spielen ___ Kinder.\n\n*(Kinder : des enfants, sens indéfini.)*\n\n**2.** Dans *Das ist meine Schwester*, *das* est-il un article ? Explique.","bareme":[{"critere":"Genres justes des articles (Die Schule, Das Mädchen, eine / Die Katze)","points":6},{"critere":"Absence d'article : métier, matière, nom de pays","points":6},{"critere":"Pas d'article indéfini au pluriel","points":3},{"critere":"Explication de das démonstratif invariable","points":5}],"dureeMin":10,"corrige":"**1. Texte complété**\n\n> *Mein Vater ist Ø Lehrer. Die Schule, in der er arbeitet, ist groß. Am Morgen trinkt er Ø Kaffee. Das Mädchen neben ihm ist meine Schwester. Sie hat eine Katze. Die Katze heißt Mimi. Im Sommer fahren wir nach Ø Deutschland. Im Garten spielen Ø Kinder.*\n\nPoints attendus :\n- Métier après *sein* : pas d'article (*Er ist Lehrer*).\n- Nom de matière : pas d'article (*Kaffee*, « du café »).\n- La plupart des noms de pays : pas d'article (*nach Deutschland*).\n- *ein* n'a **pas de pluriel** : « des enfants » = *Kinder*.\n- *das Mädchen* est neutre (-chen) ; *die Schule*, *die Katze* féminins.\n\n**2.** Non : dans *Das ist meine Schwester*, *das* est un **démonstratif invariable** (« ça, c'est ma sœur »). Il ne s'accorde à rien, même si *Schwester* est féminin ; un article serait suivi d'un nom qu'il détermine."}$exo$::jsonb),
  ('38282da7-3f32-500b-b359-817b2db1001e'::uuid, 3, 'traduction', $exo${"titre":"Thème : genres et pièges","consigne":"Traduis les phrases en allemand, puis justifie trois de tes choix.","enonce":"**1. Traduis en allemand.**\n\n1. La jeune fille est ma cousine.\n2. Elle est étudiante.\n3. Le soleil brille, la lune est invisible.\n4. Une journée à Berlin coûte cher.\n5. Des enfants jouent dans la rue.\n6. Ça, c'est la solution !\n\n*Aide : Mädchen ; die Cousine ; die Studentin ; Sonne ; Mond ; scheinen ; unsichtbar ; Tag ; teuer sein ; auf der Straße ; Lösung.*\n\n**2.** Justifie en français : l'article de *Mädchen*, l'absence d'article devant *Studentin*, et l'article de *Lösung*.","bareme":[{"critere":"Genres justes : das Mädchen, die Sonne, der Mond, die Lösung","points":6},{"critere":"Absence d'article : métier après sein, indéfini pluriel","points":4},{"critere":"Das démonstratif invariable et ein Tag","points":3},{"critere":"Phrases correctes (verbe, accord, ordre)","points":2},{"critere":"Trois justifications justes","points":5}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Das Mädchen ist meine Cousine.*\n2. *Sie ist Studentin.*\n3. *Die Sonne scheint, der Mond ist unsichtbar.*\n4. *Ein Tag in Berlin ist teuer.*\n5. *Kinder spielen auf der Straße.*\n6. *Das ist die Lösung!*\n\nPoints attendus :\n- *die Sonne* (le soleil) et *der Mond* (la lune) : genres inverses du français.\n- *Sie ist Studentin* : pas d'article devant un métier ou un statut après *sein*.\n- « Des enfants » : pas d'article indéfini au pluriel.\n- *Das ist…* : démonstratif invariable.\n- *Sie* reprend *das Mädchen* : accepté aussi, car il s'agit d'une personne ; *es* est grammaticalement possible.\n\n**2.** *das Mädchen* : tous les diminutifs en *-chen* sont neutres. *Studentin* : après *sein*, un métier ou un statut s'emploie sans article (« elle est **une** étudiante » ne se dit pas). *die Lösung* : les noms en *-ung* sont féminins."}$exo$::jsonb),
  ('162db04f-4052-5182-9896-18fa726e8cdf'::uuid, 1, 'traduction', $exo${"titre":"Le bon cas, la bonne forme","consigne":"Complète avec la forme correcte du déterminant entre parenthèses.","enonce":"**Complète.**\n\n1. Ich sehe ___ (der) Mann.\n2. Ich helfe ___ (die) Frau.\n3. Ich gebe ___ (das) Kind ein Buch.\n4. Er kauft ___ (ein) Hund.\n5. Das ist das Auto ___ (der) Vater___.\n6. Wir spielen mit ___ (die, pluriel) Kinder___.","bareme":[{"critere":"Accusatifs justes (den, einen)","points":5},{"critere":"Datifs justes (der, dem, den)","points":8},{"critere":"Génitif des Vaters avec -s","points":4},{"critere":"-n du datif pluriel : Kindern","points":3}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *Ich sehe den Mann.* — COD masculin → accusatif *den*.\n2. *Ich helfe der Frau.* — *helfen* : datif féminin *der*.\n3. *Ich gebe dem Kind ein Buch.* — COI neutre → datif *dem*.\n4. *Er kauft einen Hund.* — COD masculin → *einen*.\n5. *Das ist das Auto des Vaters.* — complément du nom → génitif *des*, et le nom masculin prend *-s*.\n6. *Wir spielen mit den Kindern.* — *mit* + datif ; au datif pluriel, l'article est *den* **et** le nom prend *-n*.\n\nRappel : le masculin est le seul genre qui change entre nominatif et accusatif (*der → den*, *ein → einen*)."}$exo$::jsonb),
  ('162db04f-4052-5182-9896-18fa726e8cdf'::uuid, 2, 'traduction', $exo${"titre":"Possessifs et déterminants en der-","consigne":"Complète chaque phrase, puis indique le cas du groupe complété et sa fonction.","enonce":"**Complète, puis donne le cas et la fonction.**\n\n1. Ich besuche ___ (mein) Großvater.\n2. Ich schenke ___ (meine) Mutter Blumen.\n3. ___ (dieser) Film gefällt mir.\n4. Kennst du ___ (diese) Frau?\n5. ___ (jeder) Kind bekommt ein Geschenk.\n6. Ich spreche mit ___ (unsere, pluriel) Nachbarn.","bareme":[{"critere":"Formes justes des six déterminants","points":10},{"critere":"Cas et fonction correctement identifiés","points":6},{"critere":"Orthographe des terminaisons et des noms","points":4}],"dureeMin":11,"corrige":"**Réponses**\n\n1. *meinen Großvater* — accusatif, COD de *besuchen* ; le possessif se décline comme *ein* : *meinen*.\n2. *meiner Mutter* — datif, COI (on offre **à** sa mère).\n3. *Dieser Film* — nominatif, sujet de *gefällt*.\n4. *diese Frau* — accusatif, COD ; au féminin, accusatif = nominatif.\n5. *Jedes Kind* — nominatif, sujet ; *jeder* prend les terminaisons de l'article défini (*das* → *jedes*).\n6. *unseren Nachbarn* — datif pluriel après *mit* ; *unser* garde son e.\n\nRappel : *kein* et les possessifs se déclinent comme *ein* ; *dieser*, *jeder*, *welcher* comme l'article défini."}$exo$::jsonb),
  ('162db04f-4052-5182-9896-18fa726e8cdf'::uuid, 3, 'traduction', $exo${"titre":"Thème : les quatre cas en action","consigne":"Traduis les cinq phrases en allemand, puis indique le cas de chaque groupe nominal souligné.","enonce":"**1. Traduis en allemand.**\n\n1. Le frère de **mon amie** offre un livre à **son père**.\n2. Je n'ai pas de **voiture**.\n3. Nous parlons avec **les voisins**.\n4. **Chaque élève** connaît **ce professeur**.\n5. La maison de **la famille** est grande.\n\n*Aide : die Freundin ; schenken ; sein Vater ; das Auto ; der Nachbar (pluriel die Nachbarn) ; der Schüler ; der Lehrer ; die Familie.*\n\n**2.** Donne le cas des sept groupes en gras et justifie-le par leur fonction.","bareme":[{"critere":"Nominatifs et accusatifs justes (kein Auto, diesen Lehrer)","points":4},{"critere":"Datifs justes (seinem Vater, den Nachbarn)","points":5},{"critere":"Génitifs justes (meiner Freundin, der Familie)","points":5},{"critere":"Déterminants en der- et kein bien déclinés","points":3},{"critere":"Cas identifiés et justifiés par la fonction","points":3}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Der Bruder meiner Freundin schenkt seinem Vater ein Buch.*\n2. *Ich habe kein Auto.*\n3. *Wir sprechen mit den Nachbarn.*\n4. *Jeder Schüler kennt diesen Lehrer.*\n5. *Das Haus der Familie ist groß.*\n\n**2. Cas des groupes en gras**\n- *meiner Freundin* : **génitif** féminin, complément du nom *Bruder*.\n- *seinem Vater* : **datif**, COI de *schenken*.\n- *kein Auto* : **accusatif** neutre, COD (même forme qu'au nominatif).\n- *den Nachbarn* : **datif pluriel** après *mit* (le nom a déjà son -n).\n- *Jeder Schüler* : **nominatif**, sujet.\n- *diesen Lehrer* : **accusatif** masculin, COD — *dieser* prend les terminaisons de l'article.\n- *der Familie* : **génitif** féminin, complément du nom *Haus* ; au féminin, pas de marque sur le nom."}$exo$::jsonb),
  ('b0710f9c-ed06-5507-a596-aba67f5e00d7'::uuid, 1, 'traduction', $exo${"titre":"Remplacer par un pronom","consigne":"Remplace le groupe en gras par le pronom personnel qui convient.","enonce":"**Remplace le groupe en gras par un pronom.**\n\n1. **Der Tisch** ist alt.\n2. Ich sehe **den Lehrer**.\n3. Ich helfe **meiner Schwester**.\n4. **Die Lampe** ist neu.\n5. Wir danken **den Eltern**.\n6. Ich kaufe **das Buch**.","bareme":[{"critere":"Genre grammatical conservé (er pour der Tisch, sie pour die Lampe)","points":8},{"critere":"Cas juste : ihn, ihr, ihnen, es","points":8},{"critere":"Phrases correctement recopiées (majuscule, ordre)","points":4}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Er ist alt.* — *der Tisch* est masculin → *er*, même pour un objet.\n2. *Ich sehe ihn.* — masculin, COD → accusatif *ihn*.\n3. *Ich helfe ihr.* — féminin, *helfen* régit le datif → *ihr*.\n4. *Sie ist neu.* — *die Lampe* est féminin → *sie*.\n5. *Wir danken ihnen.* — pluriel, *danken* régit le datif → *ihnen*.\n6. *Ich kaufe es.* — neutre, COD → *es*.\n\nRègle : le pronom garde le **genre grammatical** du nom et prend le **cas** de sa fonction. Traduire mécaniquement une chose par *es* est une faute : en allemand, une table est « il »."}$exo$::jsonb),
  ('b0710f9c-ed06-5507-a596-aba67f5e00d7'::uuid, 2, 'traduction', $exo${"titre":"Deux pronoms dans la phrase","consigne":"Remplace les deux compléments par des pronoms (phrases 1 à 3), puis traduis les phrases 4 et 5.","enonce":"**Remplace les deux compléments par des pronoms.**\n\n1. Ich gebe dem Kind das Buch.\n2. Er schenkt seiner Mutter die Blumen.\n3. Wir zeigen den Gästen das Haus.\n\n**Traduis.**\n\n4. Hier, mon père m'a appelé. (*commence par Gestern ; anrufen*)\n5. Je vous remercie, Monsieur Braun. (*vouvoiement ; danken + datif*)","bareme":[{"critere":"Formes des pronoms justes (es, ihm, sie, ihr, ihnen, mich)","points":6},{"critere":"Ordre des deux pronoms : accusatif puis datif","points":6},{"critere":"Pronom placé juste après le verbe, avant le sujet nominal","points":4},{"critere":"Ihnen de politesse avec majuscule","points":4}],"dureeMin":10,"corrige":"1. *Ich gebe es ihm.*\n2. *Er schenkt sie ihr.*\n3. *Wir zeigen es ihnen.*\n4. *Gestern hat mich mein Vater angerufen.*\n5. *Ich danke Ihnen, Herr Braun.*\n\nPoints attendus :\n- Avec deux groupes nominaux, l'ordre est datif puis accusatif ; avec deux **pronoms**, c'est **accusatif puis datif** : *es ihm*, *sie ihr*, *es ihnen*. *Ich gebe ihm es* est faux.\n- *das Buch* → *es* ; *die Blumen* (pluriel) → *sie* ; *seiner Mutter* → *ihr* ; *den Gästen* → *ihnen*.\n- Phrase 4 : les pronoms remontent juste après le verbe conjugué ; en cas d'inversion, le pronom *mich* peut précéder le sujet nominal *mein Vater*.\n- Phrase 5 : *Sie* de politesse → datif *Ihnen*, toujours avec majuscule."}$exo$::jsonb),
  ('b0710f9c-ed06-5507-a596-aba67f5e00d7'::uuid, 3, 'traduction', $exo${"titre":"Une lettre à Anna","consigne":"Traduis la lettre en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Chère Anna, merci pour ta lettre ! Je l'ai lue hier. Mon frère te salue. Il a un nouveau vélo : il est rouge. Mes parents t'invitent : tu peux venir chez nous en été. Est-ce que tu veux leur écrire ?\n\n*Aide : Liebe Anna ; danke für + accusatif ; der Brief ; lesen (gelesen) ; grüßen ; ein neues Fahrrad ; einladen (séparable) ; zu uns ; im Sommer ; schreiben + datif.*\n\n**2.** Explique en français pourquoi « je **l'**ai lue » se traduit par *ihn* et « **il** est rouge » par *es*.","bareme":[{"critere":"Pronoms reprenant le genre du nom : ihn (Brief), es (Fahrrad)","points":5},{"critere":"Cas justes : dich, ihnen, uns","points":5},{"critere":"Place des pronoms et du préverbe ein en fin de phrase","points":3},{"critere":"Phrases correctes (verbes, possessifs, ponctuation)","points":3},{"critere":"Explication juste du choix ihn / es","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Liebe Anna, danke für deinen Brief! Ich habe ihn gestern gelesen. Mein Bruder grüßt dich. Er hat ein neues Fahrrad: Es ist rot. Meine Eltern laden dich ein: Du kannst im Sommer zu uns kommen. Willst du ihnen schreiben?*\n\nPoints attendus :\n- *deinen Brief* : *für* + accusatif, masculin.\n- *ihn* : reprend *der Brief* (masculin), COD → accusatif.\n- *dich* : COD de *grüßen* et de *einladen* ; le préverbe *ein* ferme la phrase.\n- *es* : reprend *das Fahrrad* (neutre), sujet.\n- *ihnen* : datif pluriel (« à eux »), COI de *schreiben* ; minuscule, car ce n'est pas le vouvoiement.\n- Majuscule au début de la phrase après les deux-points (*Es ist rot*, *Du kannst*) acceptée ou minuscule tolérée.\n\n**2.** Le pronom allemand garde le **genre grammatical** du nom qu'il remplace, pas celui du français. *Der Brief* (la lettre) est masculin : on le reprend par *ihn* à l'accusatif. *Das Fahrrad* (le vélo) est neutre : on le reprend par *es*."}$exo$::jsonb),
  ('266418d2-8561-5aa9-83e5-8849f1cd6332'::uuid, 1, 'traduction', $exo${"titre":"Dieser, et das ou dass","consigne":"Complète les phrases 1 à 5 avec la bonne forme de dieser, puis les phrases 6 et 7 avec das ou dass.","enonce":"**Complète avec dieser à la bonne forme.**\n\n1. ___ Mann ist mein Nachbar.\n2. Ich kenne ___ Frau nicht.\n3. Ich wohne in ___ Haus.\n4. Kaufst du ___ Rock? (*der Rock*)\n5. Das Auto ___ Mannes ist neu.\n\n**Complète avec das ou dass.**\n\n6. Ich glaube, ___ er kommt.\n7. ___ ist mein Bruder.","bareme":[{"critere":"Formes de dieser justes selon genre et cas","points":12},{"critere":"Choix juste entre das et dass","points":8}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Dieser Mann* — nominatif masculin.\n2. *diese Frau* — accusatif féminin.\n3. *in diesem Haus* — datif neutre (lieu où l'on est).\n4. *diesen Rock* — accusatif masculin.\n5. *dieses Mannes* — génitif masculin.\n6. *Ich glaube, dass er kommt.* — conjonction qui introduit une subordonnée.\n7. *Das ist mein Bruder.* — démonstratif invariable.\n\nPoints attendus : *dieser* se décline comme l'article défini (*der → dieser*, *den → diesen*, *dem → diesem*, *des → dieses*). Test pour *das* / *dass* : si l'on peut remplacer par *dieses*, c'est *das* avec un seul s ; sinon, c'est la conjonction *dass*."}$exo$::jsonb),
  ('266418d2-8561-5aa9-83e5-8849f1cd6332'::uuid, 2, 'traduction', $exo${"titre":"Celui-là, le même","consigne":"Réponds aux cinq questions.","enonce":"**Complète la réponse avec le démonstratif accentué.**\n\n1. — Kennst du Peter? — Ja, ___ kenne ich gut!\n2. — Magst du die Lehrerin? — Ja, ___ mag ich.\n3. — Hilfst du den Nachbarn? — Ja, ___ helfe ich gern.\n\n4. Réécris pour dire clairement qu'il s'agit du frère **de Paul** : *Ich traf Paul und seinen Bruder.*\n5. Traduis : « Nous habitons dans la même maison. » et « Elle a la même robe que moi. » Explique en une phrase pourquoi tu n'emploies pas le même mot.","bareme":[{"critere":"Démonstratifs accentués justes (den, die, denen)","points":6},{"critere":"Emploi de dessen pour lever l'ambiguïté","points":4},{"critere":"derselbe décliné et der gleiche employés à bon escient","points":6},{"critere":"Explication juste : identique ou semblable","points":4}],"dureeMin":10,"corrige":"1. *Den kenne ich gut!* — masculin, COD → *den*.\n2. *Die mag ich.* — féminin, COD → *die*.\n3. *Denen helfe ich gern.* — pluriel, *helfen* + datif → *denen* (forme propre au démonstratif).\n4. *Ich traf Paul und dessen Bruder.* — *dessen* désigne sans équivoque le frère de Paul (*seinen* pouvait renvoyer au sujet).\n5. *Wir wohnen in demselben Haus.* / *Sie hat das gleiche Kleid wie ich.*\n\nExplication : *derselbe* désigne un objet **identique**, unique (une seule maison) ; *der gleiche* désigne un objet **semblable** (deux robes pareilles). Dans *derselbe*, les deux morceaux se déclinent : *dem-* comme l'article (datif après *in*), *-selben* comme un adjectif faible."}$exo$::jsonb),
  ('266418d2-8561-5aa9-83e5-8849f1cd6332'::uuid, 3, 'traduction', $exo${"titre":"Dialogue dans la cour","consigne":"Traduis ce dialogue en allemand en employant les démonstratifs, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu vois ce garçon ?\n— Celui-là ? Je le connais : c'est le frère de Lisa.\n— Et la jeune fille à côté de lui ?\n— Celle-là, je ne la connais pas. Mais Lisa et sa sœur (la sœur de Lisa) habitent dans la même rue que moi.\n— Ce sont mes amies !\n\n*Aide : der Junge (accusatif den Jungen) ; das Mädchen ; neben + datif ; die Straße ; die Freundin.*\n\n**2.** Explique en français ton choix de *das* pour « celle-là » et de *deren* pour « sa sœur ».","bareme":[{"critere":"dieser et démonstratifs accentués justes (diesen, den, das)","points":5},{"critere":"deren pour lever l'ambiguïté sur la sœur","points":3},{"critere":"derselben Straße décliné au datif","points":3},{"critere":"Das sind … : verbe accordé avec ce qui suit","points":3},{"critere":"Justification de das et de deren","points":6}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n— *Siehst du diesen Jungen?*\n— *Den da? Den kenne ich: Das ist der Bruder von Lisa.* (*Lisas Bruder* accepté)\n— *Und das Mädchen neben ihm?*\n— *Das kenne ich nicht. Aber Lisa und deren Schwester wohnen in derselben Straße wie ich.*\n— *Das sind meine Freundinnen!*\n\nPoints attendus :\n- *diesen Jungen* : accusatif masculin ; *Den* : démonstratif accentué, masculin accusatif.\n- *Das ist…* et *Das sind…* : *das* invariable, le verbe s'accorde avec ce qui suit (*sind* devant un pluriel).\n- *in derselben Straße* : lieu où l'on est → datif, *der-* + *-selben*.\n- *neben ihm* : datif (localisation).\n\n**2.** *Das* : le démonstratif reprend le genre du nom ; *Mädchen* est **neutre**, donc *das* à l'accusatif, même s'il s'agit d'une fille. *deren* : génitif féminin du démonstratif, il renvoie sans équivoque à Lisa ; *ihre Schwester* serait possible mais moins précis dans une phrase à plusieurs personnes. C'est un usage soigné, apprécié à l'écrit."}$exo$::jsonb),
  ('9ee758be-1ff5-5fa7-8b51-d320d3ad0eab'::uuid, 1, 'traduction', $exo${"titre":"Huit pluriels","consigne":"Donne le pluriel de chaque nom avec son article, puis indique pour trois d'entre eux le schéma de pluriel.","enonce":"**1. Donne le pluriel avec l'article.**\n\nder Tag · das Kind · die Frau · der Lehrer · das Auto · die Lehrerin · der Sohn · das Buch\n\n**2.** Pour *Frau*, *Lehrer* et *Auto*, nomme le schéma de pluriel (terminaison ajoutée ou absence de terminaison).","bareme":[{"critere":"Huit pluriels justes, Umlaut compris","points":14},{"critere":"Article die au pluriel pour tous les noms","points":2},{"critere":"Schémas justes pour les trois noms","points":4}],"dureeMin":6,"corrige":"**1. Pluriels**\n\n- *die Tage* (-e)\n- *die Kinder* (-er)\n- *die Frauen* (-en)\n- *die Lehrer* (aucune terminaison)\n- *die Autos* (-s)\n- *die Lehrerinnen* (-nen : le n est doublé)\n- *die Söhne* (-e avec Umlaut)\n- *die Bücher* (-er avec Umlaut)\n\nAu pluriel, l'article défini est **die** pour les trois genres.\n\n**2.** *Frau* : schéma en **-(e)n**, celui de presque tous les féminins, sans inflexion. *Lehrer* : **aucune terminaison** (masculin en -er). *Auto* : **-s**, schéma des emprunts et abréviations."}$exo$::jsonb),
  ('9ee758be-1ff5-5fa7-8b51-d320d3ad0eab'::uuid, 2, 'traduction', $exo${"titre":"Tout au pluriel","consigne":"Mets chaque phrase entièrement au pluriel (sujet, verbe et complément).","enonce":"**Mets au pluriel.**\n\n1. Das Kind spielt mit dem Ball.\n2. Die Zeitung liegt auf dem Tisch.\n3. Der Lehrer spricht mit der Schülerin.\n4. Das Auto steht vor dem Haus.\n\n*Aide : der Ball → die Bälle ; der Tisch → die Tische ; das Haus → die Häuser ; die Schülerin → die Schülerinnen.*","bareme":[{"critere":"Pluriels des noms justes","points":8},{"critere":"-n du datif pluriel ajouté, sauf après -s (Autos)","points":6},{"critere":"Verbes accordés et articles die / den justes","points":6}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Die Kinder spielen mit den Bällen.*\n2. *Die Zeitungen liegen auf den Tischen.*\n3. *Die Lehrer sprechen mit den Schülerinnen.*\n4. *Die Autos stehen vor den Häusern.*\n\nPoints attendus :\n- Sujets au pluriel avec *die* : *Kinder*, *Zeitungen*, *Lehrer* (sans terminaison), *Autos*.\n- Verbes à la 3e personne du pluriel : *spielen*, *liegen*, *sprechen*, *stehen*.\n- Datif pluriel : article *den*, et le nom prend **-n** s'il n'en a pas déjà un : *Bällen*, *Tischen*, *Häusern* ; *Schülerinnen* et *Zeitungen* finissent déjà par n.\n- Exception : pas de -n après un pluriel en -s (*mit den Autos*)."}$exo$::jsonb),
  ('9ee758be-1ff5-5fa7-8b51-d320d3ad0eab'::uuid, 3, 'traduction', $exo${"titre":"Thème : singuliers et pluriels trompeurs","consigne":"Traduis les phrases en allemand, puis explique trois pièges.","enonce":"**1. Traduis en allemand.**\n\n1. Mon père porte des lunettes.\n2. Les enfants jouent avec les chats des voisins.\n3. La police arrive avec deux voitures.\n4. Les fruits sont frais.\n5. Les gens sont gentils.\n\n*Aide : tragen ; die Katze ; der Nachbar (pluriel die Nachbarn) ; kommen ; das Auto ; frisch ; nett.*\n\n**2.** Explique en français les trois pièges des phrases 1, 3 et 4.","bareme":[{"critere":"eine Brille et das Obst au singulier, verbe accordé","points":5},{"critere":"Pluriels justes : Kinder, Katzen, Nachbarn, Autos, Leute","points":5},{"critere":"Datif pluriel et génitif pluriel corrects","points":4},{"critere":"Explication des trois pièges","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Mein Vater trägt eine Brille.*\n2. *Die Kinder spielen mit den Katzen der Nachbarn.*\n3. *Die Polizei kommt mit zwei Autos.*\n4. *Das Obst ist frisch.*\n5. *Die Leute sind nett.*\n\nPoints attendus :\n- *mit den Katzen* : datif pluriel (le nom finit déjà par n) ; *der Nachbarn* : génitif pluriel (article *der*).\n- *die Leute* n'existe qu'au pluriel : verbe *sind*.\n- *die Polizei* est un singulier : verbe *kommt*.\n\n**2. Les pièges**\n- Phrase 1 : l'allemand met au **singulier** ce que le français met au pluriel : « des lunettes » = *eine Brille*.\n- Phrase 3 : *Autos* est un pluriel en -s : au datif pluriel, il ne prend **pas** de -n (*mit zwei Autos*).\n- Phrase 4 : *das Obst* n'existe qu'au singulier : « les fruits sont » → *das Obst ist*."}$exo$::jsonb),
  ('6c6f48ea-0623-58c4-9295-b3d68b0afcf9'::uuid, 1, 'traduction', $exo${"titre":"L'attribut ne bouge pas","consigne":"Corrige l'erreur de chaque phrase, puis réponds à la question 2.","enonce":"**1. Corrige chaque phrase.**\n\n1. Die Frau ist alte.\n2. Das Wetter ist schönes.\n3. Die Kinder sind müden.\n4. Das Haus wird großes.\n5. Er singt schöne.\n\n**2.** Dans *Ein alter Mann ist gekommen* et *Der Mann ist alt*, pourquoi l'adjectif n'a-t-il pas la même forme ?","bareme":[{"critere":"Cinq phrases corrigées avec l'adjectif à sa forme nue","points":12},{"critere":"Explication juste : épithète déclinée, attribut invariable","points":8}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Die Frau ist alt.*\n2. *Das Wetter ist schön.*\n3. *Die Kinder sind müde.* (*müde* se termine déjà par e : c'est sa forme nue)\n4. *Das Haus wird groß.*\n5. *Er singt schön.* — ici, *schön* est un **adverbe** : l'allemand n'a pas de terminaison d'adverbe, le mot reste invariable.\n\nAprès *sein*, *werden* et *bleiben*, l'adjectif attribut reste à sa forme nue : ni -e, ni -er, rien.\n\n**2.** Tout dépend de la **place** de l'adjectif. Dans *Ein alter Mann*, il est **épithète** (devant le nom) : il se décline toujours. Dans *Der Mann ist alt*, il est **attribut** (après le verbe *sein*) : il ne se décline jamais."}$exo$::jsonb),
  ('6c6f48ea-0623-58c4-9295-b3d68b0afcf9'::uuid, 2, 'traduction', $exo${"titre":"Thème : attributs et adverbes","consigne":"Traduis les cinq phrases en allemand.","enonce":"**Traduis en allemand.**\n\n1. La maison est grande et belle.\n2. Ma sœur devient impatiente.\n3. Il chante bien.\n4. Je trouve ce film intéressant.\n5. Le train est plus rapide que la voiture.\n\n*Aide : das Haus ; ungeduldig ; singen ; schön ; der Film ; interessant ; der Zug ; schnell ; das Auto.*","bareme":[{"critere":"Adjectifs attributs invariables après sein et werden","points":8},{"critere":"Adverbe invariable (schön ou gut)","points":3},{"critere":"finden + COD + attribut invariable","points":4},{"critere":"Comparatif en -er suivi de als","points":5}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Das Haus ist groß und schön.*\n2. *Meine Schwester wird ungeduldig.*\n3. *Er singt schön.* (*gut* accepté)\n4. *Ich finde diesen Film interessant.*\n5. *Der Zug ist schneller als das Auto.*\n\nPoints attendus :\n- Phrases 1 et 2 : l'attribut ne s'accorde pas, même au féminin (*ungeduldig*, pas *ungeduldige*).\n- Phrase 3 : l'allemand n'a pas de terminaison d'adverbe comme -ment : le même mot sert d'adjectif et d'adverbe.\n- Phrase 4 : *finden* + COD appelle un attribut, invariable ; *diesen Film* à l'accusatif.\n- Phrase 5 : la terminaison -er est la marque du **comparatif**, pas un accord ; « que » = *als*."}$exo$::jsonb),
  ('6c6f48ea-0623-58c4-9295-b3d68b0afcf9'::uuid, 3, 'traduction', $exo${"titre":"Le portrait de Klara","consigne":"À partir de la fiche, écris le portrait de Klara en six phrases. Emploie les adjectifs comme attributs (après sein, werden, bleiben) et au moins un comparatif. Puis réponds à la question 2.","enonce":"**1. Écris le portrait (six phrases).**\n\n**Fiche de Klara**\n- ta meilleure amie, 15 ans\n- grande et sportive\n- parfois impatiente\n- reste calme pendant les examens\n- chante bien\n- plus rapide que son frère\n\n*Aide : groß ; sportlich ; ungeduldig ; ruhig ; die Prüfung ; singen ; schnell ; der Bruder.*\n\n**2.** Un camarade écrit *Klara ist große*. Explique-lui son erreur en français.","bareme":[{"critere":"Attributs invariables après sein et bleiben","points":7},{"critere":"Adverbe invariable pour chanter","points":2},{"critere":"Comparatif avec als correct","points":3},{"critere":"Phrases correctes : verbe en 2e position, inversion","points":4},{"critere":"Explication juste de l'erreur","points":4}],"dureeMin":15,"corrige":"**1. Portrait modèle**\n\n*Meine beste Freundin heißt Klara. Sie ist fünfzehn Jahre alt. Sie ist groß und sportlich. Manchmal ist sie ungeduldig, aber in den Prüfungen bleibt sie ruhig. Sie singt schön. Sie ist schneller als ihr Bruder.*\n\nPoints attendus :\n- *groß*, *sportlich*, *ungeduldig*, *ruhig* : attributs après *sein* ou *bleiben* → forme nue, sans terminaison.\n- *singt schön* (ou *gut*) : adverbe invariable.\n- *schneller als* : comparatif en -er + *als*.\n- Inversion après *Manchmal* et *in den Prüfungen* (verbe en 2e position).\n- *Meine beste Freundin* : épithète déclinée devant le nom, acceptée.\n\n**2.** Après *sein*, l'adjectif est **attribut** : il ne se décline jamais, même quand le sujet est féminin. Il faut écrire *Klara ist groß*. La terminaison n'apparaît que si l'adjectif est placé **devant** le nom (*eine große Freundin*)."}$exo$::jsonb),
  ('d237ec84-6d70-59d7-b4b7-68458884de22'::uuid, 1, 'traduction', $exo${"titre":"Les terminaisons de l'épithète","consigne":"Complète la terminaison de chaque adjectif.","enonce":"**Complète la terminaison (nominatif sauf indication).**\n\n1. der alt__ Mann\n2. ein alt__ Mann\n3. ein alt__ Haus\n4. mit dem neu__ Auto\n5. kalt__ Kaffee (sans déterminant)\n6. eine schön__ Blume\n\n*Rappel : der Mann, das Haus, das Auto, der Kaffee, die Blume.*","bareme":[{"critere":"Déclinaison faible après der / dem (-e, -en)","points":6},{"critere":"Déclinaison mixte après ein / eine (-er, -es, -e)","points":8},{"critere":"Déclinaison forte sans déterminant (-er)","points":6}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *der alte Mann* — faible : *der* marque déjà le cas → -e.\n2. *ein alter Mann* — mixte : *ein* ne marque pas le masculin → l'adjectif prend -er.\n3. *ein altes Haus* — mixte : *ein* ne marque pas le neutre → -es.\n4. *mit dem neuen Auto* — faible au datif → -en.\n5. *kalter Kaffee* — forte : aucun déterminant, l'adjectif prend la marque de l'article (*der* → -er).\n6. *eine schöne Blume* — *eine* marque déjà le féminin → terminaison faible -e.\n\nPrincipe : la marque du cas apparaît **une fois** dans le groupe ; si le déterminant la porte, l'adjectif se contente de -e ou -en."}$exo$::jsonb),
  ('d237ec84-6d70-59d7-b4b7-68458884de22'::uuid, 2, 'traduction', $exo${"titre":"Le nouvel ami","consigne":"Complète les terminaisons du texte, puis justifie deux de tes choix.","enonce":"**1. Complète les terminaisons.**\n\n> Ich habe einen neu__ Freund. Er wohnt in einem groß__ Haus mit einem schön__ Garten. Sein klein__ Bruder spielt mit einem rot__ Ball. Er hat ein teu__ Fahrrad (*teuer*). Morgen fahren wir mit dem neu__ Zug nach Berlin.\n\n*Rappel : der Freund, das Haus, der Garten, der Bruder, der Ball, das Fahrrad, der Zug.*\n\n**2.** Justifie en français la terminaison de *klein__ Bruder* et celle de *teu__ Fahrrad*.","bareme":[{"critere":"Terminaisons -en justes à l'accusatif et au datif","points":8},{"critere":"Nominatif masculin après sein : kleiner","points":3},{"critere":"Forme teures, sans le e de teuer","points":3},{"critere":"Faible après dem : neuen","points":3},{"critere":"Deux justifications justes","points":3}],"dureeMin":11,"corrige":"**1. Texte complété**\n\n> *Ich habe einen neuen Freund. Er wohnt in einem großen Haus mit einem schönen Garten. Sein kleiner Bruder spielt mit einem roten Ball. Er hat ein teures Fahrrad. Morgen fahren wir mit dem neuen Zug nach Berlin.*\n\nPoints attendus :\n- *einen neuen* (accusatif masculin), *einem großen*, *einem schönen*, *einem roten* (datif) : le déterminant marque le cas → -en.\n- *dem neuen Zug* : déclinaison faible au datif → -en.\n\n**2.** *kleiner Bruder* : *Bruder* est masculin et sujet (nominatif) ; le possessif *sein* se décline comme *ein* et ne marque rien au nominatif masculin → l'adjectif prend la marque -er. *teures Fahrrad* : *Fahrrad* est neutre, COD (accusatif) ; *ein* ne marque pas le neutre → -es ; et *teuer* perd son e devant la terminaison : *teures*, jamais *teueres*."}$exo$::jsonb),
  ('d237ec84-6d70-59d7-b4b7-68458884de22'::uuid, 3, 'traduction', $exo${"titre":"Thème : le vieil homme de la montagne","consigne":"Traduis le texte en allemand, puis explique ta méthode pour deux groupes nominaux.","enonce":"**1. Traduis en allemand.**\n\n> Un vieil homme habite dans une petite maison au pied d'une haute montagne. Il boit du café froid et mange du bon pain. Sa fille porte une robe rose. Le vieil homme aime les longues promenades.\n\n*Aide : alt ; klein ; am Fuß + génitif ; hoch ; der Berg ; kalt ; gut ; das Brot ; die Tochter ; tragen ; rosa ; das Kleid ; lang ; der Spaziergang (pluriel die Spaziergänge) ; lieben.*\n\n**2.** Explique en français comment tu as trouvé la terminaison de *kalt…* devant *Kaffee* et la forme de *hoch* devant *Berg*.","bareme":[{"critere":"Déclinaisons mixte et faible justes (alter, kleinen, alte)","points":5},{"critere":"Déclinaison forte sans déterminant (kalten, gutes, lange)","points":5},{"critere":"Irréguliers et invariables : hohen, rosa","points":4},{"critere":"Méthode expliquée : cas et genre, puis déterminant","points":6}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *Ein alter Mann wohnt in einem kleinen Haus am Fuß eines hohen Berges. Er trinkt kalten Kaffee und isst gutes Brot. Seine Tochter trägt ein rosa Kleid. Der alte Mann liebt lange Spaziergänge.*\n\nPoints attendus :\n- *ein alter Mann* (nominatif, mixte) ; *einem kleinen Haus* (datif) ; *eines hohen Berges* (génitif) ; *der alte Mann* (faible).\n- *kalten Kaffee*, *gutes Brot*, *lange Spaziergänge* : aucun déterminant → déclinaison forte, terminaisons de l'article défini (*den*, *das*, *die*).\n- *hoch* perd son c : *hohen*.\n- *rosa* est invariable : *ein rosa Kleid*.\n- *an einem hohen Berg* accepté pour « au pied de ».\n\n**2.** Méthode : repérer d'abord le **cas et le genre**, puis regarder le déterminant. *Kaffee* est masculin, COD → accusatif ; il n'y a aucun déterminant, donc l'adjectif porte la marque de l'article *den* → *kalten*. *Berg* est masculin, au génitif après *eines*, qui marque déjà le cas → terminaison -en ; et *hoch* perd son c devant une terminaison → *hohen*."}$exo$::jsonb),
  ('18775db1-3692-52d7-8375-cfe759b34716'::uuid, 1, 'traduction', $exo${"titre":"Sein ou ihr ?","consigne":"Complète chaque phrase avec le possessif qui convient, bien décliné, puis réponds à la question 2 en français.","enonce":"**1. Complète avec le possessif.**\n\n1. Anna besucht ___ Großmutter. *(sa grand-mère, à elle)*\n2. Peter ruft ___ Vater an. *(son père, à lui — accusatif)*\n3. Das Kind spielt mit ___ Hund. *(son chien — datif)*\n4. Wir fahren mit ___ Auto. *(notre voiture — datif, das Auto)*\n5. Die Kinder und ___ Eltern kommen heute. *(leurs parents)*\n6. Herr Klein, ist das ___ Buch? *(votre livre, politesse)*\n\n**2.** Explique en une ou deux phrases pourquoi on écrit *ihre* dans la phrase 1 et *seinen* dans la phrase 2.","bareme":[{"critere":"Radical juste selon le possesseur : ihr- (1, 5), sein- (2, 3), unser- (4), Ihr- avec majuscule (6)","points":8},{"critere":"Terminaisons justes selon l'objet possédé : ihre, seinen, seinem, unserem, ihre, Ihr","points":8},{"critere":"Explication : radical commandé par le possesseur, terminaison par le genre et le cas du nom","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Anna besucht **ihre** Großmutter. — possesseur féminin (Anna) → *ihr-* ; *Großmutter* féminin → *-e*.\n2. Peter ruft **seinen** Vater an. — possesseur masculin → *sein-* ; *Vater* masculin à l'accusatif → *-en*.\n3. Das Kind spielt mit **seinem** Hund. — *Kind* est neutre → *sein-* ; *mit* + datif masculin → *-em*.\n4. Wir fahren mit **unserem** Auto. — *unser* garde son e ; datif neutre → *-em*.\n5. Die Kinder und **ihre** Eltern kommen heute. — *ihr* = leur ; pluriel nominatif → *-e*.\n6. Herr Klein, ist das **Ihr** Buch? — vouvoiement → *Ihr* avec majuscule ; *Buch* neutre nominatif → pas de terminaison.\n\n**2.** Le **radical** dépend du **possesseur** : Anna est une femme → *ihr-*, Peter est un homme → *sein-*. La **terminaison** dépend du **nom possédé** : *Großmutter* est féminin → *ihre* ; *Vater* est masculin et COD (accusatif) → *seinen*. Le possessif se décline comme *ein* / *kein*."}$exo$::jsonb),
  ('18775db1-3692-52d7-8375-cfe759b34716'::uuid, 2, 'traduction', $exo${"titre":"Léna présente sa famille","consigne":"Léna prépare une présentation de sa famille pour son correspondant allemand. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Mon frère et sa copine habitent à Berlin.\n2. Ma sœur aime son chat.\n3. Nos voisins et leur fils viennent ce soir.\n4. Les enfants, où est votre professeur ?\n5. Les enfants, j'ai vu votre mère.\n6. Le matin, je me lave les mains.\n\n*Aide : die Freundin = la copine ; die Katze = le chat ; der Nachbar, die Nachbarn = le voisin ; der Sohn = le fils ; der Lehrer = le professeur ; ich habe … gesehen = j'ai vu ; heute Abend = ce soir ; morgens = le matin ; waschen = laver.*\n\n**2.** Dans les phrases 4 et 5, le possessif change de forme. Explique pourquoi.","bareme":[{"critere":"Radical sein- / ihr- choisi selon le possesseur (phrases 1, 2, 3)","points":6},{"critere":"Terminaisons justes selon le genre et le cas : seine, ihre, ihr Sohn, euer, eure","points":6},{"critere":"Phrase 6 construite avec le datif et l'article : mir die Hände","points":4},{"critere":"Explication : euer devient eur- devant une terminaison","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Mein Bruder und **seine** Freundin wohnen in Berlin.* — possesseur masculin → *sein-* ; *Freundin* féminin → *-e*.\n2. *Meine Schwester liebt **ihre** Katze.* — possesseur féminin → *ihr-* ; *Katze* féminin accusatif → *-e*.\n3. *Unsere Nachbarn und **ihr** Sohn kommen heute Abend.* — *ihr* = leur ; *Sohn* masculin nominatif → pas de terminaison.\n4. *Kinder, wo ist **euer** Lehrer?* — *euer* sans terminaison (masculin nominatif).\n5. *Kinder, ich habe **eure** Mutter gesehen.* — *Mutter* féminin → terminaison *-e* → *eure*.\n6. *Morgens wasche ich **mir die** Hände.* (ou *Ich wasche mir morgens die Hände.*) — avec les parties du corps, l'allemand emploie l'article + un datif, pas le possessif.\n\n**2.** *euer* perd son second e dès qu'il reçoit une terminaison : *euer Lehrer* (pas de terminaison) mais *eure Mutter*, *euren Vater*. À l'inverse, *unser* garde son e : *unsere Nachbarn*."}$exo$::jsonb),
  ('18775db1-3692-52d7-8375-cfe759b34716'::uuid, 3, 'traduction', $exo${"titre":"Le texte de Sophie à corriger","consigne":"Lis le texte de Sophie, corrige ses fautes en justifiant, puis traduis les phrases de la question 3.","enonce":"**Document — Sophie parle de son frère Paul**\n\n> Mein Bruder Paul hat einen Hund. Ihr Hund heißt Rex. Paul spielt jeden Tag mit sein Hund. Nach dem Spiel wasche ich meine Hände. Meine Eltern und ihre Freunde kommen am Samstag. „Ist das dein Ball?“ – „Nein, das ist nicht mein, das ist Pauls Ball.“\n\n1. Le texte contient **quatre** fautes sur le possessif. Relève-les, corrige-les et justifie chaque correction.\n2. Un camarade pense que *ihre Freunde* est aussi une faute. A-t-il raison ? Explique.\n3. Traduis en allemand :\n   - a. Julia et son frère aiment leur chien.\n   - b. — À qui est ce livre ? — C'est le mien.\n\n*Aide : der Ball ; das Buch ; lieben = aimer.*","bareme":[{"critere":"Les quatre fautes relevées et corrigées : Sein Hund, seinem Hund, mir die Hände, meiner","points":8},{"critere":"Justifications : possesseur, datif après mit, tournure article + datif, possessif employé seul","points":4},{"critere":"ihre Freunde reconnu correct : ihr = leur, pluriel","points":3},{"critere":"Traductions justes : ihr Bruder, ihren Hund, Wessen, meins","points":5}],"dureeMin":16,"corrige":"**1. Les quatre fautes**\n- *Ihr Hund* → **Sein Hund** : le possesseur est Paul, un homme → radical *sein-*.\n- *mit sein Hund* → **mit seinem Hund** : *mit* impose le datif ; *Hund* masculin → *-em*.\n- *wasche ich meine Hände* → **wasche ich mir die Hände** : avec les parties du corps, l'allemand n'emploie pas le possessif mais l'article + un pronom au datif.\n- *das ist nicht mein* → **das ist nicht meiner** : employé seul, le possessif prend les terminaisons de l'article défini ; *Ball* est masculin (*der*) → *meiner*.\n\n**2.** Non. *ihre Freunde* est correct : *ihr* signifie ici **leur** (les amis de mes parents), et *Freunde* est un pluriel → terminaison *-e*.\n\n**3.**\n- a. *Julia und **ihr** Bruder lieben **ihren** Hund.* — Julia est une femme → *ihr Bruder* ; « leur chien » → *ihr-*, *Hund* masculin accusatif → *ihren*.\n- b. *— **Wessen** Buch ist das? — Das ist **meins** (meines).* — *Buch* neutre (*das*) → possessif seul *mein(e)s*."}$exo$::jsonb),
  ('a19abf9f-293c-5125-807c-ea04a842e199'::uuid, 1, 'traduction', $exo${"titre":"À qui est-ce ?","consigne":"Transforme chaque groupe avec von en génitif, puis réponds à la question 2 par une phrase complète.","enonce":"**1. Transforme au génitif.** Utilise le génitif saxon pour les noms propres, le génitif ordinaire pour les autres.\n\n1. das Auto von Peter\n2. das Fahrrad von Anna\n3. das Haus von dem Vater\n4. die Tasche von der Lehrerin\n5. das Zimmer von dem Kind\n6. die Spielsachen von den Kindern\n\n**2.** Pose la question qui correspond à « à qui est ce cahier ? » en allemand, puis réponds que c'est le cahier de Maria. *(das Heft = le cahier)*","bareme":[{"critere":"Génitif saxon sans article ni apostrophe : Peters Auto, Annas Fahrrad","points":5},{"critere":"Masculin et neutre : des + nom en -(e)s (des Vaters, des Kindes)","points":6},{"critere":"Féminin et pluriel : der sans marque sur le nom (der Lehrerin, der Kinder)","points":5},{"critere":"Question avec Wessen et réponse Marias Heft","points":4}],"dureeMin":6,"corrige":"**1.**\n1. **Peters Auto** — nom propre placé devant, -s sans apostrophe, aucun article.\n2. **Annas Fahrrad**\n3. **das Haus des Vaters** — masculin : article *des*, le nom prend *-s*.\n4. **die Tasche der Lehrerin** — féminin : article *der*, aucune marque sur le nom.\n5. **das Zimmer des Kindes** — neutre : *des*, le nom prend *-es* (ou *des Kinds*, plus rare).\n6. **die Spielsachen der Kinder** — pluriel : *der*, aucune marque.\n\n**2.** *Wessen Heft ist das?* — *Das ist **Marias** Heft.* (*Wessen?* = de qui ?, la question du génitif.)"}$exo$::jsonb),
  ('a19abf9f-293c-5125-807c-ea04a842e199'::uuid, 2, 'traduction', $exo${"titre":"Les vacances de Tom","consigne":"Complète le récit de Tom avec la préposition qui convient et l'article au génitif, puis traduis les groupes de la question 2.","enonce":"**1. Complète avec *wegen, trotz, während* ou *statt*, et l'article au génitif.**\n\n1. ___ d__ Ferien fahre ich nach Hamburg. *(pendant)*\n2. ___ d__ Regens spielen wir Fußball. *(malgré)*\n3. ___ d__ Sturms bleibt das Museum geschlossen. *(à cause de — der Sturm)*\n4. ___ ein__ Kaffees trinke ich einen Tee. *(au lieu de)*\n5. Das Haus mein__ Großmutter liegt außerhalb d__ Stadt.\n\n**2.** Traduis chaque groupe de deux façons : **a.** le vélo de Lisa ; **b.** la voiture de mon père. Pour chaque groupe, indique laquelle des deux formes est la plus soignée, à l'écrit.","bareme":[{"critere":"Prépositions justes : Während, Trotz, Wegen, Statt","points":6},{"critere":"Articles et noms au génitif justes : der Ferien, des Regens, des Sturms, eines Kaffees, meiner, der Stadt","points":6},{"critere":"Deux traductions justes de chaque groupe (génitif et von + datif)","points":5},{"critere":"Registre identifié : le génitif est plus soigné que von + datif","points":3}],"dureeMin":10,"corrige":"**1.**\n1. **Während der** Ferien fahre ich nach Hamburg. — *Ferien* est un pluriel → *der*.\n2. **Trotz des** Regens spielen wir Fußball. — masculin → *des Regens*.\n3. **Wegen des** Sturms bleibt das Museum geschlossen.\n4. **Statt eines** Kaffees trinke ich einen Tee. — masculin → *eines*, nom en *-s*.\n5. Das Haus **meiner** Großmutter liegt außerhalb **der** Stadt. — féminin → *meiner*, *der*.\n\n**2.**\n- a. *Lisas Fahrrad* (génitif saxon, courant pour un nom propre) / *das Fahrrad von Lisa* (oral, plus relâché). La forme la plus soignée : **Lisas Fahrrad**.\n- b. *das Auto meines Vaters* (génitif ordinaire) / *das Auto von meinem Vater* (von + datif). La forme la plus soignée : **das Auto meines Vaters**.\n\nLe génitif recule à l'oral mais reste la marque d'un écrit soigné ; *von* + datif est la tournure parlée."}$exo$::jsonb),
  ('a19abf9f-293c-5125-807c-ea04a842e199'::uuid, 3, 'traduction', $exo${"titre":"Réécrire en allemand soigné","consigne":"Réécris le texte de Lena dans un allemand écrit soigné, explique tes choix, puis écris trois phrases à ton sujet.","enonce":"**Document — Le message de Lena, écrit comme on parle**\n\n> Wegen dem Regen feiern wir im Haus von meiner Tante. Das Geschenk von meinem Bruder ist toll. Trotz dem Wetter kommen alle Freunde von Lena. Das Auto von Paul steht vor der Tür.\n\n1. Réécris les quatre phrases en remplaçant chaque tournure orale par le **génitif** (génitif ordinaire ou génitif saxon selon le cas).\n2. Explique pourquoi un correcteur remarque ces transformations.\n3. Écris **trois phrases** sur ta vie (école, loisirs, famille) : une avec *während*, une avec *wegen*, une avec un génitif saxon.\n\n*Aide : das Wetter = le temps ; das Geschenk = le cadeau.*","bareme":[{"critere":"Prépositions wegen et trotz suivies du génitif : des Regens, des Wetters","points":6},{"critere":"Compléments du nom au génitif : meiner Tante, meines Bruders, Lenas Freunde, Pauls Auto","points":6},{"critere":"Explication : le génitif marque un niveau de langue écrit et soigné","points":3},{"critere":"Trois phrases correctes avec während, wegen et un génitif saxon","points":5}],"dureeMin":15,"corrige":"**1. Texte réécrit**\n\n> *Wegen **des Regens** feiern wir im Haus **meiner Tante**. Das Geschenk **meines Bruders** ist toll. Trotz **des Wetters** kommen alle **Freunde Lenas** (ou : **Lenas Freunde**). **Pauls Auto** steht vor der Tür.*\n\n- *wegen* et *trotz* régissent le génitif à l'écrit : *des Regens*, *des Wetters* (masculin / neutre → *des* + *-s*).\n- *meiner Tante* : féminin → *meiner*, sans marque sur le nom.\n- *meines Bruders* : masculin → *meines*, nom en *-s*.\n- Noms propres : génitif saxon devant le nom, sans article ni apostrophe (*Pauls Auto*, *Lenas Freunde*).\n\n**2.** Le génitif recule dans l'allemand parlé (on dit *wegen dem*, *von meinem*), mais il reste un **marqueur de niveau de langue** : à l'écrit, il montre qu'on maîtrise la langue soignée.\n\n**3. Exemple de réponse**\n- *Während der Woche habe ich viel Arbeit.*\n- *Wegen des Tests lerne ich heute Abend.*\n- *Am Samstag spiele ich mit Maxims Ball.*\n\nToute phrase correcte avec *während* + génitif, *wegen* + génitif et un nom propre + *-s* devant le nom est acceptée."}$exo$::jsonb),
  ('c7f2ae97-5e40-5df3-992c-062113c88dd9'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus vieux, meilleur","consigne":"Complète chaque phrase avec le comparatif de l'adjectif entre parenthèses, puis corrige la phrase de la question 2.","enonce":"**1. Complète.**\n\n1. Berlin ist ___ als München. *(groß)*\n2. Mein Bruder ist ___ als ich. *(alt)*\n3. Das Buch ist ___ als der Film. *(interessant)*\n4. Heute ist es ___ als gestern. *(warm)*\n5. Mein Deutsch ist ___ als mein Englisch. *(gut)*\n6. Ich trinke ___ Tee als Kaffee. *(gern)*\n7. Anna ist so ___ wie Lisa. *(groß)*\n\n**2.** Corrige la phrase suivante et explique ta correction : *Tom ist größer wie Paul.*","bareme":[{"critere":"Comparatifs réguliers en -er avec Umlaut : größer, älter, interessanter, wärmer","points":8},{"critere":"Irréguliers justes : besser, lieber","points":4},{"critere":"als après un comparatif, so… wie pour l'égalité, faute de la question 2 corrigée et expliquée","points":8}],"dureeMin":6,"corrige":"**1.**\n1. Berlin ist **größer** als München.\n2. Mein Bruder ist **älter** als ich.\n3. Das Buch ist **interessanter** als der Film. — adjectif long, mais toujours *-er*, jamais « mehr interessant ».\n4. Heute ist es **wärmer** als gestern.\n5. Mein Deutsch ist **besser** als mein Englisch. — *gut → besser*.\n6. Ich trinke **lieber** Tee als Kaffee. — *gern → lieber* : je préfère le thé au café.\n7. Anna ist so **groß** wie Lisa. — égalité : l'adjectif ne change pas.\n\n**2.** *Tom ist größer **als** Paul.* Après un comparatif, le second terme est introduit par **als** ; *wie* ne s'emploie qu'après *so* (égalité)."}$exo$::jsonb),
  ('c7f2ae97-5e40-5df3-992c-062113c88dd9'::uuid, 2, 'traduction', $exo${"titre":"Deux vélos à comparer","consigne":"Noah hésite entre deux vélos. À partir du tableau, écris les phrases demandées en allemand.","enonce":"**Document — Les deux vélos**\n\n| | Rad X | Rad Y |\n| Prix | 400 € | 400 € |\n| Poids | 14 kg | 10 kg |\n| Âge | 3 ans | 1 an |\n| Vitesse | 25 km/h | 30 km/h |\n\n1. Écris **quatre phrases** de comparaison : une sur le prix, une sur le poids, une sur l'âge, une sur la vitesse.\n2. Noah préfère le Rad Y : écris-le avec *lieber*.\n3. Les vélos coûtent de plus en plus cher : dis-le en allemand.\n\n*Aide : teuer → teurer (cher) ; schwer (lourd) ; leicht (léger) ; alt (vieux) ; schnell (rapide) ; fahren = rouler ; kosten = coûter.*","bareme":[{"critere":"Comparatifs de supériorité justes avec als (poids, âge, vitesse)","points":6},{"critere":"Égalité exprimée par so… wie pour le prix","points":4},{"critere":"Préférence exprimée avec lieber","points":4},{"critere":"immer + comparatif : immer teurer","points":3},{"critere":"Formes justes : Umlaut d'älter, orthographe de teurer","points":3}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Prix : *Rad X ist **so teuer wie** Rad Y.* — même prix → égalité.\n- Poids : *Rad X ist **schwerer als** Rad Y.* (ou *Rad Y ist leichter als Rad X.*)\n- Âge : *Rad X ist **älter als** Rad Y.* — Umlaut : *alt → älter*.\n- Vitesse : *Rad Y ist **schneller als** Rad X.*\n\n**2.** *Noah fährt **lieber** mit Rad Y.* (ou *Noah mag Rad Y lieber.*) — *gern → lieber* = préférer.\n\n**3.** *Die Fahrräder werden **immer teurer**.* — *immer* + comparatif = de plus en plus.\n\nToute formulation correcte est acceptée ; *als* après le comparatif et *wie* après *so* sont exigés."}$exo$::jsonb),
  ('c7f2ae97-5e40-5df3-992c-062113c88dd9'::uuid, 3, 'traduction', $exo${"titre":"Comparer sans se tromper","consigne":"Corrige le texte de Hugo en justifiant, traduis les trois phrases, puis compare deux saisons en trois phrases.","enonce":"**Document — Le texte de Hugo**\n\n> Mein Bruder ist mehr groß als ich. Er hat ein größer Zimmer. Er ist so alt als mein Cousin. Je mehr er trainiert, desto er wird stärker.\n\n1. Le texte contient **quatre fautes**. Corrige chaque phrase et justifie.\n2. Traduis en allemand :\n   - a. Plus je lis, mieux je comprends.\n   - b. Mon frère aîné a un plus grand vélo.\n   - c. Il fait de plus en plus froid.\n3. Compare l'été et l'hiver en **trois phrases** : une avec *als*, une avec *so… wie* ou *nicht so… wie*, une avec *lieber*.\n\n*Aide : lesen, verstehen ; das Fahrrad ; kalt ; der Sommer, der Winter ; lang (long) ; die Tage.*","bareme":[{"critere":"Les quatre fautes corrigées : größer, größeres, so alt wie, desto stärker wird er","points":8},{"critere":"Traductions justes : je… desto, älterer / größeres déclinés, immer kälter","points":6},{"critere":"Trois phrases de comparaison correctes (als, so… wie, lieber)","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *mehr groß* → **größer** : *mehr* traduit une quantité, jamais le comparatif d'un adjectif.\n- *ein größer Zimmer* → **ein größeres Zimmer** : le comparatif épithète se décline ; neutre après *ein* → *-es*.\n- *so alt als* → **so alt wie** : égalité = *so… wie*.\n- *desto er wird stärker* → **desto stärker wird er** : après *desto*, le comparatif vient d'abord, puis le verbe, puis le sujet (*Je mehr er trainiert, desto stärker wird er.*).\n\n**2.**\n- a. *Je mehr ich lese, desto (umso) besser verstehe ich.*\n- b. *Mein **älterer** Bruder hat ein **größeres** Fahrrad.* — deux terminaisons : celle du comparatif, puis celle de la déclinaison.\n- c. *Es wird **immer kälter**.*\n\n**3. Exemple de réponse**\n- *Im Sommer sind die Tage länger als im Winter.*\n- *Der Winter ist nicht so warm wie der Sommer.*\n- *Ich mag den Sommer lieber als den Winter.*"}$exo$::jsonb),
  ('f12b680a-3341-5350-aed7-9bc828cfb022'::uuid, 1, 'traduction', $exo${"titre":"Les superlatifs à connaître","consigne":"Donne le superlatif en am … -sten de chaque adjectif, puis choisis la bonne forme dans les deux phrases de la question 2.","enonce":"**1. Donne la forme en *am … -sten*.**\n\nschnell · alt · kurz · groß · gut · viel · gern · hoch\n\n**2. Choisis la bonne forme et justifie en une phrase.**\n\n1. Der ICE ist *am schnellsten / der schnellste*.\n2. Das ist *am schnellsten / der schnellste* Zug.","bareme":[{"critere":"Superlatifs réguliers justes, avec le e de liaison et l'exception groß : schnellsten, ältesten, kürzesten, größten","points":8},{"critere":"Irréguliers justes : besten, meisten, liebsten, höchsten","points":8},{"critere":"Choix justifié : am -sten en attribut, der -ste devant un nom","points":4}],"dureeMin":6,"corrige":"**1.**\n- schnell → **am schnellsten**\n- alt → **am ältesten** (e de liaison après *t*, et Umlaut)\n- kurz → **am kürzesten** (e de liaison après *z*)\n- groß → **am größten** (exception : pas de e)\n- gut → **am besten**\n- viel → **am meisten**\n- gern → **am liebsten**\n- hoch → **am höchsten**\n\n**2.**\n1. *Der ICE ist **am schnellsten**.* — l'adjectif est attribut (après *sein*) : forme figée *am … -sten*.\n2. *Das ist **der schnellste** Zug.* — l'adjectif est épithète, devant le nom : *der … -ste*, qui se décline."}$exo$::jsonb),
  ('f12b680a-3341-5350-aed7-9bc828cfb022'::uuid, 2, 'traduction', $exo${"titre":"Le sondage de la classe","consigne":"Lis le tableau du cours de sport, puis réponds en allemand par des phrases complètes.","enonce":"**Document — 100 mètres, classe 3eB**\n\n| Élève | Temps | Âge |\n| Tim | 12,4 s | 15 ans |\n| Mia | 13,1 s | 14 ans |\n| Jonas | 14,0 s | 16 ans |\n\n1. *Wer läuft am schnellsten?*\n2. *Wer ist am ältesten? Wer ist am jüngsten?*\n3. Écris une phrase qui dit que Tim est **le coureur le plus rapide de tous**, avec l'adjectif devant le nom. *(der Läufer = le coureur)*\n4. Écris deux phrases qui disent ce que tu préfères faire par-dessus tout, en sport et le week-end.\n\n*Aide : jung = jeune.*","bareme":[{"critere":"Forme am … -sten juste en attribut et en adverbe (schnellsten, ältesten, jüngsten)","points":6},{"critere":"Superlatif épithète décliné : der schnellste Läufer","points":6},{"critere":"Complément du superlatif juste : von allen + datif","points":4},{"critere":"Deux phrases correctes avec am liebsten et l'inversion","points":4}],"dureeMin":10,"corrige":"**1.** *Tim läuft **am schnellsten**.* — adverbe : forme figée.\n\n**2.** *Jonas ist **am ältesten**.* (e de liaison après *t*, Umlaut) — *Mia ist **am jüngsten**.*\n\n**3.** *Tim ist **der schnellste Läufer von allen**.* — épithète devant le nom → *der schnellste* ; complément introduit par *von* + datif. (*Tim ist der Schnellste von allen* est aussi accepté.)\n\n**4. Exemple de réponse**\n- *Am liebsten spiele ich Basketball.*\n- *Am Wochenende schlafe ich am liebsten lange.*\n\n*am liebsten* = ce que je préfère par-dessus tout ; placé en tête, il entraîne l'inversion verbe-sujet."}$exo$::jsonb),
  ('f12b680a-3341-5350-aed7-9bc828cfb022'::uuid, 3, 'traduction', $exo${"titre":"Le meilleur et le plus haut","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis explique la règle des deux formes du superlatif.","enonce":"**1. Traduis en allemand.**\n\n1. Berlin est la plus grande ville d'Allemagne. *(deux façons)*\n2. Ce que je préfère par-dessus tout, c'est lire des romans policiers.\n3. Je joue avec mon meilleur ami.\n4. La Zugspitze est la montagne la plus haute d'Allemagne.\n5. C'est lui qui a le plus d'argent.\n\n**Document — deux phrases d'un élève**\n\n> a. Das ist der Zug am schnellsten.\n> b. Paula ist am altsten.\n\n**2.** Corrige les deux phrases du document.\n**3.** Explique en quelques lignes, en français, comment on choisit entre les deux formes du superlatif.\n\n*Aide : die Stadt ; der Krimi, die Krimis ; der Freund ; der Berg ; das Geld.*","bareme":[{"critere":"Phrases 1 et 4 : superlatif épithète décliné et complément de lieu (in + datif ou génitif)","points":5},{"critere":"Phrases 2, 3 et 5 : am liebsten avec inversion, meinem besten Freund, am meisten","points":5},{"critere":"Les deux phrases du document corrigées : der schnellste Zug, am ältesten","points":5},{"critere":"Explication : attribut ou adverbe → am -sten figé ; épithète → der -ste décliné","points":5}],"dureeMin":16,"corrige":"**1.**\n1. *Berlin ist **die größte Stadt in Deutschland**.* / *Berlin ist **Deutschlands größte Stadt**.* — épithète féminine ; complément avec *in* + datif ou génitif.\n2. ***Am liebsten** lese ich Krimis.* — *am liebsten* n'est pas « le plus aimé » mais « ce que je préfère » ; inversion après l'adverbe.\n3. *Ich spiele mit **meinem besten** Freund.* — *mit* + datif, superlatif épithète décliné.\n4. *Die Zugspitze ist **der höchste Berg** Deutschlands* (ou *in Deutschland*). — *hoch → höchste*, *Berg* masculin.\n5. *Er hat **am meisten** Geld.* — *viel → am meisten*.\n\n**2.**\n- a. *Das ist **der schnellste Zug**.* — devant un nom, on emploie la forme déclinée.\n- b. *Paula ist **am ältesten**.* — après *t*, on intercale un *e* ; *alt* prend aussi l'Umlaut.\n\n**3.** Le superlatif a deux formes selon la **place** de l'adjectif. Quand il est **attribut** (après *sein*) ou **adverbe** (*er läuft…*), on emploie *am* + *-sten*, forme figée qui ne se décline pas. Quand il est **épithète**, devant un nom, on emploie *der / die / das* + *-ste*, qui se décline comme un adjectif (*mit dem besten Freund*). Dans les deux cas, on ajoute un *e* de liaison après *d, t, s, ß, z, sch* (sauf *groß → größten*)."}$exo$::jsonb),
  ('2b9eaec2-c0e6-58dd-b017-9c513916cf34'::uuid, 1, 'traduction', $exo${"titre":"Durch, für, gegen, ohne, um","consigne":"Complète chaque phrase avec la préposition qui convient et, s'il le faut, la terminaison de l'article ou du possessif.","enonce":"**1. Complète avec *durch, für, gegen, ohne* ou *um*.**\n\n1. Wir gehen ___ d__ Park. *(à travers — der Park)*\n2. Das Geschenk ist ___ mein__ Schwester. *(pour)*\n3. Ich trinke den Kaffee ___ Zucker. *(sans)*\n4. Wir sitzen ___ d__ Tisch. *(autour de — der Tisch)*\n5. Ich bin ___ dies__ Idee. *(contre — die Idee)*\n6. Der Film beginnt ___ acht Uhr. *(à huit heures pile)*\n\n**2.** Quel cas suit ces cinq prépositions ? Explique pourquoi on écrit *den Park* et non *der Park* dans la phrase 1.","bareme":[{"critere":"Prépositions justes : durch, für, ohne, um, gegen, um","points":8},{"critere":"Terminaisons de l'accusatif justes : den Park, meine Schwester, den Tisch, diese Idee","points":8},{"critere":"Explication : ces prépositions imposent toujours l'accusatif, masculin der → den","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Wir gehen **durch den** Park.\n2. Das Geschenk ist **für meine** Schwester.\n3. Ich trinke den Kaffee **ohne** Zucker. — *ohne* se passe souvent d'article.\n4. Wir sitzen **um den** Tisch.\n5. Ich bin **gegen diese** Idee.\n6. Der Film beginnt **um** acht Uhr. — heure précise → *um* (*gegen acht Uhr* = vers huit heures).\n\n**2.** *durch, für, gegen, ohne, um* imposent **toujours l'accusatif**, quel que soit le sens. Au masculin, l'article *der* devient *den* à l'accusatif : *durch den Park*. Au féminin et au neutre, la forme ne change pas (*meine Schwester*, *diese Idee*)."}$exo$::jsonb),
  ('2b9eaec2-c0e6-58dd-b017-9c513916cf34'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Emma","consigne":"Emma répond à une invitation. Traduis son message en allemand, puis réponds à la question 2.","enonce":"**Le message d'Emma, en français**\n\n1. J'arrive vers huit heures.\n2. Le cadeau est pour ton frère.\n3. Nous marchons le long de la rivière.\n4. Je vais jusqu'à la gare en bus.\n5. Je viens sans mon vélo.\n\n*Aide : kommen ; das Geschenk ; der Bruder ; laufen ; der Fluss ; fahren ; der Bahnhof ; mit dem Bus ; das Fahrrad.*\n\n**2.** Emma hésite entre *gegen acht Uhr* et *um acht Uhr*. Explique la différence.","bareme":[{"critere":"Prépositions justes : gegen, für, entlang, bis zum, ohne","points":7},{"critere":"Accusatif juste après les prépositions : deinen Bruder, den Fluss, mein Fahrrad","points":6},{"critere":"Place d'entlang après le nom et bis suivi de zum","points":3},{"critere":"Différence gegen (vers) / um (heure précise) expliquée","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. *Ich komme **gegen** acht Uhr.* — heure approximative.\n2. *Das Geschenk ist **für deinen** Bruder.* — *für* + accusatif ; masculin → *deinen*.\n3. *Wir laufen **den Fluss entlang**.* — *entlang* se place **après** le nom, qui est à l'accusatif.\n4. *Ich fahre mit dem Bus **bis zum** Bahnhof.* — *bis* est souvent suivi d'une seconde préposition (*zum* = *zu dem*).\n5. *Ich komme **ohne mein** Fahrrad.* — *Fahrrad* neutre : *mein* à l'accusatif.\n\n**2.** *gegen acht Uhr* = **vers** huit heures (approximatif) ; *um acht Uhr* = **à** huit heures pile. Une seule préposition d'écart change l'heure du rendez-vous."}$exo$::jsonb),
  ('2b9eaec2-c0e6-58dd-b017-9c513916cf34'::uuid, 3, 'traduction', $exo${"titre":"Pour apprendre, pas für lernen","consigne":"Corrige le texte de Jules en justifiant chaque correction, puis rédige une invitation de quatre phrases.","enonce":"**Document — Le texte de Jules**\n\n> Ich lerne Deutsch für in Berlin studieren. Jeden Morgen gehe ich durch dem Wald. Das Buch ist für mein Vater. Am Sonntag laufen wir entlang die Straße.\n\n1. Chaque phrase contient **une faute**. Recopie les phrases corrigées.\n2. Justifie chaque correction en une phrase.\n3. Rédige en allemand une **invitation de quatre phrases** à une fête d'anniversaire, avec **quatre prépositions différentes** parmi *durch, für, gegen, ohne, um, bis, entlang*.\n\n*Aide : die Party ; der Geburtstag ; der Garten ; der Kuchen.*","bareme":[{"critere":"Quatre corrections justes : um… zu studieren, durch den Wald, für meinen Vater, die Straße entlang","points":8},{"critere":"Justifications : für devant un nom seulement, accusatif obligatoire, place d'entlang","points":4},{"critere":"Invitation : quatre prépositions différentes suivies de l'accusatif correct","points":6},{"critere":"Invitation compréhensible, verbes conjugués et ordre des mots corrects","points":2}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> *Ich lerne Deutsch, **um in Berlin zu studieren**. Jeden Morgen gehe ich **durch den** Wald. Das Buch ist **für meinen** Vater. Am Sonntag laufen wir **die Straße entlang**.*\n\n**2. Justifications**\n- « Pour + verbe » ne se dit pas *für* : *für* introduit un groupe nominal, jamais un verbe. Le but se dit **um… zu** + infinitif.\n- *durch* impose l'**accusatif** : *der Wald* → *den Wald* (et non le datif *dem*).\n- *für* impose l'accusatif : *Vater* masculin → *meinen Vater*.\n- *entlang* se place **après** le nom : *die Straße entlang*.\n\n**3. Exemple de réponse**\n\n> *Hallo Tim! Ich mache am Samstag eine Party für meinen Geburtstag. Die Party beginnt um drei Uhr. Wir essen Kuchen und spielen im Garten bis zum Abend. Komm nicht ohne deinen Bruder!*\n\nToute invitation correcte employant quatre prépositions différentes avec l'accusatif juste est acceptée."}$exo$::jsonb),
  ('d6f8119a-1d2d-5c24-b0d9-17721db035ec'::uuid, 1, 'traduction', $exo${"titre":"Aus, bei, mit, nach, seit, von, zu","consigne":"Complète chaque phrase avec la préposition entre parenthèses et la terminaison du datif, en contractant quand c'est l'usage.","enonce":"**1. Complète.**\n\n1. Ich fahre ___ d__ Bus in die Stadt. *(avec)*\n2. Er kommt ___ d__ Schweiz. *(de — die Schweiz)*\n3. Ich wohne ___ mein__ Eltern. *(chez)*\n4. Ich gehe heute ___ Arzt. *(chez — contracté)*\n5. ___ d__ Film essen wir Pizza. *(après — der Film)*\n6. Ich lerne ___ ein__ Jahr Deutsch. *(depuis — das Jahr)*\n\n**2.** Dans la phrase 6, pourquoi le verbe est-il au présent alors que le français pourrait hésiter ? Explique en une phrase.","bareme":[{"critere":"Prépositions justes : mit, aus, bei, zum, nach, seit","points":6},{"critere":"Terminaisons du datif justes : dem Bus, der Schweiz, meinen Eltern, dem Film, einem Jahr","points":8},{"critere":"Contraction zum employée","points":2},{"critere":"Explication : seit + présent","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich fahre **mit dem** Bus in die Stadt.\n2. Er kommt **aus der** Schweiz. — féminin au datif → *der*.\n3. Ich wohne **bei meinen** Eltern. — datif pluriel → *-en*.\n4. Ich gehe heute **zum** Arzt. — *zu dem* → *zum*, contraction obligatoire dans l'usage.\n5. **Nach dem** Film essen wir Pizza. — masculin datif → *dem* ; inversion après le complément.\n6. Ich lerne **seit einem** Jahr Deutsch. — neutre datif → *einem*.\n\n**2.** Avec *seit*, l'action a commencé dans le passé et **dure encore** : l'allemand emploie le **présent**, comme le français (« j'apprends l'allemand depuis un an »)."}$exo$::jsonb),
  ('d6f8119a-1d2d-5c24-b0d9-17721db035ec'::uuid, 2, 'traduction', $exo${"titre":"Le voyage de Noah","consigne":"Noah raconte ses projets de voyage. Traduis ses phrases en allemand, puis explique tes choix de préposition.","enonce":"**1. Traduis en allemand.**\n\n1. Cet été, je vais en Autriche.\n2. Ensuite, je vais en Suisse.\n3. Je vais chez ma tante.\n4. Le soir, je rentre à la maison.\n5. Le dimanche, je suis à la maison.\n6. J'habite à Munich depuis deux ans.\n\n*Aide : Österreich (sans article) ; die Schweiz ; die Tante ; fahren, gehen ; wohnen ; München ; das Jahr, die Jahre ; im Sommer ; dann ; abends ; sonntags.*\n\n**2.** Explique quand on emploie *nach*, *in* + accusatif et *zu* pour dire où l'on va.","bareme":[{"critere":"Choix juste de nach, in die et zu selon le lieu (phrases 1 à 3)","points":7},{"critere":"Datif et contractions justes : zu meiner Tante, seit zwei Jahren","points":5},{"critere":"Expressions figées nach Hause / zu Hause bien employées","points":4},{"critere":"seit + présent, et règle nach / in / zu expliquée","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Im Sommer fahre ich **nach Österreich**.* — pays sans article → *nach*.\n2. *Dann fahre ich **in die Schweiz**.* — pays avec article → *in* + accusatif.\n3. *Ich fahre **zu meiner** Tante.* — personne → *zu* + datif.\n4. *Abends gehe ich **nach Hause**.* — avec mouvement.\n5. *Sonntags bin ich **zu Hause**.* — sans mouvement.\n6. *Ich wohne **seit zwei Jahren** in München.* — *seit* + datif pluriel (*Jahren*) et verbe au **présent**.\n\n**2.** Pour dire où l'on va : **nach** devant un pays ou une ville **sans article** (*nach Wien*) ; **in** + accusatif devant un pays **avec article** (*in die Schweiz, in die Türkei*) ; **zu** + datif devant une **personne** ou un bâtiment vu comme un but (*zum Arzt, zur Post*). *nach Hause* / *zu Hause* sont des expressions figées."}$exo$::jsonb),
  ('d6f8119a-1d2d-5c24-b0d9-17721db035ec'::uuid, 3, 'traduction', $exo${"titre":"Une journée à Hambourg","consigne":"Corrige le texte d'Hugo en justifiant, puis décris ta propre journée en quatre phrases.","enonce":"**Document — Le texte d'Hugo**\n\n> Seit drei Jahren habe ich in Hamburg gewohnt. Jeden Tag fahre ich mit meinem Fahrrad zu die Schule. Nach der Schule gehe ich bei meinem Freund Max. Im Juli fahren wir nach die Türkei. Meine Mutter kommt aus Frankreich.\n\n1. Le texte contient **quatre fautes**. Recopie les phrases fautives corrigées.\n2. Justifie chaque correction.\n3. Une phrase du texte est entièrement correcte : laquelle ? Explique pourquoi.\n4. Décris ta journée en **quatre phrases** en employant au moins quatre prépositions différentes parmi *aus, bei, mit, nach, seit, von, zu*.","bareme":[{"critere":"Quatre corrections : Seit… wohne ich, zur Schule, zu meinem Freund, in die Türkei","points":8},{"critere":"Justifications : seit + présent, contraction, zu pour une destination, pays avec article","points":4},{"critere":"Phrase correcte identifiée : aus Frankreich, pays sans article, aus + origine","points":2},{"critere":"Quatre phrases personnelles avec quatre prépositions à datif bien construites","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *Seit drei Jahren **wohne ich** in Hamburg.*\n- *Jeden Tag fahre ich mit meinem Fahrrad **zur** Schule.*\n- *Nach der Schule gehe ich **zu meinem** Freund Max.*\n- *Im Juli fahren wir **in die** Türkei.*\n\n**2. Justifications**\n- Avec *seit*, l'action dure encore : **présent**, pas parfait.\n- *zu* impose le datif : *zu der* → contraction **zur** (obligatoire dans l'usage).\n- On **va** chez quelqu'un : *zu* + datif ; *bei* indique qu'on **est** chez lui (sans mouvement).\n- *die Türkei* a un article : on emploie **in** + accusatif, pas *nach*.\n\n**3.** *Meine Mutter kommt aus Frankreich* est correct : *aus* + datif marque l'origine, et *Frankreich* s'emploie sans article.\n\n**4. Exemple de réponse**\n- *Ich fahre mit dem Bus zur Schule.*\n- *Nach dem Unterricht esse ich bei meiner Oma.*\n- *Ich lerne seit vier Jahren Deutsch.*\n- *Am Abend bekomme ich eine Nachricht von meinem Freund.*"}$exo$::jsonb),
  ('f28e4c19-33e9-5441-930c-29c3b78a49b6'::uuid, 1, 'traduction', $exo${"titre":"Wo ou wohin ?","consigne":"Complète chaque phrase avec l'article au bon cas, puis explique ton choix pour les phrases 1 et 2.","enonce":"**1. Complète avec l'article.**\n\n1. Ich gehe in ___ Schule. *(die Schule)*\n2. Ich bin in ___ Schule.\n3. Das Bild hängt an ___ Wand. *(die Wand)*\n4. Die Katze liegt unter ___ Tisch. *(der Tisch)*\n5. Die Katze läuft unter ___ Tisch. *(elle s'y glisse)*\n6. Das Heft liegt neben ___ Buch. *(das Buch)*\n\n**2.** Explique pourquoi l'article n'est pas le même dans les phrases 1 et 2.","bareme":[{"critere":"Accusatif juste en cas de déplacement (wohin) : die Schule, den Tisch","points":8},{"critere":"Datif juste en cas de localisation (wo) : der Schule, der Wand, dem Tisch, dem Buch","points":8},{"critere":"Explication avec les questions wo ? / wohin ?","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich gehe in **die** Schule. — *wohin?* déplacement → accusatif.\n2. Ich bin in **der** Schule. — *wo?* localisation → datif.\n3. Das Bild hängt an **der** Wand. — état → datif.\n4. Die Katze liegt unter **dem** Tisch. — *wo?* → datif.\n5. Die Katze läuft unter **den** Tisch. — elle change de lieu (*wohin?*) → accusatif.\n6. Das Heft liegt neben **dem** Buch. — *wo?* → datif.\n\n**2.** Les neuf prépositions mixtes changent de cas selon le sens. Dans la phrase 1, il y a un **changement de lieu** (question *wohin?*) → **accusatif** ; dans la phrase 2, une **localisation** (question *wo?*) → **datif**."}$exo$::jsonb),
  ('f28e4c19-33e9-5441-930c-29c3b78a49b6'::uuid, 2, 'traduction', $exo${"titre":"Clara range sa chambre","consigne":"Complète chaque paire de phrases avec le verbe conjugué et l'article au bon cas, puis réponds à la question 2.","enonce":"**1. Complète.** Dans chaque paire, la phrase **a** décrit l'action, la phrase **b** le résultat.\n\n1. a. Clara ___ die Lampe auf ___ Schreibtisch. *(stellen / stehen)* — b. Die Lampe ___ auf ___ Schreibtisch.\n2. a. Sie ___ das Buch auf ___ Bett. *(legen / liegen)* — b. Das Buch ___ auf ___ Bett.\n3. a. Sie ___ das Poster an ___ Wand. *(hängen)* — b. Das Poster ___ an ___ Wand.\n\n*der Schreibtisch, das Bett, die Wand*\n\n**2.** Contracte : *in das Zimmer* ; *an dem Fenster* ; *auf das Bett*.","bareme":[{"critere":"Couples de verbes justes et conjugués : stellt / steht, legt / liegt, hängt / hängt","points":8},{"critere":"Accusatif pour l'action, datif pour l'état : den / dem Schreibtisch, das / dem Bett, die / der Wand","points":8},{"critere":"Contractions justes : ins, am, aufs","points":4}],"dureeMin":10,"corrige":"**1.**\n1. a. Clara **stellt** die Lampe auf **den** Schreibtisch. — action → accusatif. b. Die Lampe **steht** auf **dem** Schreibtisch. — état → datif.\n2. a. Sie **legt** das Buch auf **das** (*aufs*) Bett. b. Das Buch **liegt** auf **dem** Bett.\n3. a. Sie **hängt** das Poster an **die** Wand. — *hängen* faible = accrocher. b. Das Poster **hängt** an **der** Wand. — *hängen* fort = être accroché.\n\nLes verbes d'action (*stellen, legen, setzen, hängen* faible) appellent l'accusatif ; les verbes d'état (*stehen, liegen, sitzen, hängen* fort) le datif.\n\n**2.** *in das Zimmer* → **ins Zimmer** ; *an dem Fenster* → **am Fenster** ; *auf das Bett* → **aufs Bett**."}$exo$::jsonb),
  ('f28e4c19-33e9-5441-930c-29c3b78a49b6'::uuid, 3, 'traduction', $exo${"titre":"Même verbe, deux cas","consigne":"Traduis les phrases en allemand, puis explique en français la méthode qui permet de choisir le cas.","enonce":"**1. Traduis en allemand.**\n\n1. Je cours dans le parc (à l'intérieur du parc).\n2. J'entre en courant dans le parc.\n3. Je pose la bouteille sur la table.\n4. La bouteille est sur la table.\n5. Je me réjouis des vacances.\n6. En janvier, nous allons au cinéma.\n\n*Aide : laufen ; der Park ; die Flasche ; der Tisch ; sich freuen auf ; die Ferien (pluriel) ; der Januar ; das Kino.*\n\n**2.** En quelques lignes, explique pourquoi les phrases 1 et 2 n'ont pas le même cas alors que le verbe est le même, et donne la méthode à suivre pour choisir l'article.","bareme":[{"critere":"Phrases 1 et 2 : im Park (datif) / in den Park (accusatif)","points":5},{"critere":"Phrases 3 et 4 : stellen + accusatif, stehen + datif","points":4},{"critere":"Emplois figés justes : auf die Ferien (accusatif), im Januar, ins Kino avec inversion","points":5},{"critere":"Explication : c'est le changement de lieu, pas le verbe, qui décide ; méthode wo ? / wohin ?","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n1. *Ich laufe **im Park**.* — je cours à l'intérieur : pas de changement de lieu → datif (*in dem* → *im*).\n2. *Ich laufe **in den Park**.* — j'y entre : changement de lieu → accusatif.\n3. *Ich **stelle** die Flasche auf **den** Tisch.* — action → accusatif.\n4. *Die Flasche **steht** auf **dem** Tisch.* — état → datif.\n5. *Ich freue mich **auf die** Ferien.* — emploi figé : *sich freuen auf* + accusatif.\n6. ***Im** Januar gehen wir **ins** Kino.* — *im Januar* figé ; *ins Kino* = déplacement ; inversion après le complément de temps.\n\n**2.** Ce n'est pas le verbe de mouvement qui décide, mais le **changement de lieu** : dans la phrase 1, on court en restant dans le parc (*wo?* → datif) ; dans la phrase 2, on passe de l'extérieur à l'intérieur (*wohin?* → accusatif). Méthode : trouver le **verbe**, se demander **wo?** ou **wohin?**, et n'écrire l'article qu'**ensuite**. Certaines expressions ne relèvent plus du lieu et s'apprennent telles quelles (*im Januar, sich freuen auf* + accusatif)."}$exo$::jsonb),
  ('1414399e-8343-59dd-8ac1-54f583b9ba25'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie chaque paire de phrases avec la conjonction indiquée, en respectant la virgule et l'ordre des mots.","enonce":"**1. Relie les deux phrases.**\n\n1. Ich bleibe zu Hause. Ich bin krank. *(denn)*\n2. Er ist arm. Er ist glücklich. *(aber)*\n3. Das ist nicht mein Buch. Es ist deins. *(sondern)*\n4. Trinkst du Tee? Trinkst du Kaffee? *(oder)*\n5. Ich spiele Fußball. Mein Bruder spielt Tennis. *(und)*\n\n**2.** Dans la phrase 3, pourquoi faut-il *sondern* et non *aber* ?","bareme":[{"critere":"Phrases reliées sans changer l'ordre des mots après la conjonction (verbe en 2e position)","points":10},{"critere":"Virgule devant denn, aber et sondern, pas devant und ni oder","points":5},{"critere":"Explication : sondern après une négation","points":5}],"dureeMin":6,"corrige":"**1.**\n1. *Ich bleibe zu Hause, **denn** ich bin krank.* — après *denn*, rien ne bouge : sujet puis verbe.\n2. *Er ist arm, **aber** glücklich.* (ou *…, aber er ist glücklich.*)\n3. *Das ist nicht mein Buch, **sondern** deins.*\n4. *Trinkst du Tee **oder** Kaffee?*\n5. *Ich spiele Fußball **und** mein Bruder spielt Tennis.*\n\nLes conjonctions de coordination occupent la **position zéro** : elles ne comptent pas dans l'ordre des mots.\n\n**2.** *sondern* (« mais au contraire ») s'emploie après une **négation** pour rectifier : *nicht mein Buch, sondern deins*. *aber* s'emploie sans négation, pour une opposition simple."}$exo$::jsonb),
  ('1414399e-8343-59dd-8ac1-54f583b9ba25'::uuid, 2, 'traduction', $exo${"titre":"Trois syntaxes pour une même idée","consigne":"Réécris chaque idée avec les mots de liaison demandés, puis explique où se place le verbe dans chaque cas.","enonce":"**1. Idée : nous restons à la maison parce qu'il pleut.**\n\nÉcris la phrase de trois façons :\na. avec *denn* ;\nb. avec *weil* ;\nc. avec *deshalb*.\n\n*(Wir bleiben zu Hause. — Es regnet.)*\n\n**2. Idée : je suis fatigué, pourtant je continue à travailler.**\n\nÉcris la phrase de deux façons :\na. avec *aber* ;\nb. avec *trotzdem*.\n\n*(Ich bin müde. — Ich lerne weiter.)*\n\n**3.** Explique en français, pour *denn*, *weil* et *deshalb*, où se place le verbe conjugué.","bareme":[{"critere":"Phrase avec denn : ordre normal, virgule","points":4},{"critere":"Phrase avec weil : verbe conjugué à la fin","points":4},{"critere":"Phrases avec deshalb et trotzdem : inversion verbe-sujet","points":6},{"critere":"Explication des trois places du verbe (coordination, subordination, adverbe)","points":6}],"dureeMin":10,"corrige":"**1.**\na. *Wir bleiben zu Hause, **denn** es regnet.*\nb. *Wir bleiben zu Hause, **weil** es **regnet**.*\nc. *Es regnet, **deshalb bleiben wir** zu Hause.*\n\n**2.**\na. *Ich bin müde, **aber** ich lerne weiter.*\nb. *Ich bin müde, **trotzdem lerne ich** weiter.*\n\n**3.**\n- Après **denn** (coordination) : la conjonction est en position zéro, rien ne bouge — sujet puis verbe en **2e position**.\n- Après **weil** (subordination) : le verbe conjugué part **à la fin** de la subordonnée.\n- Après **deshalb** (adverbe de liaison, comme *trotzdem*) : l'adverbe occupe la **1re position**, le verbe reste en 2e position, donc le sujet passe derrière : **inversion**.\n\nTrois syntaxes pour un même lien logique : les confondre est l'erreur la plus fréquente en expression écrite."}$exo$::jsonb),
  ('1414399e-8343-59dd-8ac1-54f583b9ba25'::uuid, 3, 'traduction', $exo${"titre":"Donner son avis en nuances","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis donne ton avis en quatre phrases.","enonce":"**1. Traduis en allemand.**\n\n1. Ni mon frère ni ma sœur ne parlent allemand.\n2. Il joue non seulement au football, mais aussi au tennis.\n3. Ou bien nous allons au cinéma, ou bien nous restons à la maison.\n4. Certes, le voyage est cher, mais il est intéressant.\n\n**Document — deux phrases d'élève**\n\n> a. Ich spiele nicht Tennis, aber Fußball.\n> b. Weder Tom noch Lisa kommt nicht.\n\n**2.** Corrige les deux phrases et justifie.\n\n**3.** Donne ton avis sur le téléphone portable au collège en **quatre phrases**, en utilisant *zwar… aber*, *denn* et *deshalb*.\n\n*Aide : die Reise ; teuer ; das Handy ; nützlich (utile) ; stören (déranger) ; im Unterricht.*","bareme":[{"critere":"Traductions justes des corrélatifs : weder… noch, nicht nur… sondern auch, entweder… oder, zwar… aber","points":8},{"critere":"Corrections justifiées : sondern après négation, pas de nicht après weder… noch","points":4},{"critere":"Avis : zwar… aber, denn (sans inversion) et deshalb (avec inversion) bien construits","points":6},{"critere":"Avis cohérent et compréhensible","points":2}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n1. *Weder mein Bruder noch meine Schwester spricht Deutsch.* (*sprechen* au pluriel est aussi accepté) — la phrase est déjà négative : pas de *nicht*.\n2. *Er spielt nicht nur Fußball, sondern auch Tennis.*\n3. *Entweder gehen wir ins Kino, oder wir bleiben zu Hause.* (*Entweder wir gehen…* est aussi accepté.)\n4. *Die Reise ist zwar teuer, aber (sie ist) interessant.*\n\n**2.**\n- a. *Ich spiele nicht Tennis, **sondern** Fußball.* — après une négation, on rectifie avec *sondern*.\n- b. *Weder Tom noch Lisa **kommt**.* — *weder… noch* porte déjà la négation : ajouter *nicht* est une faute.\n\n**3. Exemple de réponse**\n\n> *Das Handy ist zwar nützlich, aber es stört im Unterricht. Viele Schüler spielen im Unterricht, denn sie sind nicht konzentriert. Deshalb bin ich für ein Handyverbot in der Klasse. Nach der Schule ist das Handy aber okay.*\n\nSont vérifiés : *zwar* après le verbe et *aber* en tête de la seconde partie, *denn* sans changement d'ordre, *deshalb* suivi de l'inversion."}$exo$::jsonb),
  ('4d060405-96ad-522a-b261-339ab7c02f25'::uuid, 1, 'traduction', $exo${"titre":"Wo, wohin, woher ?","consigne":"Complète chaque phrase avec la préposition (et l'article contracté si besoin), puis indique la question à laquelle elle répond.","enonce":"**1. Complète, puis écris à côté *wo?*, *wohin?* ou *woher?*.**\n\n1. Ich fahre ___ Deutschland.\n2. Ich komme ___ Frankreich.\n3. Im Sommer fahren wir ___ Meer. *(das Meer)*\n4. Heute Abend gehe ich ___ Kino. *(das Kino)*\n5. Ich bin gerade ___ Arzt. *(der Arzt)*\n6. Mama kommt um sechs Uhr ___ der Arbeit.","bareme":[{"critere":"Prépositions justes : nach, aus, ans, ins, beim, von","points":12},{"critere":"Contractions correctes : ans, ins, beim","points":4},{"critere":"Question juste pour chaque phrase","points":4}],"dureeMin":6,"corrige":"1. Ich fahre **nach** Deutschland. — *wohin?* pays sans article.\n2. Ich komme **aus** Frankreich. — *woher?* venir d'un pays.\n3. Im Sommer fahren wir **ans** Meer. — *wohin?* un bord : *an* + accusatif (*an das* → *ans*).\n4. Heute Abend gehe ich **ins** Kino. — *wohin?* nom avec article : *in* + accusatif (*in das* → *ins*).\n5. Ich bin gerade **beim** Arzt. — *wo?* chez une personne sans mouvement : *bei dem* → *beim*.\n6. Mama kommt um sechs Uhr **von** der Arbeit. — *woher?* point de départ : *von* + datif."}$exo$::jsonb),
  ('4d060405-96ad-522a-b261-339ab7c02f25'::uuid, 2, 'traduction', $exo${"titre":"Dialogue avant les vacances","consigne":"Complète le dialogue entre Ben et Aylin, puis traduis les deux paires de phrases de la question 2.","enonce":"**1. Complète le dialogue.**\n\n> Ben: Wohin fährst du in den Ferien?\n> Aylin: Ich fahre ___ Land zu meiner Oma. *(à la campagne)*\n> Ben: Wo wohnt sie genau?\n> Aylin: Sie wohnt ___ Land, in einem kleinen Dorf.\n> Ben: Und dein Vater? Woher kommt er?\n> Aylin: Er kommt ___ Türkei. Im August fahren wir alle ___ Türkei.\n\n**2. Traduis en allemand.**\na. Je vais chez le médecin. / Je suis chez le médecin.\nb. Il part à l'étranger. / Il vit à l'étranger.\n\n*Aide : das Ausland = l'étranger ; der Arzt.*","bareme":[{"critere":"Paire aufs Land / auf dem Land juste","points":4},{"critere":"aus der Türkei (origine) et in die Türkei (destination) justes","points":4},{"critere":"zum Arzt / beim Arzt justes","points":6},{"critere":"ins Ausland / im Ausland justes","points":6}],"dureeMin":10,"corrige":"**1.**\n- Ich fahre **aufs** Land zu meiner Oma. — mouvement : *auf* + accusatif (*auf das* → *aufs*).\n- Sie wohnt **auf dem** Land. — sans mouvement : datif.\n- Er kommt **aus der** Türkei. — origine : *aus* + datif ; pays avec article féminin → *der*.\n- Im August fahren wir alle **in die** Türkei. — destination, pays avec article → *in* + accusatif (jamais *nach*).\n\n**2.**\na. *Ich gehe **zum** Arzt.* (mouvement vers une personne) / *Ich bin **beim** Arzt.* (sans mouvement). Le français dit « chez » dans les deux cas ; l'allemand oblige à choisir.\nb. *Er geht (fährt) **ins** Ausland.* / *Er lebt **im** Ausland.* — expressions figées par paires : une avec mouvement (accusatif), une sans (datif)."}$exo$::jsonb),
  ('4d060405-96ad-522a-b261-339ab7c02f25'::uuid, 3, 'traduction', $exo${"titre":"Hin, her et le récit d'un voyage","consigne":"Traduis les phrases de la question 1, rédige le récit demandé, puis réponds à la question 3 en français.","enonce":"**1. Traduis en allemand.**\na. Viens ici !\nb. Vas-y !\nc. Où vas-tu ? *(deux façons)*\nd. D'où viens-tu ? *(deux façons)*\n\n**2.** Raconte en **six phrases** un voyage imaginaire : d'où tu pars, où tu vas, chez qui, où tu dors, ce que tu visites. Emploie au moins **cinq** constructions différentes parmi : *nach, in* + accusatif, *zu, an* + accusatif, *aus, von, bei*.\n\n**3.** Explique la différence entre *hineingehen* et *herauskommen* en t'appuyant sur le sens de *hin* et *her*.","bareme":[{"critere":"Impératifs justes : Komm her!, Geh hin!","points":3},{"critere":"Questions justes : Wohin / Wo… hin, Woher / Wo… her","points":4},{"critere":"Récit : cinq constructions de lieu différentes avec le bon cas","points":7},{"critere":"Récit compréhensible, verbes conjugués correctement","points":2},{"critere":"Explication : hin = éloignement du locuteur, her = rapprochement","points":4}],"dureeMin":18,"corrige":"**1.**\na. *Komm **her**!* — rapprochement vers celui qui parle.\nb. *Geh **hin**!* — éloignement.\nc. *Wohin gehst du?* / *Wo gehst du **hin**?*\nd. *Woher kommst du?* / *Wo kommst du **her**?* — la particule peut se détacher et partir en fin de phrase.\n\n**2. Exemple de réponse**\n\n> *Ich komme aus Lyon. Im Juli fahre ich mit dem Zug nach Berlin. Dort gehe ich zu meinem Brieffreund Jonas. Ich schlafe bei seiner Familie. Am Montag gehen wir ins Museum. Am Wochenende fahren wir ans Meer.*\n\nConstructions attendues : *aus* (origine), *nach* (ville sans article), *zu* + datif (personne), *bei* + datif (sans mouvement), *in* + accusatif (*ins Museum*), *an* + accusatif (*ans Meer*).\n\n**3.** *hin* marque l'**éloignement** du locuteur, *her* le **rapprochement**. *hineingehen* = entrer, vu de **dehors** (on s'éloigne de celui qui parle) ; *herauskommen* = sortir, vu de **dedans** (on vient vers celui qui parle). Ces particules se soudent aux prépositions pour former des préverbes."}$exo$::jsonb),
  ('ff69d39a-6453-5eba-9179-90832d66cb08'::uuid, 1, 'traduction', $exo${"titre":"Am, im ou um ?","consigne":"Complète chaque complément de temps, puis traduis les trois expressions de la question 2.","enonce":"**1. Complète avec *am*, *im*, *um* ou *in der*.**\n\n1. ___ Montag\n2. ___ Sommer\n3. ___ acht Uhr\n4. ___ Januar\n5. ___ Abend\n6. ___ Jahr 2026\n7. ___ Nacht\n8. ___ Mitternacht\n\n**2.** Traduis et explique la différence : *morgen* ; *morgens* ; *am Morgen*.","bareme":[{"critere":"am devant les jours et parties de la journée : am Montag, am Abend","points":4},{"critere":"im devant mois, saisons, années : im Sommer, im Januar, im Jahr 2026","points":4},{"critere":"um devant l'heure précise et exception in der Nacht","points":4},{"critere":"Sens juste de morgen, morgens, am Morgen","points":8}],"dureeMin":6,"corrige":"**1.**\n1. **am** Montag — jour\n2. **im** Sommer — saison\n3. **um** acht Uhr — heure précise\n4. **im** Januar — mois\n5. **am** Abend — partie de la journée\n6. **im** Jahr 2026 — année\n7. **in der** Nacht — exception (et non *am*)\n8. **um** Mitternacht — heure précise\n\n**2.**\n- *morgen* = **demain**.\n- *morgens* = **le matin, en général**, habituellement (adverbe).\n- *am Morgen* = **ce matin-là**, un matin précis.\n\nUn seul *s* d'écart suffit à changer le sens."}$exo$::jsonb),
  ('ff69d39a-6453-5eba-9179-90832d66cb08'::uuid, 2, 'traduction', $exo${"titre":"L'agenda de Lina","consigne":"Traduis les phrases de l'agenda de Lina en commençant chaque phrase par le complément de temps.","enonce":"**L'agenda de Lina, en français**\n\n1. Chaque jour, je vais au collège.\n2. Il y a deux semaines, j'étais à Vienne.\n3. Dans une heure, le film commence.\n4. J'apprends l'allemand depuis trois ans. *(commence par « Seit… »)*\n5. Pendant les vacances, je lis beaucoup.\n6. Du lundi au vendredi, je me lève tôt.\n\n*Aide : in die Schule gehen ; die Woche ; Wien ; die Stunde ; beginnen ; die Ferien (pluriel) ; lesen ; früh aufstehen (ich stehe … auf).*","bareme":[{"critere":"Prépositions et cas justes : vor zwei Wochen, in einer Stunde, seit drei Jahren, während der Ferien, von… bis","points":8},{"critere":"Accusatif sans préposition : jeden Tag","points":3},{"critere":"Inversion verbe-sujet après le complément de temps en tête","points":5},{"critere":"seit + présent","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. ***Jeden Tag** gehe ich in die Schule.* — durée ou date entière : accusatif sans préposition.\n2. ***Vor zwei Wochen** war ich in Wien.* — *vor* + datif = il y a.\n3. ***In einer Stunde** beginnt der Film.* — *in* + datif = dans (futur).\n4. ***Seit drei Jahren** lerne ich Deutsch.* — *seit* + datif pluriel, verbe au **présent**.\n5. ***Während der Ferien** lese ich viel.* — *während* + génitif ; *Ferien* pluriel → *der*.\n6. ***Von Montag bis Freitag** stehe ich früh auf.*\n\nDans chaque phrase, le complément de temps ouvre la phrase : le verbe reste en 2e position et le sujet passe **derrière** (inversion)."}$exo$::jsonb),
  ('ff69d39a-6453-5eba-9179-90832d66cb08'::uuid, 3, 'traduction', $exo${"titre":"Des vacances en Italie","consigne":"Corrige le texte d'Inès en justifiant, puis raconte ta journée type en cinq phrases.","enonce":"**Document — La carte postale d'Inès**\n\n> Am Sommer fahre ich nach Italien. Ich bin dort seit zwei Wochen gewesen. Um Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. Nächsten Woche ich fahre nach Hause.\n\n1. Le texte contient **quatre phrases fautives** (une phrase est correcte). Corrige-les.\n2. Justifie chaque correction.\n3. Raconte ta journée type en **cinq phrases**, avec **cinq compléments de temps différents** ; au moins deux phrases commencent par le complément de temps.","bareme":[{"critere":"Corrections : Im Sommer, Ich bin seit zwei Wochen dort, Am Abend, Nächste Woche fahre ich","points":8},{"critere":"Justifications : im / am, seit + présent, accusatif sans préposition, inversion","points":4},{"critere":"Journée type : cinq compléments de temps différents et justes","points":5},{"critere":"Inversion correcte quand le complément ouvre la phrase","points":3}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> ***Im** Sommer fahre ich nach Italien. Ich **bin** seit zwei Wochen dort. **Am** Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. **Nächste Woche fahre ich** nach Hause.*\n\n**2. Justifications**\n- Saisons → **im** (*im Sommer*), pas *am*.\n- Avec *seit*, l'action dure encore : **présent** (*ich bin*), pas parfait.\n- Parties de la journée → **am** (*am Abend*) ; *um* est réservé à l'heure précise.\n- *nächste Woche* : accusatif sans préposition, **féminin** → *nächste* ; en tête de phrase, le verbe reste en 2e position → **inversion** (*fahre ich*).\n- La phrase *Morgens stehe ich um neun Uhr auf* est correcte (*morgens* = le matin, habituellement).\n\n**3. Exemple de réponse**\n\n> *Morgens stehe ich um sieben Uhr auf. Um acht Uhr beginnt der Unterricht. Am Mittag esse ich in der Kantine. Nach der Schule spiele ich Fußball. Am Abend lese ich ein Buch.*"}$exo$::jsonb),
  ('9d919db3-2583-5f60-815b-1454a6016a0d'::uuid, 1, 'traduction', $exo${"titre":"Sein, haben, werden","consigne":"Complète avec la bonne forme de sein, haben ou werden au temps indiqué, puis donne les trois participes.","enonce":"**1. Complète.**\n\n1. Ihr ___ müde. *(sein, présent)*\n2. Du ___ einen Hund. *(haben, présent)*\n3. Mein Bruder ___ Arzt. *(werden, présent : il devient)*\n4. Gestern ___ ich krank. *(sein, prétérit)*\n5. Wir ___ keine Zeit. *(haben, prétérit)*\n6. Es ___ kalt. *(werden, prétérit)*\n\n**2.** Donne le participe passé de *sein*, *haben* et *werden* (verbe plein).","bareme":[{"critere":"Présents justes : seid, hast, wird","points":8},{"critere":"Prétérits justes : war, hatten, wurde","points":6},{"critere":"Participes justes : gewesen, gehabt, geworden","points":6}],"dureeMin":6,"corrige":"**1.**\n1. Ihr **seid** müde. (attention : *seid* avec d, le verbe ; *seit* avec t est la préposition « depuis »)\n2. Du **hast** einen Hund.\n3. Mein Bruder **wird** Arzt. — *werden* verbe plein = devenir.\n4. Gestern **war** ich krank.\n5. Wir **hatten** keine Zeit.\n6. Es **wurde** kalt.\n\n**2.** *sein → **gewesen*** ; *haben → **gehabt*** ; *werden → **geworden*** (et *worden* seulement quand *werden* est auxiliaire du passif)."}$exo$::jsonb),
  ('9d919db3-2583-5f60-815b-1454a6016a0d'::uuid, 2, 'traduction', $exo${"titre":"Haben ou sein au parfait ?","consigne":"Complète chaque phrase au parfait avec haben ou sein conjugué, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec *haben* ou *sein*.**\n\n1. Ich ___ nach Berlin gefahren.\n2. Ich ___ das Auto meines Vaters gefahren.\n3. Er ___ um sieben Uhr aufgestanden.\n4. Wir ___ den ganzen Tag zu Hause geblieben.\n5. Sie ___ ein Buch gelesen.\n6. Was ___ passiert?\n7. Das Kind ___ schnell eingeschlafen.\n8. Ich ___ eine Pizza gegessen.\n\n**2.** Les phrases 1 et 2 ont le même verbe, mais pas le même auxiliaire. Explique pourquoi.","bareme":[{"critere":"sein pour les verbes de mouvement et de changement d'état : bin, ist aufgestanden, ist eingeschlafen","points":6},{"critere":"sein pour bleiben et passieren : sind geblieben, ist passiert","points":4},{"critere":"haben pour les autres verbes : habe gefahren (avec COD), hat gelesen, habe gegessen","points":4},{"critere":"Explication : fahren avec un COD prend haben, c'est le sens qui tranche","points":6}],"dureeMin":10,"corrige":"**1.**\n1. Ich **bin** nach Berlin gefahren. — déplacement.\n2. Ich **habe** das Auto meines Vaters gefahren. — *fahren* avec un COD (*das Auto*).\n3. Er **ist** um sieben Uhr aufgestanden. — changement d'état.\n4. Wir **sind** den ganzen Tag zu Hause geblieben. — *bleiben* prend toujours *sein*.\n5. Sie **hat** ein Buch gelesen.\n6. Was **ist** passiert? — *passieren* prend *sein*.\n7. Das Kind **ist** schnell eingeschlafen. — changement d'état.\n8. Ich **habe** eine Pizza gegessen.\n\n**2.** Dans la phrase 1, *fahren* exprime un **déplacement** d'un point à un autre : auxiliaire **sein** (je me suis déplacé). Dans la phrase 2, *fahren* a un **COD** (*das Auto*) : il signifie « conduire » et prend **haben**. C'est le sens de la phrase qui tranche, pas le verbe lui-même."}$exo$::jsonb),
  ('9d919db3-2583-5f60-815b-1454a6016a0d'::uuid, 3, 'traduction', $exo${"titre":"Les trois vies de werden","consigne":"Traduis les phrases, corrige la phrase du document, puis explique les emplois de werden.","enonce":"**1. Traduis en allemand.**\n\n1. Je deviens nerveux.\n2. Je reçois une lettre.\n3. Demain, il fera beau.\n4. La maison est en train d'être construite.\n5. Il est devenu médecin.\n6. La maison a été construite en 1990.\n\n*Aide : nervös ; der Brief ; das Wetter ; schön ; bauen (construire) ; der Arzt.*\n\n**Document — phrase d'un élève**\n\n> Ich habe gestern nach Paris gegangen.\n\n**2.** Corrige cette phrase et justifie.\n**3.** Explique en français les trois emplois de *werden* et pourquoi *bekommen* est un piège.","bareme":[{"critere":"werden verbe plein, futur et passif justes (phrases 1, 3, 4)","points":6},{"critere":"bekommen = recevoir (phrase 2)","points":2},{"critere":"Participes justes : ist… geworden, ist… gebaut worden","points":5},{"critere":"Phrase du document corrigée : bin gegangen, verbe de mouvement","points":3},{"critere":"Explication des trois emplois de werden et du faux ami bekommen","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *Ich **werde** nervös.* — verbe plein : devenir.\n2. *Ich **bekomme** einen Brief.* — *bekommen* = recevoir.\n3. *Morgen **wird** das Wetter schön (**sein**).* — auxiliaire du futur.\n4. *Das Haus **wird gebaut**.* — passif d'action : *werden* + participe.\n5. *Er **ist** Arzt **geworden**.* — parfait de *werden* verbe plein : *sein* + *geworden*.\n6. *Das Haus **ist** 1990 **gebaut worden**.* — parfait du passif : participe *worden*.\n\n**2.** *Ich **bin** gestern nach Paris **gegangen**.* — *gehen* est un verbe de mouvement d'un point à un autre : il forme son parfait avec **sein**.\n\n**3.** *werden* a trois emplois : **verbe plein** « devenir » (*Er wird Arzt*) ; **auxiliaire du futur** (*Es wird regnen*) ; **auxiliaire du passif** d'action (*Das Haus wird gebaut*). Au participe, il fait *geworden* comme verbe plein, *worden* dans un passif. *bekommen* ressemble à « become » ou « devenir », mais il signifie **recevoir** : « je deviens » se dit *ich werde*. La confusion produit un contresens complet."}$exo$::jsonb),
  ('beb8ad89-e312-514b-8875-77d4944effef'::uuid, 1, 'traduction', $exo${"titre":"Les temps primitifs","consigne":"Donne les trois temps primitifs (infinitif, prétérit, participe II) de chaque verbe et classe-le.","enonce":"**1. Recopie et complète le tableau.**\n\n| Infinitif | Prétérit (er) | Participe II | Famille |\n| machen | | | |\n| spielen | | | |\n| fahren | | | |\n| schreiben | | | |\n| nehmen | | | |\n| gehen | | | |\n| studieren | | | |\n| bringen | | | |\n\n*Familles : faible, fort, mixte, verbe en -ieren.*\n\n**2.** Quelle différence vois-tu entre le participe d'un verbe faible et celui d'un verbe fort ?","bareme":[{"critere":"Verbes faibles justes : machte / gemacht, spielte / gespielt","points":4},{"critere":"Verbes forts justes : fuhr / gefahren, schrieb / geschrieben, nahm / genommen, ging / gegangen","points":8},{"critere":"Cas particuliers : studierte / studiert sans ge-, brachte / gebracht (mixte)","points":4},{"critere":"Différence ge-…-t / ge-…-en expliquée","points":4}],"dureeMin":8,"corrige":"**1.**\n| Infinitif | Prétérit | Participe II | Famille |\n| machen | machte | gemacht | faible |\n| spielen | spielte | gespielt | faible |\n| fahren | fuhr | gefahren | fort |\n| schreiben | schrieb | geschrieben | fort |\n| nehmen | nahm | genommen | fort |\n| gehen | ging | gegangen | fort |\n| studieren | studierte | studiert | en -ieren (faible, sans ge-) |\n| bringen | brachte | gebracht | mixte |\n\n**2.** Le participe d'un verbe **faible** se forme en *ge-… **-t*** et garde son radical (*gemacht*). Celui d'un verbe **fort** se forme en *ge-… **-en*** et change souvent de voyelle (*gesprochen, genommen*). Le mixte a un radical modifié mais des terminaisons faibles (*gebracht*)."}$exo$::jsonb),
  ('beb8ad89-e312-514b-8875-77d4944effef'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Complète les phrases au présent, puis mets le récit de Max au prétérit.","enonce":"**1. Conjugue au présent.**\n\n1. Du ___ gut Deutsch. *(sprechen)*\n2. Er ___ mir das Buch. *(geben)*\n3. ___ du den Film heute Abend? *(sehen)*\n4. Sie ___ einen Roman. *(lesen)*\n5. Du ___ zu schnell! *(fahren)*\n6. Wir ___ ihm ein Geschenk. *(geben)*\n\n**2. Réécris le récit au prétérit.**\n\n> Am Samstag fahre ich nach Köln. Ich nehme den Zug. Im Zug schreibe ich eine Karte. In Köln kaufe ich ein T-Shirt und spiele mit meinem Cousin Fußball.","bareme":[{"critere":"Changement de voyelle aux 2e et 3e personnes du singulier : sprichst, gibt, siehst, liest, fährst","points":8},{"critere":"Pas de changement au pluriel : wir geben","points":2},{"critere":"Prétérits forts justes : fuhr, nahm, schrieb","points":6},{"critere":"Prétérits faibles justes : kaufte, spielte","points":4}],"dureeMin":10,"corrige":"**1.**\n1. Du **sprichst** gut Deutsch. — *e → i*.\n2. Er **gibt** mir das Buch. — *e → i*.\n3. **Siehst** du den Film heute Abend? — *e → ie*.\n4. Sie **liest** einen Roman. — *e → ie*.\n5. Du **fährst** zu schnell! — *a → ä*.\n6. Wir **geben** ihm ein Geschenk. — au pluriel, pas de changement.\n\n**2. Récit au prétérit**\n\n> *Am Samstag **fuhr** ich nach Köln. Ich **nahm** den Zug. Im Zug **schrieb** ich eine Karte. In Köln **kaufte** ich ein T-Shirt und **spielte** mit meinem Cousin Fußball.*\n\n- Verbes forts : la voyelle change et il n'y a pas de terminaison à la 1re personne (*fuhr, nahm, schrieb*).\n- Verbes faibles : radical inchangé + *-te* (*kaufte, spielte*)."}$exo$::jsonb),
  ('beb8ad89-e312-514b-8875-77d4944effef'::uuid, 3, 'traduction', $exo${"titre":"Lire un récit au prétérit","consigne":"Analyse les verbes du récit, réécris-en une partie au parfait, puis traduis la dernière phrase.","enonce":"**Document — Le voyage de Paul**\n\n> Letzten Sommer **fuhr** Paul nach Hamburg. Er **nahm** den Zug und **schrieb** seiner Mutter eine Karte. Er **kaufte** ein Souvenir und **telefonierte** mit seinem Freund. Am Abend **dachte** er an seine Familie.\n\n1. Pour chaque verbe en gras, donne l'**infinitif** et la **famille** (fort, faible, mixte, en -ieren).\n2. Réécris les deux premières phrases du récit au **parfait**. *(Aide : fahren se conjugue avec sein au parfait, les autres avec haben.)*\n3. Traduis en allemand : **Il parle allemand et elle lit un livre.**","bareme":[{"critere":"Infinitifs justes : fahren, nehmen, schreiben, kaufen, telefonieren, denken","points":5},{"critere":"Familles justes : trois forts, un faible, un en -ieren, un mixte","points":4},{"critere":"Parfait juste : ist gefahren, hat genommen, geschrieben, gekauft, telefoniert (sans ge-)","points":7},{"critere":"Traduction avec les changements de voyelle : spricht, liest","points":4}],"dureeMin":16,"corrige":"**1.**\n| Forme | Infinitif | Famille |\n| fuhr | fahren | fort |\n| nahm | nehmen | fort |\n| schrieb | schreiben | fort |\n| kaufte | kaufen | faible (-te) |\n| telefonierte | telefonieren | en -ieren (faible) |\n| dachte | denken | mixte (radical modifié, terminaison faible) |\n\n**2. Au parfait**\n\n> *Letzten Sommer **ist** Paul nach Hamburg **gefahren**. Er **hat** den Zug **genommen** und seiner Mutter eine Karte **geschrieben**.*\n\n(La suite, si l'élève la réécrit : *Er hat ein Souvenir **gekauft** und mit seinem Freund **telefoniert**.* — pas de *ge-* pour les verbes en *-ieren* ; *Am Abend hat er an seine Familie **gedacht**.*)\n\n**3.** *Er **spricht** Deutsch und sie **liest** ein Buch.* — verbes forts : *e → i* (*sprechen*) et *e → ie* (*lesen*) à la 3e personne du singulier."}$exo$::jsonb),
  ('8bb3c37b-8164-51a4-8a4a-748fba6429c2'::uuid, 1, 'traduction', $exo${"titre":"Le bon modal","consigne":"Complète chaque phrase avec le verbe de modalité qui convient, conjugué au présent, puis réponds à la question 2.","enonce":"**1. Complète.**\n\n1. Ich ___ gut schwimmen. *(capacité)*\n2. ___ ich reinkommen? *(autorisation)*\n3. Du ___ heute lernen, morgen ist der Test. *(nécessité)*\n4. Wir ___ im Sommer nach Berlin fahren. *(volonté)*\n5. Ich ___ einen Kaffee, bitte. *(demande polie)*\n6. Der Arzt sagt, er ___ im Bett bleiben. *(consigne venue d'autrui)*\n\n**2.** Dans la phrase 3, où se place l'infinitif *lernen* ? Énonce la règle.","bareme":[{"critere":"Modal juste selon le sens : kann, darf, musst, wollen, möchte, soll","points":8},{"critere":"Conjugaison juste, sans terminaison aux 1re et 3e personnes du singulier","points":8},{"critere":"Règle : modal en 2e position, infinitif à la fin","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich **kann** gut schwimmen. — *können* : capacité.\n2. **Darf** ich reinkommen? — *dürfen* : permission.\n3. Du **musst** heute lernen, morgen ist der Test. — *müssen* : nécessité.\n4. Wir **wollen** im Sommer nach Berlin fahren. — *wollen* : volonté.\n5. Ich **möchte** einen Kaffee, bitte. — forme polie de *mögen*.\n6. Der Arzt sagt, er **soll** im Bett bleiben. — *sollen* : consigne venue d'autrui.\n\n**2.** Dans une principale, le modal conjugué est en **2e position** et l'infinitif part **à la fin** de la phrase : *Du musst heute **lernen**.*"}$exo$::jsonb),
  ('8bb3c37b-8164-51a4-8a4a-748fba6429c2'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de l'auberge","consigne":"Lis le règlement de l'auberge de jeunesse, puis réponds aux questions en allemand.","enonce":"**Document — Jugendherberge Bremen**\n\n> Rauchen verboten! — Frühstück von 7 bis 9 Uhr. — Die Zimmer sind um 10 Uhr frei. — Fahrräder: 8 Euro pro Tag. — Die Küche ist für alle offen.\n\n1. Écris **quatre phrases** avec *man* + un modal pour résumer le règlement : une interdiction, une obligation, une possibilité, une autorisation.\n2. Traduis et explique la différence : *Du musst nicht kommen.* / *Du darfst nicht rauchen.*\n3. Relie les deux phrases avec *weil* : *Ich kann heute nicht kommen. Ich muss lernen.*\n\n*Aide : rauchen ; frühstücken ; das Zimmer verlassen (quitter la chambre) ; mieten (louer) ; kochen.*","bareme":[{"critere":"Quatre phrases avec man + modal adapté au sens (darf nicht, muss, kann, darf)","points":8},{"critere":"Négation : muss nicht = pas obligé, darf nicht = interdiction","points":6},{"critere":"Subordonnée avec weil : infinitif puis modal à la fin","points":6}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Interdiction : *Man **darf** hier nicht **rauchen**.*\n- Obligation : *Man **muss** das Zimmer um 10 Uhr **verlassen**.*\n- Possibilité : *Man **kann** Fahrräder **mieten**.* (ou *Man kann von 7 bis 9 Uhr frühstücken.*)\n- Autorisation : *Man **darf** in der Küche **kochen**.*\n\n**2.**\n- *Du musst nicht kommen* = **tu n'es pas obligé** de venir.\n- *Du darfst nicht rauchen* = **tu n'as pas le droit** de fumer (interdiction).\n*müssen* + négation supprime l'obligation ; l'interdiction se dit avec *nicht dürfen*.\n\n**3.** *Ich kann heute nicht kommen, **weil** ich **lernen muss**.* — en subordonnée, tout part à la fin : l'infinitif, puis le modal conjugué."}$exo$::jsonb),
  ('8bb3c37b-8164-51a4-8a4a-748fba6429c2'::uuid, 3, 'traduction', $exo${"titre":"Ce qu'on a dû faire","consigne":"Transforme les phrases au passé, traduis la phrase rapportée, puis écris un court texte sur tes projets.","enonce":"**1. Mets au parfait.**\na. Ich muss arbeiten.\nb. Er kann nicht kommen.\nc. Ich will es. *(sans infinitif)*\n\n**2. Mets au prétérit.**\na. Wir können nicht schwimmen.\nb. Sie muss lernen.\n\n**3.** Traduis en allemand, avec *sollen* : « Le médecin m'a dit de rester au lit. » (Commence par *Ich…*)\n\n**4.** Écris **quatre phrases** sur tes projets pour l'été, avec **quatre modaux différents**.\n\n*Aide : im Bett bleiben ; im Sommer ; arbeiten, reisen, schlafen.*","bareme":[{"critere":"Parfait avec double infinitif : habe arbeiten müssen, hat nicht kommen können ; participe gewollt sans infinitif","points":6},{"critere":"Prétérits justes sans Umlaut : konnten, musste","points":4},{"critere":"sollen employé pour rapporter une consigne : Ich soll im Bett bleiben","points":3},{"critere":"Quatre phrases avec quatre modaux différents, bien conjugués, infinitif à la fin","points":7}],"dureeMin":16,"corrige":"**1.**\na. *Ich **habe arbeiten müssen**.* — avec un infinitif dépendant : **double infinitif**, pas de participe.\nb. *Er **hat nicht kommen können**.*\nc. *Ich **habe es gewollt**.* — sans infinitif, le participe existe.\n\n**2.**\na. *Wir **konnten** nicht schwimmen.*\nb. *Sie **musste** lernen.* — prétérit régulier, **sans inflexion**.\n\n**3.** *Ich **soll** im Bett bleiben.* — *sollen* rapporte une consigne extérieure (on m'a dit de…).\n\n**4. Exemple de réponse**\n\n> *Im Sommer will ich nach Österreich reisen. Dort kann ich wandern. Ich darf zum ersten Mal allein fahren. Aber ich muss vorher etwas Geld verdienen.*\n\nSont vérifiés : un modal différent par phrase, conjugué, et l'infinitif en fin de phrase."}$exo$::jsonb),
  ('6697e639-cb1f-5110-91f6-dd1a09664389'::uuid, 1, 'traduction', $exo${"titre":"Le préverbe à sa place","consigne":"Construis chaque phrase au présent, puis donne le participe passé de chaque verbe.","enonce":"**1. Construis la phrase au présent.**\n\n1. aufstehen — ich — um sieben Uhr\n2. einkaufen — wir — am Samstag\n3. anrufen — er — seine Mutter\n4. besuchen — ich — meine Tante\n5. verstehen — du — den Text\n\n**2.** Donne le participe passé de : *aufstehen, einkaufen, anrufen, besuchen, verstehen*.","bareme":[{"critere":"Préverbe séparable en fin de phrase : stehe… auf, kaufen… ein, ruft… an","points":8},{"critere":"Verbes inséparables non coupés : besuche, verstehst","points":4},{"critere":"Participes justes : aufgestanden, eingekauft, angerufen (ge- intercalé), besucht, verstanden (sans ge-)","points":8}],"dureeMin":6,"corrige":"**1.**\n1. *Ich **stehe** um sieben Uhr **auf**.* — le préverbe ferme la phrase.\n2. *Wir **kaufen** am Samstag **ein**.*\n3. *Er **ruft** seine Mutter **an**.*\n4. *Ich **besuche** meine Tante.* — *be-* est inséparable : rien ne bouge.\n5. *Du **verstehst** den Text.* — *ver-* inséparable.\n\n**2.**\n- *aufstehen → **aufgestanden*** ; *einkaufen → **eingekauft*** ; *anrufen → **angerufen*** — le *ge-* s'intercale entre le préverbe et le radical.\n- *besuchen → **besucht*** ; *verstehen → **verstanden*** — inséparables : **pas de ge-**."}$exo$::jsonb),
  ('6697e639-cb1f-5110-91f6-dd1a09664389'::uuid, 2, 'traduction', $exo${"titre":"La journée de Lukas","consigne":"À partir des notes de Lukas, rédige sa journée en allemand, puis transforme deux phrases comme demandé.","enonce":"**Document — Les notes de Lukas**\n\n| Heure | Action |\n| 7 h | aufstehen |\n| 8 h | mit dem Bus abfahren |\n| 17 h | im Supermarkt einkaufen |\n| 19 h | fernsehen |\n| 22 h | einschlafen |\n\n1. Écris **cinq phrases** au présent sur la journée de Lukas (3e personne). Commence au moins deux phrases par l'heure.\n2. Relie avec *weil* : *Lukas ist müde. Er steht um sieben Uhr auf.*\n3. Complète avec *zu* : *Lukas hat keine Lust, ___ (einkaufen).*","bareme":[{"critere":"Préverbe en fin de phrase dans les principales : steht… auf, fährt… ab, kauft… ein, sieht… fern, schläft… ein","points":8},{"critere":"Inversion quand l'heure ouvre la phrase et verbes forts bien conjugués (fährt, sieht, schläft)","points":4},{"critere":"Subordonnée : préverbe recollé en fin (aufsteht)","points":4},{"critere":"zu intercalé : einzukaufen","points":4}],"dureeMin":10,"corrige":"**1. Exemple de réponse**\n- *Um sieben Uhr **steht** Lukas **auf**.*\n- *Um acht Uhr **fährt** er mit dem Bus **ab**.*\n- *Um siebzehn Uhr **kauft** er im Supermarkt **ein**.*\n- *Um neunzehn Uhr **sieht** er **fern**.*\n- *Um zweiundzwanzig Uhr **schläft** er **ein**.*\n\nLe préverbe séparable ferme la phrase ; l'heure en tête entraîne l'inversion ; *fahren, sehen, schlafen* changent de voyelle à la 3e personne.\n\n**2.** *Lukas ist müde, **weil** er um sieben Uhr **aufsteht**.* — en subordonnée, le préverbe se **recolle** au verbe, à la fin.\n\n**3.** *Lukas hat keine Lust, **einzukaufen**.* — le *zu* s'intercale entre le préverbe et le radical."}$exo$::jsonb),
  ('6697e639-cb1f-5110-91f6-dd1a09664389'::uuid, 3, 'traduction', $exo${"titre":"Kommen et sa famille","consigne":"Donne le sens des verbes, traduis les phrases, puis explique comment reconnaître un préverbe séparable.","enonce":"**1.** Donne le sens de : *kommen, ankommen, bekommen, mitkommen, umkommen*.\n\n**2. Traduis en allemand.**\na. Le train arrive à huit heures.\nb. Je reçois un cadeau.\nc. Tu viens avec nous ?\nd. Elle traduit le texte.\ne. Le train est arrivé. *(parfait avec sein)*\nf. J'ai reçu un cadeau. *(parfait avec haben)*\n\n*Aide : der Zug ; das Geschenk ; übersetzen ; der Text.*\n\n**3.** Explique en français le test qui permet de savoir si un préverbe est séparable, et pourquoi *übersetzen* peut être les deux.","bareme":[{"critere":"Sens justes des cinq verbes","points":4},{"critere":"Phrases au présent : kommt… an, bekomme, Kommst du mit?, übersetzt (non coupé)","points":6},{"critere":"Participes : ist angekommen (ge- intercalé), habe bekommen (sans ge-)","points":4},{"critere":"Explication : test de l'accent et double statut selon le sens concret ou figuré","points":6}],"dureeMin":16,"corrige":"**1.** *kommen* = venir ; *ankommen* = arriver ; *bekommen* = recevoir ; *mitkommen* = accompagner, venir avec ; *umkommen* = périr. Le sens dépend entièrement du préverbe.\n\n**2.**\na. *Der Zug **kommt** um acht Uhr **an**.*\nb. *Ich **bekomme** ein Geschenk.* — *be-* inséparable.\nc. ***Kommst** du **mit**?*\nd. *Sie **übersetzt** den Text.* — sens figuré (traduire) → inséparable.\ne. *Der Zug **ist angekommen**.* — *ge-* intercalé.\nf. *Ich **habe** ein Geschenk **bekommen**.* — inséparable : pas de *ge-*.\n\n**3.** Le seul critère fiable est l'**accent** : un préverbe **séparable** est accentué (*ÁN-kommen*), un préverbe **inséparable** ne l'est pas, l'accent tombe sur le radical (*be-KÓMMEN*). *über-* fait partie des préverbes à double statut : au sens **concret**, il est séparable (*Ich setze über* = je traverse en bateau) ; au sens **figuré**, il est inséparable (*Ich übersetze den Text* = je traduis)."}$exo$::jsonb),
  ('0821fbf9-ddf3-5128-9e34-060b4f8693ef'::uuid, 1, 'traduction', $exo${"titre":"Mich ou mir ?","consigne":"Complète chaque phrase avec le pronom réfléchi qui convient, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec le pronom réfléchi.**\n\n1. Ich wasche ___.\n2. Ich wasche ___ die Hände.\n3. Du kaufst ___ ein Buch.\n4. Er freut ___ auf die Ferien.\n5. Wir interessieren ___ für Musik.\n6. Setzen Sie ___ bitte!\n\n**2.** Pourquoi écrit-on *mich* dans la phrase 1 et *mir* dans la phrase 2 ?","bareme":[{"critere":"Réfléchis à l'accusatif sans COD : mich, sich, uns","points":6},{"critere":"Réfléchis au datif en présence d'un COD : mir, dir","points":6},{"critere":"sich en minuscule dans le vouvoiement","points":3},{"critere":"Explication : un COD dans la phrase fait passer le réfléchi au datif","points":5}],"dureeMin":6,"corrige":"**1.**\n1. Ich wasche **mich**. — pas de COD → accusatif.\n2. Ich wasche **mir** die Hände. — *die Hände* est COD → datif.\n3. Du kaufst **dir** ein Buch. — COD *ein Buch* → datif.\n4. Er freut **sich** auf die Ferien.\n5. Wir interessieren **uns** für Musik.\n6. Setzen Sie **sich** bitte! — *sich* ne prend **jamais** de majuscule, même dans le vouvoiement.\n\n**2.** Dans la phrase 1, il n'y a pas d'autre complément : le réfléchi est le COD → **accusatif** (*mich*). Dans la phrase 2, il y a déjà un COD (*die Hände*) : le réfléchi passe au **datif** (*mir*). Les deux séries ne diffèrent qu'aux deux premières personnes du singulier."}$exo$::jsonb),
  ('0821fbf9-ddf3-5128-9e34-060b4f8693ef'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Ambre","consigne":"Ambre écrit à sa correspondante. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je me souviens de mes vacances.\n2. Je m'intéresse au sport.\n3. Je me réjouis de ton cadeau (je l'ai reçu).\n4. Je me réjouis du week-end (il n'est pas encore là).\n5. Je me lève à sept heures.\n6. Je suis souvent en retard.\n\n*Aide : sich erinnern ; der Sport ; das Geschenk ; das Wochenende ; aufstehen ; sich verspäten ; oft.*\n\n**2.** Explique pourquoi la phrase 5 n'a pas de pronom réfléchi en allemand et pourquoi la phrase 6 en a un.","bareme":[{"critere":"Prépositions justes suivies de l'accusatif : an meine Ferien, für Sport","points":6},{"critere":"auf (à venir) et über (déjà arrivé) bien distingués","points":6},{"critere":"Faux pronominaux : stehe… auf sans réfléchi, verspäte mich","points":4},{"critere":"Explication juste des faux pronominaux","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Ich erinnere mich **an** meine Ferien.* — *sich erinnern an* + accusatif.\n2. *Ich interessiere mich **für** Sport.* — *sich interessieren für* + accusatif.\n3. *Ich freue mich **über** dein Geschenk.* — ce qui est déjà arrivé → *über*.\n4. *Ich freue mich **auf** das Wochenende.* — ce qui vient → *auf*.\n5. *Ich **stehe** um sieben Uhr **auf**.* — pas de pronom.\n6. *Ich **verspäte mich** oft.*\n\n**2.** Certains verbes pronominaux en français ne le sont pas en allemand : *aufstehen* (se lever) n'a pas de réfléchi. À l'inverse, *sich verspäten* (être en retard) est pronominal en allemand mais pas en français. Il faut apprendre chaque verbe avec sa construction."}$exo$::jsonb),
  ('0821fbf9-ddf3-5128-9e34-060b4f8693ef'::uuid, 3, 'traduction', $exo${"titre":"Le pronom au bon endroit","consigne":"Place les pronoms, corrige le texte de Malo en justifiant, puis écris quatre phrases sur toi.","enonce":"**1. Place le pronom réfléchi au bon endroit.**\na. Gestern hat mein Bruder verletzt. *(sich)*\nb. Ich bin glücklich, weil ich freue. *(mich)*\nc. Heute Abend sehe ich den Film an. *(mir)*\n\n**Document — Le texte de Malo**\n\n> Jeden Morgen wasche ich mich die Haare. Mein Freund interessiert sich an Fußball. Nächste Woche beginnen die Ferien: wir freuen uns schon über die Ferien. Am Sonntag spaziere ich mich im Park.\n\n**2.** Chaque phrase contient une faute. Corrige-les et justifie.\n\n**3.** Écris **quatre phrases** sur toi avec quatre verbes pronominaux différents du cours (dont un au datif avec COD).","bareme":[{"critere":"Place juste du pronom : hat sich mein Bruder, weil ich mich freue, sehe mir… an","points":5},{"critere":"Corrections : mir die Haare, für Fußball, auf die Ferien, gehe… spazieren","points":6},{"critere":"Justifications : datif avec COD, bonne préposition, auf / über, faux pronominal","points":3},{"critere":"Quatre phrases personnelles correctes, dont un réfléchi au datif avec COD","points":6}],"dureeMin":16,"corrige":"**1.**\na. *Gestern hat **sich** mein Bruder verletzt.* — inversion : le pronom vient après le verbe, **avant** un sujet nominal.\nb. *Ich bin glücklich, weil ich **mich** freue.* — subordonnée : après le sujet.\nc. *Heute Abend sehe ich **mir** den Film an.* — COD *den Film* → datif, juste après le verbe et le sujet inversé.\n\n**2. Texte corrigé**\n- *Jeden Morgen wasche ich **mir** die Haare.* — il y a un COD (*die Haare*) → réfléchi au datif.\n- *Mein Freund interessiert sich **für** Fußball.* — *sich interessieren für* + accusatif.\n- *Wir freuen uns schon **auf** die Ferien.* — les vacances sont à venir → *auf* ; *über* pour ce qui est déjà arrivé.\n- *Am Sonntag **gehe** ich im Park **spazieren**.* — « se promener » n'est pas pronominal en allemand.\n\n**3. Exemple de réponse**\n- *Ich interessiere mich für Geschichte.*\n- *Ich erinnere mich gern an meine Kindheit.*\n- *Ich freue mich auf die Sommerferien.*\n- *Am Wochenende kaufe ich mir ein neues Buch.* — réfléchi au datif avec le COD *ein neues Buch*."}$exo$::jsonb),
  ('e458f10b-13b6-5f04-85fd-86d036afb913'::uuid, 1, 'traduction', $exo${"titre":"Privatsphäre und Öffentlichkeit : traduire l'essentiel","consigne":"Traduis le texte en français (version), puis réponds à la question 2.","enonce":"**Texte (inventé, d'après le cours).**\n\n> Viele Deutsche wollen ihre Privatsphäre schützen. Der Datenschutz ist ihnen wichtig, denn sie erinnern sich an die Überwachung durch die Stasi. Seit 1949 steht im Grundgesetz: « Männer und Frauen sind gleichberechtigt. » 2005 wurde Angela Merkel die erste Bundeskanzlerin.\n\n*Aide : sich erinnern an = se souvenir de ; die Bundeskanzlerin = la chancelière.*\n\n1. Traduis le texte en français.\n2. Donne le mot allemand, **avec son article**, pour : **a)** l'espace public ; **b)** l'égalité des droits ; **c)** l'émancipation.","bareme":[{"critere":"Traduction fidèle du texte, sans contresens (wurde = est devenue, Seit 1949 steht = depuis 1949 figure)","points":10},{"critere":"Les trois mots de vocabulaire justes avec leur article (2 points chacun)","points":6},{"critere":"Français correct et naturel","points":4}],"dureeMin":7,"corrige":"**1. Traduction proposée**\n« Beaucoup d'Allemands veulent protéger leur vie privée. La protection des données leur tient à cœur (est importante pour eux), car ils se souviennent de la surveillance exercée par la Stasi. Depuis 1949, on peut lire dans la Loi fondamentale : « Les hommes et les femmes sont égaux en droits. » En 2005, Angela Merkel est devenue la première chancelière. »\n\nPoints de vigilance :\n- *die Privatsphäre* → la vie privée ; *der Datenschutz* → la protection des données ; *die Überwachung* → la surveillance.\n- *Seit 1949 steht* : présent allemand avec *seit* → présent en français (« depuis 1949, la Loi fondamentale dit / on lit »).\n- *wurde* est ici le prétérit de *werden* = **devenir** (pas un passif) : « est devenue ».\n- *gleichberechtigt* → « égaux en droits ».\n\n**2. Vocabulaire**\na) *die Öffentlichkeit* ; b) *die Gleichberechtigung* ; c) *die Emanzipation*.\nUn mot juste sans article ou avec un mauvais article vaut 1 point sur 2."}$exo$::jsonb),
  ('e458f10b-13b6-5f04-85fd-86d036afb913'::uuid, 2, 'traduction', $exo${"titre":"Deux Allemagnes, deux vies de femmes","consigne":"Lis le texte, réponds en français aux questions 1 et 2, puis en allemand à la question 3.","enonce":"**Texte (témoignage inventé).**\n\n> Meine Großmutter Helga lebte in der DDR. Sie arbeitete als Ingenieurin, und ihre Kinder gingen in die Krippe. Ihre Schwester Renate wohnte in der Bundesrepublik. Sie wollte als Verkäuferin arbeiten, aber bis 1977 brauchte eine verheiratete Frau im Westen die Erlaubnis ihres Mannes. Renate blieb also zu Hause bei den Kindern.\n\n*Aide : die Krippe = la crèche ; die Verkäuferin = la vendeuse ; die Erlaubnis = l'autorisation.*\n\n1. Présente les deux sœurs et relève **deux différences** entre leurs vies.\n2. Explique en deux ou trois phrases la formule « *Kinder, Küche, Kirche* » et dis à quelle sœur la situation décrite correspond le mieux.\n3. **En allemand**, écris trois phrases pour dire ce qui a changé pour les femmes en Allemagne en **1918**, en **1949** et en **2005**.","bareme":[{"critere":"Les deux sœurs présentées et deux différences justes, appuyées sur le texte","points":6},{"critere":"Formule des trois K expliquée (sphère privée assignée aux femmes) et reliée à Renate","points":5},{"critere":"Trois phrases allemandes aux dates et faits exacts (droit de vote, Loi fondamentale, Merkel)","points":6},{"critere":"Correction de la langue allemande (verbe en 2e position, prétérit)","points":3}],"dureeMin":12,"corrige":"**1.** Helga vivait en **RDA** : elle était ingénieure, donc elle travaillait, et ses enfants allaient à la crèche. Sa sœur Renate vivait en **RFA** : elle voulait travailler comme vendeuse, mais jusqu'en 1977, une femme mariée avait besoin de l'autorisation de son mari ; elle est donc restée à la maison avec ses enfants.\nDifférences attendues (deux suffisent) : l'une travaille, l'autre reste au foyer ; les enfants de l'une vont à la crèche, ceux de l'autre sont gardés à la maison ; l'une décide de son métier, l'autre dépend de l'accord de son mari. Cela illustre le cours : à l'Est, presque toutes les femmes travaillaient grâce aux crèches ; à l'Ouest, le modèle de la mère au foyer a duré plus longtemps.\n\n**2.** Sous l'Empire, la formule des « trois K » — *Kinder, Küche, Kirche* (les enfants, la cuisine, l'église) — résumait la place assignée aux femmes : la **sphère privée**, loin de la vie publique et du travail. La situation de **Renate**, restée à la maison avec ses enfants, y correspond le mieux.\n\n**3. Modèle**\n- *1918 durften die Frauen zum ersten Mal wählen.* (ou : *1918 bekamen die Frauen das Wahlrecht.*)\n- *1949 schrieb man ins Grundgesetz: « Männer und Frauen sind gleichberechtigt. »* (ou : *Seit 1949 steht im Grundgesetz …*)\n- *2005 wurde Angela Merkel die erste Bundeskanzlerin.*\nAccepter toute formulation correcte ; valoriser le verbe conjugué en 2e position après la date (*1918 durften …*)."}$exo$::jsonb),
  ('e458f10b-13b6-5f04-85fd-86d036afb913'::uuid, 3, 'traduction', $exo${"titre":"Datenschutz : une passion allemande ?","consigne":"Rédige en allemand un texte argumenté d'environ 130 à 150 mots. Appuie-toi sur des repères précis du cours.","enonce":"**Sujet.**\n\n> *Der Datenschutz ist in Deutschland eine Leidenschaft. Warum?*\n\nTon texte doit :\n1. citer **au moins deux repères datés** du cours sur la protection des données ;\n2. expliquer **l'origine historique** de cette méfiance ;\n3. donner **ton avis** : cette prudence est-elle justifiée aujourd'hui ?\n\n*Aide : die Leidenschaft = la passion ; das Bundesverfassungsgericht = la Cour constitutionnelle ; überwachen = surveiller ; die Akten = les archives, les dossiers.*","bareme":[{"critere":"Au moins deux repères exacts (1983 et le droit à l'autodétermination informationnelle, 2010 Street View, 2018 DSGVO)","points":5},{"critere":"Explication historique : mémoire de la Gestapo et de la Stasi, surveillance jusque dans les familles","points":5},{"critere":"Avis personnel argumenté et nuancé","points":4},{"critere":"Langue : vocabulaire du chapitre, verbe final après weil / dass, connecteurs","points":6}],"dureeMin":18,"corrige":"**Texte modèle (≈ 140 mots)**\n\n*In Deutschland ist der Datenschutz sehr wichtig. Schon 1983 hat das Bundesverfassungsgericht ein « Recht auf informationelle Selbstbestimmung » geschaffen. 2010 wollten Hunderttausende Deutsche nicht, dass man ihr Haus bei Google Street View sieht. Und 2018 trat die DSGVO in Kraft, die zum Teil von dieser Tradition inspiriert ist.*\n\n*Warum diese Leidenschaft? Die Deutschen erinnern sich an die Gestapo und an die Stasi. In der DDR hat die Stasi sogar Familien überwacht: Manche Menschen haben in den Akten entdeckt, dass ihre Verwandten sie überwacht hatten. Wer überwacht wurde, weiß, was seine Daten wert sind.*\n\n*Meiner Meinung nach ist diese Vorsicht richtig, weil Internetfirmen heute sehr viele Daten über uns sammeln. Aber man darf nicht übertreiben: Ein Haus auf einem Foto ist kein großes Geheimnis.*\n\n**Éléments attendus**\n- Repères : 1983 (Cour constitutionnelle, *Recht auf informationelle Selbstbestimmung*) ; 2010 (des centaines de milliers d'Allemands font flouter leur maison sur Street View) ; 2018 (RGPD = *DSGVO*). Deux au moins, datés juste.\n- Explication : la mémoire de deux polices politiques (Gestapo, Stasi) ; la Stasi espionnait jusque dans les familles, ce que l'ouverture des archives a révélé.\n- Avis : pour ou contre, mais justifié (ex. : les entreprises du numérique ; ou : l'excès de prudence).\n- Langue : *Privatsphäre, Datenschutz, Überwachung, Öffentlichkeit* ; verbe à la fin après *weil, dass, wer* ; inversion après un complément en tête (*2010 wollten …*)."}$exo$::jsonb),
  ('ee5fe090-648b-57be-ad5c-463c95e99d5b'::uuid, 1, 'traduction', $exo${"titre":"Die Mauer in wenigen Sätzen","consigne":"Traduis le texte en français (version), puis réponds à la question 2.","enonce":"**Texte (inventé, d'après le cours).**\n\n> Die DDR baute die Mauer am 13. August 1961. Mehr als 140 Menschen starben in Berlin an der Mauer. Am 9. November 1989 fiel sie. Heute zeigt die East Side Gallery 1,3 Kilometer bemalte Mauer, und eine doppelte Reihe von Pflastersteinen markiert ihren Verlauf in der Stadt.\n\n*Aide : der Pflasterstein = le pavé ; der Verlauf = le tracé.*\n\n1. Traduis le texte en français.\n2. Donne le sens de ces trois mots du chapitre : *die Gedenkstätte*, *die Spur*, *das Erbe*.","bareme":[{"critere":"Traduction fidèle : dates, chiffres, prétérits (baute, starben, fiel) rendus sans contresens","points":11},{"critere":"Sens juste des trois mots de vocabulaire (2 points chacun)","points":6},{"critere":"Français correct (accord de « il » pour die Mauer, temps du passé cohérents)","points":3}],"dureeMin":7,"corrige":"**1. Traduction proposée**\n« La RDA a construit le Mur le 13 août 1961. Plus de 140 personnes sont mortes au Mur à Berlin. Le 9 novembre 1989, il est tombé. Aujourd'hui, l'East Side Gallery montre 1,3 kilomètre de mur peint, et une double rangée de pavés marque son tracé dans la ville. »\n\nPoints de vigilance :\n- *baute* (prétérit de *bauen*) → « a construit » (ou « construisit ») ; *starben* (*sterben*) → « sont mortes » ; *fiel* (*fallen*) → « est tombé ».\n- *sie* reprend *die Mauer* (féminin en allemand) → « il » en français (le Mur).\n- *bemalte Mauer* → « mur peint » ; *ihren Verlauf* → « son tracé ».\n\n**2. Vocabulaire**\n- *die Gedenkstätte* : le mémorial ;\n- *die Spur* (pl. *die Spuren*) : la trace ;\n- *das Erbe* : l'héritage."}$exo$::jsonb),
  ('ee5fe090-648b-57be-ad5c-463c95e99d5b'::uuid, 2, 'traduction', $exo${"titre":"Le 9 novembre, jour du destin","consigne":"Réponds en français aux questions 1 et 2, puis en allemand à la question 3.","enonce":"**Document : quatre fois le 9 novembre.**\n\n| Jahr | Ereignis |\n| 1918 | Ausrufung der Republik |\n| 1923 | Hitlers gescheiterter Putsch in München |\n| 1938 | Pogrome der « Kristallnacht » |\n| 1989 | Fall der Mauer |\n\n*Aide : die Ausrufung = la proclamation ; gescheitert = manqué, raté ; der Nationalfeiertag = la fête nationale ; der Schicksalstag = le jour du destin ; die Wiedervereinigung = la réunification.*\n\n1. Traduis les quatre lignes du tableau.\n2. Explique pourquoi l'Allemagne a choisi le **3 octobre** et non le 9 novembre comme fête nationale.\n3. **En allemand**, écris trois ou quatre phrases pour présenter le 9 novembre à un correspondant. Commence par : *Der 9. November ist ein Schicksalstag, weil …*","bareme":[{"critere":"Les quatre lignes traduites sans contresens","points":6},{"critere":"Explication juste : 3 octobre = réunification de 1990 ; on ne peut pas fêter le jour des pogroms","points":6},{"critere":"Production allemande : contenu exact et complet (plusieurs 9 novembre, choix du 3 octobre)","points":5},{"critere":"Langue allemande : verbe final après weil, prétérit ou parfait corrects","points":3}],"dureeMin":12,"corrige":"**1. Traduction**\n- 1918 : proclamation de la République.\n- 1923 : putsch manqué d'Hitler à Munich.\n- 1938 : pogroms de la « nuit de Cristal ».\n- 1989 : chute du Mur.\n\n**2.** Le 9 novembre réunit des événements heureux (la République en 1918, la chute du Mur en 1989) et des événements sombres (le putsch d'Hitler en 1923, les pogroms de 1938). Cette date est trop chargée : on ne pouvait pas célébrer le jour des pogroms. On a donc préféré le **3 octobre**, jour de la **réunification** de 1990.\n\n**3. Modèle**\n*Der 9. November ist ein Schicksalstag, weil an diesem Tag viel passiert ist. 1918 wurde die Republik ausgerufen, und 1989 fiel die Mauer. Aber 1923 versuchte Hitler in München einen Putsch, und 1938 gab es die Pogrome der « Kristallnacht ». Deshalb ist der 9. November kein Nationalfeiertag: Man kann den Tag der Pogrome nicht feiern. Unser Nationalfeiertag ist der 3. Oktober, der Tag der Wiedervereinigung.*\n\nÉléments attendus : au moins un événement heureux et un événement sombre ; le 3 octobre et la réunification ; *weil … ist* avec le verbe à la fin."}$exo$::jsonb),
  ('ee5fe090-648b-57be-ad5c-463c95e99d5b'::uuid, 3, 'traduction', $exo${"titre":"Zerstören oder bewahren ?","consigne":"Rédige en allemand un texte argumenté d'environ 150 mots, en t'appuyant sur les deux documents. Emploie au moins une fois le verbe gedenken avec le génitif.","enonce":"**Documents (résumés d'après le cours).**\n\n> **Prora (Rügen)** : Die Nazis wollten hier für « Kraft durch Freude » ein Seebad von 4,5 Kilometern bauen. Es wurde nie fertig. Heute gibt es dort Wohnungen, eine Jugendherberge und ein Dokumentationszentrum.\n\n> **Der « Nischel » (Chemnitz)** : ein über sieben Meter hoher Kopf von Karl Marx, 1971 in der DDR aufgestellt. Die Stadt hat ihn behalten; heute ist er ihr Wahrzeichen.\n\n*Aide : das Seebad = la station balnéaire ; die Jugendherberge = l'auberge de jeunesse ; das Wahrzeichen = l'emblème ; bewahren = conserver.*\n\n**Sujet.** *Was soll man mit einem schwierigen Erbe machen?*\n1. Présente les deux lieux.\n2. Explique le choix allemand face à un patrimoine embarrassant.\n3. Donne ton avis.","bareme":[{"critere":"Les deux lieux présentés avec exactitude (origine, usage actuel)","points":5},{"critere":"Le choix « garder et documenter » expliqué : détruire efface la preuve, conserver sans expliquer glorifie","points":5},{"critere":"Avis personnel justifié","points":3},{"critere":"gedenken + génitif employé correctement (ex. der Opfer gedenken)","points":2},{"critere":"Langue : vocabulaire du chapitre (Erbe, Spuren, Gedenkstätte), syntaxe, connecteurs","points":5}],"dureeMin":20,"corrige":"**Texte modèle (≈ 150 mots)**\n\n*In Deutschland gibt es viele schwierige Orte. In Prora, auf der Insel Rügen, wollten die Nazis ein riesiges Seebad für « Kraft durch Freude » bauen. Es wurde nie fertig. Heute wohnen dort Menschen, und junge Leute schlafen in der Jugendherberge. Aber es gibt auch ein Dokumentationszentrum, das die Geschichte erklärt. In Chemnitz steht noch der Kopf von Karl Marx aus der DDR-Zeit: Die Stadt hat ihn nicht zerstört, er ist ihr Wahrzeichen geworden.*\n\n*Warum behält man solche Orte? Wer zerstört, löscht die Beweise. Wer ohne Erklärung bewahrt, verherrlicht. Deshalb wählt Deutschland einen dritten Weg: bewahren und dokumentieren. So kann man der Opfer gedenken und aus der Geschichte lernen.*\n\n*Ich finde diesen Weg richtig, denn die Spuren der Vergangenheit sind ein Erbe, auch wenn es schwer ist. Ein Ort, den man erklärt, wird eine Lektion.*\n\n**Éléments attendus**\n- Prora : complexe balnéaire nazi de 4,5 km, jamais achevé ; aujourd'hui appartements, auberge de jeunesse, centre de documentation.\n- Nischel : tête de Marx de plus de 7 m érigée en 1971 en RDA, gardée, devenue emblème de la ville.\n- Le principe du cours : détruire efface la preuve ; conserver sans expliquer glorifie ; d'où « garder et documenter ».\n- *gedenken* + génitif : *der Opfer gedenken*, *der Geschichte gedenken* (pas *an die Opfer gedenken*)."}$exo$::jsonb),
  ('70f21318-eef6-5f3a-b7b7-b1116b0f6db5'::uuid, 1, 'traduction', $exo${"titre":"Réalité ou mythe ?","consigne":"Réponds en français, en quelques phrases précises.","enonce":"**1.** Pour chacune de ces trois figures, dis **qui elle était dans la réalité** (ou si elle est fictive) et **quel mythe** on a construit autour d'elle :\n- a) Arminius (« Hermann ») ;\n- b) Barberousse ;\n- c) Siegfried.\n\n**2.** Traduis ces deux formules et donne leur contexte (date, événement) :\n- a) « *Wir sind wieder wer* » ;\n- b) « *Wir sind das Volk* ».","bareme":[{"critere":"Réalité et mythe de chacune des trois figures, exacts (4 points par figure)","points":12},{"critere":"Les deux formules traduites et replacées dans leur contexte (4 points chacune)","points":8}],"dureeMin":7,"corrige":"**1.**\n- a) **Arminius** : chef germain réel qui écrase trois légions romaines dans la forêt de Teutobourg en l'an 9. Mythe : le libérateur de la Germanie ; une statue géante, le *Hermannsdenkmal*, est achevée en 1875.\n- b) **Barberousse** : l'empereur réel Frédéric Ier, mort en 1190 pendant une croisade. Mythe : il dormirait dans la montagne du Kyffhäuser et se réveillerait pour sauver l'Allemagne.\n- c) **Siegfried** : personnage **de fiction** de la *Chanson des Nibelungen*. Mythe : le héros tueur de dragon, repris par Wagner.\nOn peut ajouter qu'au XIXe siècle, ces figures ont servi le nationalisme, puis ont été récupérées par les nazis.\n\n**2.**\n- a) « Nous revoilà quelqu'un » : après le « miracle de Berne », la victoire de la RFA sur la Hongrie (3 à 2) en finale de la Coupe du monde, le 4 juillet 1954.\n- b) « Nous sommes le peuple » : slogan des manifestations du lundi à Leipzig pendant la révolution pacifique de l'automne 1989 en RDA."}$exo$::jsonb),
  ('70f21318-eef6-5f3a-b7b7-b1116b0f6db5'::uuid, 2, 'traduction', $exo${"titre":"Le miracle de Berne raconté par un grand-père","consigne":"Lis le texte, puis réponds en français aux questions 1 à 3 et traduis la phrase demandée à la question 4.","enonce":"**Texte (témoignage inventé).**\n\n> Mein Großvater erzählt oft vom 4. Juli 1954. Er war damals zwölf Jahre alt. Das ganze Dorf hörte das Spiel im Radio. Ungarn war der große Favorit, aber Deutschland gewann 3 zu 2. « Nach dem Krieg hatten wir nichts », sagt er, « aber an diesem Tag waren wir wieder wer. » Ein paar Jahre später hatte seine Familie ein Auto und einen Fernseher: Das war das Wirtschaftswunder.\n\n1. Relève les informations précises sur l'événement (date, adversaire, score).\n2. Explique pourquoi ce match est souvent présenté comme la vraie naissance émotionnelle de la RFA.\n3. D'après le cours, qu'est-ce que le *Wirtschaftswunder* et quelles en sont les causes ?\n4. Traduis la phrase du grand-père : « *Nach dem Krieg hatten wir nichts, aber an diesem Tag waren wir wieder wer.* »","bareme":[{"critere":"Date, adversaire et score relevés exactement","points":4},{"critere":"Sens du match expliqué : fierté retrouvée d'un pays vaincu et en ruines","points":6},{"critere":"Wirtschaftswunder défini et ses trois causes du cours données","points":5},{"critere":"Traduction juste et naturelle de la phrase","points":5}],"dureeMin":11,"corrige":"**1.** Le 4 juillet 1954 ; l'adversaire est la **Hongrie**, grande favorite ; la RFA gagne **3 à 2** (finale de la Coupe du monde, à Berne).\n\n**2.** En 1954, la RFA est un pays vaincu, sorti de la guerre et du nazisme en ruines. Cette victoire inattendue contre la favorite donne aux Allemands de l'Ouest une fierté collective qu'ils n'osaient plus éprouver : « *Wir sind wieder wer* », « nous revoilà quelqu'un ». Le texte le montre : tout le village écoute le match ensemble, et le grand-père oppose « nous n'avions rien » à « nous étions de nouveau quelqu'un ». C'est pour beaucoup la naissance émotionnelle de la RFA.\n\n**3.** Le *Wirtschaftswunder* (« miracle économique ») désigne le redressement très rapide de la RFA dans les années 1950 : en ruines en 1945, elle devient une grande puissance industrielle. Causes données par le cours : la **réforme monétaire**, le **plan Marshall** et le **travail**. Dans le texte, la voiture et le téléviseur de la famille en sont les signes.\n\n**4.** « Après la guerre, nous n'avions rien, mais ce jour-là, nous étions de nouveau quelqu'un (nous revoilà quelqu'un). »\nAccepter « on n'avait rien », « on était redevenus quelqu'un »."}$exo$::jsonb),
  ('70f21318-eef6-5f3a-b7b7-b1116b0f6db5'::uuid, 3, 'traduction', $exo${"titre":"Helden und Vorbilder","consigne":"Rédige en allemand un texte argumenté d'environ 150 mots. Appuie-toi sur au moins deux exemples précis du cours.","enonce":"**Sujet.**\n\n> *« Eine Diktatur macht sich Helden, eine Demokratie wählt sich Vorbilder. »* (formule tirée du cours)\n\nExplique et discute cette phrase :\n1. Compare **Sophie Scholl** et **Hitlerjunge Quex** : réalité ou fabrication ? dans quel but ?\n2. Montre avec un autre exemple du cours (les héros fondateurs récupérés, ou 1989) qu'un récit peut servir une nation.\n3. Conclus : où est la différence entre un héros de propagande et un modèle ?\n\n*Aide : das Vorbild = le modèle ; die Propaganda ; erfinden = inventer ; die Wahrheit = la vérité ; der Mut = le courage.*","bareme":[{"critere":"Sophie Scholl et Quex présentés avec exactitude (Rose blanche, exécution en 1943 ; film de propagande de 1933)","points":5},{"critere":"Second exemple du cours pertinent et exact","points":3},{"critere":"Analyse de la différence : le rapport à la vérité, embrigader ou inspirer","points":5},{"critere":"Langue allemande : vocabulaire du chapitre, syntaxe, connecteurs","points":7}],"dureeMin":20,"corrige":"**Texte modèle (≈ 150 mots)**\n\n*Jede Nation erzählt sich Geschichten, aber nicht alle Helden sind gleich. Sophie Scholl war eine echte Studentin der « Weißen Rose ». Sie verteilte Flugblätter gegen Hitler und wurde am 22. Februar 1943 hingerichtet. Heute ist sie ein Vorbild für Zivilcourage. « Hitlerjunge Quex » ist dagegen der Held eines Propagandafilms von 1933: Man hat einen getöteten jungen Nazi zum Märtyrer gemacht, um die Jugend zu begeistern.*\n\n*Auch alte Mythen wurden benutzt: Arminius und Barbarossa dienten im 19. Jahrhundert dem Nationalismus, dann haben die Nazis sie übernommen. Nach 1989 ist die friedliche Revolution zu einem neuen Gründungsmythos geworden, aber sie ist wirklich passiert.*\n\n*Der Unterschied liegt also in der Wahrheit: Eine Diktatur erfindet Helden, damit die Menschen gehorchen. Eine Demokratie wählt echte Menschen als Vorbilder, damit die Bürger selbst denken und mutig sind.*\n\n**Éléments attendus**\n- Sophie Scholl : résistante réelle de la Rose blanche, exécutée le 22 février 1943 pour des tracts contre Hitler ; modèle de courage civique.\n- Quex : fiction de propagande (film de 1933) inspirée d'un jeune nazi tué et transformé en martyr, pour embrigader la jeunesse.\n- Second exemple : héros fondateurs au service du nationalisme puis récupérés par les nazis, ou 1989 (*Wir sind das Volk*), récit fondateur réel.\n- Idée clé : la différence tient au rapport à la vérité."}$exo$::jsonb),
  ('e42ff1a4-10cd-5b56-a0d7-2b9b806b939c'::uuid, 1, 'traduction', $exo${"titre":"Cinq formules qui ont marqué l'Allemagne","consigne":"Pour chaque formule, donne une traduction en français, puis son auteur ou son contexte et sa date.","enonce":"**Formules.**\n\n1. « *Vorsprung durch Technik* »\n2. « *Wir sind das Volk* »\n3. « *Mehr Demokratie wagen* »\n4. « *Ich bin ein Berliner* »\n5. « *blühende Landschaften* »\n\n*Aide : der Vorsprung = l'avance ; wagen = oser ; blühen = fleurir.*","bareme":[{"critere":"Traductions justes des cinq formules (2 points chacune)","points":10},{"critere":"Auteur ou contexte et date exacts pour chaque formule (2 points chacune)","points":10}],"dureeMin":7,"corrige":"1. « L'avance par la technique » : slogan publicitaire d'**Audi**, connu même à l'étranger (pas de date au programme : le contexte publicitaire suffit).\n2. « Nous sommes le peuple » : slogan des **manifestations de 1989** en RDA (manifestations du lundi, Leipzig).\n3. « Oser plus de démocratie » : **Willy Brandt**, en **1969**.\n4. « Je suis un Berlinois » : **John F. Kennedy**, en **1963**, en signe de solidarité avec Berlin-Ouest encerclé.\n5. « Des paysages florissants » : promesse d'**Helmut Kohl** en **1990** sur la prospérité rapide de l'Est après la réunification ; la formule est devenue ironique face au chômage.\n\nBarème : pour la formule 1, le contexte (publicité d'Audi) vaut les 2 points."}$exo$::jsonb),
  ('e42ff1a4-10cd-5b56-a0d7-2b9b806b939c'::uuid, 2, 'traduction', $exo${"titre":"Quand une formule se retourne","consigne":"Lis le document, réponds en français aux questions 1 à 3, puis en allemand à la question 4.","enonce":"**Document (récit simplifié, écrit pour l'exercice).**\n\n> Am Abend des 9. November 1989 liest Günter Schabowski vor der Presse eine neue Regel vor: Die DDR-Bürger dürfen reisen. Ein Journalist fragt: « Ab wann? » Schabowski sucht in seinen Papieren und sagt: « sofort, unverzüglich ». In der Nacht fällt die Mauer.\n\n1. Résume le document en deux phrases.\n2. Pourquoi dit-on que cette annonce était **confuse** ? Quelle en fut la conséquence ?\n3. Explique pourquoi les « *blühende Landschaften* » promises par Helmut Kohl en 1990 sont devenues une formule **ironique**.\n4. **En allemand**, écris deux ou trois phrases qui complètent : *Eine Formel kann sich gegen ihren Autor wenden, weil …*","bareme":[{"critere":"Résumé exact du document","points":4},{"critere":"Annonce confuse expliquée et conséquence donnée (le Mur tombe dans la nuit)","points":5},{"critere":"Ironie des blühende Landschaften expliquée (promesse de prospérité / chômage à l'Est)","points":5},{"critere":"Production allemande pertinente et correcte (verbe final après weil)","points":6}],"dureeMin":11,"corrige":"**1.** Le soir du 9 novembre 1989, Günter Schabowski lit devant la presse une nouvelle règle qui permet aux citoyens de RDA de voyager. Quand un journaliste demande à partir de quand, il répond « immédiatement, sans délai », et le Mur tombe dans la nuit.\n\n**2.** Schabowski cherche dans ses papiers : il n'est pas sûr de ce qu'il annonce, et sa réponse « *sofort, unverzüglich* » (immédiatement, sans délai) fait croire que les frontières sont ouvertes tout de suite. Conséquence : la foule se presse aux postes-frontières et le Mur tombe dans la nuit. Une phrase improvisée a changé l'histoire.\n\n**3.** En 1990, Helmut Kohl promet à l'Est des « paysages florissants », c'est-à-dire une prospérité rapide après la réunification. Mais le chômage frappe l'Est : la formule, rappelée plus tard, souligne l'écart entre la promesse et la réalité et se retourne contre son auteur.\n\n**4. Modèle**\n*Eine Formel kann sich gegen ihren Autor wenden, weil man sie nie vergisst. Helmut Kohl hat 1990 « blühende Landschaften » versprochen, aber viele Menschen im Osten waren arbeitslos. Heute benutzt man diese Worte ironisch.*\nAccepter toute idée juste ; exiger le verbe à la fin après *weil*."}$exo$::jsonb),
  ('e42ff1a4-10cd-5b56-a0d7-2b9b806b939c'::uuid, 3, 'traduction', $exo${"titre":"Die Presse, die vierte Gewalt","consigne":"Rédige en allemand un texte argumenté d'environ 150 mots, en t'appuyant sur le document et sur le cours.","enonce":"**Document : quelques médias allemands.**\n\n| Medium | Besonderheit |\n| *Tagesschau* (ARD) | Nachrichten im Fernsehen seit 1952 |\n| *Der Spiegel* | Wochenmagazin, recherchiert und deckt Skandale auf |\n| *Süddeutsche Zeitung*, *FAZ* | große überregionale Tageszeitungen |\n| *Bild* | populäre Zeitung mit Sensationen, sehr viel gelesen |\n\n*Aide : die vierte Gewalt = le quatrième pouvoir ; die Gebühr = la redevance ; der Haushalt = le foyer ; unabhängig = indépendant ; kontrollieren = contrôler.*\n\n**Sujet.** *Warum ist eine unabhängige Presse für die Demokratie wichtig?*\n1. Explique l'expression « quatrième pouvoir ».\n2. Présente la diversité des médias allemands.\n3. Explique pourquoi ARD et ZDF sont financées par une redevance, en lien avec l'histoire allemande.","bareme":[{"critere":"Quatrième pouvoir expliqué : la presse contrôle les trois pouvoirs par l'information","points":4},{"critere":"Diversité des médias présentée avec au moins trois titres exacts","points":4},{"critere":"Redevance et leçon historique (propagande nazie et de la RDA) expliquées","points":5},{"critere":"Langue allemande : vocabulaire (Pressefreiheit, Nachrichten), syntaxe, connecteurs","points":7}],"dureeMin":20,"corrige":"**Texte modèle (≈ 150 mots)**\n\n*Man nennt die Presse die « vierte Gewalt », weil sie die drei anderen Gewalten kontrolliert: Sie informiert die Bürger und zeigt, was die Politiker tun.*\n\n*In Deutschland gibt es viele verschiedene Medien. Die Tagesschau der ARD bringt seit 1952 die wichtigsten Nachrichten. Der Spiegel ist ein Wochenmagazin, das recherchiert und Skandale aufdeckt. Die Süddeutsche Zeitung und die FAZ sind große Tageszeitungen, und die Bild-Zeitung ist sehr populär, aber sie mag Sensationen.*\n\n*ARD und ZDF werden durch eine Gebühr finanziert, die jeder Haushalt bezahlt. Warum? Die Deutschen haben aus ihrer Geschichte gelernt: Die Nazis und die DDR haben die Medien für ihre Propaganda benutzt. Eine unabhängige Information soll deshalb weder vom Staat noch von der Werbung abhängen. Für mich ist die Pressefreiheit die Grundlage der Demokratie: Ohne freie Presse kann man nicht frei wählen.*\n\n**Éléments attendus**\n- Quatrième pouvoir : contrôle des pouvoirs par l'information.\n- Au moins trois médias exacts (Tagesschau depuis 1952, Spiegel hebdomadaire d'investigation, SZ/FAZ quotidiens nationaux, Bild quotidien populaire à sensation).\n- Redevance payée par chaque foyer ; leçon tirée de la propagande nazie et de la RDA : garantir une information indépendante."}$exo$::jsonb),
  ('ff33c871-1fdd-5899-9cf3-a995b1cb8ec5'::uuid, 1, 'traduction', $exo${"titre":"Un message sur les réseaux","consigne":"Traduis le texte en français (version), puis réponds aux questions 2 et 3 en français.","enonce":"**Texte (inventé).**\n\n> In den sozialen Netzwerken liest man viele Falschmeldungen, und manche Nutzer schreiben Hassrede. Aber die Meinungsfreiheit ist wichtig, und viele junge Leute engagieren sich online für das Klima.\n\n*Aide : der Nutzer = l'utilisateur.*\n\n1. Traduis le texte en français.\n2. Que signifient *die künstliche Intelligenz (KI)* et *ein Deepfake* ?\n3. Que prévoit la loi allemande *NetzDG* de 2017 ?","bareme":[{"critere":"Traduction fidèle (Falschmeldungen, Hassrede, Meinungsfreiheit, sich engagieren justes)","points":10},{"critere":"KI et Deepfake correctement définis","points":5},{"critere":"NetzDG expliquée : suppression rapide des contenus manifestement illégaux par les grandes plateformes","points":5}],"dureeMin":7,"corrige":"**1. Traduction proposée**\n« Sur les réseaux sociaux, on lit beaucoup de fausses informations, et certains utilisateurs écrivent des discours de haine. Mais la liberté d'expression est importante, et beaucoup de jeunes s'engagent en ligne pour le climat. »\n\nPoints de vigilance : *man liest* → « on lit » ; *die Falschmeldung(en)* → fausse(s) information(s), infox ; *die Hassrede* → le discours de haine ; *die Meinungsfreiheit* → la liberté d'expression (pas « de la presse ») ; *sich engagieren für* → s'engager pour.\n\n**2.** *Die künstliche Intelligenz (KI)* : l'intelligence artificielle. *Ein Deepfake* : une fausse image ou une fausse voix fabriquée par l'IA.\n\n**3.** La loi *NetzDG* (2017) oblige les grandes plateformes à **supprimer rapidement les contenus manifestement illégaux**, pour lutter contre la haine en ligne. L'Union européenne a ensuite pris le relais avec le règlement sur les services numériques."}$exo$::jsonb),
  ('ff33c871-1fdd-5899-9cf3-a995b1cb8ec5'::uuid, 2, 'traduction', $exo${"titre":"Hashtagaktivismus : engagement réel ou clic ?","consigne":"Lis les deux avis, réponds en français aux questions 1 et 2, puis en allemand à la question 3.","enonce":"**Deux avis (inventés).**\n\n> **Paul, 17 Jahre** : « Ein Klick ist kein echtes Engagement. Man teilt einen Hashtag und denkt, man hat etwas getan. »\n\n> **Mira, 18 Jahre** : « Der Hashtag öffnet die Debatte. Danach gehen die Leute auf die Straße und wählen. »\n\n1. Présente les deux positions en une ou deux phrases chacune.\n2. Présente les trois mouvements du cours (*#aufschrei*, *#MeTwo*, *Fridays for Future*) : date quand le cours la donne, et cause défendue.\n3. **En allemand**, donne ton avis en quatre ou cinq phrases. Emploie au moins une fois *sich engagieren* et mentionne un outil officiel de participation.","bareme":[{"critere":"Les deux positions reformulées fidèlement","points":4},{"critere":"Les trois mouvements exacts (dates et causes)","points":6},{"critere":"Avis allemand argumenté, avec sich engagieren et la pétition en ligne au Bundestag","points":6},{"critere":"Correction de la langue allemande","points":4}],"dureeMin":12,"corrige":"**1.** Paul pense qu'un clic ne remplace pas un engagement réel : partager un hashtag donne l'illusion d'avoir agi. Mira pense au contraire que le hashtag ouvre le débat, que la rue et les élections prolongent ensuite. Ce sont la critique fréquente et la réponse des militants présentées dans le cours.\n\n**2.**\n- *#aufschrei* (2013) : témoignages sur le sexisme au quotidien.\n- *#MeTwo* (2018) : témoignages de racisme vécu par des personnes issues de l'immigration.\n- *Fridays for Future* : grèves pour le climat, organisées largement en ligne.\n\n**3. Modèle**\n*Ich finde, dass beide recht haben. Ein Hashtag allein ändert nichts, aber er macht ein Problem sichtbar. Mit #MeTwo haben viele Menschen über Rassismus gesprochen. Wer sich wirklich engagieren will, muss danach handeln. Man kann zum Beispiel eine Online-Petition an den Bundestag schreiben: Das ist ein offizielles Mittel der Beteiligung.*\n\nÉléments attendus : un avis clair ; *sich engagieren* correctement conjugué (*ich engagiere mich*, *man engagiert sich*) ; mention des pétitions en ligne au Bundestag."}$exo$::jsonb),
  ('ff33c871-1fdd-5899-9cf3-a995b1cb8ec5'::uuid, 3, 'traduction', $exo${"titre":"Kann man den Medien noch vertrauen ?","consigne":"Rédige en allemand un texte argumenté d'environ 150 mots, en t'appuyant sur au moins trois repères du cours.","enonce":"**Sujet.**\n\n> *Falschmeldungen, Deepfakes, Skandale: Kann man den Medien noch vertrauen?*\n\nTon texte doit :\n1. présenter l'**affaire du Spiegel** (1962) et l'**affaire Relotius** (2018) et dire ce que chacune révèle ;\n2. évoquer le défi des **infox** et de l'**intelligence artificielle** ;\n3. conclure en expliquant d'où vient la confiance dans les médias.\n\n*Aide : das Vertrauen = la confiance ; der Reporter ; erfinden = inventer ; zugeben = reconnaître ; korrigieren = corriger ; verhaften = arrêter.*","bareme":[{"critere":"Affaire du Spiegel exacte (journalistes arrêtés, départ de Strauß, victoire de la liberté de la presse)","points":4},{"critere":"Affaire Relotius exacte (passages inventés, enquête et publication par le journal lui-même)","points":4},{"critere":"Infox et IA évoquées (Deepfakes, DeepL ou règlement européen de 2024)","points":3},{"critere":"Conclusion : la confiance vient de la capacité à reconnaître et corriger les erreurs","points":3},{"critere":"Langue allemande : vocabulaire, syntaxe, connecteurs","points":6}],"dureeMin":20,"corrige":"**Texte modèle (≈ 150 mots)**\n\n*Heute zweifeln viele Menschen an den Medien. Aber die Geschichte des Spiegels zeigt zwei Seiten. 1962 hat der Spiegel einen kritischen Artikel über die Armee veröffentlicht. Die Polizei hat Journalisten verhaftet, aber der Skandal war so groß, dass der Minister Franz Josef Strauß gehen musste: Die Pressefreiheit hat gewonnen.*\n\n*2018 hat man entdeckt, dass Claas Relotius, ein Starreporter des Spiegels, Teile seiner Reportagen erfunden hatte. Das Magazin hat selbst recherchiert und alles veröffentlicht.*\n\n*Heute ist die Gefahr größer: Falschmeldungen verbreiten sich schneller als die Korrekturen, und die künstliche Intelligenz kann falsche Bilder und Stimmen herstellen, die Deepfakes. 2024 hat die EU deshalb ein erstes Gesetz über die KI beschlossen.*\n\n*Kann man den Medien also vertrauen? Ich denke ja, aber nicht blind. Vertrauen kommt nicht daher, dass Journalisten keine Fehler machen, sondern daher, dass sie ihre Fehler zugeben und korrigieren.*\n\n**Éléments attendus** : les deux affaires exactes ; infox plus rapides que les démentis ; Deepfakes ; éventuellement DeepL (Cologne) ou le règlement européen sur l'IA de 2024 ; l'idée conclusive du cours. Le prénom du reporter n'est pas exigé."}$exo$::jsonb),
  ('5b3bdc41-23b2-56c4-b8d8-1685a0f84532'::uuid, 1, 'traduction', $exo${"titre":"Qui a fait quoi ?","consigne":"Réponds en français, avec précision.","enonce":"**1.** Associe chaque nom à son mouvement ou à son œuvre, et donne une date quand le cours en donne une :\n\n| Nom | Mouvement ou œuvre |\n| a) Kant | ? |\n| b) Schiller | ? |\n| c) les frères Grimm | ? |\n| d) Fritz Lang | ? |\n| e) Pina Bausch | ? |\n\n**2.** Traduis et explique en une phrase :\n- a) « *Land der Dichter und Denker* » ;\n- b) « *Tanzt, tanzt, sonst sind wir verloren* ».","bareme":[{"critere":"Les cinq associations justes, avec les dates du cours (2 points chacune)","points":10},{"critere":"Les deux formules traduites et expliquées (5 points chacune)","points":10}],"dureeMin":8,"corrige":"**1.**\n- a) **Kant** : les Lumières (*Aufklärung*) ; « *Sapere aude!* Aie le courage de te servir de ton propre entendement » (1784).\n- b) **Schiller** : le classicisme de Weimar ; l'*Ode à la joie*, mise en musique par Beethoven, devenue l'hymne européen.\n- c) **Les frères Grimm** : le romantisme (le rêve, la nature, les contes).\n- d) **Fritz Lang** : le cinéma ; *Metropolis* (1927), *M le maudit* (1931).\n- e) **Pina Bausch** : la danse ; elle dirige à partir de 1973 le *Tanztheater Wuppertal*, un « théâtre dansé ».\n\n**2.**\n- a) « Le pays des poètes et des penseurs » : la formule rend hommage aux grands écrivains (Goethe, Schiller, Lessing) et dit l'attachement de l'Allemagne à la culture, qui a construit son identité avant même l'État.\n- b) « Dansez, dansez, sinon nous sommes perdus » : pour Pina Bausch, la danse est une nécessité vitale, une façon de dire et de penser le monde, pas un simple divertissement."}$exo$::jsonb),
  ('5b3bdc41-23b2-56c4-b8d8-1685a0f84532'::uuid, 2, 'traduction', $exo${"titre":"Brecht et l'effet de distanciation","consigne":"Lis la description, réponds en français aux questions 1 et 2, puis en allemand à la question 3.","enonce":"**Description d'une mise en scène (inventée).**\n\n> In einer Schulinszenierung von « Mutter Courage » tragen die Schauspieler Schilder mit dem Jahr und dem Ort. Mitten in einer traurigen Szene singt Mutter Courage ein Lied. Dann wendet sich ein Schauspieler an das Publikum und fragt: « Wer verdient am Krieg? »\n\n*Aide : das Schild = la pancarte ; sich wenden an = s'adresser à ; verdienen an = gagner de l'argent grâce à.*\n\n1. Relève **trois procédés** de distanciation dans cette mise en scène.\n2. Explique le but du **théâtre épique** de Brecht et ce que raconte *Mère Courage* (1939).\n3. **En allemand**, écris trois ou quatre phrases qui commencent par : *Der Zuschauer soll nicht weinen, sondern …*","bareme":[{"critere":"Trois procédés relevés (pancartes, chanson, acteur qui s'adresse au public)","points":6},{"critere":"But du théâtre épique et sujet de Mère Courage expliqués exactement","points":6},{"critere":"Production allemande pertinente (réfléchir, se souvenir qu'on est au théâtre)","points":5},{"critere":"Correction de la langue allemande (nicht … sondern, modal + infinitif à la fin)","points":3}],"dureeMin":11,"corrige":"**1.** Les pancartes avec l'année et le lieu ; la chanson au milieu d'une scène triste ; l'acteur qui s'adresse directement au public et lui pose une question. Ces trois procédés font partie de l'**effet de distanciation** (*Verfremdungseffekt*) : ils rappellent qu'on est au théâtre.\n\n**2.** Brecht invente le **théâtre épique** : au lieu de faire pleurer le spectateur en l'identifiant aux personnages, il veut le **faire réfléchir**. *Mère Courage* (1939) montre une femme qui vit de la guerre et y perd ses enfants : la question « qui gagne de l'argent grâce à la guerre ? » invite le public à juger ce commerce plutôt qu'à s'émouvoir seulement.\n\n**3. Modèle**\n*Der Zuschauer soll nicht weinen, sondern nachdenken. Die Schilder und die Lieder erinnern ihn daran, dass er im Theater ist. Er soll verstehen, warum Mutter Courage ihre Kinder verliert. Für Brecht ist das Theater kein Spiegel, sondern ein Hammer.*\n\nÉléments attendus : l'idée de réflexion ; *nicht … sondern* ; l'infinitif à la fin après *soll*."}$exo$::jsonb),
  ('5b3bdc41-23b2-56c4-b8d8-1685a0f84532'::uuid, 3, 'traduction', $exo${"titre":"Mehr als Bücher","consigne":"Rédige en allemand un texte argumenté d'environ 150 mots, avec au moins trois exemples précis tirés de trois arts différents.","enonce":"**Sujet.**\n\n> *Das « Land der Dichter und Denker » ist nicht nur ein Land der Bücher.*\n\nMontre que la culture allemande s'exprime aussi par le **cinéma**, le **théâtre** et la **danse**, et qu'on y retrouve la même exigence de penser le monde.\n\nTon texte doit :\n1. expliquer brièvement l'origine de la formule (qui y est honoré) ;\n2. développer **trois exemples** précis (artiste, œuvre, date) ;\n3. conclure sur ce qui relie ces arts.\n\n*Aide : der Film ; das Theaterstück ; die Bühne ; die Inszenierung ; der Tänzer ; nachdenken über = réfléchir à.*","bareme":[{"critere":"Origine de la formule : hommage à Goethe, Schiller, Lessing ; la culture avant l'État","points":3},{"critere":"Trois exemples exacts pris dans trois arts différents (Lang, Brecht, Bausch, Ade…)","points":6},{"critere":"Conclusion reliant les arts : penser le monde","points":4},{"critere":"Langue allemande : vocabulaire du chapitre, syntaxe, connecteurs","points":7}],"dureeMin":20,"corrige":"**Texte modèle (≈ 150 mots)**\n\n*Man nennt Deutschland das « Land der Dichter und Denker ». Die Formel ehrt Goethe, Schiller und Lessing und zeigt, dass die Kultur die deutsche Identität geschaffen hat, lange vor dem Staat. Aber die deutsche Kultur ist mehr als Literatur.*\n\n*Im Kino hat Fritz Lang 1927 « Metropolis » gedreht: In dieser Stadt der Zukunft leben die Arbeiter unter der Erde. Der Film lässt uns über die Gesellschaft nachdenken. Heute zeigt Maren Ade mit « Toni Erdmann » (2016), dass das deutsche Kino lebendig ist.*\n\n*Im Theater wollte Bertolt Brecht nicht, dass der Zuschauer weint. Mit dem Verfremdungseffekt soll er nachdenken, zum Beispiel über den Krieg in « Mutter Courage ».*\n\n*Im Tanz hat Pina Bausch ab 1973 in Wuppertal ein « Tanztheater » geschaffen, in dem die Tänzer sprechen und lachen.*\n\n*Film, Bühne und Tanz haben also dasselbe Ziel wie die Bücher: die Welt verstehen.*\n\n**Éléments attendus** : l'origine de la formule ; trois exemples exacts de trois arts (cinéma : Lang, Fassbinder, Wenders, Herzog, Ade ; théâtre : Brecht ; danse : Bausch, Sasha Waltz) ; la conclusion du cours : film, scène et danse portent la même exigence de penser le monde. Le nom de l'inventeur de la formule n'est pas exigé."}$exo$::jsonb),
  ('bbc3f124-b18d-58cc-8cea-5aef3909bc4b'::uuid, 1, 'traduction', $exo${"titre":"Er sagt, er sei … : cinq paroles à rapporter","consigne":"Mets chaque phrase au discours rapporté avec le subjonctif I (ou le subjonctif II quand le subjonctif I se confond avec l'indicatif), puis traduis deux phrases.","enonce":"**1.** Rapporte ces paroles en commençant par le début donné.\n\n- a) Der Trainer: « Ich bin zufrieden. » → *Der Trainer sagt, …*\n- b) Die Ministerin: « Ich habe keine Angst. » → *Die Ministerin sagt, …*\n- c) Der Schüler: « Ich kann nicht kommen. » → *Der Schüler sagt, …*\n- d) Die Polizisten: « Wir wissen nichts. » → *Die Polizisten sagen, …*\n- e) Die Sängerin: « Ich werde im Mai kommen. » → *Die Sängerin sagt, …*\n\n**2.** Traduis en français les phrases a) et c) de ta réponse en rendant la distance du discours rapporté.","bareme":[{"critere":"Les cinq formes verbales justes : sei, habe, könne, wüssten, werde","points":12},{"critere":"Pronoms changés (ich → er / sie, wir → sie) et verbe à la place attendue","points":4},{"critere":"Traductions qui rendent la distance (« selon lui », « affirme que »…)","points":4}],"dureeMin":8,"corrige":"**1.**\n- a) *Der Trainer sagt, er **sei** zufrieden.*\n- b) *Die Ministerin sagt, sie **habe** keine Angst.*\n- c) *Der Schüler sagt, er **könne** nicht kommen.*\n- d) *Die Polizisten sagen, sie **wüssten** nichts.* — au pluriel, *wissen* au subjonctif I se confond avec l'indicatif (*sie wissen*) : on prend le subjonctif II *wüssten*.\n- e) *Die Sängerin sagt, sie **werde** im Mai kommen.*\n\nRappel : on peut aussi employer *dass* avec le verbe à la fin (*Der Trainer sagt, dass er zufrieden sei*) ; les deux sont acceptés. Barème des formes : a, b, c, e = 2 points chacune, d = 4 points (substitution par le subjonctif II).\n\n**2.**\n- a) « L'entraîneur se dit satisfait. » / « Selon l'entraîneur, il est satisfait. »\n- c) « L'élève affirme qu'il ne peut pas venir. » / « Selon lui, il ne pourrait pas venir. »\nToute traduction qui marque que le locuteur rapporte sans garantir est acceptée."}$exo$::jsonb),
  ('bbc3f124-b18d-58cc-8cea-5aef3909bc4b'::uuid, 2, 'traduction', $exo${"titre":"Un article de presse à décoder","consigne":"Lis l'article, réponds aux questions 1 et 2, puis traduis-le en français.","enonce":"**Article (inventé).**\n\n> Der Bürgermeister erklärte gestern, die Stadt habe genug Geld für ein neues Schwimmbad. Das Projekt sei gut für alle, und die Bauarbeiten würden im Frühling beginnen. Laut der Opposition gibt es aber keinen Plan. Der Bürgermeister soll außerdem ein Grundstück neben dem Schwimmbad gekauft haben. Sein Berater will davon nichts gewusst haben.\n\n*Aide : das Grundstück = le terrain ; der Berater = le conseiller.*\n\n1. Relève les **trois** verbes au subjonctif (I ou II de remplacement) et donne leur infinitif. Explique pourquoi l'un d'eux est au subjonctif II.\n2. Relève **trois autres marqueurs** du discours rapporté et donne leur sens.\n3. Traduis l'article en français en rendant la distance du journaliste.","bareme":[{"critere":"Les trois verbes relevés (habe, sei, würden), infinitifs justes et würden expliqué","points":5},{"critere":"Trois marqueurs relevés et expliqués (laut, soll, will … haben)","points":5},{"critere":"Traduction fidèle du sens","points":6},{"critere":"Distance rendue en français (conditionnel, « selon », « aurait », « prétend »)","points":4}],"dureeMin":12,"corrige":"**1.** *habe* (*haben*), *sei* (*sein*), *würden* (*werden*). Au pluriel, le subjonctif I de *werden* (*sie werden*) se confond avec l'indicatif : on le remplace par le subjonctif II *würden*.\n\n**2.**\n- *laut der Opposition* : selon l'opposition ;\n- *soll … gekauft haben* : on dit qu'il a acheté, il aurait acheté ;\n- *will … nichts gewusst haben* : il prétend n'en avoir rien su.\n\n**3. Traduction proposée**\n« Le maire a déclaré hier que la ville avait (aurait) assez d'argent pour une nouvelle piscine. Le projet serait bon pour tout le monde, et les travaux commenceraient au printemps. Selon l'opposition, il n'existe pourtant aucun plan. Le maire aurait en outre acheté un terrain à côté de la piscine. Son conseiller prétend ne rien en avoir su. »\n\nPoints de vigilance : le conditionnel français (« serait », « commenceraient », « aurait acheté ») rend la distance ; *soll* n'exprime pas ici une obligation (« doit avoir acheté » est un contresens) ; *will … gewusst haben* ≠ « veut savoir »."}$exo$::jsonb),
  ('bbc3f124-b18d-58cc-8cea-5aef3909bc4b'::uuid, 3, 'traduction', $exo${"titre":"La porte-parole a déclaré que…","consigne":"Rapporte toute la déclaration au discours indirect, justifie tes choix, puis traduis ta version en français.","enonce":"**Déclaration (inventée) de la porte-parole d'un groupe pour le climat.**\n\n> « Wir sind nicht gegen die Stadt. Wir haben alle Regeln respektiert. Morgen werden wir wieder demonstrieren. Die Polizei war sehr freundlich. Ich kann das bestätigen. »\n\n*Aide : bestätigen = confirmer.*\n\n1. Rapporte les cinq phrases au discours indirect, en commençant par : *Die Sprecherin erklärte, …* Tu peux enchaîner les phrases sans répéter le verbe introducteur.\n2. Justifie en français **trois** de tes choix : le temps du subjonctif (présent, passé, futur), le remplacement par le subjonctif II, et le fait que le verbe introducteur au passé ne change pas le temps du subjonctif.\n3. Traduis ta version en français, en employant au moins deux procédés qui marquent la distance.","bareme":[{"critere":"Formes justes : seien, hätten … respektiert, würden … demonstrieren, sei … gewesen, könne","points":8},{"critere":"Pronoms adaptés (wir → sie, ich → sie) et construction correcte","points":3},{"critere":"Trois choix justifiés avec la règle du cours","points":5},{"critere":"Traduction française fidèle, avec deux marqueurs de distance","points":4}],"dureeMin":18,"corrige":"**1. Version attendue**\n*Die Sprecherin erklärte, sie **seien** nicht gegen die Stadt. Sie **hätten** alle Regeln **respektiert**. Morgen (am nächsten Tag) **würden** sie wieder **demonstrieren**. Die Polizei **sei** sehr freundlich **gewesen**. Sie **könne** das bestätigen.*\n\n**2. Justifications**\n- *seien* : subjonctif I de *sein* au pluriel ; *sein* a une conjugaison complète, pas de confusion avec l'indicatif.\n- *hätten … respektiert* : paroles au passé → subjonctif passé (*habe/sei* + participe) ; au pluriel, *haben* se confond avec l'indicatif, donc subjonctif II *hätten*.\n- *würden … demonstrieren* : futur rapporté (*werde* + infinitif) ; au pluriel, *werden* = indicatif → *würden*.\n- *sei … gewesen* : *war* → passé rapporté, toujours *sei* + participe.\n- *könne* : subjonctif I de *können*, distinct de l'indicatif *kann*.\n- Le verbe introducteur est au prétérit (*erklärte*), mais le temps du subjonctif ne dépend **pas** de lui : il dépend du temps des paroles d'origine.\n\n**3. Traduction proposée**\n« La porte-parole a déclaré qu'ils n'étaient pas contre la ville. Selon elle, ils auraient respecté toutes les règles et manifesteraient de nouveau le lendemain. La police aurait été très aimable ; elle affirme pouvoir le confirmer. »\nMarqueurs de distance acceptés : « selon elle », conditionnel (« auraient respecté », « aurait été »), « affirme »."}$exo$::jsonb),
  ('1146abd6-d386-5cb7-b33b-20ce7fb12896'::uuid, 1, 'traduction', $exo${"titre":"Au parfait : participe ou double infinitif ?","consigne":"Mets chaque phrase au parfait, puis réponds à la question 2.","enonce":"**1.** Mets ces phrases au parfait.\n\n- a) Ich muss früh aufstehen.\n- b) Sie kann das Problem nicht lösen.\n- c) Wir wollen dir helfen.\n- d) Er lässt sein Auto reparieren.\n- e) Ich will es nicht.\n\n**2.** Explique en une ou deux phrases pourquoi la phrase e) ne se construit pas comme les quatre autres.","bareme":[{"critere":"Les quatre doubles infinitifs justes (a à d), infinitifs dans le bon ordre","points":10},{"critere":"Auxiliaire haben correctement conjugué et placé dans les cinq phrases","points":4},{"critere":"Phrase e) juste (gewollt) et règle expliquée : modal seul = participe","points":6}],"dureeMin":7,"corrige":"**1.**\n- a) *Ich **habe** früh **aufstehen müssen**.*\n- b) *Sie **hat** das Problem nicht **lösen können**.*\n- c) *Wir **haben** dir **helfen wollen**.*\n- d) *Er **hat** sein Auto **reparieren lassen**.*\n- e) *Ich **habe** es nicht **gewollt**.*\n\n**2.** Dans les phrases a) à d), le modal (ou *lassen*) est accompagné d'un infinitif : au parfait, il ne prend pas son participe mais reste à l'infinitif (double infinitif). Dans la phrase e), *wollen* est employé **seul**, sans infinitif : on emploie alors son participe normal, *gewollt*. L'auxiliaire est toujours *haben*.\n\nFautes typiques à sanctionner : *ich habe aufstehen gemusst*, *ich bin aufstehen müssen*, *er hat reparieren gelassen*."}$exo$::jsonb),
  ('1146abd6-d386-5cb7-b33b-20ce7fb12896'::uuid, 2, 'traduction', $exo${"titre":"Subordonnées, reproches et regrets","consigne":"Fais les trois exercices dans l'ordre.","enonce":"**1.** Réunis les deux phrases en une seule, avec la conjonction indiquée.\n\n- a) Ich komme zu spät. Ich habe auf den Bus warten müssen. (*weil*)\n- b) Er ist traurig. Er hat seine Freunde nicht sehen können. (*weil*)\n- c) Ich weiß es: Sie hat das Fenster reparieren lassen. (*dass*)\n\n**2.** Traduis en allemand avec le subjonctif II passé.\n\n- a) Tu aurais dû m'appeler.\n- b) J'aurais dû apprendre davantage.\n- c) Il aurait pu nous aider.\n\n**3.** Explique en français la place de l'auxiliaire dans tes réponses à l'exercice 1.","bareme":[{"critere":"Trois subordonnées justes, auxiliaire placé devant les deux infinitifs","points":8},{"critere":"Trois traductions justes au subjonctif II passé avec double infinitif","points":8},{"critere":"Règle de place expliquée (seule exception au verbe final)","points":4}],"dureeMin":11,"corrige":"**1.**\n- a) *Ich komme zu spät, weil ich auf den Bus **habe** warten müssen.*\n- b) *Er ist traurig, weil er seine Freunde nicht **hat** sehen können.*\n- c) *Ich weiß, dass sie das Fenster **hat** reparieren lassen.*\n\n**2.**\n- a) *Du **hättest** mich **anrufen sollen**.*\n- b) *Ich **hätte** mehr **lernen sollen**.*\n- c) *Er **hätte** uns **helfen können**.*\n\n**3.** Dans une subordonnée, le verbe conjugué va normalement à la fin. Mais avec un double infinitif, l'auxiliaire conjugué (*habe, hat*) se place **devant** les deux infinitifs, et non après : *weil ich … habe warten müssen*, jamais *warten müssen habe*. C'est la seule exception à la règle du verbe final.\n\nFautes à sanctionner : *weil ich auf den Bus warten müssen habe* ; *weil ich habe auf den Bus warten müssen* (l'auxiliaire se place juste devant le groupe des infinitifs, après les compléments)."}$exo$::jsonb),
  ('1146abd6-d386-5cb7-b33b-20ce7fb12896'::uuid, 3, 'traduction', $exo${"titre":"Une journée gâchée : thème","consigne":"Traduis le texte en allemand (thème), puis justifie deux de tes choix.","enonce":"**Texte à traduire.**\n\n> Hier, j'ai dû rester à la maison, parce que mes parents avaient fait réparer le toit. Je n'ai pas pu aller au cinéma avec mes amis. J'ai vu les ouvriers travailler toute la journée. Le soir, ma mère m'a dit : « Tu aurais dû faire tes devoirs. » Elle a raison : j'aurais pu les faire.\n\n*Aide : das Dach = le toit ; der Arbeiter = l'ouvrier ; die Hausaufgaben = les devoirs ; recht haben = avoir raison.*\n\n1. Traduis le texte.\n2. Justifie en français **deux** choix : la construction de « avaient fait réparer » dans la subordonnée, et celle de « tu aurais dû faire ».","bareme":[{"critere":"Doubles infinitifs justes dans les principales (bleiben müssen, gehen können, arbeiten sehen)","points":6},{"critere":"Subordonnée juste : auxiliaire hatten devant reparieren lassen","points":4},{"critere":"Subjonctif II passé juste (hättest … machen sollen, hätte … machen können)","points":4},{"critere":"Deux choix justifiés avec la règle du cours","points":3},{"critere":"Sens, vocabulaire et orthographe du reste du texte","points":3}],"dureeMin":18,"corrige":"**1. Traduction proposée**\n*Gestern **habe** ich zu Hause **bleiben müssen**, weil meine Eltern das Dach **hatten reparieren lassen**. Ich **habe** nicht mit meinen Freunden ins Kino **gehen können**. Ich **habe** die Arbeiter den ganzen Tag **arbeiten sehen**. Am Abend hat meine Mutter zu mir gesagt: « Du **hättest** deine Hausaufgaben **machen sollen**. » Sie hat recht: Ich **hätte** sie **machen können**.*\n\nAccepter : *Gestern musste ich …* (prétérit), à condition que les autres doubles infinitifs soient justes ; *meine Mutter sagte mir*.\n\n**2. Justifications**\n- « avaient fait réparer » : plus-que-parfait de *lassen* + infinitif → *hatten reparieren lassen* (double infinitif, auxiliaire *haben*). Dans la subordonnée en *weil*, l'auxiliaire conjugué *hatten* se place **devant** les deux infinitifs, et non à la fin.\n- « tu aurais dû faire » : subjonctif II passé du modal *sollen* avec un infinitif → *hättest … machen sollen* ; le modal reste à l'infinitif (*sollen*, pas *gesollt*). Cette forme exprime le **reproche**.\n\nAutres justifications acceptées : *arbeiten sehen* (*sehen* + infinitif prend le double infinitif), *ich hätte machen können* (regret, possibilité non réalisée)."}$exo$::jsonb),
  ('49bf2071-e993-57db-882d-a546aa90d5ae'::uuid, 1, 'traduction', $exo${"titre":"Cinq groupes participiaux à traduire","consigne":"Traduis chaque groupe en français, puis indique pour chacun le type de participe et son sens.","enonce":"**Groupes à traduire.**\n\n- a) das schlafende Kind\n- b) die gestohlene Tasche\n- c) die im Winter blühenden Blumen\n- d) das 1990 wiedervereinigte Deutschland\n- e) die zu lösende Aufgabe\n\n**Question.** Pour chaque groupe, précise s'il s'agit d'un **participe I**, d'un **participe II** ou de **zu + participe I**, et quel sens il porte (actif et en cours, passif ou accompli, ce qui doit être fait).","bareme":[{"critere":"Cinq traductions justes, nom noyau bien identifié (2 points chacune)","points":10},{"critere":"Type de participe et sens justes pour les cinq groupes (2 points chacun)","points":10}],"dureeMin":7,"corrige":"- a) « l'enfant endormi / qui dort » — **participe I** (*schlafen* + *d*) : actif, action en cours.\n- b) « le sac volé » — **participe II** (*gestohlen*) : passif, accompli.\n- c) « les fleurs qui fleurissent en hiver » — **participe I** (*blühend*) : actif, en cours ; *im Winter* est son complément placé entre l'article et le nom.\n- d) « l'Allemagne réunifiée en 1990 » — **participe II** (*wiedervereinigt*) : passif, accompli.\n- e) « la tâche à résoudre » — **zu + participe I** (*zu lösend*) : ce qui doit être fait.\n\nLes participes se déclinent comme des adjectifs épithètes : *schlafende*, *blühenden*, *wiedervereinigte*…"}$exo$::jsonb),
  ('49bf2071-e993-57db-882d-a546aa90d5ae'::uuid, 2, 'traduction', $exo${"titre":"De la relative au groupe participial, et retour","consigne":"Transforme les phrases comme indiqué, puis traduis les phrases demandées.","enonce":"**A. Transforme la relative en groupe participial épithète.**\n\n1. Die Menschen, die in der Stadt leben, haben weniger Platz.\n2. Ich lese das Buch, das 1929 veröffentlicht wurde.\n3. Die Preise, die seit Monaten steigen, sind ein Problem.\n\n**B. Transforme le groupe participial en relative.**\n\n4. Die von der Stasi überwachten Familien wussten nichts.\n5. Ich sehe einen im Park spielenden Jungen.\n\n**C.** Traduis en français les phrases 3 et 4.\n\n*Aide : veröffentlichen = publier.*","bareme":[{"critere":"Trois groupes participiaux justes (participe correct, bien décliné, compléments avant le participe)","points":9},{"critere":"Deux relatives justes (pronom relatif, verbe final, temps et voix)","points":6},{"critere":"Deux traductions justes et naturelles","points":5}],"dureeMin":12,"corrige":"**A.**\n1. *Die **in der Stadt lebenden** Menschen haben weniger Platz.* (participe I, actif)\n2. *Ich lese das **1929 veröffentlichte** Buch.* (participe II, passif)\n3. *Die **seit Monaten steigenden** Preise sind ein Problem.* (participe I)\n\n**B.**\n4. *Die Familien, **die von der Stasi überwacht wurden**, wussten nichts.* (participe II = passif → relative au passif ; *überwacht worden waren* accepté)\n5. *Ich sehe einen Jungen, **der im Park spielt**.* (participe I = actif en cours → relative active au présent)\n\n**C.**\n3. « Les prix qui augmentent depuis des mois sont un problème. »\n4. « Les familles qui étaient surveillées (qui avaient été surveillées) par la Stasi ne savaient rien. »\n\nPoints de vigilance : la terminaison de l'adjectif (*lebenden* après *die* au pluriel, *veröffentlichte* après *das*, *spielenden* à l'accusatif masculin après *einen*)."}$exo$::jsonb),
  ('49bf2071-e993-57db-882d-a546aa90d5ae'::uuid, 3, 'traduction', $exo${"titre":"Lire un article dense","consigne":"Analyse les groupes participiaux de l'article, traduis-le, puis transforme deux groupes en relatives.","enonce":"**Article (inventé).**\n\n> Die 1990 wiedervereinigte Stadt hat ein Problem: Die Zahl der in Armut lebenden Familien steigt. Die von der Regierung versprochenen Wohnungen sind noch nicht gebaut. Für viele Bürger ist das ein nicht zu unterschätzendes Problem, und die zu treffenden Entscheidungen sind schwer.\n\n*Aide : die Armut = la pauvreté ; versprechen = promettre ; eine Entscheidung treffen = prendre une décision.*\n\n1. Relève les **cinq** groupes participiaux épithètes. Pour chacun, donne le nom noyau et le type de participe (I, II, zu + I).\n2. Traduis l'article en français.\n3. Transforme en relatives les groupes « *die 1990 wiedervereinigte Stadt* » et « *die von der Regierung versprochenen Wohnungen* ».","bareme":[{"critere":"Cinq groupes repérés, noms noyaux et types de participe justes","points":6},{"critere":"Traduction fidèle de l'article","points":6},{"critere":"zu + participe I rendus par « à ne pas sous-estimer » et « à prendre »","points":3},{"critere":"Deux relatives justes (pronom, verbe final, passif)","points":5}],"dureeMin":18,"corrige":"**1.**\n- *die 1990 wiedervereinigte **Stadt*** — participe II ;\n- *der in Armut lebenden **Familien*** — participe I ;\n- *die von der Regierung versprochenen **Wohnungen*** — participe II ;\n- *ein nicht zu unterschätzendes **Problem*** — zu + participe I ;\n- *die zu treffenden **Entscheidungen*** — zu + participe I.\n\n**2. Traduction proposée**\n« La ville réunifiée en 1990 a un problème : le nombre de familles qui vivent dans la pauvreté augmente. Les logements promis par le gouvernement ne sont pas encore construits. Pour beaucoup de citoyens, c'est un problème à ne pas sous-estimer, et les décisions à prendre sont difficiles. »\n\n**3.**\n- *die Stadt, **die 1990 wiedervereinigt wurde*** ;\n- *die Wohnungen, **die von der Regierung versprochen wurden*** (*worden sind* accepté).\nLe participe II a un sens passif : la relative est au passif (*werden* + participe), le verbe conjugué à la fin."}$exo$::jsonb),
  ('a989aac1-5277-5abc-b828-75e21160ec96'::uuid, 1, 'traduction', $exo${"titre":"Quelque part, nulle part, personne","consigne":"Complète chaque phrase avec le pronom ou l'adverbe indéfini qui convient, puis traduis deux phrases.","enonce":"**1.** Complète (le sens est donné entre parenthèses).\n\n- a) Mein Schlüssel liegt ___ im Haus. (quelque part)\n- b) Ich habe ___ gesehen. (personne)\n- c) ___ hat angerufen. (quelqu'un)\n- d) ___ schaffe ich das. (un jour)\n- e) Gibt es ___? (quelque chose de nouveau)\n- f) Ich finde mein Handy ___. (nulle part)\n\n**2.** Traduis en français les phrases b) et f).","bareme":[{"critere":"Six mots justes (irgendwo, niemanden, jemand, irgendwann, etwas Neues, nirgendwo)","points":14},{"critere":"Deux traductions justes avec une seule négation en allemand rendue par ne … personne / nulle part","points":6}],"dureeMin":6,"corrige":"**1.**\n- a) *Mein Schlüssel liegt **irgendwo** im Haus.*\n- b) *Ich habe **niemanden** (niemand) gesehen.* — accusatif ; *niemand* sans terminaison accepté (oral).\n- c) ***Jemand*** (*Irgendwer, Irgendjemand*) *hat angerufen.*\n- d) ***Irgendwann*** *schaffe ich das.*\n- e) *Gibt es **etwas Neues**?* — adjectif substantivé : majuscule et *-es*.\n- f) *Ich finde mein Handy **nirgendwo*** (*nirgends*).\n\nBarème : 2 points par réponse, 4 pour e) (majuscule et terminaison).\n\n**2.**\n- b) « Je n'ai vu personne. »\n- f) « Je ne trouve mon portable nulle part. »\nEn allemand, une seule négation suffit (*niemanden*, *nirgendwo*) : jamais *nicht niemanden*."}$exo$::jsonb),
  ('a989aac1-5277-5abc-b828-75e21160ec96'::uuid, 2, 'traduction', $exo${"titre":"Chasse aux fautes","consigne":"Corrige chaque phrase et explique la règle en une ligne, puis écris trois phrases de ton choix.","enonce":"**1.** Chacune de ces phrases contient **une** faute. Corrige-la et explique la règle.\n\n- a) *Ich habe nicht niemanden gesehen.*\n- b) *Er hat etwas neues gekauft.*\n- c) *Ich habe mit niemanden gesprochen.*\n- d) *Das ist nicht Besonderes.*\n- e) *Das Leben gibt man keine zweite Chance.*\n\n**2.** Écris trois phrases en allemand qui emploient correctement *irgendwie*, *irgendein* et *nie*.","bareme":[{"critere":"Cinq corrections justes","points":10},{"critere":"Cinq règles expliquées clairement","points":5},{"critere":"Trois phrases correctes employant irgendwie, irgendein, nie dans leur sens","points":5}],"dureeMin":11,"corrige":"**1.**\n- a) *Ich habe **niemanden** gesehen.* — une seule négation en allemand : jamais *nicht* + *niemand*.\n- b) *Er hat etwas **Neues** gekauft.* — après *etwas*, l'adjectif devient un nom neutre : majuscule et *-es*.\n- c) *Ich habe mit **niemandem** gesprochen.* — *mit* + datif : *niemand(em)*. (*mit niemand* toléré à l'oral, pas *niemanden*, qui est l'accusatif.)\n- d) *Das ist **nichts** Besonderes.* — « rien de spécial » = *nichts* + adjectif substantivé ; *nicht* ne convient pas.\n- e) *Das Leben gibt **einem** keine zweite Chance.* — *man* n'existe qu'au nominatif ; au datif, on emploie *einem*.\n\n**2. Exemples**\n- *Irgendwie schaffe ich das.* (d'une manière ou d'une autre)\n- *Irgendein Schüler hat das Fenster offen gelassen.* (un élève quelconque)\n- *Ich war nie in Berlin.* (jamais)\nAccepter toute phrase correcte ; vérifier la déclinaison de *irgendein* (*irgendeinen* à l'accusatif masculin, etc.)."}$exo$::jsonb),
  ('a989aac1-5277-5abc-b828-75e21160ec96'::uuid, 3, 'traduction', $exo${"titre":"Le message introuvable : thème","consigne":"Traduis le texte en allemand (thème), puis justifie trois de tes choix.","enonce":"**Texte à traduire.**\n\n> Quelqu'un a laissé un message quelque part sur mon bureau, mais je ne le trouve nulle part. Personne ne sait rien. J'ai parlé avec quelqu'un du secrétariat, mais il ne m'a rien dit de précis. Un jour, je trouverai bien une solution, d'une manière ou d'une autre.\n\n*Aide : hinterlassen = laisser ; die Nachricht = le message ; der Schreibtisch = le bureau ; das Sekretariat ; genau = précis.*\n\n1. Traduis le texte.\n2. Justifie **trois** choix : la traduction de « Personne ne sait rien », la forme de « avec quelqu'un », et celle de « rien de précis ».","bareme":[{"critere":"Indéfinis justes : irgendjemand, irgendwo, nirgends, irgendwann, irgendwie","points":6},{"critere":"Une seule négation : Niemand weiß etwas ; er hat mir nichts Genaues gesagt","points":4},{"critere":"Datif juste : mit jemandem","points":2},{"critere":"Trois choix justifiés avec la règle du cours","points":4},{"critere":"Sens, place du verbe et orthographe du reste du texte","points":4}],"dureeMin":16,"corrige":"**1. Traduction proposée**\n*Irgendjemand hat irgendwo auf meinem Schreibtisch eine Nachricht hinterlassen, aber ich finde sie nirgends (nirgendwo). Niemand weiß etwas. Ich habe mit jemandem aus dem Sekretariat gesprochen, aber er hat mir nichts Genaues gesagt. Irgendwann finde ich schon eine Lösung, irgendwie.*\n\nAccepter : *Jemand / Irgendwer* ; *werde … finden* pour le futur ; *Irgendwie werde ich irgendwann eine Lösung finden*.\n\n**2. Justifications**\n- « Personne ne sait rien » : le français cumule deux mots négatifs, l'allemand n'emploie **qu'une** négation. Avec *niemand*, « rien » devient le positif *etwas* : *Niemand weiß etwas* (et non *Niemand weiß nichts*).\n- « avec quelqu'un » : *mit* + datif → *jemandem*.\n- « rien de précis » : *nichts* + adjectif substantivé, neutre, majuscule et *-es* : *nichts Genaues*.\n\nFautes lourdes : *Niemand weiß nichts* ; *mit jemand(en)* à l'accusatif ; *nichts genaues*."}$exo$::jsonb),
  ('9a3a898e-a0a2-5382-888c-542b748b51f9'::uuid, 1, 'traduction', $exo${"titre":"En faisant : indem ou beim ?","consigne":"Relie les phrases avec indem, puis réponds à la question 2.","enonce":"**1.** Relie chaque paire de phrases avec *indem* pour exprimer le moyen.\n\n- a) Man lernt eine Sprache. Man spricht viel.\n- b) Wir sparen Energie. Wir schalten das Licht aus.\n- c) Sie hält sich fit. Sie fährt jeden Tag Rad.\n\n**2.** Traduis « En mangeant, il regarde la télévision » et explique pourquoi on n'emploie pas *indem* ici.\n\n*Aide : fernsehen = regarder la télévision.*","bareme":[{"critere":"Trois phrases justes avec indem et le verbe conjugué à la fin (ausschalten recollé)","points":12},{"critere":"Traduction avec beim Essen et différence moyen / simultanéité expliquée","points":8}],"dureeMin":6,"corrige":"**1.**\n- a) *Man lernt eine Sprache, **indem** man viel **spricht**.*\n- b) *Wir sparen Energie, **indem** wir das Licht **ausschalten**.* — le verbe à particule se recolle à la fin de la subordonnée.\n- c) *Sie hält sich fit, **indem** sie jeden Tag Rad **fährt**.*\n(4 points par phrase.)\n\n**2.** *Beim Essen sieht er fern.* — Ici, « en mangeant » n'exprime pas le **moyen** (manger n'est pas une façon de regarder la télévision) mais la **simultanéité** : les deux actions ont lieu en même temps. On emploie donc *beim* + infinitif substantivé. *indem* répond à la question *wie?* (comment ?) : il traduit le gérondif de moyen."}$exo$::jsonb),
  ('9a3a898e-a0a2-5382-888c-542b748b51f9'::uuid, 2, 'traduction', $exo${"titre":"Sans, au lieu de, grâce à","consigne":"Complète chaque phrase, traduis-en trois, puis réponds à la question 3.","enonce":"**1.** Complète avec : *indem*, *beim*, *ohne … zu*, *ohne dass*, *statt … zu*, *dadurch … dass*.\n\n- a) Er verließ den Raum, ___ ein Wort ___ sagen.\n- b) ___ Lesen höre ich gern Musik.\n- c) Man schützt das Klima, ___ man weniger fliegt.\n- d) Sie ging weg, ___ ich es merkte.\n- e) ___ zu lernen, spielt er am Handy.\n- f) Die Stadt hat die Luft ___ verbessert, ___ sie den Verkehr begrenzt hat.\n\n**2.** Traduis en français les phrases a), d) et f).\n\n**3.** Explique quand on emploie *ohne … zu* et quand on emploie *ohne dass*.","bareme":[{"critere":"Six phrases complétées correctement","points":9},{"critere":"Trois traductions justes et naturelles","points":6},{"critere":"Règle ohne … zu / ohne dass expliquée (même sujet / sujets différents)","points":5}],"dureeMin":10,"corrige":"**1.**\n- a) *Er verließ den Raum, **ohne** ein Wort **zu** sagen.*\n- b) ***Beim*** *Lesen höre ich gern Musik.*\n- c) *Man schützt das Klima, **indem** man weniger fliegt.*\n- d) *Sie ging weg, **ohne dass** ich es merkte.*\n- e) ***Statt*** *(Anstatt) zu lernen, spielt er am Handy.*\n- f) *Die Stadt hat die Luft **dadurch** verbessert, **dass** sie den Verkehr begrenzt hat.*\n\n**2.**\n- a) « Il quitta la pièce sans dire un mot. »\n- d) « Elle partit sans que je m'en aperçoive. »\n- f) « La ville a amélioré la qualité de l'air en limitant la circulation. »\n\n**3.** *ohne … zu* + infinitif s'emploie quand le sujet est **le même** dans les deux propositions (*Er* verließ … *er* sagte nichts). *ohne dass* + verbe conjugué à la fin s'emploie quand les sujets sont **différents** (*sie* ging weg, *ich* merkte nichts). Même règle pour *statt … zu* / *statt dass*."}$exo$::jsonb),
  ('9a3a898e-a0a2-5382-888c-542b748b51f9'::uuid, 3, 'traduction', $exo${"titre":"Comment lutter contre les infox ?","consigne":"Rédige en allemand un texte d'environ 100 à 120 mots qui donne des conseils, en employant les structures imposées.","enonce":"**Sujet.**\n\n> *Wie kann man Fake News bekämpfen?*\n\nRédige un petit texte de conseils pour ta classe. Tu dois employer **au moins** :\n- deux subordonnées en *indem* ;\n- une construction *dadurch, dass …* ;\n- une construction *ohne … zu* ;\n- une construction *statt … zu*.\n\nTermine par une question introduite par *Wodurch?* suivie de sa réponse.\n\n*Aide : die Quelle = la source ; überprüfen = vérifier ; teilen = partager ; glauben = croire.*","bareme":[{"critere":"Deux subordonnées en indem justes (même sujet, verbe final)","points":5},{"critere":"dadurch, dass ; ohne … zu ; statt … zu employés correctement","points":6},{"critere":"Question Wodurch? et réponse Dadurch, dass … justes","points":2},{"critere":"Conseils pertinents et cohérents","points":3},{"critere":"Correction générale de la langue","points":4}],"dureeMin":16,"corrige":"**Texte modèle (≈ 110 mots)**\n\n*Fake News verbreiten sich schneller als die Wahrheit. Aber jeder kann etwas tun. Man kann Falschmeldungen bekämpfen, **indem** man die Quellen **überprüft**. Man schützt sich auch, **indem** man verschiedene Zeitungen **liest**. Die Schule kann **dadurch** helfen, **dass** sie die Schüler über Deepfakes **informiert**. Man sollte nie eine Nachricht teilen, **ohne** sie gelesen **zu** haben. **Statt** alles sofort **zu** glauben, sollte man einen Moment warten und nachdenken.*\n\n*Wodurch kann man eine Falschmeldung erkennen? Dadurch, dass keine seriöse Quelle sie bestätigt.*\n\n**Éléments attendus**\n- *indem* + verbe conjugué à la fin, même sujet que la principale.\n- *dadurch* dans la principale, *dass* + verbe final dans la subordonnée ; les sujets peuvent différer.\n- *ohne … zu* et *statt … zu* + infinitif en fin de groupe, même sujet.\n- Question *Wodurch?* et réponse *Dadurch, dass …*.\nPénaliser *indem* suivi d'un verbe en 2e position et la confusion avec *beim*."}$exo$::jsonb),
  ('097dce0a-cc15-54cf-84c9-50cc85c10e06'::uuid, 1, 'traduction', $exo${"titre":"Quel ton ?","consigne":"Pour chaque phrase, nomme le ton apporté par la particule, puis traduis trois phrases.","enonce":"**1.** Quel ton la particule ajoute-t-elle ?\n\n- a) Das ist ja toll!\n- b) Komm doch mit!\n- c) Sie ist wohl müde.\n- d) Mach das bloß nicht!\n- e) Was ist denn los?\n- f) Das ist eben so.\n\n**2.** Traduis en français les phrases b), c) et d) en rendant le ton.","bareme":[{"critere":"Six tons identifiés justement (2 points chacun)","points":12},{"critere":"Trois traductions qui rendent le ton sans calque","points":8}],"dureeMin":6,"corrige":"**1.**\n- a) *ja* : la **surprise** (enthousiasme) — « mais c'est génial ! »\n- b) *doch* : l'**invitation insistante**.\n- c) *wohl* : la **supposition**.\n- d) *bloß* : l'**avertissement**.\n- e) *denn* : l'**intérêt** dans la question.\n- f) *eben* : la **résignation**, c'est comme ça.\n\n**2.**\n- b) « Viens donc avec nous ! » / « Allez, viens ! »\n- c) « Elle est sans doute fatiguée. »\n- d) « Surtout, ne fais pas ça ! »\nOn ne traduit pas la particule mot à mot : on rend le ton (« donc », « sans doute », « surtout »)."}$exo$::jsonb),
  ('097dce0a-cc15-54cf-84c9-50cc85c10e06'::uuid, 2, 'traduction', $exo${"titre":"Une dispute en six particules","consigne":"Lis le dialogue, réponds aux questions 1 et 2 en français, puis traduis le dialogue.","enonce":"**Dialogue (inventé).**\n\n> **Lena :** Wo warst du denn? Wir haben eine Stunde gewartet!\n> **Jonas :** Ich hatte doch gesagt, dass ich später komme.\n> **Lena :** Das hast du nicht gesagt. Du vergisst eben immer alles.\n> **Jonas :** Na ja, das ist halt so. Komm, gib mir mal den Schlüssel.\n> **Lena :** Hier. Aber verlier ihn bloß nicht!\n\n1. Relève les **six** particules modales et donne la nuance de chacune.\n2. Que révèlent ces particules sur la relation entre Lena et Jonas à ce moment-là ?\n3. Traduis le dialogue en français en rendant le ton.","bareme":[{"critere":"Six particules relevées (denn, doch, eben, halt, mal, bloß) avec leur nuance juste","points":8},{"critere":"Interprétation de la relation (agacement, conflit, reproche) appuyée sur les particules","points":5},{"critere":"Traduction fidèle qui rend le ton sans traduire mot à mot","points":7}],"dureeMin":12,"corrige":"**1.**\n- *denn* (*Wo warst du denn?*) : intérêt, ici impatience dans la question.\n- *doch* (*Ich hatte doch gesagt*) : rappel insistant, « je te l'avais bien dit ».\n- *eben* (*Du vergisst eben immer alles*) : constat résigné, « c'est comme ça avec toi ».\n- *halt* (*das ist halt so*) : résignation, « c'est comme ça ».\n- *mal* (*gib mir mal den Schlüssel*) : adoucit la demande.\n- *bloß* (*verlier ihn bloß nicht!*) : avertissement.\n\n**2.** Les particules montrent une petite **dispute** : Lena est agacée (*denn*, puis *eben* qui généralise le reproche), Jonas se défend en insistant (*doch* signale le conflit), puis cède avec fatalisme (*halt*) et tente d'apaiser (*mal*). Le dernier mot de Lena (*bloß*) montre qu'elle ne lui fait pas entièrement confiance. Aucune particule ne change l'information : elles disent l'attitude.\n\n**3. Traduction proposée**\n« — Mais où étais-tu donc ? On a attendu une heure !\n— Je t'avais bien dit que je viendrais plus tard.\n— Tu ne l'as pas dit. De toute façon, tu oublies toujours tout.\n— Bon, c'est comme ça. Allez, passe-moi la clé.\n— Tiens. Mais surtout, ne la perds pas ! »"}$exo$::jsonb),
  ('097dce0a-cc15-54cf-84c9-50cc85c10e06'::uuid, 3, 'traduction', $exo${"titre":"Donner le ton, lire l'implicite","consigne":"Fais les deux parties : réécriture des phrases avec une particule, puis commentaire et traduction d'un court extrait.","enonce":"**Partie A.** Ajoute à chaque phrase la particule qui donne le ton demandé, bien placée.\n\n1. Du kennst das Problem. (évidence partagée)\n2. Hilf mir! (demande adoucie)\n3. Er kommt nicht. (supposition)\n4. Warum bist du so traurig? (intérêt dans la question)\n5. Du hast es versprochen! (reproche, rappel)\n6. Wenn ich Zeit hätte! (souhait)\n7. Wie alt bist du? (« au fait »)\n\n**Partie B. Extrait (inventé).**\n\n> Als Anna die Nachricht las, lachte sie nur. Ihre Reaktion war ja zu erwarten: Sie hatte doch schon immer gesagt, dass sie diese Stadt verlassen wollte.\n\n1. Explique ce que les particules *ja* et *doch* révèlent de l'attitude du narrateur.\n2. Traduis l'extrait en français.","bareme":[{"critere":"Sept particules justes pour le ton demandé","points":9},{"critere":"Particules placées au milieu de la phrase, après le verbe conjugué et les pronoms","points":3},{"critere":"Commentaire de ja et doch : narrateur non surpris, évidence, rappel","points":4},{"critere":"Traduction qui rend l'implicite","points":4}],"dureeMin":16,"corrige":"**Partie A.**\n1. *Du kennst **ja** das Problem.*\n2. *Hilf mir **mal**!*\n3. *Er kommt **wohl** nicht.*\n4. *Warum bist du **denn** so traurig?*\n5. *Du hast es **doch** versprochen!*\n6. *Wenn ich **bloß** (**nur**) Zeit hätte!*\n7. *Wie alt bist du **eigentlich**?*\nLa particule n'est jamais accentuée et se place après le verbe conjugué et les pronoms (*Du kennst ja …*, *Hilf mir mal*).\n\n**Partie B.**\n1. *ja* (*Ihre Reaktion war ja zu erwarten*) présente la réaction comme une évidence partagée : le narrateur n'est pas surpris, il prend le lecteur à témoin, avec peut-être une pointe d'ironie. *doch* (*Sie hatte doch schon immer gesagt*) rappel insistant : « elle l'avait bien toujours dit », comme si personne n'avait voulu l'entendre.\n2. « Quand Anna lut le message, elle se contenta de rire. Sa réaction était, bien sûr, prévisible : elle avait toujours dit, après tout, qu'elle voulait quitter cette ville. »\nAccepter « comme on pouvait s'y attendre », « elle l'avait pourtant toujours dit »."}$exo$::jsonb),
  ('df1e1253-9ff3-56bc-9b67-44f2b8e16422'::uuid, 1, 'traduction', $exo${"titre":"A, an, the ou rien ?","consigne":"Complète chaque phrase avec a, an, the ou Ø (article zéro), puis traduis les deux dernières phrases en anglais.","enonce":"**1. Complète avec a, an, the ou Ø.**\n\n1. She is ___ engineer.\n2. I bought ___ umbrella yesterday. ___ umbrella is blue.\n3. ___ sun rises in the east.\n4. It takes ___ hour to get there.\n5. ___ water is essential to life.\n6. We go swimming twice ___ week.\n\n**2. Traduis en anglais.**\n\n7. J'aime la musique.\n8. Les chats sont indépendants.","bareme":[{"critere":"Articles justes dans les six phrases à compléter (a / an / the / Ø)","points":12},{"critere":"Article zéro dans les deux traductions (music, cats au sens général)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *She is **an** engineer.* — métier → a/an ; *engineer* commence par un son voyelle → **an**.\n2. *I bought **an** umbrella yesterday. **The** umbrella is blue.* — première mention → *an* (son voyelle) ; déjà mentionné → *the*.\n3. ***The** sun rises in the east.* — objet unique → *the*.\n4. *It takes **an** hour…* — h muet, son voyelle → *an*.\n5. ***Ø** Water is essential to life.* — indénombrable au sens général → article zéro.\n6. *twice **a** week* — fréquence → *a*.\n\n**2.**\n7. *I like music.* (ou *I love music.*) — pas *the music* : sens général.\n8. *Cats are independent.* — pluriel au sens général → article zéro ; *The cats are independent* parlerait de chats précis.\n\nOn accepte *I love music*. Toute forme avec *the* devant *music* ou *cats* perd les points du critère 2."}$exo$::jsonb),
  ('df1e1253-9ff3-56bc-9b67-44f2b8e16422'::uuid, 2, 'traduction', $exo${"titre":"La chambre de Maya et Ethan","consigne":"Traduis le texte en anglais (thème). Soigne les articles, les possessifs et le génitif.","enonce":"**Thème : traduis en anglais.**\n\n> Maya et son frère Ethan partagent une chambre. Le lit de Maya est près de la fenêtre. Ethan est un musicien : sa guitare est sur le lit. Maya aime les livres et elle lit une heure par jour. Les jouets des enfants sont dans une boîte. La boîte est sous le bureau de leur père.\n\n*Aide : partager = to share ; jouet = toy ; bureau (meuble) = desk.*","bareme":[{"critere":"Articles justes : a musician, an hour, a day, a box / the box, Ø books","points":7},{"critere":"Possessifs accordés au possesseur (her brother, his guitar, their father)","points":5},{"critere":"Génitifs corrects (Maya's bed, the children's toys, their father's desk)","points":5},{"critere":"Sens général, ordre des mots et orthographe","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n> *Maya and her brother Ethan share a room. Maya's bed is near the window. Ethan is a musician: his guitar is on the bed. Maya likes books and she reads an hour a day. The children's toys are in a box. The box is under their father's desk.*\n\n**Points attendus**\n- *her brother* : le possesseur est Maya → *her* ; *his guitar* : le possesseur est Ethan → *his* ; *their father* : deux possesseurs → *their*.\n- *Maya's bed* : génitif, le possesseur passe devant. *The children's toys* : pluriel irrégulier → *'s* (pas *childrens'*). *Their father's desk* : génitif singulier.\n- *a room*, *a box* : première mention d'un singulier dénombrable ; *the box* ensuite : déjà mentionné. *the window*, *the bed* : identifiés par le contexte.\n- *Ethan is a musician* : métier → *a*.\n- *likes books* : pluriel au sens général → article zéro (pas *the books*).\n- *an hour a day* : *an* devant h muet ; *a day* : fréquence.\n\nAccepté : *a bedroom*, *loves books*, *by the window*."}$exo$::jsonb),
  ('df1e1253-9ff3-56bc-9b67-44f2b8e16422'::uuid, 3, 'traduction', $exo${"titre":"Corriger la copie de Hugo","consigne":"Hugo a rendu un petit texte plein de fautes de déterminants. Repère les erreurs, corrige-les et justifie chaque correction par la règle du cours.","enonce":"**Voici le texte de Hugo :**\n\n> *The life in the Netherlands is pleasant. My cousin Lisa lives there with his husband. She is teacher and she works in an university. Its a big school. Lisa likes the nature and she goes cycling three times the week. Last summer, I visited Lisa's parents house. This days were the best days of my life.*\n\n1. Relève et corrige les **neuf** erreurs du texte.\n2. Pour chacune, donne en une phrase la règle qui justifie la correction.\n3. Réécris la dernière phrase en parlant d'une époque lointaine et révolue, puis explique le déterminant choisi.","bareme":[{"critere":"Les neuf erreurs repérées et corrigées","points":8},{"critere":"Une règle juste et précise pour chaque correction","points":7},{"critere":"Réécriture de la dernière phrase avec those et justification (distance)","points":3},{"critere":"Texte final correct et orthographe","points":2}],"dureeMin":17,"corrige":"**1 et 2. Les neuf erreurs**\n1. *The life* → ***Life*** : indénombrable au sens général → article zéro (« la vie en général »). *The Netherlands* est juste : pays au pluriel.\n2. *his husband* → ***her husband*** : le possessif s'accorde avec le possesseur, Lisa (féminin).\n3. *She is teacher* → *She is **a** teacher* : un métier prend *a/an*.\n4. *an university* → ***a** university* : on regarde le son (« you- »), un son de consonne → *a*.\n5. *Its a big school* → ***It's** a big school* : *it's* = *it is* ; *its* sans apostrophe est le possessif.\n6. *the nature* → ***nature*** : indénombrable au sens général → article zéro.\n7. *three times the week* → *three times **a** week* : la fréquence se dit avec *a*.\n8. *Lisa's parents house* → *Lisa's **parents'** house* : possesseur au pluriel en -s → apostrophe seule.\n9. *This days* → ***These** days* (ou *Those days*) : *this* est singulier, son pluriel est *these* (proche) ou *those* (éloigné).\n\n**3.** *Those days were the best days of my life.* *Those* : pluriel de *that*, il situe le nom **loin** dans le temps, une époque révolue ; *these* désignerait ce qui est proche, maintenant. *The best* reste : le superlatif prend toujours *the*.\n\n**Texte corrigé** : *Life in the Netherlands is pleasant. My cousin Lisa lives there with her husband. She is a teacher and she works in a university. It's a big school. Lisa likes nature and she goes cycling three times a week. Last summer, I visited Lisa's parents' house. Those days were the best days of my life.*"}$exo$::jsonb),
  ('8a65c707-5151-57d5-93a7-1058287d17fb'::uuid, 1, 'traduction', $exo${"titre":"Choisir le bon modal","consigne":"Complète chaque phrase avec le modal qui convient et indique entre parenthèses ce qu'il exprime (capacité, obligation, conseil, possibilité, interdiction, déduction).","enonce":"**Complète avec : can, must, mustn't, should, might, must.**\n\n1. You look tired. You ___ go to bed earlier.\n2. Take an umbrella: it ___ rain this afternoon.\n3. My little sister is only five but she ___ read.\n4. You ___ smoke in the hospital: it is forbidden.\n5. He has worked all night. He ___ be exhausted.\n6. The rules are clear: you ___ wear a helmet on a motorbike.\n\n**7.** Trouve et corrige l'erreur : *She cans to swim.*","bareme":[{"critere":"Modal juste dans chacune des six phrases","points":12},{"critere":"Valeur du modal correctement nommée","points":5},{"critere":"Correction de She cans to swim (pas de -s, pas de to)","points":3}],"dureeMin":7,"corrige":"1. *You **should** go to bed earlier.* (conseil)\n2. *It **might** rain this afternoon.* (possibilité incertaine)\n3. *She **can** read.* (capacité)\n4. *You **mustn't** smoke in the hospital.* (interdiction)\n5. *He **must** be exhausted.* (déduction quasi certaine, valeur épistémique)\n6. *You **must** wear a helmet.* (obligation) — on accepte *have to* si l'élève l'écrit, puisque la règle vient des circonstances.\n\n7. *She **can swim**.* Deux fautes : un modal ne prend **jamais de -s** à la 3e personne, et il est suivi de la **base verbale sans to**."}$exo$::jsonb),
  ('8a65c707-5151-57d5-93a7-1058287d17fb'::uuid, 2, 'traduction', $exo${"titre":"Le règlement du stage de voile","consigne":"Traduis le règlement en anglais, puis réponds à la question 2 en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Règlement du club de voile\n> - Vous devez porter un gilet de sauvetage.\n> - Vous ne devez pas nager seul après 18 h.\n> - Vous n'êtes pas obligés d'apporter votre matériel : le club le prête.\n> - Vous devriez boire de l'eau régulièrement.\n> - Il se peut que la sortie soit annulée s'il y a du vent.\n\n*Aide : gilet de sauvetage = life jacket ; prêter = to lend ; annuler = to cancel ; vent = wind.*\n\n**2.** Explique la différence de sens entre la phrase 2 et la phrase 3.","bareme":[{"critere":"Modaux justes : must, mustn't, don't have to, should, might/may","points":10},{"critere":"Forme correcte : base verbale sans to, pas de -s","points":4},{"critere":"Explication juste de mustn't (interdiction) et don't have to (absence d'obligation)","points":4},{"critere":"Vocabulaire et orthographe","points":2}],"dureeMin":11,"corrige":"**1. Traduction modèle**\n\n> *Sailing club rules*\n> - *You must wear a life jacket.*\n> - *You mustn't swim alone after 6 pm.*\n> - *You don't have to bring your equipment: the club lends it.*\n> - *You should drink water regularly.*\n> - *The trip might be cancelled if it is windy.* (ou *if there is wind* ; *may* accepté)\n\n**Points attendus** : *must* (obligation) ; *mustn't* (interdiction) ; *don't have to* (absence d'obligation) ; *should* (conseil) ; *might/may* (possibilité incertaine). Toujours la base verbale sans *to* après le modal. *If it is windy* : présent après *if*.\n\n**2.** *Mustn't* exprime une **interdiction** : « il ne faut pas » nager seul après 18 h. *Don't have to* exprime une **absence d'obligation** : ce n'est pas la peine d'apporter son matériel, mais on peut le faire. Les confondre changerait complètement le sens du règlement."}$exo$::jsonb),
  ('8a65c707-5151-57d5-93a7-1058287d17fb'::uuid, 3, 'traduction', $exo${"titre":"Le mystère du vélo disparu","consigne":"Lis la situation, puis réponds en anglais aux questions 1 et 2, en français à la question 3.","enonce":"**Situation.** Ce matin, le vélo de Noah n'était plus devant le lycée. Voici ce qu'on sait :\n\n> Noah left his bike unlocked. The school gate was open all night. Noah's friend Jake says he saw the bike at 8 pm. Jake is very honest. The caretaker was on holiday.\n\n1. Écris **quatre phrases** au passé qui font des hypothèses ou des déductions, avec *must have*, *might have*, *can't have* et *should have* + participe passé. (Ex. : quelqu'un a pu le prendre la nuit ; Jake n'a pas pu mentir ; Noah aurait dû l'attacher…)\n2. Traduis : « Il se pourrait qu'il le retrouve. Il pourra prendre le bus en attendant. »\n3. Explique pourquoi on ne peut pas écrire *he will can take the bus*, et pourquoi *He must be sad* ne signifie pas une obligation.","bareme":[{"critere":"Quatre phrases modal + have + participe passé correctes et adaptées à la situation","points":8},{"critere":"Valeur juste de chaque structure (déduction, hypothèse, déduction négative, reproche)","points":4},{"critere":"Traduction : might find it / will be able to take","points":4},{"critere":"Explications justes (deux modaux impossibles ; must épistémique)","points":4}],"dureeMin":16,"corrige":"**1. Exemples de réponses attendues**\n- *Someone must have taken it during the night.* — déduction quasi certaine sur le passé (le portail était ouvert).\n- *A thief might have seen that it was unlocked.* — hypothèse.\n- *Jake can't have lied: he is very honest.* — déduction négative.\n- *Noah should have locked his bike.* — reproche sur le passé.\nToute phrase juste et cohérente avec la situation est acceptée. Structure obligatoire : modal + *have* + **participe passé** (*taken, seen, lied, locked*).\n\n**2.** *He might find it. He will be able to take the bus in the meantime.* (*may find it* accepté ; *meanwhile* accepté.)\n\n**3.** Deux modaux ne se suivent jamais : *will* est déjà un modal, on ne peut donc pas lui ajouter *can*. Pour dire « il pourra », on remplace *can* par *be able to* : *he will be able to*.\n*Must* a deux valeurs : **radicale** (un ordre : *you must go*) et **épistémique** (une déduction : *he must be sad*). C'est le contexte qui tranche : ici on ne donne pas d'ordre à Noah, on déduit son état d'après la situation — « il doit être triste », c'est-à-dire « il est sûrement triste »."}$exo$::jsonb),
  ('d1a3f12e-fb3b-5157-ad66-9290fe2802f6'::uuid, 1, 'traduction', $exo${"titre":"Le samedi de Chloé","consigne":"Mets les verbes entre parenthèses au prétérit simple, puis transforme les deux dernières phrases comme demandé.","enonce":"**1. Mets au prétérit.**\n\n> Last Saturday, Chloé (get) ___ up at 9. She (play) ___ tennis with her brother, then they (go) ___ to the cinema. They (see) ___ a comedy. After that, she (study) ___ for two hours and she (take) ___ the bus home.\n\n**2.**\n- Mets à la forme négative : *She saw a comedy.*\n- Pose la question portant sur le mot souligné : *They went **to the cinema**.* (commence par *Where*)","bareme":[{"critere":"Six verbes au prétérit justes (réguliers et irréguliers)","points":12},{"critere":"Négative et interrogative avec did + base verbale","points":8}],"dureeMin":7,"corrige":"**1.** *Last Saturday, Chloé **got** up at 9. She **played** tennis with her brother, then they **went** to the cinema. They **saw** a comedy. After that, she **studied** for two hours and she **took** the bus home.*\n- *play → played* (régulier, base + -ed) ; *study → studied* (y après consonne → -ied).\n- Irréguliers : *get → got*, *go → went*, *see → saw*, *take → took*.\n- Marqueur *last Saturday* : passé révolu → prétérit.\n\n**2.**\n- *She didn't see a comedy.* — *did* porte le passé, le verbe revient à la base (pas *didn't saw*).\n- *Where did they go?* — auxiliaire *did* + sujet + base verbale (pas *Where did they went?*)."}$exo$::jsonb),
  ('d1a3f12e-fb3b-5157-ad66-9290fe2802f6'::uuid, 2, 'traduction', $exo${"titre":"La panne d'électricité","consigne":"Complète le récit avec le prétérit simple ou le prétérit en BE + -ING, puis justifie deux de tes choix.","enonce":"**1. Complète le récit.**\n\n> It (rain) ___ and the wind (blow) ___. My parents (watch) ___ the news and I (do) ___ my homework when suddenly the lights (go) ___ out. My father (find) ___ a candle and we (play) ___ cards until midnight.\n\n**2.** Justifie le temps choisi pour *(watch)* et pour *(go)*.\n\n**3.** Traduis : « Il y a deux ans, nous vivions à Lyon. »","bareme":[{"critere":"Décor au prétérit BE + -ING (was raining, was blowing, were watching, was doing)","points":8},{"critere":"Événements au prétérit simple (went, found, played)","points":6},{"critere":"Justification décor / événement","points":3},{"critere":"Traduction avec ago et le prétérit","points":3}],"dureeMin":11,"corrige":"**1.** *It **was raining** and the wind **was blowing**. My parents **were watching** the news and I **was doing** my homework when suddenly the lights **went** out. My father **found** a candle and we **played** cards until midnight.*\n\n**2.** *Were watching* : c'est le **décor**, une action en cours au moment du récit (équivalent de l'imparfait « regardaient »). *Went* : c'est l'**événement** qui survient et interrompt le décor (passé simple ou composé « s'est éteinte »), donc prétérit simple.\n\n**3.** *Two years ago, we lived in Lyon.* (*we were living in Lyon* accepté). Fait situé dans un passé révolu avec *ago* → prétérit ; jamais *we have lived*."}$exo$::jsonb),
  ('d1a3f12e-fb3b-5157-ad66-9290fe2802f6'::uuid, 3, 'traduction', $exo${"titre":"Un souvenir de vacances","consigne":"Rédige en anglais un court récit (80 à 100 mots), puis réponds aux questions de grammaire en français.","enonce":"**1. Production.** Raconte en anglais un souvenir de vacances (réel ou inventé) en 80 à 100 mots. Tu dois utiliser :\n- au moins **deux** verbes réguliers et **quatre** verbes irréguliers au prétérit ;\n- au moins **deux** verbes au prétérit en BE + -ING pour planter le décor ;\n- une phrase **négative** et une phrase **interrogative** au prétérit ;\n- un **marqueur** de temps passé (*last summer*, *two years ago*…).\n\n**2.** Souligne (ou recopie) une phrase où le décor est interrompu par un événement, et explique la répartition des deux temps.\n\n**3.** Un camarade a écrit *I have visited Rome last year*. Corrige et explique.","bareme":[{"critere":"Prétérit simple juste : 2 réguliers et 4 irréguliers corrects","points":6},{"critere":"Deux prétérits BE + -ING employés pour le décor","points":4},{"critere":"Négative et interrogative avec did + base verbale, marqueur de temps","points":4},{"critere":"Explication de la phrase décor / événement","points":3},{"critere":"Correction de I have visited Rome last year et justification","points":3}],"dureeMin":18,"corrige":"**1. Exemple de récit attendu**\n\n> *Last summer, I went to Spain with my cousins. On the first day, the sun was shining and people were swimming everywhere. We walked along the beach and we ate paella. One evening, we were walking in the old town when a man stopped us. He spoke English and he told us the history of the city. We didn't understand everything, but it was fantastic. Did I want to go home? Not at all!*\n\nÀ vérifier : réguliers (*walked, stopped*), irréguliers (*went, ate, spoke, told, was*), décor (*was shining, were swimming, were walking*), négative *didn't understand* (base verbale), interrogative *Did I want…?* (base verbale), marqueur *last summer*. Longueur 80 à 100 mots.\n\n**2.** *We were walking in the old town when a man stopped us* : *were walking* est le décor, l'action en cours (imparfait) ; *stopped* est l'événement bref qui survient et l'interrompt (passé simple / composé).\n\n**3.** *I visited Rome last year.* *Last year* date le fait dans un passé terminé : dès qu'un repère de temps passé est présent, c'est le **prétérit**, jamais le present perfect."}$exo$::jsonb),
  ('ac1eda10-55e1-5e25-86c8-d402a23e3d63'::uuid, 1, 'traduction', $exo${"titre":"Since ou for ?","consigne":"Complète avec since ou for, puis mets le verbe au present perfect.","enonce":"**1. Complète avec since ou for et mets le verbe au present perfect.**\n\n1. I (know) ___ Amir ___ 2020.\n2. She (live) ___ in London ___ ten years.\n3. We (not see) ___ our grandparents ___ Christmas.\n4. They (be) ___ friends ___ a long time.\n\n**2.** Complète avec *already, yet, ever, just*.\n\n5. Have you ___ been to Canada?\n6. I haven't finished my homework ___.\n7. The bus has ___ left: you can see it at the end of the street!","bareme":[{"critere":"Present perfect bien formé (have/has + participe passé)","points":8},{"critere":"Since (point de départ) et for (durée) justes","points":6},{"critere":"Marqueurs ever, yet, just/already bien placés","points":6}],"dureeMin":8,"corrige":"**1.**\n1. *I **have known** Amir **since** 2020.* (point de départ)\n2. *She **has lived** in London **for** ten years.* (durée)\n3. *We **haven't seen** our grandparents **since** Christmas.* (point de départ)\n4. *They **have been** friends **for** a long time.* (durée)\n\n**2.**\n5. *Have you **ever** been to Canada?* — expérience de vie.\n6. *I haven't finished my homework **yet**.* — *yet* en fin de phrase négative.\n7. *The bus has **just** left* — vient juste de partir (*already* accepté).\n\nRappel : situation commencée dans le passé et qui dure encore → present perfect, jamais le présent (*I know Amir since 2020* est faux)."}$exo$::jsonb),
  ('ac1eda10-55e1-5e25-86c8-d402a23e3d63'::uuid, 2, 'traduction', $exo${"titre":"Le message de Léna","consigne":"Traduis le message en anglais, puis réponds à la question 2 en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Salut Emma ! J'apprends l'anglais depuis six ans et je n'ai jamais visité l'Angleterre. Mon frère a déjà vu Londres trois fois. J'ai perdu mon passeport : je ne peux pas partir cet été ! Ma mère le cherche depuis ce matin.\n\n*Aide : passeport = passport ; chercher = to look for.*\n\n**2.** Explique pourquoi « J'ai perdu mon passeport » se met au present perfect ici, et pourquoi « Ma mère le cherche depuis ce matin » se met au present perfect en BE + -ING.","bareme":[{"critere":"Depuis traduit par present perfect + for/since (have been learning ou have learnt ; has been looking for)","points":7},{"critere":"Present perfect avec never, already, et have lost","points":6},{"critere":"Explications : résultat présent / durée qui continue","points":5},{"critere":"Vocabulaire et orthographe","points":2}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n\n> *Hi Emma! I have been learning English for six years and I have never visited England. My brother has already seen London three times. I have lost my passport: I can't leave this summer! My mother has been looking for it since this morning.*\n\nAcceptés : *I have learnt/learned English for six years* ; *I've never been to England*.\n\n**Points attendus** : « depuis six ans » au présent en français → present perfect + **for** (durée) ; « depuis ce matin » → **since** (point de départ). *Never*, *already* : marqueurs du present perfect. Jamais *I learn English since…*.\n\n**2.** *I have lost my passport* : le present perfect fait le **bilan au présent** ; ce qui compte est le **résultat actuel** (je ne l'ai plus, donc je ne peux pas partir), pas le moment de la perte. *Has been looking for it* : la forme BE + -ING insiste sur la **durée** d'une action commencée ce matin et qui **continue encore**."}$exo$::jsonb),
  ('ac1eda10-55e1-5e25-86c8-d402a23e3d63'::uuid, 3, 'traduction', $exo${"titre":"Prétérit ou present perfect : l'entretien de Sofia","consigne":"Complète le dialogue avec le temps qui convient (prétérit, present perfect simple ou BE + -ING), puis justifie tes choix.","enonce":"**Sofia passe un entretien pour un job d'été.**\n\n> **Manager:** How long (you / work) ___ as a babysitter?\n> **Sofia:** I (work) ___ as a babysitter for two years. I (start) ___ in 2024.\n> **Manager:** (you / ever / work) ___ in a shop?\n> **Sofia:** Yes, last summer I (work) ___ in a bakery for a month.\n> **Manager:** Why are your hands so red?\n> **Sofia:** Oh, I (paint) ___ my bedroom all morning!\n> **Manager:** (you / finish) ___ it yet?\n> **Sofia:** No, I (not finish) ___ it yet.\n\n1. Complète les huit blancs.\n2. Justifie en une phrase chacun des temps choisis pour les blancs 2, 3, 5 et 6.\n3. Traduis : « Elle a écrit trois lettres ce matin (la matinée est finie). » puis « Elle a écrit trois lettres (elles sont prêtes). » et explique la différence.","bareme":[{"critere":"Huit formes verbales justes et bien construites","points":8},{"critere":"Justifications des blancs 2, 3, 5 et 6","points":6},{"critere":"Deux traductions justes (wrote / has written)","points":3},{"critere":"Explication récit daté / bilan au présent","points":3}],"dureeMin":18,"corrige":"**1.**\n1. *How long **have you been working** (ou **have you worked**) as a babysitter?*\n2. *I **have been working** (ou **have worked**) as a babysitter for two years.*\n3. *I **started** in 2024.*\n4. ***Have you ever worked** in a shop?*\n5. *Last summer I **worked** in a bakery for a month.*\n6. *I **have been painting** my bedroom all morning!*\n7. ***Have you finished** it yet?*\n8. *No, I **haven't finished** it yet.*\n\n**2.**\n- Blanc 2 : situation commencée dans le passé qui **dure encore**, avec *for* → present perfect (BE + -ING souligne la durée).\n- Blanc 3 : fait **daté** (*in 2024*) → prétérit ; un fait daté ne va jamais au present perfect.\n- Blanc 5 : *last summer* situe le fait dans un passé terminé → prétérit, même avec *for a month* (l'action est finie).\n- Blanc 6 : BE + -ING insiste sur la **durée** et ses **traces** visibles (les mains rouges).\n\n**3.** *She wrote three letters this morning.* (récit d'un moment passé et terminé → prétérit) / *She has written three letters.* (bilan : le **résultat** compte maintenant, les lettres sont écrites → present perfect). Le prétérit raconte un fait situé ; le present perfect fait le bilan au présent, sans repère daté."}$exo$::jsonb),
  ('b49eef22-c717-5979-8065-33512540d654'::uuid, 1, 'traduction', $exo${"titre":"Qu'est-ce qui s'est passé avant ?","consigne":"Mets un des deux verbes au past perfect et l'autre au prétérit, selon l'ordre réel des faits.","enonce":"**Conjugue les verbes : l'un au past perfect, l'autre au prétérit.**\n\n1. When we (arrive) ___ at the station, the train (already / leave) ___.\n2. She (be) ___ tired because she (not sleep) ___ well.\n3. After he (finish) ___ his homework, he (go) ___ out.\n4. I (recognise) ___ the town: I (visit) ___ it as a child.\n\n**5.** Dans *He'd gone* et *He'd go*, que remplace *'d* ? Explique comment tu le sais.","bareme":[{"critere":"Past perfect (had + participe passé) pour le fait le plus ancien","points":10},{"critere":"Prétérit juste pour le fait le plus récent","points":6},{"critere":"Distinction had / would après 'd expliquée","points":4}],"dureeMin":8,"corrige":"1. *When we **arrived** at the station, the train **had already left**.* — le départ du train est antérieur.\n2. *She **was** tired because she **hadn't slept** well.* — le mauvais sommeil est antérieur.\n3. *After he **had finished** his homework, he **went** out.* — *after* appelle le past perfect pour la première action.\n4. *I **recognised** the town: I **had visited** it as a child.* — la visite est antérieure.\n\n5. *He'd gone* : *'d* = **had**, car il est suivi d'un **participe passé** (*gone*). *He'd go* : *'d* = **would**, car il est suivi d'une **base verbale** (*go*)."}$exo$::jsonb),
  ('b49eef22-c717-5979-8065-33512540d654'::uuid, 2, 'traduction', $exo${"titre":"Ce que Tom a raconté","consigne":"Rapporte au discours indirect ce que Tom a dit, puis traduis la phrase de la question 2.","enonce":"**1. Tom a dit hier :**\n\n> « I have lost my phone. »\n> « I left it on the bus. »\n> « Nobody has called me since this morning. »\n\nRapporte ses paroles en commençant chaque phrase par *Tom said (that)…*\n\n**2. Traduis :** « Quand le médecin est arrivé, Paul était épuisé : il conduisait depuis dix heures. »\n\n**3.** Justifie le temps employé pour « il conduisait depuis dix heures ».","bareme":[{"critere":"Discours indirect : present perfect et prétérit transformés en past perfect","points":8},{"critere":"Pronoms et repères adaptés (he, his, it, that morning)","points":3},{"critere":"Traduction avec had been driving for ten hours","points":6},{"critere":"Justification : durée de l'action antérieure","points":3}],"dureeMin":11,"corrige":"**1.**\n- *Tom said (that) he **had lost** his phone.* (present perfect → past perfect)\n- *Tom said (that) he **had left** it on the bus.* (prétérit → past perfect)\n- *Tom said (that) nobody **had called** him since **that** morning.* (present perfect → past perfect ; *this morning* devient *that morning*, accepté aussi *since the morning*)\nPronoms : *I → he*, *my → his*, *me → him*.\n\n**2.** *When the doctor arrived, Paul was exhausted: he had been driving for ten hours.*\n\n**3.** *Had been driving* : past perfect en BE + -ING. Il marque une action **antérieure** à l'arrivée du médecin (déjà au passé) et insiste sur sa **durée** (*for ten hours*), qui explique l'épuisement."}$exo$::jsonb),
  ('b49eef22-c717-5979-8065-33512540d654'::uuid, 3, 'traduction', $exo${"titre":"Le soir du concert","consigne":"Traduis le récit en anglais, puis réponds aux questions en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Quand Inès est arrivée au stade, le concert avait déjà commencé. Elle avait attendu le bus pendant une heure et elle avait oublié son billet à la maison. Heureusement, son amie Zoé avait gardé une copie sur son téléphone. Si Inès avait su, elle serait partie plus tôt.\n\n*Aide : billet = ticket ; garder = to keep (kept, kept).*\n\n**2.** Classe dans l'ordre chronologique réel les cinq faits du récit (arrivée, début du concert, attente du bus, oubli du billet, copie gardée par Zoé — l'ordre des trois derniers entre eux importe peu, dis seulement qu'ils sont antérieurs à l'arrivée).\n\n**3.** Quelle structure emploie la dernière phrase ? Qu'exprime-t-elle ?","bareme":[{"critere":"Past perfect juste pour les faits antérieurs (had started, had forgotten, had kept)","points":6},{"critere":"Had been waiting ou had waited for an hour ; prétérit arrived","points":4},{"critere":"Irréel du passé : If Inès had known, she would have left earlier","points":4},{"critere":"Ordre chronologique expliqué","points":3},{"critere":"Structure et valeur de la dernière phrase","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *When Inès arrived at the stadium, the concert had already started. She had been waiting for the bus for an hour and she had forgotten her ticket at home. Luckily, her friend Zoé had kept a copy on her phone. If Inès had known, she would have left earlier.*\n\nAcceptés : *had waited for the bus for an hour* ; *Fortunately* ; *had begun*.\n\n**2.** L'attente du bus, l'oubli du billet et la copie gardée par Zoé sont **antérieurs** à l'arrivée ; le concert a commencé avant l'arrivée ; l'arrivée d'Inès est le dernier fait, au **prétérit**, qui sert de repère. Tous les faits antérieurs sont au **past perfect** : il correspond au plus-que-parfait français (« avait commencé », « avait oublié »).\n\n**3.** *If* + **past perfect**, *would have* + **participe passé** : c'est l'**irréel du passé**. Inès n'a pas su, elle n'est pas partie plus tôt : on imagine ce qui aurait pu se passer et qui ne s'est pas produit."}$exo$::jsonb),
  ('123fc555-ac90-56d8-90b0-7ee75eacd6f7'::uuid, 1, 'traduction', $exo${"titre":"Will ou be going to ?","consigne":"Complète chaque phrase avec la forme de futur qui convient, puis corrige l'erreur de la question 2.","enonce":"**1. Complète avec will, be going to, le présent en -ING ou le présent simple.**\n\n1. The phone is ringing! — Don't move, I ___ (answer) it.\n2. Look at those black clouds: it ___ (rain).\n3. We ___ (fly) to Dublin on Monday: the tickets are booked.\n4. Hurry up! The train ___ (leave) at 6:15.\n\n**2. Corrige :** *I'll call you when I will get home.*","bareme":[{"critere":"Forme de futur juste dans les quatre phrases","points":14},{"critere":"Correction : présent après when (when I get home)","points":6}],"dureeMin":6,"corrige":"**1.**\n1. *I**'ll answer** it.* — décision prise au moment où l'on parle → *will*.\n2. *It**'s going to rain**.* — prédiction fondée sur un indice visible → *be going to*.\n3. *We**'re flying** to Dublin on Monday.* — programme fixé, avec une date → présent en -ING.\n4. *The train **leaves** at 6:15.* — horaire officiel → présent simple.\n\n**2.** *I'll call you when I **get** home.* Après *when* (et *as soon as, until, before, after, if*), on emploie le **présent**, jamais *will*."}$exo$::jsonb),
  ('123fc555-ac90-56d8-90b0-7ee75eacd6f7'::uuid, 2, 'traduction', $exo${"titre":"Et si… ? Trois hypothèses","consigne":"Termine chaque phrase en respectant le type d'hypothèse, puis traduis les deux phrases de la question 2.","enonce":"**1. Complète en conjuguant le verbe entre parenthèses.**\n\n1. If it (rain) ___ tomorrow, we will stay at home.\n2. If I (have) ___ more money, I would travel around the world.\n3. If you had told me, I (help) ___ you.\n4. If I (be) ___ you, I would talk to her.\n\n**2. Traduis en anglais.**\n\n5. Si tu te dépêches, tu auras le bus.\n6. Si j'avais su, je serais venu.\n\n**3.** Pour les phrases 1, 2 et 3, indique le type (1, 2 ou 3) et ce qu'il exprime.","bareme":[{"critere":"Formes verbales justes dans les quatre phrases (rains, had, would have helped, were)","points":8},{"critere":"Deux traductions justes (type 1 et type 3)","points":6},{"critere":"Types identifiés avec leur valeur (possible, irréel du présent, irréel du passé)","points":6}],"dureeMin":11,"corrige":"**1.**\n1. *If it **rains** tomorrow…* — présent après *if* (jamais *will rain*).\n2. *If I **had** more money…* — prétérit dans la subordonnée.\n3. *…I **would have helped** you.* — *would have* + participe passé.\n4. *If I **were** you…* — *were* est la forme soignée à toutes les personnes (*was* toléré à l'oral, mais on attend *were*).\n\n**2.**\n5. *If you hurry, you will catch the bus.* (*you'll get the bus* accepté)\n6. *If I had known, I would have come.*\n\n**3.**\n- Phrase 1 : **type 1**, *if* + présent / *will* : le **possible**.\n- Phrase 2 : **type 2**, *if* + prétérit / *would* : l'**irréel du présent** (je n'ai pas assez d'argent).\n- Phrase 3 : **type 3**, *if* + past perfect / *would have* : l'**irréel du passé** (tu ne me l'as pas dit).\n\nJamais *would* dans la subordonnée en *if*."}$exo$::jsonb),
  ('123fc555-ac90-56d8-90b0-7ee75eacd6f7'::uuid, 3, 'traduction', $exo${"titre":"Les projets de Karim","consigne":"Rédige en anglais le texte demandé (70 à 90 mots), puis justifie tes choix en français.","enonce":"**Situation.** Karim, 16 ans, écrit à son correspondant anglais pour lui parler de ses projets d'été. Voici ses notes :\n\n> - Il a déjà décidé de chercher un petit boulot (intention ancienne).\n> - Son avion pour Londres part le 12 juillet à 10 h (horaire officiel), et il a réservé le vol avec son oncle pour ce jour-là (programme fixé).\n> - Il promet d'envoyer des photos.\n> - Il prévoit que la météo sera mauvaise, comme d'habitude.\n> - S'il gagnait au loto, il achèterait un scooter (il n'a aucune chance).\n> - Il lui téléphonera dès qu'il arrivera.\n\n1. Rédige la lettre de Karim en anglais (70 à 90 mots) en employant **toutes** les formes de l'avenir du cours et **une** hypothèse de type 2.\n2. Pour quatre phrases de ta lettre, explique en français pourquoi tu as choisi cette forme.","bareme":[{"critere":"Be going to pour l'intention, présent -ING pour le programme, présent simple pour l'horaire","points":6},{"critere":"Will pour la promesse et la prédiction","points":3},{"critere":"Hypothèse de type 2 correcte (If I won…, I would buy…)","points":3},{"critere":"Présent après as soon as (as soon as I arrive)","points":3},{"critere":"Justification de quatre choix, lettre cohérente et correcte","points":5}],"dureeMin":18,"corrige":"**1. Exemple de lettre attendue**\n\n> *Hi Jack,*\n> *This summer I'm going to look for a job. I'm flying to London with my uncle on 12th July: the plane leaves at 10 am. I'll send you lots of photos, I promise! I think the weather will be bad, as usual. If I won the lottery, I would buy a scooter, but I have no chance! I'll call you as soon as I arrive.*\n> *See you soon,*\n> *Karim*\n\n**Formes attendues** : *I'm going to look for* (intention déjà formée) ; *I'm flying… on 12th July* (programme fixé, daté) ; *the plane leaves at 10 am* (horaire officiel) ; *I'll send* (promesse) ; *the weather will be bad* (prédiction) ; *If I won…, I would buy* (type 2, irréel du présent : *if* + prétérit, *would* dans la principale) ; *as soon as I arrive* (présent après *as soon as*, jamais *will arrive*).\n\n**2.** L'élève justifie quatre choix en reprenant ces valeurs. Exemple : « *I'm going to* : Karim a déjà décidé, c'est une intention formée avant de parler. » / « *as soon as I arrive* : dans une subordonnée de temps, l'anglais met le présent pour parler de l'avenir. »"}$exo$::jsonb),
  ('c8dc4e39-37ed-53de-9059-73b4ccfdf7b6'::uuid, 1, 'traduction', $exo${"titre":"Poser les bonnes questions","consigne":"Pose la question qui porte sur le mot en gras, puis ajoute le question tag qui convient.","enonce":"**1. Pose la question portant sur le passage en gras.**\n\n1. She lives **in Manchester**.\n2. They arrived **yesterday**.\n3. He goes to the gym **twice a week**.\n4. The film lasts **two hours**.\n\n**2. Ajoute le question tag.**\n\n5. You're French, ___?\n6. She likes pizza, ___?\n7. He can't swim, ___?","bareme":[{"critere":"Questions justes : mot interrogatif + auxiliaire + sujet + base verbale","points":12},{"critere":"Question tags justes (polarité inversée, bon auxiliaire)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *Where does she live?* (pas *Where does she lives?*)\n2. *When did they arrive?*\n3. *How often does he go to the gym?*\n4. *How long does the film last?*\nL'auxiliaire *do/does/did* porte le temps et la personne, le verbe reste à la base.\n\n**2.**\n5. *You're French, **aren't you**?*\n6. *She likes pizza, **doesn't she**?* — pas d'auxiliaire dans la phrase → *do*.\n7. *He can't swim, **can he**?* — phrase négative → tag positif."}$exo$::jsonb),
  ('c8dc4e39-37ed-53de-9059-73b4ccfdf7b6'::uuid, 2, 'traduction', $exo${"titre":"L'interview d'une sportive","consigne":"Retrouve les questions du journaliste à partir des réponses de la championne, puis réponds à la question 2.","enonce":"**1. Voici les réponses de Maria, championne de natation. Écris les questions du journaliste.**\n\n1. — ___? — I started swimming **when I was six**.\n2. — ___? — I train **four hours a day**.\n3. — ___? — **My coach** taught me everything.\n4. — ___? — I admire **Laure Manaudou**.\n5. — ___? — She is **kind and very determined**.\n6. — ___? — The pool is **about two kilometres** from my house.\n\n**2.** Explique en français pourquoi les questions 3 et 4 ne se construisent pas de la même façon.","bareme":[{"critere":"Mots interrogatifs adaptés (when, how long, who, what... like, how far)","points":6},{"critere":"Ordre auxiliaire + sujet + base verbale dans les questions sur le complément","points":6},{"critere":"Question sur le sujet sans auxiliaire (Who taught you…?) et What is she like?","points":4},{"critere":"Explication question sur le sujet / sur le complément","points":4}],"dureeMin":12,"corrige":"**1.**\n1. *When did you start swimming?*\n2. *How long do you train (every day)?* (*How many hours a day do you train?* accepté)\n3. *Who taught you everything?* — pas de *did*.\n4. *Who do you admire?* (*Whom* accepté)\n5. *What is she like?* — on demande une description, son caractère (pas *How is she?*, qui demande comment elle va).\n6. *How far is the pool from your house?*\n\n**2.** Dans la question 3, *who* est le **sujet** du verbe (c'est l'entraîneur qui a appris) : on n'ajoute pas d'auxiliaire et le verbe garde le prétérit (*taught*). Dans la question 4, *who* est **complément** (Maria admire quelqu'un, le sujet est *you*) : il faut l'auxiliaire *do* devant le sujet, suivi de la base verbale."}$exo$::jsonb),
  ('c8dc4e39-37ed-53de-9059-73b4ccfdf7b6'::uuid, 3, 'traduction', $exo${"titre":"Enquête au CDI","consigne":"Corrige les questions fautives, puis rédige toi-même un questionnaire en anglais selon les consignes.","enonce":"**1. Un élève a préparé ces questions pour un sondage. Corrige chacune et explique la faute.**\n\n1. *Where you do study?*\n2. *Who did write this book?*\n3. *How often you read?*\n4. *Which book do you prefers?*\n5. *How is your best friend? — He's funny and generous.*\n\n**2. Rédige un questionnaire de six questions** sur les habitudes de lecture, en anglais. Il doit contenir :\n- une question avec *how much* ou *how many* ;\n- une question avec *which* (choix limité proposé) ;\n- une question avec *how long* ;\n- une question oui/non avec un modal ;\n- une question sur le **sujet** avec *who* ;\n- une affirmation suivie d'un **question tag**.","bareme":[{"critere":"Cinq questions fautives corrigées","points":5},{"critere":"Explication juste de chaque faute","points":5},{"critere":"Six questions produites conformes aux contraintes","points":7},{"critere":"Correction de la langue (ordre, base verbale, tag)","points":3}],"dureeMin":17,"corrige":"**1.**\n1. *Where **do you** study?* — l'auxiliaire se place **devant** le sujet.\n2. *Who **wrote** this book?* — *who* est sujet : pas d'auxiliaire *did*.\n3. *How often **do you** read?* — pas d'auxiliaire dans la phrase affirmative → on fabrique *do* devant le sujet.\n4. *Which book do you **prefer**?* — le verbe lexical reste à la base ; *do* porte la personne.\n5. *What is your best friend **like**?* — la réponse décrit un caractère : *What… like?* ; *How is he?* demande comment il va.\n\n**2. Exemple de questionnaire**\n1. *How many books do you read a month?*\n2. *Which do you prefer: novels, comics or magazines?*\n3. *How long do you read every day?*\n4. *Can you read in English?* (ou *Should the library open on Saturdays?*)\n5. *Who recommends books to you?* — question sur le sujet, sans *do*.\n6. *You like reading, don't you?* — tag de polarité inversée avec *do*.\n\nToute question juste qui respecte les contraintes est acceptée."}$exo$::jsonb),
  ('ef18c6ba-e202-5378-a388-f9e4a5869aec'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus cher, le meilleur","consigne":"Mets l'adjectif au comparatif ou au superlatif selon la consigne entre crochets.","enonce":"**Complète.**\n\n1. My brother is ___ than me. (tall) [comparatif]\n2. This phone is ___ than that one. (expensive) [comparatif]\n3. Today is ___ than yesterday. (hot) [comparatif]\n4. It's ___ film of the year. (good) [superlatif]\n5. This is ___ exercise in the book. (difficult) [superlatif]\n6. My marks are ___ than last term. (bad) [comparatif]\n7. Emma is ___ her sister. (tall) [égalité]","bareme":[{"critere":"Adjectifs courts et longs bien traités (-er / more, -est / the most)","points":8},{"critere":"Irréguliers justes (the best, worse) et doublement de consonne (hotter)","points":8},{"critere":"Égalité avec as … as","points":4}],"dureeMin":6,"corrige":"1. *taller than* — adjectif court → -er + *than*.\n2. *more expensive than* — adjectif long → *more … than*.\n3. *hotter than* — doublement de la consonne finale.\n4. *the best film* — *good* est irrégulier ; le superlatif prend toujours *the*.\n5. *the most difficult exercise* — adjectif long.\n6. *worse than* — *bad* est irrégulier.\n7. *as tall as* — égalité."}$exo$::jsonb),
  ('ef18c6ba-e202-5378-a388-f9e4a5869aec'::uuid, 2, 'traduction', $exo${"titre":"Comparer deux villes","consigne":"Compare les deux villes en anglais à partir du tableau, en six phrases.","enonce":"**Données.**\n\n| | Brighton | York |\n| Habitants | environ 280 000 | environ 200 000 |\n| Prix moyen d'un repas | 18 £ | 15 £ |\n| Jours de pluie par an | 110 | 110 |\n| Distance de Londres | 85 km | 330 km |\n| Note des touristes | 4,5 / 5 | 4,7 / 5 |\n\nÉcris **six** phrases en anglais :\n1. une comparaison de supériorité avec un adjectif **court** ;\n2. une comparaison avec un adjectif **long** ;\n3. une comparaison d'**égalité** ;\n4. une comparaison avec *far* ;\n5. une phrase avec un **superlatif** (tu peux ajouter une ville de ton choix) ;\n6. une comparaison d'**infériorité** (*not as … as* ou *less … than*).","bareme":[{"critere":"Supériorité courte et longue justes et conformes au tableau","points":6},{"critere":"Égalité et infériorité justes","points":5},{"critere":"Farther/further et superlatif avec the","points":5},{"critere":"Phrases correctes et cohérentes avec les données","points":4}],"dureeMin":11,"corrige":"**Exemples de phrases attendues**\n1. *Brighton is bigger than York.* (*bigger* : doublement du g)\n2. *A meal is more expensive in Brighton than in York.*\n3. *Brighton is as rainy as York.* (110 jours dans les deux villes)\n4. *York is farther (further) from London than Brighton.*\n5. *York is the most popular of the two… / London is the biggest city in England.* On accepte un superlatif juste avec *the*.\n6. *York is not as big as Brighton.* ou *A meal in York is less expensive than in Brighton.*\n\nFautes pénalisées : *more bigger*, *the most big*, *very bigger*, superlatif sans *the*, comparaison contraire aux données."}$exo$::jsonb),
  ('ef18c6ba-e202-5378-a388-f9e4a5869aec'::uuid, 3, 'traduction', $exo${"titre":"La publicité du nouveau téléphone","consigne":"Traduis la publicité en anglais, repère les fautes de la version d'un camarade, puis explique la structure des proportions.","enonce":"**1. Thème : traduis en anglais.**\n\n> Le nouveau Zéphyr est plus léger et beaucoup plus rapide que l'ancien modèle. Son écran est le plus lumineux du marché. Les téléphones sont de plus en plus chers, mais le Zéphyr coûte moins cher que ses rivaux. Plus vous l'utiliserez, plus vous l'aimerez !\n\n*Aide : léger = light ; lumineux = bright ; rival = rival.*\n\n**2.** Un camarade a écrit : *The new Zéphyr is more lighter and very faster than the old model. Its screen is brightest on the market.* Relève les trois fautes et corrige-les en citant la règle.\n\n**3.** Explique la construction de la dernière phrase de la publicité.","bareme":[{"critere":"Comparatifs justes : lighter, much faster, less expensive (cheaper accepté)","points":5},{"critere":"Superlatif the brightest et progression more and more expensive","points":4},{"critere":"Proportion the more … the more","points":3},{"critere":"Trois fautes du camarade corrigées et justifiées","points":6},{"critere":"Explication de la structure de proportion","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *The new Zéphyr is lighter and much faster than the old model. Its screen is the brightest on the market. Phones are more and more expensive, but the Zéphyr is less expensive than its rivals. The more you use it, the more you will love it!*\n\nAcceptés : *cheaper than its rivals* ; *costs less than its rivals* ; *the more you'll like it*. *Phones* : pluriel au sens général, sans article.\n\n**2.**\n- *more lighter* → *lighter* : jamais de **double marque** ; *light* est court → -er.\n- *very faster* → *much faster* : *very* ne se combine jamais avec un comparatif.\n- *is brightest* → *is **the** brightest* : le superlatif prend toujours *the*.\n\n**3.** *The more…, the more…* exprime la **proportion** : deux quantités augmentent ensemble. Chaque moitié commence par *the* + comparatif ; le verbe suit le sujet sans inversion (*the more you use it*)."}$exo$::jsonb),
  ('de6d964c-a7ff-5296-bfc5-8306422a3772'::uuid, 1, 'traduction', $exo${"titre":"Who, which ou whose ?","consigne":"Complète avec le pronom relatif qui convient, puis corrige l'erreur de la question 2.","enonce":"**1. Complète avec who, which, whose ou where.**\n\n1. The girl ___ won the race is my cousin.\n2. This is the book ___ I told you about.\n3. I have a friend ___ father is a pilot.\n4. That's the café ___ we met.\n5. My uncle, ___ lives in York, is a doctor.\n\n**2. Corrige :** *He said me that he was tired.*","bareme":[{"critere":"Relatifs justes dans les cinq phrases","points":14},{"critere":"Correction said / told me et règle","points":6}],"dureeMin":7,"corrige":"**1.**\n1. *who* — une personne (*that* accepté : relative déterminative).\n2. *which* — une chose (*that* ou pronom effacé acceptés : il est complément).\n3. *whose* — la possession, « dont le père ».\n4. *where* — un lieu.\n5. *who* — une personne, relative **appositive** entre virgules : *that* impossible.\n\n**2.** *He **told** me that he was tired.* ou *He **said** that he was tired.* *Tell* exige un complément de personne, *say* l'interdit : *He said me* est une faute lourde."}$exo$::jsonb),
  ('de6d964c-a7ff-5296-bfc5-8306422a3772'::uuid, 2, 'traduction', $exo${"titre":"Relier les idées","consigne":"Relie chaque paire de phrases en une seule, avec le mot demandé.","enonce":"**Relie les phrases avec le mot indiqué.**\n\n1. I met a woman. She speaks six languages. (*who*)\n2. Paris is a beautiful city. It attracts millions of tourists. (*which*, relative appositive)\n3. This is the student. Her project won a prize. (*whose*)\n4. He was tired. He went on working. (*although*)\n5. She spoke slowly. Everyone could understand. (*so that*)\n6. I'll wait here. You come back. (*until*)\n\n**7.** Dans quelle phrase la virgule est-elle obligatoire, et pourquoi ne peut-on pas y employer *that* ?","bareme":[{"critere":"Trois relatives justes (who, which avec virgules, whose)","points":8},{"critere":"Trois circonstancielles justes (although, so that, until + présent)","points":8},{"critere":"Explication relative appositive / that impossible","points":4}],"dureeMin":12,"corrige":"1. *I met a woman who speaks six languages.*\n2. *Paris, which attracts millions of tourists, is a beautiful city.*\n3. *This is the student whose project won a prize.*\n4. *Although he was tired, he went on working.* (ou *He went on working although he was tired.*)\n5. *She spoke slowly so that everyone could understand.* — but, avec un modal.\n6. *I'll wait here until you come back.* — présent après *until*, jamais *will come*.\n\n**7.** Phrase 2 : la relative est **appositive**, elle **ajoute** une information sur un nom déjà identifié (Paris). Elle est encadrée de virgules et *that* y est **impossible** ; il ne s'emploie que dans une relative déterminative, qui identifie le nom."}$exo$::jsonb),
  ('de6d964c-a7ff-5296-bfc5-8306422a3772'::uuid, 3, 'traduction', $exo${"titre":"La biographie d'une inventrice","consigne":"Traduis le texte en anglais, puis réponds aux questions d'analyse en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Hedy Lamarr, qui était une actrice célèbre, a aussi inventé un système de communication. Le système qu'elle a imaginé est utilisé aujourd'hui dans le wifi. Bien qu'elle fût connue pour ses films, peu de gens savaient qu'elle était inventrice. Elle a dit à un journaliste qu'elle trouvait les idées faciles.\n\n*Aide : inventer = to invent ; imaginer (concevoir) = to design ; peu de gens = few people.*\n\n**2.** Dans ta traduction, relève :\n- une relative appositive et une relative déterminative, en justifiant leur différence ;\n- une relative où le pronom peut s'effacer, et explique pourquoi ;\n- une complétive et une circonstancielle de concession.\n\n**3.** Pourquoi as-tu employé *told* et non *said* dans la dernière phrase ?","bareme":[{"critere":"Traduction juste des deux relatives (who… ; the system (that) she designed)","points":5},{"critere":"Concession avec although / even though et complétive avec that (ou that effacé)","points":4},{"critere":"Told a journalist (that)… correct","points":2},{"critere":"Analyse juste : appositive / déterminative, effacement du relatif complément","points":6},{"critere":"Explication say / tell","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *Hedy Lamarr, who was a famous actress, also invented a communication system. The system (that) she designed is used in wifi today. Although she was known for her films, few people knew (that) she was an inventor. She told a journalist (that) she found ideas easy.*\n\n**2.**\n- ***who was a famous actress*** : relative **appositive**, entre virgules, elle **ajoute** une information sur une personne déjà identifiée ; *that* impossible. ***(that) she designed*** : relative **déterminative**, sans virgule, elle **identifie** de quel système on parle.\n- Dans *the system (that) she designed*, le pronom est **complément** (le sujet est *she*) : il peut s'effacer. Un pronom **sujet** (*who was a famous actress*) ne s'efface jamais.\n- Complétive : *(that) she was an inventor* (ou *(that) she found ideas easy*), introduite par *that*, souvent omis. Concession : *Although she was known for her films* (*even though* accepté).\n\n**3.** « Dire à quelqu'un » : il y a un complément de personne (*a journalist*). *Tell* l'exige, *say* l'interdit (*she said to a journalist* serait possible, mais *she said a journalist* est faux)."}$exo$::jsonb),
  ('04e22a95-7692-5dbd-8be7-4d2bb117d749'::uuid, 1, 'traduction', $exo${"titre":"For, since, ago, during, while","consigne":"Complète chaque phrase avec for, since, ago, during ou while.","enonce":"**Complète.**\n\n1. I have lived in Nantes ___ 2021.\n2. She has been a nurse ___ fifteen years.\n3. We moved here three years ___.\n4. My phone rang ___ the film.\n5. He fell asleep ___ he was reading.\n6. Nobody spoke ___ the meeting.\n7. They have known each other ___ they were children.","bareme":[{"critere":"For / since justes (durée / point de départ)","points":9},{"critere":"Ago placé après la durée avec le prétérit","points":3},{"critere":"During devant un nom, while devant une proposition","points":8}],"dureeMin":6,"corrige":"1. *since 2021* — point de départ.\n2. *for fifteen years* — durée.\n3. *three years ago* — point du passé compté à rebours, avec le prétérit (*moved*).\n4. *during the film* — *during* + nom.\n5. *while he was reading* — *while* + sujet et verbe.\n6. *during the meeting* — nom.\n7. *since they were children* — point de départ exprimé par une proposition."}$exo$::jsonb),
  ('04e22a95-7692-5dbd-8be7-4d2bb117d749'::uuid, 2, 'traduction', $exo${"titre":"La carte postale de Jade","consigne":"Traduis la carte postale en anglais en choisissant bien les mots de la temporalité et les temps.","enonce":"**Thème : traduis en anglais.**\n\n> Coucou Nathan ! Je suis en Écosse depuis dix jours. Je suis arrivée il y a dix jours et j'ai déjà visité trois châteaux. Pendant la visite d'hier, il a plu. Pendant que nous marchions, un guide nous a raconté des légendes. Je dois rendre ma voiture de location d'ici vendredi. Je rentre dans deux semaines !\n\n*Aide : château = castle ; voiture de location = rental car ; rendre = to return ; raconter = to tell.*","bareme":[{"critere":"Depuis dix jours : present perfect + for ; il y a dix jours : prétérit + ago","points":6},{"critere":"During + nom et while + proposition","points":5},{"critere":"By Friday et in two weeks","points":5},{"critere":"Autres temps et vocabulaire corrects","points":4}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n> *Hi Nathan! I have been in Scotland for ten days. I arrived ten days ago and I have already visited three castles. During yesterday's visit, it rained. While we were walking, a guide told us legends. I have to return my rental car by Friday. I'm coming back in two weeks!*\n\n**Points attendus**\n- « depuis dix jours » (situation qui dure) → *have been … for ten days* ; jamais *I am in Scotland since*.\n- « il y a dix jours » → *ten days ago*, avec le **prétérit** *arrived* (jamais *I have arrived ten days ago*).\n- « pendant la visite » → *during* + nom ; « pendant que nous marchions » → *while* + proposition.\n- « d'ici vendredi » → *by Friday* (au plus tard), pas *until*.\n- « dans deux semaines » → *in two weeks*.\n\nAcceptés : *during the visit yesterday* ; *I must return* ; *I'll be back in two weeks*."}$exo$::jsonb),
  ('04e22a95-7692-5dbd-8be7-4d2bb117d749'::uuid, 3, 'traduction', $exo${"titre":"La chronologie d'une association","consigne":"Lis la fiche, rédige un court paragraphe en anglais, puis corrige et explique les fautes d'un camarade.","enonce":"**Fiche : l'association « Green Street » (nous sommes en 2026)**\n\n> - Créée en 2018 par Aya et Léo.\n> - Nettoie les parcs de la ville chaque dimanche depuis sa création.\n> - A planté 500 arbres pendant l'hiver 2023.\n> - Prépare un grand festival : il doit être prêt au plus tard le 1er juin, et il durera jusqu'au 3 juin.\n\n1. Rédige un paragraphe de 60 à 80 mots en anglais sur l'association. Tu dois employer : *for*, *since*, *ago*, *during*, *while*, *by*, *until*.\n\n2. Corrige ces phrases d'un camarade et explique chaque faute :\n- *The association exists since eight years.*\n- *It was created ago eight years.*\n- *They planted trees while the winter.*","bareme":[{"critere":"For et since avec le present perfect","points":4},{"critere":"Ago après la durée avec le prétérit","points":3},{"critere":"During + nom et while + proposition justes","points":3},{"critere":"By et until employés dans leur sens (au plus tard / jusqu'à)","points":4},{"critere":"Trois phrases corrigées et fautes expliquées","points":6}],"dureeMin":17,"corrige":"**1. Exemple de paragraphe attendu**\n\n> *Green Street was created eight years ago by Aya and Léo. It has existed for eight years, and its members have cleaned the city parks every Sunday since 2018. During the winter of 2023, they planted 500 trees. While they were planting, many neighbours came to help. Now they are preparing a big festival: it must be ready by 1st June, and it will last until 3rd June.*\n\nÀ vérifier : *eight years ago* + prétérit (*was created*) ; *for eight years* et *since 2018* avec le present perfect (situation qui dure) ; *during* + nom ; *while* + proposition ; *by 1st June* = au plus tard ; *until 3rd June* = jusqu'à.\n\n**2.**\n- *The association **has existed for** eight years.* — situation qui dure encore → present perfect ; une **durée** → *for* (*since* introduit un point de départ).\n- *It was created **eight years ago**.* — *ago* se place **après** la durée.\n- *They planted trees **during** the winter.* — *winter* est un nom : il faut la préposition *during* ; *while* exige un sujet et un verbe."}$exo$::jsonb),
  ('098b4f81-9a0a-53cd-b573-1bf57d4eeead'::uuid, 1, 'traduction', $exo${"titre":"Because ou because of ?","consigne":"Complète chaque phrase avec l'expression qui convient.","enonce":"**Complète avec : because, because of, thanks to, to, for, so as not to.**\n\n1. The match was cancelled ___ the storm.\n2. I stayed at home ___ I was ill.\n3. I passed my exam ___ your help.\n4. I bought these flowers ___ my grandmother.\n5. She went to the library ___ borrow a book.\n6. He left early ___ be late.","bareme":[{"critere":"Cause : because / because of / thanks to selon ce qui suit","points":10},{"critere":"But et « pour » : for + nom, to + verbe, so as not to","points":10}],"dureeMin":6,"corrige":"1. *because of the storm* — suivi d'un **nom**.\n2. *because I was ill* — suivi d'une **proposition**.\n3. *thanks to your help* — cause positive + nom.\n4. *for my grandmother* — « pour » + nom → *for*.\n5. *to borrow a book* — « pour » + verbe → *to* (jamais *for to*).\n6. *so as not to be late* — but négatif (pas *to not be late*)."}$exo$::jsonb),
  ('098b4f81-9a0a-53cd-b573-1bf57d4eeead'::uuid, 2, 'traduction', $exo${"titre":"Pourquoi Lucas fait du bénévolat","consigne":"Traduis le texte en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> Lucas est bénévole dans une association pour aider les personnes âgées. Comme il habite près du centre, il y va à pied. Il a commencé à cause de sa grand-mère, qui vivait seule. Il parle fort pour que tout le monde puisse l'entendre. Il a reçu un prix pour son engagement.\n\n*Aide : bénévole = volunteer ; personnes âgées = elderly people ; engagement = commitment ; prix = award.*\n\n**2.** Pour chaque mot anglais qui traduit « pour » dans ta traduction, explique pourquoi tu l'as choisi.","bareme":[{"critere":"But : to help ; so that everyone can/could hear him","points":5},{"critere":"Cause : as/since he lives ; because of his grandmother","points":5},{"critere":"For + -ING ou for + nom pour la justification du prix","points":3},{"critere":"Explication des choix de « pour »","points":4},{"critere":"Vocabulaire et orthographe","points":3}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n\n> *Lucas is a volunteer in an association to help elderly people. As he lives near the centre, he walks there. He started because of his grandmother, who lived alone. He speaks loudly so that everyone can hear him. He received an award for his commitment.*\n\nAcceptés : *Since he lives…* ; *in order to help* ; *so that everyone could hear him* ; *He got an award*.\n\n**2.**\n- *to help* : « pour » suivi d'un **verbe** → *to* + base verbale (but).\n- *so that everyone can hear him* : but avec un **sujet différent** (*everyone*) → *so that* + proposition, avec un modal.\n- *for his commitment* : « pour » suivi d'un **nom** → *for* ; il justifie le prix.\n- *because of his grandmother* : cause suivie d'un nom → *because of* (pas *because*).\n- *As he lives* : cause déjà connue, suivie d'une proposition."}$exo$::jsonb),
  ('098b4f81-9a0a-53cd-b573-1bf57d4eeead'::uuid, 3, 'traduction', $exo${"titre":"Défendre un projet de piste cyclable","consigne":"Rédige un court texte argumentatif en anglais, puis corrige les fautes d'un camarade en expliquant la règle.","enonce":"**1. Production (70 à 90 mots).** Le conseil municipal hésite à construire une piste cyclable devant ton lycée. Écris un message au maire pour défendre le projet. Tu dois employer :\n- deux expressions de **cause** suivies d'une proposition (*because*, *since* ou *as*) ;\n- deux expressions de **cause** suivies d'un nom (*because of*, *due to*, *thanks to*) ;\n- *to* + base verbale, *in order to* et *so that* ;\n- un but **négatif** avec *so as not to*.\n\n**2.** Corrige et explique :\n- *Many students are late because of the traffic is heavy.*\n- *We need a bike lane for to be safe.*\n- *We ride carefully to not have accidents.*","bareme":[{"critere":"Cause : proposition après because/since/as ; nom après because of/due to/thanks to","points":6},{"critere":"But : to, in order to, so that + modal, so as not to","points":6},{"critere":"Message argumenté cohérent et correct","points":2},{"critere":"Trois phrases corrigées avec la règle","points":6}],"dureeMin":18,"corrige":"**1. Exemple de message attendu**\n\n> *Dear Mayor,*\n> *We need a bike lane in front of our school because the road is dangerous. Since many students live nearby, they could cycle every day. At the moment, they take the car because of the rain or due to the lack of safe routes. A bike lane would help us to be more independent. The city could build it in order to reduce pollution, so that everyone could breathe better. Students would leave home earlier so as not to be late. Thanks to this project, our town would be greener.*\n\nÀ vérifier : *because / since* + proposition ; *because of / due to / thanks to* + nom ; *to be*, *in order to reduce*, *so that everyone could…* (modal après *so that*), *so as not to be late*.\n\n**2.**\n- *because of the traffic is heavy* → *because **the traffic is heavy*** (ou *because of the heavy traffic*) : après *because of*, un **nom**, jamais sujet + verbe.\n- *for to be safe* → ***to** be safe* : « pour » + verbe → *to* ; *for to* n'existe pas.\n- *to not have accidents* → ***so as not to** have accidents* : c'est la forme du but négatif."}$exo$::jsonb),
  ('b02cc532-eeb5-56ac-9658-49ef79264aae'::uuid, 1, 'traduction', $exo${"titre":"Although ou despite ?","consigne":"Complète chaque phrase avec l'expression qui convient.","enonce":"**Complète avec : although, despite, unless, whereas, in case.**\n\n1. ___ the rain, we went for a walk.\n2. ___ it was raining, we went for a walk.\n3. You will miss the bus ___ you hurry.\n4. He likes tea, ___ his sister prefers coffee.\n5. Take a coat ___ it gets cold.\n\n**6. Corrige :** *Unless you don't study, you will fail.*","bareme":[{"critere":"Concession : despite + nom, although + proposition","points":8},{"critere":"Unless, whereas et in case bien employés","points":8},{"critere":"Correction de unless you don't (double négation)","points":4}],"dureeMin":7,"corrige":"1. ***Despite** the rain* — préposition + nom (*In spite of* accepté).\n2. ***Although** it was raining* — conjonction + proposition (*Even though* accepté).\n3. *…**unless** you hurry* — « sauf si tu te dépêches ».\n4. *…**whereas** his sister prefers coffee* — opposition entre deux faits (*while* accepté).\n5. *…**in case** it gets cold* — au cas où, suivi du présent.\n\n6. *Unless you study, you will fail.* (ou *If you don't study, you will fail.*) *Unless* contient déjà la négation : *unless you don't* ferait une double négation et dirait le contraire."}$exo$::jsonb),
  ('b02cc532-eeb5-56ac-9658-49ef79264aae'::uuid, 2, 'traduction', $exo${"titre":"Le débat sur l'uniforme","consigne":"Traduis les arguments en anglais, puis nomme la relation exprimée dans chaque phrase.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Bien que l'uniforme soit cher, il évite les inégalités.\n2. Malgré les critiques, le lycée l'a adopté.\n3. Les élèves de 2de l'aiment, alors que ceux de Terminale le détestent.\n4. Tu ne pourras pas entrer à moins que tu portes ta veste.\n5. Si je dirigeais le lycée, je supprimerais l'uniforme.\n\n*Aide : uniforme = uniform ; éviter = to prevent ; supprimer = to get rid of ; veste = jacket.*\n\n**2.** Pour chaque phrase, dis s'il s'agit d'une condition, d'une concession ou d'une opposition.","bareme":[{"critere":"Concession : although + proposition, despite + nom","points":6},{"critere":"Opposition avec whereas / while","points":3},{"critere":"Condition : unless sans négation ; type 2 (If I ran…, I would…)","points":6},{"critere":"Relations correctement identifiées","points":5}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n1. *Although the uniform is expensive, it prevents inequalities.* (*Even though* accepté)\n2. *Despite the criticism, the school adopted it.* (*In spite of* accepté)\n3. *Students in 2de like it, whereas those in Terminale hate it.* (*while* accepté ; *Year 11 / Year 13* acceptés)\n4. *You won't be able to come in unless you wear your jacket.* (*You can't come in unless…* accepté)\n5. *If I ran the school, I would get rid of the uniform.* — type 2, *if* + prétérit, *would* dans la principale.\n\n**2.**\n1. Concession (obstacle reconnu sans changer d'avis).\n2. Concession.\n3. Opposition (deux faits mis en regard, sans obstacle).\n4. Condition (*unless* = sauf si).\n5. Condition, irréel du présent."}$exo$::jsonb),
  ('b02cc532-eeb5-56ac-9658-49ef79264aae'::uuid, 3, 'traduction', $exo${"titre":"Pour ou contre les écrans au collège ?","consigne":"Rédige un paragraphe argumenté en anglais, puis corrige les fautes d'un camarade en expliquant la règle.","enonce":"**1. Production (80 à 100 mots).** Donne ton avis sur l'usage des tablettes en classe. Tu dois employer :\n- une **concession** avec une conjonction et une autre avec une préposition suivie d'un -ING ;\n- une **opposition** avec *whereas* et un connecteur entre deux phrases (*however* ou *on the other hand*) ;\n- une **condition** avec *unless* et une autre avec *provided that* ou *as long as* ;\n- une hypothèse **irréelle** (type 2 ou type 3).\n\n**2.** Corrige et explique :\n- *Despite tablets are useful, they distract students.*\n- *Although the cost, schools buy them.*\n- *If teachers would allow phones, students would be happier.*","bareme":[{"critere":"Deux concessions justes (conjonction + proposition ; préposition + -ING)","points":4},{"critere":"Opposition : whereas et however / on the other hand bien employés","points":4},{"critere":"Conditions : unless sans négation, provided that / as long as, irréel correct","points":5},{"critere":"Trois fautes corrigées et règle expliquée","points":6},{"critere":"Paragraphe cohérent","points":1}],"dureeMin":20,"corrige":"**1. Exemple de paragraphe attendu**\n\n> *Although tablets are expensive, I think they are useful in class. In spite of being distracting sometimes, they help students find information quickly. Some students love them, whereas others prefer paper. However, screens can hurt our eyes. Students won't learn well unless teachers control their use. Tablets are a good tool as long as we use them for short periods. If our school had more tablets, we would work in groups more easily.*\n\nÀ vérifier : *although* + proposition ; *in spite of being* (préposition + -ING) ; *whereas* entre deux faits ; *however* en début de phrase ; *unless* sans négation ; *as long as / provided that* + présent ; type 2 (*if* + prétérit, *would*) ou type 3 (*if* + past perfect, *would have* + participe).\n\n**2.**\n- *Despite tablets are useful* → ***Although** tablets are useful* (ou *Despite **being** useful*, *Despite their usefulness*) : *despite* est une **préposition**, suivie d'un nom ou d'un -ING, jamais d'une proposition.\n- *Although the cost* → ***Despite** the cost* (ou *Although it is expensive*) : *although* est une **conjonction**, il lui faut une proposition complète.\n- *If teachers would allow* → *If teachers **allowed** phones, students would be happier* : la subordonnée en *if* ne prend jamais *would* ; au type 2, elle est au **prétérit**."}$exo$::jsonb),
  ('36174924-a1c8-57f7-9f9d-0078c2351cc6'::uuid, 1, 'traduction', $exo${"titre":"What ou how ?","consigne":"Complète chaque exclamation avec what, what a / an ou how.","enonce":"**Complète avec what, what a, what an ou how.**\n\n1. … beautiful day!\n2. … terrible weather!\n3. … strange!\n4. … fast he runs!\n5. … interesting idea!\n6. … nice people!\n7. … pity!\n\n**8.** Rappelle en français la règle qui permet de choisir entre *what* et *how*.","bareme":[{"critere":"Les sept exclamations justes (dont article a / an et absence d'article)","points":14},{"critere":"Règle : what + nom, how + adjectif ou adverbe","points":6}],"dureeMin":6,"corrige":"1. ***What a** beautiful day!* (nom singulier dénombrable : *a*)\n2. ***What** terrible weather!* (indénombrable : sans article)\n3. ***How** strange!* (adjectif)\n4. ***How** fast he runs!* (adverbe)\n5. ***What an** interesting idea!* (*an* devant une voyelle)\n6. ***What** nice people!* (pluriel : sans article)\n7. ***What a** pity!*\n\n8. ***What*** est suivi d'un **nom** (groupe nominal) ; ***how*** est suivi d'un **adjectif** ou d'un **adverbe**."}$exo$::jsonb),
  ('36174924-a1c8-57f7-9f9d-0078c2351cc6'::uuid, 2, 'traduction', $exo${"titre":"So, such et l'ordre des mots","consigne":"Transforme les phrases selon les consignes, puis traduis les exclamations en anglais.","enonce":"**A. Transforme avec so, such ou such a.**\n\n1. She is very kind. → She is …\n2. It was a very good film. → It was …\n3. They are very nice people. → They are …\n\n**B. Corrige l'ordre des mots.**\n\n4. How beautiful is this place!\n5. How is it expensive!\n\n**C. Traduis en anglais.**\n\n6. Quel dommage !\n7. Comme ta sœur chante bien !\n8. Quelle belle maison !","bareme":[{"critere":"Transformations justes avec so, such a, such","points":6},{"critere":"Deux phrases corrigées sans inversion","points":6},{"critere":"Trois traductions justes","points":8}],"dureeMin":10,"corrige":"**A.**\n1. *She is **so** kind!* (*so* + adjectif)\n2. *It was **such a** good film!* (*such a* + adjectif + nom singulier)\n3. *They are **such** nice people!* (*such* + adjectif + nom pluriel)\n\n**B.** L'anglais ne fait **pas d'inversion** dans l'exclamation : le sujet reste devant le verbe.\n4. *How beautiful **this place is**!*\n5. *How expensive **it is**!*\n\n**C.**\n6. ***What a pity!*** (ou *What a shame!*)\n7. ***How well** your sister sings!* (adverbe → *how*, sans inversion)\n8. ***What a beautiful house!***"}$exo$::jsonb),
  ('36174924-a1c8-57f7-9f9d-0078c2351cc6'::uuid, 3, 'traduction', $exo${"titre":"Carte postale d'Édimbourg","consigne":"Corrige le texte, puis rédige ta propre carte postale en anglais selon les contraintes.","enonce":"**A.** Ce message contient **cinq** erreurs sur l'exclamation. Recopie les phrases fautives corrigées et explique chaque correction en français.\n\n> Dear Grandma,\n> We are in Edinburgh! How a beautiful city! What old the castle is! Yesterday it rained all day: what a terrible weather! The people are so nice people. How is delicious the food here!\n> Love, Zoé\n\n**B. Production.** Écris une carte postale de 6 à 8 phrases racontant un voyage. Tu dois employer : *what a* + nom singulier, *what* + nom pluriel ou indénombrable, *how* + adjectif + sujet + verbe, *such a*, *so*, et une exclamation toute faite (*No way!*, *Well done!*, *How come?*…).","bareme":[{"critere":"Les cinq erreurs corrigées","points":7},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les six structures imposées présentes et correctes","points":7},{"critere":"Carte postale cohérente et correcte","points":3}],"dureeMin":17,"corrige":"**A.**\n1. ***What a** beautiful city!* — devant un nom (*city*), c'est *what (a)*, pas *how*.\n2. ***How old** the castle is!* — devant un adjectif seul, c'est *how*.\n3. *What terrible weather!* — *weather* est **indénombrable** : **pas d'article**.\n4. *The people are **so nice**!* ou *They are **such nice people**!* — *so* + adjectif, *such* + adjectif + nom.\n5. *How delicious **the food is** here!* — **pas d'inversion** : sujet puis verbe.\n\n**B. Exemple attendu :**\n*Dear Tom,*\n*We're in Cornwall. **What a** lovely place! **What** beautiful beaches! **How** blue the sea is! We had **such a** good time at the surf school. I was **so** tired after the lesson. I stood up on the board: **Well done!** said the teacher.*\n\nLe correcteur vérifie : article *a* devant un singulier, pas d'article devant un pluriel ou un indénombrable, pas d'inversion après *how*, *such a* devant un nom singulier, *so* devant un adjectif seul."}$exo$::jsonb),
  ('7d0c235b-59c9-5a4f-80ee-5d9cb00f403a'::uuid, 1, 'traduction', $exo${"titre":"Former le passif","consigne":"Mets chaque phrase à la voix passive en gardant le même temps.","enonce":"**Mets à la voix passive.** Garde le complément d'agent (*by…*) seulement quand il est utile.\n\n1. They build houses. *(présent)*\n2. Shakespeare wrote Hamlet. *(prétérit)*\n3. They have repaired the car. *(present perfect)*\n4. They will open the new pool next year. *(futur)*\n5. You can recycle this bottle. *(modal)*\n\n**6.** Rappelle en français comment se forme la voix passive.","bareme":[{"critere":"Les cinq phrases passives justes, au bon temps","points":15},{"critere":"Formation : be au temps voulu + participe passé, complément devenu sujet, by","points":5}],"dureeMin":7,"corrige":"1. *Houses **are built**.*\n2. *Hamlet **was written by** Shakespeare.* (l'auteur est intéressant : on garde *by*)\n3. *The car **has been repaired**.*\n4. *The new pool **will be opened** next year.*\n5. *This bottle **can be recycled**.*\n\n6. Voix passive : **be** conjugué au **temps** de la phrase active + **participe passé**. Le **complément d'objet** de l'actif devient **sujet** ; l'ancien sujet, si on le garde, est introduit par ***by***."}$exo$::jsonb),
  ('7d0c235b-59c9-5a4f-80ee-5d9cb00f403a'::uuid, 2, 'traduction', $exo${"titre":"Un article de journal","consigne":"Transforme les phrases de l'article à la voix passive, puis justifie l'emploi du passif.","enonce":"**Article.**\n\n> Last night, someone stole a famous painting from the city museum. The police have arrested two men. Experts are examining the frame. The museum will reopen the gallery on Monday.\n\n1. Réécris les **quatre** phrases à la voix passive, sans complément d'agent quand l'auteur est inconnu ou évident.\n2. Pourquoi le passif est-il fréquent dans les articles de journaux ? Donne deux raisons en français.\n3. Traduis : « On m'a donné un prix. » Donne les deux passifs possibles et indique le plus courant.","bareme":[{"critere":"Quatre phrases passives justes, au bon temps","points":10},{"critere":"Complément d'agent omis quand il est inconnu ou évident","points":3},{"critere":"Deux raisons de l'emploi du passif","points":3},{"critere":"Double passif : I was given a prize (le plus courant) et A prize was given to me","points":4}],"dureeMin":11,"corrige":"1.\n- *Last night, a famous painting **was stolen** from the city museum.* (auteur inconnu : pas de *by someone*)\n- *Two men **have been arrested**.* (*by the police* est évident, on peut l'omettre)\n- *The frame **is being examined** by experts.* (présent en BE + -ING → *is being* + participe passé ; *by experts* accepté ou omis)\n- *The gallery **will be reopened** on Monday.*\n\n2. Le passif permet de **mettre en avant ce qui a été fait** plutôt que qui l'a fait ; l'auteur est souvent **inconnu** (le voleur) ou **évident** (la police). C'est pourquoi le complément d'agent est omis dans la grande majorité des phrases passives.\n\n3. ***I was given a prize.*** (le plus courant) ou ***A prize was given to me.***"}$exo$::jsonb),
  ('7d0c235b-59c9-5a4f-80ee-5d9cb00f403a'::uuid, 3, 'traduction', $exo${"titre":"La construction du pont","consigne":"Corrige les erreurs, puis rédige un court texte informatif en anglais en employant le passif selon les contraintes.","enonce":"**A.** Chaque phrase contient une erreur sur le passif. Corrige-la et explique en français.\n\n1. The window broken by the storm.\n2. The bridge was build in 1894.\n3. English is speak in many countries.\n4. The letter has sent yesterday.\n\n**B. Production.** Rédige un texte informatif de 6 à 8 phrases sur un monument (réel ou inventé). Tu dois employer le passif à **quatre temps différents** (présent, prétérit, present perfect, futur ou modal), au moins un complément d'agent avec *by* justifié, et au moins un passif **sans** complément d'agent.\n\n**C.** Explique en français pourquoi tu as gardé *by* dans une phrase et pas dans une autre.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Passif à quatre temps différents, correctement formé","points":7},{"critere":"Usage justifié du complément d'agent (C)","points":4},{"critere":"Texte cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *The window **was** broken by the storm.* — il manque **be** : sans lui, pas de verbe conjugué.\n2. *The bridge was **built** in 1894.* — il faut le **participe passé** (*built*), pas la base verbale.\n3. *English is **spoken** in many countries.* — participe passé de *speak* : *spoken*.\n4. *The letter **was sent** yesterday.* — avec *yesterday* (moment passé précis), le **prétérit** : *was sent* ; et le passif demande *be* (*has been sent* serait incompatible avec *yesterday*).\n\n**B. Exemple attendu :**\n*Tower Bridge **was built** between 1886 and 1894. It **was designed by** Horace Jones. Today, it **is crossed** by thousands of cars every day. The bridge **has been painted** blue and white. It **can be visited** all year round. A new exhibition **will be opened** next spring.*\n\n**C.** On garde *by* quand l'auteur est **intéressant** ou nouveau (l'architecte) ; on l'omet quand il est **inconnu, évident ou sans intérêt** (ceux qui ont peint le pont) : s'il était important, on aurait gardé l'actif."}$exo$::jsonb),
  ('a98e1c18-e208-5501-9bf6-a8e71311a2b4'::uuid, 1, 'traduction', $exo${"titre":"Used to ou be used to ?","consigne":"Complète chaque phrase avec la bonne forme, puis traduis-la en français.","enonce":"**Complète avec used to, am / is used to ou is getting used to, et mets le verbe à la bonne forme.**\n\n1. When I was a child, I … (play) with dolls. *(ce n'est plus le cas)*\n2. I … (get up) early: I do it every day, it's easy for me.\n3. She has just moved to Canada. She … (live) in the cold.\n4. My grandfather … (smoke), but he stopped ten years ago.\n\n**5.** Explique en français la différence de forme du verbe après *used to* et après *be used to*.","bareme":[{"critere":"Les quatre formes justes","points":10},{"critere":"Traductions françaises justes","points":4},{"critere":"Règle : used to + base verbale, be used to + -ING","points":6}],"dureeMin":7,"corrige":"1. *I **used to play** with dolls.* — « Je jouais à la poupée (autrefois). »\n2. *I **am used to getting up** early.* — « J'ai l'habitude de me lever tôt. »\n3. *She **is getting used to living** in the cold.* — « Elle s'habitue à vivre dans le froid. »\n4. *My grandfather **used to smoke**.* — « Mon grand-père fumait (autrefois). »\n\n5. Après ***used to*** (habitude passée révolue) : **base verbale**. Après ***be / get used to*** (être habitué, s'habituer) : verbe en **-ING** ou nom."}$exo$::jsonb),
  ('a98e1c18-e208-5501-9bf6-a8e71311a2b4'::uuid, 2, 'traduction', $exo${"titre":"La vie d'avant de Grandpa Joe","consigne":"Exploite le document pour écrire des phrases avec used to, would et le présent simple.","enonce":"**Document – Grandpa Joe, 80 ans, raconte**\n\n| Autrefois | Aujourd'hui |\n|---|---|\n| went to school on foot | takes the bus to town |\n| was very shy | is very talkative |\n| every Sunday, went fishing with his father | watches football on TV |\n| didn't have a phone | calls his grandchildren every day |\n\n1. Écris **quatre** phrases sur la vie d'autrefois de Joe avec *used to* (dont une à la forme **négative**).\n2. Réécris la phrase sur la pêche avec *would*. Peut-on faire de même pour « was very shy » ? Justifie.\n3. Écris deux phrases sur sa vie d'aujourd'hui avec un adverbe de fréquence bien placé.\n4. Pose une question à Joe avec *used to*.","bareme":[{"critere":"Quatre phrases avec used to justes, dont la négative didn't use to","points":8},{"critere":"Would pour l'action répétée, impossible pour un état, justifié","points":5},{"critere":"Deux phrases au présent simple avec adverbe bien placé","points":4},{"critere":"Question Did you use to… ?","points":3}],"dureeMin":11,"corrige":"1. Exemples attendus :\n- *Joe **used to go** to school on foot.*\n- *He **used to be** very shy.*\n- *He **used to go** fishing with his father every Sunday.*\n- *He **didn't use to have** a phone.* (sans *-d* après *did*)\n\n2. *Every Sunday, he **would go** fishing with his father.* — *would* convient pour une **action répétée**. Pour « was very shy », **non** : c'est un **état** ; seul *used to* convient (*He used to be shy*, jamais *he would be shy*).\n\n3. Exemples : *He **usually takes** the bus to town.* / *He **always calls** his grandchildren.* / *He **is often** very talkative.* — l'adverbe se place **avant** le verbe lexical, **après** *be*.\n\n4. ***Did** you **use to** play football, Grandpa?*"}$exo$::jsonb),
  ('a98e1c18-e208-5501-9bf6-a8e71311a2b4'::uuid, 3, 'traduction', $exo${"titre":"Une nouvelle vie à Toronto","consigne":"Corrige les erreurs, puis rédige un texte en anglais qui oppose passé, présent et adaptation.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. I am used to swim every morning.\n2. I didn't used to like vegetables.\n3. When I was young, I would be very shy.\n4. She is getting used to speak English.\n\n**B. Production.** Nadia vient de quitter Lyon pour Toronto. Rédige son journal intime (8 à 10 phrases) : ce qu'elle faisait autrefois, ce qu'elle fait maintenant, ce à quoi elle est déjà habituée et ce à quoi elle s'habitue peu à peu. Tu dois employer : *used to* (affirmatif et négatif), *would*, *be used to*, *get used to*, et le présent simple avec deux adverbes de fréquence.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Used to affirmatif et négatif, would pour une action répétée","points":5},{"critere":"Be used to et get used to suivis de -ING ou d'un nom","points":5},{"critere":"Présent simple et adverbes bien placés, texte cohérent","points":4}],"dureeMin":18,"corrige":"**A.**\n1. *I am used to **swimming** every morning.* — après *be used to* : **-ING**.\n2. *I didn't **use** to like vegetables.* — après *did*, pas de *-d* : *didn't use to*.\n3. *When I was young, I **used to be** very shy.* — *shy* est un **état** : *would* est impossible.\n4. *She is getting used to **speaking** English.* — après *get used to* : **-ING**.\n\n**B. Exemple attendu :**\n*In Lyon, I **used to walk** to school with my friends. Every Friday, we **would eat** crêpes together. I **didn't use to wear** a hat! Now I **always wear** one, because it's minus ten. I **usually take** the subway. I **am** already **used to speaking** English at school. But I **am** still **getting used to** the snow and to having dinner at six.*\n\nLe correcteur vérifie : base verbale après *used to*, *didn't use to*, *would* seulement pour une action, **-ING** ou nom après *be / get used to*, adverbes avant le verbe lexical."}$exo$::jsonb),
  ('bb86d76e-ec3e-55ba-88e3-a7652920e119'::uuid, 1, 'traduction', $exo${"titre":"Rapporter des paroles","consigne":"Mets chaque phrase au discours indirect après « He said » ou « She said ».","enonce":"**Mets au discours indirect.**\n\n1. « I am tired. » → He said …\n2. « I saw her. » → He said …\n3. « I will call you. » → She said …\n4. « I can swim. » → He said …\n5. « I have finished. » → She said …\n\n**6.** Explique en français ce qu'est le **recul des temps** et quand il ne s'applique pas.","bareme":[{"critere":"Les cinq phrases justes (temps reculé, pronoms adaptés)","points":15},{"critere":"Recul des temps défini, avec ses exceptions (verbe introducteur au présent, vérité générale)","points":5}],"dureeMin":7,"corrige":"1. *He said (that) he **was** tired.* (présent → prétérit)\n2. *He said (that) he **had seen** her.* (prétérit → past perfect)\n3. *She said (that) she **would** call me.* (*will* → *would* ; *you* → *me*)\n4. *He said (that) he **could** swim.* (*can* → *could*)\n5. *She said (that) she **had finished**.* (present perfect → past perfect)\n\n6. Quand le verbe introducteur est au **passé** (*said, told*), chaque temps **recule d'un cran**. Le recul ne s'applique **pas** quand le verbe introducteur est au **présent** (*He says he is tired*), ni quand le fait rapporté est **toujours vrai**."}$exo$::jsonb),
  ('bb86d76e-ec3e-55ba-88e3-a7652920e119'::uuid, 2, 'traduction', $exo${"titre":"Ce que le prof a dit","consigne":"Rapporte les paroles au discours indirect en adaptant temps, pronoms et repères.","enonce":"**Situation.** Hier, Mrs Cole a parlé à la classe. Aujourd'hui, Lucas raconte ce qu'elle a dit à Jade, qui était absente.\n\n1. « The test is tomorrow. »\n2. « I corrected your essays yesterday. »\n3. « Are you ready? »\n4. « Where do you usually revise? »\n5. « Close your books. »\n6. « Don't be late. »\n\nCommence chaque phrase par *She said*, *She told us* ou *She asked us*. Choisis bien entre *say* et *tell*.","bareme":[{"critere":"Phrases 1 et 2 : temps reculés et repères adaptés (the next day, the day before)","points":6},{"critere":"Questions 3 et 4 : if, ordre de l'affirmative","points":6},{"critere":"Ordres 5 et 6 : told us to / not to + base verbale","points":5},{"critere":"say et tell bien employés, pronoms adaptés","points":3}],"dureeMin":11,"corrige":"1. *She said (that) the test **was the next day**.* (*is* → *was* ; *tomorrow* → *the next day*)\n2. *She told us (that) she **had corrected our** essays **the day before**.* (prétérit → past perfect ; *your* → *our* ; *yesterday* → *the day before*)\n3. *She asked us **if / whether we were** ready.* (question fermée : *if / whether*, ordre de l'affirmative)\n4. *She asked us **where we usually revised**.* (question ouverte : pas de *do*, ordre de l'affirmative)\n5. *She told us **to close** our books.*\n6. *She told us **not to be** late.*\n\n***Say*** ne prend pas de complément de personne (*She said…*) ; ***tell*** en exige un (*She told **us**…*)."}$exo$::jsonb),
  ('bb86d76e-ec3e-55ba-88e3-a7652920e119'::uuid, 3, 'traduction', $exo${"titre":"Le témoin de l'accident","consigne":"Corrige les erreurs, puis réécris un dialogue entier au discours indirect.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. He said me that he was tired.\n2. She asked me where did I live.\n3. He told that he would come.\n4. She asked me are you ready.\n\n**B. Dialogue.** Un policier interroge Ryan, témoin d'un accident.\n\n> **Policeman**: Where were you at 5 pm?\n> **Ryan**: I was waiting for the bus here.\n> **Policeman**: Did you see the car?\n> **Ryan**: Yes, it was going very fast. I have never seen that car before.\n> **Policeman**: Can you describe the driver?\n> **Ryan**: He was wearing a red cap. I will help you if I can.\n> **Policeman**: Don't leave the town.\n\nRéécris tout le dialogue au **discours indirect** dans un récit au passé (*The policeman asked Ryan…*, *Ryan said…*).","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Recul des temps juste dans tout le dialogue","points":6},{"critere":"Questions rapportées (if, mot interrogatif, ordre affirmatif) et ordre rapporté","points":5},{"critere":"Pronoms, repères (here → there) et say / tell corrects","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *He **told me** / He **said** that he was tired.* — *say* ne prend pas de complément de personne.\n2. *She asked me where **I lived**.* — la question rapportée reprend l'**ordre de l'affirmative**, sans *did*.\n3. *He **said** that he would come.* — *tell* exige un complément de personne (*He told me…*).\n4. *She asked me **if I was** ready.* — question fermée : *if / whether*, ordre affirmatif, temps reculé.\n\n**B. Réponse attendue :**\n*The policeman asked Ryan **where he had been** at 5 pm. Ryan said (that) **he had been waiting** for the bus **there**. The policeman asked him **if / whether he had seen** the car. Ryan said that **it had been going** very fast and that **he had never seen** that car before. The policeman asked him **if he could** describe the driver. Ryan said that the driver **had been wearing** a red cap and that **he would help** him if **he could**. Finally, the policeman **told him not to leave** the town.*\n\nLe correcteur vérifie : prétérit → past perfect (*were* → *had been*, *saw* → *had seen*), present perfect → past perfect, *will* → *would*, *can* → *could* ; *here* → *there* ; questions sans inversion ; ordre avec *told him not to*. Tolérer *he was waiting* / *it was going* (prétérit en BE + -ING non reculé), fréquent à l'oral, mais valoriser le past perfect."}$exo$::jsonb),
  ('1dd18b35-d27e-51d4-94aa-35366acf5ed9'::uuid, 1, 'traduction', $exo${"titre":"Some, any, much, many","consigne":"Complète chaque phrase avec le quantifieur qui convient, puis réponds à la question 2.","enonce":"**1. Complète avec some, any, much ou many.**\n\n1. I have ___ money in my pocket.\n2. We don't have ___ bread.\n3. How ___ books have you got?\n4. How ___ water do you drink a day?\n5. Would you like ___ tea?\n6. Is there ___ milk in the fridge?\n\n**2.** Explique la différence de sens entre *I have a few friends* et *I have few friends*.","bareme":[{"critere":"Six quantifieurs justes","points":12},{"critere":"Différence a few (assez, rassurant) / few (trop peu) expliquée","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n1. **some** money — affirmative.\n2. **any** bread — négative.\n3. How **many** books — dénombrable pluriel.\n4. How **much** water — indénombrable.\n5. Would you like **some** tea? — offre polie : *some* même dans une question.\n6. Is there **any** milk — interrogative.\n\n**2. A few / few**\n*I have a few friends* : j'ai quelques amis, un nombre **suffisant** — le sens est positif, il rassure.\n*I have few friends* : j'ai **peu** d'amis, trop peu — le sens est négatif, il inquiète. L'article *a* change le sens."}$exo$::jsonb),
  ('1dd18b35-d27e-51d4-94aa-35366acf5ed9'::uuid, 2, 'traduction', $exo${"titre":"La fête de Yanis","consigne":"Complète le dialogue, puis justifie trois de tes choix.","enonce":"> **Yanis**: I'm organising a party. Have we got (1) ___ crisps?\n> **Mum**: No, we haven't got (2) ___ crisps, but we've got (3) ___ lemonade.\n> **Yanis**: How (4) ___ bottles?\n> **Mum**: Only two. That's not (5) ___ for twenty people!\n> **Yanis**: And how (6) ___ cake is left?\n> **Mum**: Just (7) ___ cake, but we've got (8) ___ biscuits.\n\n*Mots possibles : any, some, many, much, enough, a little, a lot of.*\n\n1. Complète les huit blancs.\n2. Justifie tes choix pour les blancs 2, 4 et 6.","bareme":[{"critere":"Huit blancs corrects","points":10},{"critere":"Justifications : forme de la phrase (négative / interrogative)","points":4},{"critere":"Justifications : dénombrable / indénombrable (many / much)","points":4},{"critere":"Clarté des explications","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **any** — question.\n(2) **any** — négative.\n(3) **some** — affirmative.\n(4) How **many** bottles — dénombrable pluriel.\n(5) not **enough** — pas assez.\n(6) How **much** cake — *cake* est ici indénombrable (de la matière).\n(7) **a little** cake — un peu de, indénombrable.\n(8) **a lot of** biscuits (ou *some*) — affirmative, dénombrable.\n\n**2. Justifications**\n- Blanc 2 : la phrase est **négative** (*haven't got*) → *any*.\n- Blanc 4 : *bottles* est **dénombrable** pluriel → *how many*.\n- Blanc 6 : *cake* au singulier, sans article, désigne une quantité de gâteau : **indénombrable** → *how much*.\n\nAccepter (8) *some* ; refuser *much biscuits* ou *many cake*."}$exo$::jsonb),
  ('1dd18b35-d27e-51d4-94aa-35366acf5ed9'::uuid, 3, 'traduction', $exo${"titre":"Le camp de vacances","consigne":"Traduis les six phrases en anglais, puis réponds à la question 2 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Il n'y a pas de lait dans le frigo.\n2. Tu veux du jus d'orange ?\n3. Prends n'importe quel livre.\n4. Nous avons trop de devoirs et pas assez de temps.\n5. Peu d'élèves sont venus : c'était triste.\n6. J'ai quelques amis au camp, alors je suis content.\n\n*Aide : came = sont venus ; at the camp = au camp.*\n\n**2.** Les phrases 5 et 6 parlent toutes deux d'une petite quantité. Explique en quoi leur sens diffère, et comment l'anglais le marque.","bareme":[{"critere":"No / any, some pour l'offre, any au sens de n'importe quel","points":6},{"critere":"Too much / enough avec les bons noms (homework indénombrable)","points":4},{"critere":"Few / a few correctement choisis","points":4},{"critere":"Explication de la nuance few / a few","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *There is no milk in the fridge.* (ou *There isn't any milk…*)\n2. *Would you like some orange juice?* — offre polie : *some*.\n3. *Take any book (you like).* — *any* en affirmative = n'importe quel.\n4. *We have too much homework and not enough time.* — *homework* est indénombrable → *too much* (pas *too many homeworks*) ; *enough* devant le nom.\n5. *Few students came: it was sad.* (*pupils* accepté)\n6. *I have a few friends at the camp, so I'm happy.*\n\n**2. La nuance**\nLes deux phrases parlent d'un petit nombre (*students*, *friends* sont dénombrables), mais :\n- *few* (sans article) = **trop peu**, sens négatif : on le regrette (« c'était triste ») ;\n- *a few* = **quelques-uns, assez**, sens positif : on s'en contente (« je suis content »).\nL'anglais marque cette différence par la seule présence de l'article *a*. Pour un indénombrable, on aurait *little* / *a little*."}$exo$::jsonb),
  ('f9338913-2163-558a-9b7e-dfcde601ce9e'::uuid, 1, 'traduction', $exo${"titre":"Bored ou boring ?","consigne":"Choisis la bonne forme de l'adjectif, puis traduis les deux groupes.","enonce":"**1. Entoure la bonne forme et recopie la phrase.**\n\n1. The film was very (bored / boring).\n2. I am (interested / interesting) in history.\n3. After the match, the players were (tired / tiring).\n4. The news was (surprised / surprising).\n5. The children were (frightened / frightening) by the storm.\n6. This book is really (interested / interesting).\n\n**2. Traduis :** une voiture rouge — deux voitures rouges.","bareme":[{"critere":"Six choix -ed / -ing justes","points":14},{"critere":"Traduction avec adjectif invariable placé avant le nom","points":6}],"dureeMin":6,"corrige":"**1. Réponses**\n1. The film was very **boring**. — le film provoque l'ennui.\n2. I am **interested** in history. — ce que je ressens.\n3. The players were **tired**. — ce qu'ils ressentent.\n4. The news was **surprising**. — la nouvelle provoque la surprise.\n5. The children were **frightened**. — ce qu'ils ressentent.\n6. This book is really **interesting**. — le livre provoque l'intérêt.\n\nRègle : **-ed** = ce que ressent la personne ; **-ing** = ce qui provoque le sentiment.\n\n**2. Traduction**\n*a red car* — *two red cars*. L'adjectif se place **avant** le nom et reste **invariable** : jamais *reds*."}$exo$::jsonb),
  ('f9338913-2163-558a-9b7e-dfcde601ce9e'::uuid, 2, 'traduction', $exo${"titre":"La brocante de Léon","consigne":"Remets les adjectifs dans l'ordre, puis traduis les groupes avec un adjectif composé.","enonce":"Léon vend des objets à une brocante. Aide-le à écrire ses étiquettes.\n\n**1. Remets les adjectifs dans le bon ordre.**\n\na. a (wooden / small / old) box\nb. a (French / beautiful / blue) vase\nc. (leather / black / big) boots\n\n**2. Traduis en anglais.**\n\na. une fille de dix ans\nb. un film de deux heures\nc. un trajet de trois kilomètres\n\n**3.** Complète : *Léon seems ___ (happy / happily).* Explique ton choix.","bareme":[{"critere":"Ordre des adjectifs juste dans les trois groupes","points":9},{"critere":"Adjectifs composés avec trait d'union et nom au singulier","points":7},{"critere":"Adjectif après le verbe d'état seem, choix expliqué","points":4}],"dureeMin":10,"corrige":"**1. Ordre** (opinion → taille → âge → forme → couleur → origine → matière)\na. *a small old wooden box* — taille, âge, matière.\nb. *a beautiful blue French vase* — opinion, couleur, origine.\nc. *big black leather boots* — taille, couleur, matière.\n\n**2. Adjectifs composés**\na. *a ten-year-old girl*\nb. *a two-hour film*\nc. *a three-kilometre journey* (ou *trip* ; *kilometer* accepté)\nTrait d'union, et le nom reste au **singulier** : jamais *ten-years-old* ni *two-hours*.\n\n**3.** *Léon seems **happy**.* — *seem* est un verbe d'état (comme be, look, feel) : il est suivi d'un **adjectif**, pas d'un adverbe."}$exo$::jsonb),
  ('f9338913-2163-558a-9b7e-dfcde601ce9e'::uuid, 3, 'traduction', $exo${"titre":"Une journée au musée","consigne":"Traduis le texte en anglais, puis justifie trois choix grammaticaux.","enonce":"**1. Thème : traduis en anglais.**\n\n> Hier, notre classe a visité un grand musée moderne. Le guide était intéressant, mais la visite de trois heures était fatigante. À la fin, nous étions fatigués. Dans une salle, il y avait une jolie petite table ronde en bois. Le musée aide les pauvres : l'entrée est gratuite pour eux.\n\n*Aide : visited = a visité ; room = salle ; free = gratuit ; entry = l'entrée ; to help = aider.*\n\n**2.** Justifie en une phrase chacun :\na) *interesting* / *tiring* / *tired* ;\nb) l'ordre des adjectifs devant *table* ;\nc) le verbe employé avec *the poor*.","bareme":[{"critere":"Adjectifs placés avant le nom, invariables, bon ordre","points":5},{"critere":"Choix -ed / -ing justes","points":4},{"critere":"Adjectif composé three-hour et adjectif substantivé the poor avec verbe au pluriel","points":4},{"critere":"Trois justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Yesterday, our class visited a big modern museum. The guide was interesting, but the three-hour visit was tiring. At the end, we were tired. In one room, there was a lovely little round wooden table. The museum helps the poor: entry is free for them.*\n(*nice* ou *pretty little round wooden table* acceptés ; *large* accepté.)\n\n**2. Justifications**\na) *interesting* et *tiring* décrivent ce qui **provoque** le sentiment (le guide, la visite) → **-ing** ; *tired* décrit ce que **ressentent** les élèves → **-ed**. *We were tiring* voudrait dire « nous étions fatigants ».\nb) Ordre : opinion (*lovely*) → taille (*little*) → forme (*round*) → matière (*wooden*).\nc) *the poor* désigne un **groupe entier** de personnes : l'adjectif substantivé prend **the** et un sens pluriel (on le reprend par *them*, et un verbe dont il serait sujet serait au pluriel : *the poor are…*).\n\nAutres points : *three-hour* avec trait d'union et sans -s ; adjectifs jamais au pluriel."}$exo$::jsonb),
  ('d6b9f124-dfcd-519b-a367-23cd9d6f82b9'::uuid, 1, 'traduction', $exo${"titre":"Repérer l'auxiliaire","consigne":"Pour chaque phrase, relève l'auxiliaire et le verbe lexical, puis donne une réponse courte.","enonce":"**1. Relève l'auxiliaire et le verbe lexical.**\n\na. She is working.\nb. I have finished.\nc. They don't know.\nd. You can go.\n\n**2. Réponds par une réponse courte (reprise).**\n\na. Do you like tea? — Yes, …\nb. Is she ready? — No, …\nc. Have you finished? — Yes, …\nd. Can he swim? — No, …","bareme":[{"critere":"Auxiliaire et verbe lexical correctement relevés dans les quatre phrases","points":10},{"critere":"Quatre réponses courtes avec le bon auxiliaire repris","points":10}],"dureeMin":7,"corrige":"**1. Repérage**\na. auxiliaire **is** (be, forme en -ING) — verbe lexical **working** (work).\nb. auxiliaire **have** (temps composé) — verbe lexical **finished** (finish).\nc. auxiliaire **do** (dans *don't*, négation) — verbe lexical **know**.\nd. auxiliaire **can** (modal) — verbe lexical **go**.\n\n**2. Réponses courtes**\na. Yes, **I do**.\nb. No, **she isn't**.\nc. Yes, **I have**.\nd. No, **he can't**.\n\nLa reprise courte répète l'**auxiliaire** de la question, jamais le verbe lexical (*Yes, I like* est faux)."}$exo$::jsonb),
  ('d6b9f124-dfcd-519b-a367-23cd9d6f82b9'::uuid, 2, 'traduction', $exo${"titre":"Questions et négations","consigne":"Mets chaque phrase à la forme interrogative, puis à la forme négative.","enonce":"Mets chaque phrase **à la forme interrogative**, puis **à la forme négative**.\n\n1. You are ready.\n2. She has finished her homework.\n3. He works in London.\n4. They can speak Spanish.\n5. You have a car.\n\n**Question finale :** pourquoi les phrases 3 et 5 ne se construisent-elles pas comme les autres ?","bareme":[{"critere":"Questions avec l'auxiliaire placé devant le sujet","points":7},{"critere":"Négations avec not juste après l'auxiliaire","points":7},{"critere":"Do employé pour work et pour have lexical","points":4},{"critere":"Explication : verbe lexical seul, il faut un auxiliaire","points":2}],"dureeMin":10,"corrige":"**Réponses**\n1. *Are you ready?* — *You aren't ready.* (*You are not ready.*)\n2. *Has she finished her homework?* — *She hasn't finished her homework.*\n3. *Does he work in London?* — *He doesn't work in London.*\n4. *Can they speak Spanish?* — *They can't speak Spanish.* (*cannot*)\n5. *Do you have a car?* — *You don't have a car.*\n\n**Explication**\nDans les phrases 1, 2 et 4, il y a déjà un auxiliaire (*are*, *has*, *can*) : il passe devant le sujet pour la question et reçoit *not* pour la négation. Dans les phrases 3 et 5, il n'y a qu'un **verbe lexical** (*works*, *have* au sens de posséder) : seul, il ne sait former ni question ni négation, il faut donc l'auxiliaire **do** (*does* à la 3e personne, et le verbe revient à la base verbale : *does he work*)."}$exo$::jsonb),
  ('d6b9f124-dfcd-519b-a367-23cd9d6f82b9'::uuid, 3, 'traduction', $exo${"titre":"L'interview d'une chanteuse","consigne":"Retrouve les questions de la journaliste, puis réponds aux questions 2 et 3.","enonce":"Une journaliste interroge la chanteuse Maya. Voici les réponses de Maya.\n\n1. (…?) — *Yes, I am. I'm very tired tonight.*\n2. (…?) — *Yes, I do. I love my fans.*\n3. (…?) — *No, I haven't. I haven't finished my new album yet.*\n4. (…?) — *Yes, I can. I can play the piano.*\n5. (…?) — *No, I don't. I don't have a dog.*\n\n**1.** Écris les cinq questions de la journaliste.\n**2.** Dans la réponse 1, *be* est-il auxiliaire ou verbe lexical ? Et *have* dans la réponse 5 ? Justifie.\n**3.** Explique pourquoi l'auxiliaire est « la clé de toute la grammaire anglaise ».","bareme":[{"critere":"Cinq questions correctes, auxiliaire devant le sujet","points":8},{"critere":"Auxiliaire de la question cohérent avec la reprise courte","points":4},{"critere":"Statut de be et de have justifié","points":5},{"critere":"Explication du rôle de l'auxiliaire (question, négation, reprise)","points":3}],"dureeMin":15,"corrige":"**1. Questions attendues**\n1. *Are you tired (tonight)?*\n2. *Do you love your fans?* (*Do you like your fans?* accepté)\n3. *Have you finished your new album (yet)?*\n4. *Can you play the piano?* (*Can you play an instrument?* accepté)\n5. *Do you have a dog?*\nLa reprise courte donne l'auxiliaire : *I am* → *Are you…?* ; *I do* → *Do you…?*, etc.\n\n**2. Statut**\n- Réponse 1 : *be* est **lexical** (verbe d'état, *I'm tired*), mais il **garde ses pouvoirs** d'auxiliaire : il passe lui-même devant le sujet (*Are you tired?*), sans *do*.\n- Réponse 5 : *have* est **lexical** (posséder) : il n'a pas ces pouvoirs, il faut **do** (*Do you have a dog?* / *I don't have a dog*).\n\n**3. La clé**\nL'auxiliaire construit la phrase : il passe **devant le sujet** pour la question, reçoit **not** pour la négation et sert à la **reprise courte**. Une fois l'auxiliaire repéré, question, négation et réponse courte se construisent toutes seules."}$exo$::jsonb),
  ('8d44a97f-eb6d-5b16-a3ec-65b1bfbb6577'::uuid, 1, 'traduction', $exo${"titre":"Make ou let ?","consigne":"Complète avec make, made, let ou lets, puis corrige la phrase fautive.","enonce":"**1. Complète.**\n\n1. My parents ___ me do my homework every evening. (ils m'obligent)\n2. My sister ___ me borrow her bike yesterday. (elle m'a autorisé)\n3. The film ___ me cry. (il m'a fait pleurer)\n4. Our teacher ___ us use a calculator. (il nous autorise)\n\n**2. Corrige :** *My mum made me to tidy my room.*","bareme":[{"critere":"Quatre formes justes (sens et temps)","points":12},{"critere":"Correction : make + complément + base verbale, sans to","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. My parents **make** me do — obliger, présent.\n2. My sister **let** me borrow — autoriser ; *let* a la même forme au prétérit.\n3. The film **made** me cry — make = faire (provoquer), prétérit.\n4. Our teacher **lets** us use — autoriser, 3e personne du présent.\n\n**2. Correction**\n*My mum made me tidy my room.* — *make* + complément + **base verbale**, sans *to*. Le *to* ne réapparaît qu'au passif : *I was made to tidy my room*."}$exo$::jsonb),
  ('8d44a97f-eb6d-5b16-a3ec-65b1bfbb6577'::uuid, 2, 'traduction', $exo${"titre":"Les courses de Mme Leroy","consigne":"Réécris chaque phrase avec la structure causative have (ou get), puis traduis les deux phrases de la question 2.","enonce":"Mme Leroy ne fait rien elle-même : elle fait tout faire par des professionnels.\n\n**1. Réécris avec have + complément + participe passé.**\n\na. A hairdresser cut her hair.\nb. A mechanic repaired her car.\nc. A painter painted her kitchen.\nd. Someone fixed her phone. (avec *get*)\n\n**2. Traduis en anglais.**\n\na. J'ai convaincu mon frère de m'aider.\nb. Je me suis fait couper les cheveux samedi.\n\n**3.** Pourquoi *I cut my hair* ne traduit-il pas « je me suis fait couper les cheveux » ?","bareme":[{"critere":"Quatre phrases causatives correctes (have / get + complément + participe passé)","points":8},{"critere":"Get + to pour convaincre, had my hair cut","points":6},{"critere":"Explication du piège I cut my hair","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\na. *She had her hair cut.*\nb. *She had her car repaired.*\nc. *She had her kitchen painted.*\nd. *She got her phone fixed.*\nConstruction : *have / get* + complément + **participe passé**. Le sujet ne fait pas l'action : il la **commande**.\n\n**2. Traduction**\na. *I got my brother to help me.* — *get* + complément + **to** + verbe = convaincre.\nb. *I had my hair cut on Saturday.* (*I got my hair cut* accepté)\n\n**3. Le piège**\n*I cut my hair* signifie que je les ai coupés **moi-même**. « Se faire couper les cheveux » par un coiffeur se dit avec la structure causative : *I had my hair cut*."}$exo$::jsonb),
  ('8d44a97f-eb6d-5b16-a3ec-65b1bfbb6577'::uuid, 3, 'traduction', $exo${"titre":"Le stage de voile","consigne":"Traduis le texte en anglais, puis réponds aux questions 2 et 3 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n> Au stage de voile, le moniteur nous faisait nager tous les matins, mais il nous laissait choisir notre bateau. Un jour, j'ai convaincu mon ami d'essayer le kayak. Ma planche était cassée, alors je l'ai fait réparer.\n\n*Aide : sailing camp = stage de voile ; instructor = moniteur ; board = planche ; to try = essayer.*\n\n**2.** Mets ces deux phrases au passif et explique ce qui change :\na. *The instructor made us swim.*\nb. *The instructor let us choose our boat.*\n\n**3.** Classe *make*, *let*, *have*, *get* selon leur sens (obliger, autoriser, faire faire, convaincre) et indique ce qui suit le complément pour chacun.","bareme":[{"critere":"Make et let + complément + base verbale au prétérit","points":5},{"critere":"Get + to (convaincre) et have + participe passé (faire réparer)","points":5},{"critere":"Passif de make avec to ; let remplacé par be allowed to","points":5},{"critere":"Tableau des quatre verbes juste","points":3},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *At the sailing camp, the instructor made us swim every morning, but he let us choose our boat. One day, I got my friend to try the kayak. My board was broken, so I had it repaired.* (*got it repaired* accepté)\n\n**2. Passif**\na. *We were made to swim.* — au passif, **to** réapparaît après *make*.\nb. *We were allowed to choose our boat.* — *let* n'a **pas de passif** : on emploie *be allowed to*.\n\n**3. Tableau**\n- **make** = obliger → complément + **base verbale** ;\n- **let** = autoriser → complément + **base verbale** ;\n- **have** = faire faire par un professionnel → complément + **participe passé** ;\n- **get** = convaincre → complément + **to** + verbe ; ou faire faire (familier) → complément + **participe passé**."}$exo$::jsonb),
  ('b92b0ef4-e23b-59e9-9d00-ba6dfb90d75e'::uuid, 1, 'traduction', $exo${"titre":"Les verbes à particule du brevet","consigne":"Complète chaque phrase avec le verbe qui convient, à la bonne forme.","enonce":"**Complète avec : give up, look after, look for, put on, find out, get up, run out of, grow up.**\n\n1. I ___ at 7 every morning.\n2. It's cold: ___ your coat!\n3. My grandma ___ my little sister on Wednesdays.\n4. I'm ___ my keys. Have you seen them?\n5. Don't ___! You can do it!\n6. We have ___ milk: can you buy some?\n7. I want to ___ the truth.\n8. She wants to be a vet when she ___.\n\n**Question :** pourquoi *look after* ne se traduit-il pas par « regarder après » ?","bareme":[{"critere":"Huit verbes justes et bien conjugués","points":16},{"critere":"Explication : le sens n'est pas la somme des deux mots","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I **get up** at 7.\n2. **Put on** your coat! (*Put your coat on!*)\n3. My grandma **looks after** my little sister — 3e personne : -s.\n4. I'm **looking for** my keys.\n5. Don't **give up**!\n6. We have **run out of** milk.\n7. I want to **find out** the truth.\n8. when she **grows up**.\n\n**Explication**\nLe sens d'un verbe à particule ou prépositionnel n'est presque jamais la somme de ses deux mots : *look after* signifie « s'occuper de ». Ces verbes s'apprennent comme des **mots de vocabulaire entiers**."}$exo$::jsonb),
  ('b92b0ef4-e23b-59e9-9d00-ba6dfb90d75e'::uuid, 2, 'traduction', $exo${"titre":"La place du pronom","consigne":"Remplace le nom souligné par un pronom et réécris la phrase, puis réponds à la question 2.","enonce":"**1. Remplace le complément en gras par un pronom (it, them, her…).**\n\n1. Turn on **the light**.\n2. Take off **your shoes**.\n3. Look after **your sister**.\n4. Put on **your jacket**.\n5. Listen to **the teacher**. (*him*)\n6. Look up **these words** in the dictionary.\n\n**2.** Pour les phrases 1 et 3, dis s'il s'agit d'un verbe **à particule** ou d'un verbe **prépositionnel**, et explique le test qui permet de le savoir.","bareme":[{"critere":"Pronom placé avant la particule pour les verbes à particule","points":8},{"critere":"Pronom placé après la préposition pour les verbes prépositionnels","points":5},{"critere":"Nature des verbes 1 et 3 identifiée","points":3},{"critere":"Test de séparation expliqué","points":4}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Turn **it** on.* — jamais *turn on it*.\n2. *Take **them** off.*\n3. *Look after **her**.* — préposition : le pronom reste après.\n4. *Put **it** on.*\n5. *Listen to **him**.*\n6. *Look **them** up in the dictionary.*\n\nAvec un verbe **à particule**, un pronom se place **obligatoirement avant** la particule. Avec un verbe **prépositionnel**, le complément (nom ou pronom) est **toujours après** la préposition.\n\n**2. Le test**\n- *Turn on* : verbe **à particule** — on peut dire *turn the light on*.\n- *Look after* : verbe **prépositionnel** — on ne peut pas dire *look your sister after*.\nSi le complément peut se glisser entre le verbe et le petit mot, c'est une particule ; sinon, c'est une préposition."}$exo$::jsonb),
  ('b92b0ef4-e23b-59e9-9d00-ba6dfb90d75e'::uuid, 3, 'traduction', $exo${"titre":"Le premier voyage de Jules","consigne":"Lis le texte, traduis-le, puis réponds aux questions 2 et 3.","enonce":"> Jules got up at 5 a.m. He put on his jacket and looked for his passport. At the airport, he waited for his friends. The plane took off at 8. Jules was looking forward to seeing London. When he arrived, his phone had run out of battery, so he couldn't find out where his hotel was. But he didn't give up!\n\n1. Traduis le texte en français.\n2. Relève **deux verbes à particule** et **deux verbes prépositionnels**, et justifie ton classement avec le test du cours.\n3. Réécris deux phrases du texte en remplaçant le complément du verbe à particule par un pronom. Explique la règle de position.","bareme":[{"critere":"Traduction juste du sens de chaque verbe composé","points":7},{"critere":"Deux verbes à particule et deux prépositionnels bien classés","points":4},{"critere":"Classement justifié par le test de séparation","points":3},{"critere":"Deux réécritures avec pronom avant la particule, règle expliquée","points":4},{"critere":"Qualité du français","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> Jules s'est levé à 5 h. Il a mis sa veste et a cherché son passeport. À l'aéroport, il a attendu ses amis. L'avion a décollé à 8 h. Jules avait hâte de voir Londres. Quand il est arrivé, son téléphone n'avait plus de batterie, alors il n'a pas pu découvrir où était son hôtel. Mais il n'a pas abandonné !\n\nPoints de sens : *got up* = s'est levé ; *put on* = a mis (vêtement) ; *looked for* = a cherché ; *waited for* = a attendu ; *took off* = a décollé ; *looking forward to* = avait hâte de (suivi de -ING) ; *run out of* = être à court de ; *find out* = découvrir ; *give up* = abandonner.\n\n**2. Classement**\n- À particule : *put on*, *find out* (aussi *get up*, *take off*, *give up*) — on peut dire *put his jacket on*.\n- Prépositionnels : *look for*, *wait for* — impossible de dire *waited his friends for*.\n\n**3. Réécritures**\n- *He put it on.* — jamais *put on it*.\n- *He couldn't find it out.* (phrase possible, même si l'on garde plutôt le nom ici).\nRègle : avec un verbe à particule, un **pronom** se place **obligatoirement avant** la particule ; un nom peut se placer avant ou après."}$exo$::jsonb),
  ('6c689053-0072-51f7-b2ec-1dca4fa0755d'::uuid, 1, 'traduction', $exo${"titre":"To + verbe ou -ING ?","consigne":"Mets le verbe entre parenthèses à la bonne forme (to + verbe, -ING ou base verbale).","enonce":"**Mets le verbe à la bonne forme.**\n\n1. I enjoy (read) comics.\n2. She decided (leave) early.\n3. You must (go) now.\n4. He left without (say) goodbye.\n5. I hope (see) you soon.\n6. We finished (work) at six.\n7. I avoid (eat) sugar.\n8. I'm looking forward to (meet) you.\n\n**Question :** pourquoi *look forward to* est-il suivi de -ING malgré son « to » ?","bareme":[{"critere":"Huit verbes à la bonne forme","points":16},{"critere":"Explication : to est ici une préposition","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I enjoy **reading** — *enjoy* + -ING.\n2. She decided **to leave** — *decide* + to.\n3. You must **go** — après un modal : base verbale.\n4. without **saying** — après une préposition : -ING.\n5. I hope **to see** — *hope* + to.\n6. We finished **working** — *finish* + -ING.\n7. I avoid **eating** — *avoid* + -ING.\n8. looking forward to **meeting** — -ING.\n\n**Explication**\nDans *look forward to*, *to* n'est pas la marque de l'infinitif mais une **préposition** (comme dans *I look forward to the holidays*). Or, après une préposition, le verbe se met toujours en **-ING**."}$exo$::jsonb),
  ('6c689053-0072-51f7-b2ec-1dca4fa0755d'::uuid, 2, 'traduction', $exo${"titre":"Stop, remember, try","consigne":"Traduis chaque paire de phrases en français, puis complète les phrases de la question 2.","enonce":"**1. Traduis en français et explique la différence de sens.**\n\na. *He stopped to smoke.* / *He stopped smoking.*\nb. *Remember to lock the door.* / *I remember locking the door.*\nc. *Try to open the window.* / *Try opening the window.*\n\n**2. Complète avec la bonne forme.**\n\n1. Grandpa is healthier since he stopped (drink) coffee.\n2. Did you remember (buy) bread?\n3. I went to the library (study).\n4. It's too hot. Try (open) the window, it might help.","bareme":[{"critere":"Trois paires traduites avec la bonne nuance","points":9},{"critere":"Quatre blancs justes","points":8},{"critere":"Infinitif de but avec to (et non for)","points":3}],"dureeMin":10,"corrige":"**1. Traductions**\na. « Il s'est arrêté **pour** fumer. » / « Il a **arrêté de** fumer. »\nb. « **Pense à** fermer la porte à clé. » (action à faire) / « Je **me souviens d'avoir** fermé la porte à clé. » (action déjà faite)\nc. « **Essaie d'**ouvrir la fenêtre. » (effort, peut-être difficile) / « Essaie **en** ouvrant la fenêtre, pour voir. » (tester une solution)\n\n**2. Réponses**\n1. since he stopped **drinking** coffee — il a arrêté d'en boire.\n2. Did you remember **to buy** bread? — penser à faire.\n3. I went to the library **to study** — infinitif de but ; jamais *for studying*.\n4. Try **opening** the window — essayer pour voir si ça aide."}$exo$::jsonb),
  ('6c689053-0072-51f7-b2ec-1dca4fa0755d'::uuid, 3, 'traduction', $exo${"titre":"Le projet de Nina","consigne":"Traduis le texte en anglais, puis justifie quatre de tes choix.","enonce":"**1. Thème : traduis en anglais.**\n\n> Nina veut devenir pilote. Elle adore voyager et elle a appris à piloter l'an dernier. Elle est douée pour parler aux gens, mais elle déteste attendre. La semaine dernière, elle est allée à l'aéroport pour rencontrer un vrai pilote. Il lui a promis de l'aider. Elle a hâte de voler seule !\n\n*Aide : to fly = piloter / voler ; to become = devenir ; alone = seule ; she is good at = elle est douée pour.*\n\n**2.** Justifie la forme du verbe après : *want*, *good at*, *to meet* (pour rencontrer), *look forward to*.","bareme":[{"critere":"Verbes + to justes (want, learn, promise)","points":5},{"critere":"Verbes + -ING justes (love, hate, look forward to)","points":5},{"critere":"-ING après préposition et infinitif de but","points":3},{"critere":"Quatre justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Nina wants to become a pilot. She loves travelling and she learnt to fly last year. She is good at talking to people, but she hates waiting. Last week, she went to the airport to meet a real pilot. He promised to help her. She is looking forward to flying alone!*\n(*learned* et *traveling* acceptés ; *loves to travel* accepté car *love* admet les deux, mais -ING est la forme du cours.)\n\n**2. Justifications**\n- *want* + **to** + verbe : *want* fait partie des verbes suivis de l'infinitif (comme decide, hope, promise, learn).\n- *good at* + **-ING** : *at* est une **préposition** ; après une préposition, toujours -ING.\n- *to meet* : **infinitif de but** (« pour rencontrer ») → *to* ou *in order to* ; jamais *for meeting*.\n- *look forward to* + **-ING** : *to* y est une préposition, pas la marque de l'infinitif."}$exo$::jsonb),
  ('d3c8789b-1699-5096-8f18-b5f850c1c5cf'::uuid, 1, 'traduction', $exo${"titre":"Former les adverbes","consigne":"Donne l'adverbe correspondant à chaque adjectif, puis corrige la phrase fautive.","enonce":"**1. Donne l'adverbe.**\n\nslow · careful · happy · simple · good · fast · hard · late\n\n**2. Corrige :** *She speaks very good English and she sings good.*\n\n**3.** Que signifient *hardly* et *lately* ?","bareme":[{"critere":"Huit adverbes justes, irréguliers compris","points":12},{"critere":"Phrase corrigée (sings well)","points":4},{"critere":"Sens de hardly et lately","points":4}],"dureeMin":6,"corrige":"**1. Adverbes**\n- slow → **slowly**\n- careful → **carefully**\n- happy → **happily** (-y → -ily)\n- simple → **simply** (-le → -ly)\n- good → **well** (irrégulier)\n- fast → **fast** (identique)\n- hard → **hard** (identique)\n- late → **late** (identique)\n\n**2. Correction**\n*She speaks very good English and she sings **well**.* — *good English* est juste (adjectif devant un nom) ; mais pour modifier le verbe *sings*, il faut l'adverbe **well**.\n\n**3. Pièges**\n- *hardly* = **à peine** (pas « durement ») ;\n- *lately* = **récemment** (pas « tardivement »)."}$exo$::jsonb),
  ('d3c8789b-1699-5096-8f18-b5f850c1c5cf'::uuid, 2, 'traduction', $exo${"titre":"Les habitudes de Farah","consigne":"Place l'adverbe entre parenthèses au bon endroit, puis réponds à la question 2.","enonce":"**1. Réécris chaque phrase avec l'adverbe à sa place.**\n\n1. Farah gets up early. (always)\n2. She is late. (never)\n3. She has been to Spain. (never)\n4. She plays tennis on Saturdays. (usually)\n5. She doesn't run fast. (enough → après l'adjectif / adverbe)\n6. She is tired after school. (very)\n\n**2.** Remets les compléments dans l'ordre habituel : *She sang (last night / at the concert / beautifully).* Donne la règle.","bareme":[{"critere":"Adverbes de fréquence placés avant le verbe lexical, après be ou l'auxiliaire","points":10},{"critere":"Enough après, very devant l'adjectif","points":4},{"critere":"Ordre manière, lieu, temps rétabli et règle donnée","points":6}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Farah always gets up early.* — avant le verbe lexical.\n2. *She is never late.* — après *be*.\n3. *She has never been to Spain.* — après l'auxiliaire.\n4. *She usually plays tennis on Saturdays.* — avant le verbe lexical.\n5. *She doesn't run fast enough.* — *enough* après l'adverbe / l'adjectif.\n6. *She is very tired after school.* — adverbe de degré devant l'adjectif.\n\n**2. Ordre**\n*She sang beautifully at the concert last night.* — ordre habituel en fin de phrase : **manière → lieu → temps**."}$exo$::jsonb),
  ('d3c8789b-1699-5096-8f18-b5f850c1c5cf'::uuid, 3, 'traduction', $exo${"titre":"La critique de concert","consigne":"Lis le texte, corrige les fautes en justifiant, puis traduis les deux phrases de la question 3.","enonce":"> Last night, the band played very good. The singer sang loud the songs and the guitarist always was smiling. I could hard hear the drums, because I was at the back. The concert finished lately, at midnight. I have been to concerts often, but this one was really amazing!\n\n1. Le texte contient **six fautes** sur les adverbes. Relève-les et corrige-les.\n2. Justifie chaque correction par la règle du cours.\n3. Traduis : a) *I have hardly slept lately.* b) *She works hard and she is never late.*","bareme":[{"critere":"Six fautes relevées et corrigées","points":7},{"critere":"Justifications (irréguliers, place, sens de hardly / lately)","points":6},{"critere":"Traductions justes de hardly, lately, hard, late","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":16,"corrige":"**1 et 2. Les six fautes**\n- *played very good* → **played very well** : l'adverbe de *good* est *well*.\n- *sang loud the songs* → **sang the songs loudly** (ou *loud*) : on n'intercale jamais un adverbe entre le verbe et son complément d'objet.\n- *always was smiling* → **was always smiling** : l'adverbe de fréquence se place **après** *be* / l'auxiliaire.\n- *could hard hear* → **could hardly hear** : « à peine » = *hardly* ; *hard* = dur.\n- *finished lately* → **finished late** : *late* reste identique ; *lately* signifie « récemment ».\n- *I have been to concerts often* → **I have often been to concerts** : fréquence entre l'auxiliaire et le participe passé.\n\n**3. Traductions**\na) « J'ai **à peine** dormi **ces derniers temps**. » (récemment)\nb) « Elle travaille **dur** et elle n'est **jamais en retard**. » — *hard* et *late* adverbes identiques à l'adjectif."}$exo$::jsonb),
  ('7029a8c0-4f96-5423-9add-79388d47bb73'::uuid, 1, 'traduction', $exo${"titre":"Habituel ou en cours ?","consigne":"Mets le verbe au présent simple ou au présent en BE + -ING.","enonce":"**Mets le verbe à la bonne forme.**\n\n1. Look! It (rain).\n2. My brother (study) English every day.\n3. Water (boil) at 100 °C.\n4. Be quiet, I (do) my homework.\n5. She (not / like) fish.\n6. I (know) the answer.\n7. We (meet) Tom tonight at 8. (c'est organisé)\n8. He (watch) TV every evening.\n\n**Question :** pourquoi ne peut-on pas dire *I am knowing* ?","bareme":[{"critere":"Huit formes justes (temps, 3e personne, orthographe)","points":16},{"critere":"Explication des verbes d'état","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. It **is raining** — action en cours (*Look!*).\n2. My brother **studies** — habitude ; consonne + y → -ies.\n3. Water **boils** — vérité générale.\n4. I **am doing** — en cours.\n5. She **doesn't like** — présent simple, négation avec *doesn't*.\n6. I **know** — verbe d'état.\n7. We **are meeting** — projet organisé.\n8. He **watches** — habitude ; -ch → -es.\n\n**Explication**\n*Know* est un **verbe d'état** (comme like, love, want, need, understand, believe) : il n'accepte pas la forme en -ING. On dit *I know*, jamais *I am knowing*."}$exo$::jsonb),
  ('7029a8c0-4f96-5423-9add-79388d47bb73'::uuid, 2, 'traduction', $exo${"titre":"La carte postale d'Ilan","consigne":"Conjugue les verbes entre parenthèses, puis justifie trois choix.","enonce":"> Dear Grandma,\n> I (1. write) to you from Edinburgh! I (2. stay) with my aunt this week. Every morning, she (3. go) to work by bike and I (4. visit) the city. Right now, it (5. rain) and my cousin (6. play) the piano. He (7. play) every day! Tonight we (8. have) dinner at a restaurant: my aunt booked a table. I (9. love) this city!\n> Ilan\n\n1. Conjugue les neuf verbes.\n2. Justifie les formes 2, 3 et 9.","bareme":[{"critere":"Formes en BE + -ING justes (en cours, temporaire, projet)","points":7},{"critere":"Présents simples justes, orthographe de la 3e personne","points":6},{"critere":"Verbe d'état love au présent simple","points":2},{"critere":"Trois justifications exactes","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **am writing** — en cours.\n(2) **am staying** — situation temporaire.\n(3) **goes** — habitude ; -o → -es.\n(4) **visit** — habitude.\n(5) **is raining** — en cours (*right now*).\n(6) **is playing** — en cours.\n(7) **plays** — habitude (*every day*).\n(8) **are having** — projet organisé.\n(9) **love** — verbe d'état.\n\n**2. Justifications**\n- (2) *this week* : une situation **temporaire** → BE + -ING.\n- (3) *every morning* : une **habitude** → présent simple, -es à la 3e personne.\n- (9) *love* est un **verbe d'état** : jamais à la forme en -ING."}$exo$::jsonb),
  ('7029a8c0-4f96-5423-9add-79388d47bb73'::uuid, 3, 'traduction', $exo${"titre":"Le colocataire agaçant","consigne":"Traduis le texte en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> Mon frère aîné vit à Manchester. Il travaille dans une banque, mais ce mois-ci il travaille à Londres. D'habitude, il se lève à 7 h. En ce moment, il cherche un appartement. Son colocataire perd toujours ses clés, c'est énervant ! Samedi, nous prenons le train pour aller le voir : les billets sont achetés. Le train part à 9 h 15.\n\n*Aide : flatmate = colocataire ; flat = appartement ; to look for = chercher.*\n\n**2.** Pour cinq verbes de ta traduction, nomme le temps choisi et l'emploi du cours qui le justifie (habitude, état permanent, temporaire, en cours, projet organisé, programme fixe, agacement).","bareme":[{"critere":"Présent simple pour l'état permanent, l'habitude et l'horaire","points":5},{"critere":"BE + -ING pour le temporaire, l'action en cours et le projet organisé","points":5},{"critere":"Always + BE + -ING pour l'agacement","points":3},{"critere":"Cinq justifications exactes","points":5},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> *My older brother lives in Manchester. He works in a bank, but this month he is working in London. He usually gets up at 7. At the moment, he is looking for a flat. His flatmate is always losing his keys, it's annoying! On Saturday, we are taking the train to see him: the tickets are bought. The train leaves at 9.15.*\n\n**2. Justifications attendues**\n- *lives*, *works in a bank* : **état permanent** → présent simple.\n- *is working in London* (*this month*) : situation **temporaire** → BE + -ING.\n- *usually gets up* : **habitude** → présent simple.\n- *is looking for* (*at the moment*) : action **en cours** → BE + -ING.\n- *is always losing* : *always* + BE + -ING → **agacement**.\n- *are taking the train* : **projet organisé** (billets achetés) → BE + -ING.\n- *leaves at 9.15* : **programme fixe**, horaire → présent simple.\nCinq justifications suffisent."}$exo$::jsonb),
  ('dfea713c-8373-5243-8d94-88b71193a786'::uuid, 1, 'traduction', $exo${"titre":"Witch hunts : from Salem to Hollywood","consigne":"Traduis le texte en français (version), puis réponds à la question 2 en anglais.","enonce":"**Text (written for the test, based on the course).**\n\n> In 1692, in the small town of Salem, Massachusetts, nineteen people were hanged for witchcraft. There was no real evidence: fear and rumours were enough. In 1953, Arthur Miller set his play *The Crucible* in Salem, but his audience understood that he was talking about the hunt for communists.\n\n*Help: witchcraft = la sorcellerie ; evidence = les preuves.*\n\n1. Translate the text into French.\n2. In two or three sentences, explain what *a witch hunt* means today, in its figurative sense. Give one example from the course.","bareme":[{"critere":"Traduction fidèle : passif were hanged, evidence ≠ évidence, set his play in = situe sa pièce à","points":10},{"critere":"Sens figuré de witch hunt expliqué en anglais avec un exemple exact (McCarthy, Hollywood Ten)","points":6},{"critere":"Correction du français et de l'anglais","points":4}],"dureeMin":8,"corrige":"**1. Traduction proposée**\n« En 1692, dans la petite ville de Salem, dans le Massachusetts, dix-neuf personnes furent pendues (ont été pendues) pour sorcellerie. Il n'y avait aucune véritable preuve : la peur et les rumeurs suffisaient. En 1953, Arthur Miller situa sa pièce *Les Sorcières de Salem* (*The Crucible*) à Salem, mais son public comprit qu'il parlait de la chasse aux communistes. »\n\nPoints de vigilance : *were hanged* → passif « furent pendues » ; *evidence* → « preuves » (faux ami : pas « évidence ») ; *set his play in* → « situa sa pièce à » ; *audience* → « public ».\n\n**2. Expected answer (example)**\n*Today, a witch hunt is any collective persecution based on fear and accusations without proof: there are no witches any more. For example, in the 1950s, Senator Joseph McCarthy's « Red Scare » led to blacklists, and in 1947 the Hollywood Ten were condemned for refusing to say whether they were communists.*"}$exo$::jsonb),
  ('dfea713c-8373-5243-8d94-88b71193a786'::uuid, 2, 'traduction', $exo${"titre":"Is it none of the State's business ?","consigne":"Réponds en anglais aux trois questions, en phrases complètes.","enonce":"**Document: key dates (based on the course).**\n\n| Date | Event |\n| 1918 / 1928 | British women get the vote, then on equal terms with men |\n| 1973 | *Roe v. Wade* protects abortion in the USA |\n| 1985 | Margaret Atwood publishes *The Handmaid's Tale* |\n| 24 June 2022 | The *Dobbs* decision overturns *Roe v. Wade* |\n\n1. Explain in two or three sentences what the *Dobbs* decision changed.\n2. How can *The Handmaid's Tale* be linked to this debate? (2-3 sentences)\n3. Give your opinion in about 60-80 words. Start with: *Where should we draw the line between the State and our private lives?*","bareme":[{"critere":"Dobbs expliqué exactement : Roe renversé, décision rendue à chaque État","points":5},{"critere":"Lien pertinent avec The Handmaid's Tale : dystopie où l'État contrôle le corps des femmes","points":5},{"critere":"Avis argumenté, lié à la frontière privé / public","points":6},{"critere":"Correction de la langue anglaise","points":4}],"dureeMin":12,"corrige":"**1.** *In 1973, Roe v. Wade protected abortion across the United States. On 24 June 2022, the Supreme Court's Dobbs decision overturned it: there is no longer a national protection, and each State now decides for itself.*\n\n**2.** *The Handmaid's Tale (1985) is a dystopia in which the State controls women's bodies. After Dobbs, many readers saw the novel as a warning: a decision about one's own body, which seems private, can become a public, political matter.*\n\n**3. Model answer**\n*Where should we draw the line between the State and our private lives? In my opinion, some decisions belong to the private sphere: the State should protect citizens, not decide for them. The history of women's rights shows it: in 1928, British women finally voted on equal terms with men, and they gained more control over their lives. However, the law must also protect everyone, so the line is never easy to draw.*\n\nAccepter toute opinion argumentée et nuancée, à condition qu'elle s'appuie sur au moins un repère du cours."}$exo$::jsonb),
  ('dfea713c-8373-5243-8d94-88b71193a786'::uuid, 3, 'traduction', $exo${"titre":"Can the private sphere resist ?","consigne":"Rédige en anglais un essai d'environ 180 mots, en t'appuyant sur au moins trois références précises du cours.","enonce":"**Essay question.**\n\n> *Can the private sphere resist the intrusion of the public sphere?*\n\nUse at least **three** precise references (event, date, work, author) taken from **at least two** of these fields:\n- witch hunts (Salem, McCarthy, *The Crucible*) ;\n- women's bodies and the law (suffragettes, *Roe*, *Dobbs*, *The Handmaid's Tale*) ;\n- religion and institutions (Church of England, First Amendment, *In God We Trust*).\n\nYour essay should have an introduction, two arguments and a conclusion.","bareme":[{"critere":"Trois références exactes issues d'au moins deux domaines du cours","points":6},{"critere":"Argumentation : intrusions et résistances analysées, pas seulement racontées","points":6},{"critere":"Structure : introduction, deux arguments, conclusion, connecteurs","points":3},{"critere":"Langue : vocabulaire du chapitre (privacy, to intrude, scrutiny…), correction grammaticale","points":5}],"dureeMin":20,"corrige":"**Model essay (≈ 180 words)**\n\n*« An Englishman's home is his castle », says the proverb. Yet history shows that the State and society often intrude into private lives.*\n\n*First, fear can turn private beliefs into public crimes. In 1692, nineteen people were hanged in Salem after accusations without proof. In the 1950s, Senator McCarthy's Red Scare put people on blacklists for their political opinions, and in 1953 Arthur Miller used Salem in The Crucible to denounce this witch hunt.*\n\n*Second, women's bodies have long been a political battlefield. Roe v. Wade (1973) protected abortion as a private decision, but the Dobbs decision of 2022 gave the question back to each State. Margaret Atwood's The Handmaid's Tale (1985) imagines where total control could lead.*\n\n*However, the private sphere can resist: Miller's play and Atwood's novel are forms of resistance, and the First Amendment (1791) forbids a State religion, protecting individual faith.*\n\n*In conclusion, the private sphere is never safe once and for all: it resists when citizens, artists and laws defend it.*\n\n**Attendus** : trois références exactes (dates justes) ; une vraie problématique (intrusion / résistance) ; vocabulaire du chapitre ; aucune référence hors cours n'est exigée."}$exo$::jsonb),
  ('e57e3332-6f5c-5ed4-a8eb-c7ae36e9c1a4'::uuid, 1, 'traduction', $exo${"titre":"Juneteenth in a few lines","consigne":"Traduis le texte en français (version), puis réponds à la question 2 en anglais.","enonce":"**Text (written for the test, based on the course).**\n\n> On 19 June 1865, in Galveston, Texas, the last enslaved people learned that they were free. This day, known as Juneteenth, became a federal holiday in 2021. For many African Americans, it is a day to remember and to celebrate.\n\n*Help: a federal holiday = un jour férié fédéral.*\n\n1. Translate the text into French.\n2. Why do people increasingly say *enslaved people* rather than *slaves*? Answer in one or two sentences.","bareme":[{"critere":"Traduction fidèle (learned that they were free, known as, became a federal holiday)","points":10},{"critere":"Explication juste de enslaved people : des personnes réduites en esclavage, pas esclaves par nature","points":6},{"critere":"Correction du français et de l'anglais","points":4}],"dureeMin":7,"corrige":"**1. Traduction proposée**\n« Le 19 juin 1865, à Galveston, au Texas, les dernières personnes réduites en esclavage apprirent qu'elles étaient libres. Ce jour, connu sous le nom de *Juneteenth*, est devenu un jour férié fédéral en 2021. Pour de nombreux Afro-Américains, c'est un jour pour se souvenir et pour célébrer. »\n\nPoints de vigilance : *enslaved people* → « personnes réduites en esclavage » (pas simplement « esclaves ») ; *learned* → « apprirent » ; *known as* → « connu sous le nom de ».\n\n**2. Expected answer**\n*The expression « enslaved people » reminds us that these men and women were reduced to slavery by others: they were people first, and they were not slaves by nature.*"}$exo$::jsonb),
  ('e57e3332-6f5c-5ed4-a8eb-c7ae36e9c1a4'::uuid, 2, 'traduction', $exo${"titre":"Commemorating in the Commonwealth","consigne":"Réponds en anglais aux trois questions.","enonce":"**Document (based on the course).**\n\n| Date or place | Commemoration |\n| 11 November | Remembrance Day |\n| 25 April | ANZAC Day |\n| 30 September (since 2021) | National Day for Truth and Reconciliation (Canada) |\n| Robben Island | World Heritage site since 1999 |\n\n1. For each line, explain in one sentence **what or whom** is remembered.\n2. Why do people wear a **poppy** on Remembrance Day?\n3. In about 80 words, explain why societies need memorials and commemorations. Use at least three words from this list: *to commemorate, collective memory, a memorial, to reclaim*.","bareme":[{"critere":"Quatre commémorations expliquées exactement","points":6},{"critere":"Coquelicot expliqué : fleur des champs de bataille de Flandre","points":3},{"critere":"Paragraphe argumenté sur le rôle des commémorations, trois mots imposés bien employés","points":7},{"critere":"Correction de la langue anglaise","points":4}],"dureeMin":12,"corrige":"**1.**\n- *Remembrance Day (11 November) remembers the soldiers who died in the wars.*\n- *On ANZAC Day (25 April), Australians and New Zealanders remember the battle of Gallipoli (1915).*\n- *Canada's National Day for Truth and Reconciliation remembers the children of the Indigenous residential schools.*\n- *Robben Island, where Nelson Mandela was imprisoned, is a World Heritage site: it reminds visitors of his struggle.*\n\n**2.** *The poppy is the flower that grew on the battlefields of Flanders: it has become the symbol of the soldiers who died there.*\n\n**3. Model answer (≈ 80 words)**\n*Societies need memorials because collective memory is not natural: it is built step by step. When a nation decides to commemorate a date, it tells its citizens what matters. Memorials also allow peoples who were silenced to reclaim their past, like the Maori or the descendants of enslaved people. Finally, remembering is a way of learning: a museum shows the crimes of the past so that they are never repeated.*"}$exo$::jsonb),
  ('e57e3332-6f5c-5ed4-a8eb-c7ae36e9c1a4'::uuid, 3, 'traduction', $exo${"titre":"Proud and responsible ?","consigne":"Rédige en anglais un essai d'environ 180 mots, en t'appuyant sur au moins quatre repères précis du cours.","enonce":"**Essay question.**\n\n> *Can a nation be proud of its history and acknowledge its crimes?*\n\nUse at least **four** precise references from the course, taken from at least two of these fields:\n- slavery in the English-speaking world (dates, abolition, museums, Juneteenth) ;\n- works of art (*Beloved*, *12 Years a Slave*) ;\n- Indigenous territories (Waitangi, Wounded Knee, Standing Rock).\n\nYour essay should have an introduction, two arguments and a conclusion.","bareme":[{"critere":"Quatre repères exacts (dates, lieux, œuvres) d'au moins deux domaines","points":6},{"critere":"Argumentation nuancée : fierté et reconnaissance des crimes articulées","points":6},{"critere":"Structure : introduction, deux arguments, conclusion","points":3},{"critere":"Langue : vocabulaire du chapitre (to commemorate, reparations, enslaved people…), correction","points":5}],"dureeMin":20,"corrige":"**Model essay (≈ 180 words)**\n\n*Every nation chooses what it remembers. But can it be proud of its past and still look at its crimes?*\n\n*On the one hand, acknowledging crimes has become part of national memory. The first enslaved Africans arrived in Virginia in 1619; the United Kingdom abolished slavery in its Empire in 1833 and the 13th Amendment abolished it in the USA in 1865. Today, the International Slavery Museum in Liverpool (2007) and the national museum of African American history in Washington (2016) show this history. Juneteenth became a federal holiday in 2021: recognition came late, but it came.*\n\n*On the other hand, some memories are still painful. The massacre of Lakota people at Wounded Knee (1890) and the Sioux protest at Standing Rock (2016) show that Indigenous territories remain a wound. Art helps: Toni Morrison's Beloved (1987) gives a voice to those who were silenced.*\n\n*In conclusion, pride and responsibility are not opposed. Remembering is not the same as repenting: a nation can be proud precisely because it is able to face its past.*\n\n**Attendus** : quatre repères exacts ; une réponse nuancée ; *enslaved people*, *to commemorate*, *collective memory* bien employés."}$exo$::jsonb),
  ('f9944db1-1b45-5744-b36c-ee0c16e82b38'::uuid, 1, 'traduction', $exo${"titre":"Four dystopias, one warning","consigne":"Complète le tableau en anglais, puis réponds à la question 2.","enonce":"**1.** Complete the table (author, date, what the work denounces).\n\n| Work | Author | Date | What it denounces |\n| *Nineteen Eighty-Four* | ? | ? | ? |\n| *Fahrenheit 451* | ? | ? | ? |\n| *The Hunger Games* | ? | ? | ? |\n| *Black Mirror* (TV series) | ? | ? | ? |\n\n**2.** Explain in two sentences what *a cautionary tale* is, and why a dystopia is one.","bareme":[{"critere":"Auteurs et dates exacts des quatre œuvres","points":8},{"critere":"Ce que dénonce chaque œuvre, juste","points":6},{"critere":"Cautionary tale défini et appliqué à la dystopie","points":6}],"dureeMin":8,"corrige":"**1.**\n| Work | Author | Date | What it denounces |\n| *Nineteen Eighty-Four* | George Orwell | 1949 | total surveillance: *Big Brother is watching you* |\n| *Fahrenheit 451* | Ray Bradbury | 1953 | a society that burns its books |\n| *The Hunger Games* | Suzanne Collins | 2008 | deadly games turned into a TV show |\n| *Black Mirror* | Charlie Brooker | since 2011 | the dangers of our technologies |\n\n**2.** *A cautionary tale is a story that warns readers against a danger. A dystopia exaggerates a real trend to make it visible: it frightens us so that the future it describes never happens.*"}$exo$::jsonb),
  ('f9944db1-1b45-5744-b36c-ee0c16e82b38'::uuid, 2, 'traduction', $exo${"titre":"Mara's score","consigne":"Lis l'extrait, puis réponds en anglais aux trois questions.","enonce":"**Extract (invented for the test).**\n\n> Every morning, the screen on Mara's wall tells her what to eat, what to wear and whom to meet. Each citizen receives a score from one to five. Yesterday, Mara laughed at the wrong joke during a dinner, and her score fell to 2.8. Now she is no longer allowed to enter the city library.\n\n1. Find **three** features that make this extract dystopian. Quote the text.\n2. Compare this extract with **one** work from the course (title, author or creator, date).\n3. In about 60 words, explain how a dystopia exaggerates a real trend of our world.","bareme":[{"critere":"Trois traits dystopiques repérés et appuyés sur des citations","points":6},{"critere":"Comparaison pertinente avec une œuvre exacte du cours","points":5},{"critere":"Explication de l'exagération d'une tendance réelle","points":5},{"critere":"Correction de la langue anglaise","points":4}],"dureeMin":12,"corrige":"**1.** *The State or a machine controls private life: « the screen on Mara's wall tells her what to eat, what to wear and whom to meet ». Citizens are constantly judged: « Each citizen receives a score ». A tiny mistake is punished and limits freedom: « her score fell to 2.8. Now she is no longer allowed to enter the city library ».*\n\n**2.** Example: *The extract is close to Black Mirror (Charlie Brooker, since 2011), which shows the dangers of our technologies, and more precisely to a society where everyone is rated. It also recalls Nineteen Eighty-Four (George Orwell, 1949): the screen is like Big Brother, always watching. Being banned from the library also echoes Fahrenheit 451 (Ray Bradbury, 1953), where books are burnt.*\nUne seule comparaison suffit.\n\n**3. Model answer**\n*A dystopia takes something that already exists and pushes it to the extreme. Today, we rate restaurants and drivers, and apps collect our data. The extract imagines a world where people themselves are rated and punished. By exaggerating, the story makes the danger visible: it is a cautionary tale, not a prophecy.*"}$exo$::jsonb),
  ('f9944db1-1b45-5744-b36c-ee0c16e82b38'::uuid, 3, 'traduction', $exo${"titre":"Is the American Dream still alive ?","consigne":"Rédige en anglais un essai d'environ 180 mots, en t'appuyant sur au moins trois œuvres ou repères du cours.","enonce":"**Essay question.**\n\n> *The American Dream: a promise or an illusion?*\n\nIn your essay:\n1. define the American Dream (who popularised the expression, and when?) ;\n2. analyse how **at least two** works from the course question it ;\n3. conclude with your own point of view.\n\n*Useful words: a self-made man, rags to riches, upward mobility.*","bareme":[{"critere":"Définition exacte : James Truslow Adams, 1931, réussir par son travail","points":4},{"critere":"Deux œuvres au moins analysées avec exactitude (Gatsby, Of Mice and Men, Death of a Salesman)","points":6},{"critere":"Point de vue personnel argumenté et nuancé","points":4},{"critere":"Langue : vocabulaire du chapitre, structure, correction","points":6}],"dureeMin":20,"corrige":"**Model essay (≈ 180 words)**\n\n*The expression « American Dream » was popularised by James Truslow Adams in 1931: it is the idea that anyone can succeed through hard work, from rags to riches. But American literature has often shown the limits of this promise.*\n\n*In The Great Gatsby (1925), F. Scott Fitzgerald tells the story of a self-made man who becomes rich and throws lavish parties, yet he still loses Daisy. Money can buy a mansion, but not a place in the old elite: the novel shows that fortune does not erase one's origins.*\n\n*In Of Mice and Men (1937), John Steinbeck's two farm workers dream of a piece of land of their own, a dream that never comes true. And in Death of a Salesman (1949), Arthur Miller shows a salesman broken by the ideal of success.*\n\n*In my opinion, the American Dream is not dead, but it is a promise that excludes as much as it includes. Upward mobility exists, yet it is not equally open to everyone. The dream remains powerful precisely because it is never fully reached.*\n\n**Attendus** : Adams (1931) ; deux œuvres exactes ; un avis nuancé ; vocabulaire du chapitre."}$exo$::jsonb),
  ('fd5430f8-aaab-500d-b03a-9cb8769d5535'::uuid, 1, 'traduction', $exo${"titre":"Words that made history","consigne":"Réponds aux deux questions, en français pour la 1, en anglais pour la 2.","enonce":"**1.** Translate each quotation into French and give the speaker and the date.\n\n- a) *I have nothing to offer but blood, toil, tears and sweat.*\n- b) *We shall fight on the beaches.*\n- c) *I have a dream.*\n- d) *Yes we can.*\n\n**2.** Explain in English, in one or two sentences each:\n- a) what *a lingua franca* is ;\n- b) what *Globish* is.","bareme":[{"critere":"Quatre traductions justes (toil = labeur, peine)","points":8},{"critere":"Orateurs et dates exacts","points":6},{"critere":"Lingua franca et Globish définis correctement en anglais","points":6}],"dureeMin":8,"corrige":"**1.**\n- a) « Je n'ai rien d'autre à offrir que du sang, de la peine, des larmes et de la sueur. » — **Winston Churchill**, devant les Communes, 13 mai 1940.\n- b) « Nous nous battrons sur les plages. » — **Churchill**, 4 juin 1940, après Dunkerque.\n- c) « Je fais un rêve. » — **Martin Luther King**, Washington, 28 août 1963.\n- d) « Oui, nous le pouvons. » — **Barack Obama**, campagne présidentielle de 2008.\n\n**2.**\n- a) *A lingua franca is a common language used by speakers who have different mother tongues, like English in science, aviation or on the Internet.*\n- b) *Globish is a simplified English, reduced to the essentials, spoken between non-native speakers.*"}$exo$::jsonb),
  ('fd5430f8-aaab-500d-b03a-9cb8769d5535'::uuid, 2, 'traduction', $exo${"titre":"The power of repetition","consigne":"Analyse les documents en anglais, en trois réponses rédigées.","enonce":"**Documents.**\n\n> **A.** *« We shall fight on the beaches, we shall fight on the landing grounds »* — Winston Churchill, 4 June 1940.\n\n> **B.** *« Yes we can »* — Barack Obama's campaign, 2008.\n\n> **C.** *A post on a social network (invented):* « They lie. They cheat. They steal. Vote them out! »\n\n1. Identify the main rhetorical device used in document A and explain its effect on the audience in 1940.\n2. Compare documents B and C: what do they have in common with A, and what makes C different (form, target)?\n3. In about 60 words, explain whether rhetoric is always manipulation. Use the word *rhetoric*.","bareme":[{"critere":"Répétition identifiée dans A et effet expliqué (transformer la peur en détermination)","points":5},{"critere":"Comparaison B / C pertinente : formules courtes, slogans ; attaque personnelle en C","points":5},{"critere":"Réflexion nuancée sur rhétorique et manipulation","points":6},{"critere":"Correction de la langue anglaise","points":4}],"dureeMin":12,"corrige":"**1.** *Churchill uses repetition (« we shall fight … we shall fight »). Speaking just after Dunkirk, he turns fear into determination: the rhythm gives the nation the feeling that it will never give up. The repetition holds the audience together.*\n\n**2.** *B and C, like A, rely on short, memorable formulas. B is a positive slogan which includes the audience (« we »). C also repeats a structure (« They … They … They »), but it is a short attack on opponents, typical of political speech on social media: short sentences, slogans and personal attacks. It aims at dividing rather than uniting.*\n\n**3. Model answer**\n*Rhetoric is not always manipulation. Churchill's speeches used rhetoric to give courage to a whole nation. But the same techniques can be used to divide or to hide the truth: George Orwell warned in 1946 that vague language can hide reality. Words can unite or divide: what matters is whether they serve the truth.*"}$exo$::jsonb),
  ('fd5430f8-aaab-500d-b03a-9cb8769d5535'::uuid, 3, 'traduction', $exo${"titre":"Language is never neutral","consigne":"Rédige en anglais un essai d'environ 180 mots, en t'appuyant sur au moins trois repères précis du cours.","enonce":"**Essay question.**\n\n> *« Language is never neutral. » Discuss.*\n\nUse at least **three** of these references from the course:\n- *post-truth* (Oxford Dictionary, 2016) ;\n- *alternative facts* (January 2017) ;\n- George Orwell, *Politics and the English Language* (1946) ;\n- the rewriting of Roald Dahl's books (2023) ;\n- English as a *lingua franca* and the *Englishes*.\n\nYour essay should have an introduction, two arguments and a conclusion.","bareme":[{"critere":"Trois repères exacts et bien exploités","points":6},{"critere":"Argumentation : langage qui manipule, qui exclut ou qui inclut","points":6},{"critere":"Structure : introduction, deux arguments, conclusion","points":3},{"critere":"Langue : vocabulaire du chapitre (misinformation, censorship, to debunk…), correction","points":5}],"dureeMin":20,"corrige":"**Model essay (≈ 180 words)**\n\n*About one and a half billion people speak English: no language has ever been so widely shared, or so powerful. But words are never just tools.*\n\n*First, language can be used to hide the truth. As early as 1946, George Orwell explained in Politics and the English Language that vague words serve to conceal reality. In 2016, the Oxford Dictionary chose post-truth as its word of the year, and in January 2017 a White House adviser spoke of alternative facts: words were used to blur the line between facts and opinions.*\n\n*Second, choosing words is also a moral and political choice. In 2023, Roald Dahl's publisher rewrote passages considered hurtful, removing words like « fat ». For some, it was inclusion; for others, censorship or a betrayal of the author. Faced with the controversy, the original versions remained on sale.*\n\n*In conclusion, language is never neutral: it can unite, exclude or manipulate. That is why readers must learn to debunk misinformation and to ask who chooses the words, and why.*\n\n**Attendus** : trois repères exacts ; un vrai débat ; vocabulaire du chapitre."}$exo$::jsonb),
  ('732d319c-0145-5221-a349-bfbdaa81bfad'::uuid, 1, 'traduction', $exo${"titre":"A quiz that became a weapon","consigne":"Traduis le texte en français (version), puis réponds à la question 2 en anglais.","enonce":"**Text (written for the test, based on the course).**\n\n> In 2018, the Cambridge Analytica scandal revealed that the personal data of tens of millions of Facebook users had been used for political purposes. Users thought they were playing a harmless personality quiz, while their data were used to target voters.\n\n*Help: harmless = inoffensif ; to target = cibler.*\n\n1. Translate the text into French.\n2. Define in English, in one sentence each: *a whistleblower* ; *a filter bubble*. Give the name of a famous whistleblower from the course and what he revealed.","bareme":[{"critere":"Traduction fidèle (had been used = plus-que-parfait passif, while = alors que, data)","points":10},{"critere":"Définitions justes en anglais de whistleblower et filter bubble","points":6},{"critere":"Snowden et la surveillance de masse de la NSA (2013) cités exactement","points":4}],"dureeMin":8,"corrige":"**1. Traduction proposée**\n« En 2018, le scandale Cambridge Analytica a révélé que les données personnelles de dizaines de millions d'utilisateurs de Facebook avaient été utilisées à des fins politiques. Les utilisateurs croyaient jouer à un test de personnalité inoffensif, alors que leurs données servaient à cibler des électeurs. »\n\nPoints de vigilance : *had been used* → « avaient été utilisées » ; *while* → « alors que » (opposition, pas « pendant que ») ; *voters* → « électeurs ».\n\n**2.**\n- *A whistleblower is a person who reveals illegal or dangerous practices to the public.*\n- *A filter bubble is an environment in which an algorithm only shows us what confirms our opinions.*\n- *Edward Snowden revealed in 2013 that the NSA was carrying out mass surveillance of communications.*"}$exo$::jsonb),
  ('732d319c-0145-5221-a349-bfbdaa81bfad'::uuid, 2, 'traduction', $exo${"titre":"No social media under 16 ?","consigne":"Lis le document, puis réponds en anglais aux trois questions.","enonce":"**Document (invented post by a British teenager).**\n\n> « Australia has banned social media for under-16s. Some people here want the same thing. I get it: cyberbullying is real, and the algorithm keeps me scrolling for hours. But social media is also where I learn about the news, where my friends are, and where I can speak up. Banning it won't teach us anything. » — *Sam, 15*\n\n1. Sum up Sam's arguments **for** and **against** a ban.\n2. What does the British **Online Safety Act** (2023) do, and how is it different from the Australian law (2024)?\n3. Give your own opinion in about 70 words. Use at least two of these words: *digital citizenship, to log off, personal data, cyberbullying*.","bareme":[{"critere":"Arguments pour et contre de Sam fidèlement résumés","points":5},{"critere":"Online Safety Act et loi australienne présentés exactement et comparés","points":5},{"critere":"Avis argumenté avec deux mots imposés bien employés","points":6},{"critere":"Correction de la langue anglaise","points":4}],"dureeMin":12,"corrige":"**1.** *Sam understands a ban because cyberbullying is real and because the algorithm keeps him scrolling for hours. But he is against it: social media helps him follow the news, keep in touch with his friends and speak up, and he thinks a ban won't teach young people how to use it.*\n\n**2.** *The Online Safety Act (2023) obliges platforms to protect minors: it regulates the platforms rather than excluding young users. The Australian law of 2024 goes further: it bans social media for people under 16, a world first.*\n\n**3. Model answer (≈ 70 words)**\n*I think a total ban is not the best solution. Cyberbullying and the collection of personal data are real dangers, but young people also use social media to learn and to take part in public debate. Digital citizenship should be taught at school: learning to protect our data, to check information and to log off is more useful than a ban. Platforms, however, must be forced to protect minors.*\nAccepter l'avis inverse s'il est argumenté."}$exo$::jsonb),
  ('732d319c-0145-5221-a349-bfbdaa81bfad'::uuid, 3, 'traduction', $exo${"titre":"Who controls the digital public space ?","consigne":"Rédige en anglais un essai d'environ 180 mots, en t'appuyant sur au moins quatre repères précis du cours.","enonce":"**Essay question.**\n\n> *« The tools that allow everyone to speak are owned by a handful of private companies. » Is digital technology a threat or an opportunity for democracy?*\n\nUse at least **four** references from the course, for example: Snowden (2013), Cambridge Analytica (2018), the Capitol (6 January 2021), #MeToo or #BlackLivesMatter, *Nosedive* (*Black Mirror*, 2016), *America's Army* (2002), ChatGPT (2022).\n\nYour essay should have an introduction, two arguments and a conclusion.","bareme":[{"critere":"Quatre repères exacts et utiles à l'argument","points":6},{"critere":"Argumentation nuancée : pouvoir horizontal / contrôle par quelques entreprises","points":6},{"critere":"Structure : introduction, deux arguments, conclusion","points":3},{"critere":"Langue : vocabulaire du chapitre, correction grammaticale","points":5}],"dureeMin":20,"corrige":"**Model essay (≈ 180 words)**\n\n*Online, anyone can publish, sign a petition or start a movement. But who really controls this new public space?*\n\n*On the one hand, digital tools have given a voice to those who had none. Movements such as #MeToo and #BlackLivesMatter spread across the world thanks to social media: speech has become more horizontal.*\n\n*On the other hand, these tools can threaten democracy. In 2013, Edward Snowden revealed that the NSA was carrying out mass surveillance. In 2018, the Cambridge Analytica scandal showed that the data of tens of millions of Facebook users had been used for electoral purposes. On 6 January 2021, the assault on the Capitol was organised online; afterwards, Donald Trump was suspended from several networks, which shows that a few private platforms can decide who speaks. Black Mirror's episode Nosedive (2016) imagines where constant rating could lead.*\n\n*In conclusion, the question is not « for or against digital technology », but « who keeps control ». Digital citizenship starts with knowing what we share, and with laws that make platforms accountable.*\n\n**Attendus** : quatre repères exacts ; la tension pouvoir horizontal / poignée d'entreprises ; vocabulaire du chapitre."}$exo$::jsonb),
  ('0f3d0948-f21a-543e-b556-0b791a9376f6'::uuid, 1, 'traduction', $exo${"titre":"Four nations, one kingdom","consigne":"Complète le tableau, puis réponds à la question 2 en anglais.","enonce":"**1.** Complete the table.\n\n| Nation | Capital | Patron saint | Own parliament (date) |\n| England | ? | ? | ? |\n| Scotland | ? | ? | ? |\n| Wales | ? | ? | ? |\n| Northern Ireland | ? | ? | ? |\n\n**2.** In two or three sentences, explain what **devolution** is. Does London give up its sovereignty?","bareme":[{"critere":"Capitales et saints patrons exacts","points":8},{"critere":"Parlements et dates exacts (dont l'absence de parlement anglais propre)","points":5},{"critere":"Dévolution définie en anglais : compétences déléguées sans perte de souveraineté","points":7}],"dureeMin":7,"corrige":"**1.**\n| Nation | Capital | Patron saint | Own parliament |\n| England | London | Saint George | none (Westminster) |\n| Scotland | Edinburgh | Saint Andrew | Scottish Parliament (1999) |\n| Wales | Cardiff | Saint David | Senedd (1999) |\n| Northern Ireland | Belfast | Saint Patrick | Northern Ireland Assembly (1998) |\n\n**2.** *Devolution is the transfer of some powers (education, health, sometimes taxes) from London to the nations. London delegates these powers but does not give up its sovereignty: in 2022, the Supreme Court ruled that Scotland could not organise a new independence referendum on its own.*"}$exo$::jsonb),
  ('0f3d0948-f21a-543e-b556-0b791a9376f6'::uuid, 2, 'traduction', $exo${"titre":"The Scottish paradox","consigne":"Lis le document, puis réponds en anglais aux trois questions.","enonce":"**Document: referendum results (based on the course).**\n\n| Year | Question | Result |\n| 2014 | Should Scotland be an independent country? | 55 % of Scots vote to stay in the UK |\n| 2016 | Should the UK leave the EU? | UK: 52 % Leave · Scotland: 62 % Remain · Northern Ireland: 56 % Remain |\n\n1. Describe the results of the two referendums with precise figures.\n2. Explain the **paradox** Scotland faced after 2016. Why did the question of independence come back?\n3. In about 60-80 words, explain the difference between a **nation** and a **state**, using Scotland and the UK as examples.","bareme":[{"critere":"Résultats décrits avec les chiffres exacts","points":5},{"critere":"Paradoxe expliqué : rester dans le Royaume-Uni en partie pour rester dans l'UE, puis sortie imposée","points":6},{"critere":"Distinction nation / État claire et illustrée","points":5},{"critere":"Correction de la langue anglaise","points":4}],"dureeMin":12,"corrige":"**1.** *In 2014, 55 % of Scots voted to stay in the United Kingdom. In 2016, 52 % of British voters chose to leave the EU, but Scotland voted 62 % to remain, and Northern Ireland 56 %.*\n\n**2.** *In 2014, many Scots voted to stay in the UK partly in order to remain in the EU. Two years later, Scotland voted to remain in the EU but was taken out with the rest of the UK, which left on 31 January 2020. The Scots felt that their choice had not been respected, so the question of independence came back: Brexit has strengthened the case for Scottish independence.*\n\n**3. Model answer**\n*A nation is a people with a history, an identity and sometimes its own institutions; a state is the political entity that holds sovereignty. Scotland is a nation: it has its own history, symbols and, since 1999, its own parliament. The United Kingdom is the state. That is why a Scot can feel both Scottish and British.*"}$exo$::jsonb),
  ('0f3d0948-f21a-543e-b556-0b791a9376f6'::uuid, 3, 'traduction', $exo${"titre":"What still holds the Kingdom together ?","consigne":"Rédige en anglais un essai d'environ 180 mots, en t'appuyant sur au moins quatre repères précis du cours.","enonce":"**Essay question.**\n\n> *« United » Kingdom: what still holds the four nations together, and what divides them?*\n\nIn your essay, use at least **four** precise references from the course: key dates in the construction of the Kingdom, devolution, the referendums, and the vectors of union (the Crown, the Union Jack, the BBC, the NHS, sport).\n\nYour essay should have an introduction, two arguments and a conclusion.","bareme":[{"critere":"Quatre repères exacts (dates, institutions, résultats)","points":6},{"critere":"Vecteurs d'union et facteurs de division analysés","points":6},{"critere":"Structure : introduction, deux arguments, conclusion","points":3},{"critere":"Langue : vocabulaire du chapitre (devolution, sovereignty, to secede…), correction","points":5}],"dureeMin":20,"corrige":"**Model essay (≈ 180 words)**\n\n*One state, four nations, three devolved parliaments: the United Kingdom is united by history rather than by nature. It was built step by step, from the Union of the Crowns in 1603 to the Acts of Union of 1707 and the union with Ireland in 1801.*\n\n*Several things still hold it together. The Crown and the Union Jack, which combines the crosses of Saint George, Saint Andrew and Saint Patrick, are shared symbols, even if Wales does not appear on the flag. The BBC, founded in 1922, speaks to the whole Kingdom, and the NHS, created in 1948, is a common source of pride.*\n\n*Yet many things divide the nations. Each one has its own football and rugby team. Devolution gave Scotland and Wales their parliaments in 1999. Above all, Brexit revealed deep differences: the UK voted 52 % to leave in 2016, but Scotland voted 62 % and Northern Ireland 56 % to remain.*\n\n*In conclusion, the Kingdom remains united, but the union is no longer taken for granted: one can feel both Scottish and British, as long as the union respects each nation.*\n\n**Attendus** : quatre repères exacts ; union et division analysées ; vocabulaire du chapitre."}$exo$::jsonb),
  ('2d81b711-0f68-5128-9e6a-44ff64af99fb'::uuid, 1, 'traduction', $exo${"titre":"Glasgow and Edinburgh","consigne":"Traduis le texte en français (version), puis réponds à la question 2 en anglais.","enonce":"**Text (written for the test, based on the course).**\n\n> Glasgow grew rich thanks to the shipyards on the Clyde. Today, the former working-class city has reinvented itself through culture and hosted the COP26 in 2021. Edinburgh, the capital, is famous for its castle, its Festival and the Fringe, which have taken place every summer since 1947.\n\n*Help: a shipyard = un chantier naval ; to host = accueillir.*\n\n1. Translate the text into French.\n2. Give **three** other symbols of Scottish identity mentioned in the course, with one sentence each.","bareme":[{"critere":"Traduction fidèle (grew rich, has reinvented itself, have taken place since = présent en français)","points":10},{"critere":"Trois symboles exacts de l'identité écossaise expliqués en anglais","points":6},{"critere":"Correction du français et de l'anglais","points":4}],"dureeMin":8,"corrige":"**1. Traduction proposée**\n« Glasgow s'est enrichie grâce aux chantiers navals de la Clyde. Aujourd'hui, l'ancienne ville ouvrière s'est réinventée par la culture et a accueilli la COP26 en 2021. Édimbourg, la capitale, est célèbre pour son château, son Festival et le Fringe, qui ont lieu chaque été depuis 1947. »\n\nPoints de vigilance : *grew rich* → « s'est enrichie » ; *have taken place … since 1947* → présent en français avec « depuis » (« ont lieu depuis 1947 ») ; *working-class* → « ouvrière ».\n\n**2. Three symbols among:**\n- *The SNP is the party that wants Scottish independence.*\n- *The poet Robert Burns is celebrated every 25 January on Burns Night.*\n- *Scottish Gaelic is a language of Scotland.*\n- *The Stone of Destiny was returned to Scotland in 1996.*\n- *The Scottish Parliament sits at Holyrood, in a building opened in 2004.*"}$exo$::jsonb),
  ('2d81b711-0f68-5128-9e6a-44ff64af99fb'::uuid, 2, 'traduction', $exo${"titre":"Derry or Londonderry ?","consigne":"Lis le document, puis réponds en anglais aux trois questions.","enonce":"**Document (invented testimony).**\n\n> « My grandmother still says Londonderry; my best friend says Derry. We live in the same city, but our words tell different stories. Near my school, a peace wall still separates two neighbourhoods. The Good Friday Agreement changed my parents' lives, but it hasn't changed everything. » — *Aoife, 17, Northern Ireland*\n\n1. Explain the two names of the city: who uses each name, and what does each community want?\n2. What did the **Good Friday Agreement** (10 April 1998) establish? Give two elements.\n3. Explain in about 60 words the sentence « *it hasn't changed everything* », using the course.","bareme":[{"critere":"Deux noms expliqués : unionistes / nationalistes, religions et projets politiques","points":5},{"critere":"Deux éléments exacts de l'accord : partage du pouvoir, droit de se dire britannique, irlandais ou les deux","points":5},{"critere":"Explication appuyée sur les murs de la paix et la question de la frontière après le Brexit","points":6},{"critere":"Correction de la langue anglaise","points":4}],"dureeMin":12,"corrige":"**1.** *Unionists or loyalists, mostly Protestant, say « Londonderry »: they want to remain in the United Kingdom. Nationalists or republicans, mostly Catholic, say « Derry »: they would like the reunification with Ireland. The name of the city reveals political identity.*\n\n**2.** *The Good Friday Agreement (10 April 1998) established power-sharing between the two communities, and it gave people the right to be British, Irish, or both. It ended the Troubles, which had caused about 3,500 deaths since the late 1960s.*\n\n**3. Model answer**\n*Peace was signed in 1998, but living together is still being built. In Belfast and elsewhere, peace walls still separate some Catholic and Protestant neighbourhoods. Brexit has also reopened the question of the Irish border. However, change is visible: in 2024, Michelle O'Neill became the first nationalist First Minister.*"}$exo$::jsonb),
  ('2d81b711-0f68-5128-9e6a-44ff64af99fb'::uuid, 3, 'traduction', $exo${"titre":"Identity is not a single box to tick","consigne":"Rédige en anglais un essai d'environ 180 mots, en t'appuyant sur les trois nations étudiées.","enonce":"**Essay question.**\n\n> *« Identity is not a single box to tick. » Show how Scotland, Wales and Northern Ireland illustrate this idea.*\n\nUse at least **one precise reference for each nation** (date, law, event, place, festival) and at least **two** words from this list: *a minority language, to revive, power-sharing, a unionist, a nationalist*.\n\nYour essay should have an introduction, a development and a conclusion.","bareme":[{"critere":"Un repère exact pour chacune des trois nations","points":6},{"critere":"Idée d'identité plurielle démontrée, pas seulement illustrée","points":5},{"critere":"Deux mots imposés bien employés","points":2},{"critere":"Structure et cohérence","points":2},{"critere":"Correction de la langue anglaise","points":5}],"dureeMin":20,"corrige":"**Model essay (≈ 180 words)**\n\n*One can be British and feel Scottish, Welsh or Irish first, or refuse one of these words. The three nations show that identity is plural.*\n\n*In Scotland, identity is expressed through symbols: the poet Robert Burns is celebrated every 25 January, and the Stone of Destiny was returned to Scotland in 1996. Yet many Scots also feel British: in 2014, 55 % voted to stay in the United Kingdom.*\n\n*In Wales, language is at the heart of identity. Welsh, a minority language spoken by about one Welsh person in six, was given official status by the Welsh Language Act of 1993. Bilingual signs, Welsh-medium schools and the Eisteddfod help to revive it.*\n\n*In Northern Ireland, identity has been a source of conflict: a unionist wants to stay in the UK, a nationalist hopes for reunification with Ireland. The Good Friday Agreement of 1998 introduced power-sharing and allows people to be British, Irish, or both.*\n\n*In conclusion, the three nations prove that identity is not a single box to tick: the 1998 agreement even wrote this idea into law.*\n\n**Attendus** : un repère exact par nation ; l'idée d'identité plurielle ; deux mots imposés."}$exo$::jsonb),
  ('cce272bb-dd9d-5d1f-ae77-8e408b3720c8'::uuid, 1, 'traduction', $exo${"titre":"Never have I… : five sentences to rewrite","consigne":"Réécris chaque phrase en commençant par le mot donné, avec l'inversion, puis traduis deux phrases.","enonce":"**1.** Rewrite each sentence, starting with the word(s) in brackets.\n\n- a) I have never seen such a beautiful city. (*Never*)\n- b) She rarely speaks in public. (*Rarely*)\n- c) He lost his job, and he also lost his home. (*Not only*)\n- d) If I had known, I would have helped you. (*Had*)\n- e) You should not leave the room under any circumstances. (*Under no circumstances*)\n\n**2.** Translate sentences b) and d) of your answer into French.","bareme":[{"critere":"Cinq inversions justes (auxiliaire avant le sujet, do / does / did quand il le faut)","points":14},{"critere":"Deux traductions justes et naturelles","points":6}],"dureeMin":7,"corrige":"**1.**\n- a) ***Never have I** seen such a beautiful city.*\n- b) ***Rarely does she** speak in public.* — présent simple sans auxiliaire → *does*, et le verbe revient à la base verbale.\n- c) ***Not only did he** lose his job, **but** he **also** lost his home.* — prétérit simple → *did* + base verbale.\n- d) ***Had I known**, I would have helped you.* — *if* disparaît.\n- e) ***Under no circumstances should you** leave the room.*\n(a, b, d, e : 3 points chacune ; c : 2 points.)\n\n**2.**\n- b) « Il est rare qu'elle prenne la parole en public. » / « Elle parle rarement en public. »\n- d) « Si j'avais su, je t'aurais aidé. »"}$exo$::jsonb),
  ('cce272bb-dd9d-5d1f-ae77-8e408b3720c8'::uuid, 2, 'traduction', $exo${"titre":"Hardly, no sooner, little","consigne":"Corrige les phrases fautives, complète les autres, puis traduis-en trois.","enonce":"**1.** Each sentence contains **one** mistake. Correct it.\n\n- a) *No sooner had he left when it started to rain.*\n- b) *Never I have felt so free.*\n- c) *Only then I understood the truth.*\n\n**2.** Complete with the correct form of the verb in brackets.\n\n- d) Hardly ___ (she / arrive) when the phone rang.\n- e) Little ___ (they / know) that the war would last four years.\n- f) Seldom ___ (we / see) such courage.\n\n**3.** Translate sentences a), d) and e) (corrected) into French.","bareme":[{"critere":"Trois corrections justes (than, have I, did I understand)","points":6},{"critere":"Trois formes justes (had she arrived, did they know, do we see)","points":6},{"critere":"Trois traductions justes (à peine … que, être loin de se douter)","points":6},{"critere":"Orthographe et ponctuation","points":2}],"dureeMin":11,"corrige":"**1.**\n- a) *No sooner had he left **than** it started to rain.* — *No sooner* va avec *than* (*Hardly* avec *when*).\n- b) ***Never have I** felt so free.* — inversion auxiliaire / sujet.\n- c) ***Only then did I understand** the truth.* — prétérit simple → *did* + base verbale.\n\n**2.**\n- d) *Hardly **had she arrived** when the phone rang.*\n- e) *Little **did they know** that the war would last four years.*\n- f) *Seldom **do we see** such courage.*\n\n**3.**\n- a) « À peine était-il parti qu'il se mit (s'est mis) à pleuvoir. »\n- d) « À peine était-elle arrivée que le téléphone sonna. »\n- e) « Ils étaient loin de se douter que la guerre durerait quatre ans. »"}$exo$::jsonb),
  ('cce272bb-dd9d-5d1f-ae77-8e408b3720c8'::uuid, 3, 'traduction', $exo${"titre":"Frapper fort dans un essai","consigne":"Traduis le paragraphe en anglais en employant trois inversions imposées, puis explique ton choix stylistique.","enonce":"**Paragraph to translate (thème).**\n\n> Le gouvernement n'a pas seulement ignoré les avertissements : il a aussi réduit le budget. Jamais les habitants ne s'étaient sentis aussi abandonnés. Ce n'est qu'après l'inondation qu'ils ont compris l'ampleur du problème. Si les autorités avaient écouté les scientifiques, la catastrophe aurait pu être évitée.\n\n*Help: to cut = réduire ; the flood = l'inondation ; the extent = l'ampleur ; to avoid = éviter.*\n\n1. Translate the paragraph, using an inversion with **Not only**, with **Never**, with **Only after**, and a conditional inversion with **Had**.\n2. In French, explain in three or four sentences why these inversions strengthen the paragraph, and why you should not use too many in an essay.","bareme":[{"critere":"Not only did … but … also juste","points":4},{"critere":"Never had … felt juste (past perfect inversé)","points":3},{"critere":"Only after … did they understand juste","points":3},{"critere":"Had the authorities listened …, could have been avoided juste","points":4},{"critere":"Effet stylistique expliqué et limite d'usage mentionnée ; reste du texte correct","points":6}],"dureeMin":16,"corrige":"**1. Traduction proposée**\n*Not only did the government ignore the warnings, but it also cut the budget. Never had the inhabitants felt so abandoned. Only after the flood did they understand the extent of the problem. Had the authorities listened to the scientists, the disaster could have been avoided.*\n\nPoints de vigilance :\n- *Not only did the government ignore* : prétérit simple → *did* + base verbale ; *but … also*.\n- *Never had the inhabitants felt* : plus-que-parfait français → past perfect, auxiliaire *had* avant le sujet.\n- *Only after the flood did they understand* (et non *they understood*).\n- *Had the authorities listened* = *If the authorities had listened* ; *could have been avoided* (modal + passif passé).\n\n**2. Explication attendue**\nL'inversion met en relief une idée forte : placer *Never*, *Not only* ou *Only after* en tête de phrase attire l'attention du lecteur sur l'ampleur de la faute, le sentiment d'abandon ou la prise de conscience tardive. C'est une marque d'anglais écrit soutenu, qui donne de la force à l'ouverture ou à la conclusion d'un paragraphe. Mais une ou deux inversions par essai suffisent : au-delà, le style devient pesant et l'effet se perd (ici, quatre inversions sont un exercice, pas un modèle de copie)."}$exo$::jsonb),
  ('bcd86911-66dd-5708-b98d-1eb631b7273d'::uuid, 1, 'traduction', $exo${"titre":"That he be… : six sentences","consigne":"Complète chaque phrase avec la forme correcte du verbe entre parenthèses.","enonce":"**Complete.**\n\n1. It is essential that every citizen ___ (be) informed.\n2. They insisted that she ___ (leave) at once.\n3. I recommend that he ___ (see) a doctor.\n4. We suggest that he ___ (not / travel) alone.\n5. He talks as if he ___ (know) everything.\n6. It's high time the government ___ (act).\n\n**Question.** Explain in French, in two sentences, why sentences 1 to 4 and sentences 5 and 6 do not use the same form of the verb.","bareme":[{"critere":"Quatre subjonctifs présents justes (be, leave, see, not travel)","points":8},{"critere":"Deux formes au prétérit justes (knew, acted)","points":4},{"critere":"Explication : base verbale après exigence / recommandation ; prétérit pour l'irréel","points":8}],"dureeMin":7,"corrige":"1. *It is essential that every citizen **be** informed.*\n2. *They insisted that she **leave** at once.*\n3. *I recommend that he **see** a doctor.*\n4. *We suggest that he **not travel** alone.* — négation : *not* + base verbale, sans *do*.\n5. *He talks as if he **knew** everything.*\n6. *It's high time the government **acted**.*\n\n**Explication.** Dans les phrases 1 à 4, le verbe suit une expression d'exigence, de recommandation ou d'importance + *that* : on emploie le **subjonctif présent**, c'est-à-dire la base verbale à toutes les personnes (pas de *-s*, *be* pour *be*). Dans les phrases 5 et 6, on exprime l'**irréel** (il ne sait pas tout ; le gouvernement n'agit pas) : après *as if* et *it's high time*, on emploie le **prétérit** (subjonctif « passé »).\n\nAccepter en 1 à 3 la tournure britannique avec *should* (*should be*, *should leave*, *should see*)."}$exo$::jsonb),
  ('bcd86911-66dd-5708-b98d-1eb631b7273d'::uuid, 2, 'traduction', $exo${"titre":"From should to the subjunctive","consigne":"Fais les trois exercices dans l'ordre.","enonce":"**1.** Rewrite each sentence with the subjunctive instead of *should*.\n\n- a) The teacher suggests that Tom should read the book again.\n- b) It is vital that the law should protect minorities.\n- c) The doctor recommends that she should not work this week.\n\n**2.** Translate into English.\n\n- a) Je préférerais que tu restes.\n- b) Elle avait l'air d'avoir vu un fantôme.\n- c) Si j'étais toi, j'accepterais.\n\n**3.** Translate into French and explain: *Come what may*, *So be it*.","bareme":[{"critere":"Trois subjonctifs justes (read, protect, not work)","points":7},{"critere":"Trois traductions justes (stayed, as if she had seen, If I were you)","points":8},{"critere":"Deux formules figées traduites et reconnues comme subjonctifs","points":5}],"dureeMin":11,"corrige":"**1.**\n- a) *The teacher suggests that Tom **read** the book again.* (base verbale, pas *reads*)\n- b) *It is vital that the law **protect** minorities.*\n- c) *The doctor recommends that she **not work** this week.*\n\n**2.**\n- a) *I'd rather you **stayed**.* (I'd rather + sujet + prétérit)\n- b) *She looked **as if** she **had seen** a ghost.* (as if + past perfect)\n- c) ***If I were you**, I would accept.* (*Were I you, I would accept* accepté)\n\n**3.**\n- *Come what may* : « advienne que pourra ».\n- *So be it* : « ainsi soit-il ».\nCe sont des formules figées où survit le subjonctif : *come* et *be* sont des bases verbales, sans *-s* ni conjugaison."}$exo$::jsonb),
  ('bcd86911-66dd-5708-b98d-1eb631b7273d'::uuid, 3, 'traduction', $exo${"titre":"A formal letter to the head teacher","consigne":"Traduis la lettre en anglais soutenu (thème), puis justifie trois de tes choix.","enonce":"**Letter to translate (invented).**\n\n> Madame la Proviseure,\n> Il est indispensable que chaque élève soit traité de la même façon. Nous proposons que le lycée ne fasse aucune exception au règlement. Certains professeurs parlent comme s'ils ignoraient le problème. Il est grand temps que la direction agisse, et nous préférerions qu'elle nous consulte.\n\n*Help: the head teacher = le proviseur ; the rules = le règlement ; to consult = consulter ; the management = la direction.*\n\n1. Translate the letter into formal English.\n2. In French, justify **three** of your choices (subjunctive present, *as if*, *it is high time*, *would rather*).","bareme":[{"critere":"Subjonctif présent juste : be treated, not make","points":5},{"critere":"Irréel juste : as if they did not know, it is high time … acted, would rather … consulted","points":6},{"critere":"Trois choix justifiés avec la règle du cours","points":5},{"critere":"Registre soutenu et correction du reste de la lettre","points":4}],"dureeMin":18,"corrige":"**1. Traduction proposée**\n*Dear Head Teacher,*\n*It is essential that every pupil **be treated** equally. We propose that the school **not make** any exception to the rules. Some teachers talk **as if** they **did not know** about the problem. **It is high time** the management **acted**, and we **would rather** it **consulted** us.*\n\nAccepter : *every student* ; *in the same way* ; *should be treated* (moins soutenu) ; *as though*.\n\n**2. Justifications**\n- *be treated* : après *it is essential that*, subjonctif présent = base verbale à toutes les personnes (*be*, pas *is*), ici au passif.\n- *not make* : négation du subjonctif = *not* + base verbale, sans *do* (*does not make* serait l'indicatif).\n- *as if they did not know* : *as if* + prétérit exprime l'irréel (ils connaissent le problème, en réalité).\n- *It is high time the management acted* : *it's high time* + prétérit.\n- *we would rather it consulted us* : *would rather* + sujet + prétérit.\nTrois justifications exactes suffisent."}$exo$::jsonb),
  ('a6649917-865a-5740-9688-a7853abc97a1'::uuid, 1, 'traduction', $exo${"titre":"This time tomorrow…","consigne":"Traduis chaque phrase en anglais avec BE + -ING à la forme qui convient.","enonce":"**Translate into English.**\n\n1. Demain à cette heure-ci, je serai en train de voler vers Boston.\n2. Elle doit être en train de dormir (déduction).\n3. Ils nous attendent peut-être en ce moment.\n4. En juin, cela fera dix ans qu'elle travaille ici. (*By June…*)\n5. Tu aurais dû écouter !\n\n**Question.** Why is *I will be knowing the results tomorrow* wrong? Answer in French in one sentence.","bareme":[{"critere":"Cinq traductions justes (will be flying, must be sleeping, might be waiting, will have been working, should have been listening)","points":15},{"critere":"Explication : know est un verbe d'état, il refuse BE + -ING","points":5}],"dureeMin":7,"corrige":"1. *This time tomorrow, I**'ll be flying** (I will be flying) to Boston.*\n2. *She **must be sleeping**.*\n3. *They **might be waiting** for us* (*may be waiting* accepté).\n4. *By June, she **will have been working** here for ten years.*\n5. *You **should have been listening**!*\n(3 points par phrase.)\n\n**Question.** *know* est un verbe d'**état** : il ne se met jamais à la forme BE + -ING, quel que soit le temps ; il faut dire *I will know the results tomorrow*."}$exo$::jsonb),
  ('a6649917-865a-5740-9688-a7853abc97a1'::uuid, 2, 'traduction', $exo${"titre":"Simple or continuous ?","consigne":"Choisis la bonne forme et justifie chaque choix en français.","enonce":"**Choose the correct form and justify your choice in one line.**\n\n1. He must have lied / must have been lying all evening: nobody believed him.\n2. By 2030, I will have known / will have been knowing her for twenty years.\n3. Will you use / Will you be using the car tonight? I'd like to borrow it.\n4. Her eyes were red: she had cried / had been crying.\n5. In 2050, people will be living / will live in new places, according to the report. (both may be possible: explain the difference)\n6. He must be driving / must have been driving when you called him yesterday.","bareme":[{"critere":"Six choix justes","points":9},{"critere":"Six justifications exactes (action en cours, durée, verbe d'état, question polie, repère passé)","points":9},{"critere":"Précision du vocabulaire grammatical","points":2}],"dureeMin":12,"corrige":"1. *must have been lying* — déduction sur une action **en cours qui a duré** dans le passé (« all evening ») ; *must have lied* viserait un fait ponctuel.\n2. *will have known* — *know* est un verbe d'état : pas de BE + -ING.\n3. *Will you be using* — question polie qui demande un programme sans faire pression.\n4. *had been crying* — activité qui a duré juste avant, dont on voit le résultat (les yeux rouges).\n5. Les deux sont possibles : *will be living* présente la situation **en déroulement** à un moment du futur (on se place en 2050, de l'intérieur) ; *will live* énonce simplement une prédiction. Le cours donne *will be living* pour « une situation qui se déroulera ».\n6. *must have been driving* — déduction sur une action en cours dans le **passé** (« yesterday », « when you called ») : modal + *have been* + V-ING. *must be driving* porte sur le présent.\n\nBarème : 1,5 point par choix juste, 1,5 par justification juste."}$exo$::jsonb),
  ('a6649917-865a-5740-9688-a7853abc97a1'::uuid, 3, 'traduction', $exo${"titre":"A strange evening : translation","consigne":"Traduis le texte en anglais (thème), puis justifie trois de tes choix.","enonce":"**Text to translate (invented).**\n\n> Quand je suis arrivée, Lucy avait pleuré : ses yeux étaient rouges. Elle devait être en train de lire la lettre de son frère quand j'ai sonné. Demain à cette heure-ci, elle sera en route pour Londres. En septembre, cela fera trois ans qu'elle attend une réponse. Je la connais depuis longtemps, et je crois qu'elle aurait dû m'écouter.\n\n*Help: to ring the bell = sonner ; to be on one's way = être en route.*\n\n1. Translate the text.\n2. In French, justify **three** of your choices, one of which must concern a verb that refuses BE + -ING.","bareme":[{"critere":"had been crying et must have been reading justes","points":5},{"critere":"will be travelling (ou will be on her way) et will have been waiting justes","points":4},{"critere":"Verbes d'état sans -ING : have known, believe / think","points":3},{"critere":"should have been listening ou should have listened, justifié","points":2},{"critere":"Trois choix justifiés et correction du reste","points":6}],"dureeMin":18,"corrige":"**1. Traduction proposée**\n*When I arrived, Lucy **had been crying**: her eyes were red. She **must have been reading** her brother's letter when I rang the bell. This time tomorrow, she**'ll be travelling** to London (she will be on her way to London). By September, she **will have been waiting** for an answer for three years. I **have known** her for a long time, and I **believe** she **should have listened** (should have been listening) to me.*\n\n**2. Justifications (trois attendues)**\n- *had been crying* : activité qui a duré juste avant mon arrivée, dont le résultat est visible.\n- *must have been reading* : déduction sur une action **en cours** dans le passé → modal + *have been* + V-ING.\n- *will be travelling* : action en cours à un moment précis du futur (« demain à cette heure-ci »).\n- *will have been waiting* : durée jusqu'à un point du futur.\n- *have known*, *believe* : verbes d'**état**, ils refusent BE + -ING (*have been knowing* et *am believing* sont fautifs).\n- *should have listened* : reproche ; *should have been listening* insiste sur une attitude qui aurait dû durer. Les deux sont acceptés.\n\nUne justification sur un verbe d'état est obligatoire."}$exo$::jsonb),
  ('8b0e08dd-a283-592b-8038-b01ba17315c5'::uuid, 1, 'traduction', $exo${"titre":"Must be repaired : five passives","consigne":"Mets chaque phrase au passif, sans complément d'agent sauf s'il est indispensable.","enonce":"**Put into the passive.**\n\n1. They must repair the road.\n2. Someone should have warned them.\n3. We can't solve this problem easily.\n4. They might have stolen it.\n5. They looked after the children well.\n\n**Question.** In one sentence in French, explain what never changes place in sentence 5.","bareme":[{"critere":"Quatre passifs avec modal justes (be / have been + participe passé)","points":12},{"critere":"Passif du verbe à particule juste (were well looked after)","points":4},{"critere":"Règle expliquée : la particule reste collée au verbe","points":4}],"dureeMin":6,"corrige":"1. *The road **must be repaired**.*\n2. *They **should have been warned**.*\n3. *This problem **can't be solved** easily.*\n4. *It **might have been stolen**.*\n5. *The children **were well looked after**.*\n\nLe modal ne bouge pas : c'est *be* (ou *have been*) qui porte le passif (*must be repaired*, jamais *must repaired*).\n\n**Question.** La particule (*after*) reste collée au verbe *looked*, même si elle se retrouve en fin de phrase : on ne la supprime jamais."}$exo$::jsonb),
  ('8b0e08dd-a283-592b-8038-b01ba17315c5'::uuid, 2, 'traduction', $exo${"titre":"Women were not given…","consigne":"Fais les trois exercices dans l'ordre.","enonce":"**1.** Put into the passive, starting with the **person**.\n\n- a) They didn't give women the right to vote.\n- b) The company offered Sam a job.\n\n**2.** Put into the passive.\n\n- c) They made him apologise.\n- d) Nobody has dealt with the complaint.\n- e) The crowd laughed at him.\n\n**3.** Translate into English with an impersonal passive.\n\n- f) On dit qu'il est riche.\n- g) On pense qu'elle a quitté le pays.","bareme":[{"critere":"Deux passifs à double complément justes, la personne en sujet","points":5},{"critere":"Trois passifs justes (was made to, hasn't been dealt with, was laughed at)","points":8},{"critere":"Deux tournures impersonnelles justes (is said to be, is believed to have left)","points":7}],"dureeMin":11,"corrige":"**1.**\n- a) ***Women were not given** the right to vote.*\n- b) ***Sam was offered** a job (by the company).*\nAvec deux compléments, mettre la **personne** en sujet est plus naturel.\n\n**2.**\n- c) *He **was made to** apologise.* — le *to* réapparaît au passif.\n- d) *The complaint **hasn't been dealt with**.* — la préposition reste collée au verbe.\n- e) *He **was laughed at**.*\n\n**3.**\n- f) *He **is said to be** rich.*\n- g) *She **is believed to have left** the country.* — l'infinitif passé (*to have left*) marque l'antériorité.\n\nFautes à sanctionner : *He was made apologise* ; *The complaint hasn't been dealt* ; *It is said he rich*."}$exo$::jsonb),
  ('8b0e08dd-a283-592b-8038-b01ba17315c5'::uuid, 3, 'traduction', $exo${"titre":"After the flood : translation","consigne":"Traduis le texte en anglais (thème) en privilégiant le passif, puis justifie trois de tes choix.","enonce":"**Text to translate (invented news report).**\n\n> On aurait dû prévenir les habitants. On dit que la digue a été mal entretenue, et personne ne s'est occupé des plaintes. Aujourd'hui, les familles sans logement sont prises en charge par la mairie. On ne leur a pas proposé de nouvel appartement, et certains ont été obligés de partir. On pense que les travaux pourraient être terminés l'an prochain.\n\n*Help: a dyke = une digue ; to maintain = entretenir ; to look after = s'occuper de, prendre en charge ; the town council = la mairie ; the work = les travaux.*\n\n1. Translate the text, using the passive wherever possible.\n2. In French, justify **three** of your choices.","bareme":[{"critere":"Modal + passif justes : should have been warned, could be finished","points":4},{"critere":"Tournures impersonnelles justes : is said to have been, it is believed / are believed","points":4},{"critere":"Verbes à particule au passif justes : were never dealt with, are looked after","points":4},{"critere":"Double complément et make : were not offered, were made to leave","points":4},{"critere":"Trois choix justifiés et correction du reste","points":4}],"dureeMin":18,"corrige":"**1. Traduction proposée**\n*The residents **should have been warned**. The dyke **is said to have been** poorly maintained, and the complaints **were never dealt with**. Today, homeless families **are looked after** by the town council. They **were not offered** a new flat, and some of them **were made to** leave. **It is believed** that the work **could be finished** next year.*\n\nAccepter : *had to leave* à la place de *were made to leave* (le sens « obligés » est rendu, mais la phrase n'est plus un passif : 1 point sur 2) ; *weren't offered* ; *have never been dealt with*.\n\n**2. Justifications (trois attendues)**\n- *should have been warned* : modal + *have been* + participe passé pour un passif passé (reproche).\n- *is said to have been maintained* : tournure impersonnelle de l'opinion ; l'infinitif passé marque que l'entretien est antérieur.\n- *were never dealt with* / *are looked after* : la particule reste collée au verbe au passif.\n- *They were not offered a new flat* : avec deux compléments, la personne devient sujet.\n- *were made to leave* : au passif, *make* + infinitif reprend *to*.\n- *could be finished* : modal + *be* + participe passé."}$exo$::jsonb),
  ('3087b8d9-8bdb-5554-92ca-959a5bd04963'::uuid, 1, 'traduction', $exo${"titre":"Opposites and new words","consigne":"Forme les mots demandés, puis traduis-les.","enonce":"**1.** Give the **opposite** of each word, using a prefix or a suffix.\n\n- a) honest\n- b) legal\n- c) careful\n- d) possible\n- e) to understand (*mal comprendre*)\n\n**2.** Form a **noun** from each word.\n\n- f) happy\n- g) equal\n- h) child\n\n**3.** Translate all eight new words into French.","bareme":[{"critere":"Cinq contraires justes (dishonest, illegal, careless, impossible, to misunderstand)","points":8},{"critere":"Trois noms justes (happiness, equality, childhood)","points":6},{"critere":"Huit traductions justes","points":6}],"dureeMin":7,"corrige":"**1.**\n- a) *dishonest* — malhonnête\n- b) *illegal* — illégal\n- c) *careless* — négligent, imprudent (suffixe *-less* = sans)\n- d) *impossible* — impossible\n- e) *to misunderstand* — mal comprendre (préfixe *mis-*)\n\n**2.**\n- f) *happiness* — le bonheur\n- g) *equality* — l'égalité\n- h) *childhood* — l'enfance\n\nRappel : le préfixe négatif ne se choisit pas au hasard (*dishonest*, jamais *unhonest*) ; *careless* (sans soin) et non *uncareful*."}$exo$::jsonb),
  ('3087b8d9-8bdb-5554-92ca-959a5bd04963'::uuid, 2, 'traduction', $exo${"titre":"Decoding an article","consigne":"Découpe les mots soulignés en éléments, donne leur nature et leur sens, puis traduis l'extrait.","enonce":"**Extract (invented article).**\n\n> Rents are now **unaffordable** in many **overcrowded** cities. **Homelessness** is rising, and **underpaid** workers feel **powerless**. Some **postcolonial** writers see this as a new form of inequality. Young people **text** each other to organise protests.\n\n1. For each word in bold, split it into its parts (prefix, root, suffix) and give its nature (noun, adjective, verb) and its meaning.\n2. Which word in bold is an example of **conversion**? Explain.\n3. Translate the extract into French.","bareme":[{"critere":"Six mots correctement découpés, nature et sens justes","points":9},{"critere":"Conversion repérée (to text) et expliquée","points":3},{"critere":"Traduction fidèle et naturelle","points":6},{"critere":"Correction du français","points":2}],"dureeMin":12,"corrige":"**1.**\n- *un-afford-able* : adjectif ; qu'on ne peut pas se permettre → « inabordable, trop cher ».\n- *over-crowd-ed* : adjectif ; trop de monde → « surpeuplé ».\n- *home-less-ness* : nom ; le fait d'être sans logis → « le sans-abrisme ».\n- *under-paid* : adjectif ; pas assez payé → « sous-payé ».\n- *power-less* : adjectif ; sans pouvoir → « impuissant ».\n- *post-colonial* : adjectif ; après la période coloniale → « postcolonial ».\n\n**2.** *text* : le nom *a text* devient le verbe *to text* (envoyer un SMS) sans changer de forme : c'est une **conversion** (nom → verbe).\n\n**3. Traduction proposée**\n« Les loyers sont désormais inabordables dans de nombreuses villes surpeuplées. Le nombre de sans-abri augmente, et les travailleurs sous-payés se sentent impuissants. Certains écrivains postcoloniaux y voient une nouvelle forme d'inégalité. Les jeunes s'envoient des SMS pour organiser des manifestations. »"}$exo$::jsonb),
  ('3087b8d9-8bdb-5554-92ca-959a5bd04963'::uuid, 3, 'traduction', $exo${"titre":"Word building in context","consigne":"Complète le texte avec des mots dérivés des racines données, puis justifie trois formations et traduis le texte.","enonce":"**Text with gaps (invented).** Form the correct word from the root in brackets.\n\n> The report was **(1)** ___ (lead): it made readers believe that **(2)** ___ (employ) had fallen. In fact, many young people are still **(3)** ___ (employ), and **(4)** ___ (refuge) often work as **(5)** ___ (train) for very low wages. The government promises to **(6)** ___ (modern) the job centres and to **(7)** ___ (wide) access to training, but many **(8)** ___ (science) remain **(9)** ___ (hope): they think this plan is simply **(10)** ___ (relevant).\n\n*Help: the meaning is given by the context. (9) must mean « sans espoir ».*\n\n1. Fill in the ten gaps.\n2. In French, justify **three** formations (prefix or suffix and its meaning).\n3. Translate the text into French.","bareme":[{"critere":"Dix mots justes et bien orthographiés","points":10},{"critere":"Trois formations justifiées (sens du préfixe ou du suffixe)","points":4},{"critere":"Traduction fidèle et naturelle","points":6}],"dureeMin":18,"corrige":"**1.**\n(1) *misleading* ; (2) *unemployment* ; (3) *unemployed* ; (4) *refugees* ; (5) *trainees* ; (6) *modernise* (*modernize*) ; (7) *widen* ; (8) *scientists* ; (9) *hopeless* ; (10) *irrelevant*.\n\n**2. Justifications possibles**\n- *mis-leading* : *mis-* = de travers → qui induit en erreur, trompeur.\n- *un-employ-ment* : *un-* = contraire, *-ment* = nom → le chômage.\n- *refugee*, *trainee* : *-ee* = celui qui subit ou reçoit (le réfugié, le stagiaire).\n- *modern-ise*, *wid-en* : *-ise* et *-en* forment des verbes (moderniser, élargir).\n- *scient-ist* : *-ist* = une personne.\n- *hope-less* : *-less* = sans → sans espoir.\n- *ir-relevant* : *ir-* = contraire devant *r* → hors de propos.\n\n**3. Traduction proposée**\n« Le rapport était trompeur : il faisait croire aux lecteurs que le chômage avait baissé. En réalité, beaucoup de jeunes sont toujours sans emploi, et les réfugiés travaillent souvent comme stagiaires pour des salaires très bas. Le gouvernement promet de moderniser les agences pour l'emploi et d'élargir l'accès à la formation, mais de nombreux scientifiques restent sans espoir : ils pensent que ce plan est tout simplement hors de propos. »"}$exo$::jsonb),
  ('07cfe4c0-994f-55e1-9a35-00c7d2c2f1be'::uuid, 1, 'traduction', $exo${"titre":"Eventually n'a rien d'éventuel","consigne":"Traduis chaque phrase en français en évitant le faux ami.","enonce":"**Translate into French.**\n\n1. Eventually, they found the library.\n2. Actually, he is a very sensible person.\n3. She attended a lecture on climate change.\n4. He pretended to be ill.\n5. I suddenly realised that I had lost my keys.\n6. The journey took three hours.\n\n**Question.** For each sentence, name the **false friend** and give the English word that means what the French look-alike means.","bareme":[{"critere":"Six traductions justes, sans faux sens","points":12},{"critere":"Six faux amis identifiés avec le bon équivalent anglais du mot français","points":8}],"dureeMin":8,"corrige":"1. « **Finalement**, ils ont trouvé la **bibliothèque**. » — *eventually* ≠ éventuellement (*possibly*) ; *library* ≠ librairie (*bookshop*).\n2. « **En fait**, c'est quelqu'un de très **raisonnable**. » — *actually* ≠ actuellement (*currently*) ; *sensible* ≠ sensible (*sensitive*).\n3. « Elle **a assisté à** un **cours magistral** sur le changement climatique. » — *to attend* ≠ attendre (*to wait*) ; *lecture* ≠ lecture (*reading*).\n4. « Il **a fait semblant** d'être malade. » — *to pretend* ≠ prétendre (*to claim*).\n5. « Je **me suis soudain rendu compte** que j'avais perdu mes clés. » — *to realise* ≠ réaliser un projet (*to carry out, to achieve*).\n6. « Le **trajet** (voyage) a duré trois heures. » — *journey* ≠ journée (*a day*).\n\nBarème : 2 points par traduction ; 8 points pour l'ensemble des faux amis identifiés (retirer 1 point par faux ami manquant ou mal corrigé)."}$exo$::jsonb),
  ('07cfe4c0-994f-55e1-9a35-00c7d2c2f1be'::uuid, 2, 'traduction', $exo${"titre":"Calques à corriger","consigne":"Chaque phrase anglaise est un calque du français : corrige-la et explique l'erreur.","enonce":"**Correct each sentence and explain the mistake in French.**\n\n1. There are two years, I visited London.\n2. I am here since Monday.\n3. It depends of the weather.\n4. He gave me many advices.\n5. We assisted to a football match.\n6. The people is angry.\n7. Currently I know it, but eventually I will change my mind. (*Sens voulu : « En fait, je le sais, mais je changerai peut-être d'avis. »*)","bareme":[{"critere":"Sept corrections justes","points":11},{"critere":"Sept erreurs expliquées (calque, indénombrable, faux ami)","points":7},{"critere":"Orthographe et ponctuation","points":2}],"dureeMin":12,"corrige":"1. *I visited London **two years ago**.* — « il y a » + durée = *ago*, placé après la durée.\n2. *I **have been** here **since** Monday.* — « depuis » avec une action qui dure jusqu'à maintenant → present perfect.\n3. *It depends **on** the weather.* — *depend on*, pas *of*.\n4. *He gave me **a lot of advice** (some advice).* — *advice* est indénombrable : pas de *-s*, pas de *many*.\n5. *We **attended** (watched) a football match.* — « assister à » = *to attend* ; *to assist* = aider.\n6. *People **are** angry.* — *people* est déjà pluriel ; « les gens » en général se dit *people*, sans *the*.\n7. ***Actually**, I know it, but I **might (may) possibly** change my mind.* — *currently* = actuellement (sens temporel) ; « en fait » = *actually*. *Eventually* = finalement ; « peut-être / éventuellement » = *possibly* ou un modal (*might*)."}$exo$::jsonb),
  ('07cfe4c0-994f-55e1-9a35-00c7d2c2f1be'::uuid, 3, 'traduction', $exo${"titre":"Version et thème piégés","consigne":"Traduis le texte anglais en français (version), puis la phrase française en anglais (thème), en déjouant tous les pièges.","enonce":"**1. Version (invented text).**\n\n> Actually, the students who attend this lecture every week are rather sensible. Eventually, many of them realise that they have to support each other. The teacher, who was said to be strict, has been working here for ten years. By chance, one of the students swam across the river to reach the campus on the day of the strike.\n\n**2. Thème.**\n\n> Actuellement, la plupart des gens pensent que les informations qu'on lit en ligne sont fiables, mais il y a trois ans, ils ne vérifiaient rien. Cela dépend de leurs habitudes.\n\n*Help: reliable = fiable ; a habit = une habitude.*","bareme":[{"critere":"Faux amis de la version rendus dans leur vrai sens (actually, attend, lecture, sensible, eventually, realise, support, chance)","points":6},{"critere":"Structures de la version rendues naturellement (was said to be, has been working for, swam across)","points":4},{"critere":"Thème : currently, people are, information indénombrable, ago, depends on","points":6},{"critere":"Correction et naturel du français et de l'anglais","points":4}],"dureeMin":18,"corrige":"**1. Version proposée**\n« En fait, les étudiants qui assistent à ce cours magistral chaque semaine sont plutôt raisonnables. Finalement, beaucoup d'entre eux se rendent compte qu'ils doivent se soutenir les uns les autres. Le professeur, que l'on disait sévère, travaille ici depuis dix ans. Par hasard, l'un des étudiants a traversé la rivière à la nage pour rejoindre le campus le jour de la grève. »\n\nPièges : *actually* = en fait ; *attend* = assister à ; *lecture* = cours magistral ; *sensible* = raisonnable ; *eventually* = finalement ; *realise* = se rendre compte ; *support* = soutenir ; *by chance* = par hasard ; *was said to be* = on disait qu'il était ; *has been working … for ten years* = présent + « depuis » en français ; *swam across* = traverser à la nage.\n\n**2. Thème proposé**\n*Currently (Nowadays), most people think that the information they read online is reliable, but three years ago, they did not check anything. It depends on their habits.*\n\nPièges : « actuellement » = *currently / nowadays* (pas *actually*) ; « les gens » = *people*, sans *the* ; *information* est indénombrable (verbe au singulier : *is*) ; « il y a trois ans » = *three years ago* + prétérit ; « dépend de » = *depends on*."}$exo$::jsonb),
  ('e3391291-e0ad-5741-b1c9-6210d756ffc8'::uuid, 1, 'redaction', $exo${"titre":"Les quatre temps d'un projet","consigne":"Réponds à chaque question en quelques lignes, avec le vocabulaire du cours.","enonce":"**Questions de cours**\n\n1. Cite dans l'ordre les quatre temps d'un projet plastique et dis en une phrase ce qui se passe à chacun.\n2. Quelle différence y a-t-il entre une intention et un thème ? Donne un exemple d'intention.\n3. Pourquoi une production sans question posée reste-t-elle « illustrative » ?","bareme":[{"critere":"Quatre temps dans l'ordre (formuler, chercher, réaliser, présenter) avec leur contenu","points":10},{"critere":"Intention = une phrase qui vise un effet, pas un thème, avec un exemple","points":5},{"critere":"Production illustrative : montre un sujet au lieu de le travailler","points":5}],"dureeMin":7,"corrige":"1. - **Formuler une intention** : une phrase qui dit ce que je veux produire comme effet.\n- **Chercher** : essais, matériaux, échelles, références ; on a **le droit de rater**.\n- **Réaliser** : les choix plastiques **répondent à l'intention** ou la **déplacent** (et le déplacement se note).\n- **Présenter** : l'**accrochage** et le **texte d'intention** font partie de l'œuvre.\n2. Un **thème** est un sujet (« la mémoire ») ; une **intention** est une **phrase** qui vise un effet : « je veux rendre visible la disparition », « je veux que le spectateur hésite ».\n3. Sans question posée, la production **montre un sujet au lieu de le travailler** : elle illustre. Une vraie problématique **admet plusieurs réponses plastiques** ; si une seule est possible, c'est une **consigne**, pas une question."}$exo$::jsonb),
  ('e3391291-e0ad-5741-b1c9-6210d756ffc8'::uuid, 2, 'redaction', $exo${"titre":"Le carnet de Maëlys","consigne":"Analyse la situation et conseille Maëlys en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Maëlys prépare la présentation de son projet sur le thème de l'absence. Elle veut retirer de son carnet de recherche trois essais ratés et ne garder que la version finale, « pour faire propre ». Elle a aussi repris une silhouette peinte par un artiste célèbre, mais n'ose pas le dire de peur qu'on l'accuse de copier.\n\n1. Explique à Maëlys pourquoi elle ne doit pas retirer ses essais ratés. Que prouve chaque type de contenu du carnet au jury ?\n2. Reprendre la silhouette d'un artiste, est-ce copier ? Présente les trois relations légitimes à une référence et dis laquelle correspond à son geste.\n3. Son thème, « l'absence », est-il une intention ? Propose-lui une formulation d'intention.","bareme":[{"critere":"Garder les essais : c'est le cheminement qui est noté ; un échec documenté vaut mieux qu'une réussite inexpliquée","points":4},{"critere":"Ce que prouvent croquis, essais datés, références annotées, notes d'intention","points":5},{"critere":"Citer, prolonger, contredire expliqués ; son geste relève de la citation, à assumer comme emprunt","points":7},{"critere":"Thème ≠ intention, formulation d'intention pertinente","points":4}],"dureeMin":12,"corrige":"1. Au lycée, c'est la **démarche** qui est évaluée : **un échec documenté vaut mieux qu'une réussite inexpliquée**. Le carnet prouve : **croquis et variantes** → que des **choix ont été écartés** ; **essais ratés, datés** → que la **recherche a eu lieu** ; **références annotées** → que le travail **se situe** ; **notes d'intention** → que la démarche est **consciente**.\n2. Non, situer son travail par rapport à un artiste n'est pas copier, c'est **se positionner**, à condition que la relation soit **consciente** :\n- **Citer** : reprendre un motif et l'**assumer comme emprunt** ;\n- **Prolonger** : poursuivre une recherche là où l'artiste l'a laissée ;\n- **Contredire** : reprendre le dispositif pour en **renverser le sens**.\nMaëlys **cite** : elle doit le dire et l'assumer.\n3. « L'absence » est un **thème**. Une intention est une phrase : par exemple « je veux que le spectateur ressente un manque devant une place vide » ou « je veux rendre visible la disparition »."}$exo$::jsonb),
  ('e3391291-e0ad-5741-b1c9-6210d756ffc8'::uuid, 3, 'redaction', $exo${"titre":"Défendre son projet devant un jury","consigne":"Rédige un texte organisé d'une vingtaine de lignes, comme si tu préparais l'oral de présentation d'un projet.","enonce":"**Sujet.** Tu as réalisé une installation à partir de l'intention : « je veux que le spectateur hésite entre entrer et rester dehors ». Au départ, tu pensais faire une peinture ; tes essais t'ont amené à construire un seuil avec des voilages.\n\n1. Explique en quoi ton intention pose une vraie problématique (et non une consigne).\n2. Montre comment ton carnet de recherche rend visible le passage de la peinture à l'installation, et pourquoi ce déplacement est valorisé.\n3. Choisis une référence (réelle ou décrite de façon générale) et précise ta relation à elle : citer, prolonger ou contredire.\n4. Explique pourquoi l'accrochage et le texte d'intention sont le « dernier acte plastique », et ce que signifie « défendre son travail ».","bareme":[{"critere":"Problématique justifiée : elle admet plusieurs réponses plastiques","points":4},{"critere":"Carnet : essais datés, variantes, choix écartés montrant le déplacement de l'intention","points":5},{"critere":"Relation à une référence nommée et justifiée","points":4},{"critere":"Présentation (accrochage, éclairage, ordre de lecture, texte) comme acte plastique","points":4},{"critere":"Défendre = expliciter les choix, pas justifier les manques","points":3}],"dureeMin":18,"corrige":"Éléments attendus :\n1. L'intention est une **phrase** qui vise un effet sur le spectateur. Elle pose une vraie **problématique** car elle **admet plusieurs réponses plastiques** (une peinture en trompe-l'œil, un passage étroit, un voilage, un jeu de lumière…). Si une seule réponse était possible, ce serait une **consigne**. Sans cette question, le travail serait **illustratif**.\n2. Le carnet montre la **phase de recherche** : croquis de la peinture, **essais ratés datés**, variantes d'échelle et de matériaux, photos du seuil. Ils prouvent que des **choix ont été écartés** et que la recherche a eu lieu. Pendant la réalisation, les choix plastiques **répondent à l'intention ou la déplacent** : ici, passer de la peinture à l'installation est un **déplacement**, et **le déplacement se note** — c'est le **cheminement** qui est évalué, pas la seule habileté.\n3. Toute référence pertinente est acceptée si la relation est **consciente** et justifiée : **citer** (reprendre un motif en l'assumant), **prolonger** (poursuivre la recherche d'un artiste) ou **contredire** (reprendre son dispositif pour en renverser le sens). Se situer n'est pas copier.\n4. **Accrochage, éclairage, ordre de lecture, texte d'intention** : la présentation est le **dernier acte plastique**, pas une formalité ; elle fait partie de l'œuvre (ici, placer le seuil pour que le spectateur doive choisir). **Défendre** son travail, c'est **expliciter ses choix** — jamais **justifier ses manques**."}$exo$::jsonb),
  ('420b6fbd-bdee-5f71-81f4-ace095f63dba'::uuid, 1, 'redaction', $exo${"titre":"Les quatre déplacements de l'art contemporain","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quelle question l'art contemporain a-t-il remplacée, et par laquelle ?\n2. Complète : l'œuvre passe de l'objet à l'…, de l'atelier au …, de l'objet au …, de l'unique au … . Donne pour chacun le mouvement ou la pratique qui correspond.\n3. Que signifie la phrase de Duchamp : « C'est le regardeur qui fait le tableau » ?","bareme":[{"critere":"De « est-ce beau ? » à « qu'est-ce que cela fait ? »","points":4},{"critere":"Quatre déplacements justes avec la pratique associée (art conceptuel, in situ/land art, performance, Pop art)","points":12},{"critere":"L'œuvre existe activée par l'interprétation ou la participation","points":4}],"dureeMin":7,"corrige":"1. On ne demande plus « **est-ce beau ?** » mais « **qu'est-ce que cela fait ?** ».\n2. - De l'objet à l'**idée** : l'**art conceptuel**, où le protocole vaut l'œuvre.\n- De l'atelier au **lieu** : l'**in situ** et le **land art**, où l'œuvre tient à son site.\n- De l'objet au **corps** : la **performance**, où l'œuvre est un temps vécu.\n- De l'unique au **reproductible** : le **Pop art** et la **sérigraphie**, où la copie n'est plus un défaut.\n3. Pour **Duchamp**, l'œuvre n'est pas complète sans celui qui la regarde : beaucoup d'œuvres contemporaines **n'existent qu'activées** — par une **interprétation**, une **participation** ou un **récit**."}$exo$::jsonb),
  ('420b6fbd-bdee-5f71-81f4-ace095f63dba'::uuid, 2, 'redaction', $exo${"titre":"Quatre artistes, quatre gestes","consigne":"Associe et explique, en t'appuyant sur le cours.","enonce":"**Document – Quatre descriptions (sans nom)**\n\n- **A.** Un artiste reproduit en série, par sérigraphie, la même image d'une célébrité.\n- **B.** Un couple d'artistes enveloppe un monument entier de toile pendant quelques jours.\n- **C.** Une artiste suit un inconnu dans la rue et raconte son enquête par des textes et des photos.\n- **D.** Un artiste réalise des œuvres qui dénoncent la censure dans son pays.\n\n1. Retrouve l'artiste (ou les artistes) correspondant à chaque description, selon le cours.\n2. Pour chacun, dis ce que son geste « déplace ».\n3. Le street art, né dans l'illégalité, est-il resté en dehors du marché ? Explique.","bareme":[{"critere":"Quatre attributions justes : Warhol, Christo et Jeanne-Claude, Sophie Calle, Ai Weiwei","points":8},{"critere":"Ce que chaque geste déplace (unicité, éphémère et public, artiste narratrice, prise de position)","points":8},{"critere":"Street art : passé de la rue au marché, l'illégalité devenue valeur","points":4}],"dureeMin":11,"corrige":"1. **A** : **Andy Warhol** ; **B** : **Christo et Jeanne-Claude** ; **C** : **Sophie Calle** ; **D** : **Ai Weiwei**.\n2. - **Warhol**, reproduction sérielle : il déplace l'**unicité de l'œuvre**.\n- **Christo et Jeanne-Claude**, emballage monumental : l'œuvre devient **éphémère et publique**.\n- **Sophie Calle**, récit et enquête : l'**artiste devient narratrice**.\n- **Ai Weiwei**, art politique : l'œuvre comme **prise de position**.\n3. **Non** : le street art est passé de **la rue au marché** ; **l'illégalité est devenue valeur**. Galeries, foires et musées construisent aussi socialement la valeur d'une œuvre."}$exo$::jsonb),
  ('420b6fbd-bdee-5f71-81f4-ace095f63dba'::uuid, 3, 'redaction', $exo${"titre":"« Mon petit frère pourrait le faire »","consigne":"Rédige une réponse argumentée et organisée d'une vingtaine de lignes, en t'appuyant sur des exemples précis du cours.","enonce":"**Situation (inventée).** Au musée, devant une œuvre faite d'objets du quotidien disposés au sol selon un protocole écrit, ton ami Nolan s'exclame : « Ce n'est même pas beau, mon petit frère pourrait le faire, et en plus ça coûte une fortune ! »\n\nRéponds à Nolan en montrant :\n1. que l'art contemporain a déplacé la question qu'on pose à une œuvre ;\n2. à quel déplacement appartient cette œuvre, et en quoi l'idée compte plus que l'habileté ;\n3. comment se construit la valeur d'une œuvre contemporaine ;\n4. quelle méthode adopter devant une œuvre qui déroute, et quel rôle y joue le regardeur.","bareme":[{"critere":"Question déplacée : de la beauté à ce que fait l'œuvre","points":4},{"critere":"Art conceptuel : l'idée prime sur l'objet, le protocole vaut l'œuvre, avec au moins un autre déplacement cité","points":5},{"critere":"Valeur construite aussi socialement : galeries, foires, biennales, musées","points":4},{"critere":"Méthode : demander ce que l'œuvre demande de faire ; Duchamp et le regardeur","points":5},{"critere":"Argumentation organisée qui répond à Nolan","points":2}],"dureeMin":18,"corrige":"Éléments attendus :\n1. Nolan juge avec la question « **est-ce beau ?** ». L'art contemporain l'a **déplacée** vers « **qu'est-ce que cela fait ?** » : l'œuvre ne cherche pas forcément la beauté ni l'habileté technique.\n2. Cette œuvre relève du passage **de l'objet à l'idée** : c'est l'**art conceptuel**, où **le protocole vaut l'œuvre**. Ce qui compte est l'idée et la décision de l'artiste, pas la difficulté de fabrication : « pouvoir le faire » n'est pas « l'avoir pensé ». On peut citer d'autres déplacements : vers le **lieu** (in situ, land art), le **corps** (performance), le **reproductible** (Warhol et le Pop art, où la copie n'est plus un défaut).\n3. Le prix n'est pas absurde si l'on comprend le circuit : **galeries, foires, biennales, musées** — la valeur d'une œuvre contemporaine se construit **aussi socialement**. Ignorer ce circuit condamne à trouver les prix absurdes ; le comprendre fait partie de la compréhension de l'œuvre (exemple du **street art**, passé de la rue au marché).\n4. Méthode : ne pas demander **ce que l'œuvre représente**, mais **ce qu'elle demande de faire**. Pour **Duchamp**, « **c'est le regardeur qui fait le tableau** » : beaucoup d'œuvres n'existent qu'**activées** par une interprétation, une participation ou un récit. Nolan, en réagissant, participe déjà à l'œuvre."}$exo$::jsonb),
  ('9e68668e-7efe-5003-8059-28838bf56736'::uuid, 1, 'redaction', $exo${"titre":"Pixel ou vecteur ?","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Comment une image matricielle est-elle décrite ? Et une image vectorielle ? Que se passe-t-il quand on les agrandit ?\n2. Donne un usage typique de chacune.\n3. Quels sont les deux sens du mot « résolution » ? En quelle unité mesure-t-on la finesse d'impression ?","bareme":[{"critere":"Grille de pixels / formules géométriques ; pixellisation / netteté conservée","points":8},{"critere":"Usages : photographie ou peinture numérique / logo, typographie, pictogramme","points":5},{"critere":"Résolution en pixels (dimensions) et en ppp/dpi (impression)","points":7}],"dureeMin":6,"corrige":"1. Une image **matricielle** (bitmap) est une **grille de pixels colorés** : agrandie, elle **se dégrade, se pixellise**. Une image **vectorielle** est décrite par des **formules géométriques** : agrandie, elle **reste nette, sans perte**.\n2. Matricielle : **photographie**, peinture numérique. Vectorielle : **logo**, typographie, pictogramme.\n3. La résolution se lit deux fois : en **pixels** (les dimensions de l'image) et en **ppp / dpi** (points par pouce, sa **finesse à l'impression**)."}$exo$::jsonb),
  ('9e68668e-7efe-5003-8059-28838bf56736'::uuid, 2, 'redaction', $exo${"titre":"Le bon format pour chaque usage","consigne":"Aide Ilyes à choisir ses formats en justifiant chaque choix avec le cours.","enonce":"**Situation (inventée).** Ilyes prépare l'affiche d'un festival de son lycée. Il doit produire :\n- **A.** le logo du festival, qui sera imprimé en petit sur les billets et en très grand sur une banderole ;\n- **B.** une photo du groupe de musique pour le site web ;\n- **C.** une image du chanteur détourée, à poser sur un fond coloré ;\n- **D.** un fichier de l'affiche finale en qualité maximale, à archiver et à envoyer à l'imprimeur.\n\n1. Pour chaque cas, choisis un format parmi JPEG, PNG, TIFF, SVG et justifie.\n2. Pour la photo du site, quel inconvénient présente le format choisi ?\n3. Pour poser le chanteur sur le fond, quels outils de montage Ilyes peut-il utiliser ?","bareme":[{"critere":"A SVG (vectoriel, net à toutes les tailles) justifié","points":4},{"critere":"B JPEG, C PNG (transparence), D TIFF justifiés","points":8},{"critere":"JPEG : compression avec perte d'information","points":4},{"critere":"Outils : calques, masques, détourage, fondus","points":4}],"dureeMin":10,"corrige":"1. - **A** : **SVG**, format **vectoriel** : le logo reste **net sans perte** du billet à la banderole (une image matricielle se pixelliserait).\n- **B** : **JPEG**, adapté à une **photo destinée au web** (fichier léger).\n- **C** : **PNG**, qui compresse **sans perte** et **garde la transparence** : idéal pour une **image détourée**.\n- **D** : **TIFF**, qui **conserve la qualité maximale** : **archivage** et **impression**.\n2. Le JPEG **compresse en perdant de l'information** : la qualité se dégrade, surtout si on l'enregistre plusieurs fois.\n3. Les **calques** (superposer et modifier les éléments indépendamment), les **masques**, le **détourage** et les **fondus**."}$exo$::jsonb),
  ('9e68668e-7efe-5003-8059-28838bf56736'::uuid, 3, 'redaction', $exo${"titre":"Une photo qui n'a jamais eu lieu","consigne":"Rédige une réponse argumentée et organisée d'une vingtaine de lignes, en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Une image circule sur les réseaux sociaux : on y voit une baleine nageant dans une rue inondée de Paris. Elle est parfaite, sans aucune trace visible de retouche. Des milliers de personnes la partagent, et personne ne sait qui l'a faite.\n\n1. Explique comment le montage numérique permet de produire une telle image (outils, notion d'image « sans référent réel »).\n2. Que devient la valeur de preuve de la photographie ? Une photographie numérique est-elle toujours une preuve fiable ?\n3. Explique la notion d'« aura » selon Walter Benjamin et montre comment le numérique pousse cette logique à l'extrême, à partir de l'exemple.\n4. Conclus : en quoi le numérique n'est-il « pas un pinceau de plus » ?","bareme":[{"critere":"Montage : calques, masques, détourage, fondus ; image sans référent réel, photographiquement parfaite","points":5},{"critere":"Valeur de preuve remise en question quand la retouche ne laisse plus de trace","points":4},{"critere":"Aura selon Benjamin (1935) : l'ici-et-maintenant perdu par la reproduction","points":4},{"critere":"Numérique extrême : copie parfaite, diffusion instantanée, auteur indéterminé, relié à l'exemple","points":4},{"critere":"Conclusion : le numérique change le statut de l'image (matière, copie, preuve)","points":3}],"dureeMin":18,"corrige":"Éléments attendus :\n1. Avec les **calques**, les **masques**, le **détourage** et les **fondus**, on combine plusieurs images (une baleine, une rue, de l'eau) en une seule. On obtient une image **sans référent réel** : une scène **qui n'a jamais eu lieu**, pourtant **photographiquement parfaite**.\n2. La photographie passait pour une **preuve** (« ça a eu lieu »). Quand **la retouche ne laisse plus de trace**, cette **valeur de preuve** est remise en question : une photographie numérique **n'est pas toujours une preuve fiable** ; il faut s'interroger sur sa source.\n3. **Walter Benjamin** l'anticipait dès **1935** : la **reproduction** fait perdre à l'œuvre son **« aura »**, son **ici-et-maintenant**. Le numérique pousse cette logique à l'extrême : **copie parfaite** (chaque partage est identique à l'original), **diffusion instantanée** (des milliers de partages), **auteur parfois indéterminé** (personne ne sait qui l'a faite).\n4. Le numérique n'est **pas un pinceau de plus** : il change le **statut** de l'image — sa **matière** (pixels ou vecteurs), sa **copie** (sans perte ni original) et sa **preuve** (plus garantie)."}$exo$::jsonb),
  ('db450763-6653-5ad5-bbf3-40a5d0ae5fde'::uuid, 1, 'application', $exo${"titre":"Trier les voies et lire un signe","consigne":"Réponds à chaque question par une ou deux phrases précises, en utilisant le vocabulaire du cours.","enonce":"**Données.** Voici cinq voies ou réactions du métabolisme cellulaire :\n\n- la glycolyse ;\n- la glycogénogenèse ;\n- la lipolyse ;\n- le cycle de Calvin ;\n- l’hydrolyse de l’ATP : ATP + H₂O → ADP + Pi, ΔrG’° ≈ −30,5 kJ·mol⁻¹.\n\n1. Définis le **catabolisme** et l’**anabolisme**, puis classe les quatre premières voies dans l’une ou l’autre catégorie.\n2. Une réaction a un ΔrG’° de +22 kJ·mol⁻¹. Est-elle exergonique ou endergonique ? Peut-elle se dérouler seule dans le sens écrit ?\n3. Explique en deux phrases pourquoi l’on dit que l’ATP « fait la navette » entre catabolisme et anabolisme.","bareme":[{"critere":"Définitions du catabolisme et de l’anabolisme, et classement juste des quatre voies","points":9},{"critere":"Réaction à +22 kJ·mol⁻¹ reconnue endergonique, impossible seule dans ce sens","points":5},{"critere":"Rôle de navette de l’ATP : produit par le catabolisme, consommé par l’anabolisme","points":6}],"dureeMin":7,"corrige":"1. Le **catabolisme** regroupe les voies qui **dégradent** des molécules et **libèrent** de l’énergie ; l’**anabolisme** regroupe les voies qui **synthétisent** des molécules et **consomment** de l’énergie.\n- Catabolisme : **glycolyse**, **lipolyse**.\n- Anabolisme : **glycogénogenèse** (synthèse de glycogène), **cycle de Calvin** (fixation du CO₂).\n\n2. ΔrG’° = +22 kJ·mol⁻¹ > 0 : la réaction est **endergonique**. Elle est **impossible seule** dans le sens écrit (en conditions standard) ; elle ne peut avoir lieu que **couplée** à une réaction exergonique.\n\n3. Le **catabolisme produit de l’ATP** (à partir d’ADP et Pi) grâce à l’énergie qu’il libère ; l’**anabolisme consomme cet ATP**, dont l’hydrolyse très exergonique (≈ −30,5 kJ·mol⁻¹) permet de réaliser des réactions endergoniques par couplage. L’ATP transporte donc l’énergie d’une voie à l’autre : c’est une molécule énergétique **intermédiaire**."}$exo$::jsonb),
  ('db450763-6653-5ad5-bbf3-40a5d0ae5fde'::uuid, 2, 'application', $exo${"titre":"Deux réactions rendues possibles par l’ATP","consigne":"Réponds en détaillant tes calculs (avec les unités) et en justifiant chaque conclusion.","enonce":"**Situation.** Dans une cellule hépatique, on s’intéresse à deux réactions.\n\n| Réaction | ΔrG’° |\n| (1) fructose-6-phosphate + Pi → fructose-1,6-bisphosphate + H₂O | +16,3 kJ·mol⁻¹ |\n| (2) glutamate + NH₄⁺ → glutamine + H₂O | +14,2 kJ·mol⁻¹ |\n| (3) ATP + H₂O → ADP + Pi | −30,5 kJ·mol⁻¹ |\n\nLa réaction (1) est une étape de la glycolyse ; la réaction (2) fabrique un acide aminé.\n\n1. Les réactions (1) et (2) peuvent-elles se dérouler seules dans le sens écrit ? Justifie.\n2. Écris l’équation de la réaction couplée (1) + (3) en simplifiant, puis calcule son ΔrG’°. Conclus.\n3. Fais de même pour (2) + (3).\n4. Indique, pour chacune des réactions (1) et (2), si elle appartient au catabolisme ou à l’anabolisme.","bareme":[{"critere":"Réactions (1) et (2) reconnues endergoniques (ΔrG’° > 0), impossibles seules","points":4},{"critere":"Équation couplée (1)+(3) simplifiée et ΔrG’° = −14,2 kJ·mol⁻¹, conclusion","points":6},{"critere":"Équation couplée (2)+(3) simplifiée et ΔrG’° = −16,3 kJ·mol⁻¹, conclusion","points":6},{"critere":"Classement : (1) catabolisme (glycolyse), (2) anabolisme (synthèse)","points":4}],"dureeMin":11,"corrige":"1. Les deux ΔrG’° sont **positifs** (+16,3 et +14,2 kJ·mol⁻¹) : les réactions sont **endergoniques**, donc **impossibles seules** dans le sens écrit.\n\n2. On additionne (1) et (3) : Pi et H₂O apparaissent des deux côtés et se simplifient.\n**fructose-6-phosphate + ATP → fructose-1,6-bisphosphate + ADP**\nΔrG’° = +16,3 + (−30,5) = **−14,2 kJ·mol⁻¹**. La somme est négative : la réaction couplée est **exergonique, donc spontanée**.\n\n3. (2) + (3) : **glutamate + NH₄⁺ + ATP → glutamine + ADP + Pi** (une molécule d’eau se simplifie).\nΔrG’° = +14,2 + (−30,5) = **−16,3 kJ·mol⁻¹** < 0 : la réaction couplée est **spontanée**.\n\n4. (1) est une étape de la **glycolyse**, qui dégrade le glucose : **catabolisme**. (2) **synthétise** un acide aminé : **anabolisme**.\nRemarque attendue : dans les deux cas, c’est le **couplage** avec l’hydrolyse de l’ATP qui rend la réaction possible."}$exo$::jsonb),
  ('db450763-6653-5ad5-bbf3-40a5d0ae5fde'::uuid, 3, 'application', $exo${"titre":"Des électrons du NADH jusqu’au dioxygène","consigne":"Exploite les données pour répondre. Chaque calcul doit être posé avec ses unités, chaque conclusion justifiée.","enonce":"**Données.**\n\n| Couple | E’° (V) |\n| NAD⁺ / NADH | −0,32 |\n| O₂ / H₂O | +0,82 |\n\n- Demi-équation du couple NAD⁺/NADH : NAD⁺ + 2 e⁻ + H⁺ → NADH\n- Demi-équation du couple O₂/H₂O : ½ O₂ + 2 e⁻ + 2 H⁺ → H₂O\n- ΔrG’° = −n × F × ΔE’°, avec F = 96 500 C·mol⁻¹ et ΔE’° = E’° accepteur − E’° donneur.\n- Synthèse de l’ATP : ADP + Pi → ATP + H₂O, ΔrG’° = +30,5 kJ·mol⁻¹.\n\n1. Dans quel sens les électrons circulent-ils spontanément entre ces deux couples ? Identifie le donneur et l’accepteur.\n2. Écris l’équation-bilan de l’oxydation du NADH par le dioxygène à partir des deux demi-équations.\n3. Calcule ΔE’° puis ΔrG’° de cette réaction (en kJ·mol⁻¹). Qualifie la réaction.\n4. En supposant toute cette énergie utilisable, combien de molécules d’ATP pourrait-on au maximum synthétiser par NADH oxydé ? Justifie par le couplage.\n5. Un élève affirme : « Une réaction de ΔrG’° positif ne se produit jamais dans une cellule. » Discute cette affirmation.","bareme":[{"critere":"Sens des électrons du E’° le plus bas vers le plus haut : NADH donneur, O₂ accepteur","points":3},{"critere":"Équation-bilan juste : NADH + H⁺ + ½ O₂ → NAD⁺ + H₂O, électrons égalisés","points":4},{"critere":"ΔE’° = 1,14 V et ΔrG’° ≈ −220 kJ·mol⁻¹, réaction exergonique","points":5},{"critere":"Nombre maximal d’ATP ≈ 7 justifié par une somme de ΔrG’° restant négative","points":4},{"critere":"Discussion ΔrG’° / ΔrG : conditions réelles et couplage","points":4}],"dureeMin":18,"corrige":"1. Les électrons vont spontanément du couple au E’° le plus **bas** (NAD⁺/NADH, −0,32 V) vers le couple au E’° le plus **haut** (O₂/H₂O, +0,82 V). **Donneur : NADH** (il est oxydé) ; **accepteur : O₂** (il est réduit en eau).\n\n2. On écrit l’oxydation du NADH (demi-équation inversée) : NADH → NAD⁺ + 2 e⁻ + H⁺, et la réduction du dioxygène : ½ O₂ + 2 e⁻ + 2 H⁺ → H₂O. Les électrons sont égalisés (2 de chaque côté). En additionnant et en simplifiant un H⁺ :\n**NADH + H⁺ + ½ O₂ → NAD⁺ + H₂O**\n\n3. ΔE’° = E’° accepteur − E’° donneur = 0,82 − (−0,32) = **1,14 V**.\nΔrG’° = −n × F × ΔE’° = −2 × 96 500 × 1,14 = −220 020 J·mol⁻¹ ≈ **−220 kJ·mol⁻¹**.\nΔrG’° < 0 : la réaction est **exergonique** (spontanée, et très énergétique).\n\n4. Coupler cette oxydation à k synthèses d’ATP donne ΔrG’° = −220 + k × 30,5. Elle reste spontanée tant que la somme est négative : k < 220 / 30,5 ≈ 7,2. On pourrait donc synthétiser **au maximum 7 ATP** par NADH (valeur théorique ; la cellule en produit moins, une partie de l’énergie étant perdue).\n\n5. L’affirmation est **fausse**. ΔrG’° est calculé en **conditions standard** ; la cellule, elle, fonctionne en conditions réelles (ΔrG). Si elle maintient ses **produits à très faible concentration**, une réaction à ΔrG’° positif peut devenir spontanée. De plus, une réaction endergonique peut se produire si elle est **couplée** à une réaction exergonique (hydrolyse de l’ATP), la somme des ΔrG’° devenant négative."}$exo$::jsonb),
  ('58cd43b9-deac-5cc7-aab6-0a4a2b184a54'::uuid, 1, 'application', $exo${"titre":"Respirer ou fermenter : l’essentiel","consigne":"Réponds par des phrases courtes et précises.","enonce":"1. Où se déroule la **glycolyse** ? Donne son bilan net en ATP et en NADH pour une molécule de glucose.\n2. Quel est l’**accepteur final d’électrons** de la respiration aérobie ? En quoi est-il transformé ?\n3. Cite les produits de la fermentation **lactique** et de la fermentation **alcoolique**, avec un exemple d’utilisation de chacune.\n4. Donne le nombre approximatif d’ATP produits par glucose en respiration et en fermentation.","bareme":[{"critere":"Glycolyse dans le cytoplasme, bilan 2 ATP et 2 NADH","points":6},{"critere":"Dioxygène accepteur final, réduit en eau","points":4},{"critere":"Produits des deux fermentations et un usage pour chacune","points":6},{"critere":"Environ 30 ATP en respiration contre 2 en fermentation","points":4}],"dureeMin":7,"corrige":"1. La glycolyse a lieu dans le **cytoplasme**. Un glucose (6 C) donne deux pyruvates (3 C) avec un bilan net de **2 ATP** et **2 NADH** (+ 2 H⁺).\n\n2. L’accepteur final est le **dioxygène** O₂, qui est **réduit en eau** en fin de chaîne respiratoire.\n\n3. - Fermentation **lactique** : **lactate** (2 par glucose) ; utilisée pour les **yaourts, fromages**.\n- Fermentation **alcoolique** : **éthanol + CO₂** ; utilisée pour le **pain, la bière, le vin** ou le bioéthanol.\n\n4. Respiration : **environ 30 (30 à 32) ATP** par glucose ; fermentation : **2 ATP** par glucose."}$exo$::jsonb),
  ('58cd43b9-deac-5cc7-aab6-0a4a2b184a54'::uuid, 2, 'application', $exo${"titre":"Le bioréacteur de Maëlys","consigne":"Réponds en posant tes calculs et en justifiant tes choix.","enonce":"**Situation.** Maëlys, technicienne dans une entreprise de biotechnologie, dispose d’un bioréacteur de levures *Saccharomyces cerevisiae* auquel elle fournit **0,5 mol de glucose**. On retient : environ **30 ATP** par glucose en respiration, **2 ATP** en fermentation alcoolique.\n\n1. En aérobiose, calcule la quantité d’ATP produite et la quantité de CO₂ dégagée (équation : C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O).\n2. En anaérobiose, calcule les quantités d’ATP, d’éthanol et de CO₂ produites.\n3. L’entreprise veut d’une part produire de la **levure de boulangerie** (biomasse), d’autre part du **bioéthanol**. Quelles conditions Maëlys doit-elle choisir dans chaque cas ? Justifie.\n4. Explique pourquoi la fermentation rapporte si peu d’ATP.","bareme":[{"critere":"Aérobiose : 15 mol d’ATP et 3 mol de CO₂","points":5},{"critere":"Anaérobiose : 1 mol d’ATP, 1 mol d’éthanol, 1 mol de CO₂","points":5},{"critere":"Choix justifiés : aérer pour la biomasse, couper l’air pour l’éthanol","points":5},{"critere":"Oxydation partielle : l’éthanol garde de l’énergie, ATP par le substrat seulement","points":5}],"dureeMin":11,"corrige":"1. Aérobiose : ATP = 0,5 × 30 = **15 mol d’ATP** ; CO₂ = 0,5 × 6 = **3 mol de CO₂**.\n\n2. Anaérobiose (fermentation alcoolique, 2 éthanol + 2 CO₂ + 2 ATP par glucose) : ATP = 0,5 × 2 = **1 mol** ; éthanol = 0,5 × 2 = **1 mol** ; CO₂ = 0,5 × 2 = **1 mol**.\n\n3. - Pour la **biomasse** (levure de boulangerie), on **aère** : la respiration fournit environ 15 fois plus d’ATP par glucose (30 contre 2), énergie qui permet la croissance et la multiplication des levures.\n- Pour le **bioéthanol**, on **coupe l’air** : sans dioxygène, les levures fermentent et produisent de l’éthanol.\n\n4. En fermentation, l’oxydation du glucose est **partielle** : le produit final (éthanol) **garde de l’énergie**. L’ATP n’est formé que par **phosphorylation au niveau du substrat** pendant la glycolyse (2 ATP) ; les dernières étapes servent seulement à **réoxyder le NADH en NAD⁺** pour que la glycolyse continue, sans produire d’ATP."}$exo$::jsonb),
  ('58cd43b9-deac-5cc7-aab6-0a4a2b184a54'::uuid, 3, 'application', $exo${"titre":"Une suspension de levures qui change de régime","consigne":"Analyse le document, puis réponds en mobilisant le cours. Justifie chaque interprétation.","enonce":"**Document.** Une suspension de levures est placée dans un flacon fermé contenant du glucose. On mesure la concentration en dioxygène dissous et en éthanol.\n\n| Temps (min) | 0 | 5 | 10 | 15 | 20 | 25 |\n| O₂ dissous (mg·L⁻¹) | 8,0 | 5,2 | 2,1 | 0 | 0 | 0 |\n| Éthanol (mmol·L⁻¹) | 0 | 0 | 0 | 1,5 | 4,2 | 7,0 |\n\n1. Décris les deux phases visibles dans le document et nomme le métabolisme dominant dans chacune.\n2. Dans la première phase, décris le trajet des électrons et explique comment l’ATP est principalement produit (localisation, acteurs, nom du mécanisme).\n3. Dans la seconde phase, explique pourquoi la levure doit réduire l’acétaldéhyde (dérivé du pyruvate) en éthanol, alors que cette étape ne produit aucun ATP.\n4. Pour obtenir la même quantité d’ATP, combien de fois plus de glucose la levure consomme-t-elle en fermentation qu’en respiration ? Justifie.\n5. Un camarade conclut : « Dès qu’il n’y a plus de dioxygène, toute cellule fermente. » Nuance cette phrase.","bareme":[{"critere":"Deux phases décrites avec valeurs : respiration tant qu’il y a O₂, fermentation alcoolique ensuite","points":4},{"critere":"Chaîne respiratoire, gradient de protons, ATP synthase, couplage chimio-osmotique","points":5},{"critere":"Réoxydation du NADH en NAD⁺ indispensable à la poursuite de la glycolyse","points":4},{"critere":"Facteur 15 (30/2) justifié","points":3},{"critere":"Respiration anaérobie à nitrate : anaérobie ne veut pas dire fermentation","points":4}],"dureeMin":18,"corrige":"1. **De 0 à 15 min**, le dioxygène baisse de 8,0 à 0 mg·L⁻¹ et aucun éthanol n’apparaît : les levures **respirent**. **À partir de 15 min**, O₂ est épuisé et l’éthanol s’accumule (1,5 puis 7,0 mmol·L⁻¹) : elles pratiquent la **fermentation alcoolique**.\n\n2. Après la glycolyse (cytoplasme), le **cycle de Krebs** (matrice mitochondriale) achève l’oxydation : le carbone part en CO₂ et les électrons chargent **NADH et FADH₂**. Ces électrons descendent la **chaîne respiratoire** (membrane interne mitochondriale), transporteurs classés par E’° croissant, jusqu’à l’**accepteur final O₂**, réduit en eau. L’énergie libérée **pompe des protons** vers l’espace intermembranaire (gradient électrochimique) ; leur reflux par l’**ATP synthase** fabrique l’ATP : c’est le **couplage chimio-osmotique**, ou **phosphorylation oxydative**.\n\n3. Sans accepteur final externe, le NADH formé par la glycolyse ne peut plus être réoxydé par la chaîne respiratoire. Or la glycolyse a besoin de **NAD⁺**. En réduisant l’acétaldéhyde en éthanol, la levure **réoxyde le NADH en NAD⁺** : la glycolyse continue et fournit ses 2 ATP. La fermentation est une voie de **régénération des coenzymes**.\n\n4. Respiration : environ 30 ATP par glucose ; fermentation : 2 ATP. Pour la même quantité d’ATP, il faut 30 / 2 = **15 fois plus de glucose** en fermentation.\n\n5. C’est faux en général. Certaines bactéries réalisent une **respiration anaérobie** : elles utilisent le **nitrate** comme accepteur final (nitrate réductase), avec une chaîne respiratoire. **Anaérobie ne veut donc pas dire fermentation** ; ce qui distingue les deux, c’est l’existence d’un accepteur final externe."}$exo$::jsonb),
  ('e0e845b7-69a0-593a-b5bb-7dab619a02a8'::uuid, 1, 'application', $exo${"titre":"Trois questions pour nommer un type trophique","consigne":"Réponds à chaque question en justifiant par les trois critères du cours.","enonce":"**Données.** On décrit trois organismes.\n\n- **A** : une algue verte qui utilise la lumière, prend ses électrons dans l’eau et fixe le CO₂.\n- **B** : une bactérie intestinale qui oxyde du glucose pour obtenir son énergie et ses électrons, et fabrique sa matière à partir de molécules organiques.\n- **C** : une bactérie du sol qui tire son énergie de l’oxydation de l’ion ammonium NH₄⁺ (composé minéral), qui lui fournit aussi ses électrons, et qui fixe le CO₂.\n\n1. Rappelle les trois questions qui permettent de décrire un type trophique, avec les préfixes correspondants.\n2. Donne le type trophique complet de A, B et C.\n3. Lequel de ces organismes peut se cultiver sur un milieu sans aucune source organique de carbone ? Justifie.","bareme":[{"critere":"Trois questions et préfixes associés (photo/chimio, litho/organo, auto/hétéro)","points":6},{"critere":"Types trophiques justes : A photolithoautotrophe, B chimioorganohétérotrophe, C chimiolithoautotrophe","points":9},{"critere":"Culture sans carbone organique : organismes autotrophes (A et C) justifiés","points":5}],"dureeMin":8,"corrige":"1. - **Source d’énergie** : photo- (lumière) / chimio- (réactions chimiques).\n- **Source d’électrons** : litho- (composé minéral) / organo- (molécule organique).\n- **Source de carbone** : auto- (CO₂) / hétéro- (matière organique).\n\n2. - **A** : lumière, électrons de l’eau (minéral), CO₂ → **photolithoautotrophe**.\n- **B** : oxydation du glucose, électrons organiques, carbone organique → **chimioorganohétérotrophe**.\n- **C** : oxydation de NH₄⁺, électrons minéraux, CO₂ → **chimiolithoautotrophe** (c’est une bactérie nitrifiante).\n\n3. Les organismes **autotrophes** tirent leur carbone du CO₂ : **A et C** peuvent se cultiver sans source organique de carbone (C à condition de lui fournir NH₄⁺, A à condition de l’éclairer). B, hétérotrophe, a besoin de matière organique."}$exo$::jsonb),
  ('e0e845b7-69a0-593a-b5bb-7dab619a02a8'::uuid, 2, 'application', $exo${"titre":"Dans le chloroplaste de la feuille de basilic","consigne":"Réponds en t’appuyant sur le cours, avec des phrases précises.","enonce":"**Situation.** Enzo cultive du basilic sous une lampe dans sa chambre. Il se demande ce qui se passe dans ses feuilles.\n\n1. Nomme les deux étapes de la photosynthèse. Pour chacune, précise sa localisation dans le chloroplaste, ses entrées et ses sorties.\n2. D’où provient le dioxygène libéré par la feuille ? Justifie à l’aide du rôle de l’eau.\n3. Enzo éteint la lampe. Explique pourquoi le cycle de Calvin, qui n’utilise pas directement la lumière, finit lui aussi par s’arrêter.\n4. Donne un point commun entre la chaîne photosynthétique et la chaîne respiratoire mitochondriale, et la différence essentielle entre les deux.","bareme":[{"critere":"Deux étapes avec localisation, entrées et sorties justes","points":7},{"critere":"O₂ issu de l’oxydation de l’eau qui cède ses électrons","points":4},{"critere":"Arrêt du cycle de Calvin faute de NADPH et d’ATP fournis par la chaîne photosynthétique","points":5},{"critere":"Point commun (gradient de protons, ATP synthase) et différence (source d’énergie)","points":4}],"dureeMin":11,"corrige":"1. - **Chaîne photosynthétique**, dans la **membrane des thylakoïdes** : entrées = lumière, H₂O, NADP⁺, ADP (+ Pi) ; sorties = **O₂, NADPH, ATP**.\n- **Cycle de Calvin**, dans le **stroma** : entrées = **CO₂, NADPH, ATP** ; sortie = **glycéraldéhyde 3-phosphate**, précurseur d’oses.\n\n2. La lumière excite les photosystèmes, dont les électrons descendent une chaîne de transporteurs jusqu’au NADP⁺. Ces électrons sont remplacés par ceux de l’**eau**, qui est **oxydée** : c’est cette oxydation qui libère le **dioxygène**. Le O₂ vient donc de l’eau.\n\n3. Sans lumière, la chaîne photosynthétique s’arrête : elle ne produit plus de **NADPH ni d’ATP**. Or le cycle de Calvin a besoin de ces deux molécules pour **fixer le CO₂**. Une fois les réserves épuisées, il s’arrête lui aussi.\n\n4. Point commun : dans les deux cas, un **gradient de protons** fait tourner une **ATP synthase** (couplage chimio-osmotique), après le passage d’électrons dans une chaîne de transporteurs. Différence : la **source d’énergie** — la **lumière** pour la photosynthèse, l’**oxydation d’une molécule** pour la respiration."}$exo$::jsonb),
  ('e0e845b7-69a0-593a-b5bb-7dab619a02a8'::uuid, 3, 'application', $exo${"titre":"L’aquarium neuf de Rayan","consigne":"Analyse le document et réponds en mobilisant le cours sur le cycle de l’azote et les types trophiques.","enonce":"**Situation.** Rayan met en eau un aquarium neuf avec quelques poissons. Il mesure chaque semaine l’azote dissous avec des bandelettes.\n\n| Semaine | 1 | 2 | 3 | 4 | 5 | 6 |\n| NH₄⁺ (mg·L⁻¹) | 1,5 | 3,0 | 1,0 | 0,2 | 0 | 0 |\n| NO₂⁻ (mg·L⁻¹) | 0 | 0,5 | 2,5 | 1,5 | 0,3 | 0 |\n| NO₃⁻ (mg·L⁻¹) | 0 | 0 | 5 | 15 | 25 | 30 |\n\nLes déjections des poissons et les restes de nourriture sont des matières organiques azotées.\n\n1. D’où vient l’ammonium des semaines 1 et 2 ? Nomme cette transformation et précise si elle va de l’organique vers le minéral ou l’inverse.\n2. Décris et nomme la transformation qui se déroule des semaines 2 à 6. Écris-la sous forme de chaîne.\n3. Les bactéries responsables de cette transformation sont chimiolithoautotrophes et aérobies. Explique chacun des termes, puis indique une précaution à prendre pour qu’elles se développent dans le filtre.\n4. Rayan ajoute des plantes, qui consomment les nitrates. Nomme ce processus et explique en quoi il s’oppose à la transformation de la question 1.\n5. Dans la vase sans oxygène du fond, certaines bactéries transforment NO₃⁻ en N₂. Nomme ce processus et indique à quel type de métabolisme énergétique il correspond.","bareme":[{"critere":"Ammonification (minéralisation) de la matière organique azotée, organique vers minéral","points":4},{"critere":"Nitrification NH₄⁺ → NO₂⁻ → NO₃⁻ décrite à partir des données","points":4},{"critere":"Termes chimio, litho, auto et aérobie expliqués, précaution (aération) justifiée","points":5},{"critere":"Assimilation par les plantes, sens contraire de la minéralisation","points":3},{"critere":"Dénitrification, respiration anaérobie qui rend l’azote à l’atmosphère","points":4}],"dureeMin":18,"corrige":"1. L’ammonium provient de la dégradation des **déjections et restes de nourriture**, matières organiques azotées : c’est l’**ammonification**, une **minéralisation** (de l’**organique vers le minéral**). NH₄⁺ monte jusqu’à 3,0 mg·L⁻¹ en semaine 2.\n\n2. À partir de la semaine 2, NH₄⁺ baisse (3,0 → 0) tandis que les **nitrites** apparaissent (pic de 2,5 mg·L⁻¹ en semaine 3) puis baissent à leur tour, pendant que les **nitrates** s’accumulent (jusqu’à 30 mg·L⁻¹). C’est la **nitrification** :\n**NH₄⁺ → NO₂⁻ → NO₃⁻**\n\n3. - **Chimio-** : leur énergie vient de réactions chimiques (oxydation de NH₄⁺ ou NO₂⁻).\n- **Litho-** : leurs électrons viennent d’un composé minéral.\n- **Autotrophe** : leur carbone vient du CO₂.\n- **Aérobie** : elles ont besoin de dioxygène.\nPrécaution : **aérer / oxygéner** l’eau du filtre (pompe, bulleur), sans quoi elles ne se développent pas. On peut aussi ensemencer le filtre avec des bactéries nitrifiantes pour raccourcir le démarrage.\n\n4. Les plantes réalisent l’**assimilation** : elles transforment l’azote **minéral** (NO₃⁻) en **matière organique**. C’est le **sens contraire** de la minéralisation, qui transforme l’organique en minéral.\n\n5. C’est la **dénitrification** (NO₃⁻ → N₂) : une **respiration anaérobie** dans laquelle le nitrate sert d’accepteur final d’électrons. Elle **rend l’azote à l’atmosphère** sous forme de diazote."}$exo$::jsonb),
  ('d8a92fb3-4576-57b0-a742-24749249c272'::uuid, 1, 'application', $exo${"titre":"Portrait d’un catalyseur biologique","consigne":"Réponds à chaque question par une ou deux phrases, avec le vocabulaire exact du cours.","enonce":"1. Donne deux différences entre la catalyse chimique et la catalyse enzymatique.\n2. Une enzyme n’agit que sur le glucose et ne catalyse que sa phosphorylation. Nomme les deux spécificités illustrées.\n3. Qu’est-ce que le **site actif** ? De quoi dépend sa forme ?\n4. Le pepsinogène devient pepsine dans l’estomac. Comment appelle-t-on le pepsinogène ? Donne un autre exemple.","bareme":[{"critere":"Deux différences justes (conditions douces, spécificité)","points":5},{"critere":"Spécificité de substrat et spécificité de réaction reconnues","points":5},{"critere":"Site actif défini, forme liée à la structure tridimensionnelle de la protéine","points":5},{"critere":"Proenzyme, forme inactive ; exemple du trypsinogène","points":5}],"dureeMin":7,"corrige":"1. La catalyse enzymatique se fait en **conditions douces** (37 °C, pH proche de 7), alors que la catalyse chimique demande souvent des conditions dures (chaleur, pression). L’enzyme est **spécifique** du substrat et de la réaction, le catalyseur chimique l’est peu.\n\n2. N’agir que sur le glucose : **spécificité de substrat**. Ne catalyser que la phosphorylation : **spécificité de réaction**.\n\n3. Le **site actif** est la poche de l’enzyme où se **fixe le substrat** (formation du complexe ES) et où la réaction a lieu. Sa forme dépend de la **structure tridimensionnelle** de la protéine.\n\n4. Le pepsinogène est une **proenzyme** : forme **inactive** synthétisée par la cellule, activée ensuite (ici dans l’estomac acide). Autre exemple : le **trypsinogène**, qui devient **trypsine** dans l’intestin."}$exo$::jsonb),
  ('d8a92fb3-4576-57b0-a742-24749249c272'::uuid, 2, 'application', $exo${"titre":"Mesurer une vitesse initiale au laboratoire","consigne":"Exploite les mesures, pose tes calculs avec les unités et justifie tes réponses.","enonce":"**Situation.** Inès suit l’action d’une enzyme à 37 °C : elle dose le produit P formé au cours du temps.\n\n| t (min) | 0 | 1 | 2 | 3 | 4 | 6 | 10 |\n| [P] (µmol·L⁻¹) | 0 | 12 | 24 | 36 | 46 | 58 | 66 |\n\n1. Sur quel intervalle la courbe [P] = f(t) est-elle une droite ? Calcule la **vitesse initiale** v₀.\n2. Pourquoi la vitesse diminue-t-elle ensuite ? Pourquoi mesure-t-on toujours v₀ ?\n3. Inès place un tube d’enzyme 1 h à 4 °C, un autre 1 h à 80 °C, puis ramène les deux à 37 °C. Prévois, en justifiant, l’activité de chaque tube.","bareme":[{"critere":"Partie linéaire de 0 à 3 min identifiée, v₀ = 12 µmol·L⁻¹·min⁻¹","points":7},{"critere":"Baisse de vitesse expliquée (substrat consommé, produit accumulé) et intérêt de v₀","points":6},{"critere":"4 °C : activité retrouvée ; 80 °C : enzyme dénaturée, activité perdue","points":7}],"dureeMin":10,"corrige":"1. De **0 à 3 min**, [P] augmente de 12 µmol·L⁻¹ chaque minute : la courbe est une droite. Au-delà, l’augmentation ralentit (10 puis 6 puis 2 µmol·L⁻¹·min⁻¹ en moyenne).\nv₀ = pente = 36 / 3 = **12 µmol·L⁻¹·min⁻¹**.\n\n2. La vitesse diminue car le **substrat est consommé** et le **produit s’accumule**. On mesure toujours v₀ car c’est la **seule vitesse qui dépend clairement des conditions de départ** (concentrations, température, pH choisis).\n\n3. - Tube à **4 °C** : le froid **ralentit** l’enzyme sans la détruire ; ramenée à 37 °C, elle **retrouve son activité**.\n- Tube à **80 °C** : au-delà de la température optimale, la protéine se **dénature** (perte de sa structure tridimensionnelle, donc du site actif), de façon souvent **irréversible** : l’activité reste **nulle ou très faible** à 37 °C."}$exo$::jsonb),
  ('d8a92fb3-4576-57b0-a742-24749249c272'::uuid, 3, 'application', $exo${"titre":"Deux enzymes pour un même substrat","consigne":"Exploite les données et justifie chaque conclusion à l’aide des notions du cours.","enonce":"**Document 1.** Vitesse initiale v₀ (µmol·min⁻¹) de deux enzymes A et B, en quantité fixe, agissant sur le même substrat S.\n\n| [S] (mmol·L⁻¹) | 0,05 | 0,1 | 0,2 | 0,5 | 1 | 2 | 5 | 10 | 50 |\n| v₀ enzyme A | 16 | 27 | 40 | 57 | 67 | 73 | 77 | 78 | 80 |\n| v₀ enzyme B | 2 | 4 | 7 | 16 | 27 | 40 | 57 | 67 | 77 |\n\nLes deux courbes tendent vers le même plateau, Vmax = 80 µmol·min⁻¹.\n\n**Document 2.** Dans une voie métabolique, S₀ → S₁ → S₂ → P, catalysée par E1, E2 et E3, le produit final P se fixe sur E1 et diminue son activité.\n\n1. Explique pourquoi v₀ plafonne quand [S] devient grand.\n2. Détermine Km pour chaque enzyme. Laquelle a la plus grande affinité pour S ? Justifie.\n3. Pour mesurer Vmax de B, quelle concentration minimale de substrat choisir ? Justifie.\n4. On ajoute à A une molécule analogue structural de S. Explique son mode d’action.\n5. Nomme et explique la régulation du document 2 ; montre son intérêt pour la cellule.","bareme":[{"critere":"Plateau expliqué par la saturation des sites actifs","points":3},{"critere":"Km A = 0,2 et Km B = 2 mmol·L⁻¹, affinité plus grande pour A justifiée","points":6},{"critere":"Substrat saturant d’au moins 20 mmol·L⁻¹ (10 × Km) pour B","points":3},{"critere":"Inhibiteur analogue structural en compétition pour le site actif","points":4},{"critere":"Rétro-inhibition de E1 par P, boucle de régulation et intérêt","points":4}],"dureeMin":18,"corrige":"1. L’enzyme est en quantité fixe : quand [S] est grande, **tous les sites actifs sont occupés**, l’enzyme est **saturée**. Ajouter du substrat ne peut plus accélérer la réaction : v₀ atteint **Vmax**.\n\n2. Km est la concentration en substrat pour laquelle v₀ = Vmax / 2 = 80 / 2 = **40 µmol·min⁻¹**.\n- Enzyme A : v₀ = 40 pour [S] = 0,2 mmol·L⁻¹ → **Km(A) = 0,2 mmol·L⁻¹**.\n- Enzyme B : v₀ = 40 pour [S] = 2 mmol·L⁻¹ → **Km(B) = 2 mmol·L⁻¹**.\nPlus Km est petit, plus l’affinité est grande : **A a une affinité dix fois plus grande** que B (elle atteint la moitié de Vmax avec dix fois moins de substrat).\n\n3. On se place en substrat **saturant**, au moins dix fois Km : 10 × 2 = **20 mmol·L⁻¹ au minimum** pour B (pour A, 2 mmol·L⁻¹ suffiraient).\n\n4. Un **analogue structural** du substrat ressemble à S : il se fixe dans le **site actif** et **entre en compétition** avec S. Les sites occupés par l’inhibiteur ne transforment pas S : v₀ diminue.\n\n5. Le produit final P inhibe l’enzyme E1 du **début** de la voie : c’est une **rétro-inhibition** (boucle de régulation). Quand P s’accumule, E1 ralentit, donc toute la voie ralentit ; quand P est consommé, E1 redevient active. La cellule **ajuste la production de P à ses besoins** et évite de gaspiller substrat et énergie."}$exo$::jsonb),
  ('ee771525-1107-5fad-a399-111b7b16d496'::uuid, 1, 'application', $exo${"titre":"Les remparts de l’organisme","consigne":"Réponds à chaque question avec précision.","enonce":"1. Définis le **soi**, le **non-soi** et un **antigène**. Donne deux exemples de non-soi.\n2. Recopie et complète le tableau :\n\n| Barrière | Où la trouve-t-on ? | Mode d’action |\n| Lysozyme | … | … |\n| pH acide | … | … |\n| Mucus | … | … |\n| Microbiote | … | … |","bareme":[{"critere":"Soi, non-soi et antigène définis, deux exemples de non-soi justes","points":8},{"critere":"Localisation et mode d’action justes pour les quatre barrières","points":12}],"dureeMin":7,"corrige":"1. - **Soi** : l’ensemble des molécules propres à l’individu, **tolérées** par son système immunitaire.\n- **Non-soi** : tout ce qui est reconnu comme **étranger**.\n- **Antigène** : molécule **reconnue par le système immunitaire**.\nExemples de non-soi : une bactérie, un virus, un greffon d’un autre individu, une cellule anormale (deux suffisent).\n\n2.\n| Barrière | Où ? | Mode d’action |\n| **Lysozyme** | larmes, salive | enzyme qui **hydrolyse le peptidoglycane** de la paroi bactérienne |\n| **pH acide** | estomac, vagin, peau | milieu **défavorable** à beaucoup de bactéries |\n| **Mucus** | muqueuses (voies respiratoires…) | **piège les particules**, évacuées par les cils |\n| **Microbiote** | peau, intestin, muqueuses | **occupe la place et les nutriments**, empêche l’installation des pathogènes |"}$exo$::jsonb),
  ('ee771525-1107-5fad-a399-111b7b16d496'::uuid, 2, 'application', $exo${"titre":"L’écharde de Noé","consigne":"Explique chaque phénomène à l’aide des mécanismes du cours, dans l’ordre où ils se produisent.","enonce":"**Situation.** Noé se plante une écharde dans le doigt en jardinant. Quelques heures plus tard, la zone est **rouge, chaude, gonflée et douloureuse**. Des bactéries sont entrées avec l’écharde.\n\n1. Quelles cellules repèrent les bactéries en premier ? Comment les reconnaissent-elles ? Cite deux motifs moléculaires reconnus.\n2. Explique l’origine de chacun des quatre symptômes observés.\n3. Explique comment les phagocytes sanguins arrivent jusqu’au foyer infectieux (deux mécanismes).\n4. Décris les étapes de la phagocytose d’une bactérie.","bareme":[{"critere":"Cellules sentinelles et récepteurs reconnaissant des motifs (LPS, peptidoglycane)","points":5},{"critere":"Rougeur et chaleur par vasodilatation, œdème par exsudation, douleur par pression sur les nerfs","points":6},{"critere":"Diapédèse et chimiotactisme expliqués","points":4},{"critere":"Étapes de la phagocytose dans l’ordre (adhésion, endocytose, digestion, rejet)","points":5}],"dureeMin":11,"corrige":"1. Les **cellules sentinelles** (macrophages, cellules dendritiques, mastocytes) portent des **récepteurs membranaires** qui reconnaissent des **motifs moléculaires** partagés par de nombreux pathogènes : le **LPS** des bactéries Gram négatif, le **peptidoglycane**. Elles libèrent alors des **molécules pro-inflammatoires**.\n\n2. - **Rougeur et chaleur** : **vasodilatation** des vaisseaux.\n- **Gonflement (œdème)** : **exsudation du plasma** hors des vaisseaux.\n- **Douleur** : la **pression de l’œdème sur les nerfs**.\n\n3. - **Diapédèse** : les phagocytes (granulocytes, monocytes) **traversent la paroi des vaisseaux**.\n- **Chimiotactisme** : ils sont **attirés vers le foyer** par des signaux chimiques.\n\n4. 1) **Adhésion** du phagocyte à la bactérie ; 2) **endocytose** : la membrane l’entoure et forme un **phagosome** ; 3) **digestion** : fusion avec les **lysosomes**, dont les enzymes dégradent l’antigène ; 4) **rejet** des débris par exocytose, ou présentation de fragments aux lymphocytes."}$exo$::jsonb),
  ('ee771525-1107-5fad-a399-111b7b16d496'::uuid, 3, 'application', $exo${"titre":"Une mycose après les antibiotiques","consigne":"Analyse la situation et les documents, puis rédige des réponses argumentées avec les notions du cours.","enonce":"**Document 1.** Mme Laurent a suivi un traitement antibiotique de trois semaines contre une infection pulmonaire. Dix jours plus tard, elle présente des plaques blanches dans la bouche : une mycose à *Candida albicans*, une levure présente en petite quantité dans la bouche de nombreuses personnes en bonne santé.\n\n**Document 2.** Évolution du nombre de bactéries de la flore buccale de Mme Laurent (unités arbitraires) : 100 avant le traitement, 15 à la fin du traitement.\n\n**Document 3.** Chez un autre patient, une même bactérie Gram négatif provoque deux infections cutanées à six mois d’intervalle. La réaction inflammatoire se déroule les deux fois avec la même intensité et en autant de temps.\n\n1. À l’aide des documents 1 et 2, explique l’apparition de la mycose. Quel terme qualifie *Candida albicans* ici ?\n2. Montre que le microbiote est une barrière naturelle, en précisant son mode d’action.\n3. Quelle molécule de la bactérie du document 3 les cellules sentinelles peuvent-elles reconnaître ? Pourquoi cette reconnaissance est-elle dite « large » ?\n4. À partir du document 3, dégage deux caractéristiques de l’immunité innée. Complète avec une troisième, tirée du cours.\n5. Explique pourquoi l’immunité innée reste indispensable même si elle n’élimine pas toujours l’infection.","bareme":[{"critere":"Baisse de la flore (100 → 15) libérant place et nutriments, opportunisme identifié","points":5},{"critere":"Microbiote comme barrière : occupation de la place et des nutriments","points":3},{"critere":"LPS reconnu, motif partagé par de nombreux pathogènes, reconnaissance non spécifique","points":4},{"critere":"Absence de mémoire et non-spécificité tirées du document 3, immédiateté ajoutée","points":5},{"critere":"Rôle de l’innée : contenir l’infection en attendant la réponse adaptative","points":3}],"dureeMin":17,"corrige":"1. Le traitement antibiotique a fait chuter la flore bactérienne buccale de **100 à 15 unités** (−85 %). *Candida albicans*, jusque-là tenue en respect, profite de la **place et des nutriments libérés** et se multiplie : c’est un micro-organisme **opportuniste**, qui profite d’un **déséquilibre du microbiote**.\n\n2. Le **microbiote** occupe la place et consomme les nutriments : il **empêche l’installation des pathogènes**. Le document le montre par défaut : quand il est affaibli, une levure s’installe. C’est donc une **barrière naturelle**, qui agit avant toute réponse immunitaire.\n\n3. Une bactérie Gram négatif porte du **LPS** (lipopolysaccharide) dans sa membrane externe, reconnu par des récepteurs membranaires des cellules sentinelles. La reconnaissance est **large** car le LPS est un **motif partagé par de nombreux pathogènes** : elle n’est **pas spécifique d’une espèce**.\n\n4. La seconde infection déclenche une réaction **aussi rapide et aussi intense** que la première : l’organisme n’a rien « appris » → l’immunité innée est **sans mémoire**. Elle agit de la même façon contre toutes les bactéries → elle est **non spécifique**. D’après le cours, elle est aussi **immédiate** (elle démarre dès l’entrée du pathogène).\n\n5. L’immunité innée **contient l’infection** dès les premières heures (inflammation, phagocytose) **en attendant la réponse adaptative**, qui met plusieurs jours à démarrer. Ses cellules peuvent aussi **présenter des fragments** d’antigène aux lymphocytes."}$exo$::jsonb),
  ('74c25b99-580c-55e5-b64c-b83beac9c879'::uuid, 1, 'application', $exo${"titre":"Qui fait quoi chez les lymphocytes","consigne":"Réponds de façon précise, en utilisant le vocabulaire du cours.","enonce":"1. Recopie et complète le tableau :\n\n| Lymphocyte | Récepteur | Marqueur | Cellule effectrice qu’il devient | Rôle de cette cellule |\n| B | … | … | … | … |\n| T4 | … | … | … | … |\n| T8 | … | … | … | … |\n\n2. Décris la structure d’un anticorps et nomme la partie qui se lie à l’antigène, ainsi que la partie de l’antigène reconnue.\n3. Un anticorps détruit-il lui-même la bactérie qu’il reconnaît ? Justifie en citant ses deux rôles.","bareme":[{"critere":"Tableau des trois lymphocytes juste (récepteur, marqueur, devenir, rôle)","points":9},{"critere":"Anticorps en Y, deux chaînes lourdes et deux légères, paratope et épitope","points":6},{"critere":"L’anticorps marque sans détruire : neutralisation et opsonisation","points":5}],"dureeMin":8,"corrige":"1.\n| Lymphocyte | Récepteur | Marqueur | Devient | Rôle |\n| **B** | BCR (anticorps membranaire) | — | **plasmocyte** | sécrète des **anticorps** |\n| **T4** | TCR | **CD4** | **T auxiliaire** | « chef d’orchestre » : sécrète des interleukines qui activent B et T8 |\n| **T8** | TCR | **CD8** | **T cytotoxique** | **lyse les cellules infectées** (perforine-granzymes) |\n\n2. L’anticorps (immunoglobuline) est une molécule en **Y** formée de **deux chaînes lourdes et deux chaînes légères**. L’extrémité des bras porte le **paratope**, qui se lie à l’**épitope** de l’antigène par **complémentarité de forme**.\n\n3. **Non** : l’anticorps **marque**, il ne détruit pas. Ses rôles : la **neutralisation** (un virus ou une toxine couverts d’anticorps ne peuvent plus se fixer sur leur cible) et l’**opsonisation** (une bactérie couverte d’anticorps est bien plus vite **phagocytée**)."}$exo$::jsonb),
  ('74c25b99-580c-55e5-b64c-b83beac9c879'::uuid, 2, 'application', $exo${"titre":"Trois sérodiagnostics à interpréter","consigne":"Interprète chaque résultat en justifiant à l’aide des caractéristiques des réponses primaire et secondaire.","enonce":"**Situation.** Un laboratoire d’analyses médicales recherche les anticorps dirigés contre le virus de la rubéole chez trois personnes.\n\n| Personne | IgM anti-rubéole | IgG anti-rubéole |\n| Clara | élevées | faibles |\n| Hugo | absentes | élevées |\n| Sofia | absentes | absentes |\n\nOn précise que Hugo a été vacciné contre la rubéole il y a plusieurs années.\n\n1. Rappelle les différences entre réponse primaire et réponse secondaire (délai, intensité, anticorps dominants).\n2. Interprète le résultat de chacune des trois personnes.\n3. Quelles cellules expliquent que Hugo soit protégé ? Que se passerait-il s’il rencontrait le virus ?","bareme":[{"critere":"Primaire et secondaire comparées : délai, intensité, IgM puis IgG / IgG","points":6},{"critere":"Clara : infection récente ; Hugo : immunité ancienne (vaccination) ; Sofia : aucun contact","points":9},{"critere":"Lymphocytes mémoire et réponse secondaire rapide et forte pour Hugo","points":5}],"dureeMin":11,"corrige":"1.\n| Réponse | Délai | Intensité | Anticorps dominants |\n| **Primaire** (1er contact) | environ **1 à 2 semaines** | **faible** | **IgM puis IgG** |\n| **Secondaire** (contact suivant) | **quelques jours** | **forte, durable** | **IgG** |\n\n2. - **Clara** : IgM élevées, IgG faibles → réponse primaire en cours : **infection récente** (quelques jours).\n- **Hugo** : IgG seules → **infection ancienne ou vaccination** ; ici, cela correspond à sa vaccination : il est **immunisé**.\n- **Sofia** : aucun anticorps spécifique → **aucun contact** avec le virus (ni infection, ni vaccination) : elle n’est **pas protégée**.\n\n3. Sa vaccination a formé des **lymphocytes mémoire** spécifiques. S’il rencontrait le virus, il déclencherait une **réponse secondaire** : **plus rapide** (quelques jours), **plus intense**, dominée par les **IgG**, qui élimine le virus avant l’apparition de la maladie."}$exo$::jsonb),
  ('74c25b99-580c-55e5-b64c-b83beac9c879'::uuid, 3, 'application', $exo${"titre":"Qui a besoin de qui pour fabriquer des anticorps ?","consigne":"Analyse les résultats expérimentaux, puis construis une explication argumentée à l’aide du cours.","enonce":"**Document 1.** On met en culture des cellules prélevées chez une souris, avec un antigène A, puis on mesure après une semaine la quantité d’anticorps anti-A produits.\n\n| Culture | Cellules présentes | Anticorps anti-A |\n| 1 | lymphocytes B + antigène A | très peu |\n| 2 | lymphocytes B + lymphocytes T4 + antigène A | très peu |\n| 3 | lymphocytes B + lymphocytes T4 + cellules dendritiques + antigène A | beaucoup |\n| 4 | lymphocytes B + antigène A + messagers prélevés dans une culture de T4 activés | beaucoup |\n\n**Document 2.** Les plasmocytes présentent un réticulum endoplasmique granuleux très développé et de nombreuses vésicules de sécrétion.\n\n1. Comparez les cultures 1 et 3 : que montrent-elles ?\n2. Comparez les cultures 2 et 3 : quel est le rôle des cellules dendritiques ? Explique pourquoi les T4 ne s’activent pas en leur absence.\n3. Que montre la culture 4 sur le mode d’action des T4 ? Nomme ces messagers.\n4. Relie le document 2 à la fonction du plasmocyte.\n5. En une dizaine de lignes, retrace les étapes qui mènent de l’entrée de l’antigène A à la production d’anticorps, en utilisant les termes : cellule présentatrice, CMH, TCR, sélection, activation monoclonale, T auxiliaire, plasmocyte.","bareme":[{"critere":"Cultures 1 et 3 : les B seuls ne suffisent pas, une coopération cellulaire est nécessaire","points":3},{"critere":"Rôle des cellules dendritiques : présentation de peptides par le CMH au TCR des T4","points":5},{"critere":"Culture 4 : les T4 agissent par des messagers, les interleukines","points":3},{"critere":"Plasmocyte : REG et vésicules adaptés à la synthèse et sécrétion massive d’anticorps","points":3},{"critere":"Synthèse ordonnée et juste, avec les sept termes imposés","points":6}],"dureeMin":19,"corrige":"1. Avec les seuls lymphocytes B (culture 1), il y a très peu d’anticorps ; avec B + T4 + cellules dendritiques (culture 3), beaucoup. Les B **ne suffisent pas** : la production d’anticorps nécessite une **coopération** avec d’autres cellules.\n\n2. La seule différence entre 2 et 3 est la présence de **cellules dendritiques** : elles sont nécessaires. Ce sont des **cellules présentatrices d’antigène** : elles phagocytent l’antigène, le découpent et exposent des **peptides antigéniques** sur le **CMH**. Or un lymphocyte T **ne reconnaît jamais un antigène libre**, seulement un peptide présenté par le CMH : sans CPA (culture 2), les T4 ne sont pas activés et n’aident pas les B.\n\n3. Sans T4 mais avec leurs **messagers**, les B produisent beaucoup d’anticorps : les T4 agissent **à distance, par des molécules sécrétées**, les **interleukines**.\n\n4. Le plasmocyte **synthétise et sécrète** des milliers d’anticorps (protéines) par seconde : le **réticulum endoplasmique granuleux** développé assure la synthèse de ces protéines, les **vésicules** leur sécrétion.\n\n5. Synthèse attendue : l’antigène A est phagocyté par une **cellule présentatrice** (cellule dendritique), qui le découpe et expose des peptides sur son **CMH**. Parmi tous les T4, seul celui dont le **TCR** reconnaît ce complexe est retenu (**sélection**) et se multiplie en un clone (**activation monoclonale**). Ces T4 deviennent des **T auxiliaires** qui sécrètent des interleukines. De leur côté, les B dont le BCR reconnaît l’antigène A sont sélectionnés ; sous l’effet des interleukines, ils se multiplient et se différencient en **plasmocytes**, qui sécrètent des anticorps anti-A. Ces anticorps neutralisent ou opsonisent l’antigène. Des lymphocytes mémoire sont aussi formés."}$exo$::jsonb),
  ('2e8a9e4f-b724-518f-bb49-0cede682381a'::uuid, 1, 'application', $exo${"titre":"Ce qu’il y a dans un vaccin","consigne":"Réponds à chaque question par une phrase précise.","enonce":"1. Associe chaque vaccin à son type (vivant atténué, inactivé, sous-unitaire, anatoxine, ARN messager) :\n- vaccin contre la rougeole-oreillons-rubéole ;\n- vaccin contre le tétanos ;\n- vaccin contre l’hépatite B (protéine de surface) ;\n- vaccin injectable contre la poliomyélite ;\n- vaccins contre la covid-19 utilisés en France dès 2021 (ARNm).\n2. Définis l’**immunogénicité** et le rôle d’un **adjuvant** (donne un exemple).\n3. Pourquoi faut-il faire des **rappels** ?","bareme":[{"critere":"Cinq associations vaccin / type justes","points":10},{"critere":"Immunogénicité définie et rôle de l’adjuvant avec un exemple","points":6},{"critere":"Rappels : relancer une réponse secondaire, entretenir la mémoire","points":4}],"dureeMin":7,"corrige":"1. - Rougeole-oreillons-rubéole : **vivant atténué**.\n- Tétanos : **anatoxine** (toxine rendue inoffensive mais encore reconnue).\n- Hépatite B : **sous-unitaire** (une seule molécule du pathogène).\n- Poliomyélite injectable : **inactivé** (micro-organisme entier tué).\n- Covid-19 : **ARN messager** (qui fait produire l’antigène par nos cellules).\n\n2. L’**immunogénicité** est la capacité d’un antigène à **déclencher une réponse immunitaire**. L’**adjuvant** renforce la réponse à un antigène peu immunogène en **stimulant l’immunité innée** ; exemple : les **sels d’aluminium**.\n\n3. Les rappels **relancent une réponse secondaire** et **entretiennent la mémoire immunitaire** (lymphocytes mémoire), pour une protection durable."}$exo$::jsonb),
  ('2e8a9e4f-b724-518f-bb49-0cede682381a'::uuid, 2, 'application', $exo${"titre":"Aux urgences après une blessure au jardin","consigne":"Justifie chaque choix médical à l’aide des notions du cours.","enonce":"**Situation.** M. Durand, 62 ans, se blesse profondément avec un râteau couvert de terre. Il n’a jamais été vacciné contre le tétanos, maladie due à une toxine bactérienne. Le médecin lui injecte, au même moment mais à deux endroits différents, des **immunoglobulines antitétaniques** et une **première dose de vaccin** (anatoxine).\n\n1. Qu’apporte chacune des deux injections ? Précise le type d’immunité (active ou passive) et le délai d’efficacité.\n2. Pourquoi le médecin ne se contente-t-il pas des immunoglobulines ?\n3. Pourquoi ne se contente-t-il pas du vaccin ?\n4. Compare vaccination et sérothérapie dans un tableau : ce qu’on injecte, durée de protection, usage.","bareme":[{"critere":"Immunoglobulines : immunité passive immédiate ; vaccin : immunité active en quelques semaines","points":6},{"critere":"Sérothérapie seule insuffisante : anticorps éliminés, aucune mémoire","points":4},{"critere":"Vaccin seul trop lent face à une exposition récente","points":4},{"critere":"Tableau comparatif juste (injection, durée, usage)","points":6}],"dureeMin":11,"corrige":"1. - **Immunoglobulines antitétaniques** : anticorps prêtés qui neutralisent la toxine → immunité **passive**, **immédiate**.\n- **Vaccin (anatoxine)** : antigène non pathogène qui fait produire ses propres anticorps et des lymphocytes mémoire → immunité **active**, efficace en **quelques semaines**.\n\n2. Les anticorps injectés sont **éliminés en quelques semaines** et **aucun lymphocyte mémoire** n’est formé : la sérothérapie ne « vaccine » pas. M. Durand resterait sans protection pour les blessures suivantes.\n\n3. Le vaccin n’est efficace qu’après **quelques semaines** : face à une **exposition récente**, la toxine pourrait agir avant. Il faut une protection immédiate.\n\n4.\n| Critère | Vaccination | Sérothérapie |\n| Ce qu’on injecte | un **antigène non pathogène** | des **anticorps** (sérum) |\n| Durée de protection | **longue** (mémoire) | **courte** (quelques semaines) |\n| Usage | **prophylaxie** (prévenir) | **urgence** thérapeutique, exposition récente |"}$exo$::jsonb),
  ('2e8a9e4f-b724-518f-bb49-0cede682381a'::uuid, 3, 'application', $exo${"titre":"Quand la rougeole revient","consigne":"Analyse les documents et rédige une réponse argumentée, en mobilisant les notions du cours.","enonce":"**Document 1 (données fictives).** Dans un pays imaginaire, on suit la couverture vaccinale contre la rougeole des enfants (deux doses) et le nombre de cas déclarés.\n\n| Année | 2005 | 2008 | 2011 | 2014 | 2017 |\n| Couverture vaccinale (%) | 96 | 93 | 85 | 78 | 94 |\n| Cas déclarés | 40 | 120 | 5 200 | 14 000 | 300 |\n\n**Document 2.** Parmi les cas de 2014, on compte de nombreux **nourrissons de moins d’un an**, trop jeunes pour être vaccinés, et des enfants **immunodéprimés** (traités pour une leucémie), pour qui le vaccin vivant atténué est déconseillé.\n\n**Document 3 — expérience historique.** Le sérum d’un animal immunisé contre une toxine, injecté à un animal neuf, le protège aussitôt contre cette toxine.\n\n1. Décris l’évolution conjointe des deux séries du document 1 et nomme le phénomène observé entre 2008 et 2014.\n2. À l’aide du document 2, explique la notion de protection collective et montre qu’elle concerne aussi des personnes non vaccinées.\n3. Le vaccin contre la rougeole est vivant atténué : explique ce que cela signifie et pourquoi il est déconseillé aux immunodéprimés d’après le document 2.\n4. Que montre le document 3 ? Pourrait-on protéger durablement les nourrissons par cette méthode ? Justifie.\n5. Cite deux questions éthiques ou sociétales que soulève cette situation.","bareme":[{"critere":"Lien couverture / cas décrit avec valeurs, résurgence nommée","points":4},{"critere":"Protection collective expliquée : le virus circule mal, protège nourrissons et immunodéprimés","points":5},{"critere":"Vivant atténué défini, prudence chez des personnes aux défenses affaiblies","points":3},{"critere":"Protection transférable par les anticorps, mais passive et courte, sans mémoire","points":5},{"critere":"Deux enjeux éthiques ou sociétaux pertinents","points":3}],"dureeMin":18,"corrige":"1. Quand la couverture vaccinale baisse de **96 % (2005) à 78 % (2014)**, les cas explosent de **40 à 14 000**. Quand elle remonte à **94 % (2017)**, ils retombent à **300**. Les deux séries varient en sens inverse. La réapparition de la maladie quand la couverture baisse est une **résurgence**.\n\n2. Quand une **grande part** de la population est immunisée, le virus **circule mal** : il trouve peu de personnes à infecter. Cela protège aussi les personnes **qui ne peuvent pas être vaccinées** : les **nourrissons** trop jeunes et les **immunodéprimés**. Quand la couverture chute, ces personnes vulnérables sont touchées les premières (document 2) : c’est la **protection collective** qui a disparu, pas seulement la protection individuelle.\n\n3. Un vaccin **vivant atténué** contient le micro-organisme **vivant, rendu peu pathogène**. Chez une personne dont les défenses sont affaiblies (immunodéprimée), même un micro-organisme atténué pourrait se multiplier : c’est pourquoi le document 2 indique qu’il est déconseillé ; ces personnes dépendent donc de la protection collective.\n\n4. Le document 3 montre que la protection est **transférable par les anticorps** du sérum : c’est le principe de la **sérothérapie**, immunité **passive et immédiate**. Mais elle **ne protège pas durablement** : les anticorps injectés sont éliminés en quelques semaines et **aucun lymphocyte mémoire** n’est formé. Elle sert en urgence, pas en prévention à long terme.\n\n5. Exemples attendus (deux) : l’**obligation vaccinale** face à la liberté individuelle ; l’**information** et la **confiance** de la population dans les vaccins ; l’**accès aux vaccins** dans le monde ; la responsabilité envers les personnes qui ne peuvent pas être vaccinées."}$exo$::jsonb),
  ('151b3b5f-5aa0-5587-acdf-27aedaa1051f'::uuid, 1, 'application', $exo${"titre":"Ce que l’ADN permet au laboratoire","consigne":"Réponds à chaque question en reliant la propriété à la structure de la molécule.","enonce":"1. Pourquoi l’ADN migre-t-il vers l’**anode** lors d’une électrophorèse ?\n2. Quel est le principe de l’**extraction** de l’ADN ?\n3. À quelle longueur d’onde dose-t-on l’ADN par spectrophotométrie ? Quelle partie de la molécule absorbe la lumière ?\n4. Quelles liaisons sont rompues lors de la **dénaturation** de l’ADN par la chaleur ? Lesquelles résistent ?","bareme":[{"critere":"Phosphates chargés négativement : polyanion attiré par l’anode","points":5},{"critere":"Précipitation en présence de sel et d’éthanol froid","points":5},{"critere":"Absorption maximale vers 260 nm par les bases azotées","points":5},{"critere":"Liaisons hydrogène rompues, liaisons phosphodiester conservées","points":5}],"dureeMin":6,"corrige":"1. Les groupements **phosphate** sont **chargés négativement** : l’ADN est un **polyanion**, attiré par l’électrode positive, l’**anode**.\n\n2. En présence de **sel et d’éthanol froid**, l’ADN **précipite** : il devient visible (pelote) et peut être récupéré.\n\n3. On le dose vers **260 nm** (UV) : ce sont les **bases azotées** qui absorbent la lumière.\n\n4. La chaleur rompt les **liaisons hydrogène** entre bases complémentaires : les deux brins se séparent. Les **liaisons phosphodiester**, covalentes, **résistent**."}$exo$::jsonb),
  ('151b3b5f-5aa0-5587-acdf-27aedaa1051f'::uuid, 2, 'application', $exo${"titre":"Chauffer deux ADN","consigne":"Exploite les données et justifie chaque réponse par la structure de l’ADN.","enonce":"**Situation.** Lucie chauffe deux échantillons d’ADN de même longueur et suit l’absorbance à 260 nm.\n\n| Température (°C) | 60 | 70 | 75 | 80 | 85 | 90 | 95 |\n| A₂₆₀ ADN X | 1,00 | 1,02 | 1,15 | 1,30 | 1,40 | 1,41 | 1,41 |\n| A₂₆₀ ADN Y | 1,00 | 1,00 | 1,01 | 1,05 | 1,20 | 1,35 | 1,40 |\n\nPour chaque ADN, l’absorbance passe de 1,00 (double brin) à environ 1,40 (simple brin).\n\n1. Nomme et explique l’augmentation d’absorbance observée.\n2. Définis la température de fusion Tm, puis estime-la pour chaque ADN (absorbance à mi-chemin, 1,20).\n3. Lequel des deux ADN est le plus riche en paires C≡G ? Justifie.\n4. Un fragment double brin de 10 paires de bases contient 4 paires C≡G. Combien de liaisons hydrogène relient ses deux brins ?","bareme":[{"critere":"Effet hyperchrome : le simple brin absorbe plus à 260 nm","points":5},{"critere":"Tm définie, Tm(X) ≈ 77 °C et Tm(Y) ≈ 85 °C","points":6},{"critere":"ADN Y plus riche en C≡G, justifié par les trois liaisons hydrogène","points":5},{"critere":"Calcul juste : 4 × 3 + 6 × 2 = 24 liaisons","points":4}],"dureeMin":11,"corrige":"1. L’augmentation d’absorbance à 260 nm quand l’ADN passe de double brin à **simple brin** est l’**effet hyperchrome** : la chaleur dénature l’ADN (rupture des liaisons hydrogène) et l’ADN simple brin absorbe davantage.\n\n2. La **Tm** est la température à laquelle **la moitié de l’ADN est dénaturée**, soit une absorbance à mi-chemin (1,20).\n- ADN X : 1,20 est atteint entre 75 °C (1,15) et 80 °C (1,30) → **Tm(X) ≈ 77 °C** (toute valeur entre 76 et 78 °C est acceptée).\n- ADN Y : 1,20 à **85 °C** → **Tm(Y) ≈ 85 °C**.\n\n3. **L’ADN Y** a la Tm la plus haute : il est le plus **riche en paires C≡G**. Ces paires sont unies par **trois liaisons hydrogène** (contre deux pour A=T) : elles résistent mieux à la chaleur.\n\n4. 10 paires dont 4 C≡G, donc 6 A=T : 4 × 3 + 6 × 2 = 12 + 12 = **24 liaisons hydrogène**."}$exo$::jsonb),
  ('151b3b5f-5aa0-5587-acdf-27aedaa1051f'::uuid, 3, 'application', $exo${"titre":"Copier, se diviser, s’emballer","consigne":"Analyse les documents et rédige des réponses argumentées à l’aide du cours.","enonce":"**Document 1.** Quantité d’ADN par cellule (unités arbitraires) dans une culture de cellules humaines, au cours d’un cycle.\n\n| Heure | 0 | 6 | 10 | 14 | 18 | 20 | 21 | 22 |\n| ADN (u.a.) | 2 | 2 | 2,6 | 3,4 | 4 | 4 | 4 | 2 |\n\n**Document 2.** Deux cultures en boîte de Pétri :\n- cellules de peau normales : elles se divisent jusqu’à couvrir le fond en une seule couche, puis s’arrêtent ;\n- cellules issues d’une tumeur : elles continuent de se diviser et s’empilent en amas.\n\n**Document 3.** Le taxol, utilisé en chimiothérapie, bloque la mitose.\n\n1. Identifie sur le document 1 les phases G1, S, G2 et mitose, en justifiant par les valeurs.\n2. Explique ce qui se passe pendant la phase S : rôle de l’hélicase, de l’amorce, de l’ADN polymérase et de la ligase. Pourquoi un brin est-il copié par fragments ?\n3. Explique pourquoi la réplication est dite semi-conservative.\n4. Interprète le document 2 et relie-le à la cancérogenèse.\n5. Explique l’intérêt du taxol dans le traitement d’un cancer.\n6. Une cellule de peau et un neurone du même individu ont-ils le même génome ? Explique pourquoi ils sont pourtant différents.","bareme":[{"critere":"Phases identifiées avec valeurs : G1 à 2 u.a., S de 2 à 4, G2 à 4, mitose retour à 2","points":4},{"critere":"Rôles de l’hélicase, amorce, ADN polymérase (5’→3’) et ligase ; brins antiparallèles","points":5},{"critere":"Semi-conservative : chaque molécule fille garde un brin parental","points":2},{"critere":"Perte de l’inhibition de contact, mutations, prolifération anarchique ; intérêt du taxol","points":5},{"critere":"Même génome, expression de gènes différents : différenciation, gènes réprimés","points":4}],"dureeMin":20,"corrige":"1. - **G1** (0 à 6 h environ) : ADN stable à **2 u.a.**\n- **S** (6 à 18 h) : l’ADN **double** progressivement de 2 à **4 u.a.** : c’est la réplication.\n- **G2** (18 à 21 h) : ADN stable à **4 u.a.**, deux fois plus qu’en G1.\n- **Mitose** (21 à 22 h) : retour à **2 u.a.**, l’ADN est réparti entre deux cellules filles.\n\n2. L’**hélicase** ouvre la double hélice ; une **amorce** d’ARN fournit un point de départ ; l’**ADN polymérase** ajoute des **dNTP complémentaires** du brin modèle, toujours dans le sens **5’→3’** ; la **ligase** relie les fragments. Les deux brins étant **antiparallèles**, l’un est copié **en continu**, l’autre **par fragments**, reliés ensuite par la ligase.\n\n3. Chaque molécule fille est formée d’**un brin parental** (servant de modèle) et **d’un brin neuf** : la moitié de l’ancienne molécule est conservée.\n\n4. Les cellules normales cessent de se diviser au contact les unes des autres : c’est l’**inhibition de contact**. Les cellules tumorales l’ont **perdue** : des **mutations** ont déréglé le contrôle du cycle cellulaire, d’où une **prolifération anarchique** (amas). C’est la **cancérogenèse**.\n\n5. Le taxol **bloque la mitose** : les cellules cancéreuses, qui se divisent sans cesse, ne peuvent plus achever leur division ; la prolifération de la tumeur est freinée.\n\n6. **Oui**, toutes les cellules d’un individu ont **le même génome**. Elles diffèrent parce que chacune **exprime des gènes différents** : c’est la **différenciation**. Les gènes non exprimés **n’ont pas disparu**, ils sont **réprimés** (par exemple dans l’hétérochromatine, très condensée)."}$exo$::jsonb),
  ('a3f400f6-4ef2-5a71-ad76-a6be509924ca'::uuid, 1, 'application', $exo${"titre":"Bactérie, levure, moisissure, virus : les distinguer","consigne":"Réponds avec précision, en utilisant le vocabulaire du cours.","enonce":"1. Recopie et complète le tableau comparant les parois bactériennes :\n\n| Caractère | Gram positif | Gram négatif |\n| Couche de peptidoglycane | … | … |\n| Membrane externe | … | … |\n| Couleur après coloration de Gram | … | … |\n\n2. Cite deux structures présentes dans une bactérie et une structure qui y est absente, contrairement à une levure.\n3. Comment se multiplie une levure ? Comment une moisissure se propage-t-elle ?\n4. Pourquoi dit-on qu’un virus est un **parasite obligatoire** ?","bareme":[{"critere":"Tableau Gram positif / Gram négatif juste (épaisseur, membrane externe et LPS, couleur)","points":7},{"critere":"Structures bactériennes citées et absence de noyau","points":4},{"critere":"Bourgeonnement de la levure, spores de la moisissure","points":4},{"critere":"Virus : multiplication seulement à l’intérieur d’une cellule cible","points":5}],"dureeMin":7,"corrige":"1.\n| Caractère | Gram positif | Gram négatif |\n| Peptidoglycane | couche **épaisse** | couche **fine** |\n| Membrane externe | **absente** | **présente, avec le LPS** |\n| Couleur après Gram | **violette** | **rose** |\n\n2. Présents dans une bactérie (deux au choix) : **chromosome bactérien** circulaire, **plasmides**, ribosomes, membrane, **paroi**. Absent : le **noyau** (la bactérie est un procaryote ; la levure, eucaryote, en possède un).\n\n3. La levure, unicellulaire, se multiplie par **bourgeonnement**. La moisissure forme des filaments (**hyphes**) qui constituent un **mycélium** ; son appareil sporifère libère des **spores** qui propagent le champignon.\n\n4. Un virus (acide nucléique dans une capside, parfois une enveloppe) **ne peut se multiplier qu’à l’intérieur d’une cellule cible** : il dépend entièrement d’elle, d’où l’expression parasite obligatoire."}$exo$::jsonb),
  ('a3f400f6-4ef2-5a71-ad76-a6be509924ca'::uuid, 2, 'application', $exo${"titre":"Au laboratoire de contrôle de l’eau","consigne":"Exploite les observations et les résultats, puis justifie chaque conclusion.","enonce":"**Situation.** Yanis, technicien dans un laboratoire de contrôle de l’eau, examine trois micro-organismes isolés d’un prélèvement.\n\n- **A** : petites cellules en bâtonnets, sans noyau, **roses** après coloration de Gram.\n- **B** : cellules ovoïdes avec noyau ; certaines portent une excroissance qui grossit et se détache.\n- **C** : colonie cotonneuse ; au microscope, des filaments ramifiés et, à leur extrémité, des structures qui libèrent de nombreuses petites cellules.\n\nPar ailleurs, l’analyse d’une eau de consommation donne **3 *E. coli* pour 100 mL**. La limite de qualité est de **0 *E. coli* pour 100 mL**.\n\n1. Identifie la catégorie de chacun des trois micro-organismes (bactérie Gram positif ou négatif, levure, moisissure) en justifiant.\n2. Que signale la présence d’*E. coli* dans l’eau ? Comment appelle-t-on ce type de germe recherché ? L’eau est-elle conforme ?\n3. Le frère de Yanis a la grippe (maladie virale) et réclame un antibiotique. Explique pourquoi c’est inutile.","bareme":[{"critere":"A bactérie Gram négatif (bacille, sans noyau, rose), B levure (bourgeonnement), C moisissure (hyphes, spores)","points":8},{"critere":"E. coli flore indicatrice d’une contamination fécale, eau non conforme au critère","points":7},{"critere":"Antibiotique inefficace : il vise des structures bactériennes absentes des virus","points":5}],"dureeMin":10,"corrige":"1. - **A** : pas de noyau, forme de bâtonnet (bacille), rose après Gram → **bactérie Gram négatif**.\n- **B** : cellule eucaryote (noyau) qui se multiplie par une excroissance qui se détache → **levure** (bourgeonnement).\n- **C** : filaments ramifiés (**hyphes** formant un mycélium) et appareil sporifère libérant des **spores** → **moisissure**.\n\n2. *E. coli* est une **flore indicatrice** : sa présence signale une **contamination fécale** de l’eau. On compare le résultat au **critère officiel** : 3 *E. coli* pour 100 mL > 0 pour 100 mL → l’eau est **non conforme**.\n\n3. Un antibiotique agit **contre des bactéries** : il vise des **structures bactériennes** (paroi, par exemple) **absentes des virus**. Il est donc **inefficace contre la grippe**, qui est due à un virus."}$exo$::jsonb),
  ('a3f400f6-4ef2-5a71-ad76-a6be509924ca'::uuid, 3, 'application', $exo${"titre":"Des virus qui détruisent ou qui attendent","consigne":"Analyse les documents et rédige des réponses argumentées à l’aide du cours.","enonce":"**Document 1.** Deux bactériophages infectent des cultures de la même bactérie.\n- Avec le phage P1, la culture devient limpide en une heure : les bactéries ont éclaté en libérant de nombreux phages.\n- Avec le phage P2, les bactéries continuent de se multiplier ; on retrouve pourtant le génome de P2 inséré dans leur chromosome.\n\n**Document 2.** Nombre de lymphocytes T4 (par mm³ de sang) d’un patient infecté par le VIH, sans traitement.\n\n| Années après la contamination | 0 | 0,2 | 1 | 4 | 8 | 10 |\n| T4 (par mm³) | 950 | 600 | 800 | 650 | 300 | 100 |\n\nÀ 10 ans, le patient développe des infections par des micro-organismes habituellement inoffensifs.\n\n1. Décris les étapes du cycle de multiplication d’un virus dans sa cellule cible.\n2. Nomme les cycles réalisés par P1 et P2 et explique la différence.\n3. Pourquoi le VIH infecte-t-il les lymphocytes T4 ? Explique le rôle de sa transcriptase inverse.\n4. Identifie sur le document 2 les trois stades de l’infection et explique les infections de la dixième année.\n5. Les antirétroviraux visent des enzymes du virus. Cite-les et précise ce qu’on peut attendre du traitement.","bareme":[{"critere":"Étapes du cycle viral dans l’ordre (fixation, pénétration, réplication et synthèse, assemblage, libération)","points":4},{"critere":"P1 cycle lytique (phage virulent), P2 cycle lysogène (phage tempéré) expliqués","points":4},{"critere":"Récepteur CD4 et transcriptase inverse (ARN copié en ADN intégré)","points":4},{"critere":"Primo-infection, phase asymptomatique, sida avec maladies opportunistes, appuyés sur les valeurs","points":5},{"critere":"Cibles des antirétroviraux et contrôle sans élimination du virus","points":3}],"dureeMin":18,"corrige":"1. **Fixation** du virus sur un **récepteur spécifique** de la cellule cible → **pénétration** → **réplication du génome** et **synthèse des protéines virales** par la cellule → **assemblage** de nouveaux virus → **libération**, par lyse de la cellule ou par bourgeonnement (virus enveloppés).\n\n2. - **P1** : **cycle lytique** (phage **virulent**) : il se multiplie aussitôt et la bactérie **éclate** en libérant les nouveaux phages.\n- **P2** : **cycle lysogène** (phage **tempéré**) : son génome **s’intègre** au chromosome bactérien et **reste latent** ; la bactérie survit et se divise.\n\n3. Le VIH se fixe sur le **récepteur CD4**, porté par les lymphocytes **T4**. C’est un **rétrovirus** à ARN : sa **transcriptase inverse** copie son **ARN en ADN**, qui est **intégré au génome** de la cellule.\n\n4. - **Primo-infection** (0 à ~0,2 an) : chute rapide des T4 (950 → 600 par mm³).\n- **Phase asymptomatique longue** (~1 à 8 ans) : les T4 remontent (800) puis baissent lentement (650, puis 300).\n- **Sida** (10 ans) : les T4 **s’effondrent** (100 par mm³). Sans T4, chefs d’orchestre de la réponse adaptative, l’organisme est en **immunodéficience** : des micro-organismes habituellement inoffensifs provoquent des **maladies opportunistes**.\n\n5. Les antirétroviraux visent la **transcriptase inverse**, l’**intégrase** et la **protéase** du virus. Ils **contrôlent** la multiplication du virus **sans l’éliminer** : le traitement doit être poursuivi."}$exo$::jsonb),
  ('51b44c0d-6c8f-5fe1-b289-f61b6f2baeb2'::uuid, 1, 'application', $exo${"titre":"Les phases d’une culture et les agents qui la freinent","consigne":"Réponds de façon précise et concise.","enonce":"1. Cite dans l’ordre les six phases de la courbe de croissance en milieu non renouvelé, et indique pour chacune ce qui se passe et comment évolue la vitesse de croissance.\n2. Classe les trois produits suivants (antiseptique, désinfectant ou antibiotique) en précisant où ils s’utilisent : eau de Javel, amoxicilline, chlorhexidine.\n3. Quelle différence y a-t-il entre un agent **bactéricide** et un agent **bactériostatique** ?","bareme":[{"critere":"Six phases dans l’ordre avec leur description et l’évolution de la vitesse","points":11},{"critere":"Trois produits bien classés avec leur lieu d’utilisation","points":6},{"critere":"Différence -cide (tue) / -statique (bloque la croissance)","points":3}],"dureeMin":8,"corrige":"1. - **Latence** : adaptation au milieu, synthèse d’enzymes ; vitesse **nulle**.\n- **Accélération** : début des divisions ; vitesse **croissante**.\n- **Exponentielle** : divisions à rythme constant ; vitesse **maximale et constante**.\n- **Ralentissement** : nutriments qui s’épuisent, déchets qui s’accumulent ; vitesse **décroissante**.\n- **Stationnaire** : autant de morts que de divisions ; vitesse **nulle**.\n- **Déclin** : la mort l’emporte ; vitesse **négative**.\n\n2. - **Eau de Javel** : **désinfectant**, sur une surface ou un objet inerte.\n- **Amoxicilline** : **antibiotique**, dans l’organisme, contre des bactéries.\n- **Chlorhexidine** : **antiseptique**, sur un tissu vivant (peau, plaie).\n\n3. Un agent **bactéricide tue** les bactéries ; un agent **bactériostatique bloque seulement leur croissance**, sans forcément les tuer."}$exo$::jsonb),
  ('51b44c0d-6c8f-5fe1-b289-f61b6f2baeb2'::uuid, 2, 'application', $exo${"titre":"La culture de Chloé","consigne":"Exploite les mesures et pose chaque calcul avec ses unités.","enonce":"**Situation.** Chloé suit une culture bactérienne à 37 °C dans un volume fixe de bouillon.\n\n| t (min) | 0 | 30 | 60 | 90 | 120 | 150 | 240 | 300 |\n| N (bactéries·mL⁻¹) | 2,0 × 10⁴ | 2,0 × 10⁴ | 2,4 × 10⁴ | 1,6 × 10⁵ | 4,5 × 10⁵ | 1,28 × 10⁶ | 3,0 × 10⁶ | 3,0 × 10⁶ |\n\nOn admet que la phase exponentielle s’étend de 90 à 150 min.\n\n1. Nomme les phases observées de 0 à 30 min et de 240 à 300 min, et explique ce qui se passe dans chacune.\n2. Calcule le nombre de générations n entre 90 et 150 min, puis le temps de génération G.\n3. Calcule le taux de croissance µ.\n4. Pourquoi représente-t-on souvent ln N en fonction du temps ?","bareme":[{"critere":"Latence (0–30 min) et phase stationnaire (240–300 min) identifiées et expliquées","points":5},{"critere":"Facteur 8 = 2³, soit n = 3 générations et G = 20 min","points":7},{"critere":"µ = ln 2 / G ≈ 0,035 min⁻¹","points":4},{"critere":"Phase exponentielle rendue linéaire en ln N, pente = µ","points":4}],"dureeMin":12,"corrige":"1. - **0 à 30 min** : N reste à 2,0 × 10⁴ : **phase de latence**, les bactéries s’adaptent au milieu (synthèse d’enzymes) sans se diviser.\n- **240 à 300 min** : N reste à 3,0 × 10⁶ : **phase stationnaire**, il y a autant de morts que de divisions (nutriments épuisés, déchets accumulés).\n\n2. Entre 90 et 150 min, N passe de 1,6 × 10⁵ à 1,28 × 10⁶ : facteur 1,28 × 10⁶ / 1,6 × 10⁵ = **8 = 2³**, donc **n = 3 générations**.\nG = durée / n = 60 / 3 = **20 min**.\n(Vérification : en 30 min, soit 1,5 génération, N est multiplié par 2^1,5 ≈ 2,8 : 1,6 × 10⁵ × 2,8 ≈ 4,5 × 10⁵ à 120 min, conforme au tableau.)\n\n3. µ = ln 2 / G = 0,69 / 20 ≈ **0,035 min⁻¹**.\n\n4. En phase exponentielle, N = N₀ × 2ⁿ : en représentant **ln N** en fonction du temps, cette phase devient une **droite**, facile à repérer, dont la **pente est µ**."}$exo$::jsonb),
  ('51b44c0d-6c8f-5fe1-b289-f61b6f2baeb2'::uuid, 3, 'application', $exo${"titre":"Choisir un antibiotique pour une infection urinaire","consigne":"Analyse les documents, justifie chaque interprétation et argumente ta conclusion.","enonce":"**Situation.** Une souche d’*Escherichia coli* (bactérie Gram négatif) a été isolée à partir de l’urine d’une patiente.\n\n**Document 1 — antibiogramme.** Diamètres des zones d’inhibition et valeurs critiques fournies par le référentiel :\n\n| Antibiotique | Diamètre mesuré (mm) | Sensible si ≥ | Résistant si < |\n| Amoxicilline | 8 | 19 | 14 |\n| Antibiotique X | 25 | 22 | 19 |\n| Antibiotique Y | 20 | 22 | 19 |\n| Vancomycine | 6 (pas de zone) | — | — |\n\n**Document 2 — CMI de l’antibiotique X.** Des tubes de bouillon ensemencés contiennent des concentrations croissantes de X.\n\n| X (mg·L⁻¹) | 0 | 0,25 | 0,5 | 1 | 2 | 4 | 8 |\n| Trouble après 24 h | oui | oui | oui | non | non | non | non |\n\n**Document 3.** La souche porte un plasmide contenant un gène de résistance à l’amoxicilline, absent chez d’autres souches de la même espèce.\n\n1. Explique le principe de l’antibiogramme par diffusion.\n2. Classe la souche (sensible, intermédiaire, résistante) pour l’amoxicilline, X et Y.\n3. Détermine la CMI de X et définis-la. Quel rôle joue le tube à 0 mg·L⁻¹ ?\n4. Explique l’absence de zone autour de la vancomycine, puis la résistance à l’amoxicilline (document 3). Nomme le type de chaque résistance.\n5. Pourquoi les résultats n’ont-ils de valeur que si le protocole est standardisé ? Cite trois paramètres. Conclus sur l’antibiotique à privilégier.","bareme":[{"critere":"Principe : disques, diffusion, zone d’inhibition comparée aux valeurs critiques","points":3},{"critere":"Amoxicilline résistante, X sensible, Y intermédiaire, justifiés par les valeurs","points":4},{"critere":"CMI = 1 mg·L⁻¹ définie, tube sans antibiotique comme témoin de croissance","points":4},{"critere":"Vancomycine : résistance naturelle (membrane externe) ; amoxicilline : résistance acquise par plasmide","points":5},{"critere":"Standardisation (inoculum, épaisseur de gélose, durée et température) et choix de X","points":4}],"dureeMin":20,"corrige":"1. La souche est ensemencée **en nappe** sur une gélose ; on pose des **disques imprégnés d’antibiotique**. L’antibiotique **diffuse** dans la gélose et empêche la croissance autour du disque : une **zone d’inhibition** apparaît. On compare son **diamètre** aux **valeurs critiques** pour classer la souche.\n\n2. - **Amoxicilline** : 8 mm < 14 mm → **résistante**.\n- **X** : 25 mm ≥ 22 mm → **sensible**.\n- **Y** : 20 mm, entre 19 et 22 mm → **intermédiaire**.\n\n3. La **CMI** est la **plus petite concentration qui empêche toute croissance visible** : ici, le premier tube sans trouble est à **1 mg·L⁻¹** → **CMI = 1 mg·L⁻¹**. Le tube à 0 mg·L⁻¹ est un **témoin** : il vérifie que la souche pousse bien dans ces conditions (sinon l’absence de trouble ne prouverait rien).\n\n4. - **Vancomycine** : chez les bactéries Gram négatif, la **membrane externe bloque la vancomycine** : c’est une **résistance naturelle**, qui concerne toute l’espèce.\n- **Amoxicilline** : le gène de résistance est porté par un **plasmide**, absent chez d’autres souches de la même espèce : c’est une **résistance acquise** (plasmide reçu).\n\n5. Le diamètre de la zone dépend des conditions : les résultats ne sont comparables aux valeurs critiques que si le protocole est **standardisé** : **inoculum**, **épaisseur de gélose**, **durée et température d’incubation**.\nConclusion : il faut **privilégier l’antibiotique X** (souche sensible, CMI basse), éviter l’amoxicilline (résistante) et Y (intermédiaire)."}$exo$::jsonb),
  ('68bcaab4-2f96-565f-ae7b-6ec058962bd0'::uuid, 1, 'application', $exo${"titre":"Les premiers indices d’une identification","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Pourquoi faut-il partir d’une **souche pure** ? Comment vérifie-t-on la pureté ?\n2. Cite trois caractères morphologiques observés, en précisant la technique utilisée (aspect des colonies, état frais, coloration).\n3. Explique comment on lit le test **catalase** et ce qu’il révèle.\n4. Que révèle un test **oxydase** positif ?","bareme":[{"critere":"Souche pure (une seule espèce, colonie isolée) et vérification (colonies homogènes, un type de cellules)","points":6},{"critere":"Trois caractères morphologiques associés à leur technique","points":6},{"critere":"Catalase : bulles avec l’eau oxygénée, enzyme qui détruit H₂O₂","points":4},{"critere":"Oxydase : présence d’un cytochrome de la chaîne respiratoire","points":4}],"dureeMin":7,"corrige":"1. Une identification n’a de sens que sur **une seule espèce**, issue d’une **colonie isolée** : un mélange donnerait des résultats contradictoires. On vérifie la pureté par l’**aspect homogène des colonies** et la présence d’**un seul type de cellules au microscope**.\n\n2. Trois au choix : **aspect des colonies** (taille, forme, bord, couleur, surface) sur gélose ; **forme, groupement et mobilité** à l’**état frais** ; **Gram positif ou négatif** après **coloration de Gram**.\n\n3. On met la souche au contact d’**eau oxygénée** : des **bulles** (dégagement gazeux) signent la présence d’une **catalase**, enzyme qui **détruit H₂O₂** ; elle est présente chez la plupart des aérobies.\n\n4. Un test oxydase positif révèle la présence d’un **cytochrome de la chaîne respiratoire**."}$exo$::jsonb),
  ('68bcaab4-2f96-565f-ae7b-6ec058962bd0'::uuid, 2, 'application', $exo${"titre":"Une galerie à lire pour Mathis","consigne":"Interprète chaque résultat, puis établis le profil numérique en détaillant ton codage.","enonce":"**Situation.** Mathis a isolé une souche pure à partir d’un aliment. Premiers résultats : bacilles **Gram négatif**, **mobiles**, **oxydase négative**, **catalase positive**, glucose **fermenté avec gaz**, **nitrate réduit**.\n\nIl ensemence ensuite une galerie miniaturisée de 21 tests, lus par groupes de trois (valeurs 1, 2 et 4) :\n\n| Groupe | 1 | 2 | 3 | 4 | 5 | 6 | 7 |\n| Tests | + − + | + + − | − − − | + − − | + + + | − + + | − + − |\n\n**Extrait du catalogue :**\n| Profil | Identification |\n| 5 301 762 | espèce α — très bonne identification (99,5 %) |\n| 5 031 762 | espèce β — bonne identification (96 %) |\n\n1. À partir des premiers résultats, vers quelle famille Mathis peut-il s’orienter ? Quelle démarche d’identification a-t-il suivie ?\n2. Calcule le profil numérique de la galerie, groupe par groupe.\n3. Lis l’identification dans le catalogue. En quoi cette démarche est-elle différente de la première ?\n4. Pourquoi faut-il des témoins pour valider les réactifs de la galerie ?","bareme":[{"critere":"Orientation vers les entérobactéries par une démarche dichotomique","points":5},{"critere":"Profil numérique 5 301 762 calculé groupe par groupe","points":7},{"critere":"Espèce α lue, démarche probabiliste (base de données, pourcentage) distinguée","points":4},{"critere":"Témoins positif et négatif sur souches connues pour vérifier la réactivité","points":4}],"dureeMin":12,"corrige":"1. Bacilles Gram négatif, mobiles, oxydase négative, catalase positive, glucose fermenté avec gaz, nitrate réduit : on s’oriente vers les **entérobactéries**. C’est une démarche **dichotomique** : chaque test partage les possibilités en deux et oriente vers la **famille** ou le genre.\n\n2. Pour chaque groupe, on additionne les valeurs (1, 2, 4) des tests positifs :\n- groupe 1 (+ − +) : 1 + 4 = **5**\n- groupe 2 (+ + −) : 1 + 2 = **3**\n- groupe 3 (− − −) : **0**\n- groupe 4 (+ − −) : **1**\n- groupe 5 (+ + +) : 1 + 2 + 4 = **7**\n- groupe 6 (− + +) : 2 + 4 = **6**\n- groupe 7 (− + −) : **2**\nProfil : **5 301 762**.\n\n3. Le catalogue donne l’**espèce α**, avec une **très bonne identification (99,5 %)**. C’est une démarche **probabiliste** : le profil est comparé à une **base de données** et l’espèce est nommée avec un **pourcentage de certitude**, alors que la démarche dichotomique oriente seulement vers une famille ou un genre. (Le profil 5 031 762 de l’espèce β ne correspond pas : les groupes 2 et 3 sont inversés.)\n\n4. Un test sans témoin ne prouve rien : un résultat négatif pourrait venir d’un **réactif défectueux**, un positif d’une **réaction parasite**. On vérifie la réactivité des réactifs sur une **souche connue positive** et une **souche connue négative**."}$exo$::jsonb),
  ('68bcaab4-2f96-565f-ae7b-6ec058962bd0'::uuid, 3, 'application', $exo${"titre":"Deux souches isolées d’un sol","consigne":"Interprète chaque test, puis construis une conclusion argumentée sur la démarche à suivre.","enonce":"**Situation.** Au laboratoire, Aïcha isole deux souches d’un échantillon de sol et vérifie leur pureté.\n\n| Test | Souche S1 | Souche S2 |\n| Coloration de Gram | bacilles violets | bacilles roses |\n| Gélose profonde (type respiratoire) | culture uniquement en surface | culture sur toute la hauteur du tube |\n| Catalase | bulles | bulles |\n| Gélose à l’amidon révélée au lugol | halo clair autour des colonies | pas de halo, gélose bleu-noir partout |\n| Milieu glucosé avec indicateur de pH | virage vers l’acide | virage vers l’acide |\n| Auxanogramme | croissance sur glucose et sur amidon seulement | croissance sur glucose, lactose, citrate |\n\n1. Indique le résultat de la coloration de Gram pour chaque souche.\n2. Déduis de la gélose profonde le type respiratoire de S1. Que peux-tu dire de S2 à partir de ce seul test et de ce que révèle le cours sur les tests possibles ?\n3. Interprète le résultat sur gélose à l’amidon pour chaque souche. Pourquoi parle-t-on d’**exo-enzyme** ?\n4. Explique le virage de l’indicateur de pH, et le principe de l’auxanogramme.\n5. Aïcha affirme : « J’ai assez de résultats pour nommer l’espèce de S1. » Discute cette affirmation et propose la suite de la démarche, avec ses précautions.","bareme":[{"critere":"S1 Gram positif (violet), S2 Gram négatif (rose)","points":2},{"critere":"S1 aérobie strict ; S2 pousse dans tout le tube, compatible avec un type aéro-anaérobie","points":4},{"critere":"S1 sécrète une amylase (halo), S2 non ; exo-enzyme sécrétée hors de la cellule","points":5},{"critere":"Indicateur : métabolites acides issus des glucides ; auxanogramme : sources de carbone sur milieu synthétique","points":4},{"critere":"Démarche dichotomique insuffisante, galerie probabiliste avec témoins proposée","points":5}],"dureeMin":19,"corrige":"1. **S1** : bacilles violets → **Gram positif**. **S2** : bacilles roses → **Gram négatif**.\n\n2. **S1** ne pousse **qu’en surface** de la gélose profonde, là où il y a du dioxygène : elle est **aérobie stricte**. **S2** pousse sur **toute la hauteur**, y compris en profondeur sans O₂, comme en surface : ce résultat correspond à un type **aéro-anaérobie facultatif** (elle vit avec ou sans dioxygène).\n\n3. Sur la gélose à l’amidon, le lugol colore l’amidon en bleu-noir. Autour de S1, un **halo clair** : l’amidon a été hydrolysé → S1 sécrète une **amylase**. Autour de S2, pas de halo : **pas d’amylase sécrétée**. On parle d’**exo-enzyme** car l’enzyme est **sécrétée** hors de la cellule et hydrolyse une macromolécule dans le milieu ; son action se voit **autour de la colonie**.\n\n4. L’indicateur de pH vire à l’acide quand la dégradation du glucose produit des **métabolites acides**. L’**auxanogramme** teste **quelles sources de carbone permettent la croissance** sur un **milieu synthétique** : S1 n’utilise que le glucose et l’amidon, S2 utilise glucose, lactose et citrate.\n\n5. L’affirmation est **excessive**. Ces tests (Gram, type respiratoire, catalase, exo-enzyme) relèvent surtout d’une démarche **dichotomique** : ils **orientent vers une famille ou un genre**, sans nommer l’espèce avec certitude. Pour **nommer l’espèce**, il faut une démarche **probabiliste** : une **galerie** de tests miniaturisés dont le **profil numérique** est comparé à une **base de données**, qui donne un pourcentage de certitude. Précautions : partir d’une **souche pure** (déjà vérifiée) et valider les réactifs par des **témoins** positif et négatif sur des souches connues."}$exo$::jsonb),
  ('4c522328-b9f4-5090-93d1-4e4172fdd5d8'::uuid, 1, 'application', $exo${"titre":"Agglutiner ou précipiter","consigne":"Réponds en justifiant chaque résultat.","enonce":"1. Quelle différence de nature de l’antigène distingue une **agglutination** d’une **précipitation** ? Donne un exemple d’antigène pour chacune.\n2. Au groupage sanguin, on mélange les globules rouges de quatre personnes avec un sérum anti-A et un sérum anti-B.\n\n| Personne | Anti-A | Anti-B |\n| Paul | agglutination | pas d’agglutination |\n| Inès | pas d’agglutination | agglutination |\n| Léo | agglutination | agglutination |\n| Maya | pas d’agglutination | pas d’agglutination |\n\nDéduis le groupe sanguin (A, B, AB ou O) de chacun, en justifiant.\n3. Pourquoi les anticorps peuvent-ils relier plusieurs particules entre elles ?","bareme":[{"critere":"Antigène particulaire pour l’agglutination, soluble pour la précipitation, avec exemples","points":6},{"critere":"Quatre groupes justes et justifiés (Paul A, Inès B, Léo AB, Maya O)","points":10},{"critere":"Anticorps à deux bras reliant plusieurs particules en agglutinats","points":4}],"dureeMin":7,"corrige":"1. L’**agglutination** concerne un antigène **particulaire** (bactérie, globule rouge, bille de latex) ; la **précipitation** concerne un antigène **soluble** (une protéine dissoute, par exemple).\n\n2. Des globules rouges porteurs de l’antigène A s’agglutinent avec un sérum anti-A ; porteurs de B, avec un sérum anti-B.\n- **Paul** : agglutine seulement avec anti-A → antigène A seul → **groupe A**.\n- **Inès** : seulement avec anti-B → **groupe B**.\n- **Léo** : avec les deux → antigènes A et B → **groupe AB**.\n- **Maya** : avec aucun → ni A ni B → **groupe O**.\n\n3. Un anticorps possède **deux bras** portant chacun un paratope : il peut se fixer sur **deux particules à la fois**. De proche en proche, les particules sont reliées en **agglutinats visibles à l’œil nu**."}$exo$::jsonb),
  ('4c522328-b9f4-5090-93d1-4e4172fdd5d8'::uuid, 2, 'application', $exo${"titre":"Un ELISA à valider","consigne":"Décris la technique, puis interprète les résultats en commençant par les témoins.","enonce":"**Situation.** Un laboratoire recherche, par ELISA, des **anticorps** dirigés contre un virus dans le sérum de deux patients. Le puits est jugé positif si son absorbance dépasse **0,300**.\n\n**Plaque 1**\n| Puits | Absorbance |\n| Témoin négatif | 0,050 |\n| Témoin positif | 1,200 |\n| Patient Tom | 0,950 |\n| Patient Nora | 0,080 |\n\n**Plaque 2** (autre série, autre jour)\n| Puits | Absorbance |\n| Témoin négatif | 0,900 |\n| Témoin positif | 1,150 |\n| Patient Sami | 0,870 |\n\n1. Décris, dans l’ordre, les étapes de cet ELISA destiné à rechercher des anticorps du patient : ce qui est fixé au fond du puits, ce qu’on ajoute, le conjugué utilisé, la révélation.\n2. Explique le rôle du témoin positif et du témoin négatif.\n3. Interprète la plaque 1.\n4. Peut-on conclure pour Sami ? Propose une cause probable et le point critique en jeu.","bareme":[{"critere":"Étapes : antigène fixé, sérum, lavage, conjugué anti-immunoglobuline humaine couplé à une enzyme, lavage, substrat chromogène","points":6},{"critere":"Rôles des témoins positif (réactifs efficaces) et négatif (pas de réaction parasite)","points":4},{"critere":"Plaque 1 validée : Tom positif, Nora négative, justifiés par le seuil","points":5},{"critere":"Plaque 2 invalide (témoin négatif coloré), lavages insuffisants","points":5}],"dureeMin":11,"corrige":"1. - On **fixe l’antigène** viral au fond du puits.\n- On ajoute le **sérum du patient** : ses anticorps spécifiques, s’il en a, se fixent sur l’antigène. **Lavage.**\n- On ajoute un **conjugué anti-immunoglobuline humaine** (anticorps couplé à une **enzyme**), qui se fixe sur les anticorps du patient. **Lavage.**\n- On ajoute le **substrat chromogène** : l’enzyme le transforme en produit **coloré**, dont on mesure l’absorbance.\n\n2. Le **témoin positif** vérifie que **les réactifs fonctionnent** : il doit réagir. Le **témoin négatif** vérifie qu’**il n’y a pas de réaction parasite** : il ne doit pas réagir.\n\n3. Témoin négatif 0,050 < 0,300 (ne réagit pas) et témoin positif 1,200 > 0,300 (réagit) : la plaque est **validée**. **Tom** : 0,950 > 0,300 → **positif**, il possède des anticorps anti-virus. **Nora** : 0,080 < 0,300 → **négative**.\n\n4. **Non** : le témoin négatif (0,900) est **coloré**, la plaque est **invalide** et aucun résultat patient n’est interprétable. Cause probable : des **lavages insuffisants** — le conjugué resté libre a coloré tous les puits. Il faut refaire l’essai."}$exo$::jsonb),
  ('4c522328-b9f4-5090-93d1-4e4172fdd5d8'::uuid, 3, 'application', $exo${"titre":"Doser des immunoglobulines dans un sérum","consigne":"Exploite les données, pose tes calculs et justifie tes interprétations.","enonce":"**Document 1 — immunodiffusion radiale.** Un gel contient des anticorps dirigés contre une protéine P. On dépose dans des puits des solutions étalons de P et un sérum dilué au **1/4**. Après diffusion, on mesure le diamètre des anneaux.\n\n| Étalon de P (g·L⁻¹) | 0,5 | 1,0 | 2,0 | 4,0 |\n| Diamètre (mm) | 4,0 | 5,0 | 7,0 | 11,0 |\n\nSérum dilué au 1/4 : diamètre **8,0 mm**.\n\n**Document 2 — double diffusion d’Ouchterlony.** Un puits central contient un sérum anti-P. Deux puits périphériques contiennent deux extraits, E1 et E2. Les arcs de précipitation formés face à E1 et à E2 se rejoignent et **fusionnent** en un arc continu.\n\n1. Nomme les trois acteurs de l’immunodiffusion radiale (antigène, anticorps, système de révélation).\n2. Pourquoi l’anneau de précipité ne se forme-t-il pas au contact immédiat du puits, là où l’antigène est très concentré ?\n3. Montre que, sur ces étalons, le diamètre varie de façon linéaire avec la concentration. Détermine la concentration de P dans le sérum dilué, puis dans le sérum pur.\n4. Interprète le document 2.\n5. Cite un avantage de l’ELISA sur l’immunodiffusion pour un dosage, en t’appuyant sur la façon dont le signal est mesuré.","bareme":[{"critere":"Acteurs identifiés : P antigène soluble, anticorps dans le gel, anneau de précipitation","points":3},{"critere":"Précipité seulement à la zone d’équivalence, excès d’antigène empêchant le réseau","points":4},{"critere":"Linéarité montrée (+2 mm par g·L⁻¹), 2,5 g·L⁻¹ dilué et 10 g·L⁻¹ dans le sérum pur","points":7},{"critere":"Fusion des arcs interprétée : même antigène reconnu dans E1 et E2","points":3},{"critere":"ELISA : intensité de couleur mesurée au spectrophotomètre, dosage","points":3}],"dureeMin":18,"corrige":"1. **Antigène** : la protéine P (soluble), déposée dans le puits et qui diffuse. **Anticorps** : anti-P, **dans le gel**. **Révélation** : l’**anneau de précipitation** qui se forme autour du puits.\n\n2. Le précipité (réseau insoluble) n’apparaît qu’à la **zone d’équivalence**, là où antigène et anticorps sont en **proportions équivalentes**. Près du puits, l’antigène est **en excès** : le réseau ne peut pas se former. L’anneau se place plus loin, là où la concentration d’antigène a assez diminué.\n\n3. Entre deux étalons, le diamètre augmente de **2 mm par g·L⁻¹** : (5,0 − 4,0) / 0,5 = 2 ; (7,0 − 5,0) / 1,0 = 2 ; (11,0 − 7,0) / 2,0 = 2. La relation est linéaire : **d = 3,0 + 2,0 × c** (d en mm, c en g·L⁻¹).\nSérum dilué : 8,0 = 3,0 + 2,0 × c → c = 5,0 / 2,0 = **2,5 g·L⁻¹**.\nSérum pur (dilution au 1/4) : 2,5 × 4 = **10 g·L⁻¹**.\n\n4. Les arcs formés face à E1 et E2 **fusionnent** : les deux extraits contiennent **le même antigène**, reconnu par le même sérum anti-P (en double diffusion, un croisement des arcs aurait au contraire signalé des antigènes différents).\n\n5. En ELISA, le signal est une **couleur** produite par l’enzyme du conjugué, dont l’**intensité est mesurée au spectrophotomètre** : on obtient une valeur numérique qui permet de **doser**, en microplaque, sans attendre la diffusion ni mesurer un anneau à la règle."}$exo$::jsonb),
  ('5d52c5a0-de5d-57f3-a573-90603f89a10d'::uuid, 1, 'application', $exo${"titre":"Substrat ou activité : deux logiques de dosage","consigne":"Réponds de façon précise, avec les unités.","enonce":"1. Dans un dosage de **substrat en point final**, qu’est-ce qui est en excès et qu’est-ce qui est limitant ? Même question pour un dosage d’**activité enzymatique**.\n2. Définis l’**unité internationale U** et la **concentration d’activité** b (avec son unité).\n3. Convertis une activité de 6,0 U en nkat.\n4. Pourquoi thermostate-t-on une mesure d’activité enzymatique ?","bareme":[{"critere":"Point final : enzymes en excès, substrat limitant ; activité : substrat en excès, enzyme limitante","points":8},{"critere":"1 U = 1 µmol·min⁻¹ ; b = activité par unité de volume en U·L⁻¹","points":5},{"critere":"Conversion juste : 6,0 U ≈ 100 nkat","points":4},{"critere":"Thermostatisation : l’activité dépend de la température","points":3}],"dureeMin":7,"corrige":"1. - **Substrat en point final** : les **enzymes** (et les autres réactifs) sont **en excès** ; le **substrat à doser est limitant**, entièrement transformé.\n- **Activité enzymatique** : le **substrat est en excès** (saturant) ; l’**enzyme est limitante**.\n\n2. **1 U = 1 µmol de substrat transformé par minute** (µmol·min⁻¹). La **concentration d’activité b** est l’activité **par unité de volume d’échantillon**, en **U·L⁻¹** (ou kat·L⁻¹).\n\n3. 1 U ≈ 16,67 nkat → 6,0 × 16,67 ≈ **100 nkat**.\n\n4. Parce que l’**activité d’une enzyme dépend de la température** : pour que la mesure soit juste et comparable, on la fixe au plus près de l’optimum (de même, le pH est fixé par un tampon)."}$exo$::jsonb),
  ('5d52c5a0-de5d-57f3-a573-90603f89a10d'::uuid, 2, 'application', $exo${"titre":"La glycémie de M. Petit par la méthode GOD-POD","consigne":"Explique la méthode, puis calcule en posant la formule littérale avant l’application numérique.","enonce":"**Situation.** Au laboratoire d’analyses, Julia dose le glucose du plasma de M. Petit par la méthode GOD-POD, avec un étalon unique (linéarité vérifiée).\n\n> Glucose + O₂ → (GOD) → acide gluconique + H₂O₂\n> 2 H₂O₂ + chromogène → (POD) → chromophore rose + 4 H₂O\n\n| Tube | Blanc réactif | Étalon | Essai |\n| Eau distillée (µL) | 10 | — | — |\n| Étalon de glucose à 5,55 mmol·L⁻¹ (µL) | — | 10 | — |\n| Plasma (µL) | — | — | 10 |\n| Réactif GOD-POD (mL) | 1,0 | 1,0 | 1,0 |\n| Absorbance à 505 nm (zéro sur le blanc) | 0 | 0,420 | 0,378 |\n\n1. Identifie la réaction principale et la réaction indicatrice, ainsi que la molécule limitante.\n2. Quelle est la stœchiométrie entre le glucose et le chromophore ?\n3. À quoi sert le tube « blanc réactif » ?\n4. Calcule la concentration en glucose du plasma de M. Petit.","bareme":[{"critere":"Réaction principale (GOD) et indicatrice (POD), glucose limitant, enzymes en excès","points":5},{"critere":"Stœchiométrie : 2 glucoses pour 1 chromophore, justifiée","points":4},{"critere":"Blanc réactif : régler le zéro sans substrat à doser","points":3},{"critere":"c(essai) = c(étalon) × A(essai) / A(étalon) = 5,00 mmol·L⁻¹","points":8}],"dureeMin":11,"corrige":"1. **Réaction principale** : celle de la **GOD**, qui transforme le substrat à doser (glucose). **Réaction indicatrice** : celle de la **POD**, qui produit la molécule mesurée, le **chromophore rose** (à partir du chromogène). Le **glucose est la molécule limitante** ; les enzymes et les autres réactifs sont **en excès**, la réaction va à son **point final**.\n\n2. 1 glucose donne 1 H₂O₂ ; il faut 2 H₂O₂ pour 1 chromophore : **2 glucoses pour 1 chromophore**.\n\n3. Le blanc réactif contient tout sauf le glucose (eau à la place) : il sert à **régler le zéro d’absorbance**, pour ne mesurer que la couleur due au glucose.\n\n4. Étalon unique, linéarité vérifiée (loi de Beer-Lambert), mêmes volumes dans l’étalon et l’essai :\nc(essai) = c(étalon) × A(essai) / A(étalon)\nc(essai) = 5,55 × 0,378 / 0,420 = 5,55 × 0,900 = **5,00 mmol·L⁻¹** (4,995 arrondi à trois chiffres significatifs)."}$exo$::jsonb),
  ('5d52c5a0-de5d-57f3-a573-90603f89a10d'::uuid, 3, 'application', $exo${"titre":"Une activité phosphatase à mesurer sans se tromper de pente","consigne":"Exploite la cinétique, pose chaque calcul (formule, application numérique, unité) et justifie tes choix.","enonce":"**Situation.** Karim mesure l’activité d’une phosphatase dans un sérum. Le substrat est en excès ; le produit absorbe à 405 nm (ε = 18 500 L·mol⁻¹·cm⁻¹, ℓ = 1 cm). Volume réactionnel : **2,0 mL** ; prise d’essai de sérum : **0,050 mL**. Cuve thermostatée à 37 °C.\n\n| t (min) | 0 | 0,5 | 1,0 | 1,5 | 2,0 | 2,5 | 3,0 |\n| A₄₀₅ | 0,200 | 0,245 | 0,290 | 0,335 | 0,375 | 0,405 | 0,425 |\n\n1. Délimite la **période initiale** en justifiant par les écarts d’absorbance.\n2. Calcule ΔA/Δt sur la période initiale.\n3. Calcule la vitesse dans la cuve (en µmol·L⁻¹·min⁻¹), puis la quantité de produit formée par minute dans la cuve.\n4. Calcule la concentration d’activité b du sérum en U·L⁻¹, puis convertis-la en µkat·L⁻¹.\n5. Un collègue applique la méthode « deux points » avec les mesures à 0 et 3,0 min. Calcule la pente qu’il obtient et explique le problème.","bareme":[{"critere":"Période initiale de 0 à 1,5 min justifiée (écarts constants de 0,045)","points":3},{"critere":"ΔA/Δt = 0,090 min⁻¹","points":3},{"critere":"Vitesse ≈ 4,86 µmol·L⁻¹·min⁻¹ et ≈ 9,7 × 10⁻³ µmol·min⁻¹ dans 2,0 mL","points":5},{"critere":"b ≈ 195 U·L⁻¹ puis ≈ 3,2 µkat·L⁻¹","points":5},{"critere":"Pente 0,075 min⁻¹ hors période initiale : activité sous-estimée","points":4}],"dureeMin":20,"corrige":"1. Écarts entre deux mesures successives : 0,045 ; 0,045 ; 0,045 ; puis 0,040 ; 0,030 ; 0,020. Les écarts sont **constants de 0 à 1,5 min** : c’est la **période initiale** (courbe linéaire). Ensuite, la vitesse diminue.\n\n2. ΔA/Δt = (0,335 − 0,200) / (1,5 − 0) = 0,135 / 1,5 = **0,090 min⁻¹**.\n\n3. Loi de Beer-Lambert : Δc/Δt = (ΔA/Δt) / (ε × ℓ) = 0,090 / (18 500 × 1) = 4,86 × 10⁻⁶ mol·L⁻¹·min⁻¹ = **4,86 µmol·L⁻¹·min⁻¹**.\nDans 2,0 mL = 2,0 × 10⁻³ L : 4,86 × 2,0 × 10⁻³ = **9,73 × 10⁻³ µmol·min⁻¹**, soit 9,73 × 10⁻³ U, apportés par 0,050 mL de sérum.\n\n4. b = activité / volume de sérum = 9,73 × 10⁻³ / (0,050 × 10⁻³) ≈ **195 U·L⁻¹**.\nConversion : 195 × 16,67 ≈ 3 250 nkat·L⁻¹ ≈ **3,2 µkat·L⁻¹**.\n\n5. Pente « deux points » : (0,425 − 0,200) / 3,0 = 0,225 / 3,0 = **0,075 min⁻¹**, au lieu de 0,090. La mesure à 3,0 min est **hors de la période initiale** : la vitesse a déjà chuté, l’activité est **sous-estimée** (d’environ 17 %). La méthode deux points n’est valable que si les deux mesures sont **dans la période initiale**."}$exo$::jsonb),
  ('54e2455c-b030-5cf3-b502-0efcb0d8826c'::uuid, 1, 'application', $exo${"titre":"Culot, filtrat et migration","consigne":"Réponds à chaque question avec le vocabulaire exact du cours.","enonce":"1. Après une **centrifugation**, comment s’appellent les deux fractions obtenues ? Où se trouvent les éléments les plus denses ?\n2. Après une **filtration**, comment s’appellent ce qui est retenu et ce qui passe ?\n3. Une protéine a un pHi de 5,0. Dans quel sens migre-t-elle lors d’une électrophorèse dans un tampon à pH 8,6 ? Et à pH 5,0 ? Justifie.\n4. En électrophorèse sur gel d’agarose, selon quel critère les fragments d’ADN se séparent-ils ? Lesquels vont le plus loin ?","bareme":[{"critere":"Culot (éléments denses) et surnageant","points":4},{"critere":"Rétentat et filtrat","points":4},{"critere":"pH 8,6 : protéine négative, vers l’anode ; pH 5,0 : pas de migration","points":7},{"critere":"ADN séparé selon la taille, petits fragments plus loin","points":5}],"dureeMin":6,"corrige":"1. Les éléments les plus denses forment le **culot**, au fond du tube ; le liquide au-dessus est le **surnageant**.\n\n2. Ce qui est retenu par le filtre est le **rétentat** ; ce qui passe est le **filtrat**.\n\n3. - À **pH 8,6**, supérieur au pHi (5,0), la protéine est chargée **négativement** : elle migre vers l’**anode** (+).\n- À **pH 5,0**, égal à son pHi, elle **ne migre pas**.\n\n4. Les fragments d’ADN migrent tous vers l’anode et se séparent selon leur **taille** : les **plus petits vont le plus loin**."}$exo$::jsonb),
  ('54e2455c-b030-5cf3-b502-0efcb0d8826c'::uuid, 2, 'application', $exo${"titre":"Le tableau de purification de Sarah","consigne":"Complète le tableau en détaillant un calcul de chaque type, puis justifie ta conclusion.","enonce":"**Situation.** Sarah purifie une enzyme à partir d’un broyat de foie. À chaque étape, elle mesure l’activité totale et la masse de protéines totales.\n\n| Étape | Activité totale (U) | Protéines totales (mg) | Activité spécifique (U·mg⁻¹) | Rendement (%) | Enrichissement |\n| Extrait brut | 400 | 500 | … | 100 | 1 |\n| Précipitation | 300 | 150 | … | … | … |\n| Échange d’ions | 240 | 20 | … | … | … |\n| Affinité | 180 | 3 | … | … | … |\n\n1. Rappelle les formules de l’activité spécifique, du rendement et de l’enrichissement.\n2. Complète le tableau.\n3. Quelle étape a le plus augmenté la pureté de l’enzyme par rapport à l’étape précédente ? Justifie.\n4. Sarah a perdu plus de la moitié de l’activité. La purification est-elle pour autant réussie ? Argumente.","bareme":[{"critere":"Trois formules justes","points":4},{"critere":"Activités spécifiques justes (0,8 ; 2 ; 12 ; 60 U·mg⁻¹)","points":5},{"critere":"Rendements (75, 60, 45 %) et enrichissements (2,5 ; 15 ; 75) justes","points":6},{"critere":"Étape la plus efficace (échange d’ions, ×6) et conclusion argumentée sur le compromis","points":5}],"dureeMin":12,"corrige":"1. - **Activité spécifique** = activité totale / masse de protéines totales.\n- **Rendement** = activité totale à l’étape / activité totale de départ × 100.\n- **Enrichissement** = activité spécifique à l’étape / activité spécifique de départ.\n\n2.\n| Étape | AS (U·mg⁻¹) | Rendement | Enrichissement |\n| Extrait brut | 400 / 500 = **0,8** | 100 % | 1 |\n| Précipitation | 300 / 150 = **2** | 300 / 400 = **75 %** | 2 / 0,8 = **2,5** |\n| Échange d’ions | 240 / 20 = **12** | **60 %** | 12 / 0,8 = **15** |\n| Affinité | 180 / 3 = **60** | **45 %** | 60 / 0,8 = **75** |\n\n3. Par rapport à l’étape précédente, l’activité spécifique est multipliée par 2 / 0,8 = 2,5 (précipitation), 12 / 2 = **6 (échange d’ions)** et 60 / 12 = 5 (affinité). C’est l’**échange d’ions** qui a le plus augmenté la pureté d’une étape à l’autre (l’affinité fait presque autant, en ne perdant que 60 U).\n\n4. Oui : une bonne purification **augmente l’activité spécifique** en retirant des protéines inutiles, tout en perdant le moins d’activité possible. Ici, on garde **45 %** de l’activité, mais l’enzyme est **75 fois plus pure** (500 mg de protéines ramenés à 3 mg). Perdre de l’activité est inévitable ; le compromis est bon."}$exo$::jsonb),
  ('54e2455c-b030-5cf3-b502-0efcb0d8826c'::uuid, 3, 'application', $exo${"titre":"Séparer trois protéines","consigne":"Raisonne à partir des propriétés de chaque protéine et justifie chaque prévision par le critère de séparation.","enonce":"**Situation.** Un surnageant de broyat contient trois protéines :\n\n| Protéine | Masse moléculaire (kDa) | pHi |\n| P1 | 150 | 6,0 |\n| P2 (l’enzyme recherchée) | 60 | 4,5 |\n| P3 | 15 | 9,0 |\n\nLes pores de la résine d’exclusion laissent entrer les protéines de moins de 100 kDa.\n\n1. Avant de travailler sur le surnageant, pourquoi faut-il vérifier dans quelle fraction se trouve l’enzyme après la centrifugation ?\n2. On passe le mélange sur une colonne d’**exclusion**. Dans quel ordre sortent les trois protéines ? Justifie.\n3. Électrophorèse dans un tampon à pH 7,0 : prévois le sens de migration de chaque protéine.\n4. Colonne **échangeuse d’ions** à résine chargée positivement, tampon à pH 7,0 : quelle(s) protéine(s) sort(ent) en premier ? Lesquelles sont retenues ?\n5. On dispose d’un ligand qui se lie spécifiquement à P2. Explique le principe de la chromatographie d’affinité et montre pourquoi elle est la plus adaptée pour obtenir P2 en quantité. De quel type de chromatographie s’agit-il alors ?","bareme":[{"critere":"Vérifier la fraction : ne rien jeter avant d’avoir contrôlé où est l’enzyme","points":2},{"critere":"Exclusion : P1 d’abord (n’entre pas dans les pores), puis P2, puis P3","points":5},{"critere":"pH 7 : P1 et P2 négatives vers l’anode, P3 positive vers la cathode","points":5},{"critere":"Échange d’ions : P3 (même charge que la résine) sort d’abord, P1 et P2 retenues","points":4},{"critere":"Affinité : liaison spécifique au ligand, P2 décrochée ensuite ; chromatographie préparative","points":4}],"dureeMin":18,"corrige":"1. Après centrifugation, l’enzyme peut se trouver dans le **culot** ou dans le **surnageant** : il faut vérifier (par une mesure d’activité) où elle se trouve **avant de jeter** une fraction.\n\n2. En exclusion, les **grosses molécules** n’entrent pas dans les pores et sortent **en premier** ; les petites parcourent les pores et sont retardées. Ordre : **P1 (150 kDa)**, qui n’entre pas dans les pores, puis **P2 (60 kDa)**, puis **P3 (15 kDa)**.\n\n3. À pH 7,0 :\n- **P1** (pHi 6,0 < 7,0) : chargée **négativement** → vers l’**anode**.\n- **P2** (pHi 4,5 < 7,0) : **négative** → vers l’**anode**.\n- **P3** (pHi 9,0 > 7,0) : **positive** → vers la **cathode**.\n\n4. Sortent en premier les molécules de **même charge que la résine** (ou neutres) : **P3**, positive comme la résine, n’est pas retenue. **P1 et P2**, négatives, se fixent sur la résine positive et sont **retenues**.\n\n5. En **affinité**, un **ligand** fixé sur la phase fixe se lie **spécifiquement** à P2 : toutes les autres protéines sortent, puis on **décroche P2**. Le critère n’est ni la taille ni la charge, mais une **liaison spécifique** : P2 est séparée en une étape de protéines de taille ou de charge voisines. Utilisée pour **récupérer P2 en quantité**, c’est une chromatographie **préparative**."}$exo$::jsonb),
  ('f53b35e2-4bb8-57f0-a8b9-26eb30832d54'::uuid, 1, 'application', $exo${"titre":"Extraire et contrôler une solution d’ADN","consigne":"Réponds de façon précise ; pose les calculs avec les unités.","enonce":"1. Cite dans l’ordre les étapes de la préparation d’une solution d’ADN et le rôle de chacune.\n2. Pourquoi travaille-t-on avec des gants et du matériel stérile ?\n3. Une solution d’ADN double brin donne **A₂₆₀ = 0,45** et **A₂₈₀ = 0,25**. Calcule sa concentration en ADN et le rapport A₂₆₀/A₂₈₀. Conclus sur sa pureté.","bareme":[{"critere":"Quatre étapes dans l’ordre avec leur rôle (lyse, déprotéinisation, précipitation, contrôle)","points":8},{"critere":"Gants et stérilité : éviter nos nucléases et notre ADN","points":4},{"critere":"Concentration 22,5 µg·mL⁻¹, rapport 1,8 et ADN pur","points":8}],"dureeMin":8,"corrige":"1. - **Lyse cellulaire** : un détergent détruit les membranes.\n- **Déprotéinisation** : une protéase (et/ou du sel) élimine les protéines, dont les **nucléases** qui dégraderaient l’ADN.\n- **Précipitation** à l’**éthanol froid** : l’ADN, insoluble dans l’alcool, forme une pelote qu’on récupère.\n- **Contrôle** au spectrophotomètre (concentration et pureté).\n\n2. Nos propres **nucléases** dégraderaient l’ADN, et **notre ADN** contaminerait l’échantillon.\n\n3. Concentration : 1 unité d’absorbance à 260 nm ≈ 50 µg·mL⁻¹ d’ADN double brin → c = 0,45 × 50 = **22,5 µg·mL⁻¹**.\nPureté : A₂₆₀/A₂₈₀ = 0,45 / 0,25 = **1,8** : valeur d’un **ADN pur** (pas de contamination notable par des protéines)."}$exo$::jsonb),
  ('f53b35e2-4bb8-57f0-a8b9-26eb30832d54'::uuid, 2, 'application', $exo${"titre":"Une PCR à interpréter","consigne":"Explique la technique, calcule, puis interprète le gel en commençant par les témoins.","enonce":"**Situation.** Pour rechercher un gène bactérien dans un aliment, Élise réalise une PCR de **25 cycles** qui doit produire un amplicon de **500 pb**.\n\n1. Donne la composition du mélange réactionnel de PCR.\n2. Décris les trois étapes d’un cycle avec leur température et ce qui se passe.\n3. Qu’est-ce qui détermine la région copiée ?\n4. Partant de 100 molécules d’ADN matrice, combien de copies obtient-on au maximum après 25 cycles ?\n5. Élise dépose ses produits sur un gel d’agarose avec un marqueur de taille.\n\n| Puits | Bande observée |\n| Marqueur | bandes de 100 à 1 000 pb |\n| Témoin négatif (sans ADN) | aucune |\n| Témoin positif | une bande à 500 pb |\n| Échantillon A | une bande à 500 pb |\n| Échantillon B | aucune |\n\nInterprète ce gel.","bareme":[{"critere":"Mélange : ADN matrice, deux amorces, dNTP, polymérase thermostable, tampon avec Mg²⁺","points":4},{"critere":"Dénaturation ~95 °C, hybridation ~50–65 °C, élongation 72 °C, décrites","points":5},{"critere":"Amorces responsables de la spécificité","points":2},{"critere":"100 × 2²⁵ ≈ 3,4 × 10⁹ copies","points":4},{"critere":"Témoins validés, A contient le gène, B ne le contient pas (ou sous le seuil détectable)","points":5}],"dureeMin":12,"corrige":"1. **ADN matrice**, **deux amorces** qui encadrent la séquence cible, des **dNTP**, une **ADN polymérase thermostable** (Taq) et un **tampon avec Mg²⁺**.\n\n2. - **Dénaturation** (~**95 °C**) : les deux brins se séparent.\n- **Hybridation** des amorces (~**50 à 65 °C**) : les amorces se fixent par complémentarité.\n- **Élongation** (**72 °C**) : la polymérase synthétise le brin complémentaire.\n\n3. Les **amorces** : elles font la **spécificité** de la PCR en décidant quelle région est copiée.\n\n4. Après n cycles, jusqu’à 2ⁿ copies par molécule matrice : 100 × 2²⁵ = 100 × 33 554 432 ≈ **3,4 × 10⁹ copies**.\n\n5. Le **témoin négatif** ne donne aucune bande : **pas de contamination**. Le **témoin positif** donne la bande attendue à 500 pb : **le mélange fonctionne**. Les témoins sont validés.\n- **Échantillon A** : bande à **500 pb** (taille lue grâce au marqueur) → l’aliment **contient le gène recherché**.\n- **Échantillon B** : aucune bande → le gène **n’est pas détecté**."}$exo$::jsonb),
  ('f53b35e2-4bb8-57f0-a8b9-26eb30832d54'::uuid, 3, 'application', $exo${"titre":"Faire fabriquer une protéine humaine par des bactéries","consigne":"Raisonne étape par étape, pose les calculs et argumente la partie éthique.","enonce":"**Situation.** Une entreprise veut faire produire une protéine humaine par des bactéries.\n\n**Document 1.** Le vecteur est un plasmide circulaire de **4 500 pb**. Il possède deux sites EcoRI (G↓AATTC), aux positions **1 000** et **2 200**. Il porte une origine de réplication, un promoteur, un gène de résistance à l’ampicilline et un gène rapporteur interrompu par le site de clonage.\n\n**Document 2.** Le gène humain est porté par un fragment d’ADN **linéaire** de **6 000 pb**, coupé par EcoRI aux positions **1 500**, **2 500** et **4 000**.\n\n1. EcoRI laisse des **bouts collants**. Explique ce terme et l’intérêt de couper le vecteur et le gène avec la même enzyme.\n2. Combien de fragments obtient-on en digérant le plasmide ? Donne leur taille.\n3. Même question pour l’ADN linéaire du document 2. Combien de bandes verra-t-on sur un gel ? Justifie.\n4. Décris les étapes du clonage, de la digestion à la sélection, en nommant l’enzyme qui soude le gène.\n5. Des colonies poussent sur un milieu à l’ampicilline. Portent-elles toutes le plasmide recombinant ? Comment le vérifier ?\n6. Cite deux questions de bioéthique que posent ces technologies de l’ADN.","bareme":[{"critere":"Bouts collants (coupure décalée) qui se réassocient avec un fragment coupé par la même enzyme","points":3},{"critere":"Plasmide : 2 fragments de 1 200 et 3 300 pb","points":4},{"critere":"ADN linéaire : 4 fragments (1 500, 1 000, 1 500, 2 000 pb) et 3 bandes","points":4},{"critere":"Étapes du clonage ordonnées avec ligase, bactéries compétentes, sélection ; vérification par gène rapporteur ou PCR sur colonie","points":6},{"critere":"Deux questions de bioéthique pertinentes","points":3}],"dureeMin":20,"corrige":"1. EcoRI coupe les deux brins de façon **décalée** : chaque extrémité garde une courte partie simple brin, les **bouts collants**. Deux fragments coupés **par la même enzyme** ont des bouts complémentaires, qui **se réassocient facilement** : le gène peut s’insérer dans le vecteur ouvert.\n\n2. Sur un ADN **circulaire**, n sites donnent **n fragments** : 2 sites → **2 fragments**.\n- De 1 000 à 2 200 : 2 200 − 1 000 = **1 200 pb** ;\n- le reste du cercle : 4 500 − 1 200 = **3 300 pb**.\n\n3. Sur un ADN **linéaire**, n sites donnent **n + 1 fragments** : 3 sites → **4 fragments** : 0–1 500 = **1 500 pb** ; 1 500–2 500 = **1 000 pb** ; 2 500–4 000 = **1 500 pb** ; 4 000–6 000 = **2 000 pb**. Les deux fragments de 1 500 pb ont la **même taille** et migrent ensemble : on voit **3 bandes** (2 000, 1 500 et 1 000 pb).\n\n4. **Digestion** du vecteur et du gène par la même enzyme → **ligation** : la **ligase** soude le gène dans le plasmide → **transformation** : des **bactéries compétentes** absorbent le plasmide → **sélection** sur un milieu contenant l’**ampicilline** : seules les bactéries transformées poussent. Le **promoteur** du vecteur permet ensuite l’expression du gène.\n\n5. **Non** : une bactérie qui pousse sur l’ampicilline a reçu **un plasmide**, mais **pas forcément le plasmide recombinant** (le plasmide a pu se refermer sans le gène). On vérifie avec le **gène rapporteur** : interrompu par l’insertion du gène, il ne s’exprime plus chez les recombinants ; ou par une **PCR sur colonie**.\n\n6. Deux au choix : protection des **données génétiques personnelles** ; **consentement** des personnes ; **modification du génome humain** (thérapie génique) ; encadrement des **OGM** ; ces questions sont encadrées en France par les **lois de bioéthique**."}$exo$::jsonb),
  ('909b428e-56d4-5fee-a203-ad88d20f1681'::uuid, 1, 'application', $exo${"titre":"Connaître son épreuve","consigne":"Réponds à chaque question par une phrase précise.","enonce":"1. Combien de coefficients compte l’épreuve de spécialité biochimie-biologie-biotechnologie ? Comment se répartissent-ils entre la partie écrite et la partie pratique ? Quelle est la durée de chacune ?\n2. Décris les deux temps de l’écrit : nature, support et durée indicative.\n3. Combien de points compte la maîtrise de la langue à l’écrit ?\n4. Cite trois compétences évaluées pendant l’ECE.","bareme":[{"critere":"16 coefficients : écrit 7, pratique 9, 3 h chacune","points":6},{"critere":"Questionnements sur 6 à 9 documents (2 h 30) puis question de synthèse (30 min)","points":6},{"critere":"Maîtrise de la langue sur 2 points","points":2},{"critere":"Trois compétences de l’ECE citées","points":6}],"dureeMin":6,"corrige":"1. **16 coefficients** : la partie **écrite** compte pour **7**, la partie **pratique (ECE)** pour **9** ; chacune dure **3 h** et est notée sur 20.\n\n2. - **Questionnements scientifiques et technologiques** (~**2 h 30**) sur **6 à 9 documents** autour d’une problématique de biotechnologie : analyser, calculer, interpréter, argumenter.\n- **Question de synthèse** (~**30 minutes**) : un paragraphe court et argumenté, en lien avec la première partie.\n\n3. **2 points sur 20**.\n\n4. Trois au choix : analyser une procédure (sources d’erreurs, choix du matériel) ; identifier les **dangers**, évaluer les risques, choisir la **prévention** ; **réaliser** en autonomie ; effectuer les calculs avec les **outils numériques** ; exprimer les résultats avec leur **dimension métrologique** ; **interpréter** les résultats."}$exo$::jsonb),
  ('909b428e-56d4-5fee-a203-ad88d20f1681'::uuid, 2, 'application', $exo${"titre":"Ce que vaut l’ECE dans la note de Noah","consigne":"Pose tes calculs, puis justifie tes conseils à l’aide du cours.","enonce":"**Situation.** Noah prépare l’épreuve de spécialité. Aux épreuves blanches, il a obtenu **11/20 à l’écrit** et **14,5/20 à l’ECE**.\n\n1. Calcule la moyenne de Noah sur l’épreuve, en pondérant chaque partie par son coefficient.\n2. Son amie Lila a obtenu 9/20 à l’écrit. Quelle note minimale doit-elle obtenir à l’ECE pour atteindre 12/20 de moyenne sur l’épreuve ? Arrondis au centième.\n3. Que montrent ces calculs sur le poids de la partie pratique ?\n4. Le sujet d’ECE de Noah comporte : une incubation de 30 min à 37 °C, une lecture de cinétique, des calculs, la rédaction des résultats. Dans quel ordre doit-il s’organiser ? Cite aussi deux habitudes à prendre pendant l’épreuve.","bareme":[{"critere":"Moyenne pondérée juste : 207,5 / 16 ≈ 12,97","points":6},{"critere":"Note minimale de Lila ≈ 14,33/20, calcul posé","points":6},{"critere":"Poids de la pratique (9 sur 16) expliqué","points":3},{"critere":"Planification (lancer l’incubation d’abord) et deux habitudes justes","points":5}],"dureeMin":11,"corrige":"1. Moyenne = (11 × 7 + 14,5 × 9) / 16 = (77 + 130,5) / 16 = 207,5 / 16 ≈ **12,97/20**.\n\n2. On cherche x tel que (9 × 7 + x × 9) / 16 = 12 → 63 + 9x = 192 → 9x = 129 → x = 129 / 9 ≈ **14,33/20**.\n\n3. La partie pratique compte pour **9 coefficients sur 16**, plus que l’écrit (7) : une bonne ECE peut compenser un écrit moyen. Les **gestes du laboratoire** comptent autant que les connaissances.\n\n4. Noah doit **lire tout le sujet et planifier**, puis **lancer d’abord ce qui demande du temps** : l’**incubation** de 30 min, puis la **cinétique** ; il fera les **calculs** et la **rédaction** pendant les temps d’attente ou à la fin.\nHabitudes (deux au choix) : annoncer ses mesures de **prévention avant d’agir** (gants, lunettes, poste de sécurité microbiologique, déchets) ; placer systématiquement les **témoins** et les justifier ; **noter au propre chaque résultat brut avec son unité** ; comparer son résultat à une **valeur de référence** avec l’incertitude."}$exo$::jsonb),
  ('909b428e-56d4-5fee-a203-ad88d20f1681'::uuid, 3, 'application', $exo${"titre":"Corriger une copie avant le bac","consigne":"Analyse chaque réponse d’élève au regard de la méthode attendue, puis réécris-la. Justifie chaque critique.","enonce":"**Situation.** Pendant une épreuve blanche, Zoé a répondu aux questions suivantes.\n\n**Question 1.** *Document 4 : l’activité d’une enzyme vaut 60 U·L⁻¹ à 25 °C et 95 U·L⁻¹ à 37 °C. Quelle température choisir pour le dosage ?*\n> Réponse de Zoé : « Il faut choisir la bonne température, car l’activité d’une enzyme dépend de la température. »\n\n**Question 2.** *Calculer la concentration d’activité b, sachant que l’activité mesurée dans la cuve est de 8,1 × 10⁻³ U, apportée par 0,10 mL d’échantillon.*\n> Réponse de Zoé : « b = 81,00000 »\n\n**Question 3.** *Le résultat obtenu est b = 81 U·L⁻¹, avec une incertitude de 4 U·L⁻¹. La valeur de référence de l’échantillon est 85 U·L⁻¹. Conclure.*\n> Réponse de Zoé : « Le résultat est faux car 81 est différent de 85. »\n\n1. Pour chaque réponse, identifie ce qui manque ou ce qui est faux, en t’appuyant sur la méthode de l’écrit.\n2. Réécris chacune des trois réponses comme l’attend le correcteur.\n3. Pourquoi la réponse 1 de Zoé ne rapporterait-elle presque rien, bien qu’elle soit exacte ?\n4. Zoé garde 10 minutes pour la question de synthèse. Explique pourquoi c’est insuffisant et comment elle doit la rédiger.","bareme":[{"critere":"Critiques justes : réponse 1 sans exploitation du document, réponse 2 sans formule ni unité, réponse 3 sans incertitude","points":6},{"critere":"Réponse 1 réécrite : citation du document, valeurs, conclusion (37 °C)","points":3},{"critere":"Réponse 2 réécrite : formule littérale, application numérique, 81 U·L⁻¹ avec chiffres significatifs adaptés","points":4},{"critere":"Réponse 3 réécrite : 81 ± 4 U·L⁻¹ contient 85, résultat compatible","points":4},{"critere":"Synthèse : 30 minutes, paragraphe argumenté, une idée par phrase reliée à la problématique","points":3}],"dureeMin":18,"corrige":"1. - **Réponse 1** : exacte mais **générale** ; Zoé **ne cite pas le document**, n’utilise aucune valeur et **ne conclut pas** (quelle température ?).\n- **Réponse 2** : **pas de formule littérale**, pas d’application numérique, **pas d’unité**, et un nombre de chiffres **non significatif** (81,00000).\n- **Réponse 3** : **conclusion fausse** : elle oublie la **dimension métrologique** ; un résultat se compare à la référence **avec son incertitude**.\n\n2. - **Réponse 1** : « D’après le document 4, l’activité est plus élevée à 37 °C (95 U·L⁻¹) qu’à 25 °C (60 U·L⁻¹). On choisit donc **37 °C** pour le dosage. »\n- **Réponse 2** : « b = activité / volume d’échantillon = 8,1 × 10⁻³ U / (0,10 × 10⁻³ L) = **81 U·L⁻¹**. » (deux chiffres significatifs, comme les données)\n- **Réponse 3** : « b = 81 ± 4 U·L⁻¹, soit un intervalle de 77 à 85 U·L⁻¹. La valeur de référence, 85 U·L⁻¹, est dans cet intervalle : le résultat est **compatible** avec la référence. »\n\n3. Réciter le cours **sans l’appliquer aux documents** ne rapporte presque rien : le correcteur attend une **exploitation** — citer le document, en tirer l’information utile, puis **conclure**.\n\n4. La synthèse a une durée indicative de **30 minutes** : il faut la **garder dans son temps**. Elle se rédige en un **paragraphe court, argumenté**, scientifique, technologique ou sociétal, en lien avec la première partie : **une idée par phrase**, chacune **reliée à la problématique**, dans une langue soignée (la maîtrise de la langue compte pour 2 points)."}$exo$::jsonb),
  ('0ad50bc5-e1af-5ffd-a692-3490df7f87f1'::uuid, 1, 'application', $exo${"titre":"Le coussin gonflable de la voiture d'Inès","consigne":"Réponds à chaque question en écrivant la formule littérale avant de remplacer par les valeurs, et donne chaque résultat avec son unité.","enonce":"**Situation.** Le générateur de gaz d'un ancien modèle d'airbag contient **65 g d'azoture de sodium** NaN₃. Lors d'un choc, il se décompose selon l'équation :\n\n> 2 NaN₃ → 2 Na + 3 N₂\n\n**Données** : M(NaN₃) = 65 g/mol ; volume molaire d'un gaz Vm = 24 L/mol à 20 °C sous la pression atmosphérique.\n\n1. Calcule la quantité de matière d'azoture de sodium contenue dans le générateur.\n2. En utilisant les coefficients de l'équation, déduis-en la quantité de matière de diazote N₂ libérée.\n3. Calcule le volume de diazote obtenu à 20 °C et commente l'ordre de grandeur de ce résultat.","bareme":[{"critere":"n(NaN₃) = m ÷ M = 65 ÷ 65 = 1,0 mol, formule écrite et unité donnée","points":6},{"critere":"Proportions de l'équation utilisées : n(N₂) = 3/2 × n(NaN₃) = 1,5 mol","points":7},{"critere":"V = n × Vm = 1,5 × 24 = 36 L, avec un commentaire sur la vraisemblance du volume","points":7}],"dureeMin":7,"corrige":"1. n(NaN₃) = m ÷ M = 65 ÷ 65 = **1,0 mol**.\n2. D'après l'équation, **2 mol** de NaN₃ donnent **3 mol** de N₂ : n(N₂) = n(NaN₃) × 3 ÷ 2 = 1,0 × 3 ÷ 2 = **1,5 mol**.\n3. V(N₂) = n × Vm = 1,5 × 24 = **36 L**. C'est un volume de l'ordre de quelques dizaines de litres, cohérent avec la taille d'un coussin gonflable : le résultat est plausible (un résultat de 36 000 L ou de 0,036 L signalerait une erreur).\n\nOn accepte 36 L obtenus en une seule ligne à condition que le passage par les proportions de l'équation (3/2) apparaisse."}$exo$::jsonb),
  ('0ad50bc5-e1af-5ffd-a692-3490df7f87f1'::uuid, 2, 'application', $exo${"titre":"Contrôle d'alcoolémie au bord de la route","consigne":"Lis la situation, puis réponds en justifiant chaque réponse par le cours et par un calcul lorsque c'est demandé.","enonce":"**Situation.** Hugo a son permis depuis un an : il est **jeune conducteur**. Lors d'un contrôle, un gendarme lui fait souffler dans un éthylotest chimique, puis dans un éthylomètre.\n\n**Document 1 – Les deux couples mis en jeu**\n\n| Le couple | La demi-équation |\n| Cr₂O₇²⁻ / Cr³⁺ | Cr₂O₇²⁻ + 14 H⁺ + 6 e⁻ = 2 Cr³⁺ + 7 H₂O |\n| CH₃COOH / C₂H₅OH | CH₃COOH + 4 H⁺ + 4 e⁻ = C₂H₅OH + H₂O |\n\n**Document 2 – La réglementation** : 0,5 g d'alcool par litre de sang correspond à 0,25 mg par litre d'air expiré (les deux grandeurs sont proportionnelles). Seuil légal : 0,5 g/L de sang, ramené à 0,2 g/L de sang pour les jeunes conducteurs.\n\n1. Dans l'éthylotest, la zone passe de l'orange au vert. Quelle espèce est oxydée, quelle espèce est réduite ? Justifie par la couleur observée.\n2. À partir du document 1, écris l'équation de la réaction entre les ions dichromate et l'éthanol, en expliquant comment tu égalises les électrons.\n3. L'éthylomètre indique **0,15 mg/L d'air expiré**. Convertis cette valeur en g/L de sang et dis si Hugo est en infraction. Le serait-il s'il était conducteur expérimenté ?","bareme":[{"critere":"Éthanol oxydé en acide éthanoïque, ions dichromate (orange) réduits en ions chrome III (verts)","points":5},{"critere":"Électrons égalisés (12 = 2 × 6 = 3 × 4) et équation bilan juste et équilibrée","points":7},{"critere":"Conversion 0,15 mg/L d'air → 0,30 g/L de sang par proportionnalité","points":4},{"critere":"Comparaison aux deux seuils : infraction pour Hugo (0,30 > 0,2), pas pour un conducteur expérimenté (0,30 < 0,5)","points":4}],"dureeMin":11,"corrige":"1. L'**éthanol** C₂H₅OH est **oxydé** en acide éthanoïque CH₃COOH (il perd des électrons) ; les ions **dichromate** Cr₂O₇²⁻, orange, sont **réduits** en ions chrome III Cr³⁺, verts. Le passage de l'orange au vert montre que les ions dichromate ont été transformés : de l'alcool était présent dans l'air expiré.\n2. Le dichromate capte 6 e⁻, l'éthanol en cède 4. Le plus petit multiple commun est **12** : on multiplie la demi-équation du dichromate par 2 et celle de l'éthanol par 3 (12 = 2 × 6 = 3 × 4). En additionnant (sens dichromate → Cr³⁺, sens éthanol → acide) et en simplifiant les H⁺ et H₂O :\n\n2 Cr₂O₇²⁻ + 16 H⁺ + 3 C₂H₅OH → 4 Cr³⁺ + 11 H₂O + 3 CH₃COOH\n\nVérification : H : 16 + 18 = 34 à gauche, 22 + 12 = 34 à droite ; charges : −4 + 16 = +12 à gauche, 4 × 3 = +12 à droite.\n3. 0,25 mg/L d'air ↔ 0,5 g/L de sang, donc on multiplie par 2 : 0,15 mg/L d'air ↔ 0,15 × 2 = **0,30 g/L de sang**.\n- Hugo est jeune conducteur : 0,30 g/L > 0,2 g/L, il est **en infraction**.\n- Un conducteur expérimenté avec la même valeur ne le serait pas : 0,30 g/L < 0,5 g/L."}$exo$::jsonb),
  ('0ad50bc5-e1af-5ffd-a692-3490df7f87f1'::uuid, 3, 'application', $exo${"titre":"Le frigo de la colocation","consigne":"Exploite les documents, fais les calculs demandés en écrivant les formules, puis argumente en t'appuyant sur les notions du cours.","enonce":"**Situation.** Dans une colocation d'étudiants, Camille fait le tri dans la cuisine.\n\n**Document 1 – Deux laits dosés en travaux pratiques**\n\n| Le lait | Acide lactique dosé |\n| Lait A (ouvert hier) | 1,6 g/L |\n| Lait B (ouvert il y a dix jours, laissé hors du frigo) | 2,4 g/L |\n\n**Document 2 – Un beurre oublié** : laissé plusieurs jours sur la table, le beurre a pris une odeur forte et désagréable.\n\n**Document 3 – Une boisson** : elle contient **150 mg/L** d'acide benzoïque (E210). La DJA de cet additif est de **5 mg/kg/jour**.\n\n1. Exprime l'acidité de chaque lait en degrés Dornic. Lequel est frais ? Explique, au niveau chimique et biologique, ce qui arrive au lait B et pourquoi il finit par cailler.\n2. Nomme la transformation subie par le beurre, décris-la et cite ses facteurs. Propose un procédé de conservation adapté et dis s'il est physique ou chimique.\n3. À quelle famille d'additifs appartient E210 ? Définis la DJA.\n4. Calcule le volume maximal de cette boisson que peuvent boire chaque jour, sans dépasser la DJA, le petit frère de Camille (20 kg) et Camille (70 kg). Commente.","bareme":[{"critere":"Lait A : 16 °D (frais, 15 à 18 °D) ; lait B : 24 °D, trop acide","points":4},{"critere":"Caillage expliqué : bactéries, lactose transformé en acide lactique, acidité qui fait coaguler les protéines","points":4},{"critere":"Rancissement hydrolytique : hydrolyse des triglycérides, facteurs, procédé physique proposé (froid)","points":4},{"critere":"E210 classé comme conservateur et DJA définie (additif, chaque jour, toute la vie, en mg/kg/jour)","points":3},{"critere":"Doses maximales 100 mg et 350 mg, volumes 0,67 L et 2,3 L, commentaire sur le rôle de la masse","points":5}],"dureeMin":18,"corrige":"1. 1 °D correspond à 0,1 g d'acide lactique par litre.\n- Lait A : 1,6 ÷ 0,1 = **16 °D** : entre 15 et 18 °D, il est **frais**.\n- Lait B : 2,4 ÷ 0,1 = **24 °D** : trop acide, il n'est plus frais.\nDans le lait B, des **bactéries** (micro-organismes) se sont multipliées, favorisées par la température ambiante ; elles transforment le **lactose** en **acide lactique**. L'acidité augmente, et elle fait **coaguler les protéines** du lait : il caille.\n2. C'est le **rancissement hydrolytique** : l'**hydrolyse des triglycérides** du beurre libère des acides gras à l'odeur forte. Facteurs : **eau, enzymes, micro-organismes** (et la chaleur de la pièce qui les favorise). Procédé proposé : conserver le beurre au **réfrigérateur** (froid), procédé **physique** ; l'emballage limite aussi les contaminations.\n3. Les additifs E200 à E299 sont des **conservateurs** : E210 en est un. La **DJA** est la quantité d'une substance ajoutée volontairement (additif) que l'on peut ingérer **chaque jour, toute sa vie, sans risque appréciable** ; elle s'exprime en mg par kg de masse corporelle et par jour.\n4. Dose maximale = DJA × masse.\n- Frère : 5 × 20 = **100 mg** par jour ; volume = 100 ÷ 150 ≈ **0,67 L**.\n- Camille : 5 × 70 = **350 mg** par jour ; volume = 350 ÷ 150 ≈ **2,3 L**.\nLa DJA dépend de la **masse** : l'enfant l'atteint avec un volume trois à quatre fois plus petit. Une seule bouteille de 50 cL représente déjà les trois quarts de sa dose maximale, alors que pour un adulte le risque est faible à consommation normale."}$exo$::jsonb),
  ('73bdb32f-66d2-5e98-a373-2e9b4ee5b9aa'::uuid, 1, 'application', $exo${"titre":"Trois eaux sur la paillasse","consigne":"Réponds à chaque question par quelques phrases précises, en utilisant le vocabulaire du cours.","enonce":"**Situation.** Sur la paillasse de Yanis, trois flacons non étiquetés : de l'**eau distillée**, de l'**eau minérale** et de l'**eau de mer**. Il dispose d'un conductimètre et de chlorure de sodium NaCl solide.\n\n1. Explique pourquoi le chlorure de sodium se dissout bien dans l'eau. Utilise les mots « polaire » et « hydratés », et écris l'équation de dissolution.\n2. Yanis mesure trois conductivités : quasi nulle, moyenne, très élevée. Attribue chaque valeur à l'une des trois eaux, en justifiant.\n3. Pourquoi est-il dangereux d'utiliser un appareil électrique près de l'eau du robinet ?","bareme":[{"critere":"Molécule d'eau polaire (charges partielles), ions attirés, détachés et hydratés ; équation NaCl(s) → Na⁺(aq) + Cl⁻(aq)","points":8},{"critere":"Attribution justifiée par la quantité d'ions : distillée quasi nulle, minérale moyenne, mer très élevée","points":8},{"critere":"Eau chargée en ions donc conductrice du courant","points":4}],"dureeMin":7,"corrige":"1. La molécule d'eau est **polaire** : l'oxygène, plus électronégatif, porte une charge partielle négative, les hydrogènes une charge partielle positive. Les ions du cristal sont attirés par ces pôles (Na⁺ par l'oxygène, Cl⁻ par les hydrogènes), se détachent et s'entourent de molécules d'eau : ils sont **hydratés**.\nNaCl(s) → Na⁺(aq) + Cl⁻(aq)\n2. Une solution conduit le courant grâce à ses **ions** ; la conductivité augmente avec leur concentration.\n- **Quasi nulle** : eau **distillée** (débarrassée des ions).\n- **Moyenne** : eau **minérale** (ions calcium, magnésium, hydrogénocarbonate…).\n- **Très élevée** : eau **de mer** (beaucoup d'ions sodium et chlorure).\n3. L'eau du robinet contient des **ions mobiles** : elle **conduit le courant**. Au contact d'un appareil électrique, elle peut faire passer le courant à travers le corps : risque d'électrocution."}$exo$::jsonb),
  ('73bdb32f-66d2-5e98-a373-2e9b4ee5b9aa'::uuid, 2, 'application', $exo${"titre":"La bouteille d'oxygène de M. Garnier","consigne":"Convertis les unités avant de calculer, écris la formule littérale, puis donne les résultats avec leur unité.","enonce":"**Situation.** M. Garnier, insuffisant respiratoire, utilise à domicile une bouteille d'oxygène médical de **10 L** remplie à **150 bar**, à la température de **20 °C**. Son médecin lui a prescrit un débit de **3 L de dioxygène par minute** (volume mesuré à la pression atmosphérique).\n\n**Données** : 1 bar = 10⁵ Pa ; R = 8,314 J/(mol·K) ; T(K) = θ(°C) + 273 ; Vm = 24 L/mol à 20 °C sous la pression atmosphérique.\n\n1. Convertis la pression, le volume et la température dans les unités de la loi du gaz parfait.\n2. Calcule la quantité de matière de dioxygène contenue dans la bouteille.\n3. Quel volume ce dioxygène occuperait-il à la pression atmosphérique ? Pendant combien de temps environ la bouteille permet-elle de respirer au débit prescrit ?\n4. L'air ambiant contient environ 21 % de dioxygène. Pourquoi une bouteille d'oxygène médical est-elle utile à ce patient ?","bareme":[{"critere":"Conversions justes : P = 1,5 × 10⁷ Pa, V = 1,0 × 10⁻² m³, T = 293 K","points":5},{"critere":"n = P × V ÷ (R × T) ≈ 62 mol, formule écrite","points":6},{"critere":"V ≈ 1,5 × 10³ L puis durée ≈ 490 min, soit environ 8 h","points":6},{"critere":"Explication : dioxygène pur contre 21 % dans l'air, apport enrichi pour un patient qui en manque","points":3}],"dureeMin":12,"corrige":"1. P = 150 × 10⁵ = **1,5 × 10⁷ Pa** ; V = 10 L = **1,0 × 10⁻² m³** ; T = 20 + 273 = **293 K**.\n2. P × V = n × R × T, donc n = P × V ÷ (R × T) = (1,5 × 10⁷ × 1,0 × 10⁻²) ÷ (8,314 × 293) = 1,5 × 10⁵ ÷ 2 436 ≈ **62 mol** de dioxygène.\n3. V = n × Vm = 61,6 × 24 ≈ **1,5 × 10³ L** (environ 1 480 L).\nDurée = 1 480 ÷ 3 ≈ **490 minutes**, soit **environ 8 heures**.\nL'ordre de grandeur est cohérent : une bouteille de ce type sert quelques heures, il faut prévoir son remplacement.\n4. L'air ne contient qu'environ **21 %** de dioxygène (fraction molaire). La bouteille délivre du **dioxygène pur** : mélangé à l'air inspiré, il enrichit l'apport d'oxygène d'un patient dont les poumons n'en fournissent plus assez au sang."}$exo$::jsonb),
  ('73bdb32f-66d2-5e98-a373-2e9b4ee5b9aa'::uuid, 3, 'application', $exo${"titre":"L'eau du puits de la ferme des Lemaire","consigne":"Exploite les documents, fais les calculs en écrivant les formules, puis rédige une conclusion argumentée sur la potabilité de cette eau et son traitement.","enonce":"**Situation.** La famille Lemaire veut savoir si l'eau de son puits peut être bue. Un laboratoire l'analyse.\n\n**Document 1 – Dosage conductimétrique des ions sulfate.** On place **20,0 mL** d'eau du puits dans un bécher et on ajoute progressivement une solution de chlorure de baryum (Ba²⁺ + 2 Cl⁻) à **1,0 × 10⁻² mol/L**. Réaction : Ba²⁺ + SO₄²⁻ → BaSO₄ (précipité blanc). La courbe σ = f(V) présente deux portions de droite : presque horizontale jusqu'à **12,0 mL**, puis nettement croissante au-delà.\n\n**Document 2 – Autres résultats et limites de qualité**\n\n| Le paramètre | Le résultat | La limite |\n| Sulfates | à calculer | 250 mg/L |\n| Nitrates | 38 mg/L | 50 mg/L |\n| pH | 7,4 | entre 6,5 et 9 |\n| Un pesticide | 0,3 µg/L | 0,1 µg/L |\n\nDonnée : M(SO₄²⁻) = 96 g/mol.\n\n1. Explique l'allure de la courbe avant et après 12,0 mL. Comment repère-t-on l'équivalence et que signifie-t-elle ?\n2. Calcule la concentration en quantité de matière, puis en masse (en mg/L), des ions sulfate de l'eau du puits.\n3. Ce pesticide est-il un macropolluant ou un micropolluant ? Justifie.\n4. Conclus : l'eau est-elle potable ? Quels paramètres posent problème ? Propose un traitement adapté au pesticide et explique son principe.","bareme":[{"critere":"Allure expliquée (sulfate consommé puis Ba²⁺ et Cl⁻ accumulés) et équivalence au changement de pente, réactifs dans les proportions de l'équation","points":5},{"critere":"n(SO₄²⁻) = n(Ba²⁺) = 1,2 × 10⁻⁴ mol ; C = 6,0 × 10⁻³ mol/L","points":5},{"critere":"Cm = C × M ≈ 0,58 g/L soit environ 580 mg/L","points":3},{"critere":"Pesticide classé micropolluant (actif à très faible concentration)","points":2},{"critere":"Conclusion : non potable (sulfates et pesticide au-dessus des limites), adsorption sur charbon actif expliquée","points":5}],"dureeMin":20,"corrige":"1. **Avant 12,0 mL**, les ions sulfate disparaissent au fur et à mesure (ils précipitent avec les ions baryum ajoutés) : σ varie peu. **Après 12,0 mL**, il n'y a plus de sulfate : les ions baryum et chlorure ajoutés s'accumulent, σ augmente nettement. L'**équivalence** se lit au **changement de pente**, ici à **V = 12,0 mL** : les réactifs ont alors été introduits dans les **proportions de l'équation** (1 Ba²⁺ pour 1 SO₄²⁻).\n2. À l'équivalence : n(SO₄²⁻) = n(Ba²⁺) = C × V = 1,0 × 10⁻² × 12,0 × 10⁻³ = **1,2 × 10⁻⁴ mol**.\nC(SO₄²⁻) = n ÷ V = 1,2 × 10⁻⁴ ÷ 20,0 × 10⁻³ = **6,0 × 10⁻³ mol/L**.\nCm = C × M = 6,0 × 10⁻³ × 96 ≈ **0,58 g/L**, soit environ **580 mg/L**.\n3. Le pesticide est un **micropolluant** : il est présent et actif à **très faible concentration** (quelques dixièmes de microgramme par litre), comme les pesticides, médicaments ou métaux lourds.\n4. Nitrates (38 < 50 mg/L) et pH (7,4, entre 6,5 et 9) respectent les critères. Mais les **sulfates** (environ 580 mg/L, plus du double de 250 mg/L) et le **pesticide** (0,3 µg/L, trois fois la limite) les dépassent : l'eau **n'est pas potable** en l'état (et il faudrait aussi des analyses microbiologiques). Pour le pesticide : **adsorption sur charbon actif**, dont la surface immense retient les molécules à sa surface (l'oxydation par l'ozone est aussi possible)."}$exo$::jsonb),
  ('e48e856a-120e-5736-bd4d-c1ae69d14a21'::uuid, 1, 'application', $exo${"titre":"L'échographie de la cheville de Malik","consigne":"Réponds à chaque question en justifiant ; écris la formule avant de remplacer par les valeurs.","enonce":"**Situation.** Malik s'est fait une entorse. Le médecin réalise une échographie de sa cheville.\n\n**Données** : vitesse des ultrasons dans les tissus mous v = 1 540 m/s ; 1 µs = 10⁻⁶ s.\n\n1. Les ultrasons sont-ils des ondes mécaniques ou électromagnétiques ? Donne une conséquence sur leur propagation.\n2. Un écho revient à la sonde **65 µs** après l'émission. Calcule la profondeur de l'interface qui l'a renvoyé, en expliquant la division par 2.\n3. Le médecin hésite ensuite avec une IRM. Explique pourquoi l'IRM, comme l'échographie, n'expose pas le patient à une irradiation.","bareme":[{"critere":"Onde mécanique, qui a besoin d'un milieu matériel (ne se propage pas dans le vide)","points":5},{"critere":"d = v × Δt ÷ 2 = 1 540 × 65 × 10⁻⁶ ÷ 2 ≈ 5,0 × 10⁻² m, division par 2 expliquée par l'aller-retour","points":10},{"critere":"IRM : champ magnétique et radiofréquences sur les noyaux d'hydrogène, aucun rayonnement ionisant","points":5}],"dureeMin":7,"corrige":"1. Les ultrasons sont des ondes **mécaniques** (fréquence supérieure à 20 kHz) : elles ont **besoin d'un milieu matériel** pour se propager et ne se propagent pas dans le vide ; dans les tissus mous, leur vitesse est d'environ 1 540 m/s.\n2. L'onde fait un **aller et retour** entre la sonde et l'interface : la distance parcourue vaut 2d.\nd = v × Δt ÷ 2 = 1 540 × 65 × 10⁻⁶ ÷ 2 ≈ **5,0 × 10⁻² m**, soit **5,0 cm**.\n3. L'**IRM** utilise un **champ magnétique** et des **radiofréquences** qui agissent sur les noyaux d'hydrogène de l'eau des tissus : elle n'utilise ni rayons X ni radioactivité, donc **aucune irradiation** du patient. L'échographie utilise des ultrasons, ondes mécaniques, elle non plus n'est pas irradiante."}$exo$::jsonb),
  ('e48e856a-120e-5736-bd4d-c1ae69d14a21'::uuid, 2, 'application', $exo${"titre":"La scintigraphie osseuse de Mme Duval","consigne":"Réponds en écrivant tes calculs et en justifiant avec les notions du cours.","enonce":"**Situation.** Mme Duval, 60 kg, passe une scintigraphie osseuse. On lui injecte à **8 h** du technétium 99m, émetteur **γ** de période **T = 6 h**, à raison de **10 MBq par kg** de masse corporelle.\n\n1. Calcule l'activité injectée à Mme Duval. Que représente un becquerel ?\n2. Définis la période d'un radio-isotope. Quelle sera l'activité du technétium restant à **20 h** le même jour, puis à **8 h le lendemain** ?\n3. Quelle est la nature du rayonnement γ ? Pourquoi est-il adapté à une image prise par une caméra placée à l'extérieur du corps ?\n4. Cite trois précautions que doit prendre le manipulateur en radiologie qui prépare et injecte la dose.","bareme":[{"critere":"Activité injectée : 10 × 60 = 600 MBq ; Bq = une désintégration par seconde","points":4},{"critere":"Période définie ; 150 MBq à 20 h (2 périodes) et 37,5 MBq le lendemain à 8 h (4 périodes, 1/16)","points":8},{"critere":"γ = photon très énergétique, qui sort du corps et atteint le détecteur","points":4},{"critere":"Trois précautions justes (durée, distance, écran de plomb, dosimètre, gestion des déchets)","points":4}],"dureeMin":11,"corrige":"1. Activité injectée = 10 MBq/kg × 60 kg = **600 MBq**. Le becquerel (Bq) correspond à **une désintégration par seconde** : 600 MBq = 6,00 × 10⁸ désintégrations par seconde.\n2. La **période** (demi-vie) est la durée au bout de laquelle **la moitié** des noyaux radioactifs s'est désintégrée.\n- À 20 h : 12 h = **2 périodes**, il reste 600 ÷ 2² = **150 MBq**.\n- Le lendemain à 8 h : 24 h = **4 périodes**, il reste 600 ÷ 2⁴ = 600 ÷ 16 = **37,5 MBq**, soit 1/16 de l'activité initiale.\n3. Le rayonnement γ est constitué de **photons très énergétiques** : il traverse les tissus et **sort du corps**, ce qui permet à la caméra placée à l'extérieur de localiser l'endroit où le traceur s'est fixé (ici les os).\n4. Précautions : **limiter la durée** d'exposition, **augmenter la distance** à la source, utiliser des **écrans de plomb** (protège-seringue), porter un **dosimètre**, signaler la zone (trèfle), gérer les **déchets** et les urines de la patiente."}$exo$::jsonb),
  ('e48e856a-120e-5736-bd4d-c1ae69d14a21'::uuid, 3, 'application', $exo${"titre":"Trois examens pour un même patient","consigne":"Exploite les données, fais les calculs demandés, puis argumente le choix de chaque technique en t'appuyant sur le cours.","enonce":"**Situation.** M. Benali, 58 ans, consulte après une chute. Son dossier réunit trois examens.\n\n**Examen 1 – Radiographie du poignet.** Le générateur émet un rayonnement de fréquence f = 3,0 × 10¹⁷ Hz. Sur le cliché, l'os apparaît blanc et un trait noir le traverse.\n\n**Examen 2 – Échographie Doppler du cou.** Dans une artère carotide, l'onde réfléchie par le sang revient avec une fréquence plus élevée qu'à l'émission, et la vitesse du sang est nettement plus grande à un endroit précis de l'artère.\n\n**Examen 3 – TEP (tomographie par émission de positons).** On lui injecte à 9 h 00 une molécule proche du glucose marquée au **fluor 18** (émetteur β⁺, T ≈ 110 min), d'activité **280 MBq**.\n\n**Donnée** : c = 3,00 × 10⁸ m/s.\n\n1. Calcule la longueur d'onde du rayonnement de l'examen 1 et vérifie qu'il s'agit de rayons X. Pourquoi l'os apparaît-il blanc ? Que peut signifier le trait noir ?\n2. Qu'indique la fréquence plus élevée de l'onde réfléchie à l'examen 2 ? Que suggère l'accélération locale du sang ?\n3. Quelle particule émet le fluor 18 ? Pourquoi les cellules cancéreuses « s'allument »-elles en TEP ? Quelle activité reste-t-il à 14 h 30 ?\n4. Parmi ces trois examens, lesquels exposent le patient à un rayonnement ionisant ? Justifie.","bareme":[{"critere":"λ = c ÷ f = 1,0 × 10⁻⁹ m = 1 nm, compris entre 0,01 et 10 nm : rayons X","points":4},{"critere":"Os blanc : forte absorption (calcium Z = 20, tissu dense) ; trait noir = rayons non absorbés, fracture possible","points":4},{"critere":"Doppler : sang qui s'approche de la sonde ; accélération locale = rétrécissement de l'artère","points":4},{"critere":"β⁺ = positon ; cellules cancéreuses grandes consommatrices de glucose ; 330 min = 3 périodes, 35 MBq","points":5},{"critere":"Radiographie et TEP ionisantes, échographie Doppler non ionisante (ultrasons, ondes mécaniques)","points":3}],"dureeMin":20,"corrige":"1. λ = c ÷ f = 3,00 × 10⁸ ÷ 3,0 × 10¹⁷ = **1,0 × 10⁻⁹ m = 1,0 nm**. Cette valeur est comprise entre 0,01 et 10 nm : ce sont bien des **rayons X**.\nL'os est riche en **calcium** (Z = 20) et en phosphore, et c'est un tissu dense : il **absorbe fortement** les rayons X, qui n'atteignent pas le détecteur : il apparaît **blanc**. Le trait noir est une zone où les rayons ont traversé sans être absorbés : l'os est interrompu, ce qui évoque une **fracture**.\n2. Par effet Doppler, l'onde réfléchie par une cible en mouvement change de fréquence ; une fréquence **plus élevée** signifie que le sang **s'approche** de la sonde. Une vitesse du sang nettement plus grande à un endroit précis indique que le sang **accélère** : cela révèle un **rétrécissement de l'artère** à cet endroit.\n3. Le fluor 18 est émetteur **β⁺** : il émet un **positon** (antiparticule de l'électron). Il est fixé sur une molécule proche du glucose ; les cellules cancéreuses, **grandes consommatrices de glucose**, captent davantage le traceur et apparaissent plus intensément.\nDe 9 h 00 à 14 h 30 : 330 min = 3 × 110 min = **3 périodes**. Activité restante = 280 ÷ 2³ = 280 ÷ 8 = **35 MBq**.\n4. La **radiographie** (rayons X) et la **TEP** (radioactivité) exposent à des **rayonnements ionisants**. L'**échographie Doppler** utilise des ultrasons, ondes **mécaniques** : elle n'irradie pas. Les doses de la radiographie diagnostique et de la médecine nucléaire diagnostique restent faibles, mais on les justifie par le bénéfice attendu."}$exo$::jsonb),
  ('7db92b49-bd5f-5849-965b-ae0598746b0a'::uuid, 1, 'application', $exo${"titre":"Préparer du sérum physiologique","consigne":"Réponds à chaque question en écrivant les formules et en citant le matériel précis.","enonce":"**Situation.** En travaux pratiques, Salomé doit préparer **250,0 mL** de sérum physiologique, une solution de chlorure de sodium NaCl à **9,0 g/L**.\n\n**Donnée** : M(NaCl) = 58,5 g/mol.\n\n1. Écris l'équation de dissolution du chlorure de sodium dans l'eau.\n2. Calcule la masse de chlorure de sodium à peser, puis décris le protocole de préparation (matériel et gestes).\n3. Calcule la concentration en quantité de matière de cette solution.","bareme":[{"critere":"Équation NaCl(s) → Na⁺(aq) + Cl⁻(aq)","points":4},{"critere":"m = Cm × V = 2,25 g et protocole : pesée, fiole jaugée de 250 mL, dissolution, trait de jauge, agitation","points":10},{"critere":"C = Cm ÷ M ≈ 0,15 mol/L","points":6}],"dureeMin":8,"corrige":"1. NaCl(s) → Na⁺(aq) + Cl⁻(aq) : le chlorure de sodium est un soluté **ionique**.\n2. m = Cm × V = 9,0 × 0,2500 = **2,25 g** (environ 2,3 g).\nProtocole : peser 2,25 g de NaCl dans une coupelle sur une balance ; l'introduire dans une **fiole jaugée de 250,0 mL** à l'aide d'un entonnoir, en rinçant la coupelle avec de l'eau distillée ; remplir la fiole aux trois quarts, **agiter** pour dissoudre ; **compléter au trait de jauge** avec de l'eau distillée ; boucher et agiter pour homogénéiser.\n3. Cm = C × M, donc C = Cm ÷ M = 9,0 ÷ 58,5 ≈ **0,15 mol/L**."}$exo$::jsonb),
  ('7db92b49-bd5f-5849-965b-ae0598746b0a'::uuid, 2, 'application', $exo${"titre":"La glycémie de Mme Roche","consigne":"Exploite le tableau de mesures, écris tes calculs et conclus en comparant aux valeurs de référence.","enonce":"**Situation.** Au laboratoire, on dose le glucose du plasma de Mme Roche, prélevé à jeun. Le glucose étant incolore, on le fait d'abord réagir avec des enzymes qui produisent une espèce colorée en quantité proportionnelle. On mesure ensuite des absorbances au spectrophotomètre.\n\n**Document – Gamme étalon**\n\n| C (mmol/L) | 0 | 2,0 | 4,0 | 6,0 | 8,0 |\n| A | 0 | 0,12 | 0,24 | 0,36 | 0,48 |\n\nL'échantillon de Mme Roche, traité de la même façon, donne **A = 0,33**.\n\n**Données** : M(glucose) = 180 g/mol ; glycémie à jeun de référence : 0,70 à 1,10 g/L.\n\n1. À quelle longueur d'onde règle-t-on le spectrophotomètre ? Pourquoi fait-on réagir le glucose avant la mesure ?\n2. Montre que les mesures vérifient la loi de Beer-Lambert et détermine le coefficient k.\n3. Déduis-en la glycémie de Mme Roche en mmol/L, puis en g/L. Est-elle dans les valeurs de référence ?","bareme":[{"critere":"Longueur d'onde du maximum d'absorbance ; glucose incolore transformé en espèce colorée proportionnelle","points":5},{"critere":"A proportionnelle à C (droite par l'origine, rapport constant), k = 0,060 L/mmol","points":6},{"critere":"C = A ÷ k = 5,5 mmol/L, puis Cm = C × M ≈ 0,99 g/L","points":6},{"critere":"Conclusion : glycémie normale (entre 0,70 et 1,10 g/L)","points":3}],"dureeMin":12,"corrige":"1. On règle le spectrophotomètre à la longueur d'onde où l'**absorbance est maximale** pour l'espèce colorée. Le glucose est **incolore** : il n'absorbe pas dans le visible ; la réaction enzymatique produit une espèce **colorée** en quantité **proportionnelle** au glucose, que l'on peut doser.\n2. A ÷ C vaut toujours 0,12 ÷ 2,0 = 0,24 ÷ 4,0 = 0,36 ÷ 6,0 = 0,48 ÷ 8,0 = **0,060 L/mmol**, et A = 0 pour C = 0 : les points sont alignés sur une droite passant par l'origine. L'absorbance est **proportionnelle** à la concentration : A = k × C avec **k = 0,060 L/mmol** (loi de Beer-Lambert).\n3. C = A ÷ k = 0,33 ÷ 0,060 = **5,5 mmol/L** (lecture possible sur la droite).\nCm = C × M = 5,5 × 10⁻³ mol/L × 180 g/mol ≈ **0,99 g/L**.\n0,70 ≤ 0,99 ≤ 1,10 g/L : la glycémie à jeun de Mme Roche est **dans les valeurs de référence**."}$exo$::jsonb),
  ('7db92b49-bd5f-5849-965b-ae0598746b0a'::uuid, 3, 'application', $exo${"titre":"Un ionogramme et une ampoule de chlorure de calcium","consigne":"Fais les calculs en écrivant les formules et les unités, puis interprète les résultats en restant prudent comme le serait un biologiste.","enonce":"**Situation.** M. Faure, 82 ans, est hospitalisé. Sa prise de sang est rendue par un ancien automate qui exprime les ions en **g/L**.\n\n**Document 1 – Résultats**\n\n| L'ion | Le résultat |\n| Na⁺ | 3,6 g/L |\n| K⁺ | 0,16 g/L |\n\n**Document 2 – Valeurs de référence** : natrémie 135 à 145 mmol/L ; kaliémie 3,5 à 5,0 mmol/L.\n\n**Document 3 – Une ampoule injectable** de 10 mL de chlorure de calcium CaCl₂ à **100 g/L**. Le médecin prescrit l'injection de **0,50 g** de CaCl₂.\n\n**Données** : M(Na) = 23 g/mol ; M(K) = 39,1 g/mol ; M(CaCl₂) = 111 g/mol.\n\n1. Convertis les deux résultats en mmol/L et compare-les aux valeurs de référence.\n2. Que peut-on dire de ces résultats ? Comment doivent-ils être utilisés par le médecin ?\n3. Écris l'équation de dissolution du chlorure de calcium. Calcule la concentration en quantité de matière de l'ampoule, puis la concentration des ions chlorure.\n4. Quel volume de la solution de l'ampoule faut-il injecter pour administrer la dose prescrite ?","bareme":[{"critere":"Na⁺ : 3,6 ÷ 23 ≈ 0,157 mol/L = 157 mmol/L ; K⁺ : 0,16 ÷ 39,1 ≈ 4,1 mmol/L","points":6},{"critere":"Natrémie au-dessus de l'intervalle, kaliémie normale ; résultat qui oriente et se confirme avec le contexte clinique","points":4},{"critere":"CaCl₂(s) → Ca²⁺(aq) + 2 Cl⁻(aq) ; C ≈ 0,90 mol/L et [Cl⁻] = 2 × C ≈ 1,8 mol/L","points":6},{"critere":"Volume à injecter : 0,50 ÷ 100 = 5,0 × 10⁻³ L = 5,0 mL","points":4}],"dureeMin":18,"corrige":"1. C = Cm ÷ M.\n- Na⁺ : 3,6 ÷ 23 ≈ 0,157 mol/L = **157 mmol/L** : supérieure à 145 mmol/L, la natrémie est **trop élevée**.\n- K⁺ : 0,16 ÷ 39,1 ≈ 0,0041 mol/L = **4,1 mmol/L** : comprise entre 3,5 et 5,0 mmol/L, la kaliémie est **normale**.\n2. Un résultat hors de l'intervalle de référence **oriente** le diagnostic mais ne le pose pas à lui seul : le médecin doit le **confirmer par d'autres examens** et le lire avec le **contexte clinique** du patient (âge, symptômes, traitements).\n3. CaCl₂(s) → Ca²⁺(aq) + 2 Cl⁻(aq).\nC = Cm ÷ M = 100 ÷ 111 ≈ **0,90 mol/L**.\nUne mole de soluté libère **deux** moles d'ions chlorure : [Cl⁻] = 2 × C ≈ **1,8 mol/L**.\n4. V = m ÷ Cm = 0,50 ÷ 100 = 5,0 × 10⁻³ L = **5,0 mL** (la moitié de l'ampoule)."}$exo$::jsonb),
  ('50aac090-2865-5418-9a00-3cfd4625ca52'::uuid, 1, 'application', $exo${"titre":"L'alanine et la glycine","consigne":"Réponds à chaque question en utilisant le vocabulaire précis du cours.","enonce":"**Données** : formule générale d'un acide α-aminé H₂N–CH(R)–COOH ; pour la glycine R = H, pour l'alanine R = CH₃.\n\n1. Écris la formule semi-développée de l'alanine et entoure (ou nomme) ses deux groupes caractéristiques.\n2. Définis un carbone asymétrique. L'alanine en possède-t-elle un ? Et la glycine ? Justifie.\n3. En représentation de Fischer, avec –COOH en haut et R en bas, le groupe –NH₂ de l'alanine des protéines humaines est-il à gauche ou à droite ? Comment appelle-t-on cette forme ?","bareme":[{"critere":"Formule H₂N–CH(CH₃)–COOH, groupes amine et carboxyle nommés","points":6},{"critere":"Définition du carbone asymétrique, alanine chirale (4 groupes différents), glycine non chirale (deux H)","points":8},{"critere":"–NH₂ à gauche : acide aminé L","points":6}],"dureeMin":7,"corrige":"1. Alanine : **H₂N–CH(CH₃)–COOH**. Groupe **amine** –NH₂ et groupe **carboxyle** –COOH, portés par le même carbone (carbone α).\n2. Un **carbone asymétrique** est lié à **quatre groupes différents**.\n- Alanine : le carbone α porte –NH₂, –COOH, –H et –CH₃, quatre groupes différents : il est asymétrique, la molécule est **chirale** (deux énantiomères non superposables).\n- Glycine : R = H, le carbone α porte **deux atomes d'hydrogène** : il n'est pas asymétrique, la glycine **n'est pas chirale**.\n3. Les protéines humaines sont construites avec des acides aminés **L** : en Fischer, –NH₂ est **à gauche**."}$exo$::jsonb),
  ('50aac090-2865-5418-9a00-3cfd4625ca52'::uuid, 2, 'application', $exo${"titre":"Des dipeptides à la protéine","consigne":"Réponds en écrivant les formules demandées et en justifiant avec le cours.","enonce":"**Situation.** En TP, Théo dispose de glycine (R = H) et d'alanine (R = CH₃), de formule générale H₂N–CH(R)–COOH.\n\n1. Écris l'équation de formation du dipeptide **Gly-Ala** (glycine en premier, son groupe –COOH réagissant avec le –NH₂ de l'alanine). Entoure ou nomme la liaison peptidique. Quel est le nom de ce type de réaction ?\n2. Théo affirme : « Avec deux acides aminés, on ne peut faire que deux dipeptides. » Corrige-le en les listant tous.\n3. Comment pourrait-il retrouver les acides aminés qui constituent un dipeptide inconnu ?\n4. Une enzyme chauffée à 80 °C ne fonctionne plus, alors que sa séquence d'acides aminés n'a pas changé. Explique en utilisant les niveaux de structure d'une protéine.","bareme":[{"critere":"Équation juste : H₂N–CH₂–CO–NH–CH(CH₃)–COOH + H₂O, liaison –CO–NH– repérée, condensation","points":7},{"critere":"Quatre dipeptides : Gly-Gly, Gly-Ala, Ala-Gly, Ala-Ala (l'ordre compte)","points":4},{"critere":"Hydrolyse du peptide","points":3},{"critere":"Dénaturation : structure primaire conservée mais forme 3D perdue, donc site actif et fonction perdus","points":6}],"dureeMin":12,"corrige":"1. H₂N–CH₂–COOH + H₂N–CH(CH₃)–COOH → **H₂N–CH₂–CO–NH–CH(CH₃)–COOH** + H₂O\nLe groupe **–CO–NH–** est la **liaison peptidique**. C'est une **condensation** : le –COOH de la glycine réagit avec le –NH₂ de l'alanine, avec élimination d'une molécule d'eau.\n2. Théo a tort : l'**ordre compte** et chaque acide aminé peut se lier à lui-même. On obtient **quatre** dipeptides : **Gly-Gly, Gly-Ala, Ala-Gly, Ala-Ala** (Gly-Ala et Ala-Gly sont différents).\n3. Par **hydrolyse** du dipeptide : la liaison peptidique est rompue et on retrouve les acides aminés qui le constituent.\n4. La **structure primaire** (séquence des acides aminés) est intacte, mais la chaleur a détruit les repliements (structures **secondaire** et **tertiaire**) : la protéine est **dénaturée**, elle a perdu sa **forme en trois dimensions**. Or c'est cette forme qui détermine l'action : le **site actif** de l'enzyme n'existe plus, elle ne fonctionne plus."}$exo$::jsonb),
  ('50aac090-2865-5418-9a00-3cfd4625ca52'::uuid, 3, 'application', $exo${"titre":"Du savon avec de l'huile d'olive","consigne":"Exploite les données, fais les calculs en écrivant les formules, puis argumente sur la santé en t'appuyant sur le cours.","enonce":"**Situation.** Pour un projet, Lina fabrique du savon à partir de **trioléine**, le triglycéride formé à partir de glycérol et de trois molécules d'**acide oléique** (acide gras à une double liaison C=C, abondant dans l'huile d'olive). Elle la chauffe avec un excès de soude (Na⁺ + HO⁻).\n\n**Données** : M(trioléine) = 884 g/mol ; M(oléate de sodium, le savon) = 304 g/mol. Lina utilise **44,2 g** de trioléine et récupère **36,5 g** de savon sec.\n\n1. Qu'est-ce qu'un triglycéride ? L'acide oléique est-il saturé, mono-insaturé ou polyinsaturé ? Justifie.\n2. Écris l'équation de saponification sous forme littérale (triglycéride + soude) et nomme les produits. En quoi diffère-t-elle d'une hydrolyse ?\n3. Calcule la quantité de matière de trioléine, la quantité maximale de savon attendue, puis le rendement de Lina.\n4. Sa grand-mère lui dit : « Les huiles, c'est toutes pareil, je fais frire avec de l'huile de noix. » Rédige quelques lignes pour lui répondre en t'appuyant sur les acides gras et la santé.","bareme":[{"critere":"Triglycéride = triester du glycérol et de trois acides gras ; acide oléique mono-insaturé (une double liaison)","points":4},{"critere":"Saponification : triglycéride + 3 (Na⁺ + HO⁻) → glycérol + 3 (R–COO⁻ + Na⁺), totale à chaud, contre hydrolyse lente et limitée","points":5},{"critere":"n = 0,0500 mol, n(max) = 0,150 mol de savon, n(obtenu) ≈ 0,120 mol, rendement ≈ 80 %","points":7},{"critere":"Argumentation : acides gras polyinsaturés dégradés à forte chaleur, huile de noix pour l'assaisonnement, intérêt des oméga 3","points":4}],"dureeMin":18,"corrige":"1. Un **triglycéride** est un **triester** formé à partir du **glycérol** (un trialcool) et de **trois acides gras**. L'acide oléique possède **une seule** double liaison C=C : il est **mono-insaturé**.\n2. Triglycéride + 3 (Na⁺ + HO⁻) → **glycérol** + 3 (R–COO⁻ + Na⁺), les ions carboxylate formant le **savon**.\nLa saponification est **totale** et se fait **à chaud** avec la soude ; l'hydrolyse (triglycéride + 3 H₂O ⇌ glycérol + 3 acides gras) est **lente et limitée**, accélérée par des enzymes (lipases).\n3. n(trioléine) = m ÷ M = 44,2 ÷ 884 = **0,0500 mol**.\n1 mol de triglycéride donne au plus 3 mol de savon : n(max) = 3 × 0,0500 = **0,150 mol** (soit 0,150 × 304 = 45,6 g).\nn(obtenu) = 36,5 ÷ 304 ≈ **0,120 mol**.\nRendement = 0,120 ÷ 0,150 = **0,80**, soit **80 %** (ou 36,5 ÷ 45,6 ≈ 80 %).\n4. Les huiles ne sont pas toutes pareilles. L'huile de noix est riche en acides gras **polyinsaturés**, dont des **oméga 3** bénéfiques pour la santé ; mais ces acides gras **se dégradent à forte chaleur** : on réserve cette huile à l'**assaisonnement**, pas à la friture. Pour la santé, il faut limiter les acides gras **saturés** et **trans**, qui augmentent le « mauvais » cholestérol et le risque cardio-vasculaire, et garder un bon rapport oméga 6 / oméga 3."}$exo$::jsonb),
  ('3df7d090-74c7-50fd-9430-21e5e5ec03e4'::uuid, 1, 'application', $exo${"titre":"Vitamine C ou vitamine A ?","consigne":"Réponds à chaque question en justifiant par la structure des molécules.","enonce":"**Situation.** Nour hésite à prendre des compléments alimentaires. Elle lit que la vitamine C (acide ascorbique) est une petite molécule riche en groupes –OH, alors que la vitamine A (rétinol) possède une longue chaîne carbonée et un seul groupe –OH.\n\n1. Laquelle de ces vitamines est hydrosoluble, laquelle est liposoluble ? Justifie par leur structure.\n2. Pourquoi faut-il des apports **quotidiens** de vitamine C, alors qu'un excès de vitamine A peut être toxique ?\n3. Associe à chaque vitamine (A, C, D) la conséquence de sa carence.","bareme":[{"critere":"Vitamine C hydrosoluble (nombreux –OH), vitamine A liposoluble (longue chaîne carbonée, un seul –OH)","points":8},{"critere":"C peu stockée, excès éliminé dans les urines ; A stockée dans le foie et les graisses, d'où la toxicité d'un excès","points":6},{"critere":"Scorbut (C), rachitisme (D), troubles de la vision nocturne (A)","points":6}],"dureeMin":7,"corrige":"1. Plus une molécule a de groupes –OH par rapport à sa chaîne carbonée, plus elle est soluble dans l'eau.\n- La **vitamine C**, petite et riche en –OH, est **hydrosoluble**.\n- La **vitamine A**, longue chaîne carbonée avec un seul –OH, est **liposoluble**.\n2. La vitamine C, hydrosoluble, est **peu stockée** : l'excès part dans les **urines**, il faut donc des apports **quotidiens**. La vitamine A, liposoluble, est **stockée** dans le foie et les graisses : elle s'accumule, et un excès peut devenir **toxique**.\n3. Carence en vitamine C → **scorbut** ; en vitamine D → **rachitisme** ; en vitamine A → **troubles de la vision nocturne**."}$exo$::jsonb),
  ('3df7d090-74c7-50fd-9430-21e5e5ec03e4'::uuid, 2, 'application', $exo${"titre":"Ce comprimé contient-il vraiment 100 mg de vitamine C ?","consigne":"Explique le principe du dosage, fais les calculs en écrivant les formules, puis conclus.","enonce":"**Situation.** La boîte d'un complément annonce « vitamine C : 100 mg par comprimé ». Gabriel vérifie.\n\n**Protocole.** Il dissout un comprimé dans de l'eau et complète à **100,0 mL** en fiole jaugée. Il prélève **10,0 mL** de cette solution, ajoute quelques gouttes d'empois d'amidon, puis verse une solution de diiode I₂ à **5,00 × 10⁻³ mol/L**. L'équivalence est obtenue pour **11,4 mL** de diiode versé.\n\n**Réaction du dosage** : C₆H₈O₆ + I₂ → C₆H₆O₆ + 2 H⁺ + 2 I⁻ (une mole de diiode réagit avec une mole d'acide ascorbique).\n\n**Donnée** : M(acide ascorbique) = 176 g/mol.\n\n1. Quel est le rôle du diiode dans cette réaction ? Comment l'empois d'amidon permet-il de repérer l'équivalence ?\n2. Calcule la quantité de matière de vitamine C dans les 10,0 mL dosés.\n3. Déduis-en la masse de vitamine C dans le comprimé. L'étiquette est-elle exacte ?","bareme":[{"critere":"Le diiode oxyde l'acide ascorbique ; l'empois bleuit dès que le diiode est en excès, ce qui repère l'équivalence","points":6},{"critere":"n(vit C) = n(I₂) = C × Véq = 5,70 × 10⁻⁵ mol","points":6},{"critere":"Facteur 10 (100,0 mL / 10,0 mL) : 5,70 × 10⁻⁴ mol, m = n × M ≈ 0,100 g = 100 mg","points":6},{"critere":"Conclusion : l'étiquette est exacte","points":2}],"dureeMin":12,"corrige":"1. Le diiode **oxyde** l'acide ascorbique (vitamine C). Tant qu'il reste de la vitamine C, le diiode versé est consommé aussitôt. Dès qu'elle a entièrement réagi, le diiode se trouve **en excès** : l'empois d'amidon **bleuit**, ce qui repère l'**équivalence**.\n2. À l'équivalence, une mole de I₂ pour une mole de vitamine C : n(vit C) = n(I₂) = C × Véq = 5,00 × 10⁻³ × 11,4 × 10⁻³ = **5,70 × 10⁻⁵ mol** dans 10,0 mL.\n3. Le comprimé est dissous dans 100,0 mL, dix fois plus que le volume dosé : n(comprimé) = 10 × 5,70 × 10⁻⁵ = **5,70 × 10⁻⁴ mol**.\nm = n × M = 5,70 × 10⁻⁴ × 176 ≈ **0,100 g = 100 mg**.\nLa masse trouvée correspond à l'indication : l'**étiquette est exacte**."}$exo$::jsonb),
  ('3df7d090-74c7-50fd-9430-21e5e5ec03e4'::uuid, 3, 'application', $exo${"titre":"Deux étiquettes avant la plage","consigne":"Analyse les deux documents, puis réponds en argumentant avec les notions du cours. Termine par un conseil rédigé à Zoé.","enonce":"**Situation.** Avant d'aller à la plage, Zoé achète une boisson et une crème solaire.\n\n**Document 1 – Étiquette de la boisson**\n\n> Ingrédients : eau, sucre, jus de citron, colorant (E150d), conservateur (E211), antioxydant (E300 : acide ascorbique), épaississant (E412), arôme naturel de vanille.\n\n**Document 2 – Étiquette de la crème solaire**\n\n> SPF 50 – logo UVA entouré. Ingrédients : aqua, filtres UV, glycérine (hydratant), tocophérol (vitamine E), parfum.\n\n1. Classe chaque additif de la boisson dans sa famille et donne son rôle. Justifie par les numéros.\n2. Un additif est-il autorisé une fois pour toutes ? Appuie-toi sur l'exemple du dioxyde de titane E171.\n3. Une amie affirme qu'un arôme de vanille de synthèse est « moins bon pour la santé » que l'arôme naturel. Discute cette affirmation.\n4. Explique ce que signifient « SPF 50 » et le logo UVA, en distinguant les effets des UVA et des UVB. Pourquoi la crème contient-elle de la vitamine E ? Pourquoi « aqua » est-il écrit en premier ?\n5. Rédige un conseil de trois ou quatre lignes à Zoé pour se protéger du soleil.","bareme":[{"critere":"Familles justes : E150d colorant, E211 conservateur, E300 antioxydant, E412 texturant, avec leurs rôles","points":5},{"critere":"Autorisation européenne après évaluation avec DJA, retrait en cas de doute (E171 interdit depuis 2022)","points":3},{"critere":"Molécule de synthèse identique : mêmes propriétés ; l'extrait naturel contient d'autres molécules qui enrichissent le goût","points":3},{"critere":"SPF surtout contre les UVB (coups de soleil), logo UVA (vieillissement, cancers) ; vitamine E antioxydante ; aqua solvant majoritaire","points":6},{"critere":"Conseil cohérent : aucune protection totale, en remettre souvent, limiter l'exposition","points":3}],"dureeMin":18,"corrige":"1. - **E150d** (E100 à E199) : **colorant**, donne ou rend la couleur.\n- **E211** (E200 à E299) : **conservateur**, limite le développement des micro-organismes.\n- **E300** (E300 à E399) : **antioxydant**, ralentit l'oxydation.\n- **E412** (E400 à E499) : **texturant** (épaississant), donne la consistance.\n2. Non. Chaque additif est **autorisé au niveau européen après évaluation**, avec une **DJA** ; il peut être **retiré** quand un doute apparaît : le dioxyde de titane **E171** est interdit dans l'alimentation dans l'Union européenne depuis **2022**.\n3. L'affirmation est fausse telle quelle : une molécule de synthèse **identique** à la molécule naturelle (la **vanilline**) a **les mêmes propriétés**. La différence est gustative : l'extrait naturel contient **d'autres molécules** qui enrichissent le goût.\n4. L'indice **SPF** mesure surtout la protection contre les **UVB**, responsables des **coups de soleil**, qui participent aux cancers de la peau ; SPF 50 est une protection élevée. Le **logo UVA** signale une protection contre les **UVA**, qui pénètrent plus profondément (**vieillissement** de la peau, **cancers**). La **vitamine E** (tocophérol) est un **antioxydant** : elle neutralise les **radicaux libres** produits par les UV. Les ingrédients sont écrits par **concentration décroissante** : l'eau (aqua), le **solvant**, est le plus abondant.\n5. Exemple : « Zoé, ta crème protège bien des UVB et des UVA, mais **aucune crème ne protège totalement**. Remets-en **souvent**, surtout après la baignade, et **limite ton exposition** : évite les heures les plus chaudes et couvre-toi. »"}$exo$::jsonb),
  ('b7f02856-3fcb-5926-8ea9-0f65459eb690'::uuid, 1, 'application', $exo${"titre":"Où est l'eau de M. Lefèvre ?","consigne":"Fais les calculs demandés en montrant ta démarche, puis réponds par des phrases précises.","enonce":"**Situation.** M. Lefèvre pèse **70 kg**. On admet qu'1 kg d'eau occupe 1 L.\n\n1. Calcule le volume d'eau totale de son organisme.\n2. Calcule le volume de chaque compartiment : liquide intracellulaire, liquide extracellulaire, puis, dans l'extracellulaire, liquide interstitiel et plasma.\n3. Qu'appelle-t-on le **milieu intérieur** ? Cite ses constituants.","bareme":[{"critere":"Eau totale : 60 % de 70 kg = 42 L","points":5},{"critere":"Intracellulaire 28 L, extracellulaire 14 L, interstitiel 10,5 L, plasma 3,5 L","points":10},{"critere":"Milieu intérieur = liquide extracellulaire : plasma, liquide interstitiel, lymphe","points":5}],"dureeMin":7,"corrige":"1. L'eau représente environ **60 %** de la masse d'un adulte : 0,60 × 70 = **42 kg**, soit **42 L**.\n2. - Intracellulaire (2/3) : 42 × 2/3 = **28 L**.\n- Extracellulaire (1/3) : 42 × 1/3 = **14 L**.\n- Interstitiel (3/4 de l'extracellulaire) : 14 × 3/4 = **10,5 L**.\n- Plasma (1/4 de l'extracellulaire) : 14 × 1/4 = **3,5 L**.\n3. Le **milieu intérieur** est le **liquide extracellulaire**, dans lequel baignent les cellules : **plasma**, **liquide interstitiel** et **lymphe**. Sa composition est maintenue presque constante par des organes régulateurs, dont le rein."}$exo$::jsonb),
  ('b7f02856-3fcb-5926-8ea9-0f65459eb690'::uuid, 2, 'application', $exo${"titre":"Du plasma à l'urine","consigne":"Exploite le tableau : décris des valeurs précises, puis interprète-les avec tes connaissances.","enonce":"**Document – Composition comparée (en g/L) chez un adulte en bonne santé**\n\n| Le constituant | Plasma | Urine primitive | Urine définitive |\n| Protéines | 70 | 0 | 0 |\n| Glucose | 1 | 1 | 0 |\n| Urée | 0,3 | 0,3 | 20 |\n\nChaque jour, les glomérules filtrent environ **180 L** de plasma, et la diurèse est d'environ **1,5 L**.\n\n1. Compare le plasma et l'urine primitive. Quelle fonction du néphron cette comparaison met-elle en évidence ? Où a-t-elle lieu ?\n2. Compare l'urine primitive et l'urine définitive pour le glucose. Quelle fonction est mise en évidence ?\n3. Calcule par combien la concentration de l'urée est multipliée entre l'urine primitive et l'urine définitive. Explique ce résultat à l'aide du pourcentage d'eau réabsorbée, que tu calculeras.","bareme":[{"critere":"Filtration glomérulaire : même composition sans les protéines, trop grosses, au niveau du glomérule","points":6},{"critere":"Réabsorption tubulaire du glucose en totalité (1 g/L puis 0)","points":5},{"critere":"Facteur 20 ÷ 0,3 ≈ 67 et eau réabsorbée : (180 − 1,5) ÷ 180 ≈ 99,2 %","points":6},{"critere":"Interprétation : l'eau est massivement réabsorbée alors que l'urée l'est peu, elle se concentre","points":3}],"dureeMin":12,"corrige":"1. L'urine primitive a la **même composition** que le plasma (glucose 1 g/L, urée 0,3 g/L) **sauf les protéines** (70 g/L dans le plasma, 0 dans l'urine primitive). C'est la **filtration glomérulaire** : au niveau du **glomérule**, le plasma est filtré, les protéines, **trop grosses**, restent dans le sang.\n2. Le glucose passe de **1 g/L** dans l'urine primitive à **0** dans l'urine définitive : il est **réabsorbé en totalité** par le tube, et retourne dans le sang. C'est la **réabsorption tubulaire**.\n3. 20 ÷ 0,3 ≈ **67** : l'urée est environ 67 fois plus concentrée dans l'urine définitive.\nEau réabsorbée : (180 − 1,5) ÷ 180 = 178,5 ÷ 180 ≈ **99,2 %** (plus de 99 %).\nL'eau est **massivement réabsorbée** alors que l'urée l'est **peu** : la même quantité d'urée se retrouve dans un volume beaucoup plus petit, sa concentration augmente fortement. Le rein élimine ainsi ce **déchet** tout en conservant l'eau."}$exo$::jsonb),
  ('b7f02856-3fcb-5926-8ea9-0f65459eb690'::uuid, 3, 'application', $exo${"titre":"Deux bandelettes urinaires et un pesticide","consigne":"Analyse chaque situation en reliant les résultats au fonctionnement du néphron, puis rédige tes réponses de façon argumentée.","enonce":"**Situation 1.** Deux patients font une analyse d'urine.\n\n| | M. Durand | Mme Petit |\n| Glucose dans l'urine | 6 g/L | 0 |\n| Protéines dans l'urine | 0 | 1,5 g/L |\n| Glycémie | 2,4 g/L | 0,95 g/L |\n| Remarque | Soif excessive | Aucune |\n\n**Situation 2.** Un agriculteur manipule depuis des années un **pesticide liposoluble**, absorbé par la peau et les voies respiratoires.\n\n1. Nomme les anomalies urinaires de chaque patient (vocabulaire médical) et dis pourquoi elles sont anormales.\n2. Pour chaque patient, localise l'étape du fonctionnement rénal en cause et explique l'origine probable de l'anomalie.\n3. Traduis le terme utilisé pour la soif de M. Durand.\n4. Situation 2 : ce pesticide est-il un xénobiotique ? Décris son devenir dans l'organisme, de l'absorption à l'élimination, et explique pourquoi une exposition répétée est préoccupante.","bareme":[{"critere":"Glycosurie (M. Durand) et protéinurie (Mme Petit), toutes deux anormales","points":3},{"critere":"Protéinurie : atteinte du glomérule qui laisse passer les protéines","points":4},{"critere":"Glycosurie : glycémie trop élevée (2,4 g/L), glucose filtré en excès, réabsorption dépassée ; rein non en cause, diabète évoqué","points":5},{"critere":"Polydipsie = soif excessive","points":2},{"critere":"Xénobiotique ; absorption, distribution, métabolisme hépatique, stockage adipeux, élimination ; accumulation et toxicité","points":6}],"dureeMin":18,"corrige":"1. M. Durand a une **glycosurie** (glucose dans l'urine), Mme Petit une **protéinurie** (protéines dans l'urine). Normalement, l'urine définitive ne contient **ni glucose ni protéines**.\n2. - **Mme Petit** : les protéines, trop grosses, ne sont normalement **pas filtrées** par le glomérule. Leur présence signale une **atteinte du glomérule** : l'étape de **filtration** est en cause.\n- **M. Durand** : sa glycémie (**2,4 g/L**) est très au-dessus de la normale. Le glucose filtré est alors trop abondant et le tube ne peut plus **tout réabsorber** : il passe dans l'urine. Le rein n'est pas malade : c'est la **glycémie trop élevée** qui est en cause, ce qui évoque un **diabète**.\n3. **Polydipsie** : soif excessive (poly- : beaucoup ; -dipsie : soif).\n4. Oui : c'est une substance **étrangère** à l'organisme, qu'il ne produit pas, donc un **xénobiotique**. Son devenir : **absorption** cutanée et respiratoire → **distribution** par le sang → **métabolisme**, surtout par le **foie**, qui le transforme → **stockage** dans le **tissu adipeux**, puisqu'il est liposoluble → **élimination** (urine, bile et selles, air expiré, sueur). Une exposition répétée est préoccupante : stocké, il **s'accumule au fil des expositions** et peut avoir des effets toxiques sur le **foie** et les **reins**, perturber les hormones ou être cancérogène."}$exo$::jsonb),
  ('5028cb6a-9ae4-5fc1-a109-7882364a0197'::uuid, 1, 'application', $exo${"titre":"Deux hormones pour une glycémie","consigne":"Réponds à chaque question par des phrases précises, avec le vocabulaire du cours.","enonce":"1. Définis une **hormone**.\n2. Quelles cellules du pancréas sécrètent l'insuline ? Et le glucagon ? Dans quelles structures se trouvent-elles ?\n3. Complète en phrases : après un repas, quelle hormone est sécrétée et quelles sont ses actions ? À jeun, quelle hormone est sécrétée et quelles sont ses actions sur le foie ?","bareme":[{"critere":"Hormone : sécrétée par une glande endocrine dans le sang, agit à distance sur des cellules cibles à récepteurs","points":5},{"critere":"Cellules β (insuline) et α (glucagon) des îlots de Langerhans","points":5},{"critere":"Insuline : absorption du glucose par muscles et tissu adipeux, glycogenèse ; glucagon : glycogénolyse et néoglucogenèse","points":10}],"dureeMin":7,"corrige":"1. Une **hormone** est une molécule sécrétée par une **glande endocrine** dans le **sang**, qui agit **à distance** sur des **cellules cibles** porteuses de **récepteurs** spécifiques.\n2. L'insuline est sécrétée par les **cellules β**, le glucagon par les **cellules α** ; ces cellules se trouvent dans les **îlots de Langerhans**, la partie endocrine du pancréas.\n3. - **Après un repas**, la glycémie monte : les cellules β sécrètent l'**insuline** (seule hormone hypoglycémiante). Les **muscles** et le **tissu adipeux** absorbent le glucose ; le **foie** et les muscles le stockent en **glycogène** (glycogenèse) ; l'excès devient des graisses.\n- **À jeun**, la glycémie tend à baisser : les cellules α sécrètent le **glucagon** (hyperglycémiant). Le **foie** dégrade son glycogène (**glycogénolyse**) et fabrique du glucose (**néoglucogenèse**), qu'il libère dans le sang."}$exo$::jsonb),
  ('5028cb6a-9ae4-5fc1-a109-7882364a0197'::uuid, 2, 'application', $exo${"titre":"Deux courbes après le petit-déjeuner","consigne":"Exploite le document : décris avec des valeurs précises, compare, interprète, puis conclus.","enonce":"**Document – Glycémie (g/L) de deux adultes, à jeun puis après le même petit-déjeuner**\n\n| Temps | 0 (à jeun) | 30 min | 60 min | 120 min |\n| Élodie | 0,85 | 1,30 | 1,20 | 0,88 |\n| M. Morel | 1,35 | 2,10 | 2,50 | 2,20 |\n\nUne deuxième glycémie à jeun de M. Morel, mesurée la semaine suivante, vaut **1,32 g/L**.\n\n1. Décris l'évolution de la glycémie d'Élodie et explique son retour à la valeur de départ en nommant l'hormone et ses cibles.\n2. Compare la courbe de M. Morel à celle d'Élodie.\n3. M. Morel est-il diabétique ? Justifie avec le critère du cours.\n4. En quoi la régulation d'Élodie illustre-t-elle l'homéostasie ?","bareme":[{"critere":"Description chiffrée (0,85 → 1,30 à 30 min → 0,88 à 120 min) et retour en deux heures","points":5},{"critere":"Explication : insuline des cellules β, absorption du glucose par muscles et tissu adipeux, stockage en glycogène","points":5},{"critere":"Comparaison chiffrée : M. Morel plus haut à jeun, pic plus élevé et plus tardif, pas de retour","points":4},{"critere":"Diabète : glycémie à jeun ≥ 1,26 g/L à deux reprises (1,35 et 1,32)","points":4},{"critere":"Homéostasie : glycémie maintenue autour d'une valeur, équilibre dynamique","points":2}],"dureeMin":12,"corrige":"1. La glycémie d'Élodie passe de **0,85 g/L** à jeun à **1,30 g/L** 30 min après le repas (le glucose absorbé arrive dans le sang), puis redescend à **0,88 g/L** à 120 min : elle revient à sa valeur de départ en **deux heures** environ. L'élévation stimule les **cellules β** des îlots de Langerhans, qui sécrètent l'**insuline** : les **muscles** et le **tissu adipeux** absorbent le glucose, le **foie** et les muscles le stockent en **glycogène**.\n2. M. Morel part d'une glycémie à jeun plus élevée (**1,35** contre 0,85 g/L), monte plus haut (**2,50 g/L** à 60 min contre 1,30 à 30 min), et reste à **2,20 g/L** à 120 min : sa glycémie **ne revient pas** à sa valeur de départ.\n3. Le diabète est défini par une **glycémie à jeun ≥ 1,26 g/L à deux reprises**. M. Morel a 1,35 puis 1,32 g/L : il est **diabétique**.\n4. Chez Élodie, la glycémie **oscille autour d'une valeur** (proche de 1 g/L) et y revient après chaque écart : c'est l'**homéostasie**, un **équilibre dynamique** du milieu intérieur."}$exo$::jsonb),
  ('5028cb6a-9ae4-5fc1-a109-7882364a0197'::uuid, 3, 'application', $exo${"titre":"Le cas de Léo, 13 ans","consigne":"Suis la démarche du cas clinique : relève les signes, compare aux valeurs de référence, relie-les au mécanisme, nomme la pathologie et justifie le traitement.","enonce":"**Situation.** Léo, 13 ans, sans surpoids, est amené chez le médecin : depuis trois semaines, il a **très soif**, se lève la nuit pour **uriner**, a **perdu 4 kg** et se sent **très fatigué**.\n\n**Examens** :\n\n| L'examen | Le résultat |\n| Glycémie | 3,1 g/L |\n| Glucose dans l'urine | présent |\n| Corps cétoniques | présents |\n| Anticorps dirigés contre les îlots de Langerhans | présents |\n\nSon grand-père, 67 ans, en surpoids et sédentaire, a découvert son diabète lors d'une prise de sang de routine.\n\n1. Classe les signes de Léo en signes cliniques et signes paracliniques.\n2. Explique l'enchaînement qui relie l'hyperglycémie de Léo à sa soif intense, en utilisant les termes glycosurie, polyurie et polydipsie.\n3. De quel type de diabète Léo est-il atteint ? Justifie par au moins trois arguments, dont l'étiologie.\n4. Quel traitement est indispensable pour Léo, et pourquoi ? Quelle complication aiguë de ce traitement doit-il savoir reconnaître, et que doit-il faire ?\n5. Compare en quelques lignes le diabète du grand-père à celui de Léo (type, origine, début, prévention).","bareme":[{"critere":"Cliniques : soif, urines abondantes, amaigrissement, fatigue ; paracliniques : glycémie, glycosurie, corps cétoniques, anticorps","points":3},{"critere":"Chaîne : hyperglycémie → glycosurie (au-delà de 1,8 g/L) → polyurie → déshydratation → polydipsie","points":5},{"critere":"Type 1 justifié : jeune âge, début brutal, anticorps anti-îlots = maladie auto-immune détruisant les cellules β","points":5},{"critere":"Insuline à vie car plus de sécrétion ; hypoglycémie (sueurs, tremblements, malaise) → sucre immédiatement","points":4},{"critere":"Comparaison : type 2, insulinorésistance, début progressif et silencieux, en grande partie évitable","points":3}],"dureeMin":20,"corrige":"1. **Signes cliniques** : soif intense, urines abondantes (même la nuit), amaigrissement de 4 kg, fatigue. **Signes paracliniques** : glycémie à 3,1 g/L, glycosurie, corps cétoniques, anticorps anti-îlots.\n2. La glycémie (3,1 g/L) dépasse environ **1,8 g/L** : le rein ne réabsorbe plus tout le glucose, qui passe dans l'urine (**glycosurie**). Le glucose **entraîne l'eau** dans l'urine : les urines sont abondantes (**polyurie**). Léo perd de l'eau et se **déshydrate**, ce qui provoque une soif intense (**polydipsie**).\n3. Léo est atteint d'un **diabète de type 1** :\n- il est **jeune** (13 ans) et sans surpoids ;\n- le **début est brutal** (trois semaines), avec soif, polyurie, amaigrissement et fatigue ;\n- la présence d'**anticorps dirigés contre les îlots** signe une maladie **auto-immune** : son système immunitaire **détruit les cellules β**, il ne produit **plus d'insuline** (étiologie).\n4. Il lui faut de l'**insuline à vie** (injections ou pompe), avec surveillance de la glycémie, car ses cellules β ne la produisent plus : l'hygiène de vie seule ne peut pas la remplacer. Complication aiguë du traitement : l'**hypoglycémie** (sueurs, tremblements, malaise) ; il doit prendre du **sucre immédiatement**.\n5. Le grand-père a très probablement un **diabète de type 2** (90 % des cas) : après 40 ans, avec surpoids et sédentarité comme facteurs de risque ; origine : **insulinorésistance** puis insuffisance de sécrétion ; début **progressif et silencieux**, découvert par une prise de sang. Traitement par hygiène de vie puis médicaments, parfois insuline. Contrairement au type 1, il est **en grande partie évitable** (activité physique, poids, alimentation)."}$exo$::jsonb),
  ('baf14f01-e74c-54bb-a10d-5b1ff44bb209'::uuid, 1, 'application', $exo${"titre":"Bactérie ou virus ?","consigne":"Réponds à chaque question par des phrases précises, avec le vocabulaire du cours.","enonce":"**Situation.** Le même jour, Jade a une **angine à streptocoque** (une bactérie) et son frère Tom a la **grippe** (un virus).\n\n1. Compare une bactérie et un virus : taille, organisation, mode de reproduction.\n2. Le médecin prescrit un antibiotique à Jade mais pas à Tom. Explique pourquoi un antibiotique n'a aucune prise sur un virus.\n3. Cite deux autres catégories d'agents pathogènes, avec un exemple de maladie pour chacune.","bareme":[{"critere":"Comparaison juste : taille (µm / nm), cellule procaryote contre acide nucléique dans une capside, division contre reproduction dans une cellule hôte","points":10},{"critere":"Virus sans paroi, sans ribosome ni métabolisme propre : cibles des antibiotiques absentes","points":6},{"critere":"Deux catégories justes avec un exemple (champignon, parasite, prion)","points":4}],"dureeMin":8,"corrige":"1. | | Bactérie | Virus |\n| Taille | Environ 1 à 10 µm (microscope optique) | Environ 20 à 300 nm (microscope électronique) |\n| Organisation | **Cellule procaryote** : paroi, membrane, cytoplasme, ribosomes, ADN libre sans noyau | **Pas une cellule** : un acide nucléique (ADN ou ARN) dans une **capside** protéique, parfois une enveloppe |\n| Reproduction | Seule, par **division** : une bactérie en donne deux | Seulement **dans une cellule hôte** : parasite intracellulaire obligatoire |\n2. Un antibiotique vise des structures bactériennes (paroi, ribosomes, ADN, membrane) absentes des cellules humaines. Un virus n'a **ni paroi, ni ribosome, ni métabolisme propre** : l'antibiotique n'a **aucune prise** sur lui. La grippe de Tom ne se soigne donc pas par antibiotique.\n3. Par exemple : **champignons** (candidose, pied d'athlète) ; **parasites** (paludisme, gale, ténia) ; **prions** (maladie de Creutzfeldt-Jakob)."}$exo$::jsonb),
  ('baf14f01-e74c-54bb-a10d-5b1ff44bb209'::uuid, 2, 'application', $exo${"titre":"L'antibiogramme de Mme Blanchard","consigne":"Exploite le document, compare les valeurs aux seuils et justifie le choix du traitement.","enonce":"**Situation.** Mme Blanchard a une infection urinaire. Le laboratoire isole la bactérie et réalise un antibiogramme.\n\n**Document – Résultats et seuils fournis par le laboratoire**\n\n| L'antibiotique (famille, cible) | Diamètre mesuré | Sensible si | Résistante si |\n| Amoxicilline (pénicilline, paroi) | 10 mm | ≥ 19 mm | < 16 mm |\n| Gentamicine (aminoside, ribosomes) | 20 mm | ≥ 18 mm | < 15 mm |\n| Ciprofloxacine (quinolone, ADN) | 16 mm | ≥ 25 mm | < 22 mm |\n\n1. Décris brièvement le principe de l'antibiogramme. Que représente le diamètre mesuré ?\n2. Classe la souche comme sensible ou résistante à chaque antibiotique, en justifiant par les valeurs.\n3. Quel antibiotique le médecin doit-il choisir ? Explique comment il agit sur la bactérie.\n4. Dans de bonnes conditions, cette bactérie se divise toutes les 20 minutes. Combien de bactéries une seule bactérie donne-t-elle en 3 heures ? Qu'en conclus-tu sur l'intérêt d'un traitement adapté rapidement ?","bareme":[{"critere":"Principe : culture sur gélose, disques d'antibiotiques, incubation, zone d'inhibition si la bactérie est sensible","points":4},{"critere":"Classement justifié : résistante à l'amoxicilline (10 < 16) et à la ciprofloxacine (16 < 22), sensible à la gentamicine (20 ≥ 18)","points":6},{"critere":"Choix de la gentamicine, qui agit sur les ribosomes (synthèse des protéines)","points":5},{"critere":"9 divisions en 3 h : 2⁹ = 512 bactéries, conclusion sur la rapidité de multiplication","points":5}],"dureeMin":12,"corrige":"1. On étale la bactérie de la patiente sur une **gélose**, on dépose des **disques** imprégnés de différents antibiotiques, on **incube**. Autour d'un disque, une **zone d'inhibition** (sans bactéries) se forme si la bactérie est sensible : son diamètre est comparé à des valeurs critiques.\n2. - Amoxicilline : 10 mm < 16 mm : souche **résistante**.\n- Gentamicine : 20 mm ≥ 18 mm : souche **sensible**.\n- Ciprofloxacine : 16 mm < 22 mm : souche **résistante**.\n3. Le médecin choisit la **gentamicine**, seul antibiotique auquel la souche est sensible. C'est un **aminoside** qui cible les **ribosomes** : il bloque la **synthèse des protéines** de la bactérie. L'antibiogramme guide ainsi le choix du traitement le plus efficace.\n4. 3 h = 180 min = 9 × 20 min : **9 divisions**. Une bactérie donne 2⁹ = **512 bactéries**. La population augmente très vite : un antibiotique inefficace (ici l'amoxicilline) laisserait l'infection progresser ; il faut un traitement **adapté** et **rapide**."}$exo$::jsonb),
  ('baf14f01-e74c-54bb-a10d-5b1ff44bb209'::uuid, 3, 'application', $exo${"titre":"Les antibiotiques, c'est pas automatique","consigne":"Exploite les données, fais le calcul demandé, puis rédige une argumentation structurée qui s'appuie sur le mécanisme de sélection.","enonce":"**Document 1 – Une population bactérienne.** Dans une infection, un patient héberge **10⁹ bactéries** d'une même espèce. Par **mutation**, environ **une bactérie sur 10⁷** est résistante à l'antibiotique prescrit. Les bactéries se divisent toutes les 20 minutes.\n\n**Document 2 – Deux comportements**\n\n> Karim a une grippe. Il prend les antibiotiques qui restaient à sa sœur « pour guérir plus vite ».\n> Anaïs se sent mieux au troisième jour d'un traitement de sept jours et arrête ses antibiotiques.\n\n1. Combien de bactéries résistantes le patient du document 1 héberge-t-il au départ ? Que deviennent les bactéries sensibles et les résistantes au cours du traitement ?\n2. S'il ne reste que les bactéries résistantes et qu'elles se divisent sans frein, combien seront-elles au bout de 4 heures ? Conclus sur l'évolution de la population.\n3. Distingue résistance naturelle et résistance acquise. Par quels deux mécanismes une souche acquiert-elle une résistance ?\n4. Analyse les comportements de Karim et d'Anaïs : en quoi chacun est-il inutile ou dangereux ?\n5. Explique pourquoi une infection nosocomiale à bactérie résistante est particulièrement grave.","bareme":[{"critere":"10⁹ ÷ 10⁷ = 100 résistantes ; sensibles tuées, résistantes survivantes","points":4},{"critere":"12 divisions en 4 h : 100 × 2¹² = 409 600 ≈ 4 × 10⁵, population devenue résistante (sélection)","points":5},{"critere":"Naturelle (toute l'espèce) contre acquise (une souche), par mutation ou transfert de gènes (plasmides)","points":4},{"critere":"Karim : grippe virale, antibiotique inutile et sélection de résistances, médicament d'un autre ; Anaïs : arrêt de soi-même","points":5},{"critere":"Nosocomiale : contractée en établissement de santé, peu d'antibiotiques efficaces restants","points":2}],"dureeMin":20,"corrige":"1. 10⁹ ÷ 10⁷ = **100 bactéries résistantes** au départ. Sous traitement, les bactéries **sensibles meurent** ; les rares **résistantes survivent**.\n2. 4 h = 240 min = 12 × 20 min : **12 divisions**. 100 × 2¹² = 100 × 4 096 = **409 600**, soit environ **4 × 10⁵** bactéries, toutes résistantes. L'antibiotique n'a pas créé la résistance : il a **sélectionné** les bactéries résistantes, qui se multiplient et forment une **population résistante**.\n3. - **Résistance naturelle** : **toutes les souches** d'une espèce échappent à l'antibiotique (par exemple une bactérie sans paroi face aux pénicillines).\n- **Résistance acquise** : **une souche** devient résistante, par **mutation** de son ADN ou par **transfert de gènes** d'une bactérie à une autre, souvent portés par des **plasmides**.\n4. - **Karim** : la grippe est due à un **virus**, sur lequel l'antibiotique n'a **aucune prise** ; il ne guérira pas plus vite. En revanche, il expose ses propres bactéries à l'antibiotique et favorise la **sélection de souches résistantes**. De plus, il ne faut **jamais prendre les antibiotiques d'un autre**.\n- **Anaïs** : elle **arrête de soi-même** un traitement prescrit ; il faut aller au bout de la prescription.\nCes gestes justifient la campagne « Les antibiotiques, c'est pas automatique ».\n5. Une infection **nosocomiale** est contractée lors d'un séjour dans un **établissement de santé**, chez des patients souvent fragiles ; si la bactérie est résistante, il reste **peu d'antibiotiques efficaces** pour la traiter."}$exo$::jsonb),
  ('ca087cd7-d740-5423-8da9-642ebee4035d'::uuid, 1, 'application', $exo${"titre":"Les marqueurs du soi","consigne":"Réponds à chaque question par des phrases précises.","enonce":"1. Définis le **soi** et le **non-soi**. Donne un exemple de « soi modifié ».\n2. Recopie et complète :\n\n| Le marqueur | Où le trouve-t-on ? |\n| Molécules du CMH de classe I | … |\n| Molécules du CMH de classe II | … |\n| Antigènes des groupes sanguins | … |\n\n3. Définis **antigène** et **épitope**.\n4. Pourquoi faut-il chercher un donneur compatible avant une greffe ?","bareme":[{"critere":"Soi toléré, non-soi reconnu comme étranger ou soi modifié (cellule infectée ou cancéreuse)","points":5},{"critere":"CMH I : toutes les cellules nucléées ; CMH II : macrophages, cellules dendritiques, lymphocytes B ; groupes sanguins : globules rouges","points":7},{"critere":"Antigène et épitope correctement définis","points":5},{"critere":"Greffe : marqueurs du soi différents reconnus comme non-soi, risque de rejet","points":3}],"dureeMin":8,"corrige":"1. Le **soi** est l'ensemble des molécules propres à un individu, que son système immunitaire **tolère**. Le **non-soi** est tout ce qui est reconnu comme **étranger** (micro-organismes, cellules d'un autre individu) ou comme un **soi modifié** : par exemple une **cellule infectée** par un virus ou une **cellule cancéreuse**.\n2. - CMH de classe I (système HLA) : à la surface de **toutes les cellules nucléées**.\n- CMH de classe II : sur certaines cellules immunitaires, **macrophages, cellules dendritiques, lymphocytes B**.\n- Antigènes des groupes sanguins (A, B, Rhésus) : à la surface des **globules rouges**.\n3. Un **antigène** est une molécule reconnue comme étrangère, capable de déclencher une réponse immunitaire. Un **épitope** (déterminant antigénique) est la petite partie de l'antigène effectivement reconnue.\n4. Les marqueurs du soi du donneur, s'ils sont différents, sont reconnus comme **non-soi** par le receveur : le greffon est attaqué, c'est le **rejet de greffe**. Un donneur compatible limite ce risque."}$exo$::jsonb),
  ('ca087cd7-d740-5423-8da9-642ebee4035d'::uuid, 2, 'application', $exo${"titre":"L'écharde d'Ethan","consigne":"Relie chaque observation à son mécanisme, en utilisant le vocabulaire du cours.","enonce":"**Situation.** Ethan s'est planté une écharde dans le doigt en jardinant. Quelques heures plus tard, le doigt est **rouge**, **chaud**, **gonflé** et **douloureux**. Le lendemain, un peu de pus apparaît : il contient de nombreux leucocytes et des débris de bactéries.\n\n1. Quelle barrière naturelle l'écharde a-t-elle franchie ? De quel type de barrière s'agit-il ?\n2. Nomme la réaction déclenchée et explique chacun des quatre symptômes.\n3. Comment les leucocytes arrivent-ils jusqu'au foyer infectieux ?\n4. Décris les étapes de la phagocytose et nomme les deux principaux phagocytes.\n5. Cette réaction est-elle spécifique des bactéries apportées par l'écharde ? Justifie.","bareme":[{"critere":"Peau (kératine) franchie, barrière mécanique","points":2},{"critere":"Réaction inflammatoire ; rougeur et chaleur par vasodilatation, œdème par perméabilité des capillaires, douleur par médiateurs et compression","points":7},{"critere":"Diapédèse : les leucocytes quittent les vaisseaux","points":3},{"critere":"Adhésion, ingestion, digestion par les enzymes des lysosomes, rejet des débris ; neutrophiles et macrophages","points":6},{"critere":"Non spécifique : immunité innée, rapide","points":2}],"dureeMin":12,"corrige":"1. L'écharde a franchi la **peau**, dont la **kératine** forme une barrière **mécanique**.\n2. C'est la **réaction inflammatoire** (immunité innée) :\n- **Rougeur et chaleur** : **vasodilatation**, plus de sang arrive ;\n- **Gonflement (œdème)** : les capillaires deviennent **plus perméables**, du plasma passe dans les tissus ;\n- **Douleur** : **médiateurs chimiques** (histamine, prostaglandines) et **compression** des terminaisons nerveuses par l'œdème.\n3. Les leucocytes **quittent les vaisseaux** en se faufilant entre les cellules de leur paroi : c'est la **diapédèse** ; ils rejoignent le foyer infectieux.\n4. Phagocytose : **adhésion** du phagocyte à la bactérie → **ingestion** (la bactérie est enfermée dans une vésicule) → **digestion** par les enzymes des **lysosomes** → **rejet des débris** (et présentation de fragments d'antigène aux lymphocytes). Principaux phagocytes : **polynucléaires neutrophiles** et **macrophages**. Le pus est fait de ces leucocytes et des débris.\n5. Non : la réaction inflammatoire est **non spécifique**. Elle se déclenche de la même façon quel que soit le pathogène, en quelques minutes à quelques heures : c'est l'**immunité innée**."}$exo$::jsonb),
  ('ca087cd7-d740-5423-8da9-642ebee4035d'::uuid, 3, 'application', $exo${"titre":"La grippe de Mme Moreau","consigne":"Analyse le cas en reliant les observations au virus et aux défenses de l'organisme ; rédige des réponses argumentées.","enonce":"**Situation.** En janvier, Mme Moreau, 45 ans, se réveille avec une **fièvre à 39,5 °C**, des **frissons**, des **courbatures**, des **maux de tête**, une **fatigue intense** et une **toux sèche**. Trois collègues de son bureau ont eu les mêmes symptômes la semaine précédente. Son médecin diagnostique une grippe.\n\n**Examen** : leucocytes 6 500 par mm³ (valeurs de référence : 4 000 à 10 000 par mm³).\n\n1. Présente l'agent de la grippe : nature, matériel génétique, protéines de surface.\n2. Comment Mme Moreau a-t-elle probablement été contaminée ? Quelles cellules le virus infecte-t-il ?\n3. Donne le terme médical pour sa fatigue intense. Comment expliquer que la fièvre et les courbatures ne soient pas causées directement par le virus ?\n4. Interprète le résultat de l'examen sanguin.\n5. Mme Moreau réclame des antibiotiques. Que lui répond le médecin ? Dans quel cas un antibiotique pourrait-il être utile ?\n6. Cite deux défenses de la première barrière des voies respiratoires qui tentent d'arrêter le virus, en précisant leur type.","bareme":[{"critere":"Virus influenza, à ARN, enveloppé, protéines H et N","points":3},{"critere":"Contamination respiratoire (gouttelettes, aérosols) et par les mains au bureau ; cellules épithéliales des voies respiratoires","points":4},{"critere":"Asthénie ; fièvre et courbatures dues à la réponse immunitaire ; leucocytes normaux (6 500, entre 4 000 et 10 000)","points":6},{"critere":"Maladie virale : antibiotique inutile, traitement symptomatique ; utile seulement en cas de surinfection bactérienne","points":4},{"critere":"Deux défenses justes : mucus qui piège et cils qui balaient (mécaniques), lysozyme (chimique)","points":3}],"dureeMin":18,"corrige":"1. La grippe est due au **virus influenza**, un **virus à ARN enveloppé**, qui porte deux protéines de surface : l'**hémagglutinine H** et la **neuraminidase N**.\n2. Plusieurs collègues étaient malades : elle a été contaminée par **voie respiratoire** (gouttelettes, aérosols émis en toussant ou en parlant) et/ou par les **mains** (surfaces partagées). Le virus infecte les **cellules épithéliales** des voies respiratoires.\n3. La fatigue intense s'appelle l'**asthénie**. La fièvre et les courbatures sont des **effets de la réponse immunitaire elle-même** : ce sont les défenses de l'organisme contre le virus qui les provoquent.\n4. 6 500 par mm³ est compris entre 4 000 et 10 000 : le nombre de **leucocytes est normal**.\n5. La grippe est une maladie **virale** : les antibiotiques n'ont aucune prise sur un virus, le traitement est surtout **symptomatique** (repos, contre la fièvre). Un antibiotique ne servirait qu'en cas de **surinfection bactérienne** (par exemple une pneumonie bactérienne compliquant la grippe).\n6. - **Mucus** qui piège les particules et **cils** qui les balaient vers l'extérieur : barrière **mécanique**.\n- **Lysozyme** de la salive : barrière **chimique**."}$exo$::jsonb),
  ('8634131c-57d5-5321-bde9-15cce95742ac'::uuid, 1, 'application', $exo${"titre":"L'usine à anticorps","consigne":"Réponds à chaque question par des phrases précises ; tu peux t'aider d'un petit schéma légendé pour la question 2.","enonce":"1. Compare l'ultrastructure d'un lymphocyte B et celle d'un plasmocyte (cytoplasme, réticulum endoplasmique granuleux, appareil de Golgi). Relie ces différences à la fonction du plasmocyte.\n2. Décris la structure d'une immunoglobuline G : forme, chaînes, paratopes, pied.\n3. Explique ce qu'est la **neutralisation** d'un virus par un anticorps.","bareme":[{"critere":"Plasmocyte : cytoplasme abondant, REG et Golgi très développés, organites de fabrication et d'export des anticorps","points":8},{"critere":"IgG en Y, deux chaînes lourdes et deux légères, ponts disulfure, deux paratopes identiques au bout des bras, pied à sites de fixation","points":8},{"critere":"Neutralisation : fixation sur l'antigène, complexe immun, virus qui ne peut plus agir","points":4}],"dureeMin":8,"corrige":"1. | | Lymphocyte B | Plasmocyte |\n| Cytoplasme | Peu abondant | **Abondant** |\n| REG | Peu développé | **Très développé** |\n| Golgi | Peu développé | **Très développé** |\nLe réticulum endoplasmique granuleux et l'appareil de Golgi **fabriquent et exportent des protéines** : le plasmocyte, qui sécrète des **anticorps en grande quantité**, a l'ultrastructure d'une **usine à anticorps**.\n2. Une IgG a une forme en **Y** : **quatre chaînes**, deux **lourdes** et deux **légères**, reliées par des **ponts disulfure**. Au bout de chaque bras, les parties **variables** forment deux **paratopes identiques**, qui fixent l'épitope. Le **pied** (fragment constant) porte le **site de fixation du complément** et le **site de fixation au phagocyte**.\n3. L'anticorps se fixe sur l'antigène du virus et forme un **complexe immun** : le virus **ne peut plus agir** (il ne peut plus se fixer sur ses cellules cibles). C'est la **neutralisation**."}$exo$::jsonb),
  ('8634131c-57d5-5321-bde9-15cce95742ac'::uuid, 2, 'application', $exo${"titre":"Pourquoi un rappel de vaccin ?","consigne":"Exploite le document : décris avec des valeurs, compare, puis interprète avec tes connaissances.","enonce":"**Document – Concentration d'anticorps (unités arbitraires) chez Lou après deux injections du même vaccin**\n\n| Jour | 0 | 7 | 14 | 30 | 60 | 63 | 67 | 90 |\n| Anticorps | 0 | 2 | 10 | 3 | 1 | 80 | 200 | 150 |\n\nLa première injection a lieu au jour 0, la seconde (le rappel) au jour 60.\n\n1. Décris et compare les deux réponses : délai, quantité maximale d'anticorps, durée.\n2. Nomme ces deux réponses et explique la différence entre elles. Quelles cellules sont responsables de cette différence ?\n3. Quelles cellules produisent les anticorps ? De quelles cellules dérivent-elles, et quel lymphocyte est nécessaire à leur activation ?\n4. Explique le principe de la vaccination à partir de ce document.","bareme":[{"critere":"Description chiffrée : maximum 10 à J14 puis baisse ; maximum 200 à J67, quelques jours après le rappel, 20 fois plus, encore 150 à J90","points":6},{"critere":"Réponse primaire et secondaire ; plus rapide, plus forte, plus durable grâce aux cellules mémoire","points":5},{"critere":"Plasmocytes issus des lymphocytes B activés, avec l'aide des LT4 (interleukines)","points":5},{"critere":"Vaccination : réponse primaire sans la maladie, infection ultérieure combattue par une réponse secondaire","points":4}],"dureeMin":12,"corrige":"1. - **Première injection** : les anticorps apparaissent lentement (2 à J7), atteignent un **maximum faible de 10** vers J14, puis diminuent (3 à J30, 1 à J60).\n- **Rappel** : en **quelques jours** les anticorps atteignent 80 (J63) puis **200** (J67), soit **20 fois plus** qu'à la première réponse, et ils restent élevés (150 à J90).\n2. La première est la **réponse primaire** (premier contact), la seconde la **réponse secondaire** : **plus rapide**, **plus forte** et **plus durable**. Cette différence est due aux **cellules mémoire** (lymphocytes B mémoire notamment) formées lors du premier contact.\n3. Les anticorps sont sécrétés par les **plasmocytes**, issus de la **différenciation des lymphocytes B** activés et multipliés (expansion clonale). Leur activation nécessite l'aide des **lymphocytes T4 auxiliaires**, qui sécrètent des **interleukines**.\n4. Vacciner, c'est provoquer une **réponse primaire sans la maladie**, avec un antigène rendu inoffensif ; le rappel renforce la mémoire. En cas de vraie infection, la réponse sera **secondaire** : rapide et efficace, avant que la maladie s'installe."}$exo$::jsonb),
  ('8634131c-57d5-5321-bde9-15cce95742ac'::uuid, 3, 'application', $exo${"titre":"Le bilan sanguin de M. Rousseau","consigne":"Analyse les résultats, puis explique les mécanismes de défense en jeu dans des réponses rédigées et argumentées.","enonce":"**Situation.** M. Rousseau, 30 ans, a de la fièvre depuis cinq jours. Son médecin prescrit un bilan.\n\n**Document 1 – Numération formule sanguine** : polynucléaires neutrophiles normaux ; **lymphocytes nettement augmentés**.\n\n**Document 2 – Marqueur de l'inflammation** : protéine C réactive (CRP) augmentée.\n\n**Document 3 – Sérodiagnostic** du virus X : **IgM spécifiques présentes**, IgG spécifiques absentes.\n\n1. Que suggère la numération formule sanguine ? Que montre la CRP ?\n2. Que permet de conclure le sérodiagnostic ? Justifie.\n3. Le virus X se multiplie à l'intérieur de cellules. Explique comment elles sont éliminées : cellule effectrice, molécule du soi qui présente l'antigène, mode d'action.\n4. Pourquoi les anticorps seuls ne suffiraient-ils pas à éliminer ce virus ? Quel rôle gardent-ils ?\n5. Explique pourquoi le rôle du lymphocyte T4 est central dans ces deux réponses, en t'appuyant sur l'exemple du VIH.","bareme":[{"critere":"Lymphocytes augmentés : orientation vers une infection virale ; CRP augmentée : inflammation","points":3},{"critere":"IgM spécifiques : infection récente (IgG seules = ancienne ou vaccination)","points":3},{"critere":"LT8 qui reconnaît le fragment d'antigène associé au CMH I, activé, devenu LT cytotoxique, cytolyse de la cellule infectée","points":6},{"critere":"Anticorps sans accès à l'intérieur des cellules ; neutralisation des virus libres, opsonisation","points":4},{"critere":"LT4 : reconnaissance via CMH II, interleukines activant LB et LT8 ; le VIH détruit les LT4 et effondre les défenses","points":4}],"dureeMin":20,"corrige":"1. Une **augmentation des lymphocytes** oriente vers une **infection virale** (une augmentation des neutrophiles orienterait vers une infection bactérienne). La **CRP augmentée** signe une **inflammation** en cours (elle augmente en quelques heures).\n2. La présence d'**IgM spécifiques** du virus X signe une **infection récente** par ce virus ; des IgG seules auraient indiqué une infection ancienne ou une vaccination.\n3. C'est la **réponse à médiation cellulaire**. Le **LT8** spécifique reconnaît un **fragment d'antigène** viral associé au **CMH de classe I** à la surface de la cellule infectée. Activé grâce aux interleukines des LT4, il se multiplie et se différencie en **LT cytotoxique**, qui **détruit la cellule infectée** (**cytolyse**) : il libère des protéines qui **percent sa membrane** et déclenchent sa mort.\n4. Les anticorps agissent dans le plasma et les liquides : ils n'ont **pas accès à l'intérieur des cellules**, où le virus se multiplie. Ils gardent un rôle contre les **virus libres** : **neutralisation** (complexe immun), **opsonisation** (phagocytose facilitée), activation du complément.\n5. Le **LT4** reconnaît un fragment d'antigène présenté avec le **CMH II** par un macrophage ou une cellule dendritique, se multiplie et devient **LT auxiliaire** : ses **interleukines activent** à la fois les **lymphocytes B** (réponse humorale) et les **LT8** (réponse cellulaire). Sans LT4, **ni l'une ni l'autre** n'est efficace : c'est pourquoi le **VIH**, qui **détruit les LT4**, effondre les défenses."}$exo$::jsonb),
  ('187144dd-5550-51c0-9858-de1b06adec58'::uuid, 1, 'application', $exo${"titre":"Des gamètes à la cellule-œuf","consigne":"Réponds à chaque question par des phrases précises et des nombres justes.","enonce":"1. Combien de chromosomes possède une cellule du corps humain ? Et un gamète ? Nomme le mécanisme qui permet ce passage.\n2. Recopie les étapes de la spermatogenèse dans l'ordre, en indiquant pour chaque cellule si elle possède 2n ou n chromosomes : spermatide, spermatogonie, spermatozoïde, spermatocyte II, spermatocyte I.\n3. Où a lieu la fécondation ? Vers quel jour a lieu la nidation, et où ?","bareme":[{"critere":"Cellule diploïde 2n = 46, gamète haploïde n = 23, méiose","points":6},{"critere":"Ordre juste avec 2n/n : spermatogonie (2n), spermatocyte I (2n), spermatocyte II (n), spermatide (n), spermatozoïde (n)","points":8},{"critere":"Fécondation dans le tiers externe de la trompe (ampoule), nidation dans l'endomètre vers le 7e jour","points":6}],"dureeMin":7,"corrige":"1. Les cellules du corps sont **diploïdes** : **2n = 46** chromosomes. Les gamètes sont **haploïdes** : **n = 23**. C'est la **méiose** qui permet ce passage.\n2. **Spermatogonie (2n)** → **spermatocyte I (2n)** → **spermatocyte II (n)** → **spermatide (n)** → **spermatozoïde (n)**.\n3. La fécondation a lieu dans le **tiers externe de la trompe** (l'ampoule). La cellule-œuf se divise en migrant vers l'utérus, puis la **nidation** a lieu dans l'**endomètre** (muqueuse utérine), vers le **7e jour** après la fécondation."}$exo$::jsonb),
  ('187144dd-5550-51c0-9858-de1b06adec58'::uuid, 2, 'application', $exo${"titre":"La première consultation de Léa","consigne":"Réponds en t'appuyant sur les données du dossier et sur le cours ; justifie chaque conseil.","enonce":"**Situation.** Léa est enceinte. Le premier jour de ses dernières règles était le **1er mars**. Sa **sérologie de la toxoplasmose est négative**. Elle fume quelques cigarettes par jour et boit « juste un verre de vin le week-end ».\n\n1. En quelle unité les médecins datent-ils la grossesse ? À quelle date aura lieu sa première échographie, prévue à **12 SA** ?\n2. Cite trois intérêts de l'échographie pour le suivi de la grossesse et trois avantages de cette technique.\n3. Que signifie une sérologie négative à la toxoplasmose ? Quelles précautions Léa doit-elle prendre, et quel suivi est prévu ?\n4. Présente les échanges au niveau du placenta (dans les deux sens). Les sangs maternel et fœtal se mélangent-ils ?\n5. Que conseilles-tu à Léa pour l'alcool et le tabac ? Justifie.","bareme":[{"critere":"Semaines d'aménorrhée comptées depuis le 1er jour des dernières règles ; 12 SA = 84 jours, soit le 24 mai","points":4},{"critere":"Intérêts (datation, nombre d'embryons, croissance, morphologie) et avantages (sans rayonnement ionisant, non invasive, temps réel, peu coûteuse)","points":4},{"critere":"Sérologie négative = non immunisée : viande bien cuite, crudités lavées, pas de litière ; sérologie refaite chaque mois","points":4},{"critere":"Échanges justes dans les deux sens, sangs qui ne se mélangent pas","points":4},{"critere":"Zéro alcool (syndrome d'alcoolisation fœtale) et pas de tabac (petit poids, prématurité), passage à travers le placenta","points":4}],"dureeMin":12,"corrige":"1. En **semaines d'aménorrhée (SA)**, comptées depuis le **premier jour des dernières règles**. 12 SA = 12 × 7 = **84 jours** après le 1er mars : 30 jours jusqu'au 31 mars, 30 jusqu'au 30 avril, puis 24 jours : **le 24 mai**.\n2. Intérêts : **datation**, **nombre d'embryons**, **croissance**, **morphologie**, placenta. Avantages : **sans rayonnement ionisant**, **non invasive**, **en temps réel**, **peu coûteuse**.\n3. Aucun anticorps contre la toxoplasmose : Léa **n'est pas immunisée**. Précautions : **viande bien cuite**, **crudités bien lavées**, **pas de contact avec la litière du chat**. Sa sérologie sera **refaite chaque mois**.\n4. - Mère → fœtus : **dioxygène, glucose, acides aminés, eau, ions, anticorps (IgG)**.\n- Fœtus → mère : **dioxyde de carbone, urée** et autres déchets.\nLes deux sangs **ne se mélangent pas** : le sang fœtal circule dans les villosités baignées par le sang maternel.\n5. **Zéro alcool** : même un verre, car l'alcool **franchit le placenta** ; le **syndrome d'alcoolisation fœtale** est la première cause évitable de handicap mental de l'enfant. **Pas de tabac** : la nicotine et le monoxyde de carbone franchissent aussi le placenta, avec un risque de **petit poids** et de **prématurité**."}$exo$::jsonb),
  ('187144dd-5550-51c0-9858-de1b06adec58'::uuid, 3, 'application', $exo${"titre":"Le dépistage de la trisomie 21","consigne":"Analyse les documents, puis rédige des réponses argumentées qui pèsent les avantages et les risques de chaque examen.","enonce":"**Situation.** Mme Caron, 39 ans, est enceinte. L'échographie montre une clarté de la nuque augmentée ; associé aux marqueurs sanguins et à son âge, le calcul donne un risque élevé de trisomie 21. L'analyse de l'ADN fœtal dans son sang va dans le même sens. On lui propose une **amniocentèse**.\n\n**Document – Résultat du caryotype fœtal** : 47 chromosomes ; 22 paires d'autosomes, dont la paire 21 qui compte **trois** chromosomes ; deux chromosomes X.\n\n1. Explique la démarche de dépistage suivie avant l'amniocentèse. Pourquoi commence-t-on par ces examens ?\n2. Qu'est-ce qu'une amniocentèse et que permet-elle d'obtenir ? Le risque de fausse couche est de l'ordre de 0,5 à 1 % : sur 400 amniocentèses, combien de fausses couches cela représente-t-il ?\n3. Analyse le caryotype : quel est le diagnostic ? Quel est le sexe du fœtus ? Justifie.\n4. Sachant que la cellule-œuf provient de la fusion de deux gamètes, propose une explication chiffrée du nombre de chromosomes du fœtus.","bareme":[{"critere":"Dépistage en étapes : calcul d'un risque (nuque, marqueurs, âge) puis ADN fœtal, examens sans risque pour le fœtus","points":4},{"critere":"Amniocentèse : ponction de liquide amniotique pour établir le caryotype ; 2 à 4 fausses couches sur 400","points":5},{"critere":"Diagnostic : trisomie 21 (trois chromosomes 21, 47 au total) ; fille (XX)","points":5},{"critere":"Explication : un gamète normal à 23 + un gamète anormal à 24 portant deux chromosomes 21 = 47","points":4},{"critere":"Rédaction argumentée pesant bénéfice et risque","points":2}],"dureeMin":18,"corrige":"1. On commence par **calculer un risque** à partir de la **clarté de la nuque** à l'échographie, des **marqueurs sanguins** maternels et de l'**âge** ; si le risque est élevé, on analyse l'**ADN fœtal dans le sang maternel**. Ces examens sont **non invasifs** : ils ne font courir aucun risque au fœtus, alors que l'amniocentèse en comporte un. On réserve donc l'examen invasif aux grossesses à risque élevé.\n2. L'**amniocentèse** est une **ponction** (-centèse) de **liquide amniotique**, à partir de 15 SA, qui permet d'établir le **caryotype** du fœtus. Risque : 0,5 % de 400 = **2**, 1 % de 400 = **4** : environ **2 à 4 fausses couches sur 400** examens. C'est pourquoi on ne la propose que lorsque le risque de trisomie est élevé.\n3. Le caryotype compte **47 chromosomes** au lieu de 46, avec **trois chromosomes 21** : c'est une **trisomie 21**. Les gonosomes sont **XX** : le fœtus est une **fille**.\n4. Normalement, chaque gamète apporte **n = 23** chromosomes : 23 + 23 = 46. Ici, 47 = 23 + 24 : l'un des gamètes était **anormal** et portait **deux chromosomes 21** au lieu d'un ; associé au chromosome 21 de l'autre gamète, cela donne **trois chromosomes 21** dans la cellule-œuf, puis dans toutes les cellules du fœtus."}$exo$::jsonb),
  ('31ca182d-6662-5a01-9334-b6966de2a089'::uuid, 1, 'application', $exo${"titre":"Une régulation constante chez l'homme","consigne":"Réponds par des phrases précises ; tu peux compléter ta réponse 2 par un schéma fléché.","enonce":"1. Quelle hormone l'hypothalamus sécrète-t-il ? Comment ? Sur quelle glande agit-elle ?\n2. Décris l'axe hypothalamo-hypophyso-testiculaire : hormones sécrétées par l'hypophyse, action de chacune sur les testicules.\n3. Pourquoi le taux de testostérone reste-t-il à peu près constant ? Cite deux rôles de la testostérone.","bareme":[{"critere":"GnRH sécrétée de façon pulsatile, qui stimule l'antéhypophyse","points":5},{"critere":"LH → testostérone ; FSH et testostérone → spermatogenèse","points":7},{"critere":"Rétrocontrôle négatif de la testostérone sur hypothalamus et hypophyse ; deux rôles justes","points":8}],"dureeMin":7,"corrige":"1. L'hypothalamus sécrète la **GnRH**, **de façon pulsatile**, qui stimule l'**antéhypophyse**.\n2. L'antéhypophyse sécrète deux gonadostimulines : la **LH**, qui stimule la sécrétion de **testostérone** par les testicules (cellules de Leydig), et la **FSH**, qui, avec la testostérone, permet la **spermatogenèse**.\n3. La testostérone **freine l'hypothalamus et l'hypophyse** : c'est un **rétrocontrôle négatif**. Si elle augmente, GnRH et LH diminuent, donc la testostérone baisse, et inversement : son taux reste **à peu près constant**.\nRôles : développement des **organes génitaux** et des **caractères sexuels secondaires** (pilosité, voix, masse musculaire), maintien de la **spermatogenèse**, **libido**."}$exo$::jsonb),
  ('31ca182d-6662-5a01-9334-b6966de2a089'::uuid, 2, 'application', $exo${"titre":"Le cycle de Sarah","consigne":"Exploite le document : décris des valeurs précises, relie-les à l'ovaire et à l'utérus, puis explique le fonctionnement de la pilule.","enonce":"**Document – Taux d'hormones dans le sang au cours d'un cycle de 28 jours**\n\n| Jour | 2 | 8 | 12 | 13 | 20 | 27 |\n| Œstrogènes (pg/mL) | 40 | 100 | 300 | 250 | 180 | 50 |\n| LH (UI/L) | 5 | 6 | 15 | 60 | 5 | 3 |\n| Progestérone (ng/mL) | 0,5 | 0,5 | 0,8 | 1 | 15 | 1 |\n\n1. À quel moment a lieu l'ovulation ? Justifie à l'aide du document et explique ce qui la déclenche.\n2. Quelle structure de l'ovaire sécrète la progestérone entre J15 et J28 ? Quel est son effet sur l'utérus ?\n3. Que se passe-t-il vers J27-J28 en l'absence de fécondation ?\n4. Les deux rétrocontrôles du cycle : lequel s'exerce la plupart du temps, lequel juste avant l'ovulation ?\n5. Sarah prend une pilule œstroprogestative. Explique pourquoi elle n'ovule pas.","bareme":[{"critere":"Ovulation vers J13-J14 : pic de LH (60 UI/L à J13) déclenché par le pic d'œstrogènes (300 pg/mL à J12)","points":5},{"critere":"Corps jaune ; progestérone (15 ng/mL à J20) qui rend l'endomètre sécrétoire, prêt pour une nidation","points":4},{"critere":"Régression du corps jaune, chute des hormones, endomètre qui se détache : règles","points":4},{"critere":"Rétrocontrôle négatif la plupart du temps, positif juste avant l'ovulation","points":3},{"critere":"Pilule : hormones de synthèse, rétrocontrôle négatif, pas de pic de LH donc pas d'ovulation, glaire épaissie","points":4}],"dureeMin":12,"corrige":"1. L'ovulation a lieu **vers J13-J14**. Les œstrogènes montent de 40 (J2) à **300 pg/mL à J12** : ce **pic d'œstrogènes** déclenche un **pic de LH** (de 15 à **60 UI/L à J13**), qui provoque l'ovulation : le follicule mûr libère l'ovocyte II.\n2. Après l'ovulation, le follicule rompu devient le **corps jaune**, qui sécrète la **progestérone** (15 ng/mL à J20) et des œstrogènes. L'**endomètre devient sécrétoire**, prêt pour une nidation.\n3. Sans fécondation, le **corps jaune régresse** : progestérone et œstrogènes **chutent** (1 ng/mL et 50 pg/mL à J27). L'**endomètre se détache** : ce sont les nouvelles **règles**, début d'un nouveau cycle.\n4. **Négatif** la plupart du temps : les hormones ovariennes freinent FSH et LH. **Positif** juste avant l'ovulation : le pic d'œstrogènes déclenche le pic de LH.\n5. Les hormones de synthèse de la pilule exercent en permanence un **rétrocontrôle négatif** sur l'hypothalamus et l'hypophyse : **pas de pic de LH**, donc **pas d'ovulation** ; de plus, la glaire du col s'épaissit."}$exo$::jsonb),
  ('31ca182d-6662-5a01-9334-b6966de2a089'::uuid, 3, 'application', $exo${"titre":"Quatre couples au centre d'AMP","consigne":"Pour chaque couple, analyse la situation, puis propose et justifie une technique d'aide médicale à la procréation ou une autre conduite à tenir.","enonce":"**Situation.** Une gynécologue reçoit quatre couples.\n\n- **Couple A** : ils essaient d'avoir un enfant depuis **7 mois**, sans contraception.\n- **Couple B** : depuis 2 ans sans grossesse. Madame a eu une infection à chlamydia il y a quelques années ; l'examen montre des **trompes bouchées**. Le spermogramme de Monsieur est normal.\n- **Couple C** : depuis 18 mois sans grossesse. Le spermogramme de Monsieur montre **très peu de spermatozoïdes, peu mobiles**. Madame ovule normalement.\n- **Couple D** : depuis 3 ans sans grossesse. Le spermogramme de Monsieur montre une **azoospermie**.\n\n1. Définis l'infertilité. Le couple A est-il concerné ? Que lui conseilles-tu ?\n2. Couple B : quelle technique proposer ? Explique en quoi elle contourne le problème.\n3. Couple C : quelle technique proposer ? Décris-la.\n4. Couple D : traduis « azoospermie ». L'ICSI est-elle possible ? Quelle solution reste-t-il ?\n5. Le couple B aurait pu éviter son infertilité. Explique comment, en citant le seul moyen de contraception adapté.","bareme":[{"critere":"Infertilité après 12 mois de rapports réguliers sans contraception ; couple A pas encore concerné, patienter","points":4},{"critere":"Couple B : FIV, fécondation en laboratoire puis transfert d'embryon dans l'utérus, sans passer par les trompes","points":4},{"critere":"Couple C : ICSI, injection d'un spermatozoïde dans l'ovocyte, adaptée à une infertilité masculine sévère","points":4},{"critere":"Couple D : absence de spermatozoïdes, ICSI impossible, don de gamètes (sperme)","points":4},{"critere":"Prévention : préservatifs, seuls à protéger des IST comme la chlamydia","points":4}],"dureeMin":18,"corrige":"1. On parle d'**infertilité** après **douze mois** de rapports réguliers **sans contraception** et sans grossesse. Le couple A n'essaie que depuis 7 mois : il **n'est pas encore concerné**. Conseil : continuer et reconsulter si aucune grossesse ne survient au bout d'un an.\n2. Couple B : **fécondation in vitro (FIV)**. Les trompes bouchées empêchent la rencontre des gamètes. En FIV, les ovocytes sont prélevés, la **fécondation a lieu en laboratoire**, puis l'**embryon est transféré dans l'utérus** : les trompes ne sont plus nécessaires.\n3. Couple C : **ICSI** : on **injecte un spermatozoïde directement dans l'ovocyte**, puis l'embryon est transféré. Elle convient à une **infertilité masculine sévère** : un seul spermatozoïde suffit, même peu mobile.\n4. **Azoospermie** : **absence de spermatozoïdes** dans le sperme (a- : absence). L'ICSI est **impossible**, puisqu'il n'y a aucun spermatozoïde à injecter. Il reste le **don de gamètes** (don de sperme), par exemple avec une insémination artificielle.\n5. Les trompes de Madame se sont bouchées **après une infection à chlamydia**, une infection sexuellement transmissible. Les **préservatifs** (externe ou interne) sont les **seuls moyens de contraception qui protègent des IST** : leur usage aurait pu éviter l'infection, donc cette infertilité."}$exo$::jsonb),
  ('f8ec801c-6bcc-5030-b966-81971defa07c'::uuid, 1, 'application', $exo${"titre":"Du brin d'ADN à la protéine","consigne":"Réponds à chaque question en montrant chaque étape de ta réponse.","enonce":"**Situation.** On étudie le début d'un gène. Voici la séquence du **brin d'ADN transcrit** :\n\n> TAC GGA TTT ATT\n\n**Extrait du code génétique** : AUG = méthionine (début) ; CCU = proline ; AAA = lysine ; UAA = stop.\n\n1. Écris la séquence du brin d'ADN complémentaire, en rappelant la règle d'appariement.\n2. Où a lieu la transcription ? Écris l'ARN messager obtenu.\n3. Où a lieu la traduction ? Traduis cet ARNm en séquence d'acides aminés. Que se passe-t-il au quatrième codon ?","bareme":[{"critere":"Complémentarité A-T, G-C : brin complémentaire ATG CCT AAA TAA","points":5},{"critere":"Transcription dans le noyau, ARNm AUG CCU AAA UAA (U à la place de T)","points":7},{"critere":"Traduction dans le cytoplasme sur les ribosomes : méthionine – proline – lysine, puis codon stop qui arrête la traduction","points":8}],"dureeMin":7,"corrige":"1. Les bases sont **complémentaires** : A face à T, G face à C. Brin complémentaire : **ATG CCT AAA TAA**.\n2. La transcription a lieu dans le **noyau** : le brin transcrit est copié en ARN messager, avec l'**uracile (U)** à la place de la thymine. ARNm : **AUG CCU AAA UAA**.\n3. La traduction a lieu dans le **cytoplasme**, sur les **ribosomes** : l'ARNm est lu trois bases par trois bases (codons).\nAUG → **méthionine** ; CCU → **proline** ; AAA → **lysine** ; UAA → **codon stop** : il ne code aucun acide aminé et **arrête la traduction**.\nSéquence obtenue : **méthionine – proline – lysine**."}$exo$::jsonb),
  ('f8ec801c-6bcc-5030-b966-81971defa07c'::uuid, 2, 'application', $exo${"titre":"Quatre mutations sur le même gène","consigne":"Pour chaque allèle, écris l'ARNm, traduis-le avec l'extrait du code, puis nomme le type de mutation et son effet.","enonce":"**Document 1 – Brin transcrit de l'allèle normal et de quatre allèles mutés (début du gène)**\n\n| L'allèle | Le brin transcrit |\n| Normal | TAC CTC TTT |\n| Muté 1 | TAC CAC TTT |\n| Muté 2 | TAC CTT TTT |\n| Muté 3 | TAC ATC TTT |\n| Muté 4 | TAC TCT TT… (le C en 4e position a disparu) |\n\n**Document 2 – Extrait du code génétique** : AUG = méthionine ; GAG et GAA = acide glutamique ; GUG = valine ; AAA = lysine ; AGA = arginine ; UAG = stop.\n\n1. Écris l'ARNm et la séquence d'acides aminés de l'allèle normal.\n2. Fais de même pour les allèles mutés 1, 2 et 3, puis nomme le type de mutation et son effet sur la protéine.\n3. Allèle muté 4 : nomme la mutation et explique pourquoi ses conséquences sont en général plus graves.","bareme":[{"critere":"Allèle normal : AUG GAG AAA, méthionine – acide glutamique – lysine","points":4},{"critere":"Muté 1 : GUG, valine à la place de l'acide glutamique (substitution, un acide aminé changé)","points":4},{"critere":"Muté 2 : GAA, même acide aminé (substitution sans effet, codon synonyme)","points":4},{"critere":"Muté 3 : UAG stop prématuré, protéine raccourcie","points":4},{"critere":"Muté 4 : délétion d'une base, décalage de la lecture, tous les codons suivants changent (AUG AGA …)","points":4}],"dureeMin":12,"corrige":"1. Allèle normal : ARNm **AUG GAG AAA** → **méthionine – acide glutamique – lysine**.\n2. - **Muté 1** : ARNm AUG **GUG** AAA → méthionine – **valine** – lysine. **Substitution** d'une base : **un acide aminé est changé** (c'est le même changement que dans la drépanocytose).\n- **Muté 2** : ARNm AUG **GAA** AAA → méthionine – acide glutamique – lysine. **Substitution** sans effet : GAA et GAG codent le **même acide aminé** (codon synonyme) ; la protéine est inchangée.\n- **Muté 3** : ARNm AUG **UAG** … → méthionine puis **stop**. **Substitution** qui crée un **codon stop prématuré** : la protéine est **raccourcie**.\n3. **Muté 4** : **délétion** d'une base. Le brin transcrit devient TAC TCT TT…, l'ARNm AUG **AGA** AA… : méthionine – **arginine** – … La lecture se fait trois bases par trois bases : la délétion **décale la lecture**, et **tous les codons suivants changent**. Toute la suite de la protéine est modifiée (et un codon stop peut apparaître plus loin), alors qu'une substitution ne touche qu'un codon : l'effet est en général bien plus grave."}$exo$::jsonb),
  ('f8ec801c-6bcc-5030-b966-81971defa07c'::uuid, 3, 'application', $exo${"titre":"La drépanocytose dans la famille Diallo","consigne":"Analyse l'arbre généalogique, raisonne étape par étape et justifie chaque conclusion ; construis l'échiquier de croisement demandé.","enonce":"**Document 1 – La famille Diallo** : les parents, Aminata et Ousmane, sont **sains**. Ils ont trois enfants : **Fatou**, une fille **malade** ; **Ibrahim**, un garçon **sain** ; **Moussa**, un garçon **malade**. Le couple attend un quatrième enfant.\n\n**Document 2 – La maladie** : dans la drépanocytose, une substitution A → T dans le gène de la bêta-globine change un seul acide aminé de la protéine (acide glutamique → valine). L'hémoglobine anormale déforme les globules rouges en faucille.\n\nOn note N l'allèle normal et d l'allèle de la maladie.\n\n1. L'allèle d est-il dominant ou récessif ? Justifie à partir de l'arbre.\n2. Le gène est-il porté par un autosome ou par le chromosome X ? Justifie.\n3. Donne le génotype des parents et celui de Fatou. Justifie.\n4. Construis l'échiquier de croisement des deux parents et donne le risque que le quatrième enfant soit malade. Aminata pense que ce risque est plus faible « puisqu'on a déjà eu deux enfants malades » : a-t-elle raison ?\n5. Explique comment une mutation d'une seule base aboutit aux globules rouges en faucille (du gène au phénotype).","bareme":[{"critere":"Récessif : parents sains ayant des enfants malades","points":3},{"critere":"Autosome : maladie qui touche fille et garçon, pas surtout des garçons","points":3},{"critere":"Parents N//d (hétérozygotes, porteurs sains), Fatou d//d, justifiés","points":4},{"critere":"Échiquier juste : 1/4 malade, 1/2 porteur sain, 1/4 sain non porteur ; risque identique à chaque grossesse","points":6},{"critere":"Du gène au phénotype : substitution, codon modifié, un acide aminé changé, hémoglobine anormale, hématies en faucille","points":4}],"dureeMin":20,"corrige":"1. Aminata et Ousmane sont **sains** mais ont des enfants **malades** : l'allèle de la maladie était présent chez eux sans s'exprimer. L'allèle d est **récessif**.\n2. La maladie touche **une fille** (Fatou) **et un garçon** (Moussa) : elle ne touche pas presque seulement des garçons. Le gène est porté par un **autosome** (la drépanocytose est autosomique récessive).\n3. Fatou est malade et l'allèle est récessif : elle est **homozygote d//d**. Elle a reçu un allèle d de chaque parent ; or les parents sont sains, ils portent donc aussi un allèle N : ils sont **hétérozygotes N//d** (porteurs sains).\n4. | | N | d |\n| **N** | N//N (sain) | N//d (sain, porteur) |\n| **d** | N//d (sain, porteur) | d//d (**malade**) |\nRisque pour chaque enfant : **1/4 malade**, 1/2 porteur sain, 1/4 sain non porteur. Aminata a **tort** : ce risque est **le même à chaque grossesse** (1/4), quel que soit l'état des enfants précédents.\n5. La **substitution** d'une base (A → T) dans le gène modifie un **codon** de l'ARNm ; à la traduction, **un seul acide aminé** de la bêta-globine est changé (acide glutamique → **valine**). L'**hémoglobine** obtenue est **anormale** : elle **déforme les globules rouges en faucille**. Chez l'homozygote d//d, toute l'hémoglobine est anormale : c'est le **phénotype** malade."}$exo$::jsonb),
  ('5b732eb5-bc03-52cd-b111-02db1c4d0249'::uuid, 1, 'application', $exo${"titre":"Bénigne ou maligne ?","consigne":"Réponds à chaque question par des phrases précises.","enonce":"**Situation.** On a retiré à M. Perrin une tumeur de la peau. Le compte rendu indique : « tumeur bien limitée, entourée d'une capsule, à croissance lente, formée de cellules proches des cellules normales ».\n\n1. Cette tumeur est-elle bénigne ou maligne ? Justifie par trois critères.\n2. Qu'est-ce qu'une métastase ? Quelle sorte de tumeur peut en donner ?\n3. Pourquoi le risque de cancer augmente-t-il avec l'âge ?","bareme":[{"critere":"Tumeur bénigne, justifiée par trois critères (limites nettes, capsule, croissance lente, cellules proches des normales)","points":8},{"critere":"Métastase = tumeur secondaire à distance, formée par des cellules passées dans le sang ou la lymphe ; seulement les tumeurs malignes","points":7},{"critere":"Il faut en général accumuler plusieurs mutations","points":5}],"dureeMin":7,"corrige":"1. C'est une tumeur **bénigne** : ses **limites sont nettes**, elle est **entourée d'une capsule**, sa **croissance est lente** et ses **cellules sont proches des cellules normales**. Une tumeur maligne serait mal limitée, envahirait les tissus voisins, avec des cellules anormales.\n2. Une **métastase** est une **tumeur secondaire**, **à distance** de la tumeur primitive : des cellules cancéreuses envahissent les tissus voisins, passent dans le **sang** ou la **lymphe**, et forment ailleurs de nouvelles tumeurs. Seules les tumeurs **malignes** peuvent en donner ; une tumeur bénigne jamais.\n3. Un cancer résulte en général de l'**accumulation de plusieurs mutations** dans une même cellule (gènes qui accélèrent la division devenus trop actifs, gènes qui la freinent ou réparent l'ADN devenus inactifs). Il faut du temps pour les accumuler : le risque **augmente avec l'âge**."}$exo$::jsonb),
  ('5b732eb5-bc03-52cd-b111-02db1c4d0249'::uuid, 2, 'application', $exo${"titre":"Les risques de la famille Lambert","consigne":"Classe les facteurs de risque, puis argumente sur la prévention en t'appuyant sur le cours.","enonce":"**Situation.** M. Lambert, 52 ans, fume un paquet par jour depuis l'âge de 16 ans. Pendant dix ans, il a travaillé au désamiantage de bâtiments. Il passe ses étés au soleil sans protection. Sa fille Clara, 11 ans, n'a reçu aucun vaccin contre les papillomavirus. Sa sœur a appris qu'elle porte une mutation du gène BRCA1.\n\n1. Classe les facteurs de risque de cancer présents dans cette famille selon les quatre catégories du cours (comportements, environnement, infections, génétique).\n2. Distingue un agent mutagène et un agent cancérogène.\n3. Quelle part des cancers est attribuable à des facteurs évitables ? Propose, pour cette famille, trois mesures de prévention précises et justifiées.","bareme":[{"critere":"Classement juste : tabac et soleil sans protection (comportements), amiante et UV (environnement), papillomavirus (infections), BRCA1 (génétique)","points":8},{"critere":"Mutagène : provoque des mutations ; cancérogène : favorise le cancer","points":4},{"critere":"Environ 40 % évitables ; trois mesures justifiées (arrêt du tabac, protection solaire, vaccination de Clara contre les papillomavirus)","points":8}],"dureeMin":12,"corrige":"1. - **Comportements** : le **tabac** (première cause de cancer évitable) ; l'exposition au soleil **sans protection**.\n- **Environnement** : l'**amiante** (exposition professionnelle au désamiantage) ; les **ultraviolets**.\n- **Infections** : les **papillomavirus**, responsables des cancers du col de l'utérus, contre lesquels Clara n'est pas vaccinée.\n- **Génétique** : la mutation du gène **BRCA1** de sa sœur, prédisposition héréditaire rare au cancer du sein et de l'ovaire.\n2. Un agent **mutagène** provoque des **mutations** de l'ADN ; un agent **cancérogène** **favorise le cancer**.\n3. Environ **40 %** des cancers sont attribuables à des facteurs **évitables**. Mesures :\n- **arrêter le tabac** : c'est la première cause évitable, et chaque année d'exposition en moins réduit l'accumulation de mutations ;\n- **se protéger du soleil** (vêtements, crème, heures chaudes évitées) : moins d'UV mutagènes ;\n- **vacciner Clara contre les papillomavirus** : prévient les infections à l'origine de la plupart des cancers du col de l'utérus.\n(Accepté aussi : limiter l'alcool, activité physique, alimentation équilibrée.)"}$exo$::jsonb),
  ('5b732eb5-bc03-52cd-b111-02db1c4d0249'::uuid, 3, 'application', $exo${"titre":"Le parcours de Mme Girard","consigne":"Analyse le parcours de soins étape par étape, relie chaque effet secondaire au mécanisme du traitement, et utilise le vocabulaire médical.","enonce":"**Situation.** Mme Girard, 56 ans, reçoit un courrier du dépistage organisé et passe une mammographie. Une anomalie est vue dans le sein gauche. Une échographie puis une **biopsie** sont réalisées ; le compte rendu anatomopathologique conclut à un cancer. Un scanner et une scintigraphie osseuse ne montrent aucune métastase. Elle est opérée (**tumorectomie**), puis reçoit une **chimiothérapie** et une **radiothérapie**.\n\n**Bilan pendant la chimiothérapie** : leucocytes **2 500 par mm³** (valeurs de référence : 4 000 à 10 000). Elle a perdu ses cheveux et a des aphtes.\n\n1. Mme Girard est-elle dans la population du dépistage organisé ? Précise le principe de ce dépistage.\n2. Quel examen affirme le diagnostic ? Pourquoi une imagerie ne suffit-elle pas ?\n3. Quel est le but du scanner et de la scintigraphie ? Traduis « tumorectomie » et « mastectomie ».\n4. Nomme l'anomalie de son bilan sanguin et explique-la, ainsi que la perte des cheveux et les aphtes, par le mécanisme de la chimiothérapie. Quel risque la leucopénie lui fait-elle courir ?\n5. Explique le principe de la radiothérapie. Pendant le suivi, son marqueur tumoral est normal : peut-on affirmer qu'elle est guérie ?","bareme":[{"critere":"Dépistage organisé de 50 à 74 ans, mammographie tous les deux ans","points":3},{"critere":"Examen anatomopathologique de la biopsie, seul à affirmer le cancer","points":3},{"critere":"Bilan d'extension (recherche de métastases) ; tumorectomie = ablation de la tumeur, mastectomie = ablation du sein","points":4},{"critere":"Leucopénie (2 500 < 4 000) ; chimiothérapie qui touche toutes les cellules à division rapide : alopécie, aphtes, risque d'infection","points":6},{"critere":"Radiothérapie : rayonnements ionisants concentrés qui lèsent l'ADN ; marqueur normal n'exclut pas un cancer","points":4}],"dureeMin":20,"corrige":"1. Oui : le **dépistage organisé** du cancer du sein concerne les femmes de **50 à 74 ans** ; il repose sur une **mammographie tous les deux ans**. Détecté tôt, ce cancer guérit dans une grande majorité des cas.\n2. Seul l'**examen anatomopathologique** du tissu prélevé par **biopsie**, observé au microscope, **affirme le cancer**. L'imagerie (mammographie, échographie) montre une anomalie mais ne permet pas de savoir si les cellules sont cancéreuses.\n3. Le scanner et la scintigraphie osseuse constituent le **bilan d'extension** : on **cherche des métastases** (ici aucune). **Tumorectomie** : ablation chirurgicale (-ectomie) de la **tumeur** ; **mastectomie** : ablation du **sein**.\n4. 2 500 < 4 000 par mm³ : c'est une **leucopénie** (baisse des globules blancs, -pénie : diminution). La chimiothérapie **bloque la division des cellules** : elle frappe les cellules cancéreuses mais aussi **toutes les cellules saines qui se divisent vite** : cellules produisant les globules blancs (leucopénie), follicules pileux (**chute des cheveux**, alopécie), muqueuse de la bouche (**aphtes**). La leucopénie l'expose à un **risque d'infection**.\n5. La **radiothérapie** utilise des **rayonnements ionisants concentrés sur la zone tumorale** : ils **lèsent l'ADN** des cellules cancéreuses. Non : un **marqueur tumoral normal n'exclut pas un cancer** ; les marqueurs servent au **suivi**, et seul l'examen anatomopathologique fait le diagnostic. La surveillance continue (examens cliniques, imagerie)."}$exo$::jsonb),
  ('a727c1eb-c7d2-571a-ae72-2be239d226de'::uuid, 1, 'application', $exo${"titre":"Décoder le vocabulaire médical","consigne":"Découpe chaque terme en préfixe, racine et suffixe, puis donne son sens. Réponds ensuite aux questions de méthode.","enonce":"**Données** : cardi- = cœur ; gastr- = estomac ; hém- = sang ; splén- = rate ; leuc- = blanc (globules blancs) ; glyc- = glucose.\n\n1. Découpe et définis : **bradycardie**, **gastrite**, **hyperglycémie**, **leucopénie**, **splénomégalie**, **hémorragie**, **anurie**.\n2. Qu'est-ce qu'un **signe clinique** ? un **signe paraclinique** ? Donne un exemple de chaque.\n3. Que désigne l'**étiologie** d'une maladie ?","bareme":[{"critere":"Sept termes justement découpés et définis","points":12},{"critere":"Signe clinique et paraclinique définis, avec un exemple juste de chaque","points":6},{"critere":"Étiologie = cause de la maladie","points":2}],"dureeMin":8,"corrige":"1. - **Brady-cardie** : cœur lent.\n- **Gastr-ite** : inflammation de l'estomac.\n- **Hyper-glyc-émie** : excès de glucose dans le sang.\n- **Leuco-pénie** : diminution des globules blancs.\n- **Spléno-mégalie** : augmentation de volume de la rate.\n- **Hémo-rragie** : écoulement de sang.\n- **An-urie** : absence d'urine.\n2. Un **signe clinique** est ce que le patient **ressent** ou ce que le médecin **constate à l'examen** (soif, fatigue, fièvre). Un **signe paraclinique** est un **résultat d'examen complémentaire** : analyse, imagerie (une glycémie à 2,3 g/L, une radiographie).\n3. L'**étiologie** est la **cause** de la maladie."}$exo$::jsonb),
  ('a727c1eb-c7d2-571a-ae72-2be239d226de'::uuid, 2, 'application', $exo${"titre":"Corriger la copie de Nathan","consigne":"Repère les erreurs de méthode de Nathan, explique-les, puis rédige la réponse attendue.","enonce":"**Exercice 1 (chimie).** « Calculer la quantité de matière de gaz contenue dans un flacon de 500 mL, à la pression de 2,0 × 10⁵ Pa et à 27 °C. Donnée : R = 8,314 J/(mol·K). »\n\n> Copie de Nathan : n = 2,0 × 10⁵ × 500 ÷ (8,314 × 27) = 445 478\n\n**Exercice 2 (biologie).** « Exploiter le document pour expliquer l'évolution de la glycémie de Mme Vidal après un repas. »\n\n> Document : glycémie 0,9 g/L à jeun, 1,6 g/L une heure après le repas, 1,0 g/L deux heures après.\n> Donnée : après un repas, le glucose absorbé par l'intestin passe dans le sang ; l'insuline fait ensuite entrer le glucose dans les cellules.\n\n> Copie de Nathan : « La courbe monte puis descend. »\n\n1. Relève les erreurs de méthode de l'exercice 1 et refais le calcul correctement.\n2. Pourquoi la réponse de l'exercice 2 est-elle insuffisante ? Rédige la réponse attendue en suivant les étapes d'exploitation d'un document.","bareme":[{"critere":"Erreurs relevées : formule littérale absente, mL et °C non convertis, pas d'unité, ordre de grandeur non commenté","points":6},{"critere":"Calcul juste : V = 5,00 × 10⁻⁴ m³, T = 300 K, n ≈ 4,0 × 10⁻² mol","points":5},{"critere":"Exercice 2 : décrire n'est pas interpréter, valeurs absentes","points":3},{"critere":"Réponse rédigée : description chiffrée, interprétation par l'absorption du glucose puis l'insuline, conclusion","points":6}],"dureeMin":12,"corrige":"1. Erreurs de Nathan :\n- il n'a **pas écrit la formule littérale** (P × V = n × R × T, donc n = P × V ÷ (R × T)) ;\n- il n'a **pas converti les unités** : V doit être en **m³** (500 mL = 5,00 × 10⁻⁴ m³) et T en **kelvins** (27 + 273 = 300 K) ;\n- son résultat n'a **pas d'unité** et trop de chiffres ;\n- il n'a **pas commenté l'ordre de grandeur** : 445 478 mol dans un flacon de 500 mL est absurde.\nCalcul correct : n = P × V ÷ (R × T) = 2,0 × 10⁵ × 5,00 × 10⁻⁴ ÷ (8,314 × 300) = 100 ÷ 2 494 ≈ **4,0 × 10⁻² mol**, un ordre de grandeur plausible pour un petit flacon.\n2. « La courbe monte puis descend » **décrit** sans valeurs et **n'interprète pas** : il faut dire **pourquoi**.\nRéponse attendue : **Présentation** : le document donne la glycémie de Mme Vidal à jeun puis une et deux heures après un repas. **Description** : elle passe de **0,9 g/L** à jeun à **1,6 g/L** une heure après le repas, puis revient à **1,0 g/L** au bout de deux heures. **Comparaison** : elle retrouve presque sa valeur de départ. **Interprétation** : la hausse s'explique par le **glucose absorbé par l'intestin** qui passe dans le sang ; la baisse, par l'**insuline**, qui fait entrer le glucose dans les cellules. **Conclusion** : la glycémie de Mme Vidal s'élève après le repas puis est ramenée vers sa valeur initiale en deux heures."}$exo$::jsonb),
  ('a727c1eb-c7d2-571a-ae72-2be239d226de'::uuid, 3, 'application', $exo${"titre":"Mettre en ordre un cas clinique","consigne":"Applique la démarche attendue à l'épreuve : relève et classe les signes, compare-les aux références, nomme les anomalies, puis rédige une explication structurée qui relie signes et mécanisme.","enonce":"**Document 1 – Le cas.** Mme Laurent, 68 ans, consulte pour une **fatigue intense** depuis un mois, un **essoufflement** à l'effort, une **pâleur** et de petits **saignements des gencives**. Elle a eu deux infections ces dernières semaines.\n\n**Document 2 – Numération sanguine**\n\n| Les cellules | Le résultat | La référence |\n| Hématies | 3,1 millions par mm³ | 4 à 5,5 millions par mm³ |\n| Leucocytes | 2 600 par mm³ | 4 000 à 10 000 par mm³ |\n| Plaquettes | 70 000 par mm³ | 150 000 à 400 000 par mm³ |\n\n**Document 3 – L'explication du médecin** : « La moelle osseuse rouge de Mme Laurent produit moins de cellules sanguines. Le manque d'hématies réduit le transport du dioxygène ; le manque de leucocytes affaiblit les défenses ; le manque de plaquettes gêne l'arrêt des saignements. »\n\n**Données** : thrombo- = plaquette ; érythro- = rouge (globules rouges).\n\n1. Classe les signes du document 1 et du document 2 en signes cliniques et paracliniques.\n2. Compare chaque résultat à sa référence et nomme les trois anomalies avec le vocabulaire médical.\n3. Traduis le terme médical de la fatigue intense.\n4. Rédige un paragraphe structuré qui relie chaque signe clinique à une anomalie paraclinique, en t'appuyant sur le document 3.\n5. Donne deux conseils de méthode pour réussir ce type de question le jour de l'épreuve.","bareme":[{"critere":"Classement juste : cliniques (fatigue, essoufflement, pâleur, saignements, infections) et paracliniques (trois numérations)","points":4},{"critere":"Comparaison chiffrée et termes : érythropénie, leucopénie, thrombopénie","points":5},{"critere":"Asthénie","points":2},{"critere":"Paragraphe reliant fatigue, essoufflement et pâleur aux hématies, infections aux leucocytes, saignements aux plaquettes, avec l'origine médullaire","points":6},{"critere":"Deux conseils de méthode justes (lire tout le sujet, citer les valeurs, décrire puis interpréter, relire)","points":3}],"dureeMin":20,"corrige":"1. **Signes cliniques** : fatigue intense, essoufflement à l'effort, pâleur, saignements des gencives, infections répétées. **Signes paracliniques** : les trois résultats de la numération sanguine.\n2. - Hématies : 3,1 millions < 4 millions par mm³ : diminution, **érythropénie** (manque de globules rouges).\n- Leucocytes : 2 600 < 4 000 par mm³ : **leucopénie**.\n- Plaquettes : 70 000 < 150 000 par mm³ : **thrombopénie**.\n(-pénie : diminution.)\n3. **Asthénie**.\n4. Exemple : « Mme Laurent présente une baisse des trois lignées de cellules sanguines, car sa **moelle osseuse rouge** en produit moins. Le manque d'**hématies** (3,1 millions par mm³) réduit le **transport du dioxygène** vers les organes : cela explique sa **fatigue**, son **essoufflement** à l'effort et sa **pâleur**. La **leucopénie** (2 600 par mm³) **affaiblit ses défenses** : elle explique ses **infections répétées**. La **thrombopénie** (70 000 par mm³) **gêne l'arrêt des saignements** : elle explique les **saignements des gencives**. Tous les signes cliniques s'expliquent donc par un même mécanisme. »\n5. Conseils : **lire tout le sujet** avant de commencer (un document plus loin peut aider) ; **citer des valeurs précises** et les **comparer à la référence** ; **décrire puis interpréter** (dire pourquoi) ; garder **dix minutes pour relire** (orthographe des termes médicaux, réponses oubliées)."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
